insert into public.bible_verses (translation_id, book_id, chapter, verse, text)
values
('kam', 'MAT', 24, 43, 'Ĩndĩ manyai ũndũ ũũ, kana kethĩwa mwene wa nyũmba nĩwesĩ ĩvinda yĩla kĩng’ei kĩkoka, ethĩwa asyaĩĩsye, o na ndaĩ aeka nyũmba yake ĩtũlwe.'),
('kam', 'MAT', 24, 44, 'Kwondũ wa ũu nenyu ĩkalai mwĩyũmbanĩtye; nũndũ saa ũla mũtataĩĩe nĩw’o wĩũka ũla Mwana wa mũndũ.'),
('kam', 'MAT', 24, 45, 'Nũũ ĩndĩ ngombo yĩ na kĩthito na mbũĩ, ĩla vwana wayo wamĩtwie mũnene ĩũlũ wa nyũmba yake, nĩ kana ĩmanenge ala angĩ lĩu ĩvinda yaw’o?'),
('kam', 'MAT', 24, 46, 'Nĩ ngathime ngombo ĩsu, ĩla vwana wayo ooka wĩmĩthĩa ĩkĩka ũu.'),
('kam', 'MAT', 24, 47, 'Nĩ w’o nĩngũmwĩa, akamĩtw’a mũnene ĩũlũ wa syonthe ila wĩ nasyo.'),
('kam', 'MAT', 24, 48, 'Ĩndĩ ethĩwa ngombo ĩla nthũku ĩkasya ngoonĩ yayo, Vwana wakwa nĩwĩkalĩte;'),
('kam', 'MAT', 24, 49, 'na ĩkyambĩlĩlya kũmakũna athũkũmi ala angĩ, na kũya na kũnyw’a vamwe na athengi;'),
('kam', 'MAT', 24, 50, 'vwana wa ngombo ĩsu akooka mũthenya ũla ĩtatalĩthye, na saa ũla ĩtawĩsĩ,'),
('kam', 'MAT', 24, 51, 'na akamĩvũa mũno, na kũmĩnenga kĩanda kyayo vamwe na angangan’ya: vo vakethĩwa kĩĩo na kũvevetan’ya maeo.'),
('kam', 'MAT', 25, 1, 'Na ĩndĩ ũsumbĩ wa ĩtu ũkethĩwa ũilyĩ ta eĩtu ĩkũmi, ala moosie mataa moo, na maumaala mathi kũmũthaũa mũtwaani.'),
('kam', 'MAT', 25, 2, 'Na atano moo maĩ atumanu, na atano maĩ oĩ.'),
('kam', 'MAT', 25, 3, 'Nũndũ ala atumanu, yĩla moosie mataa moo, matyaakua mauta vamwe nao:'),
('kam', 'MAT', 25, 4, 'ĩndĩ ala oĩ nĩmakuie mauta mĩionĩ yoo vamwe na mataa moo.'),
('kam', 'MAT', 25, 5, 'Ĩndĩ mũtwaani ekalanga, onthe mombosya na makoma.'),
('kam', 'MAT', 25, 6, 'Ĩndĩ ũtukũ katĩ kwaĩ wasya mũnene, Sisyai, mũtwaani nĩwũkĩte! Umaalai mũmũthaũe.'),
('kam', 'MAT', 25, 7, 'Na ĩndĩ eĩtu asu onthe mookĩla, maseũvya mataa moo.'),
('kam', 'MAT', 25, 8, 'Na ala atumanu mamea ala oĩ, Tũnengei mauta amwe menyu; nũndũ mataa maitũ nĩmeũvoa.'),
('kam', 'MAT', 25, 9, 'Ĩndĩ ala oĩ masũngĩa, makyasya, Aiee, no kwĩthĩwa matetwĩanĩa ithyĩ nenyu: kavaa mũthi kwa ala mathooasya, mũkethooee ene.'),
('kam', 'MAT', 25, 10, 'Nao maendete kũthooa, mũtwaani ooka; na ala meyũmbanĩtye mavota vamwe nake mbokanĩ ya mũtwaano: na mũomo wavingwa.'),
('kam', 'MAT', 25, 11, 'Ĩtina eĩtu ala angĩ mooka, makyasya, Mwĩaĩi, Mwĩaĩi, tũvingũĩe.'),
('kam', 'MAT', 25, 12, 'Ĩndĩ asũngĩa, asya, Nĩ w’o nĩngũmwĩa, ndimwĩsĩ inyw’ĩ.'),
('kam', 'MAT', 25, 13, 'Syaĩĩsyai ĩndĩ, nũndũ mũtyĩsĩ mũthenya kana saa.'),
('kam', 'MAT', 25, 14, 'Nũndũ nĩ ta mũndũ akĩthi kyalo nthĩ ĩngĩ, ũla wetie ngombo syake mwene, na ainenga ũthwii wake.'),
('kam', 'MAT', 25, 15, 'Anenga ĩmwe mbesa sya talendi itano, na ĩngĩ sya talendi ilĩ, na ĩngĩ sya talendi ĩmwe; kĩla ĩmwe kwĩanana na ũtonyi wayo; na athi kyalo.'),
('kam', 'MAT', 25, 16, 'Oyu ĩla yosie talendi itano yathi yatethya wĩa nasyo, na yatandĩthya talendi ingĩ itano.'),
('kam', 'MAT', 25, 17, 'No ta ũu ĩla yosie ilĩ nayo yatandĩthya ingĩ ilĩ.'),
('kam', 'MAT', 25, 18, 'Ĩndĩ ĩla yosie ĩmwe yathi yenza nthĩ, yavitha mbesa sya vwana wayo.'),
('kam', 'MAT', 25, 19, 'Na ĩndĩ ĩtina wa ĩvinda ĩasa vwana wa ngombo isu ooka, na atalana nasyo.'),
('kam', 'MAT', 25, 20, 'Na ĩla yosie talendi itano yooka na yaetanĩsye na talendi ingĩ itano, ĩkyasya, Vwana, nĩwanengie talendi itano: sisya, nĩnĩtandĩthĩtye talendi ingĩ itano'),
('kam', 'MAT', 25, 21, 'Vwana wayo amĩtavya, Nĩwĩkĩte nesa, ngombo nzeo na ĩla yĩ na kĩthito: waĩ na kĩthito ĩũlũ wa syĩndũ mbũthũ, ngakwia ĩũlũ wa syĩndũ nyingĩ; lika ũtanunĩ wa vwana waku.'),
('kam', 'MAT', 25, 22, 'Na ĩla yosie talendi ilĩ yooka na yasya, Vwana, nĩwanengie talendi ilĩ: sisya, nĩnĩtandĩthĩtye talendi ingĩ ilĩ.'),
('kam', 'MAT', 25, 23, 'Vwana wayo amĩtavya, Nĩwĩkĩte nesa ngombo nzeo na ĩla yĩ na kĩthito: waĩ na kĩthito ĩũlũ wa syĩndũ mbũthũ, ngakwia ĩũlũ wa syĩndũ mbingĩ; lika ũtanunĩ wa vwana waku.'),
('kam', 'MAT', 25, 24, 'Na ĩla yosie talendi ĩmwe yooka na yasya, Vwana, nĩnakũmanyie kana wĩ mũndũ mũmũ, ũkethaa vala ũtaavuĩa, na wũmbanasya vala ũtaanyaĩĩkya;'),
('kam', 'MAT', 25, 25, 'nakwa nakĩa, nathi navitha talendi yaku nthĩ; sisya, wĩ na kĩla kyaku.'),
('kam', 'MAT', 25, 26, 'Ĩndĩ vwana wayo asũngĩa na amĩtavya, We ngombo nthũku na ndulu, nĩweesĩ kana nĩkethaa vala ndaavuĩa, na kũmban’ya vala ndaanyaĩĩkya;'),
('kam', 'MAT', 25, 27, 'nĩwaĩlwe ĩndĩ nĩ kũmatwaĩa ala ma vengi mbesa syakwa, na nooka ngyosa ila syakwa vamwe na ũtandĩthyo wasyo.'),
('kam', 'MAT', 25, 28, 'Osai ĩndĩ talendi yayo, mũmĩnenge ĩla yĩ na talendi ĩkũmi.'),
('kam', 'MAT', 25, 29, 'Nũndũ o ũla wĩ na kĩndũ akanengwa, na akaingĩvĩw’a: ĩndĩ ũla ũte na kĩndũ, akoosewa o na kĩla wĩ nakyo.'),
('kam', 'MAT', 25, 30, 'Na ngombo ĩno ĩtaĩle mĩkyei kĩvindunĩ nza: vo vakethĩwa kĩĩo na kũvevetan’ya maeo.'),
('kam', 'MAT', 25, 31, 'Ĩndĩ yĩla Mwana wa mũndũ ũkoka ũtheunĩ wake mũtisu, na alaĩka onthe vamwe nake, nĩvo ũkekalĩla kĩvĩla kya ũsumbĩ kya ũtheu wake mũtisu:'),
('kam', 'MAT', 25, 32, 'na mbee wake nikomban’wa mbaĩ syonthe: nake nũkamavathan’ya aa na aya, tondũ mũĩthi ũvathanasya malondu na mbũi;'),
('kam', 'MAT', 25, 33, 'na nũkaia malondu ngalĩ ya kw’oko kwake kwa aũme, ĩndĩ mbũi ngalĩ ya kw’oko kwake kwa aka.'),
('kam', 'MAT', 25, 34, 'Na ĩndĩ Mũsumbĩ nũkamea ala me ngalĩ ya kw’oko kwake kwa aũme, Ũkai inyw’ĩ mũathimĩtwe nĩ Asa wakwa, osai ũsumbĩ ũla mwaseũvĩw’e kuma mwambĩlĩlyo wa nthĩ:'),
('kam', 'MAT', 25, 35, 'nũndũ naĩ na nzaa, na mwanenga kya ũya; naĩ na waũni, na mwanenga kya ũnyw’a; naĩ mũeni, na mwanthokya;'),
('kam', 'MAT', 25, 36, 'naĩ mũthei, na mwambw’ĩka; naĩ mũwau, na mwooka ũnzisya; naĩ kolokolonĩ, na mwooka vala naĩ.'),
('kam', 'MAT', 25, 37, 'Nĩvo ala alũngalu makamũsũngĩa, makyasya, Mwĩaĩi, nĩ ĩndĩĩ twakwonie wĩ na nzaa, twaũnenga kya ũya? Kana wĩ na waũni, na twaũnenga kya ũnyw’a?'),
('kam', 'MAT', 25, 38, 'Na nĩ ĩndĩĩ twakwonie wĩ mũeni, na twakũthokya? Kana wĩ mũthei, na twakũvw’ĩka?'),
('kam', 'MAT', 25, 39, 'Na nĩ ĩndĩĩ twakwonie wĩ mũwau, kana wĩ kolokolonĩ, na twooka vala waĩ?'),
('kam', 'MAT', 25, 40, 'Na Mũsumbĩ akasũngĩa na kũmea, Nĩ w’o nĩngũmwĩa, O ũndũ mwamwĩkie ũmwe wa ana‐a‐asa aa makwa, o na ala anini, mwambĩkie nyie.'),
('kam', 'MAT', 25, 41, 'Nĩvo ũkamea asu nao ala me ngalĩ ya kw’oko kwake kwa aka, Umai vaa nĩĩ, inyw’ĩ mwaumanĩwe, mũthi mwakinĩ wa tene na tene ũla waseũvĩw’e Satani na alaĩka make:'),
('kam', 'MAT', 25, 42, 'nũndũ naĩ na nzaa, na mũtyaanenga kya ũya; naĩ na waũni, na mũtyaanenga kya ũnyw’a;'),
('kam', 'MAT', 25, 43, 'naĩ mũeni, na mũtyaanthokya; naĩ mũthei, na mũtyaambw’ĩka; naĩ mũwau, na naĩ kolokolonĩ, na mũtyaaũka kũnzisya.'),
('kam', 'MAT', 25, 44, 'Na ĩndĩ asu nao makasũngĩa, makyasya, Mwĩaĩi, nĩ ĩndĩĩ twakwonie wĩ na nzaa, kana wĩ na waũni, kana wĩ mũeni, kana wĩ mũthei, kana wĩ mũwau, kana wĩ kolokolonĩ, na twalea ũkũtethya?'),
('kam', 'MAT', 25, 45, 'Nĩvo ũkamasũngĩa, akyasya, Nĩ w’o nĩngũmwĩa, O ũndũ mũtaamwĩka ũmwe wa aa anini, mũtyaambĩka nyie.'),
('kam', 'MAT', 25, 46, 'Na asu makathi makalika thĩnanĩ wa tene wa tene; ĩndĩ ala alũngalu makalika thayũnĩ ũtathela.'),
('kam', 'MAT', 26, 1, 'Na kweethĩwa, Yesũ amina ndeto isu syonthe, amea amanyĩw’a make,'),
('kam', 'MAT', 26, 2, 'Nĩmwĩsĩ kana ĩtina wa mĩthenya ĩlĩ kũkeethĩwa vasaka, na Mwana wa mũndũ akanenganwe nĩ kana ambwe ngelan’yonĩ.'),
('kam', 'MAT', 26, 3, 'Nĩvo athembi anene, na atumĩa ma andũ, mombanĩte nza ya nyũmba ya mũthembi mũnene wetawa Kaiava:'),
('kam', 'MAT', 26, 4, 'nao masaman’ya nĩ kana mamũkwate Yesũ na ũseleke, na kũmũaa.'),
('kam', 'MAT', 26, 5, 'Ĩndĩ masya, Ti ĩvinda ya mboka, kũikese kũkĩla kĩtuu andũnĩ.'),
('kam', 'MAT', 26, 6, 'Na yĩla Yesũ waĩ Vethania, nyũmbanĩ ya Simoni ũla ũwaĩte mangũ,'),
('kam', 'MAT', 26, 7, 'mũndũ mũka athi vala ũĩ e na sũva wa mauta, me vata mũnene mũno, nake amwĩtĩkĩsya mũtwenĩ wake, ailyĩ lĩunĩ.'),
('kam', 'MAT', 26, 8, 'Ĩndĩ amanyĩw’a moona ũu, maĩ na ũthatu, makyasya, Wanango ũũ nĩ wa kĩ?'),
('kam', 'MAT', 26, 9, 'Nũndũ mauta aa meĩ matonya kũtewa mbesa mbingĩ, ikanengwa ngya.'),
('kam', 'MAT', 26, 10, 'Ĩndĩ Yesũ eew’a ũu amea, Nĩkĩ mũũthĩn’ya mũndũ mũka? Nũndũ ambĩka wĩa mũseo.'),
('kam', 'MAT', 26, 11, 'Nĩkwĩthĩwa ngya mwĩ nasyo mavinda onthe; ĩndĩ nyie mũi nakwa mavinda onthe.'),
('kam', 'MAT', 26, 12, 'Nũndũ akĩmbĩtĩkĩsya mauta aa mwĩĩnĩ wakwa, eeka ũu kũnzeũvya ũndũ wa kũthikwa kwakwa.'),
('kam', 'MAT', 26, 13, 'Nĩ w’o nĩngũmwĩa, O kũla kũkatavanw’a ũvoo ũũ mũseo nthĩ yonthe, ũndũ ũũ naw’o weekwa nĩ mũndũ mũka ũũ ũkawetwa wĩthĩwe wa kũmũlilikana we.'),
('kam', 'MAT', 26, 14, 'Na ĩvinda yĩu ũmwe wa ala ĩkũmi na elĩ, ũla wetawa Yutasi Isikalioti, athi kwa athembi anene,'),
('kam', 'MAT', 26, 15, 'na amakũlya, Mwĩenda kũnenga kyaũ, nakwa ngamũnengane kwenyu? Na mamũthimĩa ilungu mĩongo ĩtatũ sya vetha.'),
('kam', 'MAT', 26, 16, 'Na kuma ĩvinda yĩu amantha mwanya wa kũmũnengane kwoo.'),
('kam', 'MAT', 26, 17, 'Na mũthenya wa mbee wa kĩmũtũ kĩte ĩlawa, amanyĩw’a mooka vala ve Yesũ, makyasya, Wĩenda tũkaũseũvĩsye va, ũye vasaka?'),
('kam', 'MAT', 26, 18, 'Na asya, Endai ndũanĩ kwa mũndũ mũna, mũkamwĩe, Mũmanyĩsya asya, Ĩvinda yakwa nĩyĩthengeee; ngaya vasaka nyũmbanĩ kwaku vamwe na amanyĩw’a makwa.'),
('kam', 'MAT', 26, 19, 'Na amanyĩw’a meeka ũndũ Yesũ wameaĩe; na maseũvya vasaka.'),
('kam', 'MAT', 26, 20, 'Na ĩndĩ kwavika wĩoo, ailyĩ lĩunĩ vamwe na ala ĩkũmi na elĩ;'),
('kam', 'MAT', 26, 21, 'na makĩya, asya, Nĩ w’o nĩngũmwĩa, kana ũmwe wenyu akambũnyanĩa.'),
('kam', 'MAT', 26, 22, 'Nao meew’a woo mũno, na mambĩlĩlya kũmũkũlya ũmwe na ũmwe, Mwĩaĩi, ninyie?'),
('kam', 'MAT', 26, 23, 'Na asũngĩa, asya, Ũla wekĩanĩa kw’oko ĩsaaninĩ vamwe nakwa, nĩwe wĩmbũnyanĩa.'),
('kam', 'MAT', 26, 24, 'Mwana wa mũndũ ethi o ũndũ waandĩkĩwe: ĩndĩ woo nĩ wa mũndũ ũsu ũla wĩmũvũnyanĩa Mwana wa mũndũ! Wĩthĩwa wĩ ũseo kwa mũndũ ũsu kethĩwa ndaasyawa.'),
('kam', 'MAT', 26, 25, 'Na Yutasi, ũla wĩmũvũnyanĩa, asũngĩa na asya, Lavai, ninyie? Amwĩa, We nĩwaneena.'),
('kam', 'MAT', 26, 26, 'Na makĩya, Yesũ oosa kĩmũtũ, akĩathima, na akĩtilanga; na anenga amanyĩw’a, na asya, Osai, mũye; kĩĩ nĩkyo mwĩĩ wakwa.'),
('kam', 'MAT', 26, 27, 'Na oosa kĩkombe, na atũnga mũvea, na amanenga, akyasya, Nyw’ai inyw’onthe;'),
('kam', 'MAT', 26, 28, 'nũndũ ĩno nĩyo nthakame yakwa ya ũtianĩo, ĩla ĩĩtĩkwa kwondũ wa aingĩ kwa ũekeo wa naĩ.'),
('kam', 'MAT', 26, 29, 'Ĩndĩ nĩngũmwĩa, Kuma yu ndikanyw’a ya ũsyao ũũ wa mũsavivũ, mũvaka mũthenya ũla ngamĩnyw’a yĩ nzaũ vamwe nenyu ũsumbĩnĩ wa Asa wakwa.'),
('kam', 'MAT', 26, 30, 'Na mamina kwina, maumaala nza mathi kĩĩmanĩ kya Mĩthata.'),
('kam', 'MAT', 26, 31, 'Nĩvo Yesũ wameie, Ũtukũ ũũ inyw’onthe nĩmũũlulutĩkw’a nũndũ wakwa: nũndũ nĩkũandĩkĩtwe, Ngakũna mũĩthi, na malondu ma ĩĩthya makanyaĩĩkw’a kũũ na kũũ.'),
('kam', 'MAT', 26, 32, 'Ĩndĩ ĩtina wa kũthayũũkw’a kwakwa, ngaenda mbee wenyu kũvika Kalilii.'),
('kam', 'MAT', 26, 33, 'Ĩndĩ Vetelo asũngĩa, amwĩa, Ethĩwa onthe makalulutĩkw’a nũndũ waku, nyie ndilulutĩkw’a nongi.'),
('kam', 'MAT', 26, 34, 'Yesũ amwĩa, Nĩ w’o nĩngũkwĩa, kana ũtukũ ũũ mbee wa nzamba ĩtanasya, ũkangaĩa katatũ.'),
('kam', 'MAT', 26, 35, 'Vetelo amwĩa, O na ethĩwa no mũvaka nĩkw’e naku, ndikakũkaĩa. Na amanyĩw’a onthe masya o ta ũu.'),
('kam', 'MAT', 26, 36, 'Na ĩndĩ Yesũ athi nao kũvika vandũ vetawa Ngesemanii, na amea amanyĩw’a make, Ĩkalai vaa, ĩvinda yĩla ngũthi vaya kũvoya.'),
('kam', 'MAT', 26, 37, 'Na athi e na Vetelo na ana elĩ ma Sevetii, na ambĩlĩlya kũmaka na kũũũya mũno.'),
('kam', 'MAT', 26, 38, 'Nĩvo ĩndĩ wameie, Ngoo yakwa nĩkũũũya mũno, o na kũvika kĩkw’ũ: ĩkalai vaa, mũsyaĩĩsye vamwe nakwa.'),
('kam', 'MAT', 26, 39, 'Nake aendanga mbee vanini, na avalũka na ũthyũ wake, na avoya, akyasya, Asa wakwa, ethĩwa ũũ nũtonyeka, kĩkombe kĩĩ nĩkĩnthonoke: ĩndĩ ti ũndũ ngwenda nyie, ĩndĩ ũndũ ũkwenda we.'),
('kam', 'MAT', 26, 40, 'Na athi vala ve amanyĩw’a make, na amethĩa makomete, na amwĩa Vetelo, Nĩkĩ, mũinatonya kũsyaĩĩsya vamwe nakwa o na saa ũmwe?'),
('kam', 'MAT', 26, 41, 'Syaĩĩsyai na voyai, nĩ kana mũikalike ũtatwanĩ: veva nĩw’o ũkwenda, ĩndĩ mwĩĩ ndwĩ na vinya.'),
('kam', 'MAT', 26, 42, 'Na ĩngĩ athi ĩvinda ya kelĩ, na avoya, akyasya, Asa wakwa, ethĩwa kĩkombe kĩĩ kĩitonya kũnthonoka ndanyw’ĩte, kwenda kwaku kwĩkwe.'),
('kam', 'MAT', 26, 43, 'Na athi ĩngĩ na amethĩa makomete, nũndũ metho moo maĩ na too.'),
('kam', 'MAT', 26, 44, 'Na amatia ĩngĩ, na athi, na avoya ya katatũ, aiasya o ĩla ndeto.'),
('kam', 'MAT', 26, 45, 'Na ĩndĩ athi vala ve ala amanyĩw’a, na amea, Komai yu, mũthũmũe: sisyai, saa nũthengeee, na Mwana wa mũndũ nũnũũnenganwe mokonĩ ma andũ athe.'),
('kam', 'MAT', 26, 46, 'Ũkĩlai, tũthi: sisyai, nũthengeee ũla ũnũũmbũnyanĩa.'),
('kam', 'MAT', 26, 47, 'Na akĩneena, sisya, Yutasi, ũmwe wa ala ĩkũmi na elĩ, ooka, na vamwe nake nguthu nene yĩ na mbyũ na mathimbũ, yumĩte kwa athembi anene na atumĩa ma andũ.'),
('kam', 'MAT', 26, 48, 'Na ũla ũmũvũnyanĩe amanengete wonan’yo, akyasya, O ũla nĩmũmumunya nĩwe ũsu: mũkwatei.'),
('kam', 'MAT', 26, 49, 'Na oyu ooka vala ve Yesũ, asya, Nũvoo, Lavai; na amũmumunya.'),
('kam', 'MAT', 26, 50, 'Na Yesũ amwĩa, Mũnyanyawa, ĩka ũndũ wakũete. Na ĩndĩ mooka matambũũkya moko, mamũkwata Yesũ.'),
('kam', 'MAT', 26, 51, 'Na sisya, ũmwe wa ala maĩ vamwe na Yesũ atambũũkya kw’oko kwake, akũa ũvyũ wake, na amĩtema ngombo ya mũthembi mũnene, amĩtila kũtũ.'),
('kam', 'MAT', 26, 52, 'Na ĩndĩ Yesũ amwĩa, Tũngĩa ũvyũ waku vandũ vaw’o: nũndũ onthe ala makwataa ũvyũ makaanangwa na ũvyũ.'),
('kam', 'MAT', 26, 53, 'Kana wĩasya nditonya kũmwĩsũva Asa wakwa, nake aindetee oyu nguthu sya alaĩka mbee wa ĩkũmi na ilĩ?'),
('kam', 'MAT', 26, 54, 'Ĩndĩ maandĩko ma atĩ nĩ mũvaka ũũ wĩthĩwe, makeanĩw’a ata?'),
('kam', 'MAT', 26, 55, 'Saa ũsu Yesũ amĩtavya nguthu, Nĩmwaumĩla tondũ mũvutani wumĩlĩlawa mwĩ na mbyũ na mathimbũ nĩ kana mũngwate? Kĩla mũthenya nekalaa ĩkalũnĩ ngĩmanyĩsya, na mũtyaangwata.'),
('kam', 'MAT', 26, 56, 'Ĩndĩ ũũ w’onthe ũtw’ikĩte, nĩ kana maandĩko ma athani meanĩw’e. Nĩvo ĩndĩ amanyĩw’a onthe mamũtiie, makĩa.'),
('kam', 'MAT', 26, 57, 'Na ala mamũkwatie Yesũ mamũtwaa kwa Kaiava mũthembi mũnene, vala aandĩki na atumĩa moombanĩte.'),
('kam', 'MAT', 26, 58, 'Ĩndĩ Vetelo amũatĩĩa e kũasa, kũvika nza kwa mũthembi mũnene, na avota nthĩnĩ, na ekala nthĩ vamwe na makanga, one mũminũkĩlyo.'),
('kam', 'MAT', 26, 59, 'Na ĩndĩ athembi anene na nzama yonthe mamũmanthĩa Yesũ ũkũsĩ wa ũvũngũ, nĩ kana mamũae;'),
('kam', 'MAT', 26, 60, 'na maiaawona, o na kau kwaumĩlile ngũsĩ nyingĩ sya ũvũngũ. Ĩndĩ ĩtina kwooka ilĩ,'),
('kam', 'MAT', 26, 61, 'na syasya, Mũndũ ũũ aisye, Nyie nĩndonya kwananga ĩkalũ ya Ngai, na ngĩyaka na matukũ atatũ.'),
('kam', 'MAT', 26, 62, 'Na mũthembi mũnene aũngama, na amwĩa, Ndũsũngĩa ũndũ? Aa makũkũsĩĩa ata?'),
('kam', 'MAT', 26, 63, 'Ĩndĩ Yesũ avindya. Na ũla mũthembi mũnene amwĩa, Nĩngũkwĩavĩthya kwa Ngai ũla wĩ thayũ, ũtũtavye kana nue Klĩsto, Mwana wa Ngai.'),
('kam', 'MAT', 26, 64, 'Yesũ amwĩa, We nĩwaneena: ĩndĩ nĩngũmwĩa, Kuma yu mũkamwona Mwana wa mũndũ ailyĩ ngalĩ ya kw’oko kwa aũme kwa Vinya, na akyũka e ĩũlũ wa mathweo ma ĩtu.'),
('kam', 'MAT', 26, 65, 'Na yu mũthembi mũnene atembũa ngũa syake, akyasya, Nĩwaumana: twĩ na vata ũngĩ mwaũ wa ngũsĩ? Sisyai, yu nĩmweew’a kũumana kwake:'),
('kam', 'MAT', 26, 66, 'mwĩona ata? Masũngĩa, masya, Aĩlwe nĩ kĩkw’ũ.'),
('kam', 'MAT', 26, 67, 'Na ĩndĩ mamũtw’ĩla mata ũthyũ, na mamũlumangya na ngundi: na amwe mamũmandũla,'),
('kam', 'MAT', 26, 68, 'makyasya, Twathanĩe, we Klĩsto, nũũ ũla wakũkũna?'),
('kam', 'MAT', 26, 69, 'Na Vetelo ailyĩ nza ku ũtee: na mwĩĩtu mũthũkũmi ooka vala ũĩ, akyasya, We naku ũnaĩ vamwe na Yesũ Mũkalilii.'),
('kam', 'MAT', 26, 70, 'Ĩndĩ akaĩa mbee wa onthe, akyasya, Ndyĩsĩ ũndũ ũkwasya.'),
('kam', 'MAT', 26, 71, 'Nake aumaala valasyanĩ, mwĩĩtu ũngĩ amwona, na amea ala maĩ vo, Mũndũ ũũ nake anaĩ vamwe na Yesũ wa Nasaleti.'),
('kam', 'MAT', 26, 72, 'Na akaĩa ĩngĩ na wĩvĩto, Ndimwĩsĩ mũndũ ũsu.'),
('kam', 'MAT', 26, 73, 'Na ĩtina vandũ vanini, ala maũngeme vakuvĩ, mathi na mamwĩa Vetelo, Nĩ w’o we wĩ ũmwe woo; nũndũ kĩthyomo kyaku nĩkĩũkumbũla.'),
('kam', 'MAT', 26, 74, 'Na ĩndĩ ambĩlĩlya kũumana na kwĩvĩta, akyasya, Nyie ndimwĩsĩ mũndũ ũsu. Na oyu nzamba yasya.'),
('kam', 'MAT', 26, 75, 'Na Vetelo alilikana ndeto ĩla ĩnaneeniwe nĩ Yesũ, Nzamba ĩtanamba kwasya, ũkangaĩa katatũ. Nake aumaala, na aĩa kĩĩo kĩ woo.'),
('kam', 'MAT', 27, 1, 'Na kwakya, athembi onthe anene na atumĩa ma andũ mamũsamĩa Yesũ, nĩ kana mamũae:'),
('kam', 'MAT', 27, 2, 'na mamwova, mamũtwaa, na mamũnengane kwa ũla ngavana Vilato.'),
('kam', 'MAT', 27, 3, 'Na ĩndĩ Yutasi, ũla wamũvũnyanie, oona kana nĩwasilĩlwa, eelila, na amatũngĩa athembi anene na atumĩa ila ilungu mĩongo ĩtatũ sya vetha,'),
('kam', 'MAT', 27, 4, 'akyasya, Nĩnĩvĩtĩtye nũndũ nĩnĩmũvũnyanie ũla nthakame yake ĩte ĩvĩtyo. Ĩndĩ mo masya, Ũu nĩ ũndũ witũ ata? Sisya eue.'),
('kam', 'MAT', 27, 5, 'Nake ekya ila ilungu sya vetha nthĩnĩ wa vala vandũ vatheu, na aumaala; na athi eesũsya.'),
('kam', 'MAT', 27, 6, 'Na athembi anene moosa ilungu sya vetha na masya, Kũtyosana na ĩla mĩao kũsia vala vaiawa nthembo, nĩkwĩthĩwa nĩ thooa wa nthakame.'),
('kam', 'MAT', 27, 7, 'Na masũanĩa na mathooa kĩsesi kya mũmbi nasyo, kĩthĩwe vandũ va kũthikaa aeni.'),
('kam', 'MAT', 27, 8, 'Kwondũ wa ũu kĩsesi kyu kyeetwa, Kĩsesi kya nthakame, kũvika ũmũnthĩ.'),
('kam', 'MAT', 27, 9, 'Nĩvo weanĩw’e ũla waneeniwe nĩ Yelemia, akyasya, Na nĩmoosie ilungu mĩongo ĩtatũ sya vetha, thooa wa ũsu ũla watw’ĩĩwe thooa, ũla amwe ma ana ma Isilaeli mamũtw’ĩĩe thooa;'),
('kam', 'MAT', 27, 10, 'na mainengane kwondũ wa kĩsesi kya mũmbi o ũndũ Mwĩaĩi wambĩaĩe.'),
('kam', 'MAT', 27, 11, 'Na Yesũ aũngama mbee wa ngavana: na ngavana amũkũlya, akyasya, We nue Mũsumbĩ wa Ayuti? Na Yesũ amwĩa, We nĩwaneena.'),
('kam', 'MAT', 27, 12, 'Na avinganĩw’a nĩ athembi anene na atumĩa, ndaasũngĩa ũndũ.'),
('kam', 'MAT', 27, 13, 'Nĩvo ĩndĩ Vilato wamwĩie, Ndũkwĩw’a maũndũ ũndũ meana ala meũkũkũsĩĩa?'),
('kam', 'MAT', 27, 14, 'Nake ndaamũsũngĩa ndeto o na ĩmwe: mũvaka ngavana aseng’a mũno.'),
('kam', 'MAT', 27, 15, 'Na ĩndĩ ĩvinda ya mboka ngavana akothaa kũyĩthaĩsya ĩkomano mwovwa ũmwe, o ũla mekwenda.'),
('kam', 'MAT', 27, 16, 'Na ĩvinda yĩu maĩ na mwovwa ũmwe wesĩkĩwe, wetawa Valava.'),
('kam', 'MAT', 27, 17, 'Na ĩndĩno mombanĩte vamwe, Vilato amea, Mwĩenda nĩmũthaĩsye ũũ? Valava, kana Yesũ ũla wĩtawa Klĩsto?'),
('kam', 'MAT', 27, 18, 'Nũndũ nĩwesĩ kana mamũnenganie nũndũ wa kĩwĩu.'),
('kam', 'MAT', 27, 19, 'Na akĩkalĩla kĩvĩla kya sila, kĩveti kyake kyamũtwaĩa ũtũmane, kĩkyasya, Ndũkethĩwe na ũndũ na mũndũ ũsu mũlũngalu; nũndũ ũmũnthĩ nĩthĩniw’e nĩ maũndũ maingĩ ndotonĩ nũndũ wake.'),
('kam', 'MAT', 27, 20, 'Na ala athembi anene na atumĩa mamathinga’ĩĩsya makomano nĩ kana mamwĩtye Valava, na kũmũaa Yesũ.'),
('kam', 'MAT', 27, 21, 'Ĩndĩ ngavana asũngĩa na amea, Andũ aa elĩ, mwĩenda nĩmũthaĩsye wĩva? Nao masya, Valava.'),
('kam', 'MAT', 27, 22, 'Vilato amea, Nĩmwĩke ata ĩndĩ Yesũ ũla wĩtawa Klĩsto? Onthe masya, Nĩambwe.'),
('kam', 'MAT', 27, 23, 'Nake asya, Nĩkĩ, nĩ ũthũku mwaũ wĩkĩte? Ĩndĩ maneena na mawasya manene mũno, makyasya, Nĩambwe.'),
('kam', 'MAT', 27, 24, 'Na ĩndĩ Vilato oona kana ndatonya ũndũ, ĩndĩ kĩtuu nĩkĩkwingĩva, oosa manzĩ, na athambĩsya moko make mbee wa ĩkomano, akyasya, Nyie ndi na ĩvĩtyo nthakamenĩ ya mũndũ ũũ mũlũngalu; sisyai ũndũ ũsu e inyw’ĩ.'),
('kam', 'MAT', 27, 25, 'Na andũ onthe masũngĩa, masya, Nthakame yake yĩthĩwe ĩũlũ waitũ, na ĩũlũ wa syana sitũ.'),
('kam', 'MAT', 27, 26, 'Nĩvo ĩndĩ wamathaĩsye Valava; ĩndĩ amũkũna Yesũ na kĩvoko kyatũange, na amũnengane ambwe.'),
('kam', 'MAT', 27, 27, 'Nĩvo asikalĩ ma ngavana mamũtwaie Yesũ kĩsilĩlonĩ, na mamũmbanĩsya nguthu yonthe ya asikalĩ.'),
('kam', 'MAT', 27, 28, 'Na mamumya ngũa mamwĩkĩa ngũa ndune mũno.'),
('kam', 'MAT', 27, 29, 'Na mavĩlangan’ya ngovia ya mĩw’a na mamwĩkĩa mũtwe wake, na mamũkwatĩthya mũangi kw’okonĩ kwake kwa aũme; na matulya ndu mbee wake na mamũthekeea na kĩvũthya, makyasya, Nũvoo, Mũsumbĩ wa Ayuti!'),
('kam', 'MAT', 27, 30, 'Na mamũtw’ĩla mata, na moosa ũla mũangi na mamũkũna mũtwe.'),
('kam', 'MAT', 27, 31, 'Na mamina ũmũthekeea, mamumya ĩla ngũa, na mamwĩkĩa ngũa syake, mamũtwaa kũmwamba ngelan’yonĩ.'),
('kam', 'MAT', 27, 32, 'Na makyumaala, mamwĩthĩa mũndũ wa Kulene, wetawa Simoni: ũsu mamũkwata na vinya athi nao, nĩ kana amũkuĩe ngelan’yo yake.'),
('kam', 'MAT', 27, 33, 'Na mavika vandũ vetawa Kolokotha, ũalyũlo wayo nĩ, Vandũ va kĩng’ala,'),
('kam', 'MAT', 27, 34, 'mamũnenga mbinyu ĩvulanĩtw’e na nyongo: nake amĩsama, ndaaĩtĩkĩla kũnyw’a.'),
('kam', 'MAT', 27, 35, 'Na mamwamba, maan’ya ngũa syake makĩlimana; nĩ kana kwĩanĩw’e ũla waneeniwe nĩ mwathani, Nĩmaanisye ngũa syakwa katĩ woo, na kwondũ wa kĩtonyeo kyakwa kĩasa nĩmalimanile.'),
('kam', 'MAT', 27, 36, 'Na mekala nthĩ vo mamũsyaĩĩsye.'),
('kam', 'MAT', 27, 37, 'Na meekĩa ũvingan’yo ĩũlũ wa mũtwe wake, ũandĩkĩtwe, ŨŨ NĨWE YESŨ MŨSUMBĨ WA AYUTI.'),
('kam', 'MAT', 27, 38, 'Nĩvo avutani elĩ mambiwe vamwe nake, ũmwe ngalĩ ya kw’oko kwake kwa aũme, na ũngĩ ngalĩ ya kw’oko kwake kwa aka.'),
('kam', 'MAT', 27, 39, 'Na ala mavĩtaa nzĩanĩ mamũuma, makĩthingithya mĩtwe yoo,'),
('kam', 'MAT', 27, 40, 'makyasya, We ũla wanangaa ĩkalũ, nokĩyaka na mĩthenya ĩtatũ, ĩtangĩĩe mwene: ethĩwa nue Mwana wa Ngai, theea wume ngelan’yonĩ.'),
('kam', 'MAT', 27, 41, 'No ta ũu ala athembi anene makĩmũthekeea, vamwe na aandĩki na atumĩa, masya,'),
('kam', 'MAT', 27, 42, 'Nĩwatangĩĩe angĩ; ndatonya kwĩtangĩĩa mwene. Nĩ mũsumbĩ wa Isilaeli; natheee yu aume ngelan’yonĩ, naitũ nĩtũũmwĩtĩkĩla.'),
('kam', 'MAT', 27, 43, 'Nũmũĩkĩĩaa Ngai; namũvonokye yu, ethĩwa nũmwendete: nũndũ aisye, Nyie nĩ Mwana wa Ngai.'),
('kam', 'MAT', 27, 44, 'Na avutani nao ala mambĩtwe vamwe nake mamũneenea ndeto ta isu.'),
('kam', 'MAT', 27, 45, 'Na kuma syũa yaũngama kwatulya kĩvindu nthĩ yonthe kũvika saa kenda.'),
('kam', 'MAT', 27, 46, 'Na ta saa kenda Yesũ aneena na wasya mũnene, akyasya, Eli, Eli, lama, savakathani? Ũalyũlo wayo nĩ, Ngai wakwa, Ngai wakwa, ũndekee kĩ?'),
('kam', 'MAT', 27, 47, 'Na amwe ma ala maũngeme vo, meew’a ũu, masya, Mũndũ ũũ emwĩta Eliya.'),
('kam', 'MAT', 27, 48, 'Na oyu ũmwe woo asemba, na oosa sivanzi, anyw’ĩthya siki yakola, na amĩkĩa mũanginĩ, na amũnenga avivite.'),
('kam', 'MAT', 27, 49, 'Na ala angĩ masya, Ekai; tũsisye kana Eliya nũnũkũka kũmũtangĩĩa.'),
('kam', 'MAT', 27, 50, 'Na Yesũ aneena ĩngĩ na wasya mũnene, na aumya veva wake.'),
('kam', 'MAT', 27, 51, 'Na sisya, ngũa ya tũtũ ya ĩkalũ yatembũka ilungu ilĩ kuma ĩũlũ kũvika nthĩ; na nthĩ yatetema; na mavia manene maatũka;'),
('kam', 'MAT', 27, 52, 'na mbũa syavingũka; na mĩĩ mingĩ ya atheu ala maĩ manakoma yathayũũkw’a;'),
('kam', 'MAT', 27, 53, 'na makyuma mbũanĩ ĩtina wa kũthayũũka kwake, malika ĩla ndũanĩ ntheu na mamaumĩlĩla aingĩ.'),
('kam', 'MAT', 27, 54, 'Na ĩndĩ ũla mũnene wa asikalĩ ĩana, na ala maĩ nake makĩmũsyaĩĩsya Yesũ, moona kĩtetemo kya nthĩ, na maũndũ ala meekĩka, makĩa mũno, makyasya, Nĩ w’o ũũ eĩ Mwana wa Ngai.'),
('kam', 'MAT', 27, 55, 'Na aka aingĩ maĩ vo makĩsisya me kũasa, ala mamũatĩĩe Yesũ kuma Kalilii, makĩmũtethya:'),
('kam', 'MAT', 27, 56, 'na amwe moo maĩ Meli Makatalene, na Meli inyia wa Yakovo na Yose, na inyia wa ana ma Sevetii.'),
('kam', 'MAT', 27, 57, 'Na kwavika wĩoo, kwathi mũndũ mũthwii wa nthĩ ya Alimathia, wetawa Yosevu, nake mwene aĩ mũmanyĩw’a wa Yesũ:'),
('kam', 'MAT', 27, 58, 'mũndũ ũsu athi kwa Vilato, amwĩtya mwĩĩ wa Yesũ. Na ĩndĩ Vilato eeaa anengwe.'),
('kam', 'MAT', 27, 59, 'Na Yosevu oosa mwĩĩ, na oolingĩla ngũa ntheu ya katane,'),
('kam', 'MAT', 27, 60, 'na awia mbũanĩ yake nzaũ, ĩla wasĩte ĩvianĩ ĩnene: na avingilitya ĩvia ĩnene mũomonĩ wa mbũa, na athi.'),
('kam', 'MAT', 27, 61, 'Na Meli Makatalene aĩ vo, na Meli ũla ũngĩ, mailyĩ nthĩ melekele ĩla mbũa.'),
('kam', 'MAT', 27, 62, 'Na ũnĩ ũsu, naw’o nĩ mũthenya waatĩĩe ũla wa Ũseũvyo, athembi anene na Avalisi mamũmbanĩa Vilato,'),
('kam', 'MAT', 27, 63, 'makyasya, Vwana, nĩtũlilikene kana mũkengani ũsu yĩla waĩ thayũ aisye, Ĩtina wa matukũ atatũ ngathayũũka.'),
('kam', 'MAT', 27, 64, 'Ĩae ĩndĩ kana mbũa isũvĩwe mũno kũvika mũthenya wa katatũ, amanyĩw’a make maikese kũka mamũye, na kũmatavya andũ, Nũthayũũkĩte kuma kwa akw’ũ: na ũkengani wa ĩtina ũkeethĩwa wĩ mũnene kwĩ ũla wa mbee.'),
('kam', 'MAT', 27, 65, 'Vilato amea, Mwĩ na asũvĩi: endai mũkamĩlũlũmĩlye mũno o ũndũ mũtonya.'),
('kam', 'MAT', 27, 66, 'Nao mathi, malũlũmĩlya mbũa, makĩkĩa ĩvia ũsiĩlo, ala asũvĩi me vamwe nao.'),
('kam', 'MAT', 28, 1, 'Na mũthenya wa savato wathela, kũiambĩlĩlya kũkya mũthenya wa mbee wa kyumwa, Meli Makatalene na Meli ũla ũngĩ mathi kũsisya mbũa.'),
('kam', 'MAT', 28, 2, 'Na sisya, kwaĩ kĩtetemo kĩnene kya nthĩ; nũndũ mũlaĩka wa Mwĩaĩi atheeie kuma ĩtunĩ, na athi na avingilitya yĩla ĩvia, na ayĩkalĩla.'),
('kam', 'MAT', 28, 3, 'Na mũvw’ano wake wailyĩ ta ũtisi, na ngũa syake syaĩ nzaũ ta ĩa:'),
('kam', 'MAT', 28, 4, 'na kwondũ wa ũmũkĩa asũvĩi matetema, na meethĩwa ta akw’ũ.'),
('kam', 'MAT', 28, 5, 'Na mũlaĩka asũngĩa, amea ala aka, Mũikakĩe inyw’ĩ; nũndũ nĩnĩsĩ mwĩmantha Yesũ ũla ũnambiwe.'),
('kam', 'MAT', 28, 6, 'Nde vaa; nũndũ nũthayũũkie o tondũ waisye. Ũkai, mwone vala Mwĩaĩi ũnakomete.'),
('kam', 'MAT', 28, 7, 'Na endai na mĩtũkĩ, mũkatavye amanyĩw’a make, Nũthayũũkĩte kuma kwa akw’ũ; na sisyai, etongosya mbee wenyu kũthi Kalilii; nĩkw’o mwĩmwona; sisyai, nĩnamũtavya.'),
('kam', 'MAT', 28, 8, 'Nao mauma mbũanĩ mĩtũkĩ me na w’ĩa na ũtanu mũnene, mathi masembete mamaetee amanyĩw’a make ũvoo.'),
('kam', 'MAT', 28, 9, 'Na sisya, Yesũ akomana nao, akyasya, Ĩthĩwai na ũtanu. Nao mathengeea mamũkwata maũũ, na mamũthaitha.'),
('kam', 'MAT', 28, 10, 'Na ĩndĩ Yesũ amea, Mũikakĩe: endai mũkamatavye ana‐a‐asa makwa mathi Kalilii, na nĩkw’o membona.'),
('kam', 'MAT', 28, 11, 'Na maendete, sisya, amwe ma asũvĩi mathi ndũanĩ, na mamatavya athembi anene maũndũ onthe ala mekiwe.'),
('kam', 'MAT', 28, 12, 'Na moombana na atumĩa na masũanĩa, manenga ala asikalĩ mbesa mbingĩ,'),
('kam', 'MAT', 28, 13, 'makyasya, Asyai, Amanyĩw’a make mokie ũtukũ mamũya yĩla twĩĩkomete.'),
('kam', 'MAT', 28, 14, 'Na ũndũ ũsu weew’ĩka kwa ngavana, ithyĩ tũkamũĩkĩĩthya, na kũmũvetea inyw’ĩ thĩna.'),
('kam', 'MAT', 28, 15, 'Na ĩndĩ moosa ila mbesa, meeka o ũndũ mamanyĩiw’e: na ũndũ ũsu wanyaĩĩkw’a kwa Ayuti kũvika ũmũnthĩ.'),
('kam', 'MAT', 28, 16, 'Ĩndĩ ala amanyĩw’a ĩkũmi na ũmwe mathi Kalilii, kũvika kĩĩmanĩ kĩla meeaĩwe nĩ Yesũ.'),
('kam', 'MAT', 28, 17, 'Nao mamwona mamũthaitha: ĩndĩ amwe maĩ na nzika.'),
('kam', 'MAT', 28, 18, 'Na Yesũ ooka vala maĩ, na aneena nao, akyasya, Nĩnĩnengetwe ũkũmũ w’onthe ĩtunĩ na kũũ nthĩ.'),
('kam', 'MAT', 28, 19, 'Endai ĩndĩ mũkatw’ĩkĩthye mbaĩ syonthe amanyĩw’a, mũkĩmavatisa syĩtwanĩ ya Asa na ya Mwana na ya Veva Mũtheu:'),
('kam', 'MAT', 28, 20, 'mũkĩmamanyĩsya kũkwata maũndũ onthe o na meva ala namwĩaĩe: na sisyai, nyie nĩ vamwe nenyu mĩthenya yonthe, kũvika wĩanĩu wa ĩvinda yĩĩ.'),
('kam', 'MRK', 1, 1, 'Wambĩlĩlyo wa ũvoo mũseo wa Yesũ Klĩsto, Mwana wa Ngaĩ.'),
('kam', 'MRK', 1, 2, 'O tondũ kũandĩkĩte ĩvukunĩ ya mwathani Isaia, Sisya, nyie nĩngũtũma mũtũmwa wakwa mbee wa ũthyũ waku, Ũla ũkaseũvya nzĩa yaku;'),
('kam', 'MRK', 1, 3, 'Wasya wa mũndũ akĩneena mũno weũnĩ, Seũvyai nzĩa ya Mwĩaĩi, Lũngalyai moendelo make;'),
('kam', 'MRK', 1, 4, 'Yoana nĩwokie, akĩvatisa weũnĩ na akĩtavan’ya ũvatiso wa ũalyũlo wa ngoo ũetae ũekeo wa naĩ.'),
('kam', 'MRK', 1, 5, 'Na nthĩ yonthe ya Yutia, na onthe ma Yelusaleme, mooka vala ũĩ; na mavatisĩwa nĩwe ũsĩnĩ wa Yolotanĩ, makyumbũla nai syoo.'),
('kam', 'MRK', 1, 6, 'Na Yoana eekĩĩte ngũa ya w’ĩa wa ngamĩle, na aĩ na mũkwa kĩnyunyunĩ kyake, na aĩsaa ngie na ũkĩ wa nzũkĩ wa kĩthekanĩ.'),
('kam', 'MRK', 1, 7, 'Na atavan’ya, akyasya, Ĩtina wakwa kũkĩte ũla wĩ vinya kwĩ nyie, o na ndyĩanĩwe nĩ ũkunama nĩthasye tũmĩkwa twa iatũ syake.'),
('kam', 'MRK', 1, 8, 'Nyie nĩnĩnamũvatĩsaa na manzĩ; ĩndĩ ũsu akamũvatisaa na Veva Mũtheu.'),
('kam', 'MRK', 1, 9, 'Na kweethĩwa matukũ asu, Yesũ ooka kuma Nasaleti ya Kalilii, na avatisĩwa nĩ Yoana ũsĩnĩ wa Yolotani.'),
('kam', 'MRK', 1, 10, 'Na oyu akyuma manzĩnĩ, oona matu mavingũka, na Veva ailyĩ ta ĩvũĩ aimũtheeea:'),
('kam', 'MRK', 1, 11, 'na wasya wauma ĩtunĩ, We nue Mwana wakwa mwendwa, nendeew’e nue.'),
('kam', 'MRK', 1, 12, 'Na oyu Veva amũtwaa na vinya weũnĩ.'),
('kam', 'MRK', 1, 13, 'Na aĩ ku weũnĩ matukũ mĩongo ĩna akĩtatwa nĩ Satani; na aĩ vamwe na nyamũ sya kĩthekanĩ; na alaĩka nĩmamũthũkũmaa.'),
('kam', 'MRK', 1, 14, 'Na ĩtina wa Yoana kwĩkĩwa kolokolonĩ, Yesũ aenda Kalilii akĩtavan’ya ũvoo mũseo wa Ngai,'),
('kam', 'MRK', 1, 15, 'akyasya, Ĩvinda nĩ ĩviku, na ũsumbĩ wa Ngai nũthengeee: alyũlai ngoo na mũkĩtĩkĩla ũvoo mũseo.'),
('kam', 'MRK', 1, 16, 'Na akĩvĩtĩla ũtee wa ũkanga wa Kalilii, oona Simoni na Andalea mwana‐a‐inyia makĩkya kĩtei ũkanganĩ; nũndũ maĩ atei ma makũyũ.'),
('kam', 'MRK', 1, 17, 'Na Yesũ amea, Ngatĩĩai, nakwa ngamũtw’a atei ma andũ.'),
('kam', 'MRK', 1, 18, 'Na oyu matia itei, na mamũatĩĩa.'),
('kam', 'MRK', 1, 19, 'Na aendanga mbee vanini na oona Yakovo mwana wa Sevetii, na Yoana mwana‐a‐inyia, nao maĩ ngalawanĩ makĩseũvya itei syoo.'),
('kam', 'MRK', 1, 20, 'Na oyu ameta: na matia ĩthe woo Sevetii ngalawanĩ vamwe na athũkũmi, na mamũatĩĩa.'),
('kam', 'MRK', 1, 21, 'Na mathi Kavelinaumi; na oyu mũthenya wa savato avota ĩsinakokenĩ na amanyĩsya.'),
('kam', 'MRK', 1, 22, 'Na maseng’w’a nĩ ũmanyĩsyo wake: nĩkwĩthĩwa amamanyĩsya ta ũla wĩ na ũkũmũ, o na ti ta aandĩki.'),
('kam', 'MRK', 1, 23, 'Na oyu ĩsinakokenĩ yoo kwaĩ mũndũ ũla wakwetwe nĩ veva mũvũku; na aneena na wasya mũnene,'),
('kam', 'MRK', 1, 24, 'akyasya, Twĩ ũndũ naku wa kyaũ, we Yesũ Mũnasaleti? Nĩwooka kũtwananga? Nĩngwĩsĩ we, wĩ ũla Mũtheũ wa Ngai.'),
('kam', 'MRK', 1, 25, 'Na Yesũ ookan’ya, akyasya, Tumya kanyw’a, noimuma.'),
('kam', 'MRK', 1, 26, 'Na ũla veva mũvuku, ũkĩmũthingithangya na kũkaya na wasya mũnene, wamuma.'),
('kam', 'MRK', 1, 27, 'Na onthe maseng’a, mũvaka makũlan’ya ene kwa ene, makyasya, Ũndũ ũũ nata? Ũmanyĩsyo mweũ! Nũkwĩaĩa na ũkũmũ o na maveva mavuku, na nĩmeũmwĩw’a.'),
('kam', 'MRK', 1, 28, 'Na oyu nguma yake yanyaĩĩka nthĩ yonthe ya Kalĩlii na ndee syayo.'),
('kam', 'MRK', 1, 29, 'Na oyu, mauma ĩsinakokenĩ, mavota nyũmbanĩ ya Simoni na Andalea, vamwe na Yakovo na Yoana.'),
('kam', 'MRK', 1, 30, 'Na ĩndĩ inyia wa mũka wa Simoni akomete awaĩte ndetema; na oyu mamũtavya ũvoo wake:'),
('kam', 'MRK', 1, 31, 'nake ooka na amũkwata kw’oko, amũkĩlya; na ndetema yamũtia, nake amathũkũma.'),
('kam', 'MRK', 1, 32, 'Na wĩoo, syũa yĩkĩthũa, mamũetee onthe ala maĩ awau, na ala makwetwe nĩ ndaimoni.'),
('kam', 'MRK', 1, 33, 'Na andũ ma ndũa yonthe moombana vamwe mũomonĩ.'),
('kam', 'MRK', 1, 34, 'Na avosya aingĩ ala mawaĩte mowau ma mĩthemba mingĩ, na aumya ndaimoni nyingĩ; na ndaaĩtĩkĩla ndaimoni ineene, nĩkwĩthĩwa nĩsyamwĩsĩ.'),
('kam', 'MRK', 1, 35, 'Na kĩoko tene, w’oa ũtanatema, ookĩla, aumaala, na athi vandũ vate andũ, na avoyea vo.'),
('kam', 'MRK', 1, 36, 'Na Simoni na ala maĩ nake mamũvikĩla;'),
('kam', 'MRK', 1, 37, 'na mamwona mamwĩa, Andũ onthe nĩmeũkũmantha.'),
('kam', 'MRK', 1, 38, 'Nake amea, Tũendei kũngĩ, kũvika tũtũla tũla twĩ mbee, nĩtavan’ye ku nakw’o; nũndũ nyie naetiwe nĩ ũu.'),
('kam', 'MRK', 1, 39, 'Na atavan’ya masinakokenĩ moo Kalilii kw’onthe, na aumya ndaimoni.'),
('kam', 'MRK', 1, 40, 'Na mũndũ ũwaĩte mangũ athi vala ũĩ, akĩmwĩsũva na kũmũtulĩlya ndu, na kũmwĩa, Ethĩwa nũkwenda, nũtonya kũnthesya.'),
('kam', 'MRK', 1, 41, 'Na Yesũ ũndũ wa kũmwĩw’ia ĩnee, atambũũkya kw’oko kwake, amũkiita, na amwĩa, Nĩngwenda; ĩthĩwa mũtheu.'),
('kam', 'MRK', 1, 42, 'Na oyu mangũ mavoa, na athea'),
('kam', 'MRK', 1, 43, 'Na amwĩaĩa na vinya, na amumaalya oyu, akĩmwĩa,'),
('kam', 'MRK', 1, 44, 'Sisya ndũkatavye mũndũ o na wĩva; ĩndĩ thi ũkeyonan’ye kwa mũthembi, nokyũmya nthembo ila Mose weaie kwondũ wa kũthew’a kwaku, syĩthĩwe ũkũsĩ kwoo.'),
('kam', 'MRK', 1, 45, 'Ĩndĩ aumaala, na ambĩlĩya kũtavan’ya mũno na kũnyaĩĩkya ũvoo ũsu, na kwondũ wa ũu Yesũ ndaatonya ĩngĩ kũvota ndũanĩ eyonanĩtye, ĩndĩ ekala ũtee kũndũ kũte andũ: na andũ mooka vala ũĩ kuma kĩla vandũ.'),
('kam', 'MRK', 2, 1, 'Na matukũ amwe mathela, asyoka ĩngĩ Kavelinaumi, na kwatavanw’a kana e vo nyũmbanĩ.'),
('kam', 'MRK', 2, 2, 'Na aingĩ moombana vamwe, mũvaka vatyaatiala ũthei, aiee, o na mũomonĩ: nake amatavya ĩla ndeto.'),
('kam', 'MRK', 2, 3, 'Na mooka mamũtee mũndũ ũla waĩ na ũwau wa kwaa mamutha, akuĩtwe nĩ andũ ana.'),
('kam', 'MRK', 2, 4, 'Na meethĩa matitonya kũmũthengeea nũndũ wa mũvivinyano wa andũ, mathaĩlya kĩalanĩ vala waĩ: na mavũthũa, matheesya ũkomo ũla ũsu waĩ na ũwau wa kwaa mamutha ũkomee.'),
('kam', 'MRK', 2, 5, 'Na Yesũ oona mũĩkĩĩo woo, amwĩa ũla waĩ na ũwau wa kwaa mamutha, Mwana, naĩ syaku nĩsyaekwa.'),
('kam', 'MRK', 2, 6, 'Ĩndĩ vaĩ amwe ma aandĩki mekalĩte vo, makĩsũanĩa ngoonĩ syoo,'),
('kam', 'MRK', 2, 7, 'Nĩkĩ mũndũ ũũ ũnũũneeka ũu? Nũkũumana: nũũ ũtonya kũekea naĩ ate o ũmwe, nake nĩ Ngaĩ?'),
('kam', 'MRK', 2, 8, 'Na oyu Yesũ amanya vevanĩ wake kana nĩmeũsũanĩa ũu nthĩnĩ woo, amea, Nĩkĩ mũũsũanĩa maũndũ asu ngoonĩ syenyu?'),
('kam', 'MRK', 2, 9, 'Ũla ũvũthũ nĩ wĩva, kũtavya ũũ eĩ na ũwau wa kwaa mamutha, Naĩ syaku nĩsyaekwa; kana kwasya, Ũkĩla noyosa ũkomo waku ũende?'),
('kam', 'MRK', 2, 10, 'Ĩndĩ nĩ kana mũmanye atĩ Mwana wa mũndũ e na ũkũmũ kũũ nthĩ wa kũekea naĩ (amwĩa ũla waĩ na ũwau wa kwaa mamutha),'),
('kam', 'MRK', 2, 11, 'Nĩngũkwĩa, Ũkĩla, ũkue ũkomo waku, wĩnũke.'),
('kam', 'MRK', 2, 12, 'Nake ookĩla, na oyu akua ũkomo, aumaala onthe makyona; na kwondũ wa ũu onthe maseng’a, na mamũtaĩa Ngai, makyasya, Tũtyaaona ũndũ ta ũu ĩngĩ nongi.'),
('kam', 'MRK', 2, 13, 'Na aumaala ĩngĩ athi ũtee wa ũkanga; na ĩkomano yonthe yamũmbanĩa, nake amamanyĩsya.'),
('kam', 'MRK', 2, 14, 'Na avĩtĩte, oona Livai mwana wa Alivaio ekalĩte vala vaumĩaw’a koti, na amwĩa, Mbikĩla. Nake ookĩla amũvikĩla.'),
('kam', 'MRK', 2, 15, 'Na kweethĩwa ekalĩte nyũmba ya mũndũ ũsu akĩya lĩu, aumya ma koti na andũ athe aingĩ mekala nthĩ vamwe na Yesũ na amanyĩw’a make: nĩkwĩthĩwa maĩ aingĩ, na nĩmamũvikĩlĩte.'),
('kam', 'MRK', 2, 16, 'Na aandĩki ma Avalisi, mamwona akĩya vamwe na aumya ma koti na andũ athe, mamea amanyĩw’a make, Kũilyĩ ata ũũ ũnũkũya na kũnyw’a vamwe na aumya ma koti na andũ athe?'),
('kam', 'MRK', 2, 17, 'Na Yesũ eew’a ũũ amea, Ala mate awau mati vata wa mũiiti, ĩndĩ no ala awau: ndyaaũka kwĩta ala alũngalu ĩndĩ nĩ ala athe.'),
('kam', 'MRK', 2, 18, 'Na amanyĩw’a ma Yoana na ma Avalisi nĩmatĩĩaa ũya: nao mooka mamwĩa Yesũ, Nĩkĩ amanyĩw’a ma Yoana na amanyĩw’a ma Avalisi nĩmatĩĩaa ũya, ĩndĩ amanyĩw’a maku matitĩĩaa ũya?'),
('kam', 'MRK', 2, 19, 'Na Yesũ amakũlya, Ala metĩtwe mũtwaanonĩ nĩmatonya kũtĩĩa ũya ĩvinda yĩla mũtwaanĩ wĩ vamwe nao? Mũtwaani e vo vamwe nao maitonya kũtĩĩa ũya.'),
('kam', 'MRK', 2, 20, 'Ĩndĩ mĩthenya nĩyũkĩte, yĩla mũtwaani ũkaumw’a kwoo, na ĩndĩ makatĩĩa ũya mĩthenya ĩsu.'),
('kam', 'MRK', 2, 21, 'Na vai mũndũ ũliaa kĩlio kya ngũa nzaũ ngũanĩ ngũũ: nũndũ alia, kĩla kyeũ kĩkĩawa vo nĩkyumasya kĩlungu ngũanĩ ngũũ, na ũtembũku ũiendeea ũineneva.'),
('kam', 'MRK', 2, 22, 'O na vai mũndũ wĩkĩaa mbinyu mbĩthĩ mathatwanĩ makũũ; nũndũ eekĩa, ĩla mbinyu ĩkatembũa mathatwa, na mbinyu ĩkĩtĩka, na mathatwa makyanangĩka: ĩndĩ mekĩaa mbinyu mbĩthĩ mathatwanĩ meũ.'),
('kam', 'MRK', 2, 23, 'Na kweethĩwa, aendele mĩũndanĩ ya nganũ mũthenya wa savato, amanyĩw’a make mambĩlĩlya kũtũla iia sya nganũ, maendete.'),
('kam', 'MRK', 2, 24, 'Na Avalisi mamwĩa, Sisya, nĩkĩ mekwĩka mũthenya wa savato ũndũ ũtosana na ĩla mĩao?'),
('kam', 'MRK', 2, 25, 'Na amea, Mũtyaasoma nongĩ ũndũ Ndavĩtĩ wekie, yĩla waĩ na thĩna, na akĩw’a nzaa, we na ala maĩ nake?'),
('kam', 'MRK', 2, 26, 'Ũndũ wavotĩe nyũmbanĩ ya Ngai, yĩla Aviathalĩ waĩ mũthembi mũnene, na aya imũtũ ila syaiĩawa Ngai, naw’o ndwosana na ĩla mĩao kũĩwa nĩ mũndũ ate o athembi na anenga ala maĩ nake nao?'),
('kam', 'MRK', 2, 27, 'Na amea, Savato watwiwe nũndũ wa mũndũ, na ti mũndũ nũndũ wa savato:'),
('kam', 'MRK', 2, 28, 'kwondũ wa ũu Mwana wa mũndũ nĩ Mwĩaĩi o na wa savato.'),
('kam', 'MRK', 3, 1, 'Na alika ĩngĩ ĩsinakokenĩ; na kwaĩ mũndũ vo waĩ na kw’oko kwau.'),
('kam', 'MRK', 3, 2, 'Na mamũsyaĩĩsya, kana nũnũũmũvosya mũthenya wa savato: nĩ kana mamũvinganĩsye.'),
('kam', 'MRK', 3, 3, 'Na amwĩa ũla mũndũ waĩ na kw’oko kwau, Ũngama katĩ.'),
('kam', 'MRK', 3, 4, 'Na amakũlya, Nĩkwosana na ĩla mĩao kwĩka nesa mũthenya wa savato, kana kwĩka ũthũku? Kũtangĩĩa thayũ kana kũaa? Indĩ mavindya.'),
('kam', 'MRK', 3, 5, 'Na amasiangya na ũthatu, akĩw’a woo nũndũ wa wũmũ wa ngoo syoo, amwĩa ũla mũndũ, Tambũũkya kw’oko kwaku. Na atambũũkya; na kw’oko kwake kwavoa kwethĩwa kũima.'),
('kam', 'MRK', 3, 6, 'Na Avalisi maumaala, na oyu mambĩlĩlya kũsaman’ya vamwe na ala ma Elote ũndũ matonya kũmũaa.'),
('kam', 'MRK', 3, 7, 'Na Yesũ eesomola vau, we na amanyĩw’a make, athi ũkanganĩ: na ĩkomano ĩnene kuma Kalilii yamũatĩĩa: o na kuma Yutia,'),
('kam', 'MRK', 3, 8, 'na kuma Yelusaleme, na kuma Itumea, na mbee was Yolotani, na ngalĩ sya Tile na Sitoni, ĩkomano ĩnene, ya ala meew’a maũndũ manene ala wĩkaa, mooka vala ũĩ.'),
('kam', 'MRK', 3, 9, 'Na atavya amanyĩw’a make kana kakalawa kekale vakuvĩ nake nũndũ wa ĩkomano, yĩikese kũmũvivinya;'),
('kam', 'MRK', 3, 10, 'nũndũ nũvoetye aingĩ; na onthe ala maĩ na mothĩn’yo mamũvivinyanĩa nĩ kana mamũkiite.'),
('kam', 'MRK', 3, 11, 'Na maveva mavuku, o yĩla mamwona, mavalũka nthĩ mbee wake, na kũneena na wasya mũnene, makyasya, We nue Mwana wa Ngai.'),
('kam', 'MRK', 3, 12, 'Na amakindĩlĩla mũno maikamumbũle.'),
('kam', 'MRK', 3, 13, 'Na ambata kĩĩmanĩ, na ameta o ala wendete we mwene moke kwake; nao mooka vala ũĩ.'),
('kam', 'MRK', 3, 14, 'Na anyuva ĩkũmi na elĩ kana methĩwae vamwe nake, na nĩ kana amatũme kũtavan’ya,'),
('kam', 'MRK', 3, 15, 'na kwĩthĩwa na ũkũmũ wa kũvosya mowau na kumya ndaimoni;'),
('kam', 'MRK', 3, 16, 'na amũtw’ĩĩa Simoni syĩtwa yĩngĩ, Vetelo;'),
('kam', 'MRK', 3, 17, 'na Yakovo mwana was Sevetii, na Yoana mwana‐a‐inyia wa Yakovo; namo amatw’ĩĩa syĩtwa yĩngĩ, Voaneliki, nayo nĩ, Ana ma kĩtundumo:'),
('kam', 'MRK', 3, 18, 'na Andalea, na Vilivu, na Valitholomayo, na Mathayo, na Thoma, na Yakovo mwana wa Aluvaio, na Thatayo na Simoni Mũkanaani,'),
('kam', 'MRK', 3, 19, 'na Yutasi Isikalioti, ũla wamũvũnyanĩe. Na mathi nyũmbanĩ.'),
('kam', 'MRK', 3, 20, 'Na yĩla ĩkomano yoombana ĩngĩ, ũndũ mo mataatonya ũndũ o na kũya lĩu.'),
('kam', 'MRK', 3, 21, 'Na andũ ma kwoo meew’a ũu, maumaala mamũkwate: nũndũ masya, E na ndũũka.'),
('kam', 'MRK', 3, 22, 'Na aandĩki ala matheeie kuma Yelusaleme masya, E na Veelisevuli, na eumya ndaimoni na vinya wa mũnene wa ndaimoni.'),
('kam', 'MRK', 3, 23, 'Na ameta moke vala ũĩ, na amatavya na ngelekan’yo, Satani atonya ata kumya Satani?'),
('kam', 'MRK', 3, 24, 'Na ethĩwa ũsumbĩ nĩwĩvathanĩtye, ũsumbĩ ũsu ndũtonya kũũngama.'),
('kam', 'MRK', 3, 25, 'Na ethĩwa nyũmba nĩyĩvathanĩtye, nyũmba ĩsu ndĩtonya kũũngama.'),
('kam', 'MRK', 3, 26, 'Na ethĩwa Satanĩ nũkwĩyũkita mwene, na kwĩvathan’ya, ndakaũngama, ĩndĩ e na mũminũkĩlyo.'),
('kam', 'MRK', 3, 27, 'Ĩndĩ vai mũndũ ũtonya kũvota nyũmbanĩ ya ũla wĩ vinya, akamũvuta mĩio yake, atambĩte kũmwova ũla wĩ vinya; na ĩndĩ aitava ila syĩ nyũmbanĩ yake.'),
('kam', 'MRK', 3, 28, 'Nĩ w’o nĩngũmwĩa, Naĩ syonthe ĩkaekewa ana ma andũ, na moumano moo ala maumanaa namo:'),
('kam', 'MRK', 3, 29, 'ĩndĩ o ũla wĩmũuma Veva Mũtheu nde ĩndĩ ũkaekewa, ĩndĩ e na ĩvĩtyo ya tene na tene;'),
('kam', 'MRK', 3, 30, 'nũndũ masya, E na veva mũvuku.'),
('kam', 'MRK', 3, 31, 'Na inyia wake na ana‐a‐inyia make mooka; na maũngama nza, na mamũtũmana maimwĩta.'),
('kam', 'MRK', 3, 32, 'Na ikomano yekala nthĩ yĩmũthyũlũlũkĩte; na mamwĩa, Sisya, mwenyu na ana‐a‐mwenyu me nza na nĩmeũkũmantha.'),
('kam', 'MRK', 3, 33, 'Na amasũngĩa, na asya, Mwaitũ na ana‐a‐ia naaũ?'),
('kam', 'MRK', 3, 34, 'Na amasiangya ala mekalĩte nthĩ mamũthyũlũlũkite, na asya, Sisyai, mwaitũ na ana‐a‐ia!'),
('kam', 'MRK', 3, 35, 'Nĩkwĩthĩwa o ũla wĩkaa kwenda kwa Ngai, ũsu nĩwe mwana‐a‐ia, na mwĩĩtu‐a‐ia, na mwaitũ.'),
('kam', 'MRK', 4, 1, 'Na ambĩlĩlya ĩngĩ kũmanyĩsya e ũtee wa ũkanga. Na ĩkomano ĩnene mũno yamũmbanĩa, na ũndũ wa ũu alika ngalawanĩ, na ekala vu ũkanganĩ; na ĩkomano yonthe yekala nthĩ yĩ ũtee wa ũkanga.'),
('kam', 'MRK', 4, 2, 'Na amamanyĩsya maũndũ maingi na ngelekan’yo, na ũmanyĩsyonĩ wake amea,'),
('kam', 'MRK', 4, 3, 'Ĩthukĩĩsyei: mũvuĩi nĩwaendie kũvuĩa:'),
('kam', 'MRK', 4, 4, 'na kweethĩwa akĩvuĩa, mbeke imwe syavalũka ũtee wa nzĩa, na nyũnyi syooka syaiya.'),
('kam', 'MRK', 4, 5, 'Na ingĩ syavalũka mavianĩ, vala ve mũthanga mũnini; na oyu syamea, nĩkwĩthĩwa ityaĩ na mũthanga mũliku:'),
('kam', 'MRK', 4, 6, 'na syũa yaaa, syavova; na nĩkwĩthĩwa ityaĩ na mĩi, syooma.'),
('kam', 'MRK', 4, 7, 'Na ingĩ syavalũka mĩw’anĩ, na mĩw’a yeana na yainyita, na syaaa mũsyaĩe.'),
('kam', 'MRK', 4, 8, 'Na ingĩ syavalũka mũthanganĩ mũseo, na syasyaa, ikĩmea na kwĩana; na syasyaa, imwe mĩongo ĩtatũ, na imwe mĩongo thanthatũ, na imwe ĩana.'),
('kam', 'MRK', 4, 9, 'Na asya, Ũla wĩ matũ ma kwĩw’a, nĩew’e.'),
('kam', 'MRK', 4, 10, 'Na yĩla waĩ weka, ala mamũthyũlũlũkĩte, vamwe na ala ĩkũmi na elĩ, mamũkũlya ũndũ wa ĩla ngelekan’yo.'),
('kam', 'MRK', 4, 11, 'Na amea, Inyw’ĩ mũnengetwe kũmanya nzama ya ũsumbĩ wa Ngai: ĩndĩ kwa ala me ũtee, maũndũ onthe nĩmekawa na ngelekan’yo;'),
('kam', 'MRK', 4, 12, 'kana kũsisya nĩmeũsisya, na matikwona, na kwĩw’a nĩmekwĩw’a, na matiũmanya; maikese kwĩalyũla, na makĩekewa.'),
('kam', 'MRK', 4, 13, 'Na amakũlya, Mũtyĩsĩ ngelekan’yo ĩno? Mũkamanya ata ĩndĩ ngelekan’yo syonthe?'),
('kam', 'MRK', 4, 14, 'Ũla mũvũĩi avuĩaa ndeto.'),
('kam', 'MRK', 4, 15, 'Aa nĩo ala me ũtee wa nzĩa, vala ndeto yavuĩiwe; nao meew’a, oyu Satani akyũka na akyumya ĩla ndeto ĩvuĩiwe ngooni syoo.'),
('kam', 'MRK', 4, 16, 'Na ala mavuĩiwe mavianĩ no ta ũu, ala, yĩla meew’a ĩla ndeto, nĩmeũmyosa oyu na ũtanu;'),
('kam', 'MRK', 4, 17, 'na mati na mĩi nthĩnĩ woo, ĩndĩ mekala ĩvinda ĩnini; na ĩtina, yĩla thĩna kana ũnyamao wookĩla kwondũ wa ĩla ndeto, oyu mailulutĩka.'),
('kam', 'MRK', 4, 18, 'Na angĩ ala mavuĩiwe mĩw’anĩ, nĩ ala meew’a ĩla ndeto,'),
('kam', 'MRK', 4, 19, 'na mawĩmakĩo ma nthĩ, na ũkengani wa ũthwii, na ĩtomo ya syĩndũ ingĩ makĩlika, na kũnyita ĩla ndeto, na ĩilea ũsyaa.'),
('kam', 'MRK', 4, 20, 'Na asu ala mavuĩiwe mũthanganĩ mũseo nĩ ala mekwĩw’a ĩla ndeto, na makimyosa, na makĩsyaa, amwe mĩongo ĩtatũ, na angĩ mĩongo thanthatũ, na angĩ ĩana.'),
('kam', 'MRK', 4, 21, 'Na amakũlya, Taa nũetawe nĩ kana wiwe ungu wa ĩmisi, kana ungu wa ũkomo? Ti kana wiwe vala vatũlu?'),
('kam', 'MRK', 4, 22, 'Nĩkwĩthĩwa kũti ũndũ ũvithe, ũtakavuanw’a; o na kũti kĩmbithĩ, kĩtakaumbũka ũtheinĩ.'),
('kam', 'MRK', 4, 23, 'Ethĩwa ve mũndũ wĩ matũ ma kwĩw’a, nĩew’e.'),
('kam', 'MRK', 4, 24, 'Na amea, Ĩsũvĩei ũndũ mũkwĩw’a: kĩthimo kĩla mũthimaa no kyo mũkathimĩwa; na nĩmũkongeleelwa.'),
('kam', 'MRK', 4, 25, 'Nũndũ ũla wĩ na kĩndũ, ũsu akanengwa; na ũla ũtaĩ, ũsu akavenwa o na kĩla wĩ nakyo.'),
('kam', 'MRK', 4, 26, 'Na amea, Ũsumbĩ wa Ngai nĩ ta ũũ, ta mũndũ wavandie mbeũ mũthanganĩ;'),
('kam', 'MRK', 4, 27, 'na akĩkoma na akĩamũka, ũtukũ na mũthenya, na ila mbeũ ikamea na kwĩana ũndũ ũtesi.'),
('kam', 'MRK', 4, 28, 'Nthĩ ĩsyaaa ũndũ wayo; mbee nĩ ĩtũ, na mũatĩĩa nĩ kĩia, na mũminũkĩlyo nĩ mbeke mbusũu kĩianĩ.'),
('kam', 'MRK', 4, 29, 'Ĩndĩ lĩu wooma, oyu akyosa kavyũ, nũndũ ngetha nĩ mbiku.'),
('kam', 'MRK', 4, 30, 'Nake asya, Twĩũvw’anan’ya na kyaũ ũsumbĩ wa Ngai? Kana twĩũelekan’ya na kĩ?'),
('kam', 'MRK', 4, 31, 'Ũilyĩ ta mbeke ya kalatali ĩla yavandwa nthĩ, o na kau nĩ nini kwĩ mbeũ syonthe sya nthĩ,'),
('kam', 'MRK', 4, 32, 'ĩndĩ yavandwa nĩyĩanaa, ĩkethĩwa nene mbee wa nyũnyi syonthe, na kũasavya mbonge nene; ũndũ nyũnyi sya yayaya itonya kwĩkala muunyĩnĩ wayo.'),
('kam', 'MRK', 4, 33, 'Na amatavasya ĩla ndeto na ngelekan’yo nyingĩ ta isu, o tondũ maĩ matonya kũmĩw’a;'),
('kam', 'MRK', 4, 34, 'na vate ngelekan’yo ndaaneena nao: ĩndĩ amamanyĩasya amanyĩw’a make maũndũ onthe me nzama.'),
('kam', 'MRK', 4, 35, 'Na mũthenya ũsu, kwavika wĩoo, amea, Tũingei mũingo ũla ũngĩ.'),
('kam', 'MRK', 4, 36, 'Na matia ĩkomano, athi nake, e o ngalawanĩ ĩsu. Na ngalawa ingĩ syaĩ vamwe nake.'),
('kam', 'MRK', 4, 37, 'Na kwookĩla kĩuutani kĩnene kya kĩseve, na itulumo syakũnanga ngalawa, o na ngalawa yambĩlĩlya kusũa manzĩ.'),
('kam', 'MRK', 4, 38, 'Nake mwene aĩ ĩtina akomete mũtonĩ: na mamũamũkya, mamwĩa, Mũmanyĩsya, ndwĩ na ũndũ tũkyaa?'),
('kam', 'MRK', 4, 39, 'Na aamũka, na akan’ya kĩseve, na atavya ũkanga, Usya, kilya. Na kĩseve kyausya, na kwaya ũuu mũnene.'),
('kam', 'MRK', 4, 40, 'Na amakũlya, Nĩkĩ mwĩ na w’ĩa? Mũtinamba kwĩthĩwa na mũĩkĩĩo?'),
('kam', 'MRK', 4, 41, 'Na makwatwa nĩ w’ĩa mũnene, na maneenan’ya ene kwa ene, Ũũ nũũ ĩndĩ, ũndũ o na kĩseve na ũkanga niũmwĩw’a?'),
('kam', 'MRK', 5, 1, 'Na mainga mũingo ũla ũngi wa ũkanga, mavika nthĩ ya Akelasene.'),
('kam', 'MRK', 5, 2, 'Na auma ngalawanĩ, oyu mũndũ akomana nake, aumite mbũanĩ, e na veva mũvuku,'),
('kam', 'MRK', 5, 3, 'ũla waĩ na wĩkalo mbũanĩ: na vatyaĩ mũndũ waatonya kũmwova, aiee, o na mũnyololo;'),
('kam', 'MRK', 5, 4, 'nĩkwĩthĩwa nĩwovawa mavinda maingĩ na mbĩngũ na mĩnyololo, na mĩnyololo nĩyatusangawa nĩwe, na mbĩngũ nĩsyatũlangawa ilungu, na vatyaĩ mũndũ waĩ na vinya wa kũmũvoovya.'),
('kam', 'MRK', 5, 5, 'Na mavinda onthe, mũthenya na ũtukũ, mbũanĩ na iĩmanĩ, ekalaa akĩlonzan’ya na kwĩtemanga na mavia.'),
('kam', 'MRK', 5, 6, 'Na amwona Yesũ e kũasa, asemba na amũthaitha;'),
('kam', 'MRK', 5, 7, 'na aneena na wasya mũnene, akyasya, Nĩ ũndũ naku wa kĩ, we Yesũ, Mwana wa Ngai Ula Wĩ Ĩũlũ wa Onthe? Nĩngũkwĩavĩthya kwa Ngai, ndũkanyamasye.'),
('kam', 'MRK', 5, 8, 'Nũndũ amwĩie, Uma we, veva mũvuku, mũndũnĩ ũũ.'),
('kam', 'MRK', 5, 9, 'Nake amũkũlya, Syĩtwa yaku nue ata? Amwĩa, Syĩtwa yakwa, ninyie Nguthu; nũndũ twi aingĩ.'),
('kam', 'MRK', 5, 10, 'Na amwĩsũva mũno ndakamalũngye maume nthĩ ĩsu.'),
('kam', 'MRK', 5, 11, 'Na vau nguumo wa kĩĩma kwaĩ ĩĩthya ya ngũlũe nyingĩ ikĩya.'),
('kam', 'MRK', 5, 12, 'Nao mamwĩsũva, makyasya, Twĩe tũende ĩĩthyanĩ ya ngũlũe, tũlike nthĩnĩ wasyo.'),
('kam', 'MRK', 5, 13, 'Na amanenga ũthei. Na ala maveva mavuku mauma na malika ngũlũenĩ: na yĩla ĩĩthya ya ngũlũe yatheea kĩvaũũkonĩ yĩsembete, yalika ũkanganĩ, ũtalo wasyo nĩ ta ngili ilĩ; na syakw’ĩa ũkanganĩ.'),
('kam', 'MRK', 5, 14, 'Na ala maĩthasya makĩa, na matavan’ya ũvoo ndũanĩ na ndee. Na andũ mauma mone ũndũ ũla wĩkĩkie.'),
('kam', 'MRK', 5, 15, 'Na mooka vala ve Yesũ, na moona ũla eĩkwatĩtwe nĩ ndaimoni ailyĩ nthĩ, evw’ĩkĩte ngũa, e na kĩlĩko, nake nĩwe ũla eĩ na ila nguthu: na makĩa.'),
('kam', 'MRK', 5, 16, 'Na ala moonie ũndũ ũsu, mamatavya ũndũ wĩkiwe ũsu ũla eĩkwatĩtwe nĩ ndaimoni, na ũvoo wa ila ngũlũe.'),
('kam', 'MRK', 5, 17, 'Na mambĩlĩlya kũmwĩsũva Yesũ aume mĩvakanĩ yoo.'),
('kam', 'MRK', 5, 18, 'Na ailika ngalawanĩ, ũla eĩkwatĩtwe nĩ ndaimonĩ amwĩsũva ekalan’ye nake.'),
('kam', 'MRK', 5, 19, 'Na Yesũ amũvata, ĩndĩ amwĩa, Enda nyũmba kwaku kwa andũ maku, ũkamatavye maũndũ ũndũ manenevete ala Mwĩaĩi ũkwĩkie, na ũndũ ũkwĩw’ĩie tei.'),
('kam', 'MRK', 5, 20, 'Na akwata nzĩa athi, na ambĩlĩya kũtavan’ya ku Ndekavoli maũndũ ũndũ manenevete ala Yesũ ũmwĩkie: na andũ onthe maseng’a'),
('kam', 'MRK', 5, 21, 'Na Yesũ ainganĩsya ĩngĩ na ngalawa kũvika mũingo ũla ũngĩ, ĩkomano ĩnene yoombana vala ũĩ; nake aĩ ũtee wa ũkanga.'),
('kam', 'MRK', 5, 22, 'Na kwooka ũmwe wa anene ma ĩsinakoke, syĩtwa yake eetawa Yailu; na amwona, avalũka maũũnĩ make,'),
('kam', 'MRK', 5, 23, 'na amwĩsũva mũno, akyasya, Kelitu kakwa nĩkeũkw’a: nĩngũũvoya wũke ũkakailĩĩle moko maku, kavoe kethĩwe thayũ.'),
('kam', 'MRK', 5, 24, 'Na aendan’ya nake: na ikomano ĩnene yamũatĩĩa na yamũvivinya.'),
('kam', 'MRK', 5, 25, 'Na kwai mũndũ mũka ũla waumawa nĩ nthakame ĩvinda ya myaka ĩkũmi na ĩlĩ,'),
('kam', 'MRK', 5, 26, 'na anyamaaw’a mũno nĩ aiiti aingĩ, na aanangĩte syonthe ila waĩ nasyo, na ndaĩ kavaa o na vanini, ĩndĩ aendeea na kũwaa,'),
('kam', 'MRK', 5, 27, 'na eew’a ũvoo wa Yesũ, alikĩla nguthunĩ e ĩtina, na akiita ngua yake.'),
('kam', 'MRK', 5, 28, 'Nũndũ aisye, Nakiita o na ethĩwa no ngũa syake, nĩngũvoa nĩthĩwe nĩ mũima.'),
('kam', 'MRK', 5, 29, 'Na oyu nthongo ya nthakame yake yang’ala; na eew’a mwĩĩnĩ wake kana nĩwavoa ũthĩn’yo ũsu wake.'),
('kam', 'MRK', 5, 30, 'Na oyu Yesũ amanya nthĩnĩ wake kana vinya nĩwauma kwake, eethyũũa e nguthunĩ, na akũlya, Nũũ ũla wangiita ngũa syakwa?'),
('kam', 'MRK', 5, 31, 'Na amanyĩw’a make mamwĩa, Nũkwona ũndũ ĩkomano yĩũkũvivinya, naku wikũlya, Nũũ ũla wangiita?'),
('kam', 'MRK', 5, 32, 'Na asisya ngalĩ syonthe nĩ kana one ũla weka ũndũ ũsu.'),
('kam', 'MRK', 5, 33, 'Na ũla mũndũ mũka aĩkĩa na kũtetema, amanya ũndũ wekwa, ooka na avalũka nthĩ mbee wake, na amũtavya w’o w’onthe.'),
('kam', 'MRK', 5, 34, 'Nake amwĩa, Mwĩĩtu, mũĩkĩĩo waku nĩwakũvosya; thi na ũvoo, wĩthĩwe wĩ mũima, ũte na ũthĩn’yo waku.'),
('kam', 'MRK', 5, 35, 'Akĩneena, kwooka andũ kuma kwa mũnene wa ĩsinakoke, makyasya, Mwĩĩtu waku nĩwakw’a: yu wĩnyamaĩsya Mũmanyĩsya kĩ?'),
('kam', 'MRK', 5, 36, 'Indĩ Yesũ eew’a ndeto ĩla yaneenwa, amwia ũla mũnene wa ĩsinakoke, Ndũkakĩe, ĩkĩĩa tũ.'),
('kam', 'MRK', 5, 37, 'Na ndaaĩtĩkĩla mũndũ aendan’ye nake, ate o Vetelo, na Yakovo, na Yoana mwana‐a‐inyia wa Yakovo.'),
('kam', 'MRK', 5, 38, 'Na mavika nyũmba ya ũla mũnene wa ĩsinakoke; na oona kĩtuu kĩnene, na andũ aingĩ makĩĩa na kũmeta mũno.'),
('kam', 'MRK', 5, 39, 'Na avota nthĩnĩ, amakũlya, Nĩkĩ mũũlonzan’ya na kũĩa? Kana ti kakw’ũ ĩndĩ nĩkakomete.'),
('kam', 'MRK', 5, 40, 'Nao mamũthekeea mũno. Indĩ we, amaumaalya onthe nza, athi na ĩthe wa kala kana na inyia wako, na ala maĩ vamwe nake, avota namo nthĩnĩ vala ve kala kana.'),
('kam', 'MRK', 5, 41, 'Na akwata kana kw’oko, akea, Talĩtha kumi; ũalyũlo wa ndeto nĩ, Kelĩtu, nĩkwĩa, Ũkĩla.'),
('kam', 'MRK', 5, 42, 'Na oyu kala kelĩtu kaũngama, kathi na maũũ: nũndũ kaĩ ka myaka ĩkũmi na ĩlĩ. Na oyu maseng’a na ũseng’yo mũnene.'),
('kam', 'MRK', 5, 43, 'Na amavata mũno mũndũ ndakamanye ũndũ ũsu: na eeaa kanengwe kya ũya.'),
('kam', 'MRK', 6, 1, 'Na auma vo; na athi nthĩ ĩla ya kwoo; na amanyĩw’a make mamũvikĩla.'),
('kam', 'MRK', 6, 2, 'Na mũthenya wa savato wavĩka, ambĩlĩlya kũmanyĩsya ĩsinakokenĩ: na aingĩ makĩmwĩw’a maseng’a, makyasya, Mũndũ ũũ aumĩtye maũndũ aa va? Na, Ũĩ ũũ nĩ mwaũ ũla ũnengetwe mũndũ ũũ, o na mavinya aa mekwĩkwa na moko make?'),
('kam', 'MRK', 6, 3, 'Ũũ ti ũla mũseũvya wa mbwaũ, mwana wa Meli, na mwana‐a‐inyia wa Yakovo, na Yose, na Yutasi, na Simoni? Na eĩtu‐a‐inyia mati kũũ kwitũ? Na malulutĩkw’a nĩwe.'),
('kam', 'MRK', 6, 4, 'Na Yesũ amea, Mwathani ndalea kwĩthĩwa na ndaĩa, ate o nthĩ yake mwene, na mbaĩnĩ yake, na nyũmbanĩ yake.'),
('kam', 'MRK', 6, 5, 'Na ndaatonya kwĩka wĩko wĩ vinya vo, ate o kũmailĩĩla moko make andũ awau avũthũ, na kũmavosya.'),
('kam', 'MRK', 6, 6, 'Na aseng’a nũndũ wa kũlea kwĩtĩkĩla kwoo. Na anganga mĩsyĩ akĩmanyĩsya.'),
('kam', 'MRK', 6, 7, 'Na ameta kwake ala ĩkũmi na elĩ, na ambĩlĩlya kũmatũma elĩ na elĩ; na amanenga ũkũmũ ĩũlũ wa maveva mavuku;'),
('kam', 'MRK', 6, 8, 'na ameaĩa maikakue kĩndũ kya nzĩanĩ, ate o ndata yoka; vate kĩmũtũ, kana mũvuko, kana mbesa ngusunĩ syoo;'),
('kam', 'MRK', 6, 9, 'ĩndĩ mekĩe iatũ: na asya, Mũikekĩe itonyeo ilĩ.'),
('kam', 'MRK', 6, 10, 'Na amea, O vala mwĩvota nyũmba, mwĩĩkala vo kũvika o yĩla mwĩvauma.'),
('kam', 'MRK', 6, 11, 'Na o ũla ũteũmũthokya na kũmwĩw’a, mũkyũma vo, tuangai kĩtoo kĩla kĩ maũũnĩ menyũ wĩthĩwe ũkũsĩ kwoo.'),
('kam', 'MRK', 6, 12, 'Na maumaala mathi, na matavan’ya kana andũ maalyũle ngoo.'),
('kam', 'MRK', 6, 13, 'Na maumya ndaimoni nyingĩ, na makiitya andũ aingĩ mauta ala maĩ awau, na mamavosya.'),
('kam', 'MRK', 6, 14, 'Na mũsumbĩ Elote eew’a ũvoo ũsu; nũndũ syĩtwa ya Yesũ nĩyeesĩkĩwe: na asya, Yoana ũla Mũvatisi nũthayũũkĩte kuma akw’ũnĩ, na kwondũ wa ũu mavinya aa metethya wĩa nthĩnĩ wake.'),
('kam', 'MRK', 6, 15, 'Ĩndĩ angĩ masya, Nĩ Eliya. Na angĩ masya, Nĩ mwathanĩ, o ta ũmwe wa athani.'),
('kam', 'MRK', 6, 16, 'Ĩndĩ Elote eew’a asya, Yoana ũla namũtilile mũtwe, nĩwe ũthayũũkĩte.'),
('kam', 'MRK', 6, 17, 'Nũndũ Elote mwene aĩ anatũma andũ na akamũkwata Yoana, akamwova kolokolonĩ kwondũ wa Elotia, mũka wa mwana‐a‐inyia wake Vilivu; nũndũ nĩwamũtwaĩte.'),
('kam', 'MRK', 6, 18, 'Nũndũ Yoana amũtavisye Elote, Kũtyosana na mĩao we kwĩthĩwa na mũka wa mwana‐a‐mwenyu.'),
('kam', 'MRK', 6, 19, 'Na ĩndĩ Elotia aĩ na ũthũ nake, na nĩwendaa kũmũaa; na ndaatonya;'),
('kam', 'MRK', 6, 20, 'nũndũ Elote nĩwamũkĩaa Yoana, nĩkwĩthĩwa nĩwesĩ kana nĩ mũndũ mũlũngalũ na mũtheu, na nĩwamũsũvĩaa. Na amwĩw’a nĩwasaanĩaw’a nĩ maũndũ maingĩ; ĩndĩ amwĩthukĩĩasya na mũyo.'),
('kam', 'MRK', 6, 21, 'Na mũthenya waĩle wavika, Elote amavokea mboka ya mũthenya wa kũsyawa kwake, na ameta eaĩi ma kwake, na maovisa ma asikalĩ, na andũ me nguma ma Kalilii;'),
('kam', 'MRK', 6, 22, 'na mwĩĩtu wa Elotia ũsu alika na asũnga, amwendeesya Elote na ala mailyĩ lĩunĩ vamwe nake; na mũsumbĩ amwĩa ũla mwĩĩtu, Mbĩtya o kĩla ũkwenda na nĩngũũnenga.'),
('kam', 'MRK', 6, 23, 'Nake eevĩta, amwĩa, O kĩla wĩmbĩtya ngakũnenga, kũvika nyunzu ya ũsumbĩ wakwa.'),
('kam', 'MRK', 6, 24, 'Na aumaala, amũkũlya inyia wake, Nĩmwĩtya kyaũ? Na asya, Mũtwe wa Yoana ũla Mũvatisi.'),
('kam', 'MRK', 6, 25, 'Na oyu alika na mĩtũkĩ vala ve mũsumbĩ, amwĩtya, akyasya, Nĩngwenda ũnenge oyu mũtwe wa Yoana ũla Mũvatisi, wĩ ĩsaaninĩ.'),
('kam', 'MRK', 6, 26, 'Na mũsumbĩ eew’a woo mũno; ĩndĩ kwondũ wa mawĩvĩto make, na kwondũ wa ala mailyĩ lĩunĩ, ndaaĩtĩkĩla kũmũvata.'),
('kam', 'MRK', 6, 27, 'Na oyu mũsũmbĩ atũma mũsikalĩ ũmwe wa asũvĩi make, na eeaa mũtwe wake ũetwe: na athi amũtila mũtwe, e kolokolonĩ,'),
('kam', 'MRK', 6, 28, 'na aete mũtwe wake wĩ ĩsaaninĩ, oonenga ũla mwĩĩtu; na mwĩĩtu anenga inyia wake.'),
('kam', 'MRK', 6, 29, 'Na amanyĩw’a ma Yoana meew’a ũvoo, mooka moosa kimba kyake, mathika mbũanĩ.'),
('kam', 'MRK', 6, 30, 'Na atũmwa mamũmbanĩa Yesũ; na mamũtavya maũndũ onthe, o ala meekie, na ala mamanyĩisye.'),
('kam', 'MRK', 6, 31, 'Na amea, Ũkai inyw’ĩ mwĩ inyw’oka vandũ vate andũ, mũthũmũe vanini. Nũndũ kwaĩ aingĩ mokĩte na maendete, na matyaĩ na ũthei o na wa kũya.'),
('kam', 'MRK', 6, 32, 'Na mathi ngalawanĩ me oka vandũ vate andũ,'),
('kam', 'MRK', 6, 33, 'Na andũ mamona maendete, na aingĩ mamamanya, na masemba vo na nyaĩĩ maũmĩte ndũanĩ syonthe, na mamba ũvika.'),
('kam', 'MRK', 6, 34, 'Na Yesũ aũma ngalawanĩ oona ĩkomano ĩnene, na amew’ĩa andũ tei, nĩkwĩthĩwa mailyi ta malondũ mate na mũĩthi: na ambĩlĩlya kũmamanyĩsya maũndũ maingĩ.'),
('kam', 'MRK', 6, 35, 'Na yĩla kwatwie kũtuka, amanyĩw’a make mooka vala ũĩ, mamwĩa, Vaa tũĩ nĩ weũnĩ, na nĩkũtwie kũtuka;'),
('kam', 'MRK', 6, 36, 'ũmbũũkya aa, nĩ kana mathi ndee na mĩsyĩ kũũ na kũũ makethooee liu.'),
('kam', 'MRK', 6, 37, 'Indĩ asũngĩa, amea, Manengei lĩu e inyw’ĩ. Na mamũkũlya, Tũende tũkathooe imũtũ sya silingi maana elĩ, tũkamanenge maye?'),
('kam', 'MRK', 6, 38, 'Na amasũngĩa, Mwĩ na imũtũ syĩana? Endai mũsisye. Na mamanya masya, Nĩ itano, na makũyũ elĩ.'),
('kam', 'MRK', 6, 39, 'Na ameaĩa mekalye onthe nthĩ nyekinĩ nziũ, ngũthũ na nguthu.'),
('kam', 'MRK', 6, 40, 'Na mekala nthĩ mĩkw’ĩlĩ, kũmwe ĩana na kũngĩ mĩongo ĩtano.'),
('kam', 'MRK', 6, 41, 'Na oosa ila imũtũ itano na ala makũyũ elĩ, na ang’elela ĩtunĩ aithima na aitilanga ila imũtũ; na anenga amanyĩw’a mamaaĩe; na ala makũyũ elĩ amaaĩa onthe.'),
('kam', 'MRK', 6, 42, 'Na onthe maya mavũna.'),
('kam', 'MRK', 6, 43, 'Na moosa ilungu ila ndile, ikavũ ĩkũmi an ilĩ syausũa, na sya makũyũ namo.'),
('kam', 'MRK', 6, 44, 'Na ala maĩe ila imũtũ maĩ aũme ngili itano.'),
('kam', 'MRK', 6, 45, 'Na oyu amathing’ĩĩsya amanyĩw’a make malike ngalawanĩ, mambe kũinganĩsya mũingo ũla ũngĩ, kũvika Vethisaita, ĩvinda yĩla we mwene ũnũkũmbũũkya makomano.'),
('kam', 'MRK', 6, 46, 'Na amatiĩa ũvoo athi kĩĩmanĩ kũvoya.'),
('kam', 'MRK', 6, 47, 'Na kwavika wĩoo ĩla ngalawa yaĩ ũkanganĩ katĩ, nake aĩ weka ku mwaĩo.'),
('kam', 'MRK', 6, 48, 'Na amona makĩthĩna nĩ ũtwaa ngalawa, nũndũ kĩseve nĩkyamathaũĩtye, ta ũsyaĩĩsyo wa kana wa ũtũkũ athi vala maĩ, akinyĩle ũkanganĩ ĩũlũ; na enda kũmavĩta:'),
('kam', 'MRK', 6, 49, 'ĩndĩ mo mamwona akinyĩle ũkanganĩ ĩũlũ, matalĩthya kana nĩ ĩimũ, na makaya;'),
('kam', 'MRK', 6, 50, 'nũndũ onthe nĩmamwonie, na maũũya. Ĩndĩ oyu aneena nao, na amea, Ĩthĩwai na ũnyiau: ninyie; mũikakĩe.'),
('kam', 'MRK', 6, 51, 'Na ambata vala maĩ ngalawanĩ; na kĩseve kyakilya: na maseng’a mũno nthĩnĩ woo;'),
('kam', 'MRK', 6, 52, 'nũndũ maiaamanya ũndũ wa ila imũtũ, ĩndĩ ngoo syoo syaĩ nyũmũ.'),
('kam', 'MRK', 6, 53, 'Na mainga mavika nthĩ ya Kenesaleti, na moova ngalawa ũtee wa ũkanga.'),
('kam', 'MRK', 6, 54, 'Na mauma ngalawanĩ, oyu andũ mamũmanya,'),
('kam', 'MRK', 6, 55, 'na masemba makoman’ya nthĩ ĩsu yonthe, na mambĩlĩlya kũkua na mokomo moo ala maĩ awau, mamaete vala meewie ũĩ.'),
('kam', 'MRK', 6, 56, 'Na kw’onthe kũla wavotie, mĩsyĩ, kana ndũanĩ kana ndee, mamaia ala awau ing’ang’anĩ, na mamwĩsũva makiite o na ethĩwa no ũtiivo wa ngũa yaye; nao onthe ala mamũkiitie mavow’a vyũ.'),
('kam', 'MRK', 7, 1, 'Na Avalisi na amwe ma aandĩki ala maumĩte Yelusaleme mamũmbanĩa,'),
('kam', 'MRK', 7, 2, 'na moona amwe ma amanyĩw’a make makĩya lĩu woo na nzaa mbuku, nasyo nĩ ila ite nthambye.'),
('kam', 'MRK', 7, 3, '(Nũndũ Avalisi na Ayuti onthe, makĩkwata mokũũ ma atumĩa, matiĩsaa matathambĩte nzaa mũno;'),
('kam', 'MRK', 7, 4, 'na mauma kĩng’ang’anĩ, matathambĩte matiya; na ve maũndũ angĩ maingĩ ala makothaa kũkwata, ta kũthambya ikombe, na mbisũ, na mĩio ya ũthũku.)'),
('kam', 'MRK', 7, 5, 'Na ĩndĩ ala Avalisi na aandĩki mamũkũlya, Nĩkĩ amanyĩw’a maku matikinyaa kwĩanana na mokũũ ma atumĩa, ĩndĩ nĩmaĩsaa lĩu woo na nzaa mbuku?'),
('kam', 'MRK', 7, 6, 'Na amea, Isaia nĩwathanie nesa ũndũ wenyu angangan’ya, o ũndũ kũandĩkĩtwe, Andũ aa nĩmandaĩaa na ilomo syoo, Ĩndĩ ngoo syoo syĩ kũasa nakwa. Ĩndĩ manthaithaa ũthaithi wa mana,'),
('kam', 'MRK', 7, 7, 'Makĩmanyĩsya momanyĩsyo, nao nĩ mawĩaĩo ma andũ.'),
('kam', 'MRK', 7, 8, 'Nĩmũtiaa mĩao ya Ngai, na kũkwataa mũno mokũũ ma andũ, ta kũthambya mbisũ na ikombe: na maũndũ maingĩ ta asu nĩmwĩkaa.'),
('kam', 'MRK', 7, 9, 'Na amea, Nĩmũleaa vyũ ĩla mĩao ya Ngai nĩ kana mwĩkalae na mokũũ menyu,'),
('kam', 'MRK', 7, 10, 'Nũndũ Mose aisye, Taĩa au na mwenyu; na, Ũla ũnũkũuma ĩthe kana nyinyia, nakw’e:'),
('kam', 'MRK', 7, 11, 'ĩndĩ inyw’ĩ mwĩasya, Ethĩwa mũndũ akamwĩa ĩthe kana nyinyia, Kĩndũ o na kĩva kĩla naĩ ndonya ũkũnenga nĩ Kolivani, naw’o nĩ kwasya, Nĩkĩnengetwe Ngai;'),
('kam', 'MRK', 7, 12, 'inyw’ĩ mũtiĩtĩkĩla ĩngĩ akamũtethya ĩthe kana nyinyia na ũndũ;'),
('kam', 'MRK', 7, 13, 'nĩmũkwananga ndeto ya Ngai kwondũ wa mokũũ menyu, ala mũtianĩaa: na maũndũ maingĩ ta asũ nĩmwĩkaa.'),
('kam', 'MRK', 7, 14, 'Na ayĩta ĩkomano yũke vala ũi ĩngĩ, na ayĩa, Mbĩthukĩĩsyai inyw’onthe, mũmanye:'),
('kam', 'MRK', 7, 15, 'vai kĩndũ kĩ ũtee wa mũndũ kĩla kĩkĩlika nthĩni wake kĩtonya kũmũvukya; ĩndĩ maũndũ ala maumaa nthĩnĩ wake, nĩmo mamũvukasya ũla mũndũ.'),
('kam', 'MRK', 7, 16, '(Ethĩwa mũndũ e na matũ ma kwĩw’a, nĩew’e.)'),
('kam', 'MRK', 7, 17, 'Na atia ĩkomano, alika nyũmba, amanyĩw’a make mamũkũlya ũndũ wa ĩla ngelekan’yo.'),
('kam', 'MRK', 7, 18, 'Na amea, Inyw’ĩ nenyu mũti na ũmanyi? Mũtiũmanya kana o kĩla kĩ ũtee wa mũndũ kyamũlika mũndũ, kĩitonya kũmũvukya;'),
('kam', 'MRK', 7, 19, 'nũndũ kĩivotaa ngoonĩ, ĩndĩ ĩvunĩ yake, na nĩkĩũmĩwa? Asya ũu, atheisye sya ũya syonthe.'),
('kam', 'MRK', 7, 20, 'Na asya, Ũndũ ũla wumaa nthĩnĩ wa mũndũ, nĩw’o ũvukasya mũndũ.'),
('kam', 'MRK', 7, 21, 'Nũndũ kuma nthĩnĩ, ngoonĩ sya andũ, nĩkw’o kumaa malilikano mathũku, mawathavu, mong’ei, maũaani, molaalaĩ,'),
('kam', 'MRK', 7, 22, 'mawendi, mothũku, mokengani, mĩmeo mĩthũku, itho ĩthũku, kũumana, wĩyĩan’yo, ũtumanu:'),
('kam', 'MRK', 7, 23, 'maũndũ asu onthe mathũku maumaa nthĩnĩ, na nĩmo mavũkasya mũndũ.'),
('kam', 'MRK', 7, 24, 'Na auma vo, athi mĩvakanĩ ya Tile na Sitoni. Na avota nyũmba na ndendaa ũmanyĩke nĩ mũndũ; na ndaatonya kwĩvitha.'),
('kam', 'MRK', 7, 25, 'Ĩndĩ oyu mũndũ mũka, ũla kelĩtu kake kaĩ na veva mũvuku, eew’a ũvoo wake, ooka na amũvalũkĩla maũũnĩ make.'),
('kam', 'MRK', 7, 26, 'Na ũla mũndũ mũka aĩ Mũkiliki ũko wa Silovonike. Na amwĩsũva amumĩsye mwĩĩtu wake ĩla ndaimoni.'),
('kam', 'MRK', 7, 27, 'Na amwĩa, Ieke syana syambe ũvũna: nũndũ ti ũseo kwosa lĩu wa syana na kũwĩkĩsya ngitĩ.'),
('kam', 'MRK', 7, 28, 'Ĩndĩ we asũngĩa, amwĩa, Ĩĩ, Mwĩaĩi; ĩndĩ o na ngitĩ syĩ ungu wa mesa niĩsaa tũlungu tũla tũũvalũkangw’a nĩ syana.'),
('kam', 'MRK', 7, 29, 'Na amwĩa, Kwondũ wa ndeto ii enda; ndaimoni nĩyumie mwĩĩtunĩ waku.'),
('kam', 'MRK', 7, 30, 'Na enũka, na amwĩthĩa mwana akomete ũkomonĩ, na ĩla ndaimoni nĩyumie.'),
('kam', 'MRK', 7, 31, 'Na ĩngĩ auma mĩvakanĩ ya Tile, avĩtĩla Sitoni, athi kũvika ũkanga wa Kalilii, avĩtĩle katĩ wa mĩvaka ya Ndekavoli.'),
('kam', 'MRK', 7, 32, 'Na mamũetee ũmwe mwau matũ, na wavũvũtaa; na mamwĩsuva amwilĩĩle kw’oko kwake.'),
('kam', 'MRK', 7, 33, 'Na amwosa e weka amũvanthan’ya na ĩkomano, na amwĩkĩa syaa syake matũnĩ make, na atw’ĩla mata, na akiita ũĩmĩ wake;'),
('kam', 'MRK', 7, 34, 'na ang’elela ĩtunĩ avevũũka, na amwĩa, Evavatha, ũalyũlo nĩ, Vingũka.'),
('kam', 'MRK', 7, 35, 'Na matũ make mavingũka, na kĩla kyoovete ũĩmĩ wake kyathaw’a, na aneena nesa.'),
('kam', 'MRK', 7, 36, 'Na ameaĩa maikatavye mũndũ: ĩndĩ o ũndũ wongeleele kũmeaĩa, now’o mongeleele mũno kũtavan’ya.'),
('kam', 'MRK', 7, 37, 'Na maseng’a ũndũ ũtathimĩka, makyasya, Nĩwĩkĩte maũndũ onthe nesa; nũtumaa o na ala au matũ mew’a, na ala mataaneena maneena.'),
('kam', 'MRK', 8, 1, 'Na ĩngĩ matukũ asu, yĩla kwaĩ ĩkomano ĩnene, nayo yĩtyaĩ na kya ũya, ameta amanyĩw’a make, na amea,'),
('kam', 'MRK', 8, 2, 'Nĩngũyĩw’ĩa ĩkomano tei, nĩkwĩthĩwa yu nĩ matukũ atatũ mekalĩte nakwa, na mati na kya ũya:'),
('kam', 'MRK', 8, 3, 'na ethĩwa nĩngũmombũũkya maende kwoo me na nzaa, makanyalĩla nzĩanĩ; na amwe moo maumĩte kũasa.'),
('kam', 'MRK', 8, 4, 'Na amanyĩw’a make mamũsũngĩa, Mũndũ atonya ata kũvũnĩthya andũ aa na imũtũ kũũ weũnĩ?'),
('kam', 'MRK', 8, 5, 'Na amakũlya, Mwĩ na imũtũ syĩana? Na masya, Nĩ mũonza.'),
('kam', 'MRK', 8, 6, 'Na ayĩaĩa ĩkomano yĩkale nthĩ: nake oosa ila imũtũ mũonza, na atũnga mũvea, na atilanga, na anenga amanyĩw’a make, mamaaĩe; na mayĩaĩa ĩkomano.'),
('kam', 'MRK', 8, 7, 'Na maĩ na tũmakũyũ tũvũthũ: na atũathima, na eeaa kana mayĩaĩe tũu natw’o.'),
('kam', 'MRK', 8, 8, 'Na maya, mavũna: na moosa ũtialo wa ilungu ila ndile, ikavũ mũonza.'),
('kam', 'MRK', 8, 9, 'Na ala maĩe maĩ ta ngili inya: na amombũũkya.'),
('kam', 'MRK', 8, 10, 'Na oyu alika ngalawanĩ vamwe na amanyĩw’a make, na athi ngalĩ sya Ndalimanutha.'),
('kam', 'MRK', 8, 11, 'Na Avalisi maumĩla, na mambĩlĩlya kũkũlan’ya nake, makĩmantha kyama kuma ĩtunĩ, makĩmũtata.'),
('kam', 'MRK', 8, 12, 'Na avevũũka mũno vevanĩ wake na asya, Nĩkĩ ũsyao ũũ ũkũmantha kyama? Nĩ w’o nĩngũmwĩa, Ũsyao ũũ ndũkanengwa kyama.'),
('kam', 'MRK', 8, 13, 'Na amatia, na avota ĩngĩ ngalawanĩ, ainga mũingo ũla ũngĩ.'),
('kam', 'MRK', 8, 14, 'Na nĩmoolĩtwe nĩ ũkua imũtũ; ate o kĩmũtũ kĩmwe maĩ nakyo ngalawani.'),
('kam', 'MRK', 8, 15, 'Na ameaĩa, akyasya, Ĩmanyĩlĩlei, ĩsũvĩei yĩla ĩlawa ya Avalisi na ya Elote.'),
('kam', 'MRK', 8, 16, 'Na masũanĩa ene kwa ene, makyasya, Nĩkwĩthĩwa tũi na imũtũ.'),
('kam', 'MRK', 8, 17, 'Na Yesũ amanya ũu amea, Nĩkĩ mũũsũanĩa nũndũ mũi na imũtũ? Mũinamba kwona o na kũmanya? Ngoo syenyu ko nyũmũ?'),
('kam', 'MRK', 8, 18, 'Mwĩ na metho, na mũtikwona? Na mwĩ na matũ, na mũtikwĩw’a? O na mũtiũlilikana?'),
('kam', 'MRK', 8, 19, 'Yĩla namatilangĩle andũ ngili itano ila imũtũ itano, mwoosie ikavũ syĩana syusũĩte ilungu ila ndile? Mamwĩa, Nĩ ĩkũmi na ilĩ.'),
('kam', 'MRK', 8, 20, 'Na ĩvinda yĩla nĩnamatilangĩle andũ ngili inya imũtũ mũonza, mwoosie ikavũ syĩana sya ilungu ila ndile? Na mamwĩa, Nĩ mũonza.'),
('kam', 'MRK', 8, 21, 'Na amea, O na yu mũtinamba ũmanya?'),
('kam', 'MRK', 8, 22, 'Na mavika Vethisaita. Na mamũetee kĩlilinda, mamwĩsũva akĩkiite.'),
('kam', 'MRK', 8, 23, 'Na akwata kĩla kĩlilinda kw’oko, akĩtwaa ũtee wa mũsyĩ; na akĩtw’ĩla mata metho, na akilĩĩla moko, akĩkũlya, Nũkwona kĩndũ?'),
('kam', 'MRK', 8, 24, 'Na kyookĩlya metho, kyasya, Nĩngwona andũ; nũndũ nĩngũmona ta mĩtĩ, maendete.'),
('kam', 'MRK', 8, 25, 'Na akilĩĩla moko ĩngĩ methonĩ; na kyaketeea mũno, nakyo kyavow’a, na kyoona syĩndũ syonthe nesa.'),
('kam', 'MRK', 8, 26, 'Na amwĩa enũke kwoo, akyasya, O na mũsyĩ ũũ ndũkavote vo.'),
('kam', 'MRK', 8, 27, 'Na Yesũ na amanyĩw’a make mauma vo, mathi mĩsyĩ ya Kaisalea ya Vilivu: na me nzĩanĩ maendete amakũlya amanyĩw’a make, akysaya, Andũ measya nyie nĩ ũũ?'),
('kam', 'MRK', 8, 28, 'Na mamũtavya, makyasya, Wĩ Yoana ũla Mũvatisi; na angĩ, Wĩ Eliya; ĩndĩ angĩ, Wĩ ũmwe wa athani.'),
('kam', 'MRK', 8, 29, 'Na amakũlya, Ĩndĩ inyw’ĩ mwĩasya nyie nĩ ũũ? Vetelo asũngĩa, amwĩa, We nue Klĩsto.'),
('kam', 'MRK', 8, 30, 'Na ameaĩa maikatavye mũndũ ũndũ wake.'),
('kam', 'MRK', 8, 31, 'Na ambĩlĩlya kũmamanyĩsya kana Mwana wa mũndũ ndatĩa ũthĩnw’a na mathĩna maingĩ, na kũlewa nĩ atumĩa, na athembi anene, na aandĩki, na kũawa, na mĩthenya ĩtatũ yathela akathayũũka ĩngĩ.'),
('kam', 'MRK', 8, 32, 'Na aneena ndeto isu ateũvitha. Na Vetelo amwosa, ambĩlĩlya kũmũkan’ya.'),
('kam', 'MRK', 8, 33, 'Ĩndĩ we eethyũũa, na amasisya amanyĩw’a make, amũkan’ya Vetelo, akyasya, Syoka ĩtina wakwa, Satani; nũndũ ndũũlilikana maũndũ ma Ngai, ĩndĩ nĩ ala ma andũ.'),
('kam', 'MRK', 8, 34, 'Na ayĩta ĩkomano na amanyĩw’a make nao, na amea, Ethĩwa mũndũ o na wĩva nũnũkwenda kũmbikĩla, nĩelee mwene, na kwĩyaĩkya ngelan’yo yake, na akĩmbikĩla.'),
('kam', 'MRK', 8, 35, 'Nũndũ o ũla ũnũkwenda kũvĩtya thayũ wake akawasya; na o ũla ũkawasya thayũ wake kwondũ wakwa na kwondũ wa ũvoo mũseo, ũsu akoovĩtya.'),
('kam', 'MRK', 8, 36, 'Nũndũ mũndũ aunwa nĩ kyaũ o na akosa nthĩ nima na akyasya thayũ wake?'),
('kam', 'MRK', 8, 37, 'Nũndũ mũndũ akakũan’ya thayũ wake na kyaũ?'),
('kam', 'MRK', 8, 38, 'Nũndũ o ũla ũkambĩw’ĩa nthoni nyie kana ndeto syakwa ũsyaonĩ ũũ wa ũlaalai na wa naĩ, nake Mwana wa mũndũ nũkamwĩw’ĩa nthoni, yĩla ũkoka ũtheunĩ mũtisu wa Ĩthe wake vamwe na alaĩka atheu.'),
('kam', 'MRK', 9, 1, 'Na amea, Nĩ w’o nĩngũmwĩa, Ve andũ amwe ma aa maũngeme vaa, ala matakasama kĩkw’ũ nongi, matanamba kwona ũsumbĩ wa Ngai wũkĩte na vinya.'),
('kam', 'MRK', 9, 2, 'Na matukũ thanthatũ mathela Yesũ oosa Vetelo, na Yakovo, na Yoana, ambata nao kĩĩmanĩ kĩtũlu me oka: na mũvw’ano wake waalyũka mene;'),
('kam', 'MRK', 9, 3, 'na ngũa syake syakaka, syeeũva kw’ũ, ũndũ mũthambya o na wĩva kũũ nthĩ ũtatonya kweũvya.'),
('kam', 'MRK', 9, 4, 'Na Eliya vamwe na Mose mamaumĩlĩa: nao nĩmaneenanasya na Yesũ.'),
('kam', 'MRK', 9, 5, 'Na Vetelo asũngĩa na amwĩa Yesũ, Lavai, nĩ ũseo kwitũ kwĩthĩwa vaa: na twake malwanda atatũ; yĩmwe yĩthĩwe yaku, na yĩmwe ya Mose, na yĩmwe ya Eliya.'),
('kam', 'MRK', 9, 6, 'Nũndũ ndaamanya ũndũ wa kũneena; nĩkwĩthĩwa nĩmalikilwe nĩ w’ĩa mũnene.'),
('kam', 'MRK', 9, 7, 'Na kwooka ĩthweo yamekĩa muunyĩ: na wasya wauma ĩthweonĩ, ũkyasya, Ũũ nĩwe Mwana wakwa mwendwa: mwĩw’ei we.'),
('kam', 'MRK', 9, 8, 'Na mĩtũkĩ masisya kũũ na kũũ, na matyaona mũndũ ĩngĩ, ate o Yesũ weka vamwe nao.'),
('kam', 'MRK', 9, 9, 'Na makĩtheea kuma kĩĩmanĩ, ameaĩa maikatavye mũndũ maũndũ ala monie, mũvaka o yĩla Mwana wa mũndũ ũkathayũũka kuma kwa akw’ũ.'),
('kam', 'MRK', 9, 10, 'Na masũvĩa ĩla ndeto, maikũlan’ya ene kwa ene ũndũ kũthayũũka kuma kwa akw’ũ kũilyĩ.'),
('kam', 'MRK', 9, 11, 'Na mamũkũlya, makyasya, Nĩkĩ ĩndĩ aandĩki mekwasya mũvaka Eliya ambe kũka?'),
('kam', 'MRK', 9, 12, 'Na amea, Nĩ w’o Eliya nĩwũkĩte mbee, na kũtũnga maũndũ onthe kwĩthĩwa meũ: ĩndĩ kũandĩkĩtwe ata ũndũ wa Mwana wa mũndũ, kana akathĩnw’a na mathĩna maingĩ na kũlewa?'),
('kam', 'MRK', 9, 13, 'Ĩndĩ nĩngũmwĩa kana Eliya nĩwokie, nao mamwĩkie o ũndũ mendie, o ũndũ waandĩkĩwe.'),
('kam', 'MRK', 9, 14, 'Na mavika vala ve amanyĩw’a, moona ĩkomano ĩnene yĩmathyũlũlũkĩte, na aandĩki maikũlangan’ya nao.'),
('kam', 'MRK', 9, 15, 'Na oyu ĩkomano yonthe yamwona, yaseng’a mũno, na yasemba vala ũĩ yamũkethya.'),
('kam', 'MRK', 9, 16, 'Na amakũlya ala aandĩki, Mwĩkũlan’ya nao ata?'),
('kam', 'MRK', 9, 17, 'Na ũmwe wa ĩkomano amũsũngĩa, Mũmanyĩsya, nĩnakũetee mwana wakwa wĩ na veva ũtaneenaa;'),
('kam', 'MRK', 9, 18, 'na o vala ũmũtwaaa nũũmũlumangan’ya na nthĩ: na ĩvũyũ nĩyĩũmuma, na nũnũkũvevetan’ya maeo, na nũnũkũsonzoma: na namatavya amanyĩw’a maku mawumye; na maemwa.'),
('kam', 'MRK', 9, 19, 'Na amasũngĩa asya, Ũsyao ũũ ũte na mũĩkĩĩo, ngeethĩwa nenyu ĩvinda yĩana ata? Nĩmũmĩĩsya ĩvinda yĩana ata? Mũetei vaa nĩĩ.'),
('kam', 'MRK', 9, 20, 'Na mamũete vala ũĩ: na amwona, oyu ũla veva wamũthingithangya mũno; na avalũka nthĩ, na eeyalalya akyumwa nĩ ĩvũyũ.'),
('kam', 'MRK', 9, 21, 'Na akũlya ĩthe, Nĩ kuma ĩvinda yĩva akwatwa nĩ ũndũ ũũ? Na amwĩa, Kuma e mũnini.'),
('kam', 'MRK', 9, 22, 'Na mavinda maingĩ nũmwĩkasya mwakinĩ, o na manzĩnĩ, ũmwanange: ĩndĩ ethĩwa nũtonya ũndũ, utwĩw’ĩe tei, noitũtethya.'),
('kam', 'MRK', 9, 23, 'Na Yesũ amwĩa, Ethĩwa we nũtonya! Maũndũ onthe nĩmatonyeka kwa ũla ũnũkũĩkĩĩa.'),
('kam', 'MRK', 9, 24, 'Na oyu ĩthe wa ũla mwana aneena na wasya mũnene, asya, Nĩngũĩkĩĩa; ndethya vala ndekũĩkĩĩa.'),
('kam', 'MRK', 9, 25, 'Na yĩla Yesũ wonie kana ĩkomano yooka yĩsembete vamwe, akan’ya ũla veva mũvuku akĩwĩa, We veva ũtaneenaa na ũtew’aa, nĩngũkwĩaĩa, mume, na ndũkaamũlike ĩngĩ.'),
('kam', 'MRK', 9, 26, 'Na wakaya, na wamũthingithangya mũno, wamuma: na ũla mwana eethĩwa ta wak’wa; mũvaka ala aingĩ masya, Nĩwakw’a.'),
('kam', 'MRK', 9, 27, 'Ĩndĩ Yesũ amũkwata kw’oko amũkĩlya; nake aũngama.'),
('kam', 'MRK', 9, 28, 'Na Yesũ avota nyũmba, amanyĩw’a make mamũkũlya me nzama, Nĩkĩ ithyĩ tũinatonya kũwumya?'),
('kam', 'MRK', 9, 29, 'Na amea, Mũthemba ũũ ndumĩka kwa ũndũ o na wĩva, ate o kwa kũvoya na kũtĩĩa ũya.'),
('kam', 'MRK', 9, 30, 'Na mauma vo, mavĩtĩla katĩ wa nthĩ ya Kalilii; nake ndendaa mũndũ o na wĩva amanye ũu.'),
('kam', 'MRK', 9, 31, 'Nũndũ amamanyĩasya amanyĩw’a make, na kũmea, Mwana wa mũndũ nũnũkũnenganwe mokonĩ ma andũ, na makamũaa; na mamũaa, ĩtina wa matukũ atatũ akathayũũka.'),
('kam', 'MRK', 9, 32, 'Ĩndĩ maiaamanya ndeto ĩsu na makĩa kũmũkũlya.'),
('kam', 'MRK', 9, 33, 'Na mavika Kavelinaumi: na yĩla waĩ nyũmba amakũlya, Mwĩsũanĩaa ata mwĩ nzĩanĩ?'),
('kam', 'MRK', 9, 34, 'Ĩndĩ mavindya: nũndũ nĩmakananĩaa ene kwa ene me nzĩanĩ, nũũ ũla mũnene.'),
('kam', 'MRK', 9, 35, 'Na ekala nthĩ, na ameta ala ĩkũmi na elĩ; na amea, Ethĩwa mũndũ nũkwenda kwĩthĩwa wa mbee, akeethĩwa e ĩtina kwĩ onthe, na mũthũkũmi wa onthe.'),
('kam', 'MRK', 9, 36, 'Na oosa kana kanini, akekalya katĩ woo: na akavĩtĩĩsya moko, amea,'),
('kam', 'MRK', 9, 37, 'O ũla ũkosa kamwe ka syana nini iilyĩ kaa syĩtwanĩ yakwa, embosa nyie: na o ũla ũnũũmbosa nyie, ndeũmbosa nyie, ĩndĩ nĩ ũla wandũmie.'),
('kam', 'MRK', 9, 38, 'Yoana amwĩa, Mũmanyĩsya, nĩtũnoonie mũndũ akyumya ndaimoni na syĩtwa yaku; na twamũvata, nĩkwĩthĩwa ndeũtũvikĩla.'),
('kam', 'MRK', 9, 39, 'Ĩndĩ Yesũ asya, Mũĩkamũvate: nĩkwithĩwa vai mũndũ ũla ũkeka wĩa wĩ vinya na syĩtwa yakwa, na oyu mĩtũkĩ akaneenea naĩ.'),
('kam', 'MRK', 9, 40, 'Nũndũ ũla ũte na ũndũ naitũ e ngalĩ ĩ yaitũ.'),
('kam', 'MRK', 9, 41, 'Nũndũ o ũla ũkamũnenga kĩkombe kya manzĩ mũnyw’e, nĩkwĩthĩwa mwĩ ma Klĩsto, nĩ w’o nĩngũmwĩa ndakaĩwa nĩ ĩtuvi yake.'),
('kam', 'MRK', 9, 42, 'Na o ũla ũkalulutĩkya kamwe ka tũũ tũnini tũla tũmbĩtĩkĩlaa, nĩ kavaa kwake kwoveewa ngingo ĩvia ĩnene ya kũthia, na akĩkw’a ũkanganĩ.'),
('kam', 'MRK', 9, 43, 'Na ethĩwa kw’oko kwaku nĩkũũkũlulutĩkya, kũtile: nĩ ũseo kwaku ũlike thayũnĩ na kĩthu kya kw’oko, kwĩ kũthi Ngienanĩ wĩ na moko elĩ, mwakinĩ ũla ũte ĩndĩ ũkavoa;'),
('kam', 'MRK', 9, 44, '(vala kĩinyũ kyoo kĩtakw’a, na vala mwaki ũtavoa).'),
('kam', 'MRK', 9, 45, 'Na ethĩwa kũũ kwaku nĩkũũkũlulutĩkya, kũtile: nĩ ũseo kwaku ũlike thayũnĩ na kĩthu kya kũũ, kwĩ ũkĩkw’a Ngienanĩ wĩ maũũ elĩ, mwakinĩ ũte ĩndĩ ũkavoa:'),
('kam', 'MRK', 9, 46, '(vala kĩinyũ kyoo kĩtakw’a, na vala mwaki ũtavoa).'),
('kam', 'MRK', 9, 47, 'Na ethĩwa itho yaku nĩyĩũkũlulutĩkya, yumye: nĩ ũseo kwaku ũlike ũsumbĩnĩ wa Ngai wĩ na nthongo, kwĩ ũkĩkw’a Ngienanĩ wĩ na metho elĩ:'),
('kam', 'MRK', 9, 48, 'vala kĩinyũ kyoo kĩtakw’a, na vala mwaki ũtavoa.'),
('kam', 'MRK', 9, 49, 'Nũndũ kĩla mũndũ akekĩwa mũnyũ nĩ mwaki, na kĩla nthembo ĩkasamĩthw’a mũnyũ nĩ mũnyũ.'),
('kam', 'MRK', 9, 50, 'Mũnyũ nĩ mũseo: ĩndĩ mũnyũ wathela mũsamo waw’o, mũkasamĩthya na kyaũ? Ĩthĩwai na mũnyũ nthĩnĩ wenyu, na ĩkalai na mũuo inyw’ĩ kwa inyw’ĩ.'),
('kam', 'MRK', 10, 1, 'Na ookĩla auma vo, athi mĩvakanĩ ya Yutia, na mũingo wa Yolotani: na makomano mamũkomanĩa ĩngĩ; na amamanyĩsya ĩngĩ, o ũndũ wakothaa kwĩka.'),
('kam', 'MRK', 10, 2, 'Na Avalisi mooka vala ũĩ, mamũkũlya, makĩmũtata, Nĩkwosana na ĩla mĩao mũndũ kũmũeka mũka wake?'),
('kam', 'MRK', 10, 3, 'Nake asũngĩa, na amea, Mose amwĩaĩe ata?'),
('kam', 'MRK', 10, 4, 'Masya, Mose nĩwetĩkĩlile valũa wa kũtaanĩsya ũandĩkwe, na kũmũeka.'),
('kam', 'MRK', 10, 5, 'Ĩndĩ Yesũ amea, Nĩ kwondũ wa wũmũ wa ngoo syenyu wamũandĩkĩe mwĩao ũsu.'),
('kam', 'MRK', 10, 6, 'Ĩndĩ kuma mwambĩlĩlyonĩ wa syĩndũ kũmbwa, Ngai oombie mũũme na mũka.'),
('kam', 'MRK', 10, 7, 'Kwondũ wa ũu mũndũ akatia ĩthe na nyinyia, na akalũman’ya na mũka wake;'),
('kam', 'MRK', 10, 8, 'namo elĩ makeethĩwa mwĩĩ ũmwe: o na maikethĩwa me elĩ ĩngĩ, ĩndĩ nĩ mwĩĩ ũmwe.'),
('kam', 'MRK', 10, 9, 'Ĩndĩ ala Ngai ũlũmanĩtye, mũndũ ndakamataan’ye.'),
('kam', 'MRK', 10, 10, 'Na me nyũmbanĩ amanyĩw’a mamũkũlya ĩngĩ ũvoo ũsu.'),
('kam', 'MRK', 10, 11, 'Na amea, O ũla ũkamũeka mũka wake, na aitwaa ũngĩ, nĩwamũvĩtanĩsya mũka kwa kwĩka ũlaalai:'),
('kam', 'MRK', 10, 12, 'na ethĩwa mũka ewe akamũeka mũũme, na aitwawa nĩ ũngĩ, nũnũũlaalaa.'),
('kam', 'MRK', 10, 13, 'Na mamũteee syana nini nĩ kana aikiite; na amanyĩw’a mamakan’ya.'),
('kam', 'MRK', 10, 14, 'Ĩndĩ Yesũ oona ũu, athatw’a, na amea, Iekeĩ syana nini syũke kwakwa; mũikaivate: nũndũ ũsumbi wa Ngai nĩ wa ala mailyĩ ta isu.'),
('kam', 'MRK', 10, 15, 'Nĩ w’o nĩngũmwĩa, O ũla ũtosaa ũsumbĩ wa Ngai ta kana kanini, ndakalika vo nongi.'),
('kam', 'MRK', 10, 16, 'Na aivĩtĩĩsya moko make, na aiathima, akĩsilĩĩla moko ĩũlũ wasyo.'),
('kam', 'MRK', 10, 17, 'Na akĩthi na nzĩa, mũndũ ũmwe ooka vala ũĩ asembete, na amũtulĩlya ndu, amũkũlya, Mũmanyĩsya mũseo, nĩke ũndũ wĩva nĩ kana nĩtiĩwe thayũ ũtathela?'),
('kam', 'MRK', 10, 18, 'Na Yesũ amũkũlya, Nĩkĩ ũũmbĩta mũseo? Kũi mũseo ate o ũmwe, nake nĩ Ngai.'),
('kam', 'MRK', 10, 19, 'Nũmĩsĩ ĩla mĩao, Ndũkoae, Ndũkalaalae, Ndũkoye, Ndũkaneene ũkũsĩ wa ũvũngũ, Ndũkavutane, Taĩa au na mwenyu.'),
('kam', 'MRK', 10, 20, 'Nake amwĩa, Mũmanyĩsya, maũndũ asu onthe nĩnamakwatie kuma nĩ mũnini.'),
('kam', 'MRK', 10, 21, 'Na Yesũ aimũsisya amwenda, na amwĩa, Ve ũndũ ũmwe ũtiele: thi, ũkathoosye o ila wĩ nasyo, ũnenge ngya, na ũkethĩwa na ũthwii ĩtunĩ: na ĩndĩ ũkyũka, ũngatĩĩe.'),
('kam', 'MRK', 10, 22, 'Ĩndĩ ũthyũ wake waalyũka eew’a ndeto ĩsu, nake athi na woo: nĩkwĩthĩwa aĩ na ũthwii mwingĩ.'),
('kam', 'MRK', 10, 23, 'Na Yesũ asisya ngalĩ syonthe, na amea amanyĩw’a make, Ko nĩ vinya ala athwii kũlika ũsumbĩnĩ wa Ngai!'),
('kam', 'MRK', 10, 24, 'Na amanyĩw’a make maseng’a nũndũ wa ndeto syake. Indĩ Yesũ asũngĩa ĩngĩ, amea, Syana, ko nĩ ũndũ wĩ vinya ala mekũĩkĩĩa ũthwii makĩlika ũsumbĩnĩ wa Ngai!'),
('kam', 'MRK', 10, 25, 'Nĩ ũvũthũ ngamĩle kũvotela kalimanĩ ka singano, kwĩ mũndũ mũthwii kũvota ũsumbĩnĩ wa Ngai.'),
('kam', 'MRK', 10, 26, 'Na maseng’a mũno mũnene, makĩmwĩa, Nũũ ĩndĩ ũtonya kũtangĩĩwa?'),
('kam', 'MRK', 10, 27, 'Na Yesũ amasisya, amea, Kwa andũ ndũtonyeka, ĩndĩ kwa Ngai ti ũu: nũndũ maũndũ onthe nĩmatonyeka kwa Ngai.'),
('kam', 'MRK', 10, 28, 'Vetelo ambĩlĩlya kũmwĩa, Sisya, ithyĩ nĩtũtiĩte syonthe na twakũatĩĩa.'),
('kam', 'MRK', 10, 29, 'Yesũ asya, Nĩ w’o nĩngũmwĩa, Kũi mũndũ waatia nyũmba, kana ana‐a‐inyia, kana eĩtu‐a‐inyia, kana nyinyia, kana ĩthe, kana syana, kana mĩũnda, kwondũ wakwa, na kwondũ wa ũvoo mũseo,'),
('kam', 'MRK', 10, 30, 'ũtakosa yu ĩvinda yĩĩ vandũ va kĩmwe ĩana, nyũmba, na ana‐a‐inyia, na eĩtu‐a‐inyia, na aanyinyia, na syana, na mĩũnda, vamwe na mathĩna; na ĩvinda yĩla yũkĩte thayũ ũtathela.'),
('kam', 'MRK', 10, 31, 'Ĩndĩ aingĩ me mbee makethĩwa me ĩtina; na ala me ĩtina makethĩwa me mbee.'),
('kam', 'MRK', 10, 32, 'Na me nzĩanĩ, mambatĩte Yelũsaleme, Yesũ eethĩwa amatongoesye: na maseng’a; na mamũatĩĩa me na w’ĩa. Na oosa ĩngĩ ala ĩkũmi na elĩ, n ambĩlĩlya kũmatavya maũndũ ala makamũkĩtĩkĩa,'),
('kam', 'MRK', 10, 33, 'akyasya, Sisyai, nĩtũkwambata Yelusaleme; na Mwana wa mũndũ akanenganwe mokonĩ ma athembi anene na aandĩki; nao makamũsilĩla oawe, na makamũnengane mokonĩ ma Andũ‐ma‐mbaĩ‐ingĩ;'),
('kam', 'MRK', 10, 34, 'na makamũthekeea na kĩvũthya, na kũmũtw’ĩlanga mata, na kũmũvũa, na kũmũaa; na ĩtina wa matukũ atatũ akathayũũka.'),
('kam', 'MRK', 10, 35, 'Na Yakovo na Yoana, ana ma Sevetii, mamũthengeea, makĩmwĩa, Mũmanyĩsya, nĩtũkwenda ũtwĩke o ũla tũũkũvoya.'),
('kam', 'MRK', 10, 36, 'Na amakũlya, Mwĩenda nĩmwĩke ata?'),
('kam', 'MRK', 10, 37, 'Nao mamwĩa, Tũnenge ithyĩ kwĩkala, ũmwe ngalĩ ya kw’oko kwaku kwa aũme, na ũmwe ngalĩ ya kw’oko kwaku kwa aka, ũtheunĩ waku mũtisu.'),
('kam', 'MRK', 10, 38, 'Ĩndĩ Yesũ amea, Mũtyĩsĩ ũndũ mũũvoya. Nĩmũtonya kũnyw’a kĩkombe kĩla nĩnyw’a nyie, kana kũvatiswa na ũvatiso ũla nĩvatiswa naw’o?'),
('kam', 'MRK', 10, 39, 'Na mamwĩa, Nĩtũtonya. Na Yesũ amea, Kĩkombe kĩla nĩnyw’a mũkanyw’a; na ũvatiso ũla nĩvatiswa naw’o mũkavatiswa naw’o:'),
('kam', 'MRK', 10, 40, 'ĩndĩ kwĩkala ngalĩ ya kw’oko kwakwa aũme, kana ngalĩ ya kw’oko kwakwa kwa aka, ti ũndũ wakwa kũnengane; ĩndĩ nĩ kwa ala maseũvĩw’e.'),
('kam', 'MRK', 10, 41, 'Na ala ĩkũmi meew’a ũu, mambĩlĩlya kũmathatĩa Yakovo na Yoana.'),
('kam', 'MRK', 10, 42, 'Na Yesũ ameta moke vala ũĩ, na amea, Nĩmwĩsĩ kana ala matalawa kwĩthĩwa anene ĩũlũ wa Andũ‐ma‐mbaĩ‐ingĩ, nĩmasumbĩkaa ĩũlũ woo; na anene moo nĩmameaĩaa.'),
('kam', 'MRK', 10, 43, 'Ĩndĩ ũu tiw’o katĩ wenyu: ĩndĩ o ũla ũkwenda kwĩthĩwa e mũnene katĩ wenyu, akeethĩwa e mũthũkũmi wenyu;'),
('kam', 'MRK', 10, 44, 'na o ũla ũkwenda kwĩthĩwa wa mbee katĩ wenyu, akeethĩwa e ngombo ya onthe.'),
('kam', 'MRK', 10, 45, 'Nũndũ o na Mwana wa mũndũ nake ndaaũka kũthũkũmwa, ĩndĩ nĩ kũthũkũma, na kũnengane thayũ wake wĩthĩwe wovosyo kwondũ wa aingĩ.'),
('kam', 'MRK', 10, 46, 'Na mavika Yeliko: na akyuma Yeliko, vamwe na amanyĩw’a make na ĩkomano inene, Valitimeo, mwana wa Timeo, mũvoyi kĩlilinda, ailyĩ ũtee wa nzĩa.'),
('kam', 'MRK', 10, 47, 'Na eew’a kana nĩ Yesũ Mũnasaleti, ambĩlĩlya kũneena na wasya mũnene, na kwasya, Yesũ, mwana wa Ndaviti, mbĩw’ĩa tei.'),
('kam', 'MRK', 10, 48, 'Na aingĩ mamũkan’ya, nĩ kana avindye: ĩndĩ ookĩlya wasya mũno mũnene mbee, We mwana wa Ndaviti, mbĩw’ĩa tei.'),
('kam', 'MRK', 10, 49, 'Na Yesũ aũngama, na asya, Mwĩtei. Na mamwĩta mũvoyi ũla kĩlilinda, mamũtavya, Ĩthĩwa na ũtanu: ũkĩla, nũnũũkwĩta.'),
('kam', 'MRK', 10, 50, 'Nake alekya ngũa yake nthĩ, athaanyũka, na ooka vala ve Yesũ.'),
('kam', 'MRK', 10, 51, 'Na Yesũ amũsũngĩa, asya, Wĩenda ngwĩke ata? Na ũsu kĩlilinda amwĩa, Lavai, nĩenda kwona.'),
('kam', 'MRK', 10, 52, 'Na Yesũ amwĩa, Enda; mũĩkĩĩo wakũ nĩwakũvosya. Na oyu anengwa kwona, na amũatĩĩa Yesũ nzĩanĩ.'),
('kam', 'MRK', 11, 1, 'Na yĩla mathengeeie Yelusaleme, kũvika Vethivake na Vethania, kĩĩmanĩ kya Mĩthata, atũma elĩ ma amanyĩw’a make,'),
('kam', 'MRK', 11, 2, 'na amea, Endai mũsyĩ ũla ũmwelekele: na oyu mwavota nthĩnĩ waw’o, mũkoona ndena ya ĩng’oi yovetwe, ĩtaamba ũkũa mũndũ; mĩthasyei, mũmĩete.'),
('kam', 'MRK', 11, 3, 'Na ethĩwa mũndũ o na wĩva akamũkũlya, Mwĩĩka ũu nĩkĩ? Asyai, Mwĩaĩi e vata nayo; na akamĩtũnga mĩtũkĩ.'),
('kam', 'MRK', 11, 4, 'Na mathi, moona ndena ya ĩng’oi yovetwe mũomonĩ nza, nzĩanĩ nene; na mamĩthasya.'),
('kam', 'MRK', 11, 5, 'Na amwe ma ala maũngeme vo mamakũlya, Mwĩĩka ata, mũkĩthasya ndena ya ĩng’oi?'),
('kam', 'MRK', 11, 6, 'Na mamea o tondũ Yesũ waisye: na mamaeka mathi.'),
('kam', 'MRK', 11, 7, 'Na mamũetee Yesũ ĩla ndena, na mamilĩĩla ngũa syoo; nake amĩtũla.'),
('kam', 'MRK', 11, 8, 'Na aingĩ malan’ya ngũa syoo nzĩanĩ; na angĩ malan’ya tũũvonge twa mĩtĩ, tũla matemete mĩũndanĩ.'),
('kam', 'MRK', 11, 9, 'Na ala maendie mbee, na ala maĩ ĩtina, mookĩlya wasya mũnene, makyasya, Hosana; nĩ mũathime ũla wũkĩte syĩtwanĩ ya Mwĩaĩi:'),
('kam', 'MRK', 11, 10, 'Nĩ mũathime ũsumbĩ ũla wũkĩte, ũsumbĩ wa asa waitũ Ndaviti: Hosana, ku ĩũlũ mũno.'),
('kam', 'MRK', 11, 11, 'Na avota Yelusaleme na alika ĩkalũnĩ; na asyaangya syĩndũ syonthe ngalĩ syonthe, nũndũ kwaĩ ĩvinda ya wĩoo, aumaala athi Vethania vamwe na ala ikũmi na elĩ.'),
('kam', 'MRK', 11, 12, 'Na ũnĩ ũsu, mauma Vethania, eew’a nzaa.'),
('kam', 'MRK', 11, 13, 'Na oona mũkũyũ wĩ matũ wĩ kũasa, athi kũsisya kana nĩwĩthĩa wĩ na kĩndũ: na avika vo ndaaona kĩndũ ate o matũ; nũndũ kũtyaĩ ĩvinda ya makũyũ.'),
('kam', 'MRK', 11, 14, 'Na asũngĩa, awĩa, Kuma ũmũnthĩ vati mũndũ ũkaya ũsyao waku o na tene na tene. Naamanyĩw’a make meew’a ũu.'),
('kam', 'MRK', 11, 15, 'Na mavika Yelusaleme: nake avota ĩkalũnĩ, na ambĩlĩlya kũmakuthũa ala mathooasya na ala mathooaa ĩkalũnĩ, na ang’uthũlanga mesa sya ala meũvunzya mbesa, na ivĩla sya ala meũthoosya mavũĩ;'),
('kam', 'MRK', 11, 16, 'na ndaaĩtĩkĩla mũndũ o na wĩva avĩtĩlye mũio ĩkalũnĩ.'),
('kam', 'MRK', 11, 17, 'Na amamanyĩsya aimea, Kũiandĩkĩtwe, Nyũmba yakwa ĩkeetwa nyũmba ya ũvoyea nĩ mbaĩ syonthe? Ĩndĩ inyw’ĩ mũmĩtw’ĩte ngunga ya avutani.'),
('kam', 'MRK', 11, 18, 'Na athembi anene na aandĩki meew’a ũu, mamantha ũndũ matonya kũmũaa: nũndũ nĩmamũkĩie, nĩkwĩthĩwa ĩkomano yonthe yaseng’iw’e nĩ ũmanyĩsyo wake.'),
('kam', 'MRK', 11, 19, 'Na kĩla mũthenya kwavika wĩoo aumaa ndũanĩ.'),
('kam', 'MRK', 11, 20, 'Na kĩoko mavĩtĩte moona ũla mũkũyũ wũmĩte kuma mĩĩnĩ.'),
('kam', 'MRK', 11, 21, 'Na Vetelo alilikana, amwĩa, Lavai, sisya, mũkũyũ ũla ũnawĩvĩkie nĩwũmie.'),
('kam', 'MRK', 11, 22, 'Na Yesũ asũngĩa, amea, Ĩthĩwai na mũĩkĩĩo wa Ngai.'),
('kam', 'MRK', 11, 23, 'Nĩ w’o nĩngũmwĩa. O ũla ũkatavya kĩĩma kĩĩ, Kuwa nokĩkw’a ũkanganĩ; o na ndakethĩwa na nzika ngoonĩ yake, ĩndĩ akĩtĩkĩla kana ũndũ ũnũkwasya nũkwĩkwa; ũsu akeekwa ũu.'),
('kam', 'MRK', 11, 24, 'Kwondũ wa ũu nĩngũmwĩa, Maũndũ onthe o ala mũkwĩtya mũkĩvoya, ĩtĩkĩlai kana nĩmũũmosa na mũkeethĩwa mwĩ namo.'),
('kam', 'MRK', 11, 25, 'Na o yĩla mũkũũngama, mũkĩvoya, mũekeei, ethĩwa mwĩ ũndũ na mũndũ; nĩ kana Ĩthe wenyu ũla wĩ ĩtunĩ amũekee inyw’ĩ mavĩtyo menyu.'),
('kam', 'MRK', 11, 26, '(Ĩndĩ mwalea kũekea angĩ mavĩtyo, o na Ĩthe wenyu ũla wiĩtũndakamũekea inywĩ mavĩtyo menyu.)'),
('kam', 'MRK', 11, 27, 'Na mooka ĩngĩ Yelusaleme: na aitambũka ĩkalũnĩ, athembi anene, na aandĩki, na atumĩa mooka vala ũĩ,'),
('kam', 'MRK', 11, 28, 'na mamũkũlya, Wĩkaa maũndũ aa na ũkũmũ wĩva? Kana nũũ ũkũnengete ũkũmũ kwĩka maũndũ aa?'),
('kam', 'MRK', 11, 29, 'Na Yesũ amea, Nakwa nĩngũmũkũlya ũkũlyo ũmwe, nenyu nzũngĩai, nakwa nĩngũmũtavya ũkũmũ ũla ũtumaa nĩka maũndũ aa.'),
('kam', 'MRK', 11, 30, 'Ũvatisi wa Yoana waumie ĩtunĩ kana waumie andũnĩ? Nzũngĩai.'),
('kam', 'MRK', 11, 31, 'Na masũanĩa ene kwa ene, makyasya, Ethĩwa nĩtũkwasya, Waumie ĩtunĩ; nake akasya, Nĩkĩ ĩndĩ mũtaamwĩtĩkĩla?'),
('kam', 'MRK', 11, 32, 'Ĩndĩ ethĩwa nĩtũkwasya, Waumie andũnĩ — nĩmakĩaa andũ: nũndũ andũ onthe nĩmeesĩ Yoana nĩ mwathani wa w’o.'),
('kam', 'MRK', 11, 33, 'Na mamũsũngĩa Yesũ masya, Tũtyĩsĩ. Na Yesũ amea, O nakwa ndimũtavya ũkũmũ ũla ũtumaa nĩka maũndũ aa.'),
('kam', 'MRK', 12, 1, 'Na ambĩlĩlya kũneena nao na ngelekan’yo. Mũndũ avandie mũũnda wa mĩsavivũ, na oothyũlũlũkya wiio, na enza ĩima ya ũangĩa nzavivũ, na aaka mwako mũtũlu wa mũnyoolo, na oonenga aĩmi mamũĩmĩe, nake athi ũenĩ nthĩ ĩngĩ.'),
('kam', 'MRK', 12, 2, 'Na ĩvinda yavĩka atũma ngombo kwa ala aĩmi nĩ kana yose kwa aĩmi mosyao amwe ma mũũnda wa mĩsavivũ.'),
('kam', 'MRK', 12, 3, 'Na mamĩkwata, na mamĩkũna, na mamĩlũngya ĩte na kĩndũ.'),
('kam', 'MRK', 12, 4, 'Na ĩngĩ atũma ngombo ĩngĩ kwoo; na ĩsũ mamĩuauĩkya mũtwe na mamĩsonokya.'),
('kam', 'MRK', 12, 5, 'Na amĩtũma ĩngĩ; na ĩsu mamyũaa: na atũma ingĩ mbingĩ; na makĩkũna imwe, na makyũaa ingĩ.'),
('kam', 'MRK', 12, 6, 'Na eethĩwa atialĩte na ũmwe, nake nĩ mwana ũla wendete: ũsu amũtũma kwamo ĩtina, akyasya, Makamũtaĩa mwana wakwa.'),
('kam', 'MRK', 12, 7, 'Indĩ aĩmi asu masya ene kwa ene, Ũũ nĩwe mũtiĩwa; ũkai, tũmũae, na ũtiĩwa ũkeethĩwa witũ.'),
('kam', 'MRK', 12, 8, 'Na mamũkwata, mamũaa, na mamwĩkya ũtee wa mũũnda wa mĩsavivũ.'),
('kam', 'MRK', 12, 9, 'Na yu ĩndĩ ũla mwene wa mũũnda ũsu wa mĩsavivũ akeeka ata? Akooka na akaananga ala aĩmi, na akanenga angĩ mũũnda ũsu wa mĩsavivũ.'),
('kam', 'MRK', 12, 10, 'O na mũtyaamba ũsoma ũandĩko ũũ: Ĩvia yĩla yaleilwe nĩ aki, Yĩu yatw’ikie yĩla ĩnene ya kĩkotonĩ;'),
('kam', 'MRK', 12, 11, 'Ũu nĩwaumie kwa Mwĩaĩi, Naw’o nĩ ũseng’yo methonĩ maitũ?'),
('kam', 'MRK', 12, 12, 'Na mamantha kũmũkwata; na makĩa ĩkomano; nũndũ nĩmamanyie kana ngelekan’yo ĩsu aneena ũndũ woo: na mamũeka, na mathi.'),
('kam', 'MRK', 12, 13, 'Na matũma amwe ma Avalisi na ma Elote vala ũĩ, nĩ kana mamũtee ndetonĩ syake.'),
('kam', 'MRK', 12, 14, 'Na mooka, mamwĩa, Mũmanyĩsya, nĩtwĩsĩ wĩ wa w’o, na ndũkĩaa mũndũ o na wĩva; nũndũ ndũsiasya ũthyũ wa mũndũ, ĩndĩ nũmanyĩasya w’o nzĩa ya Ngai: Nĩkwosana na ĩla mĩao kũnenga Kaisali koti, kana ti w’o?'),
('kam', 'MRK', 12, 15, 'Tũmũnenge, kana tũikamũnenge? Ĩndĩ we, esĩ wangangan’yo woo, amea, Nĩkĩ mũũndata? Ndeteei silingi none.'),
('kam', 'MRK', 12, 16, 'Na mamũetee. Na amakũlya, Mũvw’ano ũũ na ũandĩko ũũ nĩ waũ? Na mamwĩa, Nĩ wa Kaisali.'),
('kam', 'MRK', 12, 17, 'Na Yesũ amea, Mũnengei Kaisali syĩndũ sya Kaisali, na Ngai syĩndũ sya Ngai. Na maseng’ie mũno nĩwe.'),
('kam', 'MRK', 12, 18, 'Na Asatukai mooka vala ũĩ, ala maasya kana kũi ũthayũũkyo; na mamũkũlya, makyasya,'),
('kam', 'MRK', 12, 19, 'Mũmanyĩsya, Mose nĩwatũandĩkĩe, atĩ ethĩwa mwana‐a‐inyia wa mũndũ nĩwakw’a, na atia mũka wake, na ndaatia kana, mwana‐a‐inyia wake namwose ũ mũndũ mũka, amũũngamĩsye mwana‐a‐inyia mbeũ.'),
('kam', 'MRK', 12, 20, 'Kwaĩ aũme mũonza ma inyia ũmwe: na ũla wa mbee atwaa mũka, na akw’a atatiĩte mbeũ;'),
('kam', 'MRK', 12, 21, 'na wa kelĩ nake amwosa, na akw’a atatiĩte mbeũ; na wa katatũ o ta ũu;'),
('kam', 'MRK', 12, 22, 'na asu mũonza maiaatia mbeũ. Ĩtina wa onthe ũla mũndũ mũka nake akw’a.'),
('kam', 'MRK', 12, 23, 'Ũthayũũkyonĩ ĩndĩ akethĩwa e mũka wa wĩva wa asu? Nũndũ onthe mũonza nĩmamũtwaĩte.'),
('kam', 'MRK', 12, 24, 'Yesũ amea, Kĩla kĩũtuma mũvĩtya, tĩ kwĩthĩwa mũtyĩsĩ ala maandĩko, o na vinya wa Ngai?'),
('kam', 'MRK', 12, 25, 'Nũndũ yĩla makathayũũka kuma akw’ũnĩ, maikatwaana, o na maikatwaawa; ĩndĩ makethĩwa mailyĩ ta alaĩka ala me ĩtunĩ.'),
('kam', 'MRK', 12, 26, 'Ĩndĩ ũndũ wa akw’ũ, kana makathayũũkw’a; mũiaasoma ĩvukunĩ ya Mose, vala vaandĩkĩtwe ũvoo wa kala Kakuthu, ũndũ Ngai waneenie nake, akyasya, Nyie nĩ Ngai wa Avalaamu, na Ngai wa Isaka, na Ngai wa Yakovo?'),
('kam', 'MRK', 12, 27, 'We ti Ngai wa ala akw’ũ, indĩ nĩ wa ala me thayũ: nĩmũũvĩtya mũno.'),
('kam', 'MRK', 12, 28, 'Na ũmwe wa aandĩki ooka, na eew’a maineenan’ya nake, na esĩ kana amasũngĩa nesa, amũkũlya, Nĩ mwĩao wĩva ũla wĩ mbee wa yonthe?'),
('kam', 'MRK', 12, 29, 'Yesũ amũsũngĩa, Wa mbee nĩ ũũ, Ĩw’a Isilaeli; Mwĩaĩi Ngai waitũ nĩ Mwĩaĩi ũmwe:'),
('kam', 'MRK', 12, 30, 'mwende Mwĩaĩi Ngai waku na ngoo yaku yonthe, na thayũ waku w’onthe, na kĩlĩko kyaku kyonthe, na vinya waku w’onthe.'),
('kam', 'MRK', 12, 31, 'Na wa kelĩ nĩw’o ũũ, Mwende mũtũĩ waku o tondũ wĩyendete mwene. Vai mwĩao ũngĩ mũnene kwĩ ĩsu.'),
('kam', 'MRK', 12, 32, 'Na ũla mũandĩki amwĩa, Nĩ w’o, Mũmanyĩsya, nĩwaneena w’o kana Ngai nĩ ũmwe; na vai ũngĩ ate o we:'),
('kam', 'MRK', 12, 33, 'na kũmwenda na ngoo yonthe, na ũmanyi w’onthe, na vinya w’onthe, na kũmwenda mũndũ ũngĩ o tondũ wĩyendete mwene, nĩkũthonokete mũno nthembo nima syonthe sya ũvĩvw’a, o na nthembo sya kũtonywa.'),
('kam', 'MRK', 12, 34, 'Na Yesũ oona kana asũngĩa na ũmanyi, amwĩa, We ndwĩ kũasa na ũsumbĩ wa Ngai. Na ĩtina wa ũu vai mũndũ waatata kũmũkũlya ũndũ ĩngĩ.'),
('kam', 'MRK', 12, 35, 'Na Yesũ akĩmanyĩsya ĩkalũnĩ asũngĩa, asya, Aandĩki measya ata kana Klĩsto nĩ mwana wa Ndaviti?'),
('kam', 'MRK', 12, 36, 'Ndaviti mwene e nthĩnĩ wa Veva Mũtheu aisye, Mwĩaĩi amwĩie Mwĩaĩi wakwa, Ĩkala nthĩ ngalĩ ya kw’oko kwakwa kwa aũme, Mũvaka nat’wa amaitha maku kavĩla ka nyaĩĩ syaku.'),
('kam', 'MRK', 12, 37, 'Ndaviti mwene emwĩta Mwĩaĩi; na ĩndĩ nĩ mwana wake ata? Na yĩla ĩkomano ĩnene yamwĩthukĩĩsya na ũtanu.'),
('kam', 'MRK', 12, 38, 'Na ũmanyĩsyonĩ wake asya, Ĩsũvĩei aandĩki, ala mendaa kũtambũka mekĩe ngũa ndasa, na kũkethw’a ing’ang’anĩ,'),
('kam', 'MRK', 12, 39, 'na ivĩla sya mbee masinakokenĩ, na kũndũ kwa mbee mbokanĩ:'),
('kam', 'MRK', 12, 40, 'ala maĩsaa nyũmba sya aka ndiwa, na nũndũ wa ũkengani nĩmaasavasya mboya; asu nĩmo ala makona ũsilĩlo mũnene mbee.'),
('kam', 'MRK', 12, 41, 'Na ekala nthĩ elekele vala valekelaw’a nthembo, na oona ũndũ ĩkomano yĩũlekya mbesa vala valekelaw’a: na aingĩ ala maĩ athwii meekĩa nyingĩ.'),
('kam', 'MRK', 12, 42, 'Na kwooka mũndũ mũka ndiwa ngya, eekĩa tũwela twĩlĩ, nat’wo nĩ ĩsendi yĩmwe.'),
('kam', 'MRK', 12, 43, 'Na ameta amanyĩw’a make, amea, Nĩ w’o nĩngũmwĩa, Ndiwa ĩno ngya nĩyekĩa nyingĩ kwĩ onthe ala mekwĩkĩa vala valekelaw’a:'),
('kam', 'MRK', 12, 44, 'nũndũ aa onthe meekĩa nũndũ wa kwingĩvĩwa kwoo; ĩndĩ ũũ kuma ũkyanĩ wake eekĩa syonthe ila wĩ nasyo, nĩsyo wĩkwatyo wake w’onthe wa thayũ.'),
('kam', 'MRK', 13, 1, 'Na akyuma ĩkalũnĩ, ũmwe wa amanyĩw’a make amwĩa, Mũmanyĩsya, sisya, ũndũ mavia aa mailyĩ, na ũndũ myako ĩno ĩtilyĩ.'),
('kam', 'MRK', 13, 2, 'Na Yesũ amwĩa, Nũkwona myako ĩno mĩnene? Vaa vaikatiwa ĩvia ĩũlũ wa yĩngĩ, yĩla yĩtakaombowa.'),
('kam', 'MRK', 13, 3, 'Na ekalĩte kĩĩmanĩ kya Mĩthata kwelekela ĩkalũ, Vetelo na Yakovo na Yoana na Andalea mamũkũlya me nzama,'),
('kam', 'MRK', 13, 4, 'Tũtavye, maũndũ asu makethĩwa ĩndĩĩ? Na wonan’yo nĩ wĩva yĩla maũndũ asu onthe makathengeea kwĩanĩw’a?'),
('kam', 'MRK', 13, 5, 'Na Yesũ ambĩlĩlya kũmatavya, Ĩsũvĩei mũndũ ndakamwasye.'),
('kam', 'MRK', 13, 6, 'Aingĩ makooka na syĩtwa yakwa, makyasya, Ninyie we; na makamasya aingĩ.'),
('kam', 'MRK', 13, 7, 'Na yĩla mũkew’a ũvoo wa makaũ na mawetango ma makaũ, mũikaũũye: maũndũ asu mati ndĩi ya ũlea kwĩkĩka; ĩndĩ mũminũkĩlyo ndũnamba ũvika.'),
('kam', 'MRK', 13, 8, 'Nũndũ mbaĩ ĩkookĩlĩla mbaĩ, na ũsumbĩ ũkookĩlĩla ũsumbĩ; kũkeethĩwa itetemo sya nthĩ kũũ na kũũ; na kũkeethĩwa mayũa; maũndũ asu nĩ wambĩlĩlyo wa woo.'),
('kam', 'MRK', 13, 9, 'Ĩndĩ inyw’ĩ ĩsũvĩei: nũndũ makamũnengane nzamanĩ; na mũkakũnĩwa masinakokenĩ; na mũkaũngama mbee wa makavana na asumbĩ kwondũ wakwa, mwĩthĩwe ngũsĩ kwamo.'),
('kam', 'MRK', 13, 10, 'Na ĩngĩ mũvaka ũvoo mũseo wambe ũtavanw’a mbaĩnĩ syonthe.'),
('kam', 'MRK', 13, 11, 'Na yĩla memũtwaa na kũmũnengane mokonĩ ma andũ, mũikambe kũũũya ũndũ mwĩneena: ĩndĩ o ũla mwĩnengwa saa ũsu, ũneenei: nĩkwĩthĩwa ti ĩnyw’ĩ mwĩneena, ĩndĩ nĩ Veva Mũtheu.'),
('kam', 'MRK', 13, 12, 'Na mũndũ akanengane mwana‐a‐inyia oawe, na ĩthe mwana wake; na syana ikamokĩlĩla ala maisyaie, na kũmoaĩthya.'),
('kam', 'MRK', 13, 13, 'Na inyw’ĩ mũkamenwa nĩ andũ onthe kwondũ wa syĩtwa yakwa: ĩndĩ ũla wĩũmĩĩsya kũvika mũminũkĩlyo, ũsu akatangĩĩwa.'),
('kam', 'MRK', 13, 14, 'Ĩndĩ yĩla mwĩona ũthatyo ũla wanangaa ũũngeme vandũ ũtaĩle kũũngama (ũla ũsomaa namanye), ĩvinda yĩu ala me Yutia makĩe mathi iĩmanĩ:'),
('kam', 'MRK', 13, 15, 'na ũla wĩ ĩũlũ wa nyũmba ndakatheee, o na ndakavote nthĩnĩ, kumya kĩndũ o na kĩva kĩla kĩ nyũmbanĩ kwake:'),
('kam', 'MRK', 13, 16, 'na ũla wĩ mũũndanĩ ndakasyoke ose ngũa yake ya ĩũlũ.'),
('kam', 'MRK', 13, 17, 'Ĩndĩ woo nĩ wa ala aito na ala mekwongya mĩthenya ĩsu!'),
('kam', 'MRK', 13, 18, 'Na voyai ũndũ ũsu ndũkethĩwe ĩvinda ya mbevo.'),
('kam', 'MRK', 13, 19, 'Nũndũ matukũ asu kũkethĩwa thĩna ũndũ ũtaaĩthĩwa kuma mwambĩlĩlyo wa kũmbwa kwa syĩndũ ila Ngai wombie kũvika na yu, o na kũikethĩwa ũngĩ nongi.'),
('kam', 'MRK', 13, 20, 'Na kethĩwa Ngai ndaakuvĩvya matukũ asu, kũivĩta mwĩĩ o na wĩva; ĩndĩ kwondũ wa anyuve, ala wanyuvie, akuvĩvya matukũ asu.'),
('kam', 'MRK', 13, 21, 'Na ĩvinda yĩu ethĩwa mũndũ o na wĩva akamwĩa, Sisyai, Klĩsto e vaa; kana, Sisyaĩ, e vaya; mũiketĩkĩle;'),
('kam', 'MRK', 13, 22, 'nũndũ makookĩla Maklĩsto ma ũvũngũ na athani ma ũvũngũ, na makoonan’ya syama na moseng’yo, nĩ kana masye o na anyuve, ethĩwa ũu nũtonyeka.'),
('kam', 'MRK', 13, 23, 'Ĩndĩ inyw’ĩ ĩsũvĩei: sisyai, nĩnamũtavya maũndũ onthe mbee.'),
('kam', 'MRK', 13, 24, 'Ĩndĩ matukũ asu, ĩtina wa ũla thĩna, syũa yĩkaya kĩvindu, na mwei ndũkaumya kyeni kyaw’o,'),
('kam', 'MRK', 13, 25, 'na ndata ikethĩwa ikĩvalũkanga kuma ĩtunĩ, na mavinya ala me ĩtunĩ makathingithangwa.'),
('kam', 'MRK', 13, 26, 'Na nĩvo meona Mwana wa mũndũ okĩte mathweonĩ na vinya mũnene na ũtheu mũtisu.'),
('kam', 'MRK', 13, 27, 'Na nĩvo wĩtũma alaĩka momban’ye anyuve make kuma ngalĩ inya sya ĩseve, na kuma kĩtulu kya nthĩ kũvika kĩtulu kya ĩtu.'),
('kam', 'MRK', 13, 28, 'Na ĩndĩ ĩmanyĩsyei ngelekan’yo ya mũkũyũ: mbonge syaw’o syololoa, na syathongoosya wenze, nĩmwĩsĩ kana mũniino nũthengeee;'),
('kam', 'MRK', 13, 29, 'no ta ũu nenyu, mũkyona maũndũ asu makĩkĩka manyai kana e vakũvĩ, o ta mĩomonĩ.'),
('kam', 'MRK', 13, 30, 'Nĩ w’o nĩngũmwĩa, Ũsyao ũũ ndũkavĩta, maũndũ asu onthe mateanĩw’e.'),
('kam', 'MRK', 13, 31, 'Ĩtu na nthĩ nikavĩta: ĩndĩ ndeto syakwa itikavĩta.'),
('kam', 'MRK', 13, 32, 'Ĩndĩ mũthenya ũsu na saa ũsu vai ũmwe wĩsĩ, o na alaĩka me ĩtunĩ, o na Mwana, ĩndĩ no Asa.'),
('kam', 'MRK', 13, 33, 'Ĩsũvĩei, syaĩĩsyai, na voyai: nũndũ mũtyĩsĩ ĩvinda yĩu nĩ ĩndĩĩ.'),
('kam', 'MRK', 13, 34, 'Nĩ ta mũndũ akĩthi kyalo nthĩ ĩngĩ, atiĩte nyũmba yake, ainengete ngombo syake ũkũmũ, na kĩla ĩmwe wĩa wayo, na aimwĩaĩa mũsũvĩi nasyaĩĩsye.'),
('kam', 'MRK', 13, 35, 'Syaĩĩsyaĩ ĩndĩ; nũndũ mũtyĩsĩ yĩla mwene wa nyũmba wĩũka, ethĩwa nĩ wĩoo, kana ũtukũ katĩ, kana nzamba syasya, kana kĩoko;'),
('kam', 'MRK', 13, 36, 'ndakese kũka na mĩtũkĩ mũtesĩ na aimwĩthĩa mũkomete.'),
('kam', 'MRK', 13, 37, 'Na ũu ngũmũtavya inyw’ĩ, nĩmatavya onthe, Syaĩĩsyai.'),
('kam', 'MRK', 14, 1, 'Na ĩtina wa mĩthenya ĩlĩ kwaĩ mboka ya vasaka na kĩmũtũ kĩte ĩlawa: na athembi anene na aandĩki mamantha ũndũ matonya kũmũkwata na ũseleke na kũmũaa:'),
('kam', 'MRK', 14, 2, 'nũndũ maasya, Tũikaamũkwate ĩvinda ya mboka, kũikese kwĩthĩwa kĩtuu andũnĩ.'),
('kam', 'MRK', 14, 3, 'Na yĩla waĩ Vethania nyũmbanĩ ya Simoni ũla ũwaĩte mangũ, ailyĩ lĩunĩ, kwooka mũndũ mũka e na sũva wa mauta matheu, me thooa mũnene mũno; na ooaa sũva amwĩtĩkĩsye mũtwenĩ wake.'),
('kam', 'MRK', 14, 4, 'Ĩndĩ kwaĩ amwe mathatie ngoonĩ syoo, makyasya, Wanango ũũ wa mauta nĩ wa kĩ?'),
('kam', 'MRK', 14, 5, 'Nũndũ mauta aa meĩ matonya kũtewa mbee wa silingi maana atatũ, ikanengwa ngya. Na mamũnyungunyĩĩsya ũla mũndũ mũka.'),
('kam', 'MRK', 14, 6, 'Ĩndĩ Yesũ asya, Ekanai nake; nĩkĩ mũũmũthĩn’ya? Ambĩka wĩa mũseo.'),
('kam', 'MRK', 14, 7, 'Nĩkwĩthĩwa ngya mwĩ nasyo mavinda onthe, na yĩla mũkwenda nĩmũtonya kũmeka nesa; ĩndĩ nyie mũi nakwa mavinda onthe.'),
('kam', 'MRK', 14, 8, 'Nĩweka ũla ũtonya; amba ũmbĩtĩkĩsya mwĩĩ wakwa mauta kwondũ wa kũthikwa kwakwa.'),
('kam', 'MRK', 14, 9, 'Na nĩ w’o nĩngũmwĩa, O kũla kũkatavanw’a ũvoo mũseo nthĩ yonthe ũndũ ũũ naw’o weekwa nĩ mũndũ mũka ũũ ũkawetwa wĩthĩwe wa kũmũlilikana we.'),
('kam', 'MRK', 14, 10, 'Na Yutasi Isikalioti, ũmwe wa ala ĩkũmi na elĩ, athi kwa athembi anene, ni kana amũnengane kwoo.'),
('kam', 'MRK', 14, 11, 'Nao, meew’a ũu, matana, na mamwatha kũmũnenga mbesa. Na amantha ũndũ ũtonya na ũvũthũ kũmũnengane kwoo.'),
('kam', 'MRK', 14, 12, 'Na mũthenya wa mbee wa kĩmũtũ kĩte ĩlawa, yĩla mooaie katena ka vasaka, amanyĩw’a make mamũkũlya, Wĩenda tũende tũkaũseũvisye va ũye vasaka?'),
('kam', 'MRK', 14, 13, 'Na atũma elĩ ma amanyĩw’a make, amea, Endai ndũanĩ, na mũndũ ũkuĩte kĩkuu kya manzĩ ekomana nenyu: mũvikĩlei ũsu;'),
('kam', 'MRK', 14, 14, 'na o vala wĩlika, tavyai mwene wa nyũmba, Mũmanyĩsya akũlya, Ĩĩva nyũmba yakwa ya aeni, vala ngũĩa vasaka vamwe na amanyĩw’a makwa?'),
('kam', 'MRK', 14, 15, 'Nake mwene akamwon’ya nyũmba nene ya ĩũlũ, nzeũvye yĩ na mĩio: mũtũseũvĩsye vo.'),
('kam', 'MRK', 14, 16, 'Na amanyĩw’a maũmaala, mathi ndũanĩ, na moona o ũndũ ũmatavisye: na maseũvya vasaka.'),
('kam', 'MRK', 14, 17, 'Na kwavika wĩoo ooka vamwe na ala ĩkũmi na elĩ.'),
('kam', 'MRK', 14, 18, 'Na mailyĩ makĩya, Yesũ asya, Nĩ w’o nĩngũmwĩa, Ũmwe wenyu akambũnyanĩa, nake nũnũũya vamwe nakwa.'),
('kam', 'MRK', 14, 19, 'Mambĩlĩlya kwĩw’a woo na kũmũkũlya ũmwe na ũmwe, Ninyie?'),
('kam', 'MRK', 14, 20, 'Na amea, Nĩ ũmwe wa ala ĩkũmi na elĩ, ũla ũnũkwĩkĩanĩa kw’oko ĩsaaninĩ vamwe nakwa.'),
('kam', 'MRK', 14, 21, 'Nũndũ Mwana wa mũndũ ethi, o ũndũ waandĩkĩwe: ĩndĩ woo nĩ wa mũndũ ũsu ũla wĩmũvũnyanĩa Mwana wa mũndũ! Wĩthĩwa wi ũseo kwa mũndũ ũsu kethĩwa ndaasyawa.'),
('kam', 'MRK', 14, 22, 'Na makĩya, oosa kĩmũtũ, na akĩathima, akĩtilanga, na amanenga, amea, Osai: kĩĩ nĩkyo mwĩĩ wakwa.'),
('kam', 'MRK', 14, 23, 'Na oosa kĩkombe, na atũnga mũvea, amanenga: na onthe manyw’a yakyo.'),
('kam', 'MRK', 14, 24, 'Na amea, Ĩno nĩyo nthakame yakwa ya ũtianĩo mweũ, ĩla ĩĩtĩkwa kwondũ wa andũ aingĩ.'),
('kam', 'MRK', 14, 25, 'Nĩw’o nĩngũmwĩa, Ndikanyw’a ĩngĩ ya ũsayo wa mũsavivũ, mũvaka mũthenya ũla ngamĩnyw’a yĩ nzaũ ũsumbĩnĩ wa Ngai.'),
('kam', 'MRK', 14, 26, 'Na maina wathi, maumaala mathi kĩĩmanĩ kya Mĩthata.'),
('kam', 'MRK', 14, 27, 'Na Yesũ amea, Inyw’onthe nĩmũũlulutĩkw’a nũndũ wakwa: nũndũ nĩkũandikĩtwe, Ngakũna mũĩthi na malondũ makanyaĩĩkw’a.'),
('kam', 'MRK', 14, 28, 'Ĩndĩ ĩtina wa kũthayũũka kwakwa, ngaenda mbee wenyu kũvika Kalilii.'),
('kam', 'MRK', 14, 29, 'Ĩndĩ Vetelo amwĩa, O na ethĩwa onthe makalulutĩkw’a, nyie ndilulutĩkw’a nongi.'),
('kam', 'MRK', 14, 30, 'Na Yesũ amwĩa, Nĩ w’o nĩngũkwĩa, kana we ũtukũ ũũ wa ũmũnthĩ, mbee wa nzamba ĩtanasya kelĩ, ũkangaĩa katatũ.'),
('kam', 'MRK', 14, 31, 'Ĩndĩ ongeleka kũneena na vinya, O na ethĩwa no mũvaka nĩkw’e naku ndikakũkaĩa. Na onthe masya o ta ũu.'),
('kam', 'MRK', 14, 32, 'Na mavika vandũ vetawa Ngesemanii: na amea amanyĩw’a make, Ĩkalai vaa ĩvinda yĩla ngũvoya.'),
('kam', 'MRK', 14, 33, 'Na athi e na Vetelo na Yakovo na Yoana, na ambĩlĩlya kũmaka na kũũũya mũno.'),
('kam', 'MRK', 14, 34, 'Na amea, Ngoo yakwa nĩkũũũya mũno o na kũvika kĩkw’ũ: ĩkalai vaa, mũsyaĩĩsye.'),
('kam', 'MRK', 14, 35, 'Nake aendanga mbee vanini, na eevalũkya nthĩ, na avoya kana ethĩwa ũũ nũtonyeka, saa ũsu ũmũthonoke.'),
('kam', 'MRK', 14, 36, 'Na asya, Nau, Asa, maũndũ onthe nĩmatonyeka kwaku; mbĩtĩthya kĩkombe kĩĩ: ĩndĩ ti ũndũ ngwenda nyie, ĩndĩ ũndũ ũkwenda we.'),
('kam', 'MRK', 14, 37, 'Na ooka amethĩa makomete, na amũkũlya Vetelo, Simoni, kaĩ nũkomete? Ndũnatonya kũsyaĩĩsya o na saa ũmwe?'),
('kam', 'MRK', 14, 38, 'Syaĩĩsyai na voyai, nĩ kana mũikalike ũtatwanĩ: veva nĩ w’o ũkwenda, ĩndĩ mwĩĩ ndwĩ na vinya.'),
('kam', 'MRK', 14, 39, 'Na athi ĩngĩ, avoya, akyasya o ila ndeto.'),
('kam', 'MRK', 14, 40, 'Na ooka ĩngĩ na amethĩa makomete, nũndũ metho moo maĩ na too mũno; na maiaamanya ũndũ wa ũmũsũngĩa.'),
('kam', 'MRK', 14, 41, 'Na ooka ya katatũ na amea, Komai yu, mũthũmũe: nũu; ũla saa nĩ mũviku; sisyai, Mwana wa mũndũ nũnũũnenganwe mokonĩ ma andũ athe.'),
('kam', 'MRK', 14, 42, 'Ũkĩlai, tũthi: sisyai, ũla ũnũũmbũnyanĩa nũthengee.'),
('kam', 'MRK', 14, 43, 'Na oyu akĩneena, Yutasi, ũmwe wa ala ĩkũmi na elĩ, ooka, vamwe na ĩkomano yĩ na mbyũ na mathimbũ, maumĩte kwa athembi anene na aandĩki na atumĩa.'),
('kam', 'MRK', 14, 44, 'Na ũla ũmũvũnyanĩe amanengete wonan’yo, akyasya, O ũla nĩmũmumunya, nĩwe ũsu; mũkwatei, mũmũtwae mũmũsũvĩe.'),
('kam', 'MRK', 14, 45, 'Nake ooka, oyu athi vala ũĩ, na amwĩa, Lavai; na amũmumunya.'),
('kam', 'MRK', 14, 46, 'Na matambũũkya moko moo, na mamũkwata.'),
('kam', 'MRK', 14, 47, 'Ĩndĩ ũmwe wa ala maũngeme vo akũa ũvyũ wake, na amĩtema ngombo ya mũthembi mũnene, amĩtila kũtũ.'),
('kam', 'MRK', 14, 48, 'Na Yesũ asũngĩa, amea, Nĩmwaumĩla mwĩ na mbyũ na mathimbũ, na mwoka kũngwata ta nĩ mũvutani?'),
('kam', 'MRK', 14, 49, 'Kĩla mũthenya naĩ nenyu ĩkalũnĩ ngĩmanyĩsya, na mũiaangwata: ĩndũ ũu nĩwĩkiwe nĩ kana maandĩko meanĩw’e.'),
('kam', 'MRK', 14, 50, 'Na onthe mamũtia, makĩa.'),
('kam', 'MRK', 14, 51, 'Na mwanake ũmwe amũatĩĩa, evw’ĩkĩte ngũa ya katane mwĩĩ wake: na mamũkwata;'),
('kam', 'MRK', 14, 52, 'ĩndĩ atia ngũa ya katane, akĩa e mũthei'),
('kam', 'MRK', 14, 53, 'Na mamũtwaa Yesũ kwa mũthembi ũla mũnene: na mamũmbanĩa vo athembi onthe anene, na atumĩa, na aandĩki.'),
('kam', 'MRK', 14, 54, 'Na Vetelo amũatĩĩa e kũasa, o na nthĩnĩ, ku nza kwa mũthembi mũnene; na ekala nthĩ vamwe na makanga, makyota mwaki.'),
('kam', 'MRK', 14, 55, 'Na ĩndĩ athembĩ anene na nzama yonthe mamũmanthĩa Yesũ ũkũsĩ nĩ kana mamũae; na maiaawona.'),
('kam', 'MRK', 14, 56, 'Nũndũ aingĩ mamũkũsĩĩa ũvũngũ, na ũkũsĩ woo ndwaosana.'),
('kam', 'MRK', 14, 57, 'Na amwe maũngama mamũkũsĩĩa ũvũngũ, makyasya,'),
('kam', 'MRK', 14, 58, 'Ithyĩ nĩtũneewie akyasya, Ngaananga ĩkalũ yĩĩ yĩla yaakiwe na moko, na matukũ atatũ ngaaka yĩngĩ yĩtekwakwa na moko.'),
('kam', 'MRK', 14, 59, 'O na ũu, ũkũsĩ woo ndwaosana.'),
('kam', 'MRK', 14, 60, 'Na ũla mũthembi mũnene aũngama katĩ, amũkũlya Yesũ, akyasya, Ndũsũngĩa ũndũ? Aa makũkũsĩĩa ata?'),
('kam', 'MRK', 14, 61, 'Ĩndĩ avindya, o na ndaasũngĩa ũndũ. Na mũthembi mũnene amũkũlya ĩngĩ, amwĩa, We nue Klĩsto Mwana wa Mũtaĩwa?'),
('kam', 'MRK', 14, 62, 'Na Yesũ asya, Ninyie we: na mũkamwona Mwana wa mũndũ ailyĩ ngalĩ ya kw’oko kwa aũme kwa Vinya, akyũka na mathweo ma ĩtu.'),
('kam', 'MRK', 14, 63, 'Na mũthembi mũnene atembũanga ngũa syake, akyasya, Twĩ na vata ũngĩ mwaũ wa ngũsĩ?'),
('kam', 'MRK', 14, 64, 'Nĩmweew’a kũumana kwake; mwĩona ata? Na onthe matw’a kana aĩlwe nĩ kĩkw’ũ.'),
('kam', 'MRK', 14, 65, 'Na amwe mambĩlĩlya kũmũtw’ĩla mata, na kũmũvw’ĩka ũthyũ, na kũmũlumangya, na kũmwĩa, Athana: na ala makanga mamũmandũla.'),
('kam', 'MRK', 14, 66, 'Na Vetelo e ĩtheo ku nza, kwooka ũmwe wa eĩtu athũkũmi ma mũthembi mũnene;'),
('kam', 'MRK', 14, 67, 'na oona Vetelo akyota mwaki, amũsisya, na asya, We naku wĩĩ vamwe na ũla Mũnasaleti, Yesũ.'),
('kam', 'MRK', 14, 68, 'Ĩndĩ akaĩa, akyasya, Ndyĩsĩ, o na ndiũmanya ũndũ ũkwasya; na aumaala nza valasyanĩ, na nzamba yasya.'),
('kam', 'MRK', 14, 69, 'Na ũla mwĩĩtu mũthũkũmi amwona ĩngĩ, na ambĩlĩlya kũmea ala maũngeme vakuvĩ, Ũũ nĩ ũmwe woo.'),
('kam', 'MRK', 14, 70, 'Ĩndĩ akaĩa ĩngĩ. Na ĩtina vandũ vanini, ala maũngeme vakuvĩ mamwĩa Vetelo, Nĩw’o wĩ ũmwe woo; nĩkwĩthĩwa wĩ Mũkalilii.'),
('kam', 'MRK', 14, 71, 'Ĩndĩ ambĩlĩlya kũumana, na kwĩvĩta, Ndimwĩsĩ mũndũ ũsu mũũweta.'),
('kam', 'MRK', 14, 72, 'Na oyu, nzamba yasya ya kelĩ. Na Vetelo alilikana ndeto ila ũtaviw’e nĩ Yesũ, Nzamba ĩtanasya kelĩ, ũkangaĩa katatũ. Na aililikana, aĩa.'),
('kam', 'MRK', 15, 1, 'Na oyu kĩoko athembi anene vamwe na atumĩa na aandĩki, na nzama yonthe, masũanĩa ene kwa ene, na mamwova Yesũ, na mamũtwaa, na mamũnengane kwa Vilato.'),
('kam', 'MRK', 15, 2, 'Na Vilato amũkũlya, We nue Mũsumbĩ wa Ayuti? Na asũngĩa, amwĩa, We nĩwaneena.'),
('kam', 'MRK', 15, 3, 'Na athembi anene mamũvinganĩsya na maũndũ maingĩ.'),
('kam', 'MRK', 15, 4, 'Na Vilato amũkũlya ĩngĩ, akyasya, Ndũsũngĩa ũndũ? Sisya maũndũ ũndũ meana ala meũkũvinganĩsya namo.'),
('kam', 'MRK', 15, 5, 'Ĩndĩ Yesũ ndaasũngĩa ũndũ ĩngĩ; na Vilato aseng’a.'),
('kam', 'MRK', 15, 6, 'Na ĩndĩ ĩvinda ya mboka akothaa kũmathaĩsya mwovwa ũmwe, o ũla mamwĩtasya.'),
('kam', 'MRK', 15, 7, 'Na vaĩ mũndũ ũmwe wetawa Valava wovetwe vamwe na ala mang’endie, andũ ala mooaie angĩ ũng’endũnĩ ũsu.'),
('kam', 'MRK', 15, 8, 'Na yĩla ĩkomano yambata yambĩlĩlya kũmũvoya eke o tondũ wakothaa kũyĩka.'),
('kam', 'MRK', 15, 9, 'Na Vilato amasũngĩa, akyasya, Mwĩenda nĩmũthaĩsya Mũsumbĩ wa Ayuti?'),
('kam', 'MRK', 15, 10, 'Nũndũ amanyie kana athembi anene manamũnenganie nũndũ wa kĩwĩu.'),
('kam', 'MRK', 15, 11, 'Ĩndĩ athembi anene mathing’ĩĩsya ĩkomano yĩneene atĩ nĩ kavaa amathaĩsye Valava.'),
('kam', 'MRK', 15, 12, 'Na Vilato asũngĩa ĩngĩ amea, Nĩmwĩke ata ĩndĩ ũũ mũũmwĩta Mũsumbĩ wa Ayuti?'),
('kam', 'MRK', 15, 13, 'Nao maneena ĩngĩ na mawasya manene, Mwambe.'),
('kam', 'MRK', 15, 14, 'Na Vilato amakũlya, Nĩkĩ, nĩ ũthũku mwaũ wĩkĩte? Ĩndĩ maneena na mawasya manene mũno, Mwambe.'),
('kam', 'MRK', 15, 15, 'Na Vilato akyenda kũyendeesya ĩkomano, ayĩthaĩsya Valava, na amũkũna Yesũ na kĩvoko kyatũange, amũnengane ambwe.'),
('kam', 'MRK', 15, 16, 'Na asikalĩ mamũtwaa Yesũ nthĩnĩ wa nza, na vo nĩ kĩsilĩlonĩ, na moomban’ya nguthu yonthe ya asikalĩ.'),
('kam', 'MRK', 15, 17, 'Na mamwĩkĩa ngũa ĩilyĩ ta ndune, na mavĩlangan’ya ngovia ya mĩw’a, mamwĩkĩa mũtwe wake;'),
('kam', 'MRK', 15, 18, 'na mambĩlĩlya kũmũkethya, Nũvoo, Mũsumbĩ wa Ayuti!'),
('kam', 'MRK', 15, 19, 'Na mamũkũna mũtwe na mũangi, na mamũtw’ĩla mata, na matulya ndu mamũthaitha.'),
('kam', 'MRK', 15, 20, 'Na mamina ũmũthekeea na kĩvũthya, mamumya ĩla ngũa ĩilyĩ ta ndune, mamwĩkĩa ngũa syake. Na mamumaalya mamwambe.'),
('kam', 'MRK', 15, 21, 'Na mamũkwata mũndũ avĩtĩte, aumĩte ũtee wa ndũa, wetawa Simoni Mũkulene, ĩthe wa Alesanda na Luvusi, athi nao, nĩ kana amũkuĩe ngelan’yo yake.'),
('kam', 'MRK', 15, 22, 'Na mamũtwaa vandũ vetwa Kolokotha, ũalyũlo wayo nĩ, Vandũ va kĩng’ala.'),
('kam', 'MRK', 15, 23, 'Na mamũnenga mbinyu ĩvũlanĩtw’e na manemane: ĩndĩ ndaaosa.'),
('kam', 'MRK', 15, 24, 'Na mamwamba, na maaan’ya ngũa syake, makĩlimana, ũndũ kĩla mũndũ wĩosa.'),
('kam', 'MRK', 15, 25, 'Na kwaĩ saa itatũ, na mamwamba.'),
('kam', 'MRK', 15, 26, 'Na ũandĩko wa kũvinganĩw’a kwake nĩwaandĩkiwe ĩũlũ, MŨSUMBĨ WA AYUTI.'),
('kam', 'MRK', 15, 27, 'Na mamwamba vamwe na avutani elĩ; ũmwe ngalĩ ya kw’oko kwake kwa aũme, na ũmwe ngalĩ ya kw’oko kwake kwa aka.'),
('kam', 'MRK', 15, 28, 'Na ũandĩko weanĩw’a ũla waĩtye, Akatalwa vamwe na avĩtan’ya.'),
('kam', 'MRK', 15, 29, 'Na ala mavĩtaa nzĩanĩ mamũuma, makĩthingithya mĩtwe yoo, makyasya, A! We ũla wanangaa ĩkalũ, noiyaka na mĩthenya ĩtatũ,'),
('kam', 'MRK', 15, 30, 'ĩtangĩĩe mwene, noitheea wume ngelan’yonĩ.'),
('kam', 'MRK', 15, 31, 'No ta ũu ala athembi anene makĩmũthekeea na kĩvũthya ene kwa ene, vamwe na aandĩki, masya, Nĩwatangĩĩe angĩ; ndatonya kwĩtangĩĩa mwene.'),
('kam', 'MRK', 15, 32, 'Klĩsto, Mũsumbĩ wa Isilaeli, natheee yu aume ngelan’yonĩ, nĩ kana twone na kwĩtĩkĩla. Na ala mambiwe vamwe nake mamũvũthya.'),
('kam', 'MRK', 15, 33, 'Na syũa yaũngama, kwatulya kĩvindu nthĩ yonthe kũvika saa kenda.'),
('kam', 'MRK', 15, 34, 'Na saa kenda Yesũ aneena na wasya mũnene, Eloi, Eloi, lama savakathani? Ũalyũlo wayo nĩ, Ngai wakwa, Ngai wakwa, ũndekee kĩ?'),
('kam', 'MRK', 15, 35, 'Na amwe ma ala maũngeme vakuvĩ, meew’a ũu, masya, Sisyai, emwĩta Eliya.'),
('kam', 'MRK', 15, 36, 'Na ũmwe asemba, na anyw’ĩthya sivanzi siki yakola, na amĩkĩa mũanginĩ, na amũnenga avivite, akyasya, Ekai; tũsisye kana Eliya nũnũkũka kũmumya.'),
('kam', 'MRK', 15, 37, 'Na Yesũ aneena na wasya mũnene, na aumya veva.'),
('kam', 'MRK', 15, 38, 'Na ngũa ya tũtũ ya ĩkalũ yatembũka ilungu ilĩ kuma ĩũlũ kũvika nthĩ.'),
('kam', 'MRK', 15, 39, 'Na ũla mũnene wa asikalĩ ĩana, ũla waũngeme amwelekele, oona kana nĩwaumya veva ta ũũ, asya, Nĩ w’o mũndũ ũũ eĩ Mwana wa Ngai.'),
('kam', 'MRK', 15, 40, 'Na vaĩ aka nao makĩsisya me kũasa: na amwe moo maĩ Meli Makatalene, na Meli, inyĩa wa Yakovo ũla mũnini na wa Yose, na Salome;'),
('kam', 'MRK', 15, 41, 'asu mamũatĩĩaa yĩla waĩ Kalilii na kũmũthũkũmaa; na aka angĩ aingĩ ala mambatie vamwe nake kũvika Yelusaleme.'),
('kam', 'MRK', 15, 42, 'Na kwavika wĩoo, nĩkwĩthĩwa nĩ Ũseũvyo, nĩw’o mũthenya ũla ũatĩĩwe nĩ savato,'),
('kam', 'MRK', 15, 43, 'kwathi Yosevu wa Alimathia, mũndũ wa nzama wĩ ndaĩa, nake mwene nĩweteele ũsumbĩ wa Ngai; na athi na ũnyiaukwa Vilato, amwĩtya mwĩĩ wa Yesũ.'),
('kam', 'MRK', 15, 44, 'Na Vilato aseng’a ethĩwa nũminie kũkw’a: na amwĩta ũla mũnene wa asikalĩ ĩana, amũkũlya kana nũkwie tene.'),
('kam', 'MRK', 15, 45, 'Na amanyĩthw’a nĩ ũla mũnene wa asikalĩ ĩana, amũnenga Yosevu ũla mwĩĩ.'),
('kam', 'MRK', 15, 46, 'Na athooa ngũa ya katane, na amumya nthĩ, na amũlingĩla ĩla ngũa ya katane, na amwia mbũanĩ ĩla yasĩtwe ĩvianĩ ĩnene; na avingilitya ĩvia mũomonĩ wa mbũa.'),
('kam', 'MRK', 15, 47, 'Na Meli Makatalene na Meli inyia wa Yose moona vala waiiwe.'),
('kam', 'MRK', 16, 1, 'Na mũthenya wa savato wathela, Meli Makatalene, na Meli inyia wa Yakovo, na Salome, mathooa mĩtĩ yĩ mũuke mũseo, nĩ kana maende mamũvake.'),
('kam', 'MRK', 16, 2, 'Na kĩoko tene, mũthenya wa mbee wa kyumwa, mathi mavika mbũanĩ syũa yĩkyuma.'),
('kam', 'MRK', 16, 3, 'Na maneenan’ya ene kwa ene, Nũũ ũla ũnũũtũvingilitĩlya ĩvia yume mũomonĩ wa mbũa?'),
('kam', 'MRK', 16, 4, 'Na mookĩlya metho, moona kana ĩvia nĩyĩvingilitilw’e: nũndũ yaĩ ĩnene mũno.'),
('kam', 'MRK', 16, 5, 'Na makĩlika mbũanĩ, moona mwanake ailyĩ ngalĩ ya kw’oko kwa aũme, ekĩĩte ngũa nzaũ ndasa; na maseng’a.'),
('kam', 'MRK', 16, 6, 'Na amea, Mũikaseng’e; mwĩmantha Yesũ Mũnasaleti, ũla ũnambiwe; nũthayũũkĩte; nde vaa: sisyai, vandũ vala manamwiĩte!'),
('kam', 'MRK', 16, 7, 'Ĩndĩ endai, mũkamatavye amanyĩw’a make na Vetelo, atĩĩ, Etongosya mbee wenyu kũthi Kalilii: nĩkw’o mũkamwona, o tondũ wamũtavisye.'),
('kam', 'MRK', 16, 8, 'Na maumaala mbũanĩ, masemba; nũndũ makwatiwe nĩ kũtetema na kũseng’a: o na matyaatavya mũndũ ũndũ; nũndũ nĩmakĩaa.'),
('kam', 'MRK', 16, 9, 'Na Yesũ athayũũka kĩoko tene, mũthenya wa mbee wa kyumwa, amba ũmumĩlĩla Meli Makatalene, ũla waumiw’e nĩwe ndaimoni mũonza.'),
('kam', 'MRK', 16, 10, 'Nake athi amatavya ala maĩ vamwe nake ũvoo, me na kĩmeto na kĩĩo.'),
('kam', 'MRK', 16, 11, 'Nao meew’a kana e thayũ, na nĩwoniwe nĩwe, malea kwĩtĩkĩla.'),
('kam', 'MRK', 16, 12, 'Na ĩtina wa maũndũ asu amaumĩlĩla andũ elĩ moo, e na mũvw’ano ũngĩ, maendete na nzĩa makĩthi na ku ndee.'),
('kam', 'MRK', 16, 13, 'Nao mathi na matavya ala angĩ: o na asu mainametĩkĩla.'),
('kam', 'MRK', 16, 14, 'Na ĩtina amaumĩlĩla ala ĩkũmi na ũmwe mailyĩ makĩya; na amakan’ya nũndũ wa kũlea kwĩtĩkĩla kwoo na nũndũ wa wũmũ wa ngoo syoo, nũndũ mainametĩkĩla ala mamwonie ĩtina wa kũthayũũka kwake.'),
('kam', 'MRK', 16, 15, 'Na amea, Endai inyw’ĩ nthĩ yonthe, mũkaitavye syũmbe syonthe ũvoo mũseo.'),
('kam', 'MRK', 16, 16, 'Ũla ũnũkwĩtĩkĩla na kũvatiswa akatangĩĩwa; ĩndĩ ũla ũtekwĩtĩkĩla akasilĩlwa.'),
('kam', 'MRK', 16, 17, 'Na syama ii ikamaatĩĩa ala meĩtĩkĩla: syĩtwanĩ yakwa makaumya ndaimoni; makaneena na ithyomo nzaũ;'),
('kam', 'MRK', 16, 18, 'makakwata nzoka, na ethĩwa makanyw’a kĩndũ kyũaa, kĩĩkamathũkya nongi; makamailĩĩla moko ala awau, na makavoa.'),
('kam', 'MRK', 16, 19, 'Na ĩndĩ Mwĩaĩi Yesũ amina kũneena nao, atwawa ĩũlũ ĩtunĩ, na ekala nthĩ ngalĩ ya kw’oko kwa aũme kwa Ngai.'),
('kam', 'MRK', 16, 20, 'Nao mathi, matavan’ya ũvoo mũseo kũndũ kw’onthe, Mwĩaĩi akĩtethya wĩa vamwe nao, na akĩlũlũmĩlya ĩla ndeto na syama ila syaendanasya nayo. Ameni.'),
('kam', 'LUK', 1, 1, 'Nĩkwĩthĩwa andũ aingĩ nĩmatatie kũandĩka ũvoo wa maũndũ ala meanĩiw’e katĩ waitũ,'),
('kam', 'LUK', 1, 2, 'na matũnengie ithyĩ, nũndũ maĩ ngũsĩ sya kwona na metho, na athũkũmi ma ĩ ndeto kuma mwambĩlĩlyonĩ,'),
('kam', 'LUK', 1, 3, 'na nĩkwĩthĩwa nĩneekuũĩte nesa vala maũndũ asu onthe maumie, nĩnonete nĩ ũseo nyie ngũandĩkĩe nĩatĩanĩsye, Theovilo mũtaĩwa;'),
('kam', 'LUK', 1, 4, 'nĩ kana ũmanye w’o wa maũndũ ala wamanyĩiw’e.'),
('kam', 'LUK', 1, 5, 'Tene, ĩvinda ya Elote mũsumbĩ wa Yutia, kwaĩ mũthembĩ ũmwe ũla wetawa Nzakalia, wa nguthu ya Aviya: na mũka wake aĩ wa mbaĩ ya Aluni, na syĩtwa yake eetawa Elisavethi.'),
('kam', 'LUK', 1, 6, 'Nao elĩ maĩ alũngalu mbee wa Ngai, makĩendeea mĩaonĩ yonthe na motw’ĩonĩ onthe ma Mwĩaĩi matyaailĩĩlĩka ũthũku.'),
('kam', 'LUK', 1, 7, 'Nao matyaĩ na kana, nũndũ Elisavethi aĩ ngũngũ, na me elĩ maĩ akũu.'),
('kam', 'LUK', 1, 8, 'Na ĩndĩ kweethĩwa, yĩla watethasya wĩa wa ũthembi mbee wa Ngai kũatĩanĩa na nguthu yake,'),
('kam', 'LUK', 1, 9, 'o ũndũ kwĩkawa wĩanĩ wa ũthembi, malimana, na atw’ĩka wa kũlika ĩkalũnĩ ya Mwĩaĩi atoeesye ũvani.'),
('kam', 'LUK', 1, 10, 'Na ĩkomano yonthe yekalĩte nza yĩkĩvoya ĩvinda ya kũtoeesya ũvani.'),
('kam', 'LUK', 1, 11, 'Na aumĩlĩlwa nĩ mũlaĩka wa Mwĩaĩi, mũlaĩka aũngeme ngalĩ ya kw’oko kwa aũme kwa kĩthembeo kya kũtoeesya ũvani.'),
('kam', 'LUK', 1, 12, 'Na Nzakalia amwona aũũya, na akwatwa nĩ w’ĩa.'),
('kam', 'LUK', 1, 13, 'Ĩndĩ ũla mũlaĩka amwĩa, Ndũkakĩe, Nzakalia: nĩkwĩthĩwa kũvoya kwaku nĩkwĩw’ĩkĩte, na mũka waku Elisavethi akakũsyaĩa kana kavĩsĩ, na ũkaketa syĩtwa yako Yoana.'),
('kam', 'LUK', 1, 14, 'Naku ũkeethĩwa na ũtanu na mũyo; na aingĩ makeew’a mũyo nũndũ wa kũsyawa kwako.'),
('kam', 'LUK', 1, 15, 'Nĩkwĩthĩwa akethĩwa e mũnene methonĩ ma Mwĩaĩi, na mbinyu kana kĩla kĩtoonasya ndakanyw’a; o na kuma ĩvunĩ ya nyinyia akeethĩwa ausũĩtwe nĩ Veva Mũtheu.'),
('kam', 'LUK', 1, 16, 'Na akamaalyũla aingĩ ma ana ma Isilaeli melekele Mwĩaĩi Ngai woo.'),
('kam', 'LUK', 1, 17, 'Nake akatongosya mbee wake na veva na vinya wa Eliya, athyũũe ngoo sya aaĩthe syelekele syana, na alei mathi nthĩnĩ wa ũĩ wa ala alũngalu; kũmũmbanĩsya Mwĩaĩi andũ ala mamũseũvĩw’e.'),
('kam', 'LUK', 1, 18, 'Na Nzakalia amũkũlya mũlaĩka, Ngamanya ata ũndũ ũũ? Nĩkwĩthĩwa nĩ mũkũu nyie, na mũka wakwa nĩ mũkũu.'),
('kam', 'LUK', 1, 19, 'Na mũlaĩka amũsũngĩa, amwĩa, Ninyie Kavilieli, ũla ũũngamaa mbee wa Ngai; nakwa ndũmiwe nũke kũneena naku, na ngũetee ũvoo ũũ mũseo.'),
('kam', 'LUK', 1, 20, 'Na sisya, nũkũkilya na ndwĩtonya kũneena, kũvika mũthenya ũla maũndũ asu makekĩka, nũndũ ndũnaĩkĩĩa ndeto syakwa, ila ikeanĩw’a ĩvinda yasyo.'),
('kam', 'LUK', 1, 21, 'Na andũ mamweteela Nzakalia, na maseng’a nũndũ wa kwĩkala kwake ĩkalũnĩ.'),
('kam', 'LUK', 1, 22, 'Nake yĩla waumaalile, ndaatonya kũneena nao: na mamanya nĩwona woni ĩkalũnĩ: na aneena namo na moko, na ekala atatonya kũneena.'),
('kam', 'LUK', 1, 23, 'Na kweethĩwa, yĩla matukũ meanĩie ma ũthũkũmi wake, athi nyũmba kwake.'),
('kam', 'LUK', 1, 24, 'Na ĩtina wa matukũ asu Elisavethi mũka wake aitava; na eevitha myei ĩtano, akyasya,'),
('kam', 'LUK', 1, 25, 'Ũũ nĩw’o Mwĩaĩi ũmbĩkĩte mĩthenya ĩla wanzyaĩĩsye, ambetee ntheko yakwa andũnĩ.'),
('kam', 'LUK', 1, 26, 'Na mwei wa thanthatũ mũlaĩka Kavilieli atũmwa nĩ Ngai ndũa ya Kalilii, ĩla yĩtawa Nasaleti,'),
('kam', 'LUK', 1, 27, 'kwa mwĩĩtu ũla wevaĩtw’e nĩ mũndũ wetawa Yosevu, wa mbaĩ ya Ndaviti; na syĩtwa ya mwĩĩtu ũsu nĩ Meli.'),
('kam', 'LUK', 1, 28, 'Na mũlaĩka athi vala waĩ, na amwĩa, Wakya, ũla wonew’e ũseo mũno, Mwĩaĩi e vamwe naku.'),
('kam', 'LUK', 1, 29, 'Nake aũũya mũno nũndũ wa ndeto isu, na asũanĩa ũndũ ngethi ĩsu ĩtilyĩ.'),
('kam', 'LUK', 1, 30, 'Na mũlaĩka amwĩa, Eka ũkĩa, Meli: nũndũ nĩwonew’e ũseo kwa Ngai.'),
('kam', 'LUK', 1, 31, 'Na sisya, ũkaitava, na ũkasyaa kana kavĩsĩ, na ũkaketa syĩtwa yako Yesũ.'),
('kam', 'LUK', 1, 32, 'Nake akethĩwa e mũnene, na aketawa Mwana wa Ũla Wĩ Ĩũlũ wa Onthe: na Mwĩaĩi Ngai nũkamũnenga kĩvĩla kya ũsumbĩ kya ĩthe wake Ndaviti:'),
('kam', 'LUK', 1, 33, 'nake nũkasumbĩka mbaĩ ya Yakovo tene na tene; na ũsumbĩ wake ndũkethĩwa na mũminũkĩlyo.'),
('kam', 'LUK', 1, 34, 'Na Meli amũkũlya mũlaĩka, Ũndũ ũũ ũkeekĩka ata, nakwa ndyĩsĩ mũndũ mũũme?'),
('kam', 'LUK', 1, 35, 'Na mũlaĩka amũsũngĩa, amwĩa, Veva Mũtheu akooka ĩũlũ waku, na vinya wa Ũla Wĩ Ĩũlũ wa Onthe akakwĩkĩa muunyĩ: kwondũ wa ũu kĩla kĩtheu kĩsyawa kĩketawa Mwana wa Ngai.'),
('kam', 'LUK', 1, 36, 'Na sisya, Elisavethi ũla wa mbaĩ yaku, nũitavĩte kavĩsĩ nake nĩ mũkũu; na ũũ nĩ mwei wa thanthatũ wake ũla wetawa ngũngũ.'),
('kam', 'LUK', 1, 37, 'Nĩkwĩthĩwa kwa Ngai vai ũndũ ũtatonyeka.'),
('kam', 'LUK', 1, 38, 'Na Meli asya, Sisya, nyie nĩ ngombo ya Mwĩaĩi; nĩwĩthĩwe kwakwa o ta ndeto syaku. Na mũlaĩka amũtia athi.'),
('kam', 'LUK', 1, 39, 'Na matukũ asu Meli ookĩla athi mĩtũkĩ nthĩ ĩla yĩ iĩma, ndũanĩ ĩmwe ya Yutia;'),
('kam', 'LUK', 1, 40, 'na avota nyũmbanĩ ya Nzakalia amũkethya Elisavethi.'),
('kam', 'LUK', 1, 41, 'Na kweethĩwa, yĩla Elisavethi wewie ngethi ya Meli, kana kathaka ĩvunĩ yake; na Elisavethi ausũwa nĩ Veva Mũtheu;'),
('kam', 'LUK', 1, 42, 'na ookĩlya wasya wake aneena mũno, akyasya, Nũathimĩtwe we katĩ wa aka, na ũsyao wa ĩvu yaku nũathimĩtwe.'),
('kam', 'LUK', 1, 43, 'Ũndũ ũũ nata kwakwa, kana inyia wa Mwĩaĩi wakwa ambũkĩe?'),
('kam', 'LUK', 1, 44, 'Nũndũ sisya, yĩla ngethi yaku yalika matũnĩ makwa, kana nĩkathaka nĩ mũyo ĩvunĩ yakwa.'),
('kam', 'LUK', 1, 45, 'Na kũathimwa nĩ ũsu ũla wetĩkĩlile; nũndũ maũndũ ala wataviw’e nĩ Mwĩaĩi makeanĩw’a.'),
('kam', 'LUK', 1, 46, 'Na Meli asya atĩĩ, Ngoo yakwa nĩnĩũmũtaĩa Mwĩaĩi,'),
('kam', 'LUK', 1, 47, 'Na veva wakwa nũmũtanĩe Ngai, Mũtangĩĩi wakwa.'),
('kam', 'LUK', 1, 48, 'Nĩkwĩthĩwa asyaĩtye ũnini wa ngombo yake: Nũndũ sisya, kuma yu nzyawa syonthe ikambĩtaa mũathime.'),
('kam', 'LUK', 1, 49, 'Nĩkwĩthĩwa ũla wĩ vinya nũmbĩkĩte maũndũ manene; Na syĩtwa yake nĩ ĩtheu.'),
('kam', 'LUK', 1, 50, 'Na tei wake nũkwoneka nĩ nzyawa na nzyawa Kwa ala mamũkĩaa.'),
('kam', 'LUK', 1, 51, 'Nĩwonanĩtye vinya na kw’oko kwake; Na nũmanyaĩĩkĩtye ala mekwĩng’athĩlĩlya mavindyonĩ ma ngoo syoo.'),
('kam', 'LUK', 1, 52, 'Ala anene nũmaumĩtye ivĩlanĩ sya ũsumbĩ, Na nũmanenevetye ala anini.'),
('kam', 'LUK', 1, 53, 'Ala me na nzaa nũmavũnĩtye na maũndũ maseo; Na ala athwii nũmalũngĩtye me athei.'),
('kam', 'LUK', 1, 54, 'Nũmatethetye Isilaeli, mũthũkũmi wake, Nĩ kana alilikane kũmwĩw’ĩa tei'),
('kam', 'LUK', 1, 55, 'Avalaamu na ũsyao wake tene na tene (O tondũ waneenie na aaĩthe maitũ).'),
('kam', 'LUK', 1, 56, 'Na Meli ekala nake ta myei ĩtatũ, na asyoka kwoo.'),
('kam', 'LUK', 1, 57, 'Na matukũ ma Elisavethi meanĩa ma ũsyaa; na asyaa kana kavĩsĩ.'),
('kam', 'LUK', 1, 58, 'Na atũi make na andũ ma mbaĩ yake meew’a ũndũ Mwĩaĩi wamwingĩvĩsye tei; matana vamwe nake.'),
('kam', 'LUK', 1, 59, 'Na ĩndĩ kweethĩwa mũthenya wa nyanya, mooka kwaĩka kana; na menda kũketa Nzakalia, ta syĩtwa ya ĩthe wako.'),
('kam', 'LUK', 1, 60, 'Ĩndĩ inyia wako asũngĩa, akyasya, Aiee, ti w’o; nĩketwe Yoana.'),
('kam', 'LUK', 1, 61, 'Na mamwĩa, Kwa mbaa au vai wĩ na syĩtwa yĩu.'),
('kam', 'LUK', 1, 62, 'Na mamũneen’ya ĩthe wako na moko, amon’ye ũndũ ũnũkwenda ketwe.'),
('kam', 'LUK', 1, 63, 'Nake ametya kĩndũ kya ũandĩka, na aandĩka, Syĩtwa yako nĩ Yoana. Na onthe maseng’a.'),
('kam', 'LUK', 1, 64, 'Na oyu kanyw’a wake wavingũwa, na ũĩmĩ wake wathaw’a, nake aneena, akĩmũkatha Ngai.'),
('kam', 'LUK', 1, 65, 'Na onthe ala maĩ ũtũinĩ makwatwa nĩ w’ĩa na maũndũ asu manyaĩĩkw’a nthĩ yonthe ya Yutia ĩla yĩ iĩma.'),
('kam', 'LUK', 1, 66, 'Na onthe ala meewie maũndũ asu mamaia ngoonĩ syoo, makyasya, Kana kau kakethĩwa kailyĩ ata? Nũndũ kw’oko kwa Mwĩaĩi kwaĩ vamwe nako.'),
('kam', 'LUK', 1, 67, 'Na Nzakalia ĩthe wako ausũwa nĩ Veva Mũtheu, na athana, akyasya,'),
('kam', 'LUK', 1, 68, 'Mwĩaĩi, Ngai wa Isilaeli, nakathwe; Nũndũ nũmokĩe andũ make na kũmovosya,'),
('kam', 'LUK', 1, 69, 'Na nũtũkĩlĩlye ũvya wa ũtangĩĩo Nyũmbanĩ ya Ndaviti, mũthũkũmi wake'),
('kam', 'LUK', 1, 70, '(Tondũ waneenie na makanyw’a ma athani make atheu ala maĩ kw’o kuma tene),'),
('kam', 'LUK', 1, 71, 'Ũtangĩĩo kuma amaithanĩ maitũ, o na mokonĩ ma onthe ala matũmenaa;'),
('kam', 'LUK', 1, 72, 'Amon’ye aasa maitũ tei, Na kũlilikana ũtianĩo wake mũtheu;'),
('kam', 'LUK', 1, 73, 'Wĩvĩto ũla wevĩtĩe asa waitũ Avalaamu,'),
('kam', 'LUK', 1, 74, 'Kana, twavonoka mokonĩ ma amaitha maitũ, akatũnenga ithyĩ Kũmũthũkũma tũte na w’ĩa,'),
('kam', 'LUK', 1, 75, 'Twĩ na ũtheu na ũlũngalu kwake mĩthenya yaitũ yonthe.'),
('kam', 'LUK', 1, 76, 'Naku we, kana, ũkeetawa mwathani wa Ũla Wĩ Ĩũlũ wa Onthe: Nũndũ ũkatongosya mbee wa Mwĩaĩi ũmũseũvĩsye nzĩa syake;'),
('kam', 'LUK', 1, 77, 'Na kũnenga andũ make ũmanyi wa ũtangĩĩo Kwondũ wa kũekewa naĩ syoo,'),
('kam', 'LUK', 1, 78, 'Nũndũ wa ĩnee ĩnene ya Ngai waitũ, Yĩla kwondũ wayo kyeni kya kũikya kyumĩte ĩũlũ nĩkĩtũvikĩe,'),
('kam', 'LUK', 1, 79, 'Kĩmamulĩke ala mekalaa kĩvindunĩ na kyuunĩ kya kikw’ũ; Kĩtũtongoesye maũũ maitũ nzĩanĩ ya mũuo.'),
('kam', 'LUK', 1, 80, 'Na kana kaneneva, kakyongelwa vinya vevanĩ, na kekalaa kũla kũte andũ kũvika mũthenya wa kumĩla kwake kwa Isilaeli.'),
('kam', 'LUK', 2, 1, 'Na kweethĩwa matukũ asu mwĩao waumie kwa Kaisali Aukusito, nĩ kana andũ onthe maandĩkwe.'),
('kam', 'LUK', 2, 2, 'Na kũandĩka kũu kwaĩ kwa mbee yĩla Kwilinio waĩ ngavana wa Silia.'),
('kam', 'LUK', 2, 3, 'Na onthe mathi kũandĩkwa, kĩla mũndũ ndũanĩ yoo.'),
('kam', 'LUK', 2, 4, 'Na Yosevu nake ambata kuma Nasaleti, ndũa ĩmwe ya Kalilii, athi Yutia, avika ndũanĩ ya Ndaviti, ĩla yĩtawa Mbethelemu, nũndũ we aĩ wa nyũmba ya mũvĩa wa Ndaviti;'),
('kam', 'LUK', 2, 5, 'ni kana aandĩkwe vamwe na Meli, ũla wevaĩtye, nake aĩ mũito.'),
('kam', 'LUK', 2, 6, 'Na kweethĩwa, yĩla maĩ kw’o, matukũ make mavika ma ũsyaa.'),
('kam', 'LUK', 2, 7, 'Na asyaa kana kavĩsĩ ka mbee; na akavw’ĩka ngũa sya ũkenge, na akakomya mũvalatĩnĩ, nũndũ nyũmbanĩ ya aeni vaiaĩ ũthei woo.'),
('kam', 'LUK', 2, 8, 'Na nthĩ ĩsu kwaĩ aĩthi mekalaa weũnĩ, maisyaĩĩsya indo syoo ũtukũ.'),
('kam', 'LUK', 2, 9, 'Nao maumĩlĩlwa nĩ mũlaĩka wa Mwĩaĩi, na ũtheu mũtisu wa Mwĩaĩi wamamulĩka; nao makĩa mũno.'),
('kam', 'LUK', 2, 10, 'Na mũlaĩka amea, Ekai ũkĩa; nũndũ sisyai, nyie nĩnamũetee ũvoo mũseo wa ũtanu mũnene ũla ũkethĩwa wa andũ onthe:'),
('kam', 'LUK', 2, 11, 'nũndũ ũmũnthĩ, ndũanĩ ya Ndaviti, nĩmũsyaĩwe Mũtangĩĩi, nake nĩ Klĩsto ũla Mwĩaĩi.'),
('kam', 'LUK', 2, 12, 'Na wonan’yo kwenyu nĩ atĩĩ: Mũkoona kana kavw’ĩkĩtwe ngũa sya ũkenge, kamamĩtw’e mũvalatĩnĩ.'),
('kam', 'LUK', 2, 13, 'Na o kavinda kau, kwethĩwa vamwe na ũla mũlaĩka aingĩ ma nguthu ya ĩtunĩ, makĩmũkumya Ngai, makyasya,'),
('kam', 'LUK', 2, 14, 'Ngai nataĩwe ku ĩũĩũ mũno, Na mũuo wĩthĩwe kũũ nthĩ andũnĩ ala wendeeaw’a nĩmo.'),
('kam', 'LUK', 2, 15, 'Na kweethĩwa, yĩla alaĩka mamatiie makĩthi ĩtuni, aĩthi maneenan’ya ene kwa ene, Tũendei yu Mbethelemu, tũsisye ũndũ ũũ ũla weekĩka, ũla Mwĩaĩi watũmanyĩthya.'),
('kam', 'LUK', 2, 16, 'Na mathi mĩtũkĩ, na meethĩa Meli na Yosevu, na kala kaũkenge kamamĩtw’e mũvalatĩnĩ.'),
('kam', 'LUK', 2, 17, 'Na makona, matavan’ya ndeto ila mataviw’e ũndũ wa kala kana.'),
('kam', 'LUK', 2, 18, 'Na onthe ala meewie maseng’a kwondũ wa maũndũ ala mataviw’e nĩ aĩthi.'),
('kam', 'LUK', 2, 19, 'Ĩndĩ Meli ekalya ndeto isu syonthe ngoonĩ yake, akĩsũanĩa.'),
('kam', 'LUK', 2, 20, 'Na aĩthi masyoka, maimũtaĩa na maimũkumya Ngai ũndũ wa maũndũ onthe ala meewie na moonie, o tondũ mataviw’e.'),
('kam', 'LUK', 2, 21, 'Na matukũ nyanya mavika ma kũkaĩka, syĩtwa yako keetwa Yesũ, o tondũ keetiwe nĩ mũlaĩka katanamba kũitavwa.'),
('kam', 'LUK', 2, 22, 'Na matukũ meanĩa ma kwĩthesya kwoo kwĩanana na mĩao ya Mose, mambata nako Yelusaleme, kakanenganwe kwa Mwĩaĩi'),
('kam', 'LUK', 2, 23, '(o tondũ kũandĩkĩtwe mĩaonĩ ya Mwĩaĩi, Kala kaũme kakasyawa mbee kaketawa katheu ka Mwĩaĩi),'),
('kam', 'LUK', 2, 24, 'na nĩ kana maumye nthembo o tondũ kwaĩtw’e mĩaonĩ ya Mwĩaĩi, Ndumbũ ilĩ, kana maswii elĩ ma mavũĩ.'),
('kam', 'LUK', 2, 25, 'Na ĩndĩ Yelusaleme kwaĩ mũndũ wetawa Simeoni; nake aĩ mũlũngalu na aĩ mũkĩi wa Ngai, akyeteela ũkiakisyo wa Isilaeli: na Veva Mũtheu aĩ ĩũlũ wake.'),
('kam', 'LUK', 2, 26, 'Nake nĩwonetw’e nĩ Veva Mũtheu, kana ndakona kĩkw’ũ, atanona ũla Klĩsto wa Mwĩaĩi.'),
('kam', 'LUK', 2, 27, 'Nake ooka ĩkalũnĩ atongoew’e nĩ Veva: na ĩthe na inyia mavota na kala kana Yesũ, nĩ kana meke nako tondũ wĩaĩtwe mĩaonĩ,'),
('kam', 'LUK', 2, 28, 'nake ĩndĩ akosa kana mokonĩ make, na amũkatha Ngai, akyasya,'),
('kam', 'LUK', 2, 29, 'Yu ĩndĩ, Mwĩaĩi, ngombo yaku nĩthi na mũuo, Tondũ waneenie;'),
('kam', 'LUK', 2, 30, 'Nĩkwĩthĩwa metho makwa nĩmoona ũtangĩĩo waku,'),
('kam', 'LUK', 2, 31, 'Ũla ũseũvĩtye mbee wa andũ onthe;'),
('kam', 'LUK', 2, 32, 'Kyeni kya kũmavuanĩsya Andũ‐ma‐mbaĩ‐ingĩ, Na ũtaĩo wa andũ maku Isilaeli.'),
('kam', 'LUK', 2, 33, 'Na ĩthe na inyia wako maseng’a ũndũ wa maũndũ ala maneeniwe ũndũ wako;'),
('kam', 'LUK', 2, 34, 'na Simeoni amaathima, na amwĩa Meli inyia wako, Nĩwene, kana kaa kaiĩtwe kethĩwe ũvalũko na wũkĩlo wa aingĩ ma Isilaeli; na wonan’yo ũla ũkakananĩw’a mũno;'),
('kam', 'LUK', 2, 35, 'ĩĩ, na ũvyũ ũkatonya ngoo yaku; nĩ kana mosũanĩo ma ngoo nyingĩ mavuanw’e.'),
('kam', 'LUK', 2, 36, 'Na vo vaĩ mwathani mũndũ mũka, ũla wetawa Ana, mwĩĩtu wa Vanueli, wa mbaĩ ya Aseli (nake aĩ mũkũu mũno, na nĩwekalĩte myaka mũonza na mũũme wake ĩtina wa wĩĩtu wake,'),
('kam', 'LUK', 2, 37, 'nake aĩ ndiwa myaka mĩongo nyanya na ĩna), o na ndaumaa ĩkalũnĩ, akĩthaitha na kũtĩĩa kũya na kwĩsũvana ũtukũ na mũthenya.'),
('kam', 'LUK', 2, 38, 'Nake ooka kavinda kau amũtũngĩa Ngai mũvea, na amatavya onthe ala meteele wovosyo wa Yelusaleme ũvoo wako.'),
('kam', 'LUK', 2, 39, 'Na mamina kwĩanĩsya maũndũ onthe ala meeaĩtwe mĩaonĩ ya Mwĩaĩi, masyoka Kalilii, na mathi ndũanĩ yoo Nasaleti.'),
('kam', 'LUK', 2, 40, 'Na kana kaneneva, na keethĩwa na vinya, na kausũwa nĩ ũĩ: na mumo wa Ngai waĩ ĩũlũ wako.'),
('kam', 'LUK', 2, 41, 'Na kĩla mwaka ĩthe na inyia wako maendaa Yelusaleme ĩvinda ya mboka ya vasaka.'),
('kam', 'LUK', 2, 42, 'Na kavikya myaka ĩkũmi na ĩlĩ, mambata o tondũ kweekawa ĩvinda ya mboka ĩsu;'),
('kam', 'LUK', 2, 43, 'na matukũ meanĩa, masyoka, na kĩvĩsĩ Yesũ kyatiwa Yelusaleme; ĩndĩ ĩthe na inyia wakyo maiaamanya ũu;'),
('kam', 'LUK', 2, 44, 'ĩndĩ matalĩthasya kĩ o vamwe namo nguthunĩ, na mathi mũendo wa syũa ĩima; na mambĩlĩlya ũkĩmantha andũnĩ ma mbaĩ yoo na andũnĩ ala meesene namo;'),
('kam', 'LUK', 2, 45, 'na malea ũkyona, masyoka Yelusaleme, maikĩmantha.'),
('kam', 'LUK', 2, 46, 'Na kweethĩwa, matukũ atatũ mathela makyona ĩkalũnĩ, kĩilyĩ katĩ wa amanyĩsya ma mĩao, kĩimethukĩĩsya, na kĩimakũlya mokũlyo:'),
('kam', 'LUK', 2, 47, 'na onthe ala makĩwie maseng’a ũndũ wa ũmnayi wakyo na mosũngĩo makyo.'),
('kam', 'LUK', 2, 48, 'Nao makyona, maseng’a; na inyia wakyo akĩkũlya, Mwana wakwa, ũtwĩkie ũu nĩkĩ? Nĩwene, au waku nakwa tũkũmanthie na kyeva.'),
('kam', 'LUK', 2, 49, 'Nakyo kyamea, Mwĩmanthĩaa kĩ? Mũiĩsĩ kana nĩnaĩlwe kwithĩwa wĩanĩ wa Asa wakwa?'),
('kam', 'LUK', 2, 50, 'Nao maiaamanya kĩtina kya ndeto ila kyamatavya.'),
('kam', 'LUK', 2, 51, 'Nakyo kyatheea nao, kũvika Nasaleti: na kyamenyivĩsya; na inyia wakyo aia maũndũ asu onthe ngoonĩ yake.'),
('kam', 'LUK', 2, 52, 'Na Yesũ aendeea akyũĩva na akĩana, e mwaĩlu kwa Ngai na kwa andũ.'),
('kam', 'LUK', 3, 1, 'Mwaka wa ĩkũmi na katano wa kũsumbĩka kwa Tivelio Kaisali, yĩla Vondio Vilato waĩ ngavana wa Yutia, na Elote waĩ mũsumbĩ wa Kalilii, na mwana‐a‐inyia wake Vilivu mũsumbĩ wa nthĩ ya Itulea na Takakoniti, na Lisania mũsumbĩ wa Avilene,'),
('kam', 'LUK', 3, 2, 'na yĩla Anasi na Kaiava maĩ athembi anene, ndeto ya Ngai yamũkie Yoana mwana wa Nzakalia e weũnĩ.'),
('kam', 'LUK', 3, 3, 'Nake athi nthĩ yonthe ĩla yĩ ũtee wa ũsĩ wa Yolotani, akĩtavan’ya ũvatiso wa ũalyũlo wa ngoo ũetae ũekeo wa naĩ;'),
('kam', 'LUK', 3, 4, 'o tondũ kũandĩkĩtwe ĩvukunĩ ya ndeto sya mwathani Isaia, Wasya wa mũndũ akĩneena mũno weũnĩ, Seũvyai nzĩa ya Mwĩaĩi, Lũngalyai moendelo make.'),
('kam', 'LUK', 3, 5, 'Syanda syonthe ikalindwa, Na iĩma na tũlĩma tw’onthe ikeananw’a na nthi; Na ila nthyoeku ikalũngalw’a, Na nzĩa ila nthũku ikatindimalw’a;'),
('kam', 'LUK', 3, 6, 'Na mĩĩ yonthe ĩkoona ũtangĩĩo wa Ngai.'),
('kam', 'LUK', 3, 7, 'Na ĩndĩ amea makomano ala mookaa kũvatiswa nĩwe, Inyw’ĩ ũsyao wa nzoka mbai, nũũ ũla ũmwonetye kũkĩa ũthatu ũla wũkĩte?'),
('kam', 'LUK', 3, 8, 'Syaai ĩndĩ ũsyao ũla waĩle ũalyũlo wa ngoo, na mũtikambĩlĩlye kwasya nthĩnĩ wenyu, Twĩ na asa waitũ Avalaamu: nũndũ nĩngũmwĩa, kana Ngai nũtonya kũmũkĩlĩlya Avalaamu syana mavianĩ aa.'),
('kam', 'LUK', 3, 9, 'O na yu ĩthoka nĩyiĩtwe matinanĩ ma mĩtĩ: kwondũ wa ũu kĩla mũtĩ ũtasyaaa ũsyao mũseo nũtemawa, na kwĩkw’a mwakinĩ.'),
('kam', 'LUK', 3, 10, 'Na makomano mamũkũlya makyasya, Twaĩlwe nĩ kwĩka ata ĩndĩ?'),
('kam', 'LUK', 3, 11, 'Amasũngĩa, amea, Ũla wĩ na itonyeo ilĩ, namũaĩe ũla ũtaĩ; na ũla wĩ na lĩu, eke o ũu.'),
('kam', 'LUK', 3, 12, 'Na aumya ma koti mooka kũvatiswa, nao mamũkũlya atĩĩ, Mũmanyĩsya, naitũ twaĩlwe nĩ kwĩka ata?'),
('kam', 'LUK', 3, 13, 'Nake amea, Mũĩkaumĩthye mbee wa ũndũ mwĩaĩwe.'),
('kam', 'LUK', 3, 14, 'Na asikalĩ namo mamũkũlya, makyasya, Naitũ twaĩlwe nĩ kwĩka ata? Na amasũngĩa, Manyai kũmũvena mũndũ kĩndũ na vinya, kana kũmũvinganĩsya ũndũ ũte wa w’o; na ĩanĩwai nĩ ĩtuvi yenyu.'),
('kam', 'LUK', 3, 15, 'Na yĩla andũ mekalĩte makĩsyaĩĩsya, na andũ onthe makĩsũanĩa ngoonĩ syoo ũvoo wa Yoana, kana nokwĩthĩwa nĩwe Klĩsto;'),
('kam', 'LUK', 3, 16, 'Yoana asũngĩa, na amea onthe, Nĩ w’o nyie nĩmũvatisaa na manzĩ; ĩndĩ nĩkũkĩte ũla wĩ vinya kũte nyie, nakwa ndyĩanĩwe nĩ kũthasya tũmĩkwa twa iatũ syake: ũsu akamũvatisaa na Veva Mũtheu na mwaki:'),
('kam', 'LUK', 3, 17, 'na kĩũlũkya kyake kĩ kw’okoni kwake, nake akathesya vyũ kĩvũĩo kyake, na akoomban’ya nganũ yake ĩkũmbĩnĩ yake; ĩndĩ wewa akavĩvya na mwaki ũtavoeka.'),
('kam', 'LUK', 3, 18, 'Nake nĩwamatavasya andũ ũla ũvoo mũseo vamwe na matao angĩ maingĩ;'),
('kam', 'LUK', 3, 19, 'ĩndĩ mũsumbĩ Elote, akĩkanw’a nĩwe ũndũ wa Elotia mũka wa mwana‐a‐inyia, na ũndũ wa maũndũ onthe mathũku ala Elote wekĩte,'),
('kam', 'LUK', 3, 20, 'ongela ũthũku ũngĩ ĩũlũ wa ala wekĩte, amũvingĩa Yoana kolokolonĩ.'),
('kam', 'LUK', 3, 21, 'Na kweethĩwa andũ onthe mavatiswa, nake Yesũ avatiswa, na akĩvoya, ĩtu yavingũka,'),
('kam', 'LUK', 3, 22, 'na Veva Mũtheu amũtheea e na mwĩĩ ũvw’ana ta wa ĩvũĩ, amũvũĩla, na wasya wauma ĩtunĩ, We nue Mwana wakwa mwendwa; nendeaaw’a nue.'),
('kam', 'LUK', 3, 23, 'Na Yesũ mwene, akyambĩlĩlya kũmanyĩsya, aĩ ta myaka mĩongo ĩtatũ, nake atalĩthaw’a kwĩthĩwa mwana wa Yosevu wa Eli,'),
('kam', 'LUK', 3, 24, 'wa Mathati, wa Livai, wa Meliki, wa Yanai, wa Yosevu,'),
('kam', 'LUK', 3, 25, 'wa Matathia, wa Amosi, wa Naumu, wa Esili, wa Nakai,'),
('kam', 'LUK', 3, 26, 'wa Maathi, wa Matathia, wa Semei, wa Yoseki, wa Yota,'),
('kam', 'LUK', 3, 27, 'wa Yoanani, wa Lesa, wa Nzeluvaveli, wa Sealitieli, wa Neli,'),
('kam', 'LUK', 3, 28, 'wa Meliki, wa Ati, wa Kosamu, wa Elimatamu, wa Eeli,'),
('kam', 'LUK', 3, 29, 'wa Yesua, wa Elieseli, wa Yolimu, wa Mathati, wa Livai,'),
('kam', 'LUK', 3, 30, 'wa Simeoni, wa Yutasi, wa Yosevu, wa Yonamu, wa Eliakimu,'),
('kam', 'LUK', 3, 31, 'wa Melea, wa Mena, wa Matatha, wa Nathani, wa Ndaviti,'),
('kam', 'LUK', 3, 32, 'wa Yese, wa Oveti, wa Mboasi, wa Salumoni, wa Nasoni,'),
('kam', 'LUK', 3, 33, 'wa Aminatavu, wa Alamu, wa Esiloni, wa Velesi, wa Yuta,'),
('kam', 'LUK', 3, 34, 'wa Yakovo, wa Isaka, wa Avalaamu, wa Tela, wa Naoli,'),
('kam', 'LUK', 3, 35, 'wa Seluki, wa Leu, wa Veleki, wa Eveli, wa Siela,'),
('kam', 'LUK', 3, 36, 'wa Kenani, wa Alivakasati, wa Semu, wa Noa, wa Lameki,'),
('kam', 'LUK', 3, 37, 'wa Methusela, wa Enoko, wa Yaleti, wa Maalaleli, wa Kenani,'),
('kam', 'LUK', 3, 38, 'wa Enosi, wa Sethi, wa Atamu, wa Ngai.'),
('kam', 'LUK', 4, 1, 'Na Yesũ, ausũĩtwe nĩ Veva Mũtheu, asyoka auma Yolotani, na atongoew’a nĩ Veva weũnĩ.'),
('kam', 'LUK', 4, 2, 'Akĩtatwa nĩ ndevili ĩvinda ya matukũ mĩongo ĩna. Na matukũ asu ndaĩsaa kĩndũ: na mathela, eew’a nzaa.'),
('kam', 'LUK', 4, 3, 'Na ndevili amwĩa atĩĩ, Ethĩwa nue Mwana wa Ngai, ĩaĩe ĩvia yĩĩ yĩtw’ĩke kĩmũtũ.'),
('kam', 'LUK', 4, 4, 'Na Yesũ amũsũngĩa, Nĩkũandĩkĩtwe, Mũndũ ndekalaa thayũ kwondũ na kĩmũtũ kyoka.'),
('kam', 'LUK', 4, 5, 'Na amũtongoesya kĩĩmanĩ ĩũlũ, na amwon’ya mosumbĩ onthe ma nthĩ kwa kaven’ya.'),
('kam', 'LUK', 4, 6, 'Na ndevili amwĩa atĩĩ, Nĩngũũnenga ũkũmũ ũũ w’onthe, na ndaĩa syamo: nũndũ nĩnanengiwe; nakwa nĩngũmũnenga o ũla ngwenda.'),
('kam', 'LUK', 4, 7, 'Ĩndĩ we ethĩwa nũũnthaitha, ũũ w’onthe ũkeethĩwa waku.'),
('kam', 'LUK', 4, 8, 'Yesũ amũsũngĩa, amwĩa, Nĩkũandĩkĩtwe, Mũthaithae Mwĩaĩi Ngai waku, na mũthũkũmae we, e weka.'),
('kam', 'LUK', 4, 9, 'Na amũtwaa Yelusaleme, amwĩkalya mũthyanĩ wa ĩkalũ, na amwĩa, Ethĩwa nue Mwana wa Ngai, ĩyĩkye nthĩ:'),
('kam', 'LUK', 4, 10, 'nũndũ nĩkũandĩkĩtwe, Akeeaĩa alaĩka make ũndũ waku, makũsũvĩe:'),
('kam', 'LUK', 4, 11, 'na ĩngĩ, Makakũkĩlya mokonĩ moo, Ndũkese kũtũlwa kũũ kwaku nĩ ĩvia.'),
('kam', 'LUK', 4, 12, 'Na Yesũ amũsũngia, amwĩa, Nĩkũneenetwe, Ndũkamũtate Mwĩaĩi Ngai waku.'),
('kam', 'LUK', 4, 13, 'Na ndevili amina matatwa onthe, athi amũtia ĩvinda.'),
('kam', 'LUK', 4, 14, 'Na Yesũ asyoka Kalilii vinyanĩ wa Veva: na nguma yake yausũa ndee syonthe sya nthĩ ĩsu.'),
('kam', 'LUK', 4, 15, 'Nake amanyĩsya masinakokenĩ moo, aikathwa nĩ andũ onthe.'),
('kam', 'LUK', 4, 16, 'Nake athi Nasaleti, vala waeewe: na alika ĩsinakokenĩ mũthenya wa savato, tondũ wekaa, na aũngama asome.'),
('kam', 'LUK', 4, 17, 'Anengwa ĩvuku ya mwathani Isaia. Na avuũa ĩvuku, oona vala vaandĩkĩtwe atĩĩ,'),
('kam', 'LUK', 4, 18, 'Veva wa Ngai e ĩũlũ wakwa, Nũndũ nĩwambĩtĩkĩsye mauta nĩtavye ngya ũvoo mũseo: Nũndũmĩte kũtavan’ya ũthasyo kwa ala atave, Na kũsalukw’a ililinda, Na kũthasya ala mavivinyĩtwe,'),
('kam', 'LUK', 4, 19, 'Na kũtavan’ya mwaka wa Mwĩaĩi ũla wĩtĩkĩlawa.'),
('kam', 'LUK', 4, 20, 'Na akũnza yĩla ĩvuku, anenga ũla mũthũkũmi, na ekala nthĩ: na onthe ala maĩ vo ĩsinakokenĩ mamũketeea.'),
('kam', 'LUK', 4, 21, 'Na ambĩlĩlya kũmea atĩĩ, Ũmũnthĩ ũandĩko ũũ nĩweanĩw’a matũnĩ menyu.'),
('kam', 'LUK', 4, 22, 'Na onthe mamũkũsĩaa, na maseng’a nũndũ wa ndeto sya mumo ila syaumie kanyw’anĩ wake: nao masya, Ũũ ti mwana wa Yosevu?'),
('kam', 'LUK', 4, 23, 'Nake amea atĩĩ, Vate ngananĩo mũkandavya nthimo ĩno, Mũiiti, ĩvosye mwene: ũndũ o na wĩva ũla tũneewie wĩkĩte Kavelinaumi, ĩka vaa nthĩ ĩ yaku.'),
('kam', 'LUK', 4, 24, 'Nake asya, Nĩ w’o nĩngũmwĩa, Vati mwathani ũla wĩtĩkĩlawa nthĩ ĩ yake.'),
('kam', 'LUK', 4, 25, 'Ĩndĩ nĩngũmũtavya w’o, Nthĩ ya Aisilaeli kwaĩ aka aingĩ ndiwa matukũ ma Eliya, yĩla ĩtu yavingĩtwe myaka ĩtatũ na myei thanthatũ, yĩla kwaĩ yũa ĩnene nthĩ ĩsu yonthe;'),
('kam', 'LUK', 4, 26, 'na Eliya ndaatũmwa kwa ũmwe wamo, ĩndĩ atũmiwe kwa ndiwa ĩmwe ya ndũa ya Nzalevathi, ya nthĩ ya Sitoni.'),
('kam', 'LUK', 4, 27, 'Na nthĩ ya Aisilaeli kwaĩ andũ aingĩ ala maĩ na mangũ ĩvinda ya mwathani Elisa; na vai ũmwe wamo waathew’a ate o Naamani, ũla Mũsilia.'),
('kam', 'LUK', 4, 28, 'Na onthe ala maĩ ĩsinakokenĩ, meew’a maũndũ asu mausũwa nĩ ũthilĩku;'),
('kam', 'LUK', 4, 29, 'na mookĩla, mamumya ndũanĩ, na mamũtwaa kũvika ĩũlũ wa kĩĩma kĩla kyakĩtwe ndũa yoo, nĩ kana makamwĩkĩlye vo akulumene.'),
('kam', 'LUK', 4, 30, 'Ĩndĩ avĩtĩla katĩ wamo, athi.'),
('kam', 'LUK', 4, 31, 'Na atheea athi Kavelinaumi, ndũa ĩmwe ya Kalilii. Nake amamanyĩsya mũthenya wa savato:'),
('kam', 'LUK', 4, 32, 'nao maseng’a ũndũ wa ũmanyĩsyo wake; nĩkwĩthĩwa ndeto syake syaĩ na ũkũmũ.'),
('kam', 'LUK', 4, 33, 'Na vau ĩsinakokenĩ vaĩ mũndũ ũla wakwetwe nĩ veva wa ndaimoni mbuku; nake aneena na wasya mũnene, akyasya,'),
('kam', 'LUK', 4, 34, 'Iĩ! Twĩ ũndũ naku wa kyaũ, Yesũ Mũnasaleti? Nĩwooka kũtwananga? Nĩngwĩsĩ we, wĩ Ũla Mũtheu wa Ngai.'),
('kam', 'LUK', 4, 35, 'Na Yesũ amĩkan’ya, akyasya, Tumya kanyw’a, noimuma. Na ĩla ndaimoni yamũvalũkya katĩ woo, yamuma, ĩtamwĩkĩte ũndũ.'),
('kam', 'LUK', 4, 36, 'Na onthe maseng’a, na maneenan’ya ene kwa ene, makyasya, Ndeto ĩno ĩtilyĩ ata? Nũndũ nũkwĩaĩa maveva mavuku na ũkũmũ na vinya, nao makyuma.'),
('kam', 'LUK', 4, 37, 'Na ũvoo wake wanyaĩĩka ndee syonthe, kĩla vandũ.'),
('kam', 'LUK', 4, 38, 'Nake aumaala ĩsinakokenĩ, avota nyũmbanĩ ya Simoni. Na inyia wa mũka wa Simoni aĩ na ndetema nyingĩ; na mamũvoya ũndũ wake.'),
('kam', 'LUK', 4, 39, 'Nake aũngama vakuvĩ nake, na akan’ya ndetema; nayo yamũtia: na o ĩvinda yĩu ookĩla amathũkũma.'),
('kam', 'LUK', 4, 40, 'Na syũa yĩkĩthũa, ala mawaĩtye andũ mowau ma mĩthemba mingĩ mamũetee; nake amailĩĩla kĩla mũndũ moko, na amavosya.'),
('kam', 'LUK', 4, 41, 'Na andũ aingĩ maumiw’e ndaimoni, iikaya, ikyasya, We wĩ Mwana wa Ngai. Nake aikan’ya, na aivata kũneena, nĩkwĩthĩwa nasyo nĩsyeesĩ nĩwe Klĩsto.'),
('kam', 'LUK', 4, 42, 'Na kwakya, auma vo athi vandũ vate andũ: na makomano mamũmantha, na mooka vala ũĩ, na menda kũmũsiĩĩa ndakamatie.'),
('kam', 'LUK', 4, 43, 'Ĩndĩ amea atĩĩ, Mũvaka nĩtavan’ye ũvoo mũseo wa ũsumbĩ wa Ngai ndũanĩ ila ingĩ nasyo: nũndũ natũmiwe nũndũ wa ũu.'),
('kam', 'LUK', 4, 44, 'Nake atavanasya masinakokenĩ ma Kalilii.'),
('kam', 'LUK', 5, 1, 'Na kweethĩwa, yĩla ĩkomano yĩkĩmũtindĩka yĩw’e ndeto ya Ngai, aũngeme ũtee wa ĩia ya Kenesaleti;'),
('kam', 'LUK', 5, 2, 'na oona ngalawa ilĩ ũtee wa ĩia; ĩndĩ atei ma makũyũ meethĩwa maumĩte, makĩthambya itei syoo.'),
('kam', 'LUK', 5, 3, 'Nake alika ngalawanĩ ĩmwe, ĩla ya Simoni, amũkũlya atwaange aumye ngũkanĩ vandũ vanini. Na ekala vo ngalawanĩ aimanyĩsya makomano.'),
('kam', 'LUK', 5, 4, 'Na amina ũneena, amwĩa Simoni, Twaa ngalawa vala ve kyũngũ, mũlikye itei syenyu nĩ kana mũkwatye.'),
('kam', 'LUK', 5, 5, 'Na Simoni amũsũngia, amwĩa, Mwĩaĩi, tũtethisye wĩa ũtukũ w’onthe, na tũinakwatya kĩndũ: ĩndĩ ũndũ wa ndeto syaku nĩngũlikya itei.'),
('kam', 'LUK', 5, 6, 'Na meeka ũu, makwatya makũyũ maingĩ; na itei syoo syambĩlĩlya kũtw’ĩkanga;'),
('kam', 'LUK', 5, 7, 'na mamavenesya ala maĩ ngwatanĩo nao ngalawanĩ ĩla ĩngĩ, moke kũmatethya. Nao mooka, na mausũsya ngalawa isu syelĩ, mũvaka syambĩlĩlya kũlika manzĩnĩ.'),
('kam', 'LUK', 5, 8, 'Ĩndĩ Simoni Vetelo, oona ũu, avalũka maunĩ ma Yesũ, akyasya, Uma vaa nĩĩ; nũndũ nyie nĩ mũndũ mwathe, Mwĩaĩi.'),
('kam', 'LUK', 5, 9, 'Nũndũ nĩwaseng’ie, na onthe ala maĩ nake, ũndũ wa wingĩ wa makũyũ ala makwatisye;'),
('kam', 'LUK', 5, 10, 'na Yakovo na Yoana, ana ma Sevetii, namo o ta ũu, ala maĩ ngwatanĩo na Simoni. Na Yesũ amwĩa Simoni, Manya ũkĩa; kuma yu ũkakwatasya andũ.'),
('kam', 'LUK', 5, 11, 'Na maete ngalawa syoo ngũkanĩ, matia syĩndũ syonthe, na mamũvikĩla.'),
('kam', 'LUK', 5, 12, 'Na kweethĩwa, yĩla waĩ ndũanĩ ĩmwe, sisya, kwaĩ mũndũ ũmwe ũmbĩtwe nĩ mangũ: na amwona Yesũ, eevalũkya nthĩ na ũthyũ, amwĩsũva, akyasya, Mwĩaĩi, ethĩwa nũkwenda, nũtonya kũnthesya.'),
('kam', 'LUK', 5, 13, 'Na atambũũkya kw’oko kwake, amũkiita, akyasya, Nĩngwenda; ĩthĩwa mũtheu. Na oyu mangũ mavoa.'),
('kam', 'LUK', 5, 14, 'Na amwĩaĩa ndakatavye mũndũ: ĩndĩ amwĩa, Thi ũkeyonan’ye kwa mũthembi, nokyumya nthembo ya kũthew’a kwaku, tondũ Mose weaie, yĩthĩwe ũkũsĩ kwoo.'),
('kam', 'LUK', 5, 15, 'Ĩndĩ ũvoo wake waingĩva mũno mbee: na andũ aingĩ makomana mamwĩw’e, na kũvow’a mowau moo.'),
('kam', 'LUK', 5, 16, 'Ĩndĩ we eeyathũkya athi vandũ vate andũ, avoye.'),
('kam', 'LUK', 5, 17, 'Na kweethĩwa mũthenya ũmwe yĩla wamanyĩasya, vaĩ Avalisi na amanyĩsya ma mĩao mailyĩ vo, ala maumĩte mĩsyĩ yonthe ya Kalilii, na ya Yutia, o na Yelusaleme: na vinya wa Mwĩaĩi wa kũvosya waĩ vamwe nake.'),
('kam', 'LUK', 5, 18, 'Na ĩndĩ aũme mooka makuĩte na ũkomo mũndũ waĩ na ũwau wa kwaa mamutha: na mamantha kũmũtwaa nthĩnĩ, na kũmwia mbee wake.'),
('kam', 'LUK', 5, 19, 'Nao malea kwona vandũ va ũmũtwaĩla nthĩnĩ nũndũ wa ĩkomano, malĩsa nyũmba ĩũlũ, mathaĩlya kĩalanĩ, mamũtheesya na ũkomo wake katĩ wa andũ vala ve Yesũ.'),
('kam', 'LUK', 5, 20, 'Nake oona mũĩkĩĩo woo, asya, Mũndũ we, naĩ syaku nĩsyaekwa.'),
('kam', 'LUK', 5, 21, 'Na aandĩki na Avalisi mambĩlĩlya kũsũanĩa, makyasya, Ũũ nũũ ũla ũnũũneena moumano? Nũũ ũtonya kũekea naĩ, ate o Ngai e weka?'),
('kam', 'LUK', 5, 22, 'Ĩndĩ Yesũ amanya mosũanĩo moo, asũngĩa na amea, Nĩkĩ mũũsũanĩa ũũ ngoonĩ syenyu?'),
('kam', 'LUK', 5, 23, 'Ũla ũvũthũ nĩ wĩva, nĩ kwasya, Naĩ syaku nĩsyaekwa; kana nĩ kwasya, Ũkĩla ũthi?'),
('kam', 'LUK', 5, 24, 'Ĩndĩ nĩ kana mũmanye Mwana wa mũndũ e na ũkũmũ kũũ nthĩ wa kũekea naĩ (amwĩa ũla waĩ na ũwau wa kwaa mamutha), Nĩngũkwĩa, Ũkĩla, nokyosa ũkomo waku, wĩnũke.'),
('kam', 'LUK', 5, 25, 'Na kavinda o kau ookĩla e mbee woo, na oosa kĩla wakomeaa, enũka, akĩmũkatha Ngai.'),
('kam', 'LUK', 5, 26, 'Na onthe maseng’a, na mamũkatha Ngai; na malikwa nĩ w’ĩa, makyasya, Ũmũnthĩ nĩtwonie maũndũ ma ũseng’ya.'),
('kam', 'LUK', 5, 27, 'Ĩtina wa maũndũ asu aumaala, na amwona mumya wa koti, ũla wetawa Livai, ekalĩte vala vaumĩaw’a koti, na amwĩa, Mbikĩla.'),
('kam', 'LUK', 5, 28, 'Nake atia syĩndũ syonthe, na ookĩla amũvikĩla.'),
('kam', 'LUK', 5, 29, 'Na Livai amũvokea mboka nene nyũmbanĩ kwake: na vaĩ aingĩ ma aumya ma koti na andũ angĩ mailyĩ nao makĩya lĩu.'),
('kam', 'LUK', 5, 30, 'Na Avalisi na aandĩki moo mamanyungunyĩĩsya amanyĩw’a make, makyasya, Nĩ ũndũ wa kĩ mũkũya na kũnyw’a vamwe na aumya ma koti na andũ athe?'),
('kam', 'LUK', 5, 31, 'Na Yesũ amasũngĩa, amea, Ala mate awau mati vata wa mũiiti; ĩndĩ no ala awau.'),
('kam', 'LUK', 5, 32, 'Ndyaaũka kwĩta ala alũngalu, ĩndĩ no ala athe maalyũle ngoo.'),
('kam', 'LUK', 5, 33, 'Nao mamwĩa, Amanyĩw’a ma Yoana nĩmatĩĩaa kũya mavinda maingi, makĩvoya; na ala ma Avalisi ta ũu; ĩndĩ aa maku nĩmeũya na kũnyw’a.'),
('kam', 'LUK', 5, 34, 'Na Yesũ amakũlya, Nĩmũtonya kũtuma ala metĩtwe mũtwaanonĩ matĩĩa kũya, yĩla mũtwaani wĩ vamwe nao?'),
('kam', 'LUK', 5, 35, 'Ĩndĩ mĩthenya nĩyũkĩte, yĩla mũtwaani ũkaumw’a kwoo, na nĩvo ĩndĩ makatĩĩa kũya mĩthenya ĩsu.'),
('kam', 'LUK', 5, 36, 'Ĩngĩ aneena na ngelekan’yo amatavya: Mũndũ ndatilaa kĩlio kya ngũa nzaũ alie ngũa ngũũ; nĩkwĩthĩwa eeka ũu nũkũtembũa ĩla nzaũ, na kĩlio kyu kyeũ kĩtyosana na ĩla ngũũ.'),
('kam', 'LUK', 5, 37, 'Na vai mũndũ wĩkĩaa mbinyu mbĩthĩ mathatwanĩ makũũ; nĩkwĩthĩwa eekĩa, mbinyu mbĩthĩ ĩkatembũa mathatwa asu, na ĩkĩtĩka, na mathatwa makyanangĩka.'),
('kam', 'LUK', 5, 38, 'Ĩndĩ mbinyu mbĩthĩ yaĩlwe nĩ kwĩkĩwa mathatwanĩ meũ.'),
('kam', 'LUK', 5, 39, 'Na vai mũndũ ũla waanyw’a mbinyu ngũũ ũnũkwenda ĩla mbĩthĩ; nũndũ easya, ĩla ngũũ nĩyo nzeo.'),
('kam', 'LUK', 6, 1, 'Na kweethĩwa mũthenya ũmwe wa savato, aendele mĩũndani ya nganũ, amanyĩw’a make matũla iia sya nganũ, maikiitha na nzaa, makĩya.'),
('kam', 'LUK', 6, 2, 'Na amwe ma Avalisi mamwĩa, Nũndũ wa kĩ mũkwĩka ũndũ ũtosana na ĩla mĩao ũkĩkwa mũthenya wa savato?'),
('kam', 'LUK', 6, 3, 'Yesũ amasũngĩa, amea, Mũiaasoma ũndũ Ndaviti wekie, yĩla waĩ na nzaa, we na ala maĩ nake;'),
('kam', 'LUK', 6, 4, 'ũndũ wavotie nyũmbanĩ ya Ngai, na oosa imũtũ ila syaiĩawa Ngai, na aya, na anenga ala maĩ nake; naw’o ndwosana na ĩla mĩao kũĩwa nĩ mũndũ ate o athembi oka?'),
('kam', 'LUK', 6, 5, 'Nake amea, Mwana wa mũndũ nĩ mwĩaĩi wa savato.'),
('kam', 'LUK', 6, 6, 'Na kweethĩwa mũthenya ũngĩ wa savato, avota ĩsinakokenĩ amanyĩsye: na vo vaĩ mũndũ waĩ na kw’oko kwa aũme kwau.'),
('kam', 'LUK', 6, 7, 'Na ala aandĩki na Avalisi mamũsyaĩĩsya, kana nũnũũvosya mũthenya wa savato; nĩ kana mone ũndũ wa kũmũvinganĩsya naw’o.'),
('kam', 'LUK', 6, 8, 'Nake nĩwesĩ mosũanĩo moo; na amwĩa ũla waĩ na kw’oko kwau, Ũkĩla ũũngame vaa katĩ. Nake ookĩla aũngama katĩ.'),
('kam', 'LUK', 6, 9, 'Na Yesũ amea, Nĩngũmũkũlya atĩĩ, Nĩkwosana na ĩla mĩao kwĩka nesa mũthenya wa savato, kana kwĩka ũthũku? Kũtangĩĩa thayũ, kana kũwananga?'),
('kam', 'LUK', 6, 10, 'Nake amasiangya onthe, na amwĩa ũla mũndũ, Tambũũkya kw’oko kwaku. Nake eeka ũu: na kw’oko kwavoa.'),
('kam', 'LUK', 6, 11, 'Ĩndĩ onthe mausũwa nĩ ũthatu ta me na ndũũka; na maneenan’ya makĩmantha ũndũ matonya kũmwĩka Yesũ.'),
('kam', 'LUK', 6, 12, 'Na kweethĩwa matukũ asu, ookĩla athi kĩĩmanĩ akavoye; na ekala ũtukũ w’onthe akĩvoya Ngai.'),
('kam', 'LUK', 6, 13, 'Na kwakya, ameta amanyĩw’a make; na anyuva ĩkũmi na elĩ katĩ woo, na asu ameta atũmwa:'),
('kam', 'LUK', 6, 14, 'Simoni, ũla wamũtw’ĩĩe syĩtwa ya kelĩ Vetelo, na mwana‐a‐inyia Andalea, na Yakovo na Yoana, na Vilivu na Valitholomayo,'),
('kam', 'LUK', 6, 15, 'na Mathayo na Thoma, na Yakovo wa Alivaio, na Simoni ũla wetawa Nzelote,'),
('kam', 'LUK', 6, 16, 'na Yutasi wa Yakovo, na Yutasi Isikalioti, ũla wesie kũmũvũnyanĩa;'),
('kam', 'LUK', 6, 17, 'na atheea nao, na aũngama vandũ vatindimalu, na ĩkomano ĩnene ya amanyĩw’a make, na andũ aingĩ ma Yutia kw’onthe na Yelusaleme, na ma nthĩ ya Tile na Sitoni ila syĩ ũtee wa ũkanga, ala mookie kũmwĩthukĩĩsya, na kũvow’a mowau moo:'),
('kam', 'LUK', 6, 18, 'na ala manyamaĩtw’e nĩ maveva mavuku mavow’a.'),
('kam', 'LUK', 6, 19, 'Na onthe ma ĩkomano mamantha kũmũkiita; nũndũ vinya waumie nthĩnĩ wake, na wamavosya onthe.'),
('kam', 'LUK', 6, 20, 'Nake ookĩlya metho make amasisya amanyĩw’a make, na asya atĩĩ, Mwĩ aathime inyw’ĩ ngya: nũndũ ũsumbĩ wa Ngai nĩ wenyu.'),
('kam', 'LUK', 6, 21, 'Mwĩ aathime inyw’ĩ ala mwĩ na nzaa yu: nũndũ mũkavũnw’a. Mwĩ aathime inyw’ĩ ala mũkũĩa yu: nũndũ mũkatheka.'),
('kam', 'LUK', 6, 22, 'Mwĩ aathime inyw’ĩ, yĩla andũ meũmũmena, na yĩla mekwĩvathana nenyu, na kũmũvũthya, na kũveta masyĩtwa menyu ta mathũku, kwondũ wa Mwana wa mũndũ.'),
('kam', 'LUK', 6, 23, 'Tanai mũthenya ũsu, mũtũlĩlange na ũtanu; nũndũ alĩlĩĩ, ĩtuvi yenyu nĩ ĩnene ĩtunĩ; now’o aaĩthe moo meekaa athani.'),
('kam', 'LUK', 6, 24, 'Ĩndĩ mwĩthĩwe na woo inyw’i athwii! Nĩkwĩthĩwa nĩmwoosie ũkiakisyo wenyu.'),
('kam', 'LUK', 6, 25, 'Mwĩthĩwe na woo, inyw’ĩ ala mũvũn’ye yu! Nũndũ nĩmũkew’a nzaa. Mwĩthĩwe na woo, inyw’ĩ ala mũũtheka yu! Nũndũ nĩmũkameta na kũĩa.'),
('kam', 'LUK', 6, 26, 'Mwĩthĩwe na woo inyw’ĩ, yĩla andũ onthe meũmũneenea nesa! Nĩkwĩthĩwa o ta ũu now’o aaĩthe moo mamekaa athani ma ũvũngũ.'),
('kam', 'LUK', 6, 27, 'Ĩndĩ inyw’ĩ ala mũkwĩw’a nĩngũmũtavya atĩĩ, Mendei amaitha menyu, mekei nesa ala meũmũmena,'),
('kam', 'LUK', 6, 28, 'maathimei ala mamwĩvĩkaa, mavoyeei ala mamũthĩnasya.'),
('kam', 'LUK', 6, 29, 'Ũla ũnũũkũkũna ũthĩa ũmwe mũthyũũĩe ũla ũngi; na ũla ũnũũkũvena ngũa yaku ya ĩũlũ manya ũmũvata kĩtonyeo kyaku.'),
('kam', 'LUK', 6, 30, 'Mũnenge ũla ũnũkwĩtya; na ũla unũũkũvena syĩndũ syaku ndũkamũkũlye.'),
('kam', 'LUK', 6, 31, 'Na ũndũ ũla mũkwenda kwĩkwa nĩ andũ, o ta ũu mekei o w’o.'),
('kam', 'LUK', 6, 32, 'Mũkĩmenda ala mamwendaa inyw’ĩ, mwĩ na ũseo wa kyaũ? O na ala athe no mendete ala mamendaa.'),
('kam', 'LUK', 6, 33, 'Na mũkĩmeka nesa ala mamwĩkaa inyw’ĩ nesa, mwĩ na ũseo wa kyaũ? O na athe no mekanaa ũu.'),
('kam', 'LUK', 6, 34, 'Na mũkĩmakovethya ala mũkwasya makamũĩva, mwĩ na ũseo wa kyaũ? O na athe no makovanaa, makĩtũngĩanĩa.'),
('kam', 'LUK', 6, 35, 'Ĩndĩ inyw’ĩ mendei amaitha menyu, mũmekae nesa, makovethyei, na mũiketeele mamũtũngĩe; na ĩtuvi yenyu yĩkethĩwa yĩ ĩnene, nenyu mũkethĩwa mwĩ ana ma Ũla Wĩ Ĩũlũ wa Onthe: nĩkwĩthĩwa nĩwe mũseo kwa ala mate mũvea na ala athũku.'),
('kam', 'LUK', 6, 36, 'Ĩthĩwai na tei, o ũndũ Ĩthe wenyu wĩ na tei.'),
('kam', 'LUK', 6, 37, 'Manyai ũsilĩla, na inywĩ mũikasilĩlwa: manyai kũtw’a, nenyu mũikatw’ĩĩwa: ekanĩai, nenyu mũkaekewa:'),
('kam', 'LUK', 6, 38, 'nenganei, nenyu mũkanengwa; kĩthimi kĩseo, kĩlate, kĩthingithye, na kĩtĩkĩlĩlye, makamũnenga kĩthũinĩ kwenyu. Nĩkwĩthĩwa kĩthimo kĩla mũthimaa, nokyo mũkathimĩwa.'),
('kam', 'LUK', 6, 39, 'Na Yesũ amatavya ngelekan’yo, Kĩlilinda nĩkĩtonya kũtongoesya kĩlilinda kĩngĩ? Syelĩ itivalũke ĩimanĩ?'),
('kam', 'LUK', 6, 40, 'Mũmanĩw’a ndethĩwa e ĩũlũ wa mũmanyĩsya wake: ĩndĩ kĩla mũndũ ũminĩte kũmanyĩw’a akeethĩwa ta mũmanyĩsya wake.'),
('kam', 'LUK', 6, 41, 'Naku nĩkĩ ũkũsisya kaũvavathĩ ke ithonĩ ya mwana‐a‐au, na ndũsũanĩa mũamba ũla wĩ ithonĩ yaku we?'),
('kam', 'LUK', 6, 42, 'Kana ũtonya ata kũmwĩa mwana‐a‐au, Any’a, mwana‐a‐asa, ndeka nĩkumye kaũvavathĩ ke ithonĩ yaku, na mũamba ũla wĩ ithonĩ yaku ndũũwona? Mwangangan’ya we, amba kwĩyumya mũamba ũsu wĩ ithoni kwaku, na ĩndĩ ũkoona nesa kumya kaũvavathĩ ke ithonĩ ya mwana‐a‐au.'),
('kam', 'LUK', 6, 43, 'Vai mũtĩ mũseo ũsyaa ũsyao mũthũku; kana mũtĩ mũthũku ũsyaa ũsyao mũseo.'),
('kam', 'LUK', 6, 44, 'Nũndũ kĩla mũtĩ nũmanyĩkaa nĩ ũsyao waw’o. Nũndũ mĩw’anĩ andũ maitusaa makũyũ, kana mĩtaenĩ maitusaa nzavivũ.'),
('kam', 'LUK', 6, 45, 'Mũndũ mũseo nĩwumasya ũndũ ũseo kyũmbanĩsyonĩ kĩseo kya ngoo yake; na mũndũ mũthũku nĩwumasya ũndũ ũthũku kyũmbanĩsyonĩ kĩthũku kya ngoo yake: nũndũ ũla wusũĩte ngoo nĩw’o kanyw’a ũneenaa.'),
('kam', 'LUK', 6, 46, 'Mũmbĩtaa Mwĩaĩi, Mwĩaĩi, nĩkĩ, na mũtyĩkaa maũndũ ala nĩmũtavasya?'),
('kam', 'LUK', 6, 47, 'Kĩla mũndũ wũkaa kwakwa, na kwĩw’a ndeto syakwa, naisyĩkaa, nĩngũmwon’ya ũndũ ũilyĩ:'),
('kam', 'LUK', 6, 48, 'ailyĩ ta mũndũ ũla wakie nyũmba, ũla wenzie mũkao mũliku, na aakie wambĩlĩlyo wayo ĩũlũ wa ĩvia: na kĩw’ũ kingĩ kyookie, kyakima nyũmba ĩsu, na kyaemwa nĩ ũthingithya: nũndũ yaakĩtwe ĩvianĩ.'),
('kam', 'LUK', 6, 49, 'Ĩndĩ ũla wewie, na ndaaĩka, ailyĩ ta mũndũ ũla wakie nyũmba mũthanganĩ vate wambĩlĩlyo, na kĩw’ũ kingĩ kyamĩkima, na oyu yavalũka; na ũvalũko wa nyũmba ĩsu waĩ mũnene.'),
('kam', 'LUK', 7, 1, 'Na Yesũ amina kũneena ndeto syake syonthe ĩkĩw’ika nĩ andũ, alika Kavelinaumi.'),
('kam', 'LUK', 7, 2, 'Na mũnene ũmwe wa asikali ĩana aĩ na ngombo ndwau, yakilĩlye kũkw’a, nake nĩwamyendete mũno.'),
('kam', 'LUK', 7, 3, 'Na eew’a ũvoo wa Yesũ, atũma atumĩa ma Ayuti vala ũĩ makamwĩsũve oke kũmĩvoesya ngombo yake.'),
('kam', 'LUK', 7, 4, 'Nao, mavika vala ve Yesũ, mamwĩsũva mũno, makyasya, Ũsu nĩwaĩlwe nĩ kwĩkwa ũu;'),
('kam', 'LUK', 7, 5, 'nũndũ nĩwendete mbaitũ, na ĩsinakoke yitũ nĩwatwakĩe.'),
('kam', 'LUK', 7, 6, 'Na Yesũ athi nao. Na avika vakuvĩ na nyũmba, ũla mũndũ atũma anyanyae vala ũĩ, mamwĩe, Mwĩaĩi, manya kwĩnyamasya; nũndũ ndyĩanĩwe nue ũlika ungu wa kĩala kyakwa:'),
('kam', 'LUK', 7, 7, 'na ta ũu nĩnasya ndyĩanĩwe nĩ kũka kwaku: ĩndĩ neena ndeto tũ, na mũthũkũmi wakwa nũnũũvoa.'),
('kam', 'LUK', 7, 8, 'Nĩkwĩthĩwa nyie nĩ mũndũ ũla wĩaĩawa, na nĩ na asikalĩ makwa ĩtheo wakwa: na nĩngũmwĩa ũmwe, Thi, na akĩthi; na ũngĩ, Ũka, na akyũka; na ngombo yakwa, Ĩka ũna, nayo ĩkĩka.'),
('kam', 'LUK', 7, 9, 'Na Yesũ eew’a maũndũ asu, aseng’a ũndũ wake, na eethyũũa na amea andũ ala mamũvikĩlĩte, Nĩmwĩa atĩĩ, ndyaaona mũĩkĩĩo mũnene ta ũũ, aiee, o na nthĩnĩ wa Isilaeli.'),
('kam', 'LUK', 7, 10, 'Na ala matũmiwe, masyoka nyũmba, meethĩa ĩla ngombo ĩnavoa.'),
('kam', 'LUK', 7, 11, 'Na kweethĩwa ĩvinda ĩnini yathela, athi ndũanĩ ĩla yĩtawa Naini; na amanyĩw’a make, na andũ angĩ aingĩ, maendan’ya nake.'),
('kam', 'LUK', 7, 12, 'Na athengeea mbingĩlonĩ ya ndũa, sisya, nĩkwaumaalĩtw’e mũndũ mũkw’ũ, aĩ mwana e weka, na inyia aĩ ndiwa: na andũ aingĩ ma ndũa maĩ vamwe nake.'),
('kam', 'LUK', 7, 13, 'Na Mwĩaĩi amwona, amwĩw’ĩa ĩnee, na amwĩa, Eka kũĩa.'),
('kam', 'LUK', 7, 14, 'Na athengeea akiita mũsekeseke: na ala makuĩte maũngama. Nake asya, Mwanake, nĩngũũtavya, Ũkĩla.'),
('kam', 'LUK', 7, 15, 'Na ũla waĩ mũkw’ũ ekala nthĩ, na ambĩlĩlya ũneena. Na Yesũ amũnenga inyia wake.'),
('kam', 'LUK', 7, 16, 'Na onthe makwatwa nĩ w’ĩa: na mamũkatha Ngai, makyasya, Kũũ kwitũ nĩkumbũkie mwathani mũnene: na, Ngai nũmokĩe andũ make.'),
('kam', 'LUK', 7, 17, 'Na ũvoo ũsu wake wanyaĩĩka nthĩ yonthe ya Yutia, na nthĩ ila syamĩthyũlũlũkĩte.'),
('kam', 'LUK', 7, 18, 'Na amanyĩw’a ma Yoana mamũtavya maũndũ asu onthe.'),
('kam', 'LUK', 7, 19, 'Na Yoana ameta elĩ ma amanyĩw’a make na amatũma kwa Mwĩaĩi, makamũkũlye, Nue ũla wĩũka, kana tũmweteele ũngĩ?'),
('kam', 'LUK', 7, 20, 'Na yĩla aũme asu mavikie vala ũĩ, mamwĩa, Yoana Mũvatisi nĩwatũtũma vala ũĩ, nake asya, Nue ũla wĩũka, kana tũmweteele ũngĩ?'),
('kam', 'LUK', 7, 21, 'Na saa ũsu avosya andũ aingĩ mowau na mothĩn’yo na maveva mathũku; na ililinda nyingĩ syasalukw’a metho.'),
('kam', 'LUK', 7, 22, 'Na ĩndĩ asũngĩa amea, Endai, mũkamũtavye Yoana maũndũ asu ala mwonete na ala mwĩw’ĩte; ililinda nikwona, ala mathuaa nĩmeũthi, ala mawaĩte mangũ nĩmeũthew’a, ala au matũ nĩmekwĩw’a, ala akw’ũ nĩmeũthayũũkw’a, na ala ngya nĩmeũtavw’a ũvoo mũseo.'),
('kam', 'LUK', 7, 23, 'Nĩ mũathime o ũla ũtakona ũndũ wa ũlulutĩkw’a nthĩnĩ wakwa.'),
('kam', 'LUK', 7, 24, 'Na ala matũmiwe nĩ Yoana mamina ũthi, ambĩlĩlya kũneena na makomano ũndũ wa Yoana, akyasya, Mũnaendaa kũsisya kyaũ weũnĩ? Nĩ mũangi ũla ũthingithangw’a nĩ kĩseve?'),
('kam', 'LUK', 7, 25, 'Ĩndĩ mũnaendaa kwona kyaũ? Nĩ mũndũ wĩkĩe ngũa nduũku? Nĩmwenei, ala mekĩaa ngũa nzeo mbee, na me na lĩu mũseo, mekalaa kwa asumbĩ.'),
('kam', 'LUK', 7, 26, 'Ĩndĩ mũnaendaa kũsisya kyaũ? Nĩ mwathani? Ĩĩ, nĩngũmũtavya, nĩ ũla ũvĩtũkĩte mũno mwathani.'),
('kam', 'LUK', 7, 27, 'Ũsu nĩwe ũla waandĩkĩwe atĩĩ, Sisya, nĩngũtũma mũtũmwa wakwa mbee wa ũthyũ waku, Ũla ũkaseũvya nzĩa yaku mbee waku.'),
('kam', 'LUK', 7, 28, 'Nĩngũmũtavya atĩĩ, Katĩ wa ala masyaawa nĩ aka vai ũmwe ũvĩtũkĩte Yoana: o na kau ũla mũnini ũsumbĩnĩ wa Ngai nĩ mũnene kwĩ we.'),
('kam', 'LUK', 7, 29, 'Na andũ onthe, o na aumya ma koti, meew’a, mamũtala Ngai mũlũngalu, nũndũ mavatisĩtwe na ũvatisi wa Yoana.'),
('kam', 'LUK', 7, 30, 'Ĩndĩ Avalisi na amamyisya ma mĩao malea motw’io ma Ngai, kwa kũtavatiswa nĩwe.'),
('kam', 'LUK', 7, 31, 'Na Mwĩaĩi asya, Nĩelekan’ya na kyaũ andũ ma ũsyao ũũ, nao mavw’anene na kyaũ?'),
('kam', 'LUK', 7, 32, 'Mavw’anene na syana ila syĩkalaa kĩng’ang’anĩ, ila syĩtanaa; ikyasya, Twamũvuvĩa mũtũlilũ, nenyu mũinasũnga; twamũmetea, nenyu mũinaĩa.'),
('kam', 'LUK', 7, 33, 'Nũndũ Yoana Mũvatisi nĩwũkĩte ateũya kĩmũtũ na ateũnyw’a mbinyu; na inyw’ĩ mwĩasya, E na ndaimoni.'),
('kam', 'LUK', 7, 34, 'Mwana wa mũndũ nĩwũkĩte akĩya na akĩnyw’a; na inyw’ĩ mwĩasya, Sisyai, mũyi, na mũnywi, mũnyanyae wa aumya ma koti na andũ athe!'),
('kam', 'LUK', 7, 35, 'Ũĩ nũtalĩlawa ũlũngalu nĩ syana syaw’o syonthe.'),
('kam', 'LUK', 7, 36, 'Na ũmwe wa Avalisi enda aye lĩu nake. Na alika nyũmba ya Mũvalisi, na ekala nthĩ aye.'),
('kam', 'LUK', 7, 37, 'Na sisya, mũndũ mũka wa ndũa ĩsu, ũla waĩ mwathe, yĩla wamanyie kana nũnũũya lĩu nyũmanĩ ya Mũvalisi, aete sũva wa mauta,'),
('kam', 'LUK', 7, 38, 'na aũngama ĩtina vakuvĩ na maũũ make, akĩĩa, na ambĩlĩlya kũmwĩtĩkĩsya methoi maũũ make, na kũmanyasya na nzw’ĩĩ sya mũtwe wake, na kũmamumunyanga maũũ make, akĩmavaka ala mauta.'),
('kam', 'LUK', 7, 39, 'Na Mũvalisi ũla wamwĩtĩte oona ũu, avindya ngoonĩ yake, akyasya, Kethĩwa mũndũ ũũ nĩ mwathani, eethĩwa amanyie mũndũ mũka ũũ nũũ, na nĩ mũndũ mũka ũilyĩ ata ũla ũnũũmũkiita, atĩ nĩ mwathe.'),
('kam', 'LUK', 7, 40, 'Na Yesu amũsũngĩa amwĩa, Simoni, nĩ na kaũndũ ngwenda ũkũtavya. Nake asya, Mũmanyĩsya, neena.'),
('kam', 'LUK', 7, 41, 'Yesũ amwĩa Mũndũ ũmwe, mũkovethya, aĩ na andũ elĩ maĩ na thiĩ nake: ũmwe thiĩ wake waĩ silingi maana atano, na ũla ũngĩ mĩongo ĩtano.'),
('kam', 'LUK', 7, 42, 'Nao meethĩwa mate na kĩndũ kya ũmũĩva, amaekea thiĩ woo me elĩ. Nĩ wĩva ĩndĩ wa asu elĩ ũla wĩmwenda mbee?'),
('kam', 'LUK', 7, 43, 'Simoni amũsũngĩa, asya, Nĩngwasya nĩ ũla waekewe nyingĩ. Nake amwĩa, Watw’a nesa we.'),
('kam', 'LUK', 7, 44, 'Nake eethyũũĩa ũ mũndũ mũka, aimwĩa Simoni, Nĩwene mũndũ mũka ũũ? Nĩvotie nyũmba yaku, na ndũnanenga manzĩ ma ũthambya maũũ makwa: ĩndĩ ũyũ nĩwamathambya na methoi make, na nĩwamanyasya na nzw’ĩĩ syake.'),
('kam', 'LUK', 7, 45, 'Ndũnamumunya: ĩndĩ ũyũ yĩla nĩvotie, ndanaeka kũmamumunyanga maũũ makwa.'),
('kam', 'LUK', 7, 46, 'Ndũnambaka mũtwe wakwa mauta: ĩndĩ ũyũ nĩwambaka maũũ makwa mauta.'),
('kam', 'LUK', 7, 47, 'Kwondũ wa ũu nĩngũkũtavya, Naĩ syake, o na syĩ nyingĩ, nĩsyaekwa; nũndũ e wendo mwingĩ: ĩndĩ ũla ũekewe ũndũ ũnini, ũsu e wendo mũnini.'),
('kam', 'LUK', 7, 48, 'Nake amwĩa ũla mũndũ mũka, Naĩ syaku nĩsyaekwa.'),
('kam', 'LUK', 7, 49, 'Na ala mailyĩ nthĩ nake makĩya lĩu mambĩlĩlya kũvindya ngoonĩ syoo, Ũũ nũũ ũnũkũekea naĩ?'),
('kam', 'LUK', 7, 50, 'Nake amwĩa mũndũ mũka, Mũĩkĩĩo waku nĩwakũtangĩĩa; thi na mũuo.'),
('kam', 'LUK', 8, 1, 'Na kweethĩwa ĩvinda ĩnini yathela, athi angangĩla ndũanĩ na mĩsyĩ, akĩtavan’ya na kũnyaĩĩkya ũvoo mũseo wa ũsumbĩ wa Ngai, na ala ĩkũmi na elĩ maĩ vamwe nake,'),
('kam', 'LUK', 8, 2, 'na aka amwe ala mavoiw’e maveva mathũkũ na mowau: ũmwe nĩ Meli ũla wetwa Makatalene, ũla waumiw’e ndaimoni mũonza,'),
('kam', 'LUK', 8, 3, 'na Yoena, mũka wa Kusi, mũsyaĩĩsya wa syĩndũ sya Elote, na Susana, na angĩ aingĩ ala mamũtetheasya na isamũ syoo.'),
('kam', 'LUK', 8, 4, 'Na yĩla ĩkomano ĩnene yoombanie, na andũ ma kĩla ndũa mooka vala ũĩ, aneena na ngelekan’yo:'),
('kam', 'LUK', 8, 5, 'Mũvuĩi nĩwaendie kũvuĩa mbeũ syake: na akĩvuĩa, imwe syavalũka ũtee wa nzĩa; na syakinyangwa, ikĩĩwa nĩ nyũnyi sya yayaya.'),
('kam', 'LUK', 8, 6, 'Ingĩ syavalũka ĩvianĩ; na syamea na syooma, nũndũ vatyaĩ kĩmeu.'),
('kam', 'LUK', 8, 7, 'Na ingĩ syavalũka mĩw’anĩ; na mĩw’a yameanĩsya vamwe nasyo, na yainyita.'),
('kam', 'LUK', 8, 8, 'Na ingĩ syavalũka mũthanganĩ mũseo, na syamea, na syasyaa imwe ĩana. Amina kũneena ũu, aneena na wasya mũnene, Ũla wĩ matũ ma kwĩw’a, nĩew’e.'),
('kam', 'LUK', 8, 9, 'Na amanyĩw’a make mamũkũlya, Ngelekan’yo ĩno nĩ myaũ?'),
('kam', 'LUK', 8, 10, 'Nake asya, Inyw’ĩ mũnengetwe kũmanya nzama sya ũsumbĩ wa Ngai: ĩndĩ ala angĩ mamanyĩaw’a na ngelekan’yo; nĩ kana makyona matikone, na makĩw’a maikamanye.'),
('kam', 'LUK', 8, 11, 'Na ngelekan’yo nĩyo ĩno: Mbeũ nĩ ndeto ya Ngai.'),
('kam', 'LUK', 8, 12, 'Ala me ũtee wa nzĩa nĩmo ala mew’aa; na ĩndĩ ndevili akyũka, akyumya ndeto ngoonĩ syoo, maikese kwĩtĩkĩla matangĩĩwe.'),
('kam', 'LUK', 8, 13, 'Ala me ĩvianĩ nĩmo ala mew’aa, makĩkwata ndeto na ũtanu; ĩndĩ mati na mĩi, na nĩmo mekwĩtĩkĩla kavinda kanini, ĩndĩ ĩvinda ya kũtatwa nĩmeũtia.'),
('kam', 'LUK', 8, 14, 'Na ila syavalũkile mĩw’anĩ, nĩmo ala mew’aa, na maithi mainyitwa nĩ mawĩmakĩo na ũthwii na motanu ma thayũ ũũ, nao matisyaa ũsyao ũkavika.'),
('kam', 'LUK', 8, 15, 'Ĩndĩ ila syĩ mũthanganĩ mũseo, nĩ ala mew’aa ndeto na ngoo nzeo na ya w’o, mailũmya, na maisyaa ũsyao, me na wũmĩĩsyo.'),
('kam', 'LUK', 8, 16, 'Vai mũndũ ũkwatasya taa na akokunĩkĩlya kĩndũ, kana kwia ungu wa ũkomo; ĩndĩ nũnũkwia vala vatũlu, nĩ kana ala meũvota mone kyeni.'),
('kam', 'LUK', 8, 17, 'Nũndũ vai ũndũ ũvithe, ũla ũtakavuanw’a, kana kĩmbithĩ, kĩtakamanyĩka na kumbũka ũtheinĩ.'),
('kam', 'LUK', 8, 18, 'Ĩsũvĩei ĩndĩ ũndũ mũkwĩw’a; nũndũ ũla wĩ na kĩndũ, ũsu akanengwa; na ũla ũtaĩ, akavenwa kĩla ũkwasya e nakyo.'),
('kam', 'LUK', 8, 19, 'Na ĩndĩ inyia na ana‐a‐inyia make mooka vala ũĩ, na maaĩwa nĩ mwanya ũmũthengeea ũndũ wa ĩkomano.'),
('kam', 'LUK', 8, 20, 'Nake atavw’a, Mwenyu na ana‐a‐mwenyu maũngeme nza, nao nĩmekwenda ũkwona.'),
('kam', 'LUK', 8, 21, 'Ĩndĩ asũngĩa na amea, Mwaitũ na ana‐a‐ia makwa nĩ ala mew’aa na kwĩkaa ndeto ya Ngai.'),
('kam', 'LUK', 8, 22, 'Na kweethĩwa mũthenya ũmwe wa matukũ asu, alika ngalawanĩ, we na amanyĩw’a make; na amea, Tũingei mũingo ũya wa ĩia; na makũsya.'),
('kam', 'LUK', 8, 23, 'Na makĩthi na ngalawa akoma: na kĩuutani kĩnene kyatheea ĩianĩ; na manzĩ mavota ngalawanĩ, nao meethĩwa na mũisyo.'),
('kam', 'LUK', 8, 24, 'Na mathi vala ũĩ, mamũamũkya, maimwĩa, Mwĩaĩi, Mwĩaĩi, nĩtũũkw’a. Nake aamũka, na akan’ya kĩseve na itulumo; nasyo syausya, na kwaya ũuu.'),
('kam', 'LUK', 8, 25, 'Nake amakũlya, Mũĩkĩĩo wenyu ũĩva? Nao makĩa na maseng’a, makĩneenan’ya, Ũũ nũũ ĩndĩ, nũndũ nũnũkwĩaĩa o na iseve na manzĩ, na ikamwĩw’a?'),
('kam', 'LUK', 8, 26, 'Na mavika nthĩ ya Akelasene, ĩla yelekanĩle na Kalilii.'),
('kam', 'LUK', 8, 27, 'Na yĩla waumie akinya nthĩ, akomana na mũndũ ũmwe aumĩte ndũanĩ ĩsu, ũla waĩ na ndaimoni; na ĩvinda ĩasa ndeevw’ĩkaa ngũa, kana kwĩkalaa nyũmbanĩ, ĩndĩ ekalaa mbũanĩ.'),
('kam', 'LUK', 8, 28, 'Nake amwona Yesũ, akaya, na avalũka nthĩ mbee wake, na aneena na wasya mũnene, akyasya, Nĩ ũndũ naku wa kĩ we, Yesũ, Mwana wa Ngai Ũla Wĩ Ĩũlũ wa Onthe? Nĩngũkwĩsũva ndũkanyamasye.'),
('kam', 'LUK', 8, 29, 'Nũndũ nĩwawĩaĩe veva mũvuku wume mũndũnĩ ũsu. Nĩkwĩthĩwa mavinda maingĩ nĩwakwatawa nĩw’o: nake avingĩawa, na kwovwa na mĩnyololo na mbĩngũ; na aitusanga syonthe, alũngĩlĩlaw’a weũnĩ nĩ ndaimoni.'),
('kam', 'LUK', 8, 30, 'Na Yesũ amũkũlya, Syĩtwa yaku nue ata? Nake amũsũngĩa, Ninyie Nguthu, nĩkwĩthĩwa nĩwalikĩtwe nĩ ndaimoni nyingĩ.'),
('kam', 'LUK', 8, 31, 'Na ila ndaimoni syamwĩsũva mũno ndakasyĩe ithi ĩimanĩ yĩte kĩtulu.'),
('kam', 'LUK', 8, 32, 'Na vo vaĩ ĩĩthya ya ngũlũe nyingĩ ikĩya kĩĩmanĩ: na ndaimoni syamwĩsũva inengwe ũthei wa kwilika syo. Nake ainenga ũthei.'),
('kam', 'LUK', 8, 33, 'Na ndaimoni syauma mũndũnĩ, na syavota ngũlũenĩ: na ĩĩthya yatheea kĩvaũũkonĩ yĩsembete, yalika ĩianĩ, na yakw’ĩa vo.'),
('kam', 'LUK', 8, 34, 'Na ala maĩthasya ngũlũe moona ũndũ ũsu ũla weekĩka, makĩa, na matavan’ya ndũanĩ o na ndee.'),
('kam', 'LUK', 8, 35, 'Na andũ maumaala mathi ũsisya ũndũ ũla wĩkĩkie; na mathi vala ve Yesũ, na mamwona mũndũ ũla ũnaumiw’e ndaimoni, ailyĩ nthĩ maũũnĩ ma Yesũ, evw’ĩkĩte ngũa, e na kĩlĩko: na meew’a w’ĩa mũno.'),
('kam', 'LUK', 8, 36, 'Na ala moonie ũndũ ũsu mamatavya ũndũ ũnavoiw’e ũla waĩ na ndaimoni.'),
('kam', 'LUK', 8, 37, 'Na andũ onthe ma nthĩ ya Akelasene ngalĩ syonthe mamwĩsũva aume kwoo; nũndũ makwatiwe nĩ w’ĩa mwingĩ; nake alika ngalawanĩ, na asyoka.'),
('kam', 'LUK', 8, 38, 'Ĩndĩ ũla mũndũ ũnaumiw’e ndaimoni amwĩsũva ekalan’ye nake: ĩndĩ amũeka athi, aimwĩa,'),
('kam', 'LUK', 8, 39, 'Syoka nyũmba kwaku, ũkatavan’ye maũndũ ũndũ manenevete ala Ngai ũkwĩkie. Na athi, atavan’ya ndũanĩ yonthe maũndũ ũndũ manenevete ala Yesũ ũnamwĩkie.'),
('kam', 'LUK', 8, 40, 'Na Yesũ asyoka, ĩkomano yamũthaũa na ũtanu; nũndũ onthe nĩmamweteele.'),
('kam', 'LUK', 8, 41, 'Na sisya, kwooka mũndũ wetawa Yailu, ũla waĩ mũnene wa ĩsinakoke: nake avalũka maũũnĩ ma Yesũ, na amwĩsũva athi kwake;'),
('kam', 'LUK', 8, 42, 'nũndũ aĩ na mwĩĩtu wake o ũmwe, wa myaka ĩkũmi na ĩlĩ, nake aĩ vakuvĩ na kũkw’a. Na aendete avivinyw’a nĩ ĩkomano ya andũ.'),
('kam', 'LUK', 8, 43, 'Na mũndũ mũka ũla waumawa nĩ nthakame myaka ĩkũmi na ĩlĩ, na nĩwanangĩe ũthwii wake w’onthe kwa aiiti, na ndaaona ũmwe wa ũmũvosya,'),
('kam', 'LUK', 8, 44, 'athi ĩtina wake, akiita ũtiivo wa ngũa yake; na o ĩmwe nthakame yatuma.'),
('kam', 'LUK', 8, 45, 'Na Yesũ akũlya, Nũũ ũla wangiita? Na onthe makaĩa, na Vetelo na ala maĩ nake mamwĩa, Mwĩaĩi, andũ nĩmeũkũtindĩka na kũkũvivinya.'),
('kam', 'LUK', 8, 46, 'Ĩndĩ Yesũ asya, No nakiitwa; nũndũ nĩngwĩw’a vinya wauma kwakwa.'),
('kam', 'LUK', 8, 47, 'Na mũndũ mũka oona kana ndevithĩte, ooka aitetema, na avalũka mbee wake, na atavan’ya onthe makĩw’a ũndũ ũla ũtumie amũkiita, na ũndũ wavoa kavinda kau.'),
('kam', 'LUK', 8, 48, 'Nake amwĩa, Mwĩĩtu, mũĩkĩĩo waku nĩwakũvosya; enda na mũuo.'),
('kam', 'LUK', 8, 49, 'Atanamba ũmina ũneena, mũndũ ooka auma nyũmba ya mũnene wa ĩsinakoke, akyasya, Mwĩĩtu waku nĩwakw’a; manya kũnyamasya Mũmanyĩsya.'),
('kam', 'LUK', 8, 50, 'Ĩndĩ Yesũ eew’a ũu, amũsũngĩa, Ndũkakĩe: ĩkĩĩa, tũ, nake nũnũũvow’a.'),
('kam', 'LUK', 8, 51, 'Avika nyũmba, ndaaĩtĩkĩla mũndũ alike nake, ate o Vetelo, na Yoana, na Yakovo, na ĩthe na inyia wa kelĩtu.'),
('kam', 'LUK', 8, 52, 'Na onthe meethĩwa makĩĩa na kũkũnanga ithũi: ĩndĩ nake amea, Ekai kũĩa; nũndũ ti kakw’ũ, ĩndĩ nĩkakomete.'),
('kam', 'LUK', 8, 53, 'Nao mamũthekeea mũno, nũndũ nĩmeesĩ nĩ kakw’ũ.'),
('kam', 'LUK', 8, 54, 'Nake, akwata kw’oko kwako, aketa, akyasya, Kelĩtu, ũkila.'),
('kam', 'LUK', 8, 55, 'Na veva wako wasyoka, na kookĩla oyu: na eeaa kanengwe kya ũya.'),
('kam', 'LUK', 8, 56, 'Na asyai mako maseng’a mũno: ĩndĩ amea matikatavye mũndũ ũla weekĩka.'),
('kam', 'LUK', 9, 1, 'Nake ameta ala ĩkũmi na elĩ, amanenga vinya na ũkũmũ ĩũlũ wa ndaimoni syonthe, na wa kũvosya mowau.'),
('kam', 'LUK', 9, 2, 'Na amatũma kũtavan’ya ũvoo wa ũsumbĩ wa Ngai, na kũvosya awau.'),
('kam', 'LUK', 9, 3, 'Nake amea, Manyai ũkua kĩndũ kya nzĩanĩ, ndata, kana mũvuko, kana kĩmũtũ, kana mbesa; na mũndũ ndakethĩwe na itonyeo ilĩ.'),
('kam', 'LUK', 9, 4, 'Na nyũmba o na yĩva ĩla mwĩvota, mwĩĩkala vo, mwĩuma o vo mũkĩthi.'),
('kam', 'LUK', 9, 5, 'Na ala mateũmũthokya, mũkyuma ndũanĩ ĩsu, tuangai kĩtoo maũũnĩ menyu nĩ kana wĩthĩwe ũkũsĩ kwoo.'),
('kam', 'LUK', 9, 6, 'Nao mathi, na manganga mĩsyĩ, makĩtavan’ya ũla ũvoo mũseo, na makĩvosya awau kũndũ kw’onthe.'),
('kam', 'LUK', 9, 7, 'Na mũsumbĩ Elote eew’a maũndũ asu onthe ala meekiwe: nake asũanĩwa mũno, nĩkwĩthĩwa amwe nĩmaneenie kana Yoana nũthayũũkĩte kuma akw’ũnĩ;'),
('kam', 'LUK', 9, 8, 'na angĩ, kana Eliya nĩwumĩlĩte; na angĩ, kana ũmwe wa athani ma tene nũthayũũkĩte.'),
('kam', 'LUK', 9, 9, 'Ĩndĩ Elote asya, Yoana nĩnamũtilile mũtwe: ĩndĩ ũsu nũũ, ũla ngwĩw’a maũndũ asu ũndũ wake? Nake nĩwendaa kũmwona.'),
('kam', 'LUK', 9, 10, 'Na atũmwa yĩla masyokie mamũtavya maũndũ onthe ala meekie. Nake athi nao nzama, vakuvĩ na ndũa ĩla yĩtawa Vethisaita.'),
('kam', 'LUK', 9, 11, 'Na andũ ma makomano mamanya, ũu, mamũvikĩla kw’o: nake amosa na mũyo, na amatavya ũvoo wa ũsumbĩ wa Ngai, na amavosya ala maĩ na vata wa kũvow’a.'),
('kam', 'LUK', 9, 12, 'Na syũa yambĩlĩlya ũthũa; na ala ĩkũmi na elĩ mooka, na mamwĩa, Ũmbũũkya ĩkomano, nĩ kana yĩnyaĩĩkĩe mĩsyĩ na nthĩ ila syĩ ndee, mamanthe vandũ va ũkoma na lĩu; nũndũ vaa tũĩ, nĩ weũnĩ.'),
('kam', 'LUK', 9, 13, 'Ĩndĩ amea, Manengei lĩu e inyw’ĩ. Na masya, Twĩ na imũtũ itano na makũyũ elĩ ki; ate o tũithi kũthooa lĩu wa andũ aa onthe.'),
('kam', 'LUK', 9, 14, 'Nũndũ maĩ andũ aũme ta ngili itano. Nake amea amanyĩw’a make, Mekalyei nthĩ nguthu na nguthu, kĩla nguthu yĩ na andũ ta mĩongo ĩtano.'),
('kam', 'LUK', 9, 15, 'Nao meeka ũu, na mamekalya onthe nthĩ.'),
('kam', 'LUK', 9, 16, 'Nake oosa ila imũtũ itano na makũyũ elĩ, na ang’elela ĩtunĩ, aiathima na aitilanga; na anenga amanyĩw’a matwaĩe ĩkomano.'),
('kam', 'LUK', 9, 17, 'Na maya, na onthe mavũna: na kwooswa ikavũ ĩkũmi na ilĩ sya ilungu isu ndile ila syamatialĩle.'),
('kam', 'LUK', 9, 18, 'Na kweethĩwa, akĩvoya e weka, amanyĩw’a maĩ vamwe nake: na amakũlya, akyasya, Makomano measya nyie nĩ ũũ?'),
('kam', 'LUK', 9, 19, 'Mamũsũngĩa, makyasya, Amwe measya, Yoana ũla Mũvatisi; ĩndĩ angĩ measya, Eliya; na angĩ kana wĩ ũmwe wa athani ma tene ũthayũũkĩte.'),
('kam', 'LUK', 9, 20, 'Nake amea, Ĩndĩ inyw’ĩ mwĩasya nyie nĩ ũũ? Vetelo asũngĩa, asya, We nue Klĩsto wa Ngai.'),
('kam', 'LUK', 9, 21, 'Ĩndĩ amatavya, ameaĩa matikatavye mũndũ ũndũ ũsu;'),
('kam', 'LUK', 9, 22, 'akyasya, Mwana wa mũndũ ndatĩa kũthĩnw’a na mathĩna maingĩ, na kũlewa nĩ atumĩa na athembi anene na aandĩki, na kũawa, na kũthayũũkw’a mũthenya wa katatũ.'),
('kam', 'LUK', 9, 23, 'Na ĩndĩ amea onthe, Ethĩwa mũndũ o na wĩva nũnũkwenda kũmbikĩla, nĩelee mwene, na kwĩyaĩkya ngelan’yo yake kĩla mũthenya, na akĩmbikĩla.'),
('kam', 'LUK', 9, 24, 'Nĩkwĩthĩwa o ũla ũnũkwenda kũvĩtya thayũ wake akawasya; na o ũla ũkwasya thayũ wake kwondũ wakwa, ũsu akoovĩtya.'),
('kam', 'LUK', 9, 25, 'Nũndũ mũndũ aunwa nĩ kyaũ, o na akosa nthĩ nima, akĩyananga, kana akĩyasya mwene?'),
('kam', 'LUK', 9, 26, 'Nũndũ o ũla ũkambĩw’ĩa nthoni nyie na ndeto syakwa, nũkew’ĩwa nthoni nĩ Mwana wa mũndũ, yĩla ũkoka ũtheunĩ wake mũtisu, na wa Ĩthe, na wa alaĩka atheu.'),
('kam', 'LUK', 9, 27, 'Ĩndĩ nĩngũmũtavya w’o, Katĩ wa aa maũngeme vaa, ve amwe matakasama kĩkw’ũ nongi, matanamba kwona ũsumbĩ wa Ngai.'),
('kam', 'LUK', 9, 28, 'Na kweethĩwa ĩtina wa ndeto isu o ta vandũ va mĩthenya nyanya, oosa Vetelo na Yoana na Yakovo, ambata kĩĩmanĩ kũvoya.'),
('kam', 'LUK', 9, 29, 'Na akĩvoya, mũvw’ano wa ũthyũ wake waalyũka, na ngũa syake syeeũva kw’ũ, na syakaka.'),
('kam', 'LUK', 9, 30, 'Na sisya, andũ elĩ meethĩwa makĩneenan’ya nake, nao nĩ Mose na Eliya;'),
('kam', 'LUK', 9, 31, 'ala mamaumĩlĩle na ũtheu mũtisu, makĩneenan’ya ũvoo wa kĩkw’ũ kyake kĩla ũkilĩlye kwĩanĩĩsya ku Yelusaleme.'),
('kam', 'LUK', 9, 32, 'Ĩndĩ Vetelo na ala maĩ nake makwatwa nĩ too mũnene: na mavindũka, moona ũtheu wake mũtisu, na ala aũme elĩ maũngeme nake.'),
('kam', 'LUK', 9, 33, 'Na kweethĩwa yĩla mataanĩsye nake, Vetelo amwĩa Yesũ, Mwĩaĩi, nĩ ũseo kwitũ kwĩthĩwa vaa: twake malwanda atatũ; yĩmwe yaku, na yĩngĩ ya Mose, na yĩngĩ ya Eliya: nake ndaamanya ũndũ ũnũkwasya.'),
('kam', 'LUK', 9, 34, 'Na akĩneena ũu, kwooka ĩthweo, yamekĩa muunyĩ: na meew’a w’ĩa nũndũ wa ũlika ĩthweonĩ.'),
('kam', 'LUK', 9, 35, 'Na wasya wauma ĩthweonĩ, ũkyasya, Ũũ nĩwe Mwana wakwa, mũnyuve wakwa: mwĩw’ei.'),
('kam', 'LUK', 9, 36, 'Na wasya waneena ũu, Yesũ ooneka e weka. Nao mavindya, na matukũ asu maiaatavya mũndũ maũndũ ala manoonie.'),
('kam', 'LUK', 9, 37, 'Na kweethĩwa ũnĩ ũsu, mauma kĩĩmanĩ matheea, ĩkomano ĩnene yamũthaũa.'),
('kam', 'LUK', 9, 38, 'Na ĩndĩ, mũndũ ũmwe wa ĩkomano aneena na wasya mũnene, akyasya, Mũmanyĩsya, nĩngũkwĩsũva ũkasisye mwana wakwa; nũndũ nowe wakwa e ũmwe:'),
('kam', 'LUK', 9, 39, 'nake nũkwatawa nĩ veva, na mĩtũkĩ nũnũũkaya; na nũnũũthingithangw’a ĩvũyũ yĩkauma, na ũimuma na vinya ũkĩmũvinyĩthya mũno.'),
('kam', 'LUK', 9, 40, 'Nakwa namesũva amanyĩw’a maku mawumye; na maemwa nĩw’o.'),
('kam', 'LUK', 9, 41, 'Yesũ asũngĩa na asya, Ũsyao ũũ ũte na mũĩkĩĩo na mũemu, ngeethĩwa nenyu na nĩmũmĩĩsya ĩvinda yĩana ata? Mũete mwana waku vaa.'),
('kam', 'LUK', 9, 42, 'Na kĩmwana kyũkĩte, kyavalũkw’a nĩ ĩla ndaimoni, kyathingithangw’a nĩyo. Ĩndĩ Yesũ akan’ya veva ũsu mũvuku, na akĩvosya kĩla kĩmwana, akĩnenga ĩthe.'),
('kam', 'LUK', 9, 43, 'Na onthe maseng’a ũndũ wa ũnene wa Ngai. Na yĩla onthe maseng’ete nũndũ wa maũndũ onthe ala meekiwe nĩ Yesũ, amea amanyĩw’a make atĩĩ,'),
('kam', 'LUK', 9, 44, 'Ndeto ii ilike matũni menyu: nũndũ Mwana wa mũndũ nũkanenganwe mokonĩ ma andũ.'),
('kam', 'LUK', 9, 45, 'Ĩndĩ maiaamanya ndeto isu, nũndũ syavithĩtwe kwoo, matikaimanye; nao makĩa kũmũkũlya ũndũ wasyo.'),
('kam', 'LUK', 9, 46, 'Na ngananĩo yookĩla katĩ woo, ũndũ wa ũla wĩthĩwa mũnene.'),
('kam', 'LUK', 9, 47, 'Ĩndĩ Yesũ amanya mosũanĩo ma ngoo syoo, oosa kana kanini, akaũngamya ĩvavanĩ yake,'),
('kam', 'LUK', 9, 48, 'na amea, O ũla ũkosa kana kaa kanini syĩtwanĩ yakwa embosa nyie: na o ũla ũkambosa nyie eosa ũla wandũmie: nũndũ ũla mũnini katĩ wenyu, ũsu nĩwe mũnene.'),
('kam', 'LUK', 9, 49, 'Na Yoana asũngĩa na asya, Mwĩaĩi, nĩtũnoonie mũndũ akyumya ndaimoni na syĩtwa yaku; na twamũvata, nũndũ ndaatĩanĩe naitũ.'),
('kam', 'LUK', 9, 50, 'Ĩndĩ Yesũ amwĩa, Mũikamũvate: nũndũ ũla ũte na ũndũ nenyu e ngalĩ ĩ yenyu.'),
('kam', 'LUK', 9, 51, 'Na kweethĩwa, mĩthenya yathengeea ambatw’e, alũlũmĩlya ũthyũ wake elekelye kũthi Yelusaleme,'),
('kam', 'LUK', 9, 52, 'na atũma andũ mathi mbee wake: nao mathi, na mavota mũsyĩ ũmwe wa Asamalia, mamũseũvĩsye vandũ.'),
('kam', 'LUK', 9, 53, 'Nao matyaamũthokya, nũndũ ũthyũ wake weelekele ta ũnũũthi Yelusaleme.'),
('kam', 'LUK', 9, 54, 'Na amanyĩw’a make, Yakovo na Yoana, moona ũu, masya, Mwĩaĩi, nũkwenda tũwĩe mwaki wume ĩtunĩ, ũmavĩvye?'),
('kam', 'LUK', 9, 55, 'Ĩndĩ eethyũũa, amakan’ya.'),
('kam', 'LUK', 9, 56, 'Na mathi mũsyĩ ũngĩ.'),
('kam', 'LUK', 9, 57, 'Na makĩthi nzĩanĩ, mũndũ ũmwe amwĩa, Ngakũvikĩla o kũla wĩthi.'),
('kam', 'LUK', 9, 58, 'Na Yesũ amwĩa, Mbĩwa syĩ na maima, na nyũnyi sya yayaya syĩ na ndala; ĩndĩ Mwana wa mũndũ nde na vandũ va ũkomya mũtwe wake.'),
('kam', 'LUK', 9, 59, 'Na amwĩa ũngĩ, Mbikĩla. Ĩndĩ nake asya, Mwĩaĩi, nenga ũthei nambe ũthi kũmũthika asa wakwa.'),
('kam', 'LUK', 9, 60, 'Ĩndĩ amwĩa, Eka akw’ũ mathike akw’ũ moo; ĩndĩ we enda ũkatavan’ye ũsumbĩ wa Ngai.'),
('kam', 'LUK', 9, 61, 'Na ũngĩ asya, Ngakũvikĩla, Mwĩaĩi; ĩndĩ nenga ũthei nambe ũthi kwatiĩa ũvoo ala ma nyũmba yakwa.'),
('kam', 'LUK', 9, 62, 'Ĩndĩ Yesũ amwĩa, Mũndũ akwata mĩtĩ ya ĩembe ya ng’ombe, aisisya na ĩtina, ndeanĩwe nĩ ũsumbĩ wa Ngai.'),
('kam', 'LUK', 10, 1, 'Ĩtina wa maũndũ asu Mwĩaĩi anyuva angĩ mĩongo mũonza, na amatũma elĩ na elĩ, mathi mbee wake kĩla ndũa na vandũ, vala wakilĩlye kũthi.'),
('kam', 'LUK', 10, 2, 'Na amea atĩĩ, Nĩw’o ngetha nĩ mbingĩ, ĩndĩ akethi nĩ avũthũ: kwondũ wa ũu voyai Mwĩaĩi wa ngetha, atũme akethi ngethanĩ yake.'),
('kam', 'LUK', 10, 3, 'Endai; na lĩlĩi, nĩngũmũtũma ta tũtena twa malondu katĩ wa nzũi.'),
('kam', 'LUK', 10, 4, 'Manyai ũkua ngusu ya mbesa, kana mũvuko, kana iatũ; na manyai ũkethya mũndũ nzĩanĩ.'),
('kam', 'LUK', 10, 5, 'Na o nyũmba ĩĩa mwĩlikaa, ambaai kwasya, Mũuo wĩthĩwe nyũmbanĩ ĩno.'),
('kam', 'LUK', 10, 6, 'Na ethĩwa vo ve mwana wa mũuo, mũuo wenyu ũkekala nake: ĩndĩ ethĩwa nde vo, ũkamũsyokea.'),
('kam', 'LUK', 10, 7, 'Na ĩkalai nyũmbanĩ ĩsu, mũkĩya na mũkĩnyw’a o kĩla memũnengae: nũndũ mũtethya wa wĩa nĩwaĩlwe nĩ ĩtuvi yake. Manyai kumaalanga mũkĩvotanga nyũmba ĩno na ĩno.'),
('kam', 'LUK', 10, 8, 'Na ndũa o na yĩva ĩla mwĩvotaa, na mamũthokya, ĩsaai syĩndũ ila syĩetawe mbee wenyu:'),
('kam', 'LUK', 10, 9, 'vosyai awau ala me vo, mũkĩmatavya, Nĩmũthengeewe nĩ ũsumbĩ wa Ngai.'),
('kam', 'LUK', 10, 10, 'Ĩndĩ ndũa o na yĩva ĩla mwĩvotaa, na malea kũmũthokya, endai nzĩanĩ syayo, mũkyasya,'),
('kam', 'LUK', 10, 11, 'O na kĩtoo kya ndũa yenyu, kĩla kĩkwatĩte nyaĩĩ sitũ, nĩtũũmũvangũlĩla: ĩndĩ manyai ũũ, ũsumbĩ wa Ngai nũmũthengee.'),
('kam', 'LUK', 10, 12, 'Na ĩndĩ nĩngũmũtavya, Sotomo ĩkethĩwa yĩ kavaa mũthenya ũsu, kwĩ ndũa ĩsu.'),
('kam', 'LUK', 10, 13, 'Woo nĩ waku, Kolasini! Woo nĩ waku, Vethisaita! Nũndũ kethĩwa mavinya ala mekĩtwe kwenyu, meekiwe Tile na Sitoni, andũ ma kw’o methĩwa maalyũlile ngoo tene, makĩkala nthĩ mekĩĩte makunia na kwĩyũmba mũu.'),
('kam', 'LUK', 10, 14, 'Ĩndĩ Tile na Sitoni kũkethĩwa kwĩ kavaa ũsilĩlonĩ, kũte inyw’ĩ.'),
('kam', 'LUK', 10, 15, 'Naku Kavelinaumi, ũkookĩlw’a kũvika ĩutnĩ? Ũkatheew’a kũvika vala maveva ma akw’ũ mekalaa.'),
('kam', 'LUK', 10, 16, 'Ũla ũmwĩw’aa inyw’ĩ, nũmbĩw’aa nyie; na ũla ũmũleaa inyw’ĩ, nũndeaa nyie; na ũla ũndeaa nyie, nũmũleaa ũla wandũmie.'),
('kam', 'LUK', 10, 17, 'Na ala mĩongo mũonza masyoka me atanu, makyasya, Mwĩaĩi, o na ndaimoni niũtwĩnyivĩsya syĩtwanĩ yaku.'),
('kam', 'LUK', 10, 18, 'Nake amea, Nĩnoonaa Satani avalũka kuma ĩtunĩ ta ũtisi.'),
('kam', 'LUK', 10, 19, 'Nĩmwenei, nĩnamũnenga ũkũmũ wa ũkinya ĩũlũ wa nzoka na ing’auũ, na ĩũlũ wa vinya w’onthe wa mũmaitha: na mũtikona ũndũ ũthũku nongi.'),
('kam', 'LUK', 10, 20, 'Ĩndĩ manyai ũtana nũndũ ndaimoni niũmwĩnyivĩsya; ĩndĩ tanai nũndũ masyĩtwa menyu nĩmaandĩkĩtwe ĩtunĩ.'),
('kam', 'LUK', 10, 21, 'Na saa ũsu Yesũ atana nthĩnĩ wa Veva Mũtheu, na asya, Nĩngũũkatha, Asa, Mwĩaĩi wa ĩtu na nthĩ, nũndũ maũndũ asu nĩwamavithie andũ oĩ na ala me na ũmanyi, na wavuanĩsye twana tũnini: ĩĩ, Asa; nĩkwĩthĩwa nĩw’o wendeesye kwaku.'),
('kam', 'LUK', 10, 22, 'Nĩnĩnengetwe maũndũ onthe nĩ Asa wakwa: na vai mũndũ wĩsĩ Mwana nũũ, ate o Asa; kana Asa nũũ, ate o Mwana, na mũndũ o na wĩva ũla Mwana ũkwenda ũmũvuanĩsya.'),
('kam', 'LUK', 10, 23, 'Na eethyũũĩa amanyĩw’a, na amea me nzama, Nĩ maathime metho ala mekwona maũndũ ala mũkwona:'),
('kam', 'LUK', 10, 24, 'nũndũ nĩngũmũtavya, athani na asumbĩ aingĩ mendie kwona maũndũ ala mũkwona, na maiaamona; na kwĩw’a maũndũ ala mũkwĩw’a, na maiaamew’a.'),
('kam', 'LUK', 10, 25, 'Na ĩndĩ, mũmanyĩsya ũmwe wa mĩao ookĩla amũtate, akyasya, Mũmanyĩsya, nĩĩka ata kana nĩtiĩwe thayũ ũtathela?'),
('kam', 'LUK', 10, 26, 'Nake amwĩa, Mĩaonĩ kũandĩkĩtwe ata? Ũsomaa ata?'),
('kam', 'LUK', 10, 27, 'Asũngĩa, amwĩa, Mwende Mwĩaĩi Ngai waku na ngoo yaku yonthe, na thayũ waku w’onthe, na vinya waku w’onthe, na kĩlĩko kyaku kyonthe; na mwende mũtũi waku o tondũ wĩyendete mwene.'),
('kam', 'LUK', 10, 28, 'Nake amwĩa, Wasũngĩa w’o; ĩka ũu, na ũkeethĩwa na thayũ.'),
('kam', 'LUK', 10, 29, 'Ĩndĩ we, akyenda kwĩnenga mwene ũlũngalu, amũkũlya Yesũ, Na mũtũi wakwa nũũ?'),
('kam', 'LUK', 10, 30, 'Yesũ amũsũngĩa na amwĩa, Mũndũ ũmwe nĩwaumie Yelusaleme atheee Yeliko; nake akwatwa nĩ avutani, ala mamũvutie ngũa na mamũkũnanga, na mathi, mamũtia akilĩlye kũkw’a.'),
('kam', 'LUK', 10, 31, 'Na kweethĩwa mũthembi ũmwe atheea na nzĩa ĩsu: na amwona, aathũkĩla ũtee wake.'),
('kam', 'LUK', 10, 32, 'Na Mũlivai ũmwe ta ũu, avika vala vandũ, na amwona, nake aathũkĩla ũtee.'),
('kam', 'LUK', 10, 33, 'Ĩndĩ Mũsamalia ũmwe, akĩthi kyalo, avika vala waĩ: na yĩla wamwonie, amwĩw’ĩa ĩnee,'),
('kam', 'LUK', 10, 34, 'na athi vala ũĩ, amwova kũla wakũnangĩtwe, aikwĩtĩkĩsya mauta na mbinyu; na amũtũlya nyamũnĩ yake ĩla yamũkuĩte amũtwaa nyũmbanĩ ya aeni, akamũwaĩsye vo.'),
('kam', 'LUK', 10, 35, 'Na ũnĩ ũsu aumya silingi ilĩ, amũnenga mwene wa nyũmba ĩsu, na amwĩa, Mũwasye nesa; na wavĩtũkya ii, ngakũtũngĩa ngĩsyoka.'),
('kam', 'LUK', 10, 36, 'Wĩasya nĩ wĩva wa asu atatũ, ũla wonanisye aĩ mũtũi wa ũla wakwatiwe nĩ avutani?'),
('kam', 'LUK', 10, 37, 'Nake asya, Nĩ ũla wamwĩw’ĩe tei. Na Yesũ amwĩa, Naku thi, wĩke ta ũu.'),
('kam', 'LUK', 10, 38, 'Na yu makĩthi na nzĩa, avota mũsyĩ ũmwe: na mũndũ mũka ũmwe ũla wetawa Matha amũthokya nyũmbanĩ yake.'),
('kam', 'LUK', 10, 39, 'Nake aĩ na mwĩĩtu‐a‐inyia wetawa Meli, nake ekala nthĩ maũũnĩ ma Yesũ, akĩthukĩĩsya ndeto syake.'),
('kam', 'LUK', 10, 40, 'Ĩndĩ Matha athĩniw’e nĩ wĩa; na athi vala ũĩ, na amwĩa, Mwĩaĩi, ndũkwona ũndũ mwĩĩtu‐a‐ia ũndekanĩsye na wĩa nĩtethye nĩ nyioka? Mwĩe andetheesye.'),
('kam', 'LUK', 10, 41, 'Ĩndĩ Mwĩaĩi amũsũngĩa, amwĩa, Matha, Matha, nũkwĩnyamasya na kwĩthĩn’ya na maũndũ maingĩ:'),
('kam', 'LUK', 10, 42, 'ĩndĩ no ũndũ ũmwe wĩ vata: nũndũ Meli nũnyuvie kĩlungu kĩseo, kĩla ũtakavenwa.'),
('kam', 'LUK', 11, 1, 'Na kweethĩwa, ailyĩ vandũ akĩvoya, na amina, ũmwe wa amanyĩw’a make amwĩa, Mwĩaĩi, tũmanyĩsye kũvoya, tondũ Yoana wamamanyĩisye amanyĩw’a make.'),
('kam', 'LUK', 11, 2, 'Nake amea, Mũkĩvoya aasyai atũ, Asa, syĩtwa yaku yĩtaĩwe. Ũsumbĩ waku wũke.'),
('kam', 'LUK', 11, 3, 'Tũnenge kĩla mũthenya lĩu witũ ũtwĩanĩe.'),
('kam', 'LUK', 11, 4, 'Naku ũtũekee naĩ sitũ; nũndũ ithyĩ nĩtũũmũekea kĩla ũmwe ũla wĩ thiĩ naitũ. Na ndũkatũtwaae ũtatwanĩ.'),
('kam', 'LUK', 11, 5, 'Nake amakũlya, Nĩ wĩva wenyu ũla wĩ na mũnyanyae, nake aithi kwake ũtukũ katĩ, aimwĩa, Mũnyanyawa, ngovethya imũtũ itatũ;'),
('kam', 'LUK', 11, 6, 'nũndũ mũnyanyawa nĩwoka auma kyalo, na ndi na kĩndũ kya kũmũathĩsya?'),
('kam', 'LUK', 11, 7, 'Na ũla wĩ nthĩnĩ akamũsũngĩa, akyasya, Eka kũnyamasya: nũndũ nĩnĩvingie mũomo, na nĩngomete na syana syakwa; nditonya kũkĩla ngũnenge.'),
('kam', 'LUK', 11, 8, 'Nĩngũmwĩa, O na ethĩwa ndokĩla amũnenge nũndũ nĩ mũnyanyae, ĩndĩ ũndũ wa kĩthing’ĩĩsyo kyake akookĩla amũnenge o ila wĩ vata nasyo.'),
('kam', 'LUK', 11, 9, 'Nakwa nĩngũmũtavya, Voyai, na mũkanengwa; manthai, na mũkoona vingũsyai, na mũkavingũĩwa.'),
('kam', 'LUK', 11, 10, 'Nũndũ ũla ũnũkũvoya nũnũũnengwa; na ũla unũũmantha nũnũkwona; na ũla ũnũũvingũsya nũnũũvingũĩwa.'),
('kam', 'LUK', 11, 11, 'Nĩ wĩva wenyu, ĩthe wa mwana, eetw’a kĩmũtũ nĩ mwana wake, nũmũnenga ĩvia? Kana eetw’a ĩkũyũ, vandũ va ĩkũyũ nũmũnenga nzoka?'),
('kam', 'LUK', 11, 12, 'Kana eetw’a ĩtumbĩ, nũmũnenga kĩng’auũ?'),
('kam', 'LUK', 11, 13, 'Ethĩwa inyw’ĩ ĩndĩ, ala mwĩ athũku, nĩmwĩsĩ kũnenga syana syenyu mĩthĩnzĩo mĩseo, ti mbee mũno Ĩthe wenyu ũla wa ĩtunĩ kũmanenga Veva Mũtheu ala mamwĩtasya?'),
('kam', 'LUK', 11, 14, 'Nake aumya ndaimoni ĩla ĩtaneenaa. Na kweethĩwa, yĩla ndaimoni yauma, ũla mũndũ ũtaneenaa, aneena; na andũ ma ĩkomano maseng’a.'),
('kam', 'LUK', 11, 15, 'Ĩndĩ amwe masya, Nũnũkumya ndaimoni na vinya wa Veelisevuli, mũnene wa ndaimoni.'),
('kam', 'LUK', 11, 16, 'Na angĩ mamũtata, makyenda aumye kyama ĩtunĩ.'),
('kam', 'LUK', 11, 17, 'Ĩndĩ nake, akĩmanya mosũanĩo moo, amea, Kĩla ũsumbĩ wĩvathanĩtye nũetae wanangĩkonĩ; na nyũmba yatilĩkangana na ĩngĩ nĩvalũkaa.'),
('kam', 'LUK', 11, 18, 'Na ethĩwa Satani nĩwĩvathanĩtye ũu, ũsumbĩ wake ũkaũngama ata? Nũndũ nĩmũkwasya nĩngumya ndaimoni na vinya wa Veelisevuli.'),
('kam', 'LUK', 11, 19, 'Nakwa ethĩwa numasya ndaimoni na vinya wa Veelisevuli, ana menyu masyumasya na vinya waũ? Kwondũ wa ũu makeethĩwa me asilĩli menyu.'),
('kam', 'LUK', 11, 20, 'Ĩndĩ ethĩwa nyie numasya ndaimoni na kyaa kya Ngai, nĩ w’o ĩndĩ ũsumbĩ wa Ngai nũmũkĩe inyw’ĩ.'),
('kam', 'LUK', 11, 21, 'Mũndũ wĩ vinya ũla ũkuĩte mĩio ya kaũ asũvĩaa nyũmba yake, syĩndũ syake syĩkalaa syĩ mboo:'),
('kam', 'LUK', 11, 22, 'ĩndĩ yĩla ũla wĩ vinya kwĩ we wĩũka, na kũmũkĩlya vinya, ũsu akamũvena mĩio yake yonthe ya kaũ ĩla wĩkwetye, akĩaan’ya mũtavo wake.'),
('kam', 'LUK', 11, 23, 'Ũla ũte ngalĩ yakwa ũsu e ũndũ nakwa; na ũla ũtombanasya nakwa nũnyaĩĩkasya.'),
('kam', 'LUK', 11, 24, 'Veva mũvuku wauma mũndũnĩ, ũvĩtĩlaa kũndũ kũte manzĩ, ũkĩmantha ũthũmũo, na walea kwona, ũkyasya, Nĩngũsyoka nyũmbanĩ yakwa ĩla naumie.'),
('kam', 'LUK', 11, 25, 'Naw’o wooka, weethĩa yĩ ndute, na yĩ mbanakavye.'),
('kam', 'LUK', 11, 26, 'Nĩvo ĩndĩ ũithi, ũkyosa maveva angĩ mũonza mathũku kũte w’o; na mailika na kwĩkala vo: na mwĩkalĩle wa ĩtina wa mũndũ ũsu wĩtw’ĩka mũthũku kũte ũla wa mbee.'),
('kam', 'LUK', 11, 27, 'Na kweethĩwa, akĩneena maũndũ asu, mũndũ mũka ũmwe wa ĩkomano ookĩlya wasya, na amwĩa, Nĩ ĩathime ĩvu yĩla yaũkuie, na nondo ila woongie.'),
('kam', 'LUK', 11, 28, 'Nake asya, Ĩĩ, ĩndĩ, nĩ aathime mbee, ala mew’aa ndeto ya Ngai, makĩmĩkwata.'),
('kam', 'LUK', 11, 29, 'Na yila andũ aingĩ mambĩlĩlye kũmũmbanĩa, ambĩlĩlya ũneena, Ũsyao ũũ nĩ ũsyao mũthũku: nũũmantha kyama; na ndwĩnengwa kyama ate o kyama kya Yona.'),
('kam', 'LUK', 11, 30, 'Nũndũ o tondũ Yona watw’ĩkie wonan’yo kwa Anineva, no ta ũu Mwana wa mũndũ akeethĩwa kwa ũsyao ũũ.'),
('kam', 'LUK', 11, 31, 'Na ũla mũsumbĩ mũndũ mũka wa ngalĩ ya ĩtheo, nũkokĩla ũsilĩlonĩ vamwe na andũ ma ũsyao ũũ, na akamasilĩla: nũndũ we nĩwokie kuma itulunĩ sya nthĩ nĩ kana ew’e ũĩ wa Solomoni; na sisyai, vaa ve ũla mũnene kwĩ Solomoni.'),
('kam', 'LUK', 11, 32, 'Andũ ma Nineva makaũngama ũsilĩlonĩ vamwe na ũsyao ũũ, na makoosilĩla: nũndũ nĩmaalyũlile ngoo ũtavan’yonĩ wa Yona; na sisyai, vaa ve ũla mũnene kwĩ Yona.'),
('kam', 'LUK', 11, 33, 'Vai mũndũ ũnũũkwatya taa na kũvitha ĩimanĩ, kana ungu wa ĩmisi, ĩndĩ nũnũũwia vala vatũlu, nĩ kana ala meũvota mone kyeni.'),
('kam', 'LUK', 11, 34, 'Taa wa mwĩĩ waku nĩ itho yaku: yĩla itho yaku yĩ ĩseo, mwĩĩ waku w’onthe nĩwusũĩtwe nĩ kyeni; ĩndĩ yĩla yĩ ĩthũku, mwĩĩ waku naw’o nũtulĩtye kĩvindu.'),
('kam', 'LUK', 11, 35, 'Ĩsũvĩe ĩndĩ, kana kyeni kĩla kĩ nthĩnĩ waku kĩtikethĩwe kĩvindu.'),
('kam', 'LUK', 11, 36, 'Kwondũ wa ũu ethĩwa mwĩĩ waku w’onthe nĩwusũĩtwe nĩ kyeni, ũte vandũ ve kĩvindu, ũkeethĩwa usũĩtwe nĩ kyeni ki, o tondũ taa ũkũmulĩka na kyeni kyaw’o yĩla wakanĩte nesa.'),
('kam', 'LUK', 11, 37, 'Akĩneena ũu, Mũvalisi ũmwe amwĩta oke aye lĩu kwake: na avota, ekala nthĩ aye.'),
('kam', 'LUK', 11, 38, 'Na Mũvalisi oona ũu, aseng’a nũndũ ndaathamba atanamba kũya.'),
('kam', 'LUK', 11, 39, 'Na Mwĩaĩi amwĩa, Inyw’ĩ Avalisi nĩmũtheasya kĩkombe na ĩsaani ĩũlũ; ĩndĩ nthĩnĩ nĩmusũĩtwe nĩ ũvutani na ũthũku.'),
('kam', 'LUK', 11, 40, 'Inyw’ĩ atumanu, ũla wombie ĩũlũ tiwe wombie nthĩnĩ?'),
('kam', 'LUK', 11, 41, 'Ĩndĩ nenganei motethyo ma syĩndũ ila mwĩ nasyo, na sisyai, syĩndũ syonthe ikeethĩwa syĩ ntheu kwenyu.'),
('kam', 'LUK', 11, 42, 'Woo nĩ wenyu Avalisi! Nũndũ nĩmumasya kĩlungu kya ĩkũmi kya mindi na laũ na syĩndĩ ingĩ sya ũvanda, mũkĩtia ũsili wa katĩ na wendo wa Ngai: ĩndĩ asu nĩmwaĩlwe nĩ kũmeka, na ti kũtia asu angĩ mũtamekĩte.'),
('kam', 'LUK', 11, 43, 'Woo nĩ wenyu Avalisi! Nũndũ nĩmwendaa ivĩla sya mbee masinakokenĩ, na ngethi sya andũ ing’ang’anĩ.'),
('kam', 'LUK', 11, 44, 'Woo nĩ wenyu! Nũndũ mũtilyĩ ta mbũa itonekaa, na ala makũnĩlaa ĩũlũ wasyo matyĩsĩ kana syĩ kw’o.'),
('kam', 'LUK', 11, 45, 'Na ũmwe wa amanyĩsya ma mĩao amwĩa, Mũmanyĩsya, ũkyasya ũu nũũtũneenea o naitũ naĩ.'),
('kam', 'LUK', 11, 46, 'Nake asya, O nenyu amanyĩsya ma mĩao, woo nĩ wenyu! Nũndũ nĩmũmaĩkasya andũ mĩio mĩito ĩtakuĩka, nenyu mũtiĩtĩkĩla kũmĩkiita mĩio ĩsu, o na kyaa kĩmwe.'),
('kam', 'LUK', 11, 47, 'Woo nĩ wenyu! Nũndũ inyw’ĩ nĩmwakaa mbũa sya athani, na aaĩthe menyu nĩmo mamoaie.'),
('kam', 'LUK', 11, 48, 'Ũu nĩw’o mũkũsĩĩa meko ma aaĩthe menyu na kũmetĩkĩla: nũndũ nĩmo mamoaie, nenyu nĩmũkwaka mbũa syoo.'),
('kam', 'LUK', 11, 49, 'Kwondũ wa ũũ ũĩ wa Ngai nĩwaneenie, Ngamatũmĩa athani na atũmwa; na amwe moo makamoaa na kũmathĩn’ya;'),
('kam', 'LUK', 11, 50, 'nĩ kana nthakame ya athani onthe, ĩla yetĩkiw’e nthĩ kuma mwambĩlĩlyonĩ wa nthĩ, ĩandũwe kwa ũsyao ũũ;'),
('kam', 'LUK', 11, 51, 'kuma nthakame ya Aveli kũvika nthakame ya Nzakalia, ũla woaĩwe katĩ wa kĩthembeo na vala vatheu: ĩĩ, nĩngũmwĩa, ĩkaandũwa kwa ũsyao ũũ.'),
('kam', 'LUK', 11, 52, 'Woo nĩ wenyu, inyw’ĩ amanyĩsya ma mĩao! Nũndũ nĩmwoosie ũvungũo wa ũmanyi: inyw’ĩ ene mũiaavota, na ala mavotaa asu nĩmwamasiĩĩaa.'),
('kam', 'LUK', 11, 53, 'Na auma kw’o, aandĩki na Avalisi mathing’ĩĩsya mũno kũmũkũlya, maitata kũtuma aneena maũndũ maingĩ;'),
('kam', 'LUK', 11, 54, 'makĩmantha ũndũ wumĩte kanyw’anĩ wake mamũvinganĩsye naw’o.'),
('kam', 'LUK', 12, 1, 'Na ĩndĩ ĩvinda yĩu, andũ ngili nyingĩ moombana, mũvaka makinyangana, nĩvo ĩndĩ wambĩlĩlye kũmea amanyĩw’a make, Ĩsũvĩei ĩlawa ya Avalisi, nayo nĩ wangangan’yo.'),
('kam', 'LUK', 12, 2, 'Ĩndĩ vai ũndũ ũvw’ĩke, ũtakavuũwa; kana ũndũ ũvithe, ũtakamanyĩka.'),
('kam', 'LUK', 12, 3, 'Kwondũ wa ũu o ũla mwaneenee kĩvindunĩ ũkeew’ĩka kyeninĩ; na ũla mwaneenee na kĩwe tũsũmbanĩ twa nthĩnĩ ũkatavanĩw’a nyũmbanĩ ĩũlũ.'),
('kam', 'LUK', 12, 4, 'Nakwa nĩngũmũtavya anyanyawa makwa, Manyai ũmakĩa ala moaa mwĩĩ, na ĩtina maitonya ũndũ ũngĩ.'),
('kam', 'LUK', 12, 5, 'Ĩndĩ nĩngũmũtavya ũla mwaĩle kũmũkĩa: Mũkĩei ũla ĩtina wa kũaa wĩ na vinya wa kwĩkĩa Ngienanĩ; ĩĩ, nĩngũmũtavya, Mũkĩei ũsu.'),
('kam', 'LUK', 12, 6, 'Tũsũni tũtano tũithoow’a masendi elĩ? Na Ngai ndolwa nĩ kamwe katw’o.'),
('kam', 'LUK', 12, 7, 'O na nzw’ĩĩ syonthe sya mĩtwe yenyu nĩ ndale. Manyai ũkĩa ĩndĩ: inyw’ĩ mwĩ vata kwĩ tũsũni twingĩ.'),
('kam', 'LUK', 12, 8, 'Nakwa nĩngũmwĩa, Kĩla mũndũ ũla wĩmbumbũlaa mbee wa andũ, Mwana wa mũndũ akamumbũlaa mbee wa alaĩka ma Ngai:'),
('kam', 'LUK', 12, 9, 'ĩndĩ ũla wĩngaĩaa mbee wa andũ akakaĩawa mbee wa alaĩka ma Ngai.'),
('kam', 'LUK', 12, 10, 'Na ũla wĩmũneenea Mwana wa mũndũ ndeto, akaekewa: ĩndĩ ũla wĩmũuma Veva Mũtheu ndakaekewa.'),
('kam', 'LUK', 12, 11, 'Na yĩla makamũtwaa mbee wa ala ma masinakoke, na asumbĩki, na ala me na ũkũmũ wa kũsilĩla, mũikavũavũane ũndũ mwĩmasũngĩa kana ũndũ mwĩneena:'),
('kam', 'LUK', 12, 12, 'nũndũ Veva Mũtheu akamũmanyĩsya saa o ũsu ũndũ ũla mwaĩlwe nĩ kũneena.'),
('kam', 'LUK', 12, 13, 'Na ũmwe wa ĩkomano amwĩa, Mũmanyĩsya, mũtavye mwana‐a‐ia andaĩe ũtiĩwa.'),
('kam', 'LUK', 12, 14, 'Ĩndĩ amwĩa, Mũndũ we, nũũ ũla ũndw’ĩte mũsili kana mũaan’ya ĩũlũ wenyu?'),
('kam', 'LUK', 12, 15, 'Nake amea, Ĩmanyĩlĩlei na ĩsũvĩei wendi w’onthe: nũndũ thayũ wa mũndũ ndumaa syĩndũnĩ syake, o na syĩ nyingĩ ata.'),
('kam', 'LUK', 12, 16, 'Na amatavya ngelekan’yo, akyasya, Mũũnda wa mũndũ mũthwii ũmwe wasyaĩte mũno:'),
('kam', 'LUK', 12, 17, 'na avindya ngoonĩ yake, akyasya, Nĩĩka ata, nũndũ ndi na vandũ va kũtuĩsya isyo syakwa?'),
('kam', 'LUK', 12, 18, 'Na asya, Ngeeka ũũ: ngathasya makũmbĩ makwa, nake angĩ manene; na vau ngatuĩsya isyo syakwa na isamũ syakwa syonthe.'),
('kam', 'LUK', 12, 19, 'Na ĩndĩ ngatavya ngoo yakwa, Ngoo, isamũ wĩ nasyo sya myaka mingĩ; thũmũa, ũkĩĩsaa na ũkĩnyusaa, wĩw’e mũyo.'),
('kam', 'LUK', 12, 20, 'Ĩndĩ Ngai amwĩa, Wĩ ndia we, ũtukũ ũũ thayũ waku nũkwoswa; isamũ isu wĩyũmbanĩsye, ikatw’ĩka syaũ?'),
('kam', 'LUK', 12, 21, 'Nĩw’o ũilyĩ mũndũ ũla wĩyũmbanĩasya isamũ, na ti mũthwii kwa Ngai.'),
('kam', 'LUK', 12, 22, 'Amea amanyĩw’a make, Kwondũ wa ũu nĩmwĩa, Mũikemakĩe ũndũ wa mathayũ menyu, kĩla mwĩya, kana ũndũ wa mĩĩ yenyu, kĩla mwĩĩvw’ĩka.'),
('kam', 'LUK', 12, 23, 'Nũndũ thayũ ũvĩtũkĩte lĩu, na mwĩĩ ũvĩtũkĩte ngũa.'),
('kam', 'LUK', 12, 24, 'Sũanĩai ũvoo wa ngũngũũ, nĩkwĩthĩwa itivandaa, na itikethaa; na iti na vandũ va kũmbanĩsya kana ĩkũmbĩ; na Ngai nĩwiĩthasya: inyw’ĩ mũi vata mũno kwĩ nyũnyi?'),
('kam', 'LUK', 12, 25, 'Na kwenyu aĩva ũla ũtonya kwĩyongeleela ũasa wake mũkono ũmwe kwondũ wa kwĩmakĩa?'),
('kam', 'LUK', 12, 26, 'Ĩndĩ ethĩwa mũtitonya kwĩka ũndũ ũla ũnini, mwĩĩmakĩa nĩkĩ ũndũ wa maũndũ ala angĩ?'),
('kam', 'LUK', 12, 27, 'Sũanĩai ũvoo wa malaa ma lili, ũndũ mameaa: maitethasya wĩa, na maiokothaa; ĩndĩ nĩngũmũtavya, O na Solomoni ndaĩanĩ yake yonthe ndaaĩvw’ĩka ta yĩmwe yamo.'),
('kam', 'LUK', 12, 28, 'Ĩndĩ ethĩwa Ngai nũvw’ĩkaa nyeki ya kĩthekanĩ ta ũu, ĩla ĩnĩkwĩkala ũmũnthĩ, na ũnĩ ĩkekw’a ikonĩ; ndakamũvw’ĩka inyw’ĩ mbee mũno, inyw’ĩ ma mũĩkĩĩo mũnini?'),
('kam', 'LUK', 12, 29, 'Nenyu manyai ũmantha kĩla mwĩya, na kĩla mwĩnyw’a, o na mũikethĩwe na nzika.'),
('kam', 'LUK', 12, 30, 'Nũndũ syĩndũ isu syonthe nimanthawa nĩ mbaĩ sya nthĩ: ĩndĩ Ĩthe wenyu nĩwĩsĩ mwĩ na vata wa syĩndũ isu.'),
('kam', 'LUK', 12, 31, 'Ĩndĩ inyw’ĩ manthai ũsumbĩ wa Ngai, na syĩndũ isu nĩmũkongeleelwa.'),
('kam', 'LUK', 12, 32, 'Manyai ũkĩa, inyw’ĩ ĩĩthya ĩnini; nũndũ Ĩthe wenyu nĩwendeew’e nĩ kũmũnenga ũsumbĩ.'),
('kam', 'LUK', 12, 33, 'Tai ila mwĩ nasyo mũnengane motethyo; tumai ngusu itakũaa, ũthwii wĩ ĩtunĩ ũtanyivaa, vala kĩng’ei kĩtathengeaa, o na lungulu ũtananga.'),
('kam', 'LUK', 12, 34, 'Nũndũ vala ve ũthwii wenyu, nĩvo vethĩawa ngoo syenyu nasyo.'),
('kam', 'LUK', 12, 35, 'Mwĩthĩwe mwĩvotoete inyunyunĩ, na mataa menyu makanĩte;'),
('kam', 'LUK', 12, 36, 'nenyu mwĩthĩwe ta andũ ala meteele vwana woo, yĩla wĩsyoka kuma mũtwaanonĩ; nĩ kana akyũka na kũvingũsya, mamũvingũĩe mĩtũkĩ.'),
('kam', 'LUK', 12, 37, 'Nĩ ngathime ngombo ila ikethĩwa isyaĩĩsye vwana wasyo akyũka: nĩ w’o nĩngũmũtavya, akeevotoa na kũsyĩkalya nthĩ iye, na akooka kwithũkũma.'),
('kam', 'LUK', 12, 38, 'Na ethĩwa akooka ũsyaĩĩsyonĩ wa kelĩ, kana wa katatũ, na asyĩthĩa ta ũu, nĩ ngathime ngombo isu.'),
('kam', 'LUK', 12, 39, 'Ĩndĩ manyai ũũ, kethĩwa mwene wa nyũmba nĩwesĩ saa ũla kĩng’ei kĩkoka, ethĩwa asyaĩĩsye, o na ndaĩ aeka nyũmba yake ĩtũlwe.'),
('kam', 'LUK', 12, 40, 'Nenyu ĩkalai mwĩyũmbanĩtye: nĩkwĩthĩwa Mwana wa mũndũ akooka saa ũla mũtataĩĩe.'),
('kam', 'LUK', 12, 41, 'Na Vetelo akũlya, Mwĩaĩi, ngelekan’yo ĩno watũtavya ithyĩ, kana nĩ ya andũ onthe?'),
('kam', 'LUK', 12, 42, 'Mwĩaĩi asya, Mũsyaĩĩsya wa syĩndũ wĩ kĩthito na mũĩ nũũ, ũla ũkaiwa nĩ vwana wake ĩũlũ wa andũ make onthe, amanenge lĩu woo ĩvinda yaw’o?'),
('kam', 'LUK', 12, 43, 'Nĩ ngathime ngombo ĩla ĩkethĩwa ĩkĩka ta ũu, yĩla vwana wayo wĩũka.'),
('kam', 'LUK', 12, 44, 'Nĩ w’o nĩngũmwĩa, akamĩtw’a mũnene ĩũlũ wa isamũ syake syonthe.'),
('kam', 'LUK', 12, 45, 'Ĩndĩ ethĩwa ngombo ĩsu ĩkasya ngoonĩ yayo, Vwana wakwa nĩwĩkalĩte atekũka; na ĩkyambĩlĩlya kwakũnanga athũkũmi, aũme na aka, ĩkĩya, ĩkĩnyw’a, na ĩkĩtoona;'),
('kam', 'LUK', 12, 46, 'vwana wa ngombo ĩsu akooka mũthenya ũla ĩtataĩĩe, na saa ũla ĩtesĩ, nake akamĩkũna mũno, na akamĩnenga kĩanda kyayo vamwe na ala mate kĩthito.'),
('kam', 'LUK', 12, 47, 'Na ngombo ĩla yesĩ ũndũ vwana wayo ũnũkwenda, ĩndĩ ndĩaaĩyũmban’ya na ndĩaĩĩka kwenda kwake, ĩsu ĩkakũnwa makũna maingĩ;'),
('kam', 'LUK', 12, 48, 'ĩndĩ ĩla ĩtesĩ, na yekie maũndũ ala meanĩwe nĩ ũkũnwa, ĩsu ĩkakũnwa makũna manini. Na ũla ũnũũnengwa nyingĩ, nũketw’a nyingĩ: na ũla makamũnenga syĩndũ nyingĩ, ũsu makamwĩtya nyingĩ mbee.'),
('kam', 'LUK', 12, 49, 'Nĩnookie kwĩkya mwaki nthĩ; na ethĩwa nĩwakaniw’e nĩenda ata mbee?'),
('kam', 'LUK', 12, 50, 'Nĩ na ũvatiso wa kũvatiswa naw’o; na nĩngũthingaatwa mũno kũvikĩa ũndũ ũsu wĩanĩw’e!'),
('kam', 'LUK', 12, 51, 'Inywĩ’ mwĩasya nĩnookie kũete mũuo nthĩ? Nĩngũmũtavya, Ti w’o; ĩndĩ nĩ ũtilĩkangano:'),
('kam', 'LUK', 12, 52, 'nũndũ kuma yu vakeethĩwa andũ atano nyũmba ĩmwe makatanĩsya, andũ atatũ na elĩ, na elĩ na atatũ.'),
('kam', 'LUK', 12, 53, 'Makeethĩwa makĩtaanganĩsya, ĩthe na mwana, na mwana na ĩthe; inyia na mwĩĩtu wake, na mwĩĩtu na inyia wake; inyia wa mũũme na mũka wa mwana, na mũka wa mwana na inyia wa mũũme.'),
('kam', 'LUK', 12, 54, 'Nake amea andũ ma ĩkomano, Yĩla mũkwona ĩthweo yĩkyũkĩla ũthũĩlonĩ wa syũa, mĩtũkĩ nĩmũkwasya, Mĩono ya mbua nĩyũkĩte; na kũkĩkĩka ũu.'),
('kam', 'LUK', 12, 55, 'Na yĩla mũkwona kĩseve kĩkyuma ngalĩ ya ĩtheo nĩmũkwasya, Kũkavyũva mũno; na kũkĩkĩka ũu.'),
('kam', 'LUK', 12, 56, 'Inyw’ĩ angangan’ya, nĩmwĩsĩ kũvathũkan’ya maũndũ ma nthĩ na ma ĩtu; kũilyĩ ata ĩndĩ mũtesĩ kũvathũkan’ya ĩvinda yĩĩ?'),
('kam', 'LUK', 12, 57, 'Na nĩkĩ inyw’ĩ ene mũtisilaa katĩ?'),
('kam', 'LUK', 12, 58, 'Na yĩla ũendete na mũvinganĩsya waku kwa mũsili, mwĩ nzĩanĩ tata mũno wĩw’ane nake; nĩ kana ndakese ũkũtwaa kwa mũsili, na mũsili ũsu aikũnengane kwa ĩkanga, na ĩkanga yĩikwĩkĩa kolokolonĩ.'),
('kam', 'LUK', 12, 59, 'Nĩngũkwĩa, Ndũkauma vo nongi mũvaka waĩva kũvika kawela ka mũminũkĩlyo.'),
('kam', 'LUK', 13, 1, 'Na ĩvinda yĩu kwaĩ amwe vo ala mamũtavisye ũvoo wa Akalilii, ala Vilato wavulanilye nthakame yoo vamwe na nthembo syoo.'),
('kam', 'LUK', 13, 2, 'Nake amasũngĩa amea, Mwĩasya Akalilii asu maĩ athe kũvĩtũka Akalilii onthe, nũndũ maĩ na mathĩna ta asu?'),
('kam', 'LUK', 13, 3, 'Nĩngũmũtavya, Ti w’o: ĩndĩ mwalea kũalyũla ngoo, inyw’onthe mũkaanangĩka o ta ũu.'),
('kam', 'LUK', 13, 4, 'Kana mwĩasya ala ĩkũmi na nyanya ala matumbiwe nĩ nyũmba kũya Siloami, yamoaa, maĩ athe kũvĩtũka andũ onthe ala matwĩe Yelusaleme?'),
('kam', 'LUK', 13, 5, 'Nĩngũmũtavya, Ti w’o: ĩndĩ mwalea kũalyũla ngoo inyw’onthe mũkaanangĩka o ta ũu.'),
('kam', 'LUK', 13, 6, 'Nake aneena ngelekan’yo ĩno; Mũndũ ũmwe aĩ na mũkũyũ ũvandĩtwe mũũndanĩ wake wa mĩsavivũ; nake ooka akĩmantha makũyũ mũkũyũnĩ ũsu, na ndaamona.'),
('kam', 'LUK', 13, 7, 'Na amwĩa mũĩmi wa mĩsavivũ, Sisya, myaka ĩno ĩtatũ nũkaa kũmantha makũyũ mũkũyũnĩ ũũ, na ndyaamona: ũteme; wĩanangĩa nthĩ kĩ?'),
('kam', 'LUK', 13, 8, 'Nake asũngĩa, amwia, Vwana, ekana naw’o mwaka ũũ, nambe kũĩmĩa na kwĩkĩa vũũ:'),
('kam', 'LUK', 13, 9, 'na ĩndĩ wasyaa, nĩ ũseo; na walea ũsyaa, ũkatema.'),
('kam', 'LUK', 13, 10, 'Na mũthenya wa savato ekala ĩsinakokenĩ yĩmwe akĩmanyĩsya.'),
('kam', 'LUK', 13, 11, 'Na sisya, nĩvo vaĩ mũndũ mũka ũla waĩ na veva wa wonzu ĩvinda ya myaka ĩkũmi na nyanya; na nĩwakungulele, na ndaĩ atonya kũũngalala nongi.'),
('kam', 'LUK', 13, 12, 'Yesũ amwona, amwĩta, na amwĩa, Mũndũ mũka, nĩwathaw’a wonzu waku.'),
('kam', 'LUK', 13, 13, 'Na amwilĩĩla moko make: na kavinda kau aũngalala, na amũkatha Ngai.'),
('kam', 'LUK', 13, 14, 'Na mũnene wa ĩsinakoke athata nũndũ Yesũ wavosya mũthenya wa savato, na asũngĩa na ayĩa ĩkomano, Kwĩ mĩthenya thanthatũ ĩla andũ maĩlwe nĩ kũtethya wĩa: mĩthenya ĩsu ũkai mũvow’e, ĩndĩ ti mũthenya wa savato.'),
('kam', 'LUK', 13, 15, 'Ĩndĩ Mwĩaĩi amũsũngĩa, amwĩa, Inyw’ĩ angangan’ya, kĩla mũndũ wenyu ndathaasya ng’ombe kana ĩng’oi yake vala yovetwe mũthenya wa savato, akatwaa kũnyithya?'),
('kam', 'LUK', 13, 16, 'Na mũndũ mũka ũũ, mwĩĩtu wa Avalaamu, ũla wovetwe nĩ Satani myaka ĩno ĩkũmi na nyanya, ndaĩlwe nĩ kũthaw’a kuma wovonĩ ũũ mũthenya wa savato?'),
('kam', 'LUK', 13, 17, 'Na akĩneena maũndũ asu nthũ syake syonthe syasonoka; na ĩkomano yonthe yatana ũndũ wa maũndũ asu onthe maseo ala meekiwe nĩwe.'),
('kam', 'LUK', 13, 18, 'Na ĩndĩ asya, Ũsumbĩ wa Ngai ũtilyĩ ata? Na nĩũelekan’ya na kyaũ?'),
('kam', 'LUK', 13, 19, 'Ũtilyĩ ta mbeke ya kalatali, ĩla yosiwe nĩ mũndũ, avanda mũũndanĩ wake; nayo yeana, yatwĩ’ka kĩtĩ; na nyũnyi sya yayaya nĩsyekalaa mbongenĩ syakyo.'),
('kam', 'LUK', 13, 20, 'Na ĩngĩ asya, Nĩũelekan’ya ũsumbĩ wa Ngai na kyaũ?'),
('kam', 'LUK', 13, 21, 'Ũilyĩ ta ĩlawa, yĩla mũndũ mũka wosie avitha mĩtanĩ ĩtatũ ya mũtu na w’onthe wakaata.'),
('kam', 'LUK', 13, 22, 'Nake aenda akyanganga ndũanĩ na mĩsyĩ, akĩmanyĩsya, akĩthi elekele Yelusaleme.'),
('kam', 'LUK', 13, 23, 'Na mũndũ ũmwe amũkũlya, Mwĩaĩi, ũtalo wa ala meũtangĩĩwa nĩ mũnini? Nake amea,'),
('kam', 'LUK', 13, 24, 'Thetheesyai kũvotela mũomonĩ mũtheke: nũndũ nĩngũmũtavya, aingĩ nĩmakenda kũvota, na matikatonya.'),
('kam', 'LUK', 13, 25, 'Yĩla mwene wa nyũmba wĩũkĩla na kũvinga mũomo, nenyu mũkambĩlĩlya kũũngama nza, mũkĩvingũsya mũomonĩ, mũkyasya, Mwĩaĩi, tũvingũĩe; nake akamũsũngĩa na kũmwĩa, Ndimwĩsĩ kũla mumĩte;'),
('kam', 'LUK', 13, 26, 'nĩvo mũkambĩlĩlya kwasya, No tũnaĩsanĩaa na no tũnanyusanĩaa naku, no wamanyĩasya nzĩanĩ kwitũ;'),
('kam', 'LUK', 13, 27, 'nake akasya, Nĩngũmũtavya, Ndimwĩsĩ kũla mumie; ĩvetei kũasa nakwa, inyw’onthe eki ma naĩ.'),
('kam', 'LUK', 13, 28, 'Vo vakethĩwa kĩĩo na kũvevetan’ya maeo yĩla mũkona Avalaamu, na Isaka, na Yakovo, na athani onthe, ũsumbĩnĩ wa Ngai, nenyu mũkĩkw’a nza.'),
('kam', 'LUK', 13, 29, 'Na nĩmakoka kuma wumĩlonĩ wa syũa na ũthũĩlonĩ wayo, na kuma ngalĩ ya ĩũlũ na ngalĩ ya ĩtheo, makekala nthĩ ũsumbĩnĩ wa Ngai.'),
('kam', 'LUK', 13, 30, 'Na sisyai, ve ala me ĩtina makethĩwa me mbee, na ve ala me mbee makethĩwa me ĩtina.'),
('kam', 'LUK', 13, 31, 'Na saa o ũsu Avalisi amwe mathi vala ũĩ, maimwĩa, Uma kũũ, ũthi: nũndũ Elote nũnũkwenda akũae.'),
('kam', 'LUK', 13, 32, 'Nake amea, Endai mũkatavye mbĩwa ĩsu, Sisya, nĩngumya ndaimoni na kũvosya ũmũnthĩ na ũnĩ, na mũthenya wa katatũ ngaminũkĩlya.'),
('kam', 'LUK', 13, 33, 'Ĩndĩ nĩnaĩlwe nĩ kwĩthĩwa nzĩanĩ nĩendete ũmũnthĩ na ũnĩ na aũke: nũndũ ndũtonyeka mwathani kũaĩwa kũngĩ ate o Yelusaleme.'),
('kam', 'LUK', 13, 34, 'Yelusaleme, Yelusaleme, ũla wũaa athani, na kũmakimanga na mavia ala matũmiwe kwaku! Nĩ mavinda meana nendie kũmban’ya syana syaku, o ũndũ ngũkũ yũmbanasya tũswii twayo nthwaunĩ syayo ĩndĩ nenyu mũtyaaĩtĩkĩla!'),
('kam', 'LUK', 13, 35, 'Nĩmwenei, nyũmba yenyu nĩtiĩtwe yĩ nthei: nakwa nĩngũmũtavya, Mũtikambona ĩngĩ mũvaka yĩla mũkasya, Nĩ mũathime ũla wũkĩte syĩtwanĩ ya Mwĩaĩi.'),
('kam', 'LUK', 14, 1, 'Na kweethĩwa mũthenya ũmwe wa savato yĩla wavotie nyũmbanĩ ya ũmwe wa anene ma Avalisi aye lĩu, mekala makĩmũsyĩma.'),
('kam', 'LUK', 14, 2, 'Na sisya, nĩvo vaĩ mũndũ ũmwe ũwaĩte wimbu, wekalĩte mbee wake.'),
('kam', 'LUK', 14, 3, 'Na Yesũ amasũngĩa amanyĩsya ma mĩao na Avalisi, amakũlya, Nĩkwosana na ĩla mĩao kũvosya mũthenya wa savato, kana ti w’o?'),
('kam', 'LUK', 14, 4, 'Ĩndĩ mekala makilĩtye. Nake amwosa ũ mũndũ, amũvosya, na amũeka athi.'),
('kam', 'LUK', 14, 5, 'Na amakũlya, Nũũ kwenyu ũla wĩ na ng’ombe kana ĩng’oi yĩvalũkĩte ĩimanĩ, na ndakayumya na mĩtũkĩ mũthenya wa savato?'),
('kam', 'LUK', 14, 6, 'Nao maiaatonya kũmũsũngĩa maũndũ asu.'),
('kam', 'LUK', 14, 7, 'Nake amatavya ngelekan’yo ala meetiwe, yĩla wonie ũndũ manyuvie ivĩla sya mbee; akĩmea,'),
('kam', 'LUK', 14, 8, 'Weetwa nĩ mũndũ mũtwaanonĩ, ndũkekale kĩvĩla kya mbee; vatikethĩwe ũla wĩ ndaĩa kwĩ we wĩtĩtwe nĩwe,'),
('kam', 'LUK', 14, 9, 'na ũla wamwĩtĩe inyw’ĩ elĩ akooka na ũkwĩa, Mwathũkĩe mũndũ ũũ; naku ũkookĩla na nthoni ũkekale vandũ va ĩtina.'),
('kam', 'LUK', 14, 10, 'Ĩndĩ weetwa, enda wĩkale kĩvĩlanĩ kya ĩtina; nĩ kana ũla wakwĩtie ooka, akũtavye, Mũnyanyawa, ambata kũũ mbee: nĩvo ĩndĩ wĩĩthĩwa na ndaĩa methonĩ ma onthe ala mekalĩte makĩya naku.'),
('kam', 'LUK', 14, 11, 'Nũndũ ũla wĩnenevasya mwene nũkanyivw’a: na ũla wĩnyivasya mwene nũkanenevw’a.'),
('kam', 'LUK', 14, 12, 'Na amwĩa ũla wamwĩtie, Waua lĩu wa mũthenya kana wa wĩoo, manya ũmeta anyanyau, kana ana‐a‐inyia maku, kana mbaĩ yaku, kana atũi maku ala athwii; ũndũ matesa ũkwĩta makũĩve.'),
('kam', 'LUK', 14, 13, 'Ĩndĩ wavoka mboka, mete ala ngya, na ala me ithu, na ala mathuaa, na ililinda:'),
('kam', 'LUK', 14, 14, 'naku ũkeethĩwa mũathime; nũndũ mati na kĩndũ kya ũkũĩva: nũndũ ũkaĩvwa ũthayũũkyonĩ wa ala alũngalu.'),
('kam', 'LUK', 14, 15, 'Na ũmwe ũla wekalĩte nake makĩya lĩu, eew’a maũndũ asu, amwĩa, Nĩ mũathime ũla ũkaya kĩmũtũ ũsumbĩnĩ wa Ngai.'),
('kam', 'LUK', 14, 16, 'Ĩndĩ we amwĩa, Mũndũ ũmwe nĩwavokie mboka nene; na ameta aingĩ:'),
('kam', 'LUK', 14, 17, 'na saa wa kũya mboka wavika atũma ngombo yake ĩmatavye ala meetiwe, Ũkai; syĩndũ syonthe nĩsyũmbanĩtw’e.'),
('kam', 'LUK', 14, 18, 'Na onthe mambĩlĩlya kwĩmilanga na ngoo ĩmwe. Ũla wa mbee asya, Nĩnthooete mũũnda, na nĩnaĩlwe nĩ kũthi kũoa; ame naku, ndeka nĩthi.'),
('kam', 'LUK', 14, 19, 'Na ũngĩ asya, Nĩnthooete ndewa ĩkũmi sya wĩa, na nĩngũthi kwitata; ame naku, ndeka nĩthi.'),
('kam', 'LUK', 14, 20, 'Na ũngĩ asya, Nĩndwaĩte mũka, na ũndũ wa ũu nditonya kũka.'),
('kam', 'LUK', 14, 21, 'Na ngombo yooka, yamũtavya vwana wayo maũndũ asu. Na ĩndĩ mwene wa nyũmba athata, na amĩtavya ngombo yake, Umaala mĩtũkĩ, ũthi nzĩanĩ nene na tũsĩlanĩ twa ndũa, ũete vaa ala ngya, na ala me ithu, na ililinda, na ala mathuaa.'),
('kam', 'LUK', 14, 22, 'Na ngombo yamwĩa, Vwana, ũndũ ũla wĩaie nĩwĩkiwe, ĩndĩ no vatiele ũthei.'),
('kam', 'LUK', 14, 23, 'Na vwana eea ĩ ngombo, Umaala, ũthi na malelũ na mĩvakanĩ, ũmaingĩĩsye moke, nĩ kana nyũmba yakwa yusũe.'),
('kam', 'LUK', 14, 24, 'Nũndũ nĩngũmũtavya, wa ala meetiwe vai ũmwe ũkasama lĩu wakwa.'),
('kam', 'LUK', 14, 25, 'Na makomano manene maendan’ya nake: na eethyũũa, amea,'),
('kam', 'LUK', 14, 26, 'Mũndũ akyũka kwakwa atamenete ĩthe wake, na inyia, na mũka, na syana syake, na ana‐a‐inyia na eĩtu‐a‐inyia, ĩĩ, o na thayũ wake, ndatonya kwĩthĩwa e mũmanyĩw’a wakwa.'),
('kam', 'LUK', 14, 27, 'O ũla ũtakuaa ngelan’yo yake, aingatĩĩa, ndatonya kwĩthĩwa e mũmanyĩw’a wakwa.'),
('kam', 'LUK', 14, 28, 'Nũũ kwenyu, akyenda kwaka nyũmba yĩ mũnyoolo ũtambaa kwĩkala nthĩ na kũtala mbesa sya kũmyakĩthya, nĩ kana amanye ethĩwa e nasyo sya kũmĩmina?'),
('kam', 'LUK', 14, 29, 'Ndakese kwĩthĩa aaka wambĩlĩlyo, na ndatonya kũmĩmina, onthe ala monaa mambĩlĩlye ũmũthekeea,'),
('kam', 'LUK', 14, 30, 'makyasya, Mũndũ ũũ nĩwambĩlĩlye kwaka, na nĩwaemiwe nĩ ũminũkĩlya.'),
('kam', 'LUK', 14, 31, 'Kana nĩ mũsumbĩ wĩva akĩthi kũkita na mũsumbĩ ũngĩ ũtambaa kwĩkala nthĩ na kũsũanĩa kana we, e na andũ ngili ĩkũmi, nũtonya kũkomana na ũla ũmũkĩe wĩ na andũ ngili mĩongo ĩlĩ?'),
('kam', 'LUK', 14, 32, 'Ethĩwa ti ũu, nũnũũtũmana, yĩla ũsu wĩ kũasa, amũkũlye ũndũ matonya kwĩthĩwa na mũuo.'),
('kam', 'LUK', 14, 33, 'Kwondũ wa ũu kĩla ũmwe wenyu ũla ũteũekana na syonthe ila wĩ nasyo, ndatonya kwĩthĩwa mũmanyĩw’a wakwa.'),
('kam', 'LUK', 14, 34, 'Mũnyũ nĩ mũseo: ĩndĩ ethĩwa nũthelete mũsamo waw’o, ũkasamĩthw’a ĩngĩ na kyaũ?'),
('kam', 'LUK', 14, 35, 'Ti mũseo wa kwĩkĩa mũũndanĩ kana vũũnĩ: ĩndĩ ũkekw’a ĩtheka. Ũla wĩ matũ ma kwĩw’a, nĩew’e.'),
('kam', 'LUK', 15, 1, 'Na aumya ma koti onthe na ala athe mamũthengeea kũmwĩthukĩĩsya.'),
('kam', 'LUK', 15, 2, 'Na Avalisi na aandĩki manyungunyĩsya, makyasya, Mũndũ ũũ nũnũkwosa ala athe na kũĩsanĩa nao.'),
('kam', 'LUK', 15, 3, 'Na amatavya ngelekan’yo ĩno, akyasya,'),
('kam', 'LUK', 15, 4, 'Nĩ mũndũ wĩva kwenyu, ũla wĩ na malondu ĩana, na akyasya yĩmwe, ũtatia ala mĩongo kenda na kenda weũnĩ, akamanthe yĩla yaie, mũvaka ayona?'),
('kam', 'LUK', 15, 5, 'Na ayona, akĩyilĩĩla ituonĩ syake, akĩw’a mũyo.'),
('kam', 'LUK', 15, 6, 'Na avika kwake, aimeta anyanyae na atũi make, akĩmea, Tanai vamwe nakwa, nũndu nĩnoona ĩlondu yakwa yĩla yĩĩ yau.'),
('kam', 'LUK', 15, 7, 'Nĩngũmũtavya, ta ũu vakeethĩwa ũtanu ĩtunĩ nũndũ wa ũmwe mwathe akĩalyũla ngoo, kwĩ ala alũngalu mĩongo kenda na kenda, ala mate vata wa kũalyũla ngoo.'),
('kam', 'LUK', 15, 8, 'Kana mũndũ mũka nĩ wĩva ũla wĩ na silingi ĩkũmi, akyasya ĩmwe, ũtakwatya taa, na kũtuta nyũmba, akĩmantha na kĩthing’ĩĩsyo mũvaka amyona?'),
('kam', 'LUK', 15, 9, 'Na amyona, aimeta anyanyae na atũi make, akyasya, Tanai vamwe nakwa, nĩkwĩthĩwa nĩnoona ĩla silingi nĩnaaĩtye.'),
('kam', 'LUK', 15, 10, 'O ta ũu, nĩngũmwĩa, ve ũtanu kwa alaĩka ma Ngai ũndũ wa ũmwe mwathe akĩalyũla ngoo.'),
('kam', 'LUK', 15, 11, 'Nake asya, Mũndũ ũmwe aĩ na ana elĩ:'),
('kam', 'LUK', 15, 12, 'na ĩlumaita yamwĩa ĩthe, Asa, nenga kĩlungu kya ũthwii kĩla kĩkethĩwa kĩ kyakwa. Na amaan’ya syĩndũ syake.'),
('kam', 'LUK', 15, 13, 'Na matũkũ manini mavĩta, ĩlumaita yoomban’ya mĩio yayo yonthe yathi nthĩ ĩngĩ yĩ kũasa; na nĩkw’o yaanangĩe syĩndũ syayo na mothũku onthe.'),
('kam', 'LUK', 15, 14, 'Na yamina kwananga syonthe, nĩw’o kwookie yũa ĩnene nthĩ ĩsu; nayo yambĩlĩlya kũthĩna.'),
('kam', 'LUK', 15, 15, 'Na yathi kwĩkala kwa mũndũ ũmwe wa nthĩ ĩsu; nake ayĩnenga wĩa wa kũĩthya ngũlũe isesinĩ syake.'),
('kam', 'LUK', 15, 16, 'Na kweethĩwa nĩyendaa kũvũnw’a nĩ mosyao ma mũtĩ wa mũkalavi ala ngũlũe syaĩsaa: ĩndĩ vaiaĩ mũndũ waayĩnenga.'),
('kam', 'LUK', 15, 17, 'Na yĩla yavindũkie yasya, Nĩ athũkũmi meana ata ma asa wakwa ala me na lĩu ũla matatonya ũmina, nakwa nĩngũkw’ĩa kũũ nĩ nzaa!'),
('kam', 'LUK', 15, 18, 'Nĩngũkĩla nĩthi kwa asa wakwa, na ngĩmwĩa, Asa, nĩnĩvĩtĩtye ĩtunĩ, na mbee waku:'),
('kam', 'LUK', 15, 19, 'na yu ndyaĩlĩtwe nĩ kwĩtwa mwana waku: mbĩkalya ta ũmwe wa athũkũmi maku.'),
('kam', 'LUK', 15, 20, 'Na yookĩla yathi kwa ĩthe. Ĩndĩ yĩ kũasa, ĩthe wayo ayona, na eew’a ĩnee, asemba, ayĩkwatĩla ngingonĩ, ayĩmumunya.'),
('kam', 'LUK', 15, 21, 'Na ũla mwana amwĩa, Asa, nĩnĩvĩtĩtye ĩtunĩ, na mbee waku: na ndyaĩlĩtwe nĩ kwĩtwa mwana waku ĩngĩ.'),
('kam', 'LUK', 15, 22, 'Ĩndĩ ĩthe asyĩa ngombo syake, Latyai mĩtũkĩ ngũa ĩla nzeo, mũmwĩkĩe; na mwĩkĩei ngome kyaa, na iatũ maũũ:'),
('kam', 'LUK', 15, 23, 'na etei kasalũ kala kanou, mũae, tũye, tũtane:'),
('kam', 'LUK', 15, 24, 'nĩkwĩthĩwa mwana ũũ wakwa aĩ mũkw’ũ, na nĩwathayũũka; aĩ mwau, na nĩwaumbũka. Na mambĩlĩlya kũtana.'),
('kam', 'LUK', 15, 25, 'Ĩndĩ mwana wake ũla mũkũũ aĩ mũũndanĩ: nake athengeea nyũmba, eew’a wathi ũkinwa.'),
('kam', 'LUK', 15, 26, 'Na amwĩta ũmwe wa athũkũmi, amũkũlya kĩtumi kya maũndũ asu.'),
('kam', 'LUK', 15, 27, 'Nake amwĩa, Mũinau nĩwoka; na au ooaa kasalũ kala kanou, nũndũ nĩwamwona e mũima.'),
('kam', 'LUK', 15, 28, 'Ĩndĩ athata, na alea kũvota: na ĩthe wake aumaala amwĩsũva.'),
('kam', 'LUK', 15, 29, 'Ĩndĩ amũsũngĩa, amwĩa ĩthe, Sisya, myaka ĩsu mingĩ nĩngũthũkũmaa, na ndyaavĩtan’ya mwĩao ũmwe waku; ĩndĩ ndwaanenga katena ka mbũi, ngatana vamwe na anyanyawa:'),
('kam', 'LUK', 15, 30, 'ĩndĩ yĩla mwana ũũ waku woka, ũla, wanangie syĩndũ syaku syonthe na malwaya, nĩwamũaĩa kasalũ kala kanou.'),
('kam', 'LUK', 15, 31, 'Nake amwĩa, Mwana wakwa, matukũ onthe wĩ nakwa, na ila nĩ nasyo syonthe nĩ syaku.'),
('kam', 'LUK', 15, 32, 'Ĩndĩ nĩtwaĩlĩtwe nĩ kũtana na kwĩw’a mũyo: nũndũ mũinau ũũ aĩ mũkw’ũ, na nĩwathayũũka: aĩ mwau, na nĩwaumbũka.'),
('kam', 'LUK', 16, 1, 'Na amea amanyĩw’a make, Kwaĩ mũndũ mũthwii waĩ na mũsyaĩĩsya wa syĩndũ syake; na ũsu avinganĩw’a kwake kana nĩwaĩtye syĩndũ syake.'),
('kam', 'LUK', 16, 2, 'Nake amwĩta, amwĩa, Ũvoo ũla ngwĩw’a wĩkaa nĩ mwaũ? Umya ũtalo wa ũsyaĩĩsyo waku; nũndũ ndũtonya kwĩthĩwa mũsyaĩĩsya ĩngĩ.'),
('kam', 'LUK', 16, 3, 'Na ũla mũsyaĩĩsya aneena nthĩnĩ wake, Nĩĩka ata nũndũ vwana wakwa nũnũũmbumya ũsyaĩĩsyonĩ wakwa? Ndi na vinya wa kũĩma; na nĩngũsonoka kũvoya andũ syĩndũ.'),
('kam', 'LUK', 16, 4, 'Nĩnĩsĩ ũndũ ngwĩka, kana yĩla nĩumw’a ũsyaĩĩsyonĩ, menthokya nyũmbanĩ syoo.'),
('kam', 'LUK', 16, 5, 'Na amwĩta kĩla mũndũ waĩ na thiĩ na vwana wake, na amwĩa ũla wa mbee, Thiĩ ũla wĩ naw’o na vwana wakwa wĩana ata?'),
('kam', 'LUK', 16, 6, 'Nake asya, Ithimi ĩana sya mauta. Amwĩa, Osa valũa wa thiĩ waku, wĩkale nthĩ mĩtũkĩ ũandĩke mĩongo ĩtano.'),
('kam', 'LUK', 16, 7, 'Na amwĩa ũngĩ, Thiĩ waku wĩana ata? Nake asya, Ithimi ĩana sya nganũ. Amwĩa, Osa valũa wa thiĩ waku, ũandĩke mĩongo nyanya'),
('kam', 'LUK', 16, 8, 'Na vwana wake akatha mũsyaĩĩsya ũla ũte mũlũngalu nũndũ nĩwĩkĩte na ũĩ: nũndũ ana ma nthĩ ĩno nĩ oĩ ũsyaonĩ woo kũte ana ma kyeni.'),
('kam', 'LUK', 16, 9, 'Nakwa nĩngũmwĩa, Ĩmanthĩei anyanya na ũthwii ũla ũte wa ũlũngalu; nĩ kana yĩla wĩthela, mamwose inyw’ĩ mawĩkalonĩ ma tene na tene.'),
('kam', 'LUK', 16, 10, 'Ũla wĩ na kĩthito ũndũnĩ ũnini mũno, e kĩthito maũndũnĩ manene: na ũla ũte mũlũngalu ũndũnĩ ũnini, nake ti mũlũngalu maũndũnĩ manene.'),
('kam', 'LUK', 16, 11, 'Kwondũ wa ũu ethĩwa mũtyaaĩthĩwa na kĩthito na ũthwii ũla ũte wa ũlũngalu, nũũ ũla ũkamũĩkĩĩa na ũthwii ũla wa w’o?'),
('kam', 'LUK', 16, 12, 'Na ethĩwa mũtyaĩ na kĩthito na syĩndũ sya mũndũ ũngĩ, nũũ ũla ũkamũnenga syĩndũ syenyu ene?'),
('kam', 'LUK', 16, 13, 'Vai mũthũkũmi ũtonya kũthũkũma mavwana elĩ; nũndũ akamena ũmwe, na akĩmwenda ũla ũngĩ; kana akalũman’ya na ũmwe, na akĩmũvũthya ũla ũngĩ. Mũtitonya kũmũthũkũma Ngai na ũthwii.'),
('kam', 'LUK', 16, 14, 'Na Avalisi, ala mendaa mbesa, meew’a maũndũ asu onthe; na mamũvũthya.'),
('kam', 'LUK', 16, 15, 'Nake amea, Inyw’ĩ mwĩ ala mwĩtusaa ene alũngalu kwa andũ; ĩndĩ Ngai nĩwĩsĩ ngoo syenyu: nũndũ ũndũ ũla ũnenevaw’a nĩ andũ nũmenetwe mũno nĩ Ngai.'),
('kam', 'LUK', 16, 16, 'Ĩla mĩao na athani maĩ kw’o kũvika Yoana: na kuma ĩvinda yĩu ũvoo mũseo wa ũsumbĩ wa Ngai nũtavanaw’a, na kĩla mũndũ nũvotaa na vinya.'),
('kam', 'LUK', 16, 17, 'Ĩndĩ nĩ ũvũthũ ĩtu na nthĩ kũvĩta, kwĩ kaũkenyũsyo kamwe ka ĩla mĩao kũvalũka mana.'),
('kam', 'LUK', 16, 18, 'O ũla ũekaa mũka wake, na aitwaa ũngĩ, nũnũũlaalaa: na o ũla wĩmũtwaa ũsu ũeketwe nĩ mũũme nũnũũlaalaa.'),
('kam', 'LUK', 16, 19, 'Kwaĩ mũndũ mũthwii ũmwe wekĩaa ngũa ĩilyĩ ta ndune na ya katane nzeo, nake ekalaa akĩtana atekwaĩwa nĩ kĩndũ mĩthenya yonthe:'),
('kam', 'LUK', 16, 20, 'na kwaĩ mũndũ mũvoyi wa syĩndũ wetawa Lasalo, waĩawa mbingĩlonĩ yake, wausũĩtwe nĩ itau,'),
('kam', 'LUK', 16, 21, 'nake endaa kũathĩw’a tũlungu tũla twavalũkangaa ũla mũthwii akĩya; o na ngitĩ nĩsyookaa kũmũnyenya itau syake.'),
('kam', 'LUK', 16, 22, 'Na kweethĩwa, ũla mũvoyi akw’a, na atwawa nĩ alaĩka mamwia kĩthũinĩ kya Avalaamu: na ũla mũndũ mũthwii nake akw’a, na enzĩwa nthĩ.'),
('kam', 'LUK', 16, 23, 'Na e vala maveva ma akw’ũ mekalaa ookĩlya metho make, e kĩnyamaĩonĩ, na oona Avalaamu e kũasa, na Lasalo kĩthũinĩ kyake.'),
('kam', 'LUK', 16, 24, 'Nake ookĩlya wasya, akyasya, Asa Avalaamu, mbĩw’ĩa tei, noitũma Lasalo, atole manzĩ na mũthya wa kyaa kyake na kũnthithya ũĩmĩ wakwa; nũndũ nĩngũthĩnĩa vaa mwakinĩ ũũ.'),
('kam', 'LUK', 16, 25, 'Ĩndĩ Avalaamu asya, Mwana wakwa, lilikana nĩwanengiwe moseo maku yĩla waĩ thayũ, na ta ũu Lasalo maũndũ mathũku: na yu nũnũũkiakiĩw’a vaa, naku nũkũnyamaw’a.'),
('kam', 'LUK', 16, 26, 'Na vamwe na ũu w’onthe, katĩ wenyu naitũ nĩvekĩĩtwe ĩtw’ĩku ĩnene, nĩ kana ala mendaa kuma vaa mainganĩsye vau matikatonye, na ala me kũu maikainge kũka vala tũĩ.'),
('kam', 'LUK', 16, 27, 'Nake asya, Ĩndĩ, asa, nĩngũũvoya ũmũtũme nyũmba kwa asa wakwa;'),
('kam', 'LUK', 16, 28, 'nũndũ nĩna ana‐a‐ia makwa atano; nĩ kana amanenge ũkũsĩ, matikoke vaa vandũ va kĩnyamaĩo.'),
('kam', 'LUK', 16, 29, 'Ĩndĩ Avalaamu asya, Me na Mose na athani; mamethukĩĩsye mo.'),
('kam', 'LUK', 16, 30, 'Nake asya, Aiee, asa Avalaamu: ĩndĩ ũmwe auma akw’ũnĩ athi vala maĩ, makaalyũla ngoo.'),
('kam', 'LUK', 16, 31, 'Nake amwia, Malea kwĩthukĩĩsya Mose na athani, o na mũndũ auma akw’ũnĩ, matiketĩkĩla.'),
('kam', 'LUK', 17, 1, 'Nake amea amanyĩw’a make, Kũitĩa kũka molulutĩkyo; ĩndĩ woo nĩ wa ũla ũtumaa molulutĩkyo moka!'),
('kam', 'LUK', 17, 2, 'Nĩ ũseo kwake kwoveewa ngingo ĩvia ya ũthia, akekw’a ũkanganĩ, kwĩ kũlulutĩkya kamwe ka tũũ tũnini.'),
('kam', 'LUK', 17, 3, 'Ĩsũvĩei ene: ethĩwa mwana‐a‐au eeka naĩ, mũkan’ye; na ethĩwa nũnũkũalyũla ngoo, mũekee.'),
('kam', 'LUK', 17, 4, 'Na akũvĩtanĩsya mavinda mũonza mũthenya ũmwe, na ooka moka mũonza, akyasya, Nĩnĩalyũlile ngoo; mũekee.'),
('kam', 'LUK', 17, 5, 'Atũmwa mamwĩa Mwĩaĩi, Twingĩvĩsye mũĩkĩĩo witũ.'),
('kam', 'LUK', 17, 6, 'Na Mwĩaĩi asya, Kethĩwa mwĩ na mũĩkĩĩo wĩana kaveke kamwe ka kalatali, no kũwĩa mũtĩ ũũ wa mũvolosati, Kũwa ũkavandwe ũkanganĩ; na no kũmwĩw’a.'),
('kam', 'LUK', 17, 7, 'Ĩndĩ kwenyu aĩva ũla wĩ na ngombo ĩla ĩnĩkwĩnza, kana kũĩthya malondu, na yĩla yoka kuma mũũndanĩ akĩmĩtavya, Ũka mĩtũkĩ, wĩkale nthĩ ũye?'),
('kam', 'LUK', 17, 8, 'Kaĩ ndakamĩtavya, Nzeũvĩsya lĩu nĩye, na ĩndĩ ũyĩvotoa, ũnthũkũme mũvaka nambe kũya na kũnyw’a; na ĩtina naku ũkĩya na kũnyw’a?'),
('kam', 'LUK', 17, 9, 'Nake nũmĩtũngĩaa ngombo mũvea nũndũ nĩyĩkie maũndũ ala yĩaĩwe?'),
('kam', 'LUK', 17, 10, 'Nenyu no ta ũu, mweeka maũndũ onthe ala mwĩaĩwe, aasyai, Twĩ ngombo ite ũtandĩthyo; nĩtwĩkĩte maũndũ ala twaĩlĩtwe nĩ kwĩka.'),
('kam', 'LUK', 17, 11, 'Na kweethĩwa yĩla maĩ nzĩanĩ makĩthi Yelusaleme, avĩtĩla katĩ wa Samalia na Kalilii.'),
('kam', 'LUK', 17, 12, 'Na aivota mũsyĩ ũmwe, akomana na aũme ĩkũmi ala mawaĩte mangũ, na maũngama me kũasa:'),
('kam', 'LUK', 17, 13, 'na mookĩlya mawasya moo, makyasya, Yesũ, Mwĩaĩi, twĩw’ĩe tei.'),
('kam', 'LUK', 17, 14, 'Na amona, amea, Endai mũkeyonan’ye kwa athembi. Na kweethĩwa, maendete, mathew’a.'),
('kam', 'LUK', 17, 15, 'Na ũmwe wamo, oona kana nĩwavow’a, asyoka, aimũkatha Ngai na wasya mũnene;'),
('kam', 'LUK', 17, 16, 'na avalũka na ũthyũ maũũnĩ ma Yesũ, akĩmũtũngĩa mũvea: nake aĩ Mũsamalia.'),
('kam', 'LUK', 17, 17, 'Na Yesũ asũngĩa, asya, Ala mathew’a ti ĩkũmi? Ala kenda maĩva?'),
('kam', 'LUK', 17, 18, 'Kũtinoneka angĩ meũsyoka kũtaĩa Ngai, ate o mũeni ũũ?'),
('kam', 'LUK', 17, 19, 'Na amwĩa, Ũkĩla ũthi: mũĩkĩĩo waku nĩwakũvosya.'),
('kam', 'LUK', 17, 20, 'Na akũlw’a nĩ Avalisi yĩla ũsumbĩ wa Ngai wĩũka, amasũngĩa na amea, Ũsumbĩ wa Ngai ndũkaa ũndũ wa kũsyaĩĩw’a:'),
('kam', 'LUK', 17, 21, 'o na matikasya, Sisyai, kũũ! Kana, Kũya! Nũndũ ũsumbĩ wa Ngai wĩ katĩ wenyu.'),
('kam', 'LUK', 17, 22, 'Nake amea amanyĩw’a, Mĩthenya nĩkoka yĩla mũkenda kwona ũmwe wa mĩthenya ya Mwana wa mũndũ, na mũtikawona.'),
('kam', 'LUK', 17, 23, 'Na makamwĩa, Sisyai, kũya! Sisyai, kũũ! Manyai kuma vala mũĩ, kana kũmavikĩla:'),
('kam', 'LUK', 17, 24, 'nũndũ o tondũ ũtisi ũtisaa ngalĩ ĩmwe ya ĩtu, na ũikena ngalĩ ĩla ĩngĩ ya ĩtu; Mwana wa mũndũ akethĩwa ailyĩ ũu mũthenyanĩ wake.'),
('kam', 'LUK', 17, 25, 'Ĩndĩ mbee wa maũndũ asu ndatĩa kũthĩnw’a na mathĩna maingĩ na kũlewa nĩ ũsyao ũũ.'),
('kam', 'LUK', 17, 26, 'Na o tondũ kweethĩiwe matukũ ma Noa, now’o kũkethĩwa kũilyĩ matukũ ma Mwana wa mũndũ.'),
('kam', 'LUK', 17, 27, 'Nĩmaĩsaa, nĩmanyusaa, nĩmatwaanaa, nĩmatwaawa, kũvika mũthenya ũla Noa wavotie ngalawanĩ, na kĩla kĩw’ũ kingĩ kyooka, na kyamananga onthe.'),
('kam', 'LUK', 17, 28, 'Now’o kweethĩiwe matukũ ma Loto: nĩmaĩsaa, nĩmanyusaa, nĩmathooaa, nĩmathooasya, nĩmavandaa, nĩmaakaa;'),
('kam', 'LUK', 17, 29, 'ĩndĩ mũthenya ũla Loto waumie Sotomo kwauie mwaki na mũvĩlĩtĩ kuma ĩtunĩ, wamananga onthe:'),
('kam', 'LUK', 17, 30, 'ũu now’o kũkethĩwa mũthenya ũla Mwana wa mũndũ ũkavuanw’a.'),
('kam', 'LUK', 17, 31, 'Mũthenya ũsu ũla ũkethĩwa nyũmbanĩ ĩũlũ, na syĩndũ syake syĩ nyũmbanĩ nthĩnĩ, ndakaatheee kũsyosa: no ta ũu ũla wĩ mũũndanĩ ndakaasyoke.'),
('kam', 'LUK', 17, 32, 'Lilikanai mũka wa Loto.'),
('kam', 'LUK', 17, 33, 'O ũla ũkenda ũvĩtya thayũ wake akawasya: ĩndĩ o ũla ũkasya thayũ wake akoovĩtya.'),
('kam', 'LUK', 17, 34, 'Nĩngũmwĩa, Ũtukũ ũsu kũkethĩwa aũme elĩ ũkomonĩ ũmwe; ũmwe nũkoswa, na ũla ũngĩ nũkatiwa.'),
('kam', 'LUK', 17, 35, 'Kũkethĩwa aka elĩ maithianĩa; ũmwe nũkoswa, na ũla ũngĩ nũkatiwa.'),
('kam', 'LUK', 17, 36, 'Andũ elĩ makethĩwa mũũndanĩ; ũmwe nũkoswa, na ũla ũngĩ nũkatiwa.'),
('kam', 'LUK', 17, 37, 'Na masũngĩa, mamũkũlya, Nĩ va Mwĩaĩi? Nake amea, O vala vethĩawa kimba, nĩvo ndei syũmbanĩaa.'),
('kam', 'LUK', 18, 1, 'Amatavya ngelekan’yo mamanye nĩmaĩlwe nĩ kũvoya mĩthenya yonthe, mateũleela;'),
('kam', 'LUK', 18, 2, 'akyasya, Kwaĩ mũsili ndũanĩ ĩmwe, ũla ũtakĩaa Ngai, o na ndoonaa mũndũ ta mũndũ:'),
('kam', 'LUK', 18, 3, 'Na ndũanĩ ĩsu kwaĩ mũndũ mũka ũmwe ndiwa; nĩwaendangaa kaingĩ vala ũĩ aimwĩa, Ndĩvanĩsya kwa nthũ yakwa.'),
('kam', 'LUK', 18, 4, 'Nake alea ĩvinda: na ĩtina wa ũu asya ngoonĩ yake atĩĩ, O na ethĩwa ndimũkia Ngai, o na ndyonaa mũndũ ta mũndũ;'),
('kam', 'LUK', 18, 5, 'ĩndĩ nũndũ mũndũ mũka ũũ ndiwa nũnũũnyamasya, nĩngũmũĩvanĩsya, ndakanosye akĩndokeanga mĩthenya yonthe.'),
('kam', 'LUK', 18, 6, 'Na Mwĩaĩi asya, Ĩw’ai ũndũ ũla mũsili ũte mũlũngalu ũnũkwasya.'),
('kam', 'LUK', 18, 7, 'Na Ngai ndakamaĩvanĩsya anyuve make, ala mamũĩĩa mũthenya na ũtukũ, o na amomĩĩsya?'),
('kam', 'LUK', 18, 8, 'Nĩngũmũtavya, akamaĩvanĩsya mĩtũkĩ. Ĩndĩ yĩla Mwana wa mũndũ ũkoka nũkethĩa mũĩkĩĩo nthĩ?'),
('kam', 'LUK', 18, 9, 'Amatavya ngelekan’yo ĩno nao ala metusaa ene alũngalu, makĩvũthya angĩ:'),
('kam', 'LUK', 18, 10, 'Andũ elĩ nĩmambatie ĩkalũnĩ kũvoya; ũmwe nĩ Mũvalisi, na ũngĩ nĩ mumya wa koti.'),
('kam', 'LUK', 18, 11, 'Ũla Mũvalisi aũngama avoya ngooni yake, Ngai, nĩngũũtũngĩa mũvea, nũndũ nditilyĩ ta andũ ala angĩ, avutani, ala mate alũngalu, ilaalai, kana o na ta mumya wa koti ũũ.'),
('kam', 'LUK', 18, 12, 'Kyumwa kĩmwe nĩndĩĩaa ũya kelĩ; na nĩnumasya kĩlungu kya ĩkũmi kya kĩla kĩndũ nĩ nakyo.'),
('kam', 'LUK', 18, 13, 'Ĩndĩ mumya wa koti aũngamĩte kũasa, na ndaaũngalalya metho make kũsisya ĩtunĩ, ĩndĩ eekũnanga kĩthũi, akyasya, Ngai, mbĩw’ĩa tei, nĩ mwathe nyie.'),
('kam', 'LUK', 18, 14, 'Nĩngũmũtavya, Mũndũ ũsu atheeie kwake atalĩlwe ũlũngalu kũte ũla ũngĩ: nĩkwĩthĩwa ũla wĩnenevasya mwene nũkanyivw’a; ĩndĩ ũla wĩnyivasya mwene nũkanenevw’a.'),
('kam', 'LUK', 18, 15, 'Na mamũetee twana twoo tũnini, atũkiite: na amanyĩw’a moona ũu, mamakan’ya.'),
('kam', 'LUK', 18, 16, 'Ĩndĩ Yesũ atwĩta tũke, kwake, akyasya, Tũekei twana tũnini tũke kwakwa, mũtikatũvate: nũndũ ũsumbĩ wa Ngai nĩ wa ala mailyĩ tatw’o.'),
('kam', 'LUK', 18, 17, 'Nĩ w’o nĩngũmwĩa, Ũla ũtosaa ũsumbĩ wa Ngai ta kana kanini ndakavota vo nongi.'),
('kam', 'LUK', 18, 18, 'Na mũnene ũmwe amũkũlya, akyasya, Mũmanyĩsya mũseo, nĩĩka ata kana nĩtiĩwe thayũ ũtathela?'),
('kam', 'LUK', 18, 19, 'Na Yesũ amwia, Nĩkĩ ũũmbĩta mũseo? Vai mũseo ate o ũmwe, nake nĩ Ngai.'),
('kam', 'LUK', 18, 20, 'Nũmĩsĩ ĩla mĩao, Ndũkalaalae, Ndũkoae, Ndũkoye, Ndũkaneene ũkũsĩ wa ũvũngũ, Taĩa au na mwenyu.'),
('kam', 'LUK', 18, 21, 'Nake asya, Maũndũ asu onthe nĩnamakwatie kuma nĩ mũnini.'),
('kam', 'LUK', 18, 22, 'Yesũ eew’a ũu, amwĩa, Ve ũndũ ũmwe ũtielye: Thoosya syĩndũ syonthe ila wĩ nasyo, ũnenge ngya, na ũkethĩwa na ũthwii ĩtunĩ: na ĩndĩ ũkyũka ũngatĩĩe.'),
('kam', 'LUK', 18, 23, 'Na eew’a ndeto isu, eew’a woo mũno; nũndũ aĩ mũthwii mũno.'),
('kam', 'LUK', 18, 24, 'Na Yesũ amũketeea na asya, Ko nĩ vinya ala athwii kũvota ũsumbĩnĩ wa Ngai!'),
('kam', 'LUK', 18, 25, 'Nũndũ nĩ ũvũthũ ngamĩle kũvotela kalimanĩ ka singano, kũte mũndũ mũthwii kũvota ũsumbĩnĩ wa Ngai.'),
('kam', 'LUK', 18, 26, 'Na ala meewie masya, Nũũ ĩndĩ ũtonya kũtangĩĩwa?'),
('kam', 'LUK', 18, 27, 'Nake asya, Maũndũ ala matatonyeka kwa andũ nĩmatonyeka kwa Ngai.'),
('kam', 'LUK', 18, 28, 'Nĩvo Vetelo waisye, Sisya, ithyĩ nĩtũtiĩte syĩndũ sitũ twakũatĩĩa.'),
('kam', 'LUK', 18, 29, 'Nake amea, Nĩ w’o nĩngũmwĩa, Vai mũndũ ũla waatia nyũmba, kana mũka, kana ana‐a‐inyia, kana asyai make, kana syana, kwondũ wa ũsumbĩ wa Ngai,'),
('kam', 'LUK', 18, 30, 'ũtakosa vandũ va kĩmwe nyingĩ ĩvindanĩ yĩĩ twĩ nayo, na ĩvinda yĩla yũkĩte thayũ ũtathela.'),
('kam', 'LUK', 18, 31, 'Na amomban’ya vala ũĩ ala ĩkũmi na elĩ, na amea, Sisyai, nĩtũkwambata Yelusaleme, na maũndũ onthe ala maandĩkiwe nĩ athani makeanĩwa kwa Mwana wa mũndũ.'),
('kam', 'LUK', 18, 32, 'Nĩkwĩthĩwa akanenganwe mokonĩ ma Andũ‐ma‐mbaĩ‐ingĩ, akathekeewa na kĩvũthya, na kũthĩnw’a mũno, na kũtw’ĩlangwa mata:'),
('kam', 'LUK', 18, 33, 'na makamũvũa na kũmũaa: na mũthenya wa katatũ akathayũũka.'),
('kam', 'LUK', 18, 34, 'Na maiaamanya, o na vanini, maũndũ asu; na ndeto isu nĩsyavithĩtwe kwoo, na maiaamanya ũla waneeniwe.'),
('kam', 'LUK', 18, 35, 'Na kweethĩwa, aithengeea Yeliko, kwaĩ kĩlilinda kyekalĩte ũtee wa nzĩa kĩivoya syĩndũ:'),
('kam', 'LUK', 18, 36, 'nakyo kyeew’a ĩkomano yĩvĩtĩte, kyakũlya nĩ ũndũ mwaũ.'),
('kam', 'LUK', 18, 37, 'Nao makĩtavya nĩ Yesũ wa Nasaleti ũvĩtĩte.'),
('kam', 'LUK', 18, 38, 'Nakyo kyookĩlya wasya, kĩkyasya, Yesũ Mwana wa Ndaviti, mbĩw’ĩa tei.'),
('kam', 'LUK', 18, 39, 'Na ala matongoetye makĩkan’ya, kĩkilye: ĩndĩ kyookĩlya wasya mũno mbee, Mwana wa Ndaviti, mbĩw’ĩa tei.'),
('kam', 'LUK', 18, 40, 'Na Yesũ aũngama, ameaĩa kĩetwe vala ũĩ: na kyathengeea, akĩkũlya,'),
('kam', 'LUK', 18, 41, 'Wĩenda ngwĩke ata? Na kyasya, Mwĩaĩi, nĩenda kwona nthĩ.'),
('kam', 'LUK', 18, 42, 'Na Yesũ akĩtavya, Ona nthĩ: mũĩkĩĩo waku nĩwakũvosya.'),
('kam', 'LUK', 18, 43, 'Na kavinda o kau kyanengwa kwona, na kyamũvikĩla, kĩimũkatha Ngai: na andũ onthe, moona ũu, mamũtaĩa Ngai.'),
('kam', 'LUK', 19, 1, 'Nake avota Yeliko avĩtĩla vo.'),
('kam', 'LUK', 19, 2, 'Na sisya, nĩvo vaĩ mũndũ wetawa Sakayo; nake aĩ mũnene wa aumya ma koti, na aĩ mũthwii.'),
('kam', 'LUK', 19, 3, 'Nake nĩwendaa kũmwona Yesũ amanye nũũ; na aaĩwa nũndũ wa ĩkomano, nũndũ aĩ mũkuvĩ.'),
('kam', 'LUK', 19, 4, 'Nake asemba mbee, alĩsa mũkũyũnĩ nĩ kana amwone: nũndũ nĩwokĩte avĩtĩle nzĩanĩ ĩsu.'),
('kam', 'LUK', 19, 5, 'Yesu avika vala vandũ, ang’elela ĩũlũ, amwĩa, Sakayo, theea nthĩ mĩtũkĩ; nũndũ ũmũnthi nditĩa kũtinda nyũmba kwaku.'),
('kam', 'LUK', 19, 6, 'Nake atheea nthĩ mĩtũkĩ, amũthokya kwake na mũyo.'),
('kam', 'LUK', 19, 7, 'Na moona ũu, onthe manyungunyĩsya, makyasya, Nĩwathi kwĩkala kwa mũndũ mwathe.'),
('kam', 'LUK', 19, 8, 'Na Sakayo aũngama, na amwĩa Mwĩaĩi, Sisya, Mwĩaĩi, nyunzu ya syĩndũ syakwa nĩngũnenga ngya; na ethĩwa nĩnĩvenete mũndũ kĩndũ na nzĩa ya ũkengani, nĩngũmũtũngĩa kũndũ kũna.'),
('kam', 'LUK', 19, 9, 'Yesũ amwĩa, Ũmũnthĩ ũtangĩĩo nĩwooka nyũmbanĩ ĩno, nũndũ ũũ nake nĩ mwana wa Avalaamu.'),
('kam', 'LUK', 19, 10, 'Nũndũ Mwana mũndũ nĩwokie kũmantha na kũtangĩĩa kĩla kyaaie.'),
('kam', 'LUK', 19, 11, 'Nao meew’a maũndũ asu, ongeleela kũneena ngelekan’yo, nũndũ nĩwathengeee Yelusaleme, na nũndũ nĩmatalĩthasya kana ũsumbĩ wa Ngai ũkilĩlye kwoneka.'),
('kam', 'LUK', 19, 12, 'Kwondũ wa ũu asya, Mũndũ mũnene ũmwe nĩwaendie nthĩ yĩ kũasa anengwe ũsumbĩ, na akĩsyoka.'),
('kam', 'LUK', 19, 13, 'Asyĩta ngombo syake ĩkũmi, aiaan’ya latili ĩkũmi sya vetha, asyĩa, Tandĩthyai nasyo mũvaka naalũka.'),
('kam', 'LUK', 19, 14, 'Ĩndĩ andũ make mamũmena, na matũma andũ mamũatĩĩe, makyasya, Tũtikwenda mũndũ ũũ atũsumbĩke.'),
('kam', 'LUK', 19, 15, 'Na kweethĩwa, asyoka, anengetwe ũsumbĩ, aumya mwĩao kana ngombo ila wanengie mbesa syĩtwe, nĩ kana amanye ũndũ itandĩthĩtye nasyo.'),
('kam', 'LUK', 19, 16, 'Na ĩla ya mbee yooka, yasya, Vwana, latili yaku nĩtandĩthĩtye latili ingĩ ĩkũmi.'),
('kam', 'LUK', 19, 17, 'Na amĩtavya, Nĩwĩkĩte nesa, we ngombo nzeo: nũndũ waĩ na kĩthito na kĩndũ kĩnini, ĩthĩwa na ũkũmũ ĩũlũ wa ndũa ĩkũmi.'),
('kam', 'LUK', 19, 18, 'Na ĩla ya kelĩ yooka, yasya, Vwana, latili yaku nĩtandĩthĩtye latili itano.'),
('kam', 'LUK', 19, 19, 'Nake amĩtavya o ta ĩla ĩngĩ, Ĩthĩwa ĩũlũ wa ndũa itano.'),
('kam', 'LUK', 19, 20, 'Na ĩngĩ yooka, yasya, Vwana, latili yaku, nĩ ĩno, nĩnaiie noveee kĩtambaanĩ:'),
('kam', 'LUK', 19, 21, 'nũndũ nĩnakũkĩie, nĩkwĩthĩwa wĩ mũndũ mwai: nĩwosaa kĩla ũtaiĩte, na nũkethaa kĩla ũtaavuĩa.'),
('kam', 'LUK', 19, 22, 'Amĩtavya, Ngombo nthũku we, nĩngũkũsilĩla na ndeto sya kanyw’a waku, Nĩweesĩ kana nĩ mũndũ mwai, nosaa kĩla ndaaia, na ngethaa kĩla ndaavuĩa;'),
('kam', 'LUK', 19, 23, 'nũndũ wa kĩ ĩndĩ waleile kwia mbesa syakwa venginĩ, kana nooka nĩnengwe mbesa syakwa vamwe na ũtandithyo wasyo?'),
('kam', 'LUK', 19, 24, 'Na ĩndĩ amea ala maũngamĩte vo, Mĩvenei latili ĩla ĩ nayo, mĩnenge ĩla ĩ na latili ĩkũmi.'),
('kam', 'LUK', 19, 25, 'Nao mamwĩa, Vwana, ĩ na latili ĩkũmi.'),
('kam', 'LUK', 19, 26, 'Nĩngũmũtavya kana kĩla mũndũ ũkwete kĩndũ akanengwa; ĩndĩ ũla ũte na kĩndũ, o na kĩla wĩ nakyo akavenwa.'),
('kam', 'LUK', 19, 27, 'Ĩndĩ amaitha aa makwa ala matendaa nĩmasumbĩke, maetei vaa, mũmoaĩe mbee wakwa.'),
('kam', 'LUK', 19, 28, 'Na amina kũneena maũndũ asu, aendaa mbee, ambatĩte Yelusaleme.'),
('kam', 'LUK', 19, 29, 'Na kweethĩwa, athengeea Vethivake na Vethania, vala ve kĩĩma kĩla kĩtawa Oliveti, atũma elĩ ma amanyĩw’a make,'),
('kam', 'LUK', 19, 30, 'akyasya, Endai mũsyĩ ũla ũmwelekele; na mwavota mũkoona ndena ya ĩng’oi yovetwe, ĩla ĩtaamba kũkua mũndũ: mĩthasyei, mũmĩete vaa.'),
('kam', 'LUK', 19, 31, 'Na mwakũlw’a nĩ mũndũ, Mwĩmĩthaĩsya kĩ? Asyai, Mwĩaĩi e na vata nayo.'),
('kam', 'LUK', 19, 32, 'Na ala matũmiwe mathi, na meethĩa o tondũ mataviw’e.'),
('kam', 'LUK', 19, 33, 'Na makĩthasya ĩla ndena, ene mayo mamakũlya, Mwĩmĩthaĩsya ndena kĩ?'),
('kam', 'LUK', 19, 34, 'Na masya, Mwĩaĩi e na vata nayo.'),
('kam', 'LUK', 19, 35, 'Nao mamĩtwaa kwa Yesũ: na mailĩĩla ngũa syoo ĩũlũ wa ndena, na mamũtũlya Yesũ ĩũlũ wayo.'),
('kam', 'LUK', 19, 36, 'Na akĩthi, mamwalanĩlya ngũa syoo nzĩanĩ.'),
('kam', 'LUK', 19, 37, 'Na athengeea, e kĩtheeonĩ kya kĩĩma kya Mĩthata, ĩkomano yonthe ya amanyĩw’a mambĩlĩlya kũtana na kũmũkumya Ngai na wasya mũnene, ũndũ wa mavinya ala moonie;'),
('kam', 'LUK', 19, 38, 'makyasya, Nĩ mũathime Mũsumbĩ ũla wũkĩte syĩtwanĩ ya Mwĩaĩi: mũuo wĩthĩwe ĩtunĩ, na ndaĩa yĩthĩwe ku ĩũlũ mũno.'),
('kam', 'LUK', 19, 39, 'Na Avalisi amwe ala maĩ ĩkomanonĩ mamwĩa, Mũmanyĩsya, makan’ye amanyĩw’a maku.'),
('kam', 'LUK', 19, 40, 'Nake asũngĩa, akyasya, Nĩngũmũtavya, ethĩwa aa makavindya, mavia makalonzan’ya.'),
('kam', 'LUK', 19, 41, 'Na avika vakuvĩ, amyona ĩla ndũa na aĩa nũndũ wayo,'),
('kam', 'LUK', 19, 42, 'akyasya, Kethĩwa nĩweesĩ we mũthenya ũũ wa ũmũnthĩ, maũndũ ma mũuo waku ũndũ mailyĩ! Ĩndĩ yu nĩmavithĩtwe methonĩ maku.'),
('kam', 'LUK', 19, 43, 'Ĩndĩ mĩthenya nĩyũkĩte kwaku, yĩla amaitha maku makakũthyũlũlũkĩlya wiio, na kũkwĩlingĩla, na kũkũsiĩĩa ngalĩ syonthe,'),
('kam', 'LUK', 19, 44, 'na makakũvalũkya nthĩ, syana syaku syĩ nthĩnĩ waku; na matikatia nthĩnĩ waku ĩvia yĩmwe ĩũlũ wa yĩngĩ; nĩkwĩthĩwa ndwaamanya ĩvinda ya kũsiw’a kwaku.'),
('kam', 'LUK', 19, 45, 'Nake avota ĩkalũnĩ, na ambĩlĩlya kũmakuthũa ala mathooanĩasya,'),
('kam', 'LUK', 19, 46, 'akĩmea, Nĩkũandĩkĩtwe, Nyũmba yakwa ĩkethĩwa nyũmba ya kũvoyea: ĩndĩ inywĩ mũmĩtw’ĩte ngunga ya avutani.'),
('kam', 'LUK', 19, 47, 'Na amanyĩasya ĩkalũnĩ kĩla mũthenya. Ĩndĩ athembi anene na aandĩki na ala anene andũnĩ mamantha kũmũaa:'),
('kam', 'LUK', 19, 48, 'na maaĩw’a nĩ ũndũ wa kwĩka; nũndũ andũ onthe nĩmateete matũ, makĩmwĩthukĩĩsya.'),
('kam', 'LUK', 20, 1, 'Na kweethĩwa mũthenya ũmwe, akĩmanyĩsya andũ ĩkalũnĩ, na akĩtavan’ya ũla ũvoo mũseo, athembi anene na aandĩki vamwe na atumĩa mamũwĩla;'),
('kam', 'LUK', 20, 2, 'na maneena nake, makĩmwĩa, Tũtavye: Wĩkaa maũndũ aa na ũkũmũ wĩva? Kana nũũ ũkũnengete ũkũmũ ũũ?'),
('kam', 'LUK', 20, 3, 'Nake asũngĩa na amea, Nakwa nĩngũmũkũlya ũkũlyo; ndavyai:'),
('kam', 'LUK', 20, 4, 'Ũvatisi wa Yoana waumie ĩtunĩ kana waumie andũnĩ?'),
('kam', 'LUK', 20, 5, 'Na masũanĩa ene kwa ene, makyasya, Ethĩwa nĩtũkwasya, Waumie ĩtunĩ; akasya, Nĩkĩ ĩndĩ mũtaamwĩtĩkĩla?'),
('kam', 'LUK', 20, 6, 'Ĩndĩ ethĩwa nĩtũkwasya, Waumie andũnĩ; andũ onthe makatũkima na mavia: nũndũ nĩmeetĩkĩlĩte kana Yoana aĩ mwathani.'),
('kam', 'LUK', 20, 7, 'Na masũngĩa kana matyĩsĩ kũla waumie.'),
('kam', 'LUK', 20, 8, 'Na Yesũ amea, O nakwa ndimũtavya ũkũmũ ũla ũtumaa nĩka maũndũ aa.'),
('kam', 'LUK', 20, 9, 'Na ambĩlĩlya kũmatavya andũ ngelekan’yo ĩno: Mũndũ nĩwavandie mũũnda wa mĩsavivũ, na oonenga aĩmi mamũĩmĩe, nake athi nthĩ ĩngĩ na ekala ĩvinda ĩasa.'),
('kam', 'LUK', 20, 10, 'Na ĩvinda yavika atũma ngombo kwa ala aĩmi, mamĩnenge ũsyao ũmwe wa mũũnda ũsu wa mĩsavivũ: ĩndĩ aĩmi mamĩkũna, mamĩlũngya ĩte na kĩndũ.'),
('kam', 'LUK', 20, 11, 'Na atũma ngombo ĩngĩ: nayo mamĩkũna, mamĩsonokya, mamĩlũngya ĩte na kĩndũ.'),
('kam', 'LUK', 20, 12, 'Na atũma ĩngĩ ya katatũ: na mamĩuauĩkya, na mamĩkya ũtee wa mũũnda.'),
('kam', 'LUK', 20, 13, 'Na ĩndĩ mwene wa mũũnda asya, Nĩĩka ata? Ngatũma mwana wakwa mwendwa; nokwĩthĩwa makamũtaĩa.'),
('kam', 'LUK', 20, 14, 'Ĩndĩ aĩmi mamwona, maneenan’ya, makyasya, Ũũ nĩwe mũtiĩwa; tũmũaei, nĩ kana ũtiĩwa ũtw’ĩke witũ.'),
('kam', 'LUK', 20, 15, 'Na mamwĩkya ũtee wa mũũnda wa mĩsavivũ, na mamũaa. Na ĩndĩ mwene mũũnda ũsu akameka ata?'),
('kam', 'LUK', 20, 16, 'Akooka na akaananga aĩmĩ asu, na akamanenga angĩ mũũnda wa mĩsavivũ. Nao meew’a ũu, masya, Ũkwa, ũndũ ũũ ndũkaaĩkĩke.'),
('kam', 'LUK', 20, 17, 'Ĩndĩ amaketeea, na asya, Nata ĩndĩ ndeto ii ila syaandĩkiwe, Ĩvia yĩla yaleilwe nĩ aki, Yĩu yatw’ĩkie yĩla ĩnene ya kĩkotonĩ?'),
('kam', 'LUK', 20, 18, 'Mũndũ ũla wĩvalũka ĩũlũ wa ĩvia yĩu akavevenzeka; ĩndĩ o ũla yĩmũvalũkĩla, akatumbatumbĩka anyaĩĩke ta kĩtoo.'),
('kam', 'LUK', 20, 19, 'Na aandĩki na athembi anene mamantha kũmũkwata o saa ũsu; na makĩa andũ: nĩkwĩthĩwa nĩmamanyie kana ĩla ngelekan’yo aneena nũndũ woo.'),
('kam', 'LUK', 20, 20, 'Na mamwoveesya, na matũma athiani, ala meetwie ene ta alũngalu, nĩ kana mamũtee ndetonĩ syake, na kũmũnengane ũnenenĩ na ũkũmũnĩ wa ngavana.'),
('kam', 'LUK', 20, 21, 'Na mamũkũlya, makyasya, Mũmanyĩsya, nĩtwĩsĩ nũneenaa na kũmanyĩsya katĩ, na ndwendeeaw’a nĩ wũmbe wa mũndũ, ĩndĩ nzĩa ya Ngai nũmanyĩasya w’o:'),
('kam', 'LUK', 20, 22, 'Nĩkwosana na ĩla mĩao kũnenga Kaisali koti, kana ti w’o?'),
('kam', 'LUK', 20, 23, 'Nake amanya ũseleke woo, na amea,'),
('kam', 'LUK', 20, 24, 'Kwa mbon’yai silingi. Ĩ na mũvw’ano na ũandĩko waũ? Mamũsũngĩa, Nĩ wa Kaisali.'),
('kam', 'LUK', 20, 25, 'Nake amea, Mũnengei Kaisali syĩndũ sya Kaisali, na Ngai syĩndũ sya Ngai.'),
('kam', 'LUK', 20, 26, 'Na maiaatonya kũmũkwata na ndeto ila waneenee mbee wa andũ: na maseng’a ũndũ wa ũsũngĩo wake, na mavindya.'),
('kam', 'LUK', 20, 27, 'Na ĩndĩ ookĩwa nĩ amwe ma Asatukai, ala maasya kũi ũthayũũkyo;'),
('kam', 'LUK', 20, 28, 'na mamũkũlya, makyasya, Mũmanyĩsya, Mose nĩwatũandĩkĩe, atĩ ethĩwa mwana‐a‐inya wa mũndũ nĩwakw’a, e mũka, na ndaatia kana, mwana‐a‐inyia wake namwose ũ mũndũ mũka, na amũũngamĩsye mwana‐a‐inyia mbeũ.'),
('kam', 'LUK', 20, 29, 'Kwaĩ aũme mũonza ma inyia ũmwe: na ũla wa mbee atwaa mũka, na akw’a atasyaĩte kana;'),
('kam', 'LUK', 20, 30, 'nake ũla wa kelĩ amwosa ũ mũndũ mũka:'),
('kam', 'LUK', 20, 31, 'na ũla wa katatũ nake amwosa; no ta ũu onthe mũonza maiaatia kana, na makw’a.'),
('kam', 'LUK', 20, 32, 'Na ĩtina ũla mũndũ mũka nake akw’a.'),
('kam', 'LUK', 20, 33, 'Uthayũũkyonĩ ĩndĩ akethĩwa e mũka wa wĩva wa asu? Nĩkwĩthĩwa onthe mũonza nĩmamũtwaĩte.'),
('kam', 'LUK', 20, 34, 'Na Yesũ amea, Ana ma nthĩ ĩno nĩmatwaanaa, na nĩmatwaawa:'),
('kam', 'LUK', 20, 35, 'ĩndĩ ala matalĩtwe nĩmaĩlĩtwe nĩ ũvika nthĩ ĩya, na ũthayũũkyo wa akw’ũ, maitwaanaa, o na maitwaawa:'),
('kam', 'LUK', 20, 36, 'nĩkwĩthĩwa maitonya kũkw’a ĩngĩ: nũndũ mailyĩ o ta alaĩka; na nĩ ana ma Ngai, nũndũ nĩ ana ma ũthayũũkyo.'),
('kam', 'LUK', 20, 37, 'Ĩndĩ ũndũ wa akw’ũ kana makathayũũkw’a, o na Mose nake nĩwonanisye vala vaandĩkĩtwe ũvoo wa kala Kakuthu, yĩla wetie Mwĩaĩi, Ngai wa Avalaamu, na Ngai wa Isaka, na Ngai wa Yakovo.'),
('kam', 'LUK', 20, 38, 'We ti Ngai wa ala akw’ũ, ĩndĩ nĩ wa ala me thayũ: nĩkwĩthĩwa onthe me thayũ kwake.'),
('kam', 'LUK', 20, 39, 'Na amwe maaandĩki masũngĩa, makyasya, Mũmanyĩsya, nĩwaneena nesa.'),
('kam', 'LUK', 20, 40, 'Nũndũ vai ũmwe wamo waatata kũmũkũlya mokũlyo angĩ.'),
('kam', 'LUK', 20, 41, 'Nake amakũlya, Andũ measya ata kana Klĩsto nĩ mwana wa Ndaviti?'),
('kam', 'LUK', 20, 42, 'Nũndũ Ndaviti mwene easya ĩvukunĩ ya Savuli, Mwĩaĩi amwĩie Mwĩaĩi wakwa, Ĩkala nthĩ ngalĩ ya kw’oko kwakwa kwa aũme,'),
('kam', 'LUK', 20, 43, 'Mũvaka natw’a amaitha maku kavĩla ka nyaĩĩ syaku.'),
('kam', 'LUK', 20, 44, 'Ndaviti emwĩta Mwĩaĩi, na ĩndĩ nĩ mwana wake ata?'),
('kam', 'LUK', 20, 45, 'Na andũ onthe makĩthukĩĩsya amea amanyĩw’a make,'),
('kam', 'LUK', 20, 46, 'Ĩsũvĩei aandĩki, ala mendaa kũtambũka mekĩe ngũa ndasa, na mendaa kũkethw’a ing’ang’anĩ, na ivĩla sya mbee masinakokenĩ, na kũndũ kwa mbee mbokanĩ;'),
('kam', 'LUK', 20, 47, 'ala maĩsaa nyũmba sya aka ndiwa, na nũndũ wa ũkengani nĩmaasavasya mboya: asu nĩmo ala makona ũsilĩlo mũnene mbee.'),
('kam', 'LUK', 21, 1, 'Nake ookĩlya metho, na oona ala athwii makĩlekya nthembo syoo vala valekelaw’a.'),
('kam', 'LUK', 21, 2, 'Na oona mũndũ mũka ndiwa, ũla, waĩ ngya akĩkĩa tũwela twĩlĩ.'),
('kam', 'LUK', 21, 3, 'Na asya, Nĩ w’o nĩngũmwĩa, Ndiwa ĩno ngya nĩyekĩa nyingĩ kwĩ onthe:'),
('kam', 'LUK', 21, 4, 'nũndũ aa onthe meekĩa nthembo syoo nũndũ wa kwingĩvĩwa kwoo; ĩndĩ ũũ kuma ũkyanĩ wake eekĩa wĩkwatyo w’onthe wa thayũ ũla eĩ naw’o.'),
('kam', 'LUK', 21, 5, 'Na amwe makĩneena ũvoo wa ĩkalũ, ũndũ yanakavĩtw’e na mavia maseo na maelo ma andũ, nake asya,'),
('kam', 'LUK', 21, 6, 'Ũndũ wa syĩndũ ii ila mũkwona, mĩthenya nĩyũkĩte, yĩla vaa vatakatiwa ĩvia ĩũlũ wa yĩngĩ, yĩla yĩtakaombowa.'),
('kam', 'LUK', 21, 7, 'Na mamũkũlya, makyasya, Mũmanyĩsya, maũndũ asu makethĩwa ĩndĩĩ? Na wonan’yo nĩ wĩva yĩla maũndũ asu makathengeea kwĩanĩw’a?'),
('kam', 'LUK', 21, 8, 'Na asya, Ĩsũvĩei mũtikaaw’e! Nũndũ aingĩ makooka na syĩtwa yakwa, makyasya, Ninyie we; na, Ĩvinda nĩ ĩthengeeu: manyai kũmaatĩĩa.'),
('kam', 'LUK', 21, 9, 'Na yĩla mũkew’a ũvoo wa makaũ na ithokoo, manyai kũtw’ĩka nda: nũndũ maũndũ asu mati ndĩi ya ũlea kwĩkĩka mbee; ĩndĩ mũminũkĩlyo ndũnavika.'),
('kam', 'LUK', 21, 10, 'Na ĩndĩ amea, Mbaĩ ĩkookĩlĩla mbaĩ, na ũsumbĩ ũkookĩlĩla ũsumbĩ;'),
('kam', 'LUK', 21, 11, 'na kũkeethĩwa itetemo nene sya nthĩ, na mayũa na mĩimũ kũũ na kũũ; na kũkeethĩwa motĩsyo na mawonan’yo manene makyuma ĩtunĩ.'),
('kam', 'LUK', 21, 12, 'Ĩndĩ mbee wa maũndũ asu onthe, makamũkwata, na kũmũthĩn’ya na kũmũnengane mũtwawe masinakokenĩ na makolokolonĩ, na makĩmũtwaa mbee wa asumbĩ na makavana kwondũ wa syĩtwa yakwa.'),
('kam', 'LUK', 21, 13, 'Na maũndũ aa makeethĩwa ũkũsĩ wenyu.'),
('kam', 'LUK', 21, 14, 'Kwondũ wa ũu ĩtw’ĩĩei ngoonĩ syenyu mũikasũanĩe mbee ũla mũkasũngĩa:'),
('kam', 'LUK', 21, 15, 'nũndũ nyie ngamũnenga kanyw’a na ũĩ, ũla nthũ syenyu syonthe itakatonya kũlea kana kũkananĩa.'),
('kam', 'LUK', 21, 16, 'Ĩndĩ mũkanenganwe nĩ asyai menyu, na ana‐a‐inyia menyu, na mbaĩ yenyu, na anyanyae menyu; na amwe menyu nĩmakamũaĩthya.'),
('kam', 'LUK', 21, 17, 'Na nĩmũkamenwa nĩ andũ onthe kwondũ wa syĩtwa yakwa.'),
('kam', 'LUK', 21, 18, 'Ĩndĩ ũswĩĩ ũmwe wa mĩtwe yenyu ndũkaa.'),
('kam', 'LUK', 21, 19, 'Kwondũ wa wũmĩĩsyo wenyu mũkavonokya mathayũ menyu.'),
('kam', 'LUK', 21, 20, 'Ĩndĩ yĩla mwĩona Yelusaleme yeelingĩlwa nĩ ita, manyai kana wanangĩko wayo wĩ vakuvĩ.'),
('kam', 'LUK', 21, 21, 'Ĩvinda yĩu ala me Yutia makie mathi iĩmanĩ; na ala me nthĩnĩ wayo maume vo; na ala me ndee matikavote vo.'),
('kam', 'LUK', 21, 22, 'Nũndũ matukũ asu nĩ ma ũĩvanĩsyo, nĩ kana maũndũ onthe ala maandĩkĩtwe meanĩw’e.'),
('kam', 'LUK', 21, 23, 'Woo nĩ wa ala aito na wa ala mekwongya mĩthenya ĩsu! Nũndũ kũkethĩwa ũnyamao mũnene nthĩ, na ũthilĩku ĩũlũ wa andũ aa.'),
('kam', 'LUK', 21, 24, 'Nao makavalũkw’a kwa kũtemangwa na ũvyũ, na makatwawa me atave mbaĩnĩ syonthe: na Yelusaleme ũkakinyangw’a nĩ Andũ‐ma‐mbaĩ‐ingĩ, mũvaka mavinda ma Andũ‐ma‐mbaĩ‐ingĩ meanĩw’e.'),
('kam', 'LUK', 21, 25, 'Na kũkethĩwa mawonan’yo syũanĩ na mweinĩ na ndatanĩ; na kũũ nthĩ kũkethĩwa ũnyamao wa mbaĩ, ikĩsũanĩwa nũndũ wa kĩlitũko kya ũkanga na itulumo syaw’o;'),
('kam', 'LUK', 21, 26, 'andũ nĩmakatw’ĩka nda nĩ w’ĩa, na ũndũ wa kweteela maũndũ ala mokĩte ĩũlũ wa nthĩ: nũndũ mavinya ma ĩtu nĩmakathingithangw’a.'),
('kam', 'LUK', 21, 27, 'Ĩvinda yĩu nĩmakamwona Mwana wa mũndũ okĩte ĩthweonĩ na vinya na ũtheu mũnene mũtisu.'),
('kam', 'LUK', 21, 28, 'Ĩndĩ yĩla maũndũ asu makambĩlĩlya kwĩkĩka, sisyai ĩũlũ, na ũkĩlyai mĩtwe yenyu; nũndũ wovosyo wenyu nĩ mũthengeeu.'),
('kam', 'LUK', 21, 29, 'Na amatavya ngelekan’yo: Sisyai mũkũyũ, na mĩtĩ yonthe:'),
('kam', 'LUK', 21, 30, 'yĩla yambĩlĩlya kũthongoosya wenze, nĩmũkwona na kũmanya inyw’ĩ ene kana mũniino nũthengeee.'),
('kam', 'LUK', 21, 31, 'No ta ũu nenyu, mũkyona maũndũ asu makĩkĩka, manyai kana ũsumbĩ wa Ngai wĩ vakuvĩ.'),
('kam', 'LUK', 21, 32, 'Nĩ w’o nĩngũmwĩa, Ũsyao ũũ ndũkavĩta, maũndũ asu onthe mateanĩw’e.'),
('kam', 'LUK', 21, 33, 'Ĩtu na nthĩ nikavĩta: ĩndĩ ndeto syakwa itikavĩta.'),
('kam', 'LUK', 21, 34, 'Ĩndĩ ĩsũvĩei, ngoo syenyu itikese kũemewa nĩ kũya mũno, na ũthengi, na mawĩmakĩo ma thayũ ũũ, na mũthenya ũsu kũmũvikĩa na kĩthũlũmũko ta kĩtei:'),
('kam', 'LUK', 21, 35, 'nũndũ o ta ũu, nĩw’o ũkamokĩa andũ onthe ala me ĩũlũ wa nthĩ yonthe.'),
('kam', 'LUK', 21, 36, 'Ĩndĩ ĩkalai mũsyaĩĩsye matukũ onthe, mũkĩvoya, nĩ kana mũnengwe kũvonoka maũndũ asu onthe ala makoka, na kũũngama mbee wa Mwana wa mũndũ.'),
('kam', 'LUK', 21, 37, 'Na kĩla mũthenya amanyĩasya ĩkalũnĩ; na kĩla ũtukũ nĩwaumaa, akaenda kwĩkala kĩĩmanĩ kĩla kĩtawa Oliveti.'),
('kam', 'LUK', 21, 38, 'Na andũ onthe mamũokeaa ĩkalũnĩ kĩoko tene, mamwĩthukĩĩsye.'),
('kam', 'LUK', 22, 1, 'Na mboka ya kĩmũtũ kĩte ĩlawa yathengeea, ĩla yĩtawa Vasaka.'),
('kam', 'LUK', 22, 2, 'Na athembi anene na aandĩki mamantha nzĩa ya kũmũaa; nũndũ nĩmakĩaa andũ.'),
('kam', 'LUK', 22, 3, 'Na Satani alika nthĩnĩ wa Yutasi ũla wetawa Isikalioti, nake aĩ ũmwe wa ala ĩkũmi na elĩ.'),
('kam', 'LUK', 22, 4, 'Nake athi, na aneenan’ya na athembi anene na makavuteni ma asikalĩ, ũndũ ũtonya kũmũnengane kwoo.'),
('kam', 'LUK', 22, 5, 'Nao matana, na meew’ana nake mamũnenge mbesa.'),
('kam', 'LUK', 22, 6, 'Nake eetĩkĩla, na amantha mwanya wa kũmũnengane kwoo ĩkomano yĩte vo.'),
('kam', 'LUK', 22, 7, 'Na mũthenya wa kĩmũtũ kĩte ĩlawa wavika, yĩla katena ka vasaka kaaĩlaa kũawa.'),
('kam', 'LUK', 22, 8, 'Na atũma Vetelo na Yoana, akyasya, Endai mũkatũseũvĩsye vasaka, nĩ kana tũye.'),
('kam', 'LUK', 22, 9, 'Na mamwĩa, Wĩenda tũkaseũvĩsye va?'),
('kam', 'LUK', 22, 10, 'Nake amea, Sisyai, mwavota ndũanĩ, mũkakomana na mũndũ ũkuĩte kĩkuu kya manzĩ; mũvikĩlei nyũmbanĩ o vala wĩlika.'),
('kam', 'LUK', 22, 11, 'Na mũkamwie mwene nyũmba, Mũmanyĩsya aũkũlya, Nyũmba ya aeni ĩĩva vala ngũĩa vasaka na amanyĩw’a makwa?'),
('kam', 'LUK', 22, 12, 'Nake akamwon’ya nyũmba nene ya iũlũ yĩ na mĩio; seũvĩsyai vo.'),
('kam', 'LUK', 22, 13, 'Na mathi na moona o ũndũ ũmatavisye: na maseũvya vasaka.'),
('kam', 'LUK', 22, 14, 'Na saa wavika, ekala nthĩ vamwe na atũmwa.'),
('kam', 'LUK', 22, 15, 'Na amea, Nĩnendaa mũno kũĩsanĩa nenyu vasaka ũũ ndanamba kũnyamaw’a:'),
('kam', 'LUK', 22, 16, 'nũndũ nĩngũmũtavya, Ndikaya w’o ĩngĩ, kũvika yĩla ũkeanĩw’a ũsumbĩnĩ wa Ngai.'),
('kam', 'LUK', 22, 17, 'Nake oosa kĩkombe, na amina kũtũnga mũvea, asya, Osai kĩĩ, mũolane inyw’onthe:'),
('kam', 'LUK', 22, 18, 'nũndũ nĩngũmwĩa, Kuma yu ndikanyw’a ĩngĩ ya ũsyao wa mũsavivũ, mũvaka ũsumbĩ wa Ngai wooka.'),
('kam', 'LUK', 22, 19, 'Nake oosa kĩmũtũ, na amina kũtũnga mũvea, atilanga, na amanenga, akyasya, Kĩĩ nĩkyo mwĩĩ wakwa ũla wanenganiwe nũndũ wenyu: ĩkaai ũu ũndũ wa kũndilikana.'),
('kam', 'LUK', 22, 20, 'Na mamina kũya, oosa kĩkombe eeka o ũu, akyasya, Kĩkombe kĩĩ nĩ ũtianĩo mweũ nthĩnĩ wa nthakame yakwa, ĩla ĩĩtĩkwa kwondũ wenyu.'),
('kam', 'LUK', 22, 21, 'Ĩndĩ sisyai, kw’oko kwa ũla ũnũkũmbũnyanĩa kwĩ vamwe nakwa vaa mesanĩ.'),
('kam', 'LUK', 22, 22, 'Nũndũ nĩ w’o Mwana wa mũndũ ethi, o tondũ kweeaiwe: ĩndĩ woo ni wa mũndũ ũla wĩmũvũnyanĩa!'),
('kam', 'LUK', 22, 23, 'Nao mambĩlĩlya kũkũlan’ya ene kwa ene, nĩ wĩva katĩ woo ũla wĩĩka ũndũ ũsu.'),
('kam', 'LUK', 22, 24, 'Na veethĩwa ngananĩo katĩ woo, nũũ ũla ũtalawa kwĩthĩwa nĩ mũnene.'),
('kam', 'LUK', 22, 25, 'Nake amea, Andũ‐ma‐mbaĩ‐ingĩ nĩmasumbĩkawa nĩ asumbĩ moo; na ala me ũkũmũ ĩũlũ woo metawa Eki‐ma‐nesa.'),
('kam', 'LUK', 22, 26, 'Ĩndĩ inyw’ĩ mũtikethĩwe mũily ũu: ĩndĩ ũla mũnene katĩ wenyu, nĩethĩwe ta ũla mũnini; na ũla wĩ mbee, nĩethĩwe ta ũla ũthũkũmaa.'),
('kam', 'LUK', 22, 27, 'Nũndũ mũnene nĩ wĩva, ũla wĩkalaa nthĩ akĩya, kana nĩ ũla ũthũkũmaa? Ti ũla ũilyĩ nthĩ akĩya? Ĩndĩ nyie katĩ wenyu nĩilyĩ ta ũla ũthũkũmaa.'),
('kam', 'LUK', 22, 28, 'Ĩndĩ inyw’ĩ mwĩ ala mwĩkalanĩtye nakwa matatwanĩ makwa;'),
('kam', 'LUK', 22, 29, 'nakwa nĩngũmwiĩa ũsumbĩ, o tondũ Asa wakwa wambiĩe,'),
('kam', 'LUK', 22, 30, 'nĩ kana mũkaĩsaa na kũnyusaa mesanĩ yakwa ũsumbĩnĩ wakwa; na nĩmũkekalĩla ivĩla sya ũsumbĩ mũkĩsilĩla mbaĩ ĩkũmi na ilĩ sya Isilaeli.'),
('kam', 'LUK', 22, 31, 'Simoni, Simoni, sisya, Satani nũkũlĩtye anengwe inyw’ĩ, nĩ kana amũthũngũthangye tondũ nganũ ithũngũthangaw’a:'),
('kam', 'LUK', 22, 32, 'ĩndĩ nĩnakũvoyea, kana mũĩkĩĩo waku ndũkathele; naku wasyoka, lũlũmĩlya ana‐a‐au.'),
('kam', 'LUK', 22, 33, 'Na amwĩa, Mwĩaĩi, nĩnĩyũmbanĩtye kũendan’ya naku kolokolonĩ na kĩkw’ũnĩ.'),
('kam', 'LUK', 22, 34, 'Na asya, Nĩngũkwĩa, Vetelo, ũtũkũ ũũ nzamba ndĩkasya, ũtakaĩĩte katatũ atĩ ndũmbĩsĩ.'),
('kam', 'LUK', 22, 35, 'Na amakũlya, Yĩla namũtũmie mũte na ngusu ya mbesa, kana mũvuko, kana iatũ, nĩmwaaĩwe nĩ kĩndũ? Na masya, Aiee, tũtyaaĩwa.'),
('kam', 'LUK', 22, 36, 'Nake amea, Ĩndi yu, ũla wĩ na ngusu ya mbesa, nakue, na mũvuko o ta ũu; na ũla ũte na ũvyũ, athoosye ngũa yake ya ĩũlũ, athooe.'),
('kam', 'LUK', 22, 37, 'Nũndũ nĩngũmwĩa, ũũ ũla ũandĩkĩtwe ndwĩ ndĩi ya ũlea kwĩanĩw’a nthĩnĩ wakwa atĩĩ, Nake atalilwe vamwe na avĩtan’ya: nĩkwĩthĩwa maũndũ ala maandĩkĩtwe kwondũ wakwa makeanĩw’a.'),
('kam', 'LUK', 22, 38, 'Na masya, Mwĩaĩi, sisya, vaa ve mbyũ ilĩ. Na amea, Nũu.'),
('kam', 'LUK', 22, 39, 'Na aumaala, na athi kĩĩmanĩ kya Mĩthata, o tondũ wekaa; na avikĩlwa nĩ amanyĩw’a.'),
('kam', 'LUK', 22, 40, 'Na avika vo, amea, Voyai mũtikalike matatwani.'),
('kam', 'LUK', 22, 41, 'Nake ataanĩsya nao o ta vandũ va kwĩkya ĩvia; na atulya ndu avoya,'),
('kam', 'LUK', 22, 42, 'akyasya, Asa, ethĩwa nũkwenda, mbathũkĩsya kĩkombe kĩĩ: ĩndĩ ti ũndũ ngwenda nyie, ĩndĩ nĩwĩkĩke ũla ũkwenda we.'),
('kam', 'LUK', 22, 43, 'Na aumĩlĩlwa nĩ mũlaĩka kuma ĩtunĩ, amwĩkĩa vinya.'),
('kam', 'LUK', 22, 44, 'Nake kwa kwĩthĩwa aĩ na thĩna mũnene, ongelela kũvoya na kĩthing’ĩĩsyo; na yuutĩa yake yatw’ĩka ta mavoloto manene ma nthakame, maivolotanga nthĩ.'),
('kam', 'LUK', 22, 45, 'Na yĩla wokĩlile kuma kũvoyanĩ kwake, athi vala ve amanyĩw’a make, amethĩa makomete nĩ too wa kĩmako,'),
('kam', 'LUK', 22, 46, 'na amea, Nĩkĩ mũkomie? Ũkĩlai mũvoye, mũikalike ũtatwanĩ.'),
('kam', 'LUK', 22, 47, 'Na aineena, sisya, ĩkomano yaumĩla, na ũla wetawa Yutasi, ũmwe wa ala ĩkũmi na eli, amatongoesye; na amũthengeea Yesũ nĩ kana amũmumunye.'),
('kam', 'LUK', 22, 48, 'Ĩndĩ Yesũ amwĩa, Yutasi, nũũmũvũnyanĩa Mwana wa mũndũ na kũmũmumunya?'),
('kam', 'LUK', 22, 49, 'Na yĩla ala maĩ nake moonie ũndũ ũla ũkwĩkwa masya, Mwĩaĩi, nĩtũmateme na ũvyũ?'),
('kam', 'LUK', 22, 50, 'Na ũmwe woo amĩtema ngombo ya mũthembi mũnene, amĩtila kũtũ kwa ngalĩ ya kw’oko kwa aũme.'),
('kam', 'LUK', 22, 51, 'Ĩndĩ Yesũ asũngĩa na asya, Ekai, nũu. Na akiita kũtũ kwayo, na amĩvosya.'),
('kam', 'LUK', 22, 52, 'Na Yesũ amea athembi anene, na ala anene ma ĩkalũ, na atumĩa, ala mookĩte mamũkwate, Nĩmwaumĩla, tondũ mũvutani wumĩlĩlawa, mwĩ na mbyũ na mathimbũ?'),
('kam', 'LUK', 22, 53, 'Mũiaambũkĩlĩlya moko yĩla naĩ nenyu kĩla mũthenya ĩkalũnĩ: ĩndĩ ũũ nĩw’o saa wenyu, na ũkũmũ wa kĩvindu.'),
('kam', 'LUK', 22, 54, 'Namo mamũkwata, na mamũtongoesya, mamũtwaa nyũmbanĩ ya mũthembi mũnene. Ĩndĩ Vetelo amũatĩĩa e kũasa.'),
('kam', 'LUK', 22, 55, 'Na mavuva mwaki nza, na mekala nthĩ vamwe, na Vetelo ekala katĩ woo.'),
('kam', 'LUK', 22, 56, 'Na mwĩĩtu mũthũkũmi amwona ailyĩ kyeninĩ amũketeea, na asya, Mũndũ ũũ eĩ vamwe nake.'),
('kam', 'LUK', 22, 57, 'Ĩndĩ akaĩa, akyasya, Mũndũ mũka, ndimwĩsĩ.'),
('kam', 'LUK', 22, 58, 'Na ĩtina vandũ vanini mũndũ ũngĩ amwona, na asya, Naku wĩ ũmwe wa asu. Ĩndĩ Vetelo asya, Mũndũ we, ndi ũmwe.'),
('kam', 'LUK', 22, 59, 'Na ĩtina ta vandũ va saa ũmwe mũndũ ũngĩ athetheesya kũneena, akyasya, Nĩ w’o ki mũndũ ũũ eĩ vamwe nake; nũndũ we nĩ Mũkalilii.'),
('kam', 'LUK', 22, 60, 'Ĩndĩ Vetelo asya, Mũndũ we, ndimanya ũndũ ũkwasya. Na kavinda kau, yĩla waneenaa ũu, nzamba yasya.'),
('kam', 'LUK', 22, 61, 'Na Mwĩaĩi eethyũũa, na amũsisya Vetelo. Na Vetelo alilikana ndeto sya Mwiaĩi, ila wamwĩie, Ũmũnthĩ nzamba ĩtanamba kwasya ũkangaĩa katatũ.'),
('kam', 'LUK', 22, 62, 'Nake aumaala, na aĩa kĩĩo kĩ woo.'),
('kam', 'LUK', 22, 63, 'Na andũ ala mamũkwete Yesũ mamũthekeea na kĩvũthya, na mamũkũna.'),
('kam', 'LUK', 22, 64, 'Na mamũvw’ĩka metho, na mamũkũlya, makyasya, Athana: nũũ ũla wakũkũna?'),
('kam', 'LUK', 22, 65, 'Na mamũneenea maũndũ angĩ maingĩ, makĩmũumanga.'),
('kam', 'LUK', 22, 66, 'Na kwakya, nzama ya atumĩa ma andũ yoombana, o athembi anene na aandĩki; na mamũtwaa nzamanĩ yoo, makyasya,'),
('kam', 'LUK', 22, 67, 'Ethĩwa nue Klĩsto, tũtavye. Ĩndĩ amea. O na ethĩwa nĩngũmũtavya, mũtyĩtĩkĩla:'),
('kam', 'LUK', 22, 68, 'o na ethĩwa nĩngũmũkũlya, mũinzũngĩa.'),
('kam', 'LUK', 22, 69, 'Ĩndĩ kuma yu Mwana wa mũndũ akeethĩwa ailyĩ kw’okonĩ kwa aũme kwa vinya wa Ngai.'),
('kam', 'LUK', 22, 70, 'Na onthe masya, Ĩndĩ we nue Mwana wa Ngai? Nake amea, Inyw’ĩ nĩmũkwasya ninyie we.'),
('kam', 'LUK', 22, 71, 'Na masya, Twĩ na vata ũngĩ mwaũ wa ũkũsĩ? Nũndũ ithyĩ ene nĩtweew’a kuma kanyw’anĩ wake.'),
('kam', 'LUK', 23, 1, 'Na ĩkomano yonthe yookĩla, yamũtwaa kwa Vilato.'),
('kam', 'LUK', 23, 2, 'Na yambĩlĩlya kũmũvinganĩsya, ĩkyasya, Nĩtũmwonete mũndũ ũũ aiasya, mbaitũ, aimavata kũmũnenga Kaisali koti, akyasya we mwene nĩ Klĩsto, mũsumbi.'),
('kam', 'LUK', 23, 3, 'Na Vilato amũkũlya, akyasya, Nue mũsumbĩ wa Ayuti? Na amũsũngĩa, amwĩa, Nĩwaneena we.'),
('kam', 'LUK', 23, 4, 'Na Vilato amea athembi anene na makomano, Ndiona ũndũ ũtaĩle mũndũnĩ ũũ.'),
('kam', 'LUK', 23, 5, 'Ĩndĩ mathetheesya kũneena, makyasya, Ũũ nũnũũthokoan’ya andũ, akĩmanyĩsya Yutia yonthe, kwambĩlĩlya Kalilii kũvika o vaa.'),
('kam', 'LUK', 23, 6, 'Na Vilato eew’a ũu, akũlya kana mũndũ ũũ nĩ Mũkalilii.'),
('kam', 'LUK', 23, 7, 'Na amanya kana nĩ wa kũla Elote ũsumbĩkĩte, amũtwaĩthya kwa Elote, nũndũ aĩ Yelusaleme matukũ asu.'),
('kam', 'LUK', 23, 8, 'Na yĩla Elote wamwonie Yesũ, eew’a mũyo mũno: nĩkwĩthĩwa nĩ ĩvinda ĩasa wendie kũmwona, nũndũ nĩwewie ũvoo wake; na endaa kwona kyama kĩkĩkwa nĩwe.'),
('kam', 'LUK', 23, 9, 'Na amũkũlya ndeto nyingĩ; ĩndĩ ndaamũsũngĩa ũndũ.'),
('kam', 'LUK', 23, 10, 'Na athembi anene na aandĩki maũngama, na makatĩĩa mũno kũmũvinganĩsya.'),
('kam', 'LUK', 23, 11, 'Na Elote vamwe na asikalĩ make mamũvũthya na mamũthekeea, na makĩmũvw’ĩka ngũa mbanakavye mamũtũnga kwa Vilato.'),
('kam', 'LUK', 23, 12, 'Na mũthenya ũsu Elote na Vilato matuma ndũũ: nũndũ mbee nĩmamenene.'),
('kam', 'LUK', 23, 13, 'Na Vilato oomban’ya athembi anene, na asumbĩki, vamwe na andũ,'),
('kam', 'LUK', 23, 14, 'na amea, Inyw’ĩ nĩmwandetee mũndũ ũũ, ta ũla ũnũkwasya andũ: na sisyai, nĩnamũkũlya mwĩ vo, na ndinona ũndũ ũtaĩle wa mũndũ ũũ maũndũnĩ asu ala mũmũvinganĩsye namo:'),
('kam', 'LUK', 23, 15, 'aiee, o na Elote ndanona: nũndũ nĩwamũtũnga kwitũ; na sisyai, vai ũndũ wĩkĩtwe nĩwe ũla ũtuma oawa.'),
('kam', 'LUK', 23, 16, 'Kwondũ wa ũu nĩngũmũkũna, na ngĩmũthasya.'),
('kam', 'LUK', 23, 17, 'Nũndũ no mũvaka amathaĩsye ũmwe ĩvinda ya mboka.'),
('kam', 'LUK', 23, 18, 'Na onthe mookĩlya wasya vamwe, makyasya, Mũvete mũndũ ũũ, noitũthaĩsya Valava:'),
('kam', 'LUK', 23, 19, 'nake nĩ ũla wekĩiwe kolokolonĩ nũndũ wa ũng’endu ndũanĩ, na ũndũ wa ũaani.'),
('kam', 'LUK', 23, 20, 'Na Vilato aneena nao ĩngĩ, akyenda kũmũthasya Yesũ;'),
('kam', 'LUK', 23, 21, 'ĩndĩ mookĩlya mawasya, makyasya, Mwambe, mwambe.'),
('kam', 'LUK', 23, 22, 'Nake amatavya ĩngĩ ya katatũ, Nĩkĩ, nĩ ũthũku mwaũ mũndũ ũũ wĩkĩte? Ndinona ũndũ kwake ũtuma oawa: nũndu wa ũu nĩngũmũkũna na ngĩmũthasya.'),
('kam', 'LUK', 23, 23, 'Ĩndĩ makatĩĩa ũneena na mawasya manene, makyenda ambwe. Na mawasya moo makĩlya vinya.'),
('kam', 'LUK', 23, 24, 'Na Vilato atw’a wĩkwe tondũ mekwenda.'),
('kam', 'LUK', 23, 25, 'Na amũthasya ũla wekĩiwe kolokolonĩ nũndũ wa ũng’endu na ũaani, ũla meetisye; ĩndĩ Yesũ anenganwe mamwĩke tondũ mendaa.'),
('kam', 'LUK', 23, 26, 'Na mamũtwaĩte, makwata mũndũ ũmwe wetawa Simoni, Mũkulene, wokĩte akyuma ũtee wa ndũa, na mamwilĩĩla ngelan’yo, nĩ kana amĩkue ĩtina wa Yesũ.'),
('kam', 'LUK', 23, 27, 'Na avikĩlĩtwe nĩ ĩkomano ĩnene ya andũ, na aka ala mekũnangaa ithũi na kũmũĩĩa.'),
('kam', 'LUK', 23, 28, 'Ĩndĩ Yesũ amethyũũĩa amea, Eĩtu ma Yelusaleme, ekai kũndĩĩa nyie, ĩndĩ ĩai kwondũ wenyu ene na syana syenyu.'),
('kam', 'LUK', 23, 29, 'Nũndũ sisyai, mĩthenya nĩyũkĩte, yĩla makasya, Nĩ aathime ala ngũngũ, na mavu ala mataasyaa, na nondo itaaongwa.'),
('kam', 'LUK', 23, 30, 'Nĩvo ĩndĩ makambĩlĩlya kũtavya iĩma, Tũvalũkĩlei; na tũlĩma, Tũvw’ĩkei.'),
('kam', 'LUK', 23, 31, 'Nũndũ ethĩwa nĩmekwĩka maũndũ aa mũtĩnĩ mwĩũ, mũtĩnĩ mũmũ kũkekwa ata?'),
('kam', 'LUK', 23, 32, 'Na vaĩ angĩ elĩ, andũ athe, matwaĩtwe vamwe nake, moawe.'),
('kam', 'LUK', 23, 33, 'Na mavika vandũ vetawa Kĩng’ala, mamwamba vo, vamwe na ala athe, ũmwe ngalĩ ya kw’oko kwa aũme na ũla ũngĩ ngalĩ ya kw’oko kwa aka.'),
('kam', 'LUK', 23, 34, 'Na Yesũ asya, Asa, maekee; nĩkwĩthĩwa matimanya ũndũ mekwĩka. Na maaan’ya ngũa syake, makĩlimana.'),
('kam', 'LUK', 23, 35, 'Na andũ maũngeme makĩloela. Na asumbĩki mamũthekeea, makyasya, Nĩwatangĩĩe angĩ; nĩetangĩĩe mwene, ethĩwa ũũ nĩ Klĩsto wa Ngai, ũla, mũnyuve wake.'),
('kam', 'LUK', 23, 36, 'Na asikalĩ mamũthekeea o ta ũu, makĩthi vala ũĩ, makĩmũnenga siki,'),
('kam', 'LUK', 23, 37, 'makĩmwĩa, Ethĩwa wĩ mũsumbĩ wa Ayuti, ĩtangĩĩe mwene.'),
('kam', 'LUK', 23, 38, 'Na vaandĩkĩtwe ũandĩko ĩũlũ wake, atĩĩ, ŨŨ NĨWE MŨSUMBĨ WA AYUTI.'),
('kam', 'LUK', 23, 39, 'Na ũmwe wa asu athe ala mambĩtwe vamwe nake amũuma, akyasya, We tuue Klĩsto? Ĩtangĩĩe mwene, naitũ.'),
('kam', 'LUK', 23, 40, 'Ĩndĩ ũla ũngĩ asũngĩa, aimũkan’ya, akyasya, Ndũmũkĩa Ngai we, nũndũ wĩ mũsilĩle ũndũ ũmwe nake?'),
('kam', 'LUK', 23, 41, 'Naitũ nĩtũsilĩlwe sila wa katĩ; nũndũ nĩtũkũĩvwa kwĩanana na meko maitũ: ĩndĩ mũndũ ũũ ndaaĩka ũndũ ũtaĩle.'),
('kam', 'LUK', 23, 42, 'Na amwĩa, Yesũ, wĩndilikana yĩla wĩvika ũsumbĩnĩ waku.'),
('kam', 'LUK', 23, 43, 'Yesũ amwĩa, Nĩ w’o nĩngũkwĩa, Ũmũnthĩ ũkeethĩwa vamwe nakwa Ũseonĩ.'),
('kam', 'LUK', 23, 44, 'Na yu kwaĩ ta syũa yĩkĩũngama, na kwaya kĩvindu nthĩ yonthe kũvika saa kenda,'),
('kam', 'LUK', 23, 45, 'kyeni kya syũa kyaaa: na ngũa ya tũtũ ya ĩkalũ yatembũkanĩla katĩ.'),
('kam', 'LUK', 23, 46, 'Na Yesũ ookĩlya wasya mũnene, na asya, Asa, veva wakwa nĩngũwia mokonĩ maku: na amina kũneena uũ, aumya veva wake.'),
('kam', 'LUK', 23, 47, 'Na ũla mũnene wa asikalĩ ĩana oona ũndũ kweekĩka, amũkatha Ngai, akyasya, Nĩ w’o mũndũ ũũ eĩ mũlũngalu.'),
('kam', 'LUK', 23, 48, 'Na makomano onthe ala mombanĩte kwĩloela maũndũ asu, yĩla moonie maũndũ ala meekĩka, masyoka makĩkũnanga ithũi syoo.'),
('kam', 'LUK', 23, 49, 'Na onthe ala meesene nake, na aka ala mamũvikĩlĩte kuma Kalilii, maũngeme kũasa, makĩloela maũndũ asu.'),
('kam', 'LUK', 23, 50, 'Na ĩndĩ, kwaĩ mũndũ wetawa Yosevu, waĩ wa nzama, nake aĩ mũndũ mũseo na mũlũngalu,'),
('kam', 'LUK', 23, 51, '(ndaaĩkĩanĩa namo ũtw’ĩonĩ woo na ũndũnĩ ũla meekie), mũndũ wa Alimathia, ndũa ĩmwe ya Ayuti, ũla weteele ũsumbĩ wa Ngai:'),
('kam', 'LUK', 23, 52, 'mũndũ ũsu athi kwa Vilato, na amwĩtya mwĩĩ wa Yesũ.'),
('kam', 'LUK', 23, 53, 'Nake awumya nthĩ, na oolingĩla ngũa ya katane, na awia mbũanĩ ĩla yasĩtwe ĩvianĩ, ĩla ĩtaamba kwiwa mũndũ.'),
('kam', 'LUK', 23, 54, 'Na mũthenya ũsu waĩ mũthenya wa Ũseũvyo, naw’o mũthenya wa savato wakilĩlye kũvika.'),
('kam', 'LUK', 23, 55, 'Na aka, ala maumĩte nake Kalilii, mathi ĩtina, na moona mbũa ĩsu, ũndũ mwĩĩ wake waiĩtwe.'),
('kam', 'LUK', 23, 56, 'Na masyoka, maseũvya mĩtĩ yĩ mũuke mũseo, na mauta. Na mathũmũa mũthenya wa savato o ũndũ kwĩaĩtwe.'),
('kam', 'LUK', 24, 1, 'Ĩndĩ mũthenya wa mbee wa kyumwa, ũiambĩlĩlya kũkya, mathi mbũanĩ, makuĩte mĩtĩ ĩsu yĩ mũuke mũseo ĩla maseũvĩtye.'),
('kam', 'LUK', 24, 2, 'Na meethĩa ĩvia yĩvingilitangĩtw’e kuma mbũanĩ.'),
('kam', 'LUK', 24, 3, 'Na mavota nthĩnĩ, na maiaona mwĩĩ wa Mwĩaĩi Yesũ.'),
('kam', 'LUK', 24, 4, 'Na kweethĩwa, makĩsũanĩwa nĩ ũu, sisya, aũme elĩ maũngama vakuvĩ nao, mevw’ĩkĩte ngũa ikũtisatisa:'),
('kam', 'LUK', 24, 5, 'na aka asu makwatwa nĩ w’ĩa, na makunamĩa nthĩ, makũlw’a, Nĩkĩ mũmũmantha ũla wĩ thayũ katĩ wa ala akw’ũ?'),
('kam', 'LUK', 24, 6, 'Nde vaa, nũthayũũkĩte: lilikanai ũndũ wamũtavisye yĩla waĩ Kalilii,'),
('kam', 'LUK', 24, 7, 'akyasya, Mwana wa mũndũ nde ndĩi ya kũlea kũnenganwe mokonĩ ma ala athe, na kwambwa, na kũthayũũka mũthenya wa katatũ.'),
('kam', 'LUK', 24, 8, 'Nao malilikana ndeto syake,'),
('kam', 'LUK', 24, 9, 'na masyoka kuma mbũanĩ, na mamatavya ala ĩkũmi na ũmwe, na ala angĩ onthe, maũndũ asu onthe.'),
('kam', 'LUK', 24, 10, 'Ala mamatavisye atũmwa maũndũ asu nĩ Meli Makatalene, na Yoena, na Meli inyia wa Yakovo, na aka angĩ ala maĩ vamwe nao.'),
('kam', 'LUK', 24, 11, 'Na moona ndeto isu ta sya mana; na malea kũsyĩtĩkĩla.'),
('kam', 'LUK', 24, 12, 'Ĩndĩ Vetelo ookĩla, asemba athi mbũanĩ; akunama na asisya nthĩnĩ, na oona itambaa sya katane siĩtwe syĩ syoka; na asyoka kwake, aseng’ete ũndũ wa ũndũ ũsu wĩkiwe.'),
('kam', 'LUK', 24, 13, 'Na mũthenya o ũsu elĩ moo maendete mũsyĩ wĩtawa Emau, ũla waĩ kũasa na Yelusaleme ta maĩli mũonza na nyunzu.'),
('kam', 'LUK', 24, 14, 'Na maneenan’ya ũndũ wa maũndũ asu onthe ala mekĩkĩte.'),
('kam', 'LUK', 24, 15, 'Na kweethĩwa, yĩla maneenanasya na kũkũlan’ya, Yesũ mwene athengeea, na aendan’ya nao.'),
('kam', 'LUK', 24, 16, 'Ĩndĩ metho moo masiĩĩwa matikamũmanye.'),
('kam', 'LUK', 24, 17, 'Na amea, Nĩ maũndũ maũ mũkũneenan’ya mũendete? Na maũngama, matukĩtye mothyũ.'),
('kam', 'LUK', 24, 18, 'Na ũmwe, ũla wetawa Kileova, amũsũngĩa, amwĩa, Wĩkalĩte Yelusaleme wĩ weka atĩ ndũmanya maũndũ ala mekĩtwe kw’o mĩthenye ĩno?'),
('kam', 'LUK', 24, 19, 'Nake amakũlya, Nĩ maũndũ maũ? Nao mamwĩa, Nĩ maũndũ ma Yesũ Mũnasaleti, ũla ũnaĩ mwathani wĩ vinya wa kwĩka, na wa kũneena mbee wa Ngai na mbee wa andũ onthe:'),
('kam', 'LUK', 24, 20, 'na ũndũ athembi anene na asumbĩki maitũ mamũnenganie atw’ĩĩwe kũawa, na mamwamba.'),
('kam', 'LUK', 24, 21, 'Ĩndĩ ithyĩ tũneekwetye kana nĩwe ũkovosya Isilaeli. Ĩĩ, na vamwe na ũu w’onthe, ũmũnthĩ nĩ mũthenya wa katatũ kuma maũndũ asu meekwa.'),
('kam', 'LUK', 24, 22, 'Na ĩngĩ aka amwe ma nguthu yaitũ nĩmatũseng’isye, ala maendie mbũanĩ kĩoko tene;'),
('kam', 'LUK', 24, 23, 'na malea kwona mwĩĩ wake, mooka makyasya kana nĩmaumĩlĩlwa nĩ alaĩka, ala mamatavisye e thayũ.'),
('kam', 'LUK', 24, 24, 'Na amwe ala maĩ vamwe naitũ mathi mbũanĩ, na moona o ũndũ aka maisye: ĩndĩ we mwene mainamwona.'),
('kam', 'LUK', 24, 25, 'Nake amea, Inyw’ĩ andũ atumanu, na ene ngoo syĩtĩkĩlaa mbola maũndũ onthe ala maneeniwe nĩ athani!'),
('kam', 'LUK', 24, 26, 'Klĩsto ndaaĩlwe nĩ kũnyamaw’a nĩ maũndũ asu, na kũlika ũtheunĩ wake mũtisu?'),
('kam', 'LUK', 24, 27, 'Na ambĩlĩlya na Mose na athani onthe, amavuanĩsya maandĩkonĩ onthe maũndũ ala maandĩkiwe ũndũ wake.'),
('kam', 'LUK', 24, 28, 'Na mathengeea mũsyĩ ũla meũendaa: nake eeka ta ũnũũvĩta.'),
('kam', 'LUK', 24, 29, 'Na mamũingĩĩsya, makyasya, Ĩkala naitũ; nũndũ kũkilĩlye kũtuka, na syũa nĩ ta ĩthũu. Na alika ekale nao.'),
('kam', 'LUK', 24, 30, 'Na kweethĩwa, yĩla wailyĩ nao maiya lĩu, oosa kĩmũtũ na akĩathima, na akĩtilanga, na amanenga.'),
('kam', 'LUK', 24, 31, 'Na metho moo masalukw’a, na mamũmanya; nake aaa.'),
('kam', 'LUK', 24, 32, 'Nao maneenan’ya ene kwa ene, Ngoo sitũ itinew’a muutĩa yĩla ũnũũneenaa naitũ nzĩanĩ, aitũvuanĩsya maandĩko?'),
('kam', 'LUK', 24, 33, 'Na mookĩla saa o ũsu, masyoka Yelusaleme, na meethĩa ala ĩkũmi na ũmwe mombanĩte, na ala maĩ vamwe nao,'),
('kam', 'LUK', 24, 34, 'makyasya, Nĩ w’o Mwĩaĩi nũthayũũkie, na nũmumĩlĩle Simoni.'),
('kam', 'LUK', 24, 35, 'Na mamatavya maũndũ ma nzĩanĩ, na ũndũ ũmanyĩkie nĩmo yĩla ũnũũtilangaa kĩmũtũ.'),
('kam', 'LUK', 24, 36, 'Na makĩneena maũndũ asu, Yesũ mwene aũngama katĩ woo, na amea, Mũuo nĩwĩthĩwe nenyu.'),
('kam', 'LUK', 24, 37, 'Ĩndĩ matw’ika nda na makwatwa nĩ w’ĩa, makĩtalĩthya kana meona veva.'),
('kam', 'LUK', 24, 38, 'Na amea, Nĩkĩ mũkũũũya? Na nũndũ wa kĩ mosũanĩo meũkĩla ngoonĩ syenyu?'),
('kam', 'LUK', 24, 39, 'Sisyai moko makwa na maũũ makwa, kana ninyie mwene; ngwatangai, mũnzisye; nĩkwĩthĩwa veva ndwĩ nyama na mavĩndĩ, tondũ mũmbona nĩ nasyo.'),
('kam', 'LUK', 24, 40, 'Na amina kũneena ũu, amon’ya moko make na maũũ make.'),
('kam', 'LUK', 24, 41, 'Nao kavinda kau makĩlea kũĩkĩĩa nũndũ wa ũtanu, na kũseng’a, amea, Mwĩ na kĩndũ kya ũya vaa?'),
('kam', 'LUK', 24, 42, 'Na mamũnenga kĩlungu kya ĩkũyũ ĩvĩvye.'),
('kam', 'LUK', 24, 43, 'Nake oosa, na aya mene.'),
('kam', 'LUK', 24, 44, 'Na amea, Ii nĩsyo ndeto syakwa ila namũtavisye yĩla naĩ nenyu, atĩ mũvaka maũndũ onthe meanĩw’e ala maandĩkĩtwe ũndũ wakwa mĩaonĩ ya Mose, na mavukunĩ ma athani, na ĩvukunĩ ya Savuli.'),
('kam', 'LUK', 24, 45, 'Na ĩndĩ avindũa ilĩko syoo, nĩ kana mamanye maandĩko;'),
('kam', 'LUK', 24, 46, 'na amea, Ũu nĩw’o kũandĩkĩtwe, kana Klĩsto akanyamaw’a, na kũthayũũka mũthenya wa katatũ kuma akw’ũni:'),
('kam', 'LUK', 24, 47, 'na kana ũalyũlo wa ngoo na kũekewa naĩ kũtavanw’e syĩtwanĩ yake mbaĩnĩ syonthe, kwambĩlĩlya Yelusaleme.'),
('kam', 'LUK', 24, 48, 'Nenyu mwĩ ngũsĩ sya maũndũ asu.'),
('kam', 'LUK', 24, 49, 'Na sisyai, nĩngũmũtũmĩa watho wa Asa wakwa; ĩndĩ ĩkalai ĩ ndũanĩ, mũvaka mũvw’ĩkwe na vinya kuma ĩũlũ.'),
('kam', 'LUK', 24, 50, 'Na amatongoesya kũvika Vethania; na ookĩlya moko make, na amaathima.'),
('kam', 'LUK', 24, 51, 'Na kweethĩwa akĩmaathima, ataanĩsya nao, na ambatw’a ĩtunĩ.'),
('kam', 'LUK', 24, 52, 'Na mamũthaitha, na masyoka Yelusaleme na ũtanu mũnene:'),
('kam', 'LUK', 24, 53, 'na mekalaa ĩkalũnĩ mavinda onthe, makĩmũkatha Ngai.'),
('kam', 'JHN', 1, 1, 'Mwambĩlĩlyonĩ kwaĩ Ndeto, na ĩla Ndeto yaĩ vamwe na Ngai, na ĩla Ndeto yaĩ Ngai.'),
('kam', 'JHN', 1, 2, 'Na nĩwe waĩ mwambĩlĩlyonĩ vamwe na Ngaĩ.'),
('kam', 'JHN', 1, 3, 'Syĩndũ syonthe nĩsyatw’ĩkĩthiw’e nĩwe; na ate vo vati kĩndũ o na kĩmwe kyaatw’ĩkĩthw’a katĩ wa ila syatw’ĩkĩthĩw’e'),
('kam', 'JHN', 1, 4, 'Nthĩnĩ wake vaĩ thayũ; na ũla thayũ waĩ kyeni kya andũ.'),
('kam', 'JHN', 1, 5, 'Na kĩla kyeni kĩkenaa kĩvindunĩ; na kĩvindu kĩinakĩkĩlya vinya.'),
('kam', 'JHN', 1, 6, 'Kwookie mũndũ atũmĩtwe kuma kwa Ngai, wetawa Yoana.'),
('kam', 'JHN', 1, 7, 'Ũsu ookie nũndũ wa ũkũsi, nĩ kana akũsĩĩe kĩla kyeni, andũ onthe metĩkĩle nũndũ wake.'),
('kam', 'JHN', 1, 8, 'Ndaĩ kyeni we, ĩndĩ ookie akũsĩĩe kĩla kyenĩ.'),
('kam', 'JHN', 1, 9, 'Kyaĩ kyeni kya w’o, kĩla kĩmulĩkaa o mũndũ ũla wũkaa nthĩ.'),
('kam', 'JHN', 1, 10, 'Aĩ kũũ nthĩ, na ĩ nthĩ yatw’ĩkĩthiw’e nĩwe, na nthĩ ndĩamwĩsĩ.'),
('kam', 'JHN', 1, 11, 'Ookĩe kwake mwene, na ala maĩ make maiaamwosa.'),
('kam', 'JHN', 1, 12, 'Ĩndĩ onthe ala mamwosie, amanenga ũkũmũ wa ũtw’ĩka syana sya Ngai, o ala metĩkĩlaa syĩtwa yake:'),
('kam', 'JHN', 1, 13, 'ala mataasyawa nĩ nthakame, kana kwenda kwa mwĩĩ, kana kwenda kwa mũndũ, ĩndĩ nĩ Ngai.'),
('kam', 'JHN', 1, 14, 'Na ĩla Ndeto yatw’ĩka mwĩĩ, na yatũa katĩ waitũ (na ithyĩ twoona ũtheu mũtisu wake, ũtheu mũtisu ta wa ũla wasyaiwe weka auma kwa Asa), ausũĩte mumo na w’o.'),
('kam', 'JHN', 1, 15, 'Yoana amukũsĩĩa, na aneena na wasya mũnene, akyasya, Ũũ nĩwe ũla nawetie atĩĩ, Ũla wũkĩte ĩtina wakwa e mbee wakwa: nũndũ aĩ mbee wakwa.'),
('kam', 'JHN', 1, 16, 'Nũndũ kuma wusũunĩ wake ithyonthe nĩtwoosie, na mumo ĩũlũ wa mumo.'),
('kam', 'JHN', 1, 17, 'Nũndũ ĩla mĩao yanenganĩwe kwa Mose; mumo na w’o maetiwe ni Yesũ Klĩsto.'),
('kam', 'JHN', 1, 18, 'Na vai mũndũ waamwona Ngai o na ĩndĩĩ; ũla Mwana mũsyawa weka, ũla wĩ kĩthũinĩ kya Asa, nĩwe wamumĩlilye.'),
('kam', 'JHN', 1, 19, 'Na ũũ nĩw’o ũkũsĩ wa Yoana, yĩla Ayuti matũmie athembi na Alivai kwake kuma Yelusaleme kũmũkũlya, Nue ũũ?'),
('kam', 'JHN', 1, 20, 'Nake aumbũla, na ndaakaĩa; ĩndĩ aumbũla, asya, Tii nyie Klĩsto.'),
('kam', 'JHN', 1, 21, 'Na mamũkũlya, Nata ĩndĩ? Nue Eliya? Na amea, Tii nyie we. Wĩ ũla mwathani? Na amasũngĩa, Aiee.'),
('kam', 'JHN', 1, 22, 'Na ĩndĩ mamũkũlya, Nue ũũ ĩndĩ? Kana tũkamasũngĩe ala matũtũmie. Wĩasya ata ũndũ waku?'),
('kam', 'JHN', 1, 23, 'Asya, Ninyie wasya wa mũndũ akĩneena mũno weũnĩ, Lũngalyai ũendelo wa Mwĩaĩi, o ũndũ mwathani Isaia waisye.'),
('kam', 'JHN', 1, 24, 'Na ala matũmiwe maumie kwa Avalisi.'),
('kam', 'JHN', 1, 25, 'Na mamũkũlya, na mamwĩa, Wĩvatisĩa kĩ ĩndĩ, ethĩwa tuue Klĩsto, kana Eliya, kana ũla mwathani?'),
('kam', 'JHN', 1, 26, 'Yoana amasũngĩa, akyasya, Nyie nĩvatisaa na manzĩ: katĩ wenyu vaũngamĩte ũmwe ũla mũtesĩ,'),
('kam', 'JHN', 1, 27, 'nĩwe ũla wũkĩte ĩtina wakwa, na ndyĩanĩwe nĩ ũthasya kamũkwa ka kĩatũ kyake.'),
('kam', 'JHN', 1, 28, 'Maũndũ asu nĩmeekĩwe Vethania mbee wa Yolotani, vala Yoana wavtisĩaa.'),
('kam', 'JHN', 1, 29, 'Na ũnĩ ũsu Yoana amwona Yesũ okĩte vala ũĩ, na asya, Sisyai, Katena ka ĩlondu ka Ngai, kala keumya naĩ ya nthĩ!'),
('kam', 'JHN', 1, 30, 'Ũũ nĩwe ũla naneenie ũndũ wake, Ĩtina wakwa vokĩte mũndũ ũla wĩ mbee wakwa: nũndũ aĩ mbee wakwa.'),
('kam', 'JHN', 1, 31, 'Na ndyamwĩsĩ; ĩndĩ nĩ kana onanw’e kwa Isilaelĩ, kwondũ wa ũu nĩnookie ngĩvatisa na manzĩ.'),
('kam', 'JHN', 1, 32, 'Na Yoana aumya ũkũsĩ, akyasya, Nĩnoonie ũla Veva aitheea kuma ĩtunĩ ta ĩvũĩ; na amũvũĩla.'),
('kam', 'JHN', 1, 33, 'Nakwa ndyamwĩsĩ: ĩndĩ ũla wandũmie kũvatisaa na manzĩ, nĩwe wambĩie, Ũla ũkona Veva aimũtheeea, na aimũvũĩla, ũsu nĩwe wĩvatisaa na Veva Mũtheu.'),
('kam', 'JHN', 1, 34, 'Nakwa ninoonie, na nĩnĩkũsĩĩe kana ũũ nĩ Mwana wa Ngai.'),
('kam', 'JHN', 1, 35, 'Na ũnĩ ũsu Yoana aũngeme ĩngĩ, e na elĩ ma amanyĩw’a make;'),
('kam', 'JHN', 1, 36, 'na amũsyaĩĩsya Yesũ aendete, na asya, Sisyai, Katena ka ĩlondu ka Ngai!'),
('kam', 'JHN', 1, 37, 'Na ala amanyĩw’a elĩ mamwĩw’a aineena, na mamũatĩĩa Yesũ.'),
('kam', 'JHN', 1, 38, 'Na Yesũ eethyũũa, na amona mamũvikĩlĩte, na amakũlya, Mwĩmantha kĩ? Na mamwĩa, Lavai (ũalyũlo wayo nĩ, Mũmanyĩsya), ũtwĩe va?'),
('kam', 'JHN', 1, 39, 'Na amea, Ũkai na mũkoona. Na mooka na moona vala ũtwĩe, na mekala nake mũthenya ũsu: na kwaĩ vakũvĩ saa ĩkũmi.'),
('kam', 'JHN', 1, 40, 'Ũmwe wa asu elĩ ala meewie Yoana aineena, na mamũatĩĩa, nĩ Andalea, mwana‐a‐inyia wa Simoni Vetelo.'),
('kam', 'JHN', 1, 41, 'Nake amba ũmwona mwana‐a‐inyia Simoni, na amwĩa, Nĩtwamwona ũla Masia (ũalyũlo wayo nĩ, Klĩsto).'),
('kam', 'JHN', 1, 42, 'Nake amũete vala ve Yesũ. Na Yesũ amwona, na amwĩa, Nue Simoni, mwana wa Yona: ũkeetawa Keva (ũalyũlo wayo nĩ, Vetelo).'),
('kam', 'JHN', 1, 43, 'Na ũnĩ ũsu Yesũ enda kũthi akavike Kalilii, na amwona Vilivu, na Yesũ amwĩa, Mbikĩla.'),
('kam', 'JHN', 1, 44, 'Na Vilivũ aĩ wa Vethisaita, ndũa ya Andalea na Vetelo.'),
('kam', 'JHN', 1, 45, 'Vilivu amũmantha Nathanaeli, na amwĩa, Nĩtwamwona ũla waandĩkiwe nĩ Mose mĩaonĩ, na ũla waandĩkiwe nĩ athani, nake nĩ Yesũ wa ndũa ya Nasaleti, mwana wa Yosevu.'),
('kam', 'JHN', 1, 46, 'Na Nathanaeli amwĩa, Nasaleti nĩvatonya kuma kĩndũ kĩseo? Vilivu amwĩa, Ũka ũkone.'),
('kam', 'JHN', 1, 47, 'Yesũ amwona Nathanaeli aiũka vala ũĩ, na aneena ũndũ wake, Onai, Mũisilaeli ki, ũte ũsekele!'),
('kam', 'JHN', 1, 48, 'Nathanaeli amwĩa, Ũmbĩsĩ ata? Yesũ amũsũngĩa, amwĩa, Vilivu atanamba ũkwĩta, yĩla wĩĩ ĩtina wa mũkũyũ, nĩngwonie.'),
('kam', 'JHN', 1, 49, 'Nathanaeli amũsũngĩa, Lavai, nue Mwana wa Ngai; na nue Mũsumbĩ wa Isilaeli.'),
('kam', 'JHN', 1, 50, 'Yesũ amũsũngĩa, amwĩa, Wĩĩkĩĩa nũndũ nakwĩa, Nĩngwonie ĩtina wa mũkũyũ? Ũkoona maũndũ manene kũvĩta aa.'),
('kam', 'JHN', 1, 51, 'Na amwĩa, Nĩ w’o, nĩ w’o, nĩngũmwĩa, Mũkoona ĩtu yĩkĩvingũka, na alaĩka ma Ngai makyambata na maimũtheeea Mwana wa mũndũ.'),
('kam', 'JHN', 2, 1, 'Na mũthenya wa katatũ kwaĩ mũtwaano ndũanĩ yĩtawa Kena, nthĩ ya Kalilii; na inyia wa Yesũ aĩ vo:'),
('kam', 'JHN', 2, 2, 'na Yesũ vamwe na amanyĩw’a make nĩmeetĩtwe mũtwaanonĩ.'),
('kam', 'JHN', 2, 3, 'Na mbinyu yamanyivĩa, inyia wa Yesũ amwĩa, Mati na mbinyu.'),
('kam', 'JHN', 2, 4, 'Na Yesũ amwĩa, Nĩ ũndũ naku wa kĩ, kĩveti? Saa wakwa ndũnamba ũvika.'),
('kam', 'JHN', 2, 5, 'Na inyia wake amea athũkũmi, O ũndũ wĩmũtavya, wĩkei.'),
('kam', 'JHN', 2, 6, 'Na vo vaĩ mbisũ thanthatũ sya mavia sya kwĩkĩa manzĩ, o ũndũ kwĩkawa kwa kwĩthesya kwa Ayuti, na ĩmwe yeanĩe mĩta ĩlĩ kana ĩtatũ ya kĩkuu kĩnene.'),
('kam', 'JHN', 2, 7, 'Yesũ amea, Usũsyai mbisũ manzĩ. Na masyusũsya ki.'),
('kam', 'JHN', 2, 8, 'Na amea, Tavai yu mũmũtwaĩe mũnene wa mboka. Na mamũtwaĩa.'),
('kam', 'JHN', 2, 9, 'Na mũnene wa mboka asama ala manzĩ maalyũlĩtwe mbinyu, na ndeesĩ vala yauma (ĩndĩ athũkũmi ala matavie manzĩ nĩmo meesĩ), mũnene wa mboka amwĩta mũtwaani,'),
('kam', 'JHN', 2, 10, 'na amwĩa, Kĩla mũndũ mbee aetae mbinyu ĩla nzeo; na andũ manyw’a mũno, nĩvo ĩndĩ ũetae ĩla ĩte nzeo mũno: ĩndĩ we, nĩwĩkalilye mbinyu ĩla nzeo kũvika yu.'),
('kam', 'JHN', 2, 11, 'Na Yesũ eekie kyama kyu kya mbee ndũanĩ ya Kena, nthĩ ya Kalilii, na oonan’ya ũnene wake; na amanyĩw’a make mamwĩtĩkĩla.'),
('kam', 'JHN', 2, 12, 'Ĩtina wa ũu atheea Kavelinaumi, we, na inyia wake, na ana‐a‐inyia, na amanyĩw’a make; na mekala kw’o matukũ mavũthũ.'),
('kam', 'JHN', 2, 13, 'Na vasaka wa Ayuti wathengeea ũvika, na Yesũ ambata Yelusaleme.'),
('kam', 'JHN', 2, 14, 'Na oona ĩkalũnĩ andũ makĩthoosya ng’ombe na malondu na mavũĩ, na ala meũvunzya mbesa mailyĩ nthĩ:'),
('kam', 'JHN', 2, 15, 'na aesũvya mũsalisa wa ndii, na amalũngya onthe ĩkalũnĩ, vamwe na malondu moo na ng’ombe; na mbesa sya ala meũvunzya atulũla, na mesa syoo akuluman’ya;'),
('kam', 'JHN', 2, 16, 'na amea ala mathooasya mavũĩ, Umaalyai syĩndũ ii; ekai ũmĩtw’ĩkĩthya nyũmba ya Asa nyũmba ya ũthooesya syĩndũ.'),
('kam', 'JHN', 2, 17, 'Na amanyĩw’a make malilikana ũndũ kũandĩkĩtwe, Kĩwĩu kya nyũmba yaku kĩkandya.'),
('kam', 'JHN', 2, 18, 'Na ĩndĩ Ayuti mamũsũngĩa na mamwĩa, Wĩtwon’ya wonan’yo mwaũ, ũkĩka maũndũ aa?'),
('kam', 'JHN', 2, 19, 'Yesũ amasũngĩa, amea, Anangai ĩkalũ yĩĩ, na mĩthenya ĩtatũ ngayĩũngamya.'),
('kam', 'JHN', 2, 20, 'Na ĩndĩ mamwĩa, Ĩkalũ yĩĩ yaminie myaka mĩongo ĩna na thanthatũ yĩkyakwa, naku ũkayĩũngamya na mĩthenya ĩtatũ?'),
('kam', 'JHN', 2, 21, 'Ĩndĩ we awetie ĩkalũ ya mwĩĩ wake.'),
('kam', 'JHN', 2, 22, 'Na ĩndĩ yĩla wathayũũkiw’e kuma akw’ũnĩ, amanyĩw’a make malilikana kana amatavisye ũu; na meetĩkĩla ũla ũandĩko, na ĩla ndeto yaneeniwe nĩ Yesũ.'),
('kam', 'JHN', 2, 23, 'Na yĩla waĩ Yelusaleme ĩvinda ya vasaka, mbokanĩ, aingĩ meetĩkĩla syĩtwa yake, moona syama syake ila wekie.'),
('kam', 'JHN', 2, 24, 'Ĩndĩ Yesũ ndaayĩĩkĩĩthya kwamo, nũndũ nĩwesĩ andũ onthe,'),
('kam', 'JHN', 2, 25, 'na nũndũ ndaĩ na vata wa mũndũ kũmũtavya ũndũ wa mũndũ; nũndũ we mwene nĩwesĩ ũndũ wĩ nthĩnĩ wa mũndũ.'),
('kam', 'JHN', 3, 1, 'Kwaĩ mũndũ wa Avalisi, wetawa Nikotemo, na aĩ mũnene ũmwe wa Ayuti:'),
('kam', 'JHN', 3, 2, 'ũsu ookie kwa Yesũ na ũtukũ, na amwĩa, Lavai, nĩtwĩsĩ kana wĩ mũmanyĩsya ũla wumĩte kwa Ngai; nũndũ kũi mũndũ ũtonya kwĩka syama ii ila wĩkaa, Ngai ate vamwe nake.'),
('kam', 'JHN', 3, 3, 'Yesũ amũsũngĩa, amwĩa, Nĩ w’o, nĩ w’o, nĩngũkwĩa, Keka mũndũ ũsyawa kuma ĩũlũ, ndatonya kwona ũsumbĩ wa Ngai.'),
('kam', 'JHN', 3, 4, 'Nikotemo amwĩa, Mũndũ atonya ata kũsyawa e mũkũũ? Nũtonya kũvota ĩngĩ ya kelĩ ĩvunĩ ya nyinyia, akasyawa?'),
('kam', 'JHN', 3, 5, 'Yesũ amũsũngĩa, Nĩ w’o, nĩ w’o, nĩngũkwĩa, Keka mũndũ ũsyawa nĩ manzĩ na Veva, ndatonya ũvota ũsumbĩnĩ wa Ngai.'),
('kam', 'JHN', 3, 6, 'Kĩla kĩsyaĩtwe nĩ mwĩĩ nĩ mwĩĩ; na kĩla kĩsyaĩtwe nĩ Veva nĩ veva.'),
('kam', 'JHN', 3, 7, 'Ndũkaseng’e nũndũ nakwĩa, Mũvaka mũsyawe kuma ĩũlũ.'),
('kam', 'JHN', 3, 8, 'Kĩseve nĩkĩuutanaa o kũla kĩkwenda, naku nĩwĩw’aa wasya wakyo, ĩndĩ ndwĩsĩ kũla kyumaa, na kũla kĩendaa: nĩw’o wĩthĩawa ũla ũsyaĩtwe nĩ Veva.'),
('kam', 'JHN', 3, 9, 'Nikotemo amũsũngĩa, amwĩa, Maũndũ aa mekĩkaa ata?'),
('kam', 'JHN', 3, 10, 'Yesũ amũsũngĩa, amwĩa, We wĩ mũmanyĩsya wa Isilaeli, na ndwĩsĩ maũndũ aa?'),
('kam', 'JHN', 3, 11, 'Nĩ w’o, nĩ w’o, nĩngũkwĩa, Ithyĩ nĩtũneenaa ũndũ ũla twĩsĩ, na nĩtũkũsĩĩaa ũla twoonie; na mũtikwĩtĩkĩla ũkũsĩ witũ.'),
('kam', 'JHN', 3, 12, 'Ethĩwa namũtavya maũndũ ma nthĩ na mũtiũmetĩkĩla mũkeetĩkĩla ata ngĩmũtavya maũndũ ma ĩtunĩ?'),
('kam', 'JHN', 3, 13, 'Na vai mũndũ waambata ĩtunĩ, no ũla watheeie kuma ĩtunĩ, nake nĩ Mwana wa mũndũ, ũla wĩ ĩtunĩ.'),
('kam', 'JHN', 3, 14, 'Na o tondũ Mose wokĩlilye ĩla nzoka weũnĩ, mũvaka Mwana wa mũndũ okĩlw’e ta ũu:'),
('kam', 'JHN', 3, 15, 'nĩ kana o ũla ũmwĩtĩkĩlaa ethĩwe na thayũ ũtathela.'),
('kam', 'JHN', 3, 16, 'Nũndũ Ngai nĩwendete nthĩ, nĩwanenganie Mwana wake e ũmwe, nĩ kana o ũla ũmwĩtĩkĩlaa ndakae, ĩndĩ ethĩwe na thayũ ũtathela.'),
('kam', 'JHN', 3, 17, 'Nũndũ Ngai ndaamũtũma Mwana wake kũũ nthĩ asilĩle nthĩ; ĩndĩ nĩ kana nthĩ ĩtangĩĩwe nĩwe.'),
('kam', 'JHN', 3, 18, 'Ũla ũmwĩtĩkĩlaa ti mũsilĩle: ĩndĩ ũla ũteũmwĩtĩkĩla nĩ mũsilĩle o na yu, nũndũ ndanetĩkĩla syĩtwa ya Mwana wa Ngai ũla wasyaiwe e weka.'),
('kam', 'JHN', 3, 19, 'Na ũũ nĩw’o ũsilĩlo, nũndũ kyeni nĩ kyũku kĩkalika kũũ nthĩ, na andũ nĩmendie kĩvindu kũte kyeni; nũndũ mawĩa moo maĩ mathũku.'),
('kam', 'JHN', 3, 20, 'Nũndũ kĩla mũndũ wĩkaa naĩ amenaa kyeni, na ndokaa kyeninĩ, mawĩa make maikakanw’e.'),
('kam', 'JHN', 3, 21, 'Ĩndĩ ũla wĩkaa w’o okaa kyeninĩ, mawĩa make monanw’e, kana mekĩtwe nthĩnĩ wa Ngai.'),
('kam', 'JHN', 3, 22, 'Ĩtina wa maũndũ aa Yesũ na amanyĩw’a make maendie nthĩ ya Yutia; na nĩkw’o wekalile vamwe nao, akĩvatisa.'),
('kam', 'JHN', 3, 23, 'Na Yoana nake nĩwavatisĩaa vandũ vetawa Ainoni vakuvĩ na Salimu, nũndũ vaĩ manzĩ maingĩ vo: na andũ maendaa vo, makavatiswa.'),
('kam', 'JHN', 3, 24, 'Nũndũ Yoana ndaĩ aneekĩwa kolokolonĩ.'),
('kam', 'JHN', 3, 25, 'Nĩvo ĩndĩ kwookĩla ngananĩo sya amanyĩw’a ma Yoana na Mũyuti ũmwe ũndũ wa wĩthesyo.'),
('kam', 'JHN', 3, 26, 'Na mathi kwa Yoana, na mamwĩa, Lavai, ũla waĩ naku mũingo ũya wa Yolotani, ũla wamũkũsĩĩaa, sisya, nake nũvatisaa, na andũ onthe maendaa kũla ũĩ.'),
('kam', 'JHN', 3, 27, 'Yoana asũngĩa, asya Mũndũ ndatonya kwosa ũndũ, atanengetwe kuma ĩtunĩ.'),
('kam', 'JHN', 3, 28, 'Inyw’ĩ ene nĩmũngũsĩĩaa, kana naisye, Tii nyie Klĩsto, ĩndĩ nĩtũmĩtwe mbee wake.'),
('kam', 'JHN', 3, 29, 'Ũla wĩ na mũtwawa nĩwe mũtwaani: ĩndĩ mũnyanyae wa mũtwaani, ũla ũũngeme na kũmwĩthukĩĩsya, nũtanaa mũno nũndũ wa wasya wa mũtwaani: kwondũ wa ũu ũtanu wakwa nĩwusũĩte.'),
('kam', 'JHN', 3, 30, 'Mũvaka we aneneve, nakwa nĩnyive.'),
('kam', 'JHN', 3, 31, 'Ũla ũnũkũka kuma ĩũlũ e ĩũlũ wa onthe: ũla wa nthĩ, ũsu nĩ mũndũ wa nthĩ, na aneenaa maũndũ ma nthĩ; ũla ũnũkũka kuma ĩtunĩ, ũsu e ĩũlũ wa onthe.'),
('kam', 'JHN', 3, 32, 'Na maũndũ ala wonie na wewie nĩmo ũkũsĩĩaa; na vai mũndũ wosaa ũkũsĩ wake.'),
('kam', 'JHN', 3, 33, 'Ũla wosete ũkũsĩ wake, ũsu ekĩĩte ũsiĩlo wake atĩ Ngai nĩ wa w’o.'),
('kam', 'JHN', 3, 34, 'Nũndũ ũla ũtũmĩtwe nĩ Ngai, ũsu aneenaa ndeto sya Ngai: nũndũ Ngai ndanenganae ũla Veva kwa ũthima.'),
('kam', 'JHN', 3, 35, 'Ũla Asa nũmwendete Mwana, na nĩwamũnengie maũndũ onthe kw’okonĩ kwake.'),
('kam', 'JHN', 3, 36, 'Ũla wĩtĩkĩlaa ũ Mwana e na thayũ ũtathela; ĩndĩ ũla ũtamwĩtĩkĩlaa Mwana ndakona thayũ, ĩndĩ ũthatu wa Ngai wĩkalaa ĩũlũ wake.'),
('kam', 'JHN', 4, 1, 'Na ĩndĩ yĩla Mwĩaĩi wamanyie kana Avalisi nĩmewie ũndũ Yesũ wamatw’ĩkĩthasya andũ amanyĩw’a na kũvatisa aingĩ kũvĩta Yoana.'),
('kam', 'JHN', 4, 2, '(Ĩndĩ ti Yesũ mwene wavatisaa, ĩndĩ nĩ amanyĩw’a make),'),
('kam', 'JHN', 4, 3, 'auma Yutia, na athi ĩngĩ Kalilii.'),
('kam', 'JHN', 4, 4, 'Nake ndaatĩa kũvĩtĩla Samalĩa.'),
('kam', 'JHN', 4, 5, 'Nĩvo ĩndĩ wakinyĩle ndũa ĩmwe ya Samalia, yĩtawa Saikale, vakũvĩ na kĩlungu kya nthĩ kĩla Yakovo wamũnengie mwana wake Yosevu:'),
('kam', 'JHN', 4, 6, 'na kĩthima kya Yakovo kyaĩ vo. Na ĩndĩ Yesũ, aĩ ananoa nĩ ũthi, ekala kĩthimanĩ. Na kwaĩ ta mũthenya katĩ.'),
('kam', 'JHN', 4, 7, 'Na mũndũ mũka wa Samalia ooka atave manzĩ: Yesũ amwĩa, Nenga nĩnyw’e.'),
('kam', 'JHN', 4, 8, 'Nũndũ amanyĩw’a make maĩ manathi ndũanĩ mathooe lĩu.'),
('kam', 'JHN', 4, 9, 'Ũla mũndũ mũka Mũsamalia amũkũlya, Kũilyĩ ata, we, wĩ Mũyuti, ũũmbĩtya manzĩ ma ũnyw’a, nakwa nĩ mũndũ mũka Mũsamalia? (Nũndũ Ayuti na ala ma Samalia maivulanaa.)'),
('kam', 'JHN', 4, 10, 'Yesũ amũsũngĩa na amwĩa. Kethĩwa nĩwĩsĩ mũthĩnzĩo wa Ngai, na ũla ũnũũkwĩa, Nenga nĩnyw’e; kethĩwa nĩwamwĩtya we, nake ethĩwa akũnenga manzĩ ma thayũ.'),
('kam', 'JHN', 4, 11, 'Mũndũ mũka amwĩa, Mwĩaĩi, ndwĩ na kya ũtava nakyo, na kĩthima nĩ kĩliku: ĩndĩ wumĩtye va manzĩ asu ma thayũ?'),
('kam', 'JHN', 4, 12, 'We, wĩ mũnene mbee wa asa waitũ Yakovo, ũla watũnengie kĩthima kĩĩ, na anyusaa makyo, we, na ana make, na indo syake?'),
('kam', 'JHN', 4, 13, 'Yesũ asũngĩa na amwĩa, O mũndũ ũla ũnyusaa manzĩ aa akeew’a waũni ĩngĩ:'),
('kam', 'JHN', 4, 14, 'ĩndĩ o ũla ũnũũnyw’a manzĩ ala nĩmũnenga ndakew’a waũni ĩngĩ o na ĩndĩĩ; ĩndĩ ala manzi nĩmũnenga makatw’ĩka kĩthima kya manzĩ nthĩnĩ wake, makĩvulutya ngoonĩ kũvika thayũ ũtathela.'),
('kam', 'JHN', 4, 15, 'Ũla mũndũ mũka amwĩa, Mwĩaĩi, nenga manzĩ asu, kana ndikew’e waũni ĩngĩ, o na ndikoke kũũ kũtava.'),
('kam', 'JHN', 4, 16, 'Yesũ amwĩa, Enda, ũkamwĩte mũemeu, wũke nake vaa.'),
('kam', 'JHN', 4, 17, 'Mũndũ mũka asũngĩa na amwĩa, Ndi mũũme. Yesũ amwĩa, Waneena w’o, Ndi mũũme:'),
('kam', 'JHN', 4, 18, 'nũndũ aũme ala waĩ namo maĩ atano; na ũla wĩ nake yu ti mũemeu: ũu waneena w’o.'),
('kam', 'JHN', 4, 19, 'Mũndũ mũka amwĩa, Mwĩaĩi, nĩngwona wĩ mwathani.'),
('kam', 'JHN', 4, 20, 'Aaĩthe maitũ mathaithĩaa kĩĩmanĩ kĩĩ; na inyw’ĩ mwĩasya kana Yelusaleme nĩvo vaĩle kũthaithĩwa.'),
('kam', 'JHN', 4, 21, 'Yesũ amwĩa, Mbĩtĩkĩla, kĩveti, saa nĩwũkĩte, yĩla inyw’ĩ mũtakathaithĩa Asa kĩĩmanĩ kĩĩ, o na Yelusaleme.'),
('kam', 'JHN', 4, 22, 'Inyw’ĩ mũthaithaa kĩla mũtesĩ: ithyĩ tũthaithaa kĩla twĩsĩ; nũndũ ũtangĩĩo wumaa kwa Ayuti.'),
('kam', 'JHN', 4, 23, 'Ĩndĩ saa nĩwũkĩte, na wĩ vo yu, yĩla athaithi ala ma w’o makamũthaitha Asa nthĩnĩ wa veva, na nthĩnĩ wa w’o: nũndũ Asa emantha ta asu mamũthaithae.'),
('kam', 'JHN', 4, 24, 'Ngai nĩ Veva: na ala mamũthaithaa mũvaka mamũthaithae nthĩnĩ wa veva na nthĩnĩ wa w’o.'),
('kam', 'JHN', 4, 25, 'Ũla mũndũ mũka amwĩa, Nĩnĩsĩ kana Masia nĩwũkĩte (ũla wĩtawa Klĩsto): nake ooka, akatũtavya maũndũ onthe.'),
('kam', 'JHN', 4, 26, 'Yesũ amwĩa, Ninyie we ũla ũnũũneena naku.'),
('kam', 'JHN', 4, 27, 'Na kavinda kau amanyĩw’a make mooka; na maseng’a nũndũ nũnũũneena na mũndũ mũka; ĩndĩ vaiaĩ ũmwe waamwĩa, Wĩmantha kyaũ? Kana, Wĩneenea nake kĩ?'),
('kam', 'JHN', 4, 28, 'Na ĩndĩ mũndũ mũka atia kĩkuu, kyake na aenda ndũanĩ, na amea andũ,'),
('kam', 'JHN', 4, 29, 'Ũkai, mwone mũndũ wandavya maũndũ onthe ala neekie: ũsu tiwe Klĩsto?'),
('kam', 'JHN', 4, 30, 'Na ĩndĩ mauma ndũanĩ, maendete vala ũĩ.'),
('kam', 'JHN', 4, 31, 'Na ĩvinda yĩu amanyĩw’a make mamũingĩĩsya, maimwĩa, Lavai, ya.'),
('kam', 'JHN', 4, 32, 'Ĩndĩ nake amea, Lĩu nĩ naw’o wa ũya ũla mũtawĩsĩ.'),
('kam', 'JHN', 4, 33, 'Na amanyĩw’a make mambĩlĩlya ũkũlan’ya ene kwa ene, No kwĩthĩwa mũndũ amũetee lĩũ?'),
('kam', 'JHN', 4, 34, 'Yesũ amea, Lĩu wakwa nĩ kwĩka kwenda kwa ũla wandũmie, na kũminũkĩlya wĩa wake.'),
('kam', 'JHN', 4, 35, 'Inyw’ĩ mũtyaasya, Kũtiele myei ĩna, na ngetha ĩivika? Sisyai, nĩngũmwĩa, Ũngalalyai metho menyu, mũsisye mĩũnda, kana nĩ mĩathĩku kũvika ũkethwa o na yu.'),
('kam', 'JHN', 4, 36, 'Ũla ũkethaa nĩwosaa ĩtuvi, na akyũmban’ya ũsyao kũvika thayũ ũtathela; nĩ kana ũla ũvuĩaa na ũla ũkethaa matane vamwe.'),
('kam', 'JHN', 4, 37, 'Na kwa ũu ndeto ĩtw’ĩkĩte ya w’o Ũmwe nũvũĩaa, na ũngĩ aiketha.'),
('kam', 'JHN', 4, 38, 'Nĩnamũtũmie mũkakethe kũla mũtaatethya wĩa: ala matethisye nĩ angĩ, na inyw’i mwavota mĩnoonĩ yoo.'),
('kam', 'JHN', 4, 39, 'Na Asamalia aingĩ ma ndũa ĩsu mamwĩtĩkĩla nũndũ wa ndeto sya mũndũ mũka kũmatavya, Andavisye maũndũ onthe ala neekie.'),
('kam', 'JHN', 4, 40, 'Na Asamalia mathĩ vala ũĩ, mamũingĩĩsya ekale nao: na ekala kw’o mĩthenya ĩlĩ.'),
('kam', 'JHN', 4, 41, 'Na angĩ aingĩ meetĩkĩla nũndũ wa ndeto syake;'),
('kam', 'JHN', 4, 42, 'na mamwĩa ũla mũndũ mũka, Yu nĩtũkwĩtĩkĩla, na ti ũndũ wa kũneena kwaku: nũndũ nĩtwĩyĩw’ĩe ene, na twanamya w’o kana ũũ nĩwe Mũtangĩĩi wa nthĩ.'),
('kam', 'JHN', 4, 43, 'Na matukũ elĩ mathela auma kw’o, athĩ Kalilii.'),
('kam', 'JHN', 4, 44, 'Nũndũ Yesũ mwene aisye kana mwathani ndataĩawa nthĩ ĩla yoo.'),
('kam', 'JHN', 4, 45, 'Na avika Kalilii, Akalilii mamwosa, nĩkwĩthĩwa nĩmoonete maũndũ onthe ala wekie Yelusaleme mbokanĩ: nũndũ nao nĩmaendie mbokanĩ.'),
('kam', 'JHN', 4, 46, 'Na ĩndĩ athi ĩngĩ Kena, nthĩ ya Kalilii, kũla waalyũlile manzĩ mbinyu. Na Kavelinaumi kwaĩ mũnene ũmwe, wawaĩtye mwana.'),
('kam', 'JHN', 4, 47, 'Na eew’a kana Yesũ nĩwumĩte Yutia akoka Kalilii, aenda vala ũĩ, na amwĩsũva kana atheee kwake, akamũvosye mwana wake; nũndũ aĩ vakuvĩ kũkw’a.'),
('kam', 'JHN', 4, 48, 'Na ĩndĩ Yesũ amwĩa, Keka mũkwona syama na moseng’yo mũtyĩtĩkĩla nongi.'),
('kam', 'JHN', 4, 49, 'Ũla mũnene amwĩa, Mwĩaĩi, theea, mwana wakwa atanakw’a.'),
('kam', 'JHN', 4, 50, 'Yesũ amwĩa. Thi; mwana waku e thayũ. Na ũla mũndũ eetĩkĩla ndeto ĩla Yesũ wamũtavya, na aenda.'),
('kam', 'JHN', 4, 51, 'Na atheeete, ngombo syake syamũthaũa, na syamũtavya kana mwana wake e thayũ.'),
('kam', 'JHN', 4, 52, 'Na ĩndĩ aikũlya saa ũla ũnambĩlĩlye ũvoa. Na syamwĩa, Ĩoo saa mũonza ndetema ĩnamũtiie.'),
('kam', 'JHN', 4, 53, 'Na ĩthe amanya kana nĩ saa ũla Yesũ ũnamwĩie, Mwana waku e thayũ: nake eetĩkĩla, na onthe ala ma nyũmba yake.'),
('kam', 'JHN', 4, 54, 'Na kyama kyu nĩkyo kya kelĩ, kĩla Yesũ wekie aumĩte Yutia, aithi Kalilii.'),
('kam', 'JHN', 5, 1, 'Na ĩtina wa maũndũ asu kwaĩ mboka ya Ayuti; na Yesũ ambata Yelusaleme.'),
('kam', 'JHN', 5, 2, 'Na Yelusaleme, vakuvĩ na mbingĩlo ya malondu, ve ndia, Kĩevelania yĩtawa Vethesita, yĩ na mavalasya atano.'),
('kam', 'JHN', 5, 3, 'Na nthĩnĩ wamo yekalaa nguthu nene ya andũ awau, ililinda, na ala mathuaa, na ala au mamutha, makyeteela manzĩ makwaithangw’e.'),
('kam', 'JHN', 5, 4, 'Nũndũ kyathĩ kyavika, mũlaĩka atheea ndianĩ ĩsu, na aikwaithangya manzĩ: na manzĩ makwaithangw’a o mũndũ ũla wambie ũvota ndianĩ aivow’a ũwau ũla wawaĩte.'),
('kam', 'JHN', 5, 5, 'Na vaĩ mũndũ ũmwe vo, wawaĩte ĩvinda ya myaka mĩongo ĩtatũ na nyanya.'),
('kam', 'JHN', 5, 6, 'Na Yesũ amwona amamĩte, nake nĩwesĩ kana ailyũ ũu ĩvinda ĩasa, amũkũlya, Nũkwenda ũvow’e?'),
('kam', 'JHN', 5, 7, 'Na ũla mũwau amũsũngĩa, Mwĩaĩi, ndi mũndũ wa ũndikya ndianĩ yĩla manzĩ meũkwaithangw’a: ĩndĩ yĩla ngũtheea nyie, mũndũ ũngĩ eĩthwa anamba ũlika kwĩ nyie.'),
('kam', 'JHN', 5, 8, 'Yesũ amwĩa, Ũkĩla, nokyosa ũkomo waku ũthi.'),
('kam', 'JHN', 5, 9, 'Na kavinda o kau, ũla mũndũ avow’a vyũ, na oosa ũkomo wake, na athi. Na mũthenya ũsu waĩ wa savato.'),
('kam', 'JHN', 5, 10, 'Na ĩndĩno Ayuti mamwĩa ũla ũvoiw’e, Mũnthĩ ũũ nĩ wa savato, na ndwosana na ĩla mĩao kũkua ũkomo waku.'),
('kam', 'JHN', 5, 11, 'Nake amea, Ũsu wambosya, nĩwe wambĩa, Kua ũkomo waku, ũthi.'),
('kam', 'JHN', 5, 12, 'Na mamũkũlya, Mũndũ ũsu nũũ ũla wakwĩa, Kua ũkomo waku, ũthi?'),
('kam', 'JHN', 5, 13, 'Na ũla wavoiw’e ndeesĩ ũla ũmũvoisye; nũndũ Yesũ nĩwevetie vau, nũndũ vaĩ nguthu nene.'),
('kam', 'JHN', 5, 14, 'Na ĩtina Yesũ amũwĩla ĩkalũnĩ, na amwĩa, Sisya, nũnavoiw’e: ndũkeke naĩ ĩngĩ, ũndũ ũthũku kwĩ ũũ ndũkaũkwate.'),
('kam', 'JHN', 5, 15, 'Na ũla mũndũ athi, na amea ala Ayuti kana nĩ Yesũ ũla ũnamũvoisye.'),
('kam', 'JHN', 5, 16, 'Na kwondũ wa ũu Ayuti mamũthĩn’ya Yesũ, nũndũ nũneekie maũndũ asu mũthenya wa savato.'),
('kam', 'JHN', 5, 17, 'Ĩndĩ Yesũ amasũngĩa, Kũvika na yu Asa wakwa nũtethasya wĩa, nakwa nĩngũtethya.'),
('kam', 'JHN', 5, 18, 'Kwondũ wa ũu Ayuti mathĩng’ĩĩsya kũmantha ũmũaa, nũndũ ndaananga savato w’oka, ĩndĩ eetie Ngai Ĩthe wake, ethĩwe eyĩanen’ye na Ngai.'),
('kam', 'JHN', 5, 19, 'Nĩvo ĩndĩ Yesũ wamasũngĩie, amea, Nĩ w’o nĩ w’o, nĩngũmwĩa, Ũla Mwana ndatonya kwĩka ũndũ e we mwene, ate o ũla wonaa Ĩthe akĩka: nũndũ maũndũ o na meva ala wĩkaa we, nĩmo Mwana wĩkaa o ta ũu.'),
('kam', 'JHN', 5, 20, 'Nũndũ Ĩthe nũmwendete ũ Mwana, na amwonasya maũndũ onthe ala wĩkaa: na akamwon’ya mawĩa manene kwĩ aa, nĩ kana mũseng’e.'),
('kam', 'JHN', 5, 21, 'Nũndũ o ũndũ Ĩthe nũthayũũkasya akw’ũ akamanenga thayũ, no ta ũu Mwana nake nũmanengae thayũ o ala ũnũkwenda.'),
('kam', 'JHN', 5, 22, 'Nũndũ Ĩthe ndasilĩlaa mũndũ, ĩndĩ anengete Mwana ũsili w’onthe;'),
('kam', 'JHN', 5, 23, 'nĩ kana onthe mamũtaĩae Mwana, o ũndũ mamũtaĩaa Ĩthe. Ũla ũtamũtaĩaa ũla Mwana, ũsu ndataĩaa Ĩthe ũla wamũtũmie.'),
('kam', 'JHN', 5, 24, 'Nĩ w’o, nĩ w’o, nĩngũmwĩa, Ũla wĩw’aa ndeto yakwa, na ũmwĩtĩkĩlaa ũla wandũmie, e na thayũ ũtathela, na ndakalika ũsilĩlonĩ; ĩndĩ nũvĩtĩte kuma kĩkw’ũnĩ na kũlika thayũnĩ.'),
('kam', 'JHN', 5, 25, 'Nĩ w’o, nĩ w’o, nĩngũmwĩa, Saa nĩwũkĩte, o na yu nĩ mũviku, yĩla akw’ũ makew’a wasya wa Mwana wa Ngai; na ala mekwĩw’a makeethĩwa na thayũ.'),
('kam', 'JHN', 5, 26, 'O ũndũ Ĩthe wĩ na thayũ nthĩnĩ wake mwene, nĩw’o ũnengete ũla Mwana ethĩwe na thayũ nthĩnĩ wake mwene:'),
('kam', 'JHN', 5, 27, 'na amũnengete ũkũmũ wa ũsilĩla, nũndũ nĩwe Mwana wa mũndũ.'),
('kam', 'JHN', 5, 28, 'Mũikaseng’e kwondũ wa ũu: nũndũ saa nĩwũkĩte, yĩla onthe ala me mbũanĩ makew’a wasya wake,'),
('kam', 'JHN', 5, 29, 'namo makauma; ala meekie moseo, kwa ũthayũũkyo wa thayũ; na ala meekie mothũku, kwa ũthayũũkyo wa ũsilĩlo.'),
('kam', 'JHN', 5, 30, 'Nyie nĩ nyioka nditonya kwĩka ũndũ: ũndũ ũla nĩw’aa, nĩw’o ngũsila: na kũtw’a kwakwa nĩ kwa katĩ; nũndũ ndimanthaa kwenda kwakwa, no kwenda kwa ũla wandũmie.'),
('kam', 'JHN', 5, 31, 'Ethĩwa nĩngwĩkũsĩĩa mwene, ũkũsĩ wakwa ti wa w’o.'),
('kam', 'JHN', 5, 32, 'Nĩ ũngĩ ũla ũngũsĩĩaa; na nĩnĩsĩ kana ũkũsĩ ũla ũngũsĩĩaa nĩ wa w’o.'),
('kam', 'JHN', 5, 33, 'Nĩmwatũmanie kwa Yoana, nake akũsĩĩa ũla w’o.'),
('kam', 'JHN', 5, 34, 'Ĩndĩ ũkũsĩ ũla nosaa ti kuma kwa mũndũ: ĩndĩ nĩngũneena maũndũ aa, nĩ kana mũtangĩĩwe.'),
('kam', 'JHN', 5, 35, 'Nĩwe waĩ taa mwakanu ũla wakenaa; na inyw’ĩ mweetĩkĩla kũtanĩa nthĩnĩ wa kyeni kyake kavinda kanini.'),
('kam', 'JHN', 5, 36, 'Ĩndĩ ũkũsĩ ũla nĩ naw’o nĩ mũnene kũvĩta ũla wa Yoana; nũndũ mawĩa ala Asa ũnengete nimamine, mawĩa o asu ala ngwĩka, nĩmo mangũsĩĩaa, kana Asa nũndũmĩte.'),
('kam', 'JHN', 5, 37, 'Na Asa ũla wandũmie, nĩwangũsĩĩe. Inyw’ĩ mũtyaawĩw’a wasya wake o na ĩndĩĩ kana kwona mũvw’ano wake.'),
('kam', 'JHN', 5, 38, 'Na mũi na ndeto yake ĩtwĩe nthĩnĩ wenyu: nũndũ ũla ũtũmĩtwe nĩwe, mũtiũmwĩtĩkĩla.'),
('kam', 'JHN', 5, 39, 'Mwĩmantha maandĩkonĩ, nũndũ mwĩasya mwĩ na thayũ ũtathela nthĩnĩ wamo; na nĩmo mangũsĩĩaa;'),
('kam', 'JHN', 5, 40, 'na mũtyĩtĩkĩla kũka vala nĩĩ, mũnengwe thayũ.'),
('kam', 'JHN', 5, 41, 'Ndyosaa ndaĩa kwa andũ.'),
('kam', 'JHN', 5, 42, 'Ĩndĩ nĩnĩmwĩsĩ inyw’ĩ kana mũi na wendo wa Ngai nthĩnĩ wenyu.'),
('kam', 'JHN', 5, 43, 'Nũkĩte syĩtwanĩ ya Asa, na mũĩũmbosa: ethĩwa ũngĩ akooka syĩtwanĩ yake mwene, mũkamwosa.'),
('kam', 'JHN', 5, 44, 'Mũtonya kwĩtĩkĩla ata, inyw’ĩ ala mwosaniaa ndaĩa ene kwa ene, na ndaĩa ĩla yumaa kwa Ngai ũla ũmwe mũtiũmĩmantha?'),
('kam', 'JHN', 5, 45, 'Mũikasye atĩ ngamũvinganĩsya kwa Asa: ve ũla ũmũvinganĩasya inyw’ĩ, nake nĩ Mose, ũla mwĩkwatasya.'),
('kam', 'JHN', 5, 46, 'Nũndũ kethĩwa nĩmwamwĩtĩkĩlile Mose, mwĩthĩwa mũmbĩtĩkĩlĩte nyie; nũndũ nĩwaandĩkie ũvoo wakwa.'),
('kam', 'JHN', 5, 47, 'Ĩndĩ ethĩwa mũtyĩtĩkĩla maandĩko make, mũkeetĩkĩla ndeto syakwa ata?'),
('kam', 'JHN', 6, 1, 'Ĩtina wa maũndũ asu Yesũ athi mũingo ũla ũngĩ wa ũkanga wa Kalilii, naw’o nĩ ũkanga wa Tivelia.'),
('kam', 'JHN', 6, 2, 'Na avikĩlwa nĩ andũ nguthu nene, nũndũ nĩmoonie syama ila wekaa ala maĩ awau.'),
('kam', 'JHN', 6, 3, 'Na Yesũ ambata kĩĩmanĩ, na ekala vo na amanyĩw’a make.'),
('kam', 'JHN', 6, 4, 'Na vasaka, ĩla mboka ya Ayuti, yaĩ vakuvĩ.'),
('kam', 'JHN', 6, 5, 'Na ĩndĩ Yesũ ookĩlya metho make, oona nguthu nene ĩkyũka vala ũĩ, amwĩa Vilivu, Twĩthooa imũtũ va, kana aa maye?'),
('kam', 'JHN', 6, 6, 'Aneenaa ũu aimũtata: nũndũ we mwene nĩwesĩ ũndũ ũkilĩlye kwĩka.'),
('kam', 'JHN', 6, 7, 'Vilivu amũsũngĩa, Imũtũ sya silingi maana elĩ itimeanĩa, o na ethĩwa kĩla mũndũ akosa Kanini.'),
('kam', 'JHN', 6, 8, 'Ũmwe wa amanyĩw’a make, Andalea, mwana‐a‐inyia wa Simoni Vetelo, amwĩa,'),
('kam', 'JHN', 6, 9, 'Vaa ve kavĩsĩ, ke na imũtũ itano sya mbaale na makũyũ elĩ: ĩndĩ isu nĩ syĩndũ myaũ vala ve andũ meanou?'),
('kam', 'JHN', 6, 10, 'Yesũ asya, Ĩkalyai andũ nthĩ. Na vaĩ nyeki mbingĩ vala maĩ. Na ĩndĩ aũme mekala nthĩ, ũtalo woo waĩ ta ngili itano.'),
('kam', 'JHN', 6, 11, 'Na ĩndĩ Yesũ oosa ila imũtũ; na atũnga mũvea, amaaĩa andũ ala mailyĩ nthĩ; na makũyũ o ta ũu o ũndũ mendie.'),
('kam', 'JHN', 6, 12, 'Na mavũna, amea amanyĩw’a make, Ũmban’yai motialo ma ilungu ila ndile, vatikae kindũ.'),
('kam', 'JHN', 6, 13, 'Na kwondũ wa ũu moomban’ya, na mausũsya ikavũ ĩkũmi na ilĩ na ilungu ila ndile sya imũtũ itano sya mbaale, ila syamatialĩle ala maĩe.'),
('kam', 'JHN', 6, 14, 'Na ĩndĩ andũ moona kyama kyu Yesũ weka, masya, Nĩ w’o, ũũ nĩ mwathani ũla wũkĩte kũũ nthĩ.'),
('kam', 'JHN', 6, 15, 'Na ĩndĩ Yesũ amanya kana makilyĩ kũka mamũtwae na vinya, makamũtw’ĩkĩthye mũsumbĩ, eeveta aenda ĩngĩ kĩĩmanĩ e weka.'),
('kam', 'JHN', 6, 16, 'Ĩndĩ kwavika wĩoo. Amanyĩw’a make matheea ũkanganĩ;'),
('kam', 'JHN', 6, 17, 'na malika ngalawanĩ, mainganĩsye ũkanga mathi Kavelinaumi. Na kwaĩ kũnatuka, na Yesũ ndaĩ anamba ũvika vala maĩ.'),
('kam', 'JHN', 6, 18, 'Na ũkanga waĩ ũkyũkilangw’a nũndũ wa kĩseve kĩnene kĩiuutana.'),
('kam', 'JHN', 6, 19, 'Na maĩ manatwaa ngalawa maĩli atatũ kana ana, moona Yesũ akinyĩle ũkanganĩ ĩũlũ, akĩthengeea ngalawanĩ: na makwatwa nĩ w’ĩa mũnene.'),
('kam', 'JHN', 6, 20, 'Nake amea, Ninyie; mũikakĩe.'),
('kam', 'JHN', 6, 21, 'Na kwa ũu meetĩkĩla alike ngalawanĩ: na ĩvinda yĩu ngalawa yavika nthĩ ĩla maendaa.'),
('kam', 'JHN', 6, 22, 'Na ũnĩ ũsu ĩkomano yĩũngamĩte mũingo ũla ũngĩ wa ũkanga yoonie kana kũi kakalawa kangĩ, ate o kamwe, na Yesũ ndaneelika na amanyĩw’a make ngalawanĩ, ĩndĩ amanyĩw’a manalikile me oka'),
('kam', 'JHN', 6, 23, '(ĩndĩ kwookie tũkalawa tũngĩ tũmĩte Tivelia vakuvĩ na vala manaĩĩe imũtũ ĩtina wa Mwĩaĩi atũnga mũvea):'),
('kam', 'JHN', 6, 24, 'na ĩndĩ andũ ma ĩkomano moona kana Yesũ nde vo, o na amanyĩw’a make, namo malika tũkalawanĩ, na mathi Kavelinaumi makĩmũmantha Yesũ.'),
('kam', 'JHN', 6, 25, 'Na mamwona e mũingo ũngĩ wa ũkanga, mamwĩa, Lavai, wũkie vaa ĩndĩĩ?'),
('kam', 'JHN', 6, 26, 'Yesũ amasũngĩa, amea, Nĩ w’o, nĩ w’o, ningũmũtavya, Mũiũmantha nũndũ mũnoonie syama, ĩndĩ nũndũ mũnaĩe imũtũ, mũnavũna.'),
('kam', 'JHN', 6, 27, 'Mũikathũkũmĩae lĩu ũla wanangĩkaa, ĩndĩ lĩu ũla wĩkalaa kũvika thayũ ũtathela, ũla Mwana wa mũndũ wĩmũnenga: nũndũ we ekĩĩtwe ũsiĩlo nĩ Ngai Asa.'),
('kam', 'JHN', 6, 28, 'Na kwondũ wa ũu mamwĩa, Twĩĩka ata ĩndĩ, kana twĩkae mawĩa ma Ngai?'),
('kam', 'JHN', 6, 29, 'Yesũ amasũngĩa, amea, Ũũ nĩw’o wĩa wa Ngai, mũmwĩtĩkĩle ũla watũmiwe nĩwe.'),
('kam', 'JHN', 6, 30, 'Na ĩndĩ mamwĩa, Wĩĩka kyama kĩva, nĩ kana twone, tũkwĩtĩkĩle? Wĩĩka ũndũ mwaũ?'),
('kam', 'JHN', 6, 31, 'Aasa maitũ nĩmaĩe lĩu wĩtawa mana weũnĩ; o ũndũ kũandĩkĩtwe, Amanengie imũtũ syumĩte ĩtunĩ maye.'),
('kam', 'JHN', 6, 32, 'Yesũ amea, Nĩ w’o, nĩ w’o, nĩngũmwĩa, Ti Mose wamũnengie imũtũ syumĩte ĩtunĩ; ĩndĩ Asa wakwa nĩwe ũmũnengae kĩmũtũ kĩla kya w’o kyumĩte ĩtunĩ.'),
('kam', 'JHN', 6, 33, 'Nũndũ kĩmũtũ kya Ngai nĩ kĩla kĩtheeaa kuma ĩtunĩ, na kĩnengae nthĩ thayũ.'),
('kam', 'JHN', 6, 34, 'Na ĩndĩ mamwĩa, Mwĩaĩi, mavinda onthe tũnengae kĩmũtũ kyu.'),
('kam', 'JHN', 6, 35, 'Yesũ amea, Nyie, ninyie kĩmũtũ kya thayũ: ũla wũkaa kwakwa ndakew’a nzaa, na ũla ũmbĩtĩkĩlaa ndakew’a waũni o na ĩndĩĩ.'),
('kam', 'JHN', 6, 36, 'Ĩndĩ namwĩa, nĩmũmbonete na mũtiĩtĩkĩla.'),
('kam', 'JHN', 6, 37, 'Kyonthe kĩla Asa ũnengae nĩkyũkaa kwakwa; na ũla wũkaa kwakwa ndikamwĩkya nza nongi.'),
('kam', 'JHN', 6, 38, 'Nũndũ ndyaatheea kuma ĩtunĩ nĩke kwenda kwakwa, ĩndĩ no kwenda kwa ũla wandũmie.'),
('kam', 'JHN', 6, 39, 'Na kũũ nĩkw’o kwenda kwa ũla wandũmie, nĩ kana kyonthe kĩla wanengie ndikaasye kĩndũ o na kĩmwe, ĩndĩ ngakĩthayũũkya mũthenya wa mũmĩnũkĩlyo.'),
('kam', 'JHN', 6, 40, 'Nũndũ kũũ nĩkw’o kwenda kwa Asa wakwa, kana kĩla mũndũ ũmũsiasya Mwana, na ũmwĩtĩkĩlaa, ethĩwe na thayũ ũtathela; nakwa ngamũthayũũkya mũthenya wa mũminũkĩlyo.'),
('kam', 'JHN', 6, 41, 'Kwondũ wa ũu Ayuti mamũnyungunyĩĩsya, nũndũ aisye, Nyie, ninyie kĩmũtũ kĩla kyatheeie kuma ĩtunĩ.'),
('kam', 'JHN', 6, 42, 'Namo masya, Ũũ ti Yesũ, mwana wa Yosevu, na ĩthe na nyinyia tũimesĩ? Easya ata yu, Nĩnatheeie kuma ĩtunĩ?'),
('kam', 'JHN', 6, 43, 'Yesũ amasũngĩa, amea, Ekai ũnyungunyĩsya katĩ wenyu.'),
('kam', 'JHN', 6, 44, 'Vai mũndũ ũtonya kũka kwakwa, ateũkusw’a nĩ Asa ũla wandũmie: nakwa ngamũthayũũkya mũthenya wa mũminũkĩlyo.'),
('kam', 'JHN', 6, 45, 'Nĩkũandĩkĩtwe maandĩkonĩ ma athani, Namo onthe makamanyĩw’a nĩ Ngai. Kĩla mũndũ wewie kuma kwa Asa, na akemanyĩsya, ũsu okaa kwakwa.'),
('kam', 'JHN', 6, 46, 'Ti atĩ ve mũndũ waamwona Asa, ate o ũla waumie kwa Ngai, nĩwe wamwonie Asa.'),
('kam', 'JHN', 6, 47, 'Nĩ w’o, nĩ w’o, nĩngũmwĩa, Ũla wĩtĩkĩlaa e na thayũ ũtathela.'),
('kam', 'JHN', 6, 48, 'Nyie, ninyie kĩmũtũ kya thayũ.'),
('kam', 'JHN', 6, 49, 'Aaĩthe menyu mĩmaĩe lĩu ũla wĩtawa mana me weũnĩ, na makw’a.'),
('kam', 'JHN', 6, 50, 'Kĩĩ nĩkyo kĩmũtũ kĩla kĩtheeete kuma ĩtunĩ, kya mũndũ kũya, na ndakw’a.'),
('kam', 'JHN', 6, 51, 'Nyie, ninyie kĩmũtũ kĩ thayũ kĩla kyatheeie kuma ĩtunĩ: ethĩwa mũndũ o na wĩva nũnũũya kĩmũtũ kyu, akeethĩwa na thayũ tene na tene: ĩĩ, na kĩmũtũ kĩla nganengane nĩ nyama ya mwĩĩ wakwa, kwondũ wa thayũ wa nthĩ.'),
('kam', 'JHN', 6, 52, 'Na ĩndĩ Ayuti makananĩa ene kwa ene, makyasya, Mũndũ ũũ atonya ata kũtũnenga nyama ya mwĩĩ wake tũkaya?'),
('kam', 'JHN', 6, 53, 'Nĩvo ĩndĩ Yesũ wameie, Nĩ w’o, nĩ w’o, nĩngũmwĩa, Mũteũya nyama ya mwĩĩ wa Mwana wa mũndũ na kũmĩnyw’a nthakame yake, mũi na thayũ nthĩnĩ wenyu.'),
('kam', 'JHN', 6, 54, 'Ũla ũnũũya nyama yakwa na kũnyw’a nthakame yakwa e na thayũ ũtathela; nakwa ngamũthayũũkya mũthenya wa mũminũkĩlyo.'),
('kam', 'JHN', 6, 55, 'Nũndũ nyama ya mwĩĩ wakwa nĩ lĩu wa w’o, na nthakame yakwa nĩ kya ũnyw’a kya w’o.'),
('kam', 'JHN', 6, 56, 'Ũla ũnũũya nyama ya mwĩĩ wakwa na kũnyw’a nthakame yakwa, ũsũ ekalaa nthĩnĩ wakwa, nakwa nthĩnĩ wake.'),
('kam', 'JHN', 6, 57, 'O tondũ Asa ũla wĩ thayũ wandũmie, na nikalaa thayũ kwondũ wa Asa; o ta ũu ũla ũnũũndya akekalaa thayũ kwondũ wakwa.'),
('kam', 'JHN', 6, 58, 'Kĩĩ nĩkyo kĩmũtũ kĩla kyatheeie kuma ĩtunĩ: ti tondũ aaĩthe menyu maĩe, na makw’a; ũla ũnũũya kĩmũtũ kĩĩ akekala thayũ tene na tene.'),
('kam', 'JHN', 6, 59, 'Ndeto ii aneenee ĩsinakokenĩ, akĩmanyĩsya Kavelinaumi.'),
('kam', 'JHN', 6, 60, 'Na ĩndĩ aingĩ ma amanyĩw’a make meew’a ũu, masya, Ndeto ĩno nĩ nyũmũ; ũla ũtonya ũmĩw’a nũũ?'),
('kam', 'JHN', 6, 61, 'Ĩndĩ Yesũ amanya nthĩnĩ wake kana amanyĩw’a make nĩmeũnyungunyĩsya kwondũ wayo, amakũlya, Ndeto ĩno nĩnĩũmũlulutĩkya?'),
('kam', 'JHN', 6, 62, 'Nata ĩndĩ ethĩwa mũkoona Mwana wa mũndũ akyambata kũla waĩ mbee?'),
('kam', 'JHN', 6, 63, 'Na veva ũla ũnengae thayũ; mwĩĩ ndũtandĩthya kĩndũ: ndeto ila nĩneenete nenyu nĩsyo veva, na nĩsyo thayũ.'),
('kam', 'JHN', 6, 64, 'Ĩndĩ katĩ wenyu kwĩ amwe matekwĩtĩkĩla, Nũndũ kuma mwambĩlĩlyonĩ Yesũ nĩwesĩ ala matekwĩtĩkĩla, na ũla ũkamũvũnyanĩa.'),
('kam', 'JHN', 6, 65, 'Na amea, Kwondũ wa ũu namwĩa, kana kũi mũndũ ũtonya kũka kwakwa, atanengetwe nĩ Asa.'),
('kam', 'JHN', 6, 66, 'Kwondũ wa ũu amanyĩw’a make aingĩ masyoka na ĩtina, na matyaathi nake ĩngĩ.'),
('kam', 'JHN', 6, 67, 'Na ĩndĩ Yesũ amakũlya aia ikũmi na elĩ, Nenyu nĩmũkwenda ũthi?'),
('kam', 'JHN', 6, 68, 'Simoni Vetelo amũsũngĩa, Mwĩaĩi, tũende kwaũ? Nue wĩ na ndeto sya thayũ ũtathela.'),
('kam', 'JHN', 6, 69, 'Naitũ nĩtwĩtĩkĩlĩte na nĩtwisĩ kana wĩ Ũla Mũtheu wa Ngai.'),
('kam', 'JHN', 6, 70, 'Yesũ amasũngia, Ndyaamũnyuva inyw’ĩ ĩkũmi na elĩ, na ũmwe wenyu nĩ wa Satani?'),
('kam', 'JHN', 6, 71, 'Amũwetaa Yutasi, mwana wa Simoni Isikalioti, nũndũ nĩwe ũkamũvũnyanĩa, nake aĩ ũmwe wa ala ĩkũmi na elĩ.'),
('kam', 'JHN', 7, 1, 'Na ĩtina wa maũndũ asu Yesũ angangaa Kalilii: nũndũ ndendaa kwanganga Yutia, nũndũ Ayuti nĩmamanthaa kũmũaa.'),
('kam', 'JHN', 7, 2, 'Na mboka ya Ayuti, ĩla ya kwaka malwanda, yaĩ vakuvĩ.'),
('kam', 'JHN', 7, 3, 'Na ana‐a‐inyia mamwĩa, Uma vaa ũthi Yũtia, nĩ kana amanyĩw’a maku nao mone mawĩa maku ala wĩkaa.'),
('kam', 'JHN', 7, 4, 'Nũndũ kũi mũndũ wĩkaa ũndũ avithĩte, akyenda amanyĩke nĩ andũ. Ethĩwa nũkwika mawĩa aa, iyonan’ye kwa nthi.'),
('kam', 'JHN', 7, 5, 'Nũndũ o na ana‐a‐inyia make maiamwĩtĩkĩlĩte.'),
('kam', 'JHN', 7, 6, 'Kwondũ wa ũu Yesũ amea, Ĩvinda yakwa yĩinamba ũvika; indi ĩvinda yenyu ni ĩviku mavinda onthe.'),
('kam', 'JHN', 7, 7, 'Nthĩ nditonya ũmũmena inyw’i; ĩndĩ nyie ninĩũmena, nũndũ nyie nĩnĩmĩkũsĩiaa, kana mawĩa mayo nĩ mathe.'),
('kam', 'JHN', 7, 8, 'Ambataiinyw’i mũthi mbokanĩ: ndikwambata oyu mbokanĩ ĩno; nũndũ ĩvinda yakwa yĩinamba kwĩanĩa.'),
('kam', 'JHN', 7, 9, 'Na amatavya maũndũ asu, ekalanga Kalilii.'),
('kam', 'JHN', 7, 10, 'Ĩndĩ yĩla ana‐a‐inyia maĩ manambata mbokanĩ, o nake ambata, ti kwa kwĩyumĩlya, ĩndĩ kwa kĩmbithĩ.'),
('kam', 'JHN', 7, 11, 'Na Ayuti meethĩwa makĩmũmantha mbokanĩ, makyasya, Aĩva we?'),
('kam', 'JHN', 7, 12, 'Na kwaĩ mũnyungunyĩsyo mũnene katĩ wa makomano nũndũ wake: amwe masya, Nĩ mũndũ mũseo; na angĩ masya, Ti w’o, nũnũkwasya andũ aingĩ.'),
('kam', 'JHN', 7, 13, 'Ĩndĩ vai mũndũ waneenaa ũvoo wake aumĩlĩtye vyũ nĩ kũmakia Ayuti.'),
('kam', 'JHN', 7, 14, 'Na ĩvinda ya mboka yavika katĩ, Yesũ ambata avota ĩkalũnĩ, na amanyĩsya.'),
('kam', 'JHN', 7, 15, 'Na Ayuti maseng’a, makyasya, Mũndũ ũũ esĩ ata maũndũ ma mavuku, na ndaamanyĩw’a?'),
('kam', 'JHN', 7, 16, 'Kwa ũu Yesũ amasũngĩa, amea, Ũmanyĩsyo wakwa tĩ wakwa, ĩndĩ nĩ wa ũla wandũmie.'),
('kam', 'JHN', 7, 17, 'Ethĩwa mũndũ o na wĩva nĩwendaa kwĩka kwenda kwake, akamanya ũmanyĩsyo, ethĩwa nĩ wa Ngai, kana ethĩwa nĩneenaa kwondũ wakwa mwene.'),
('kam', 'JHN', 7, 18, 'Ũla ũneenaa ũndũ wake mwene emanthĩaa ndaĩa: ĩndĩ ũla ũmanthaa ndaĩa ya ũla wamũtũmie, ũsu nĩ wa w’o, na nthĩnĩ wake vaĩ ũndũ ũte ũlũngalu.'),
('kam', 'JHN', 7, 19, 'Ũla wamũnengie ĩla mĩao ti Mose? O na vai ũmwe wenyu ũla ũmĩkwataa ĩla mĩao. Nĩkĩ mũũmantha ũmbũaa?'),
('kam', 'JHN', 7, 20, 'Na yĩla ĩkomano yamũsũngĩa, Wĩ na ndaimoni we: nũũ ũla ũnũũmantha ũkũaa?'),
('kam', 'JHN', 7, 21, 'Yesũ asũngĩa, amea, Nĩnĩneekie wia ũmwe, na inyw’onthe nĩmũũseng’w’a niw’o.'),
('kam', 'JHN', 7, 22, 'Mose amũnengie nzaĩko (tĩ atĩ yaumie kwa Mose, ĩndĩ kwa aaĩthe); na inyw’ĩ nĩmũkwaĩka mũndũ mũthenya wa savato.'),
('kam', 'JHN', 7, 23, 'Ethĩwa mũndũ nũkwaĩkwa mũthenya wa savato, kana mĩao ya Mose ndĩkanangwe; mwĩnthatĩa nũndũ nĩnavoisye mũndũ aneethĩwa e mũima vyũ mũthenya wa savato?'),
('kam', 'JHN', 7, 24, 'Mũikasile mũkĩtalĩlya, ĩndĩ sĩlai sĩla wa katĩ.'),
('kam', 'JHN', 7, 25, 'Na ĩndĩ amwe ma Yelusaleme masya, Ũũ tiwe ũla meũmantha ũmũaa?'),
('kam', 'JHN', 7, 26, 'Indi sisyai, eneena ateũvitha, o na maiũmwĩa ũndũ. No kwĩthĩwa anene mesi vyũ kana ũũ nĩ Klĩsto?'),
('kam', 'JHN', 7, 27, 'Ĩndĩ nĩtwĩsĩ kũla mũndũ ũũ wumĩte: ĩndĩ yila Klĩsto ũkoka, vai ũkamanya kũla wumĩte.'),
('kam', 'JHN', 7, 28, 'Ĩndĩ Yesũ ookĩlya wasya e ĩkalũnĩ, akĩmanyĩsya na asya, Nĩmũmbĩsĩ, na ĩngĩ nĩmwĩsĩ vala naumie; na ndyaaũka kwondũ wakwa, ĩndĩ ũla wandũmie nĩ wa w’o, ũla mũtamwĩsĩ.'),
('kam', 'JHN', 7, 29, 'Nyie nĩnĩmwĩsĩ; nĩkwĩthĩwa naumie kwake, na nĩwe wandũmie.'),
('kam', 'JHN', 7, 30, 'Na ĩndĩ mamantha ũmũkwata: ĩndĩ vai mũndũ waamũtambũũkĩsya kw’oko, nũndũ saa wake ndwaĩ ũnamba ũvika.'),
('kam', 'JHN', 7, 31, 'Ĩndĩ andũ aingĩ ma ĩkomano mamwĩtĩkĩla; na masya, Yĩla Klĩsto ũkoka, nũkeka syama nyingĩ kũthonoka ila syĩkĩtwe nĩ mũndũ ũũ?'),
('kam', 'JHN', 7, 32, 'Na Avalisi meew’a andũ ma ĩkomano mainyungunyĩĩsya maũndũ asu nũndũ wake; na ala athembi anene na Avalisi matũma makanga nĩ kana mamũkwate.'),
('kam', 'JHN', 7, 33, 'Kwondũ wa ũu Yesũ asya, Vatiele ĩvĩnda ĩnini nĩ vamwe nenyu, na ngĩthi kwa ũla wandũmie.'),
('kam', 'JHN', 7, 34, 'Mũkamantha, na mũikambona: na vala nĩĩ, mũtitonya kũka.'),
('kam', 'JHN', 7, 35, 'Na kwondũ wa ũu Ayuti maneena ene kwa ene, Mũndũ ũũ akathi na kũ kũla tũtatonya kũmwona? Akathi kwa ala ma Ũnyaĩĩko ma Akiliki, amanyĩsye Akiliki?'),
('kam', 'JHN', 7, 36, 'Ũu nata ũkwasya, Mũkamantha, na mũikambona; na vala nĩĩ, mũtitonya kũka?'),
('kam', 'JHN', 7, 37, 'Na ĩndĩ mũthenya wa kũmina, mũthenya ũla mũnene wa mboka, Yesũ aũngama na aneena na wasya mũnene, akyasya, Ethĩwa mũndũ o na wĩva e na waũni, nĩoke kwakwa anyw’e.'),
('kam', 'JHN', 7, 38, 'Ũla ũnũũmbĩtĩkĩla, o ũndũ maandĩko maĩtye, nthĩnĩ wake kũkauma mbũsĩ sya manzĩ ma thayũ.'),
('kam', 'JHN', 7, 39, 'Na aneenaa ũu kwondũ wa ũla Veva, ũla makilĩlye kũnengwa ala mamwĩtkĩlĩte: nũndũ Veva ndaĩ anamba kũnenganwe; nũndũ Yesũ ndaĩ anamba kũtaĩwa.'),
('kam', 'JHN', 7, 40, 'Na amwe ma ĩkomano meew’a ndeto isu, masya, Nĩ w’o, ũũ nĩwe ũla mwathani.'),
('kam', 'JHN', 7, 41, 'Na angĩ masya, Ũũ nĩwe Klĩsto. Ĩndĩ angĩ masya, Ai! Klĩsto euma Kalilii?'),
('kam', 'JHN', 7, 42, 'Maandĩko maiaasya Klĩsto akauma ũsyaonĩ wa Ndaviti, na kuma ndũanĩ ya Mbethelemu, vala Ndaviti wekalaa?'),
('kam', 'JHN', 7, 43, 'Na kwa ũu kwaya ũtilĩkangano ĩkomanonĩ nũndũ wake.'),
('kam', 'JHN', 7, 44, 'Na amwe menda kũmũkwata; ĩndĩ vai mũndũ waamũtambũũkĩsya moko.'),
('kam', 'JHN', 7, 45, 'Nĩvo ala makanga mamaalũkĩla athembi anene na ala Avalisi; namo mamakũlya, Nĩkĩ mũtinamũete?'),
('kam', 'JHN', 7, 46, 'Na ala makanga mamasũngĩa, Vai mũndũ ũngĩ nongi waaneena ta ũsu.'),
('kam', 'JHN', 7, 47, 'Na ĩndĩ Avalisi mamasũngĩa, O nenyu ko mwaĩtw’e?'),
('kam', 'JHN', 7, 48, 'Ve ũmwe wa ala anene, kana wa Avalisi ũmwĩtĩkĩlĩte?'),
('kam', 'JHN', 7, 49, 'Ĩndĩ ĩkomano yĩĩ yĩtesĩ ĩla mĩao nĩumanĩe.'),
('kam', 'JHN', 7, 50, 'Nikotemo (nĩ ũla waendie kwake ĩngĩ, na no ũmwe wamo) amakũlya,'),
('kam', 'JHN', 7, 51, 'Mĩao yaitũ nĩsĩlĩlaa mũndũ, ĩtanamba ũmwĩw’a na kũmanya ũndũ wĩkaa?'),
('kam', 'JHN', 7, 52, 'Na mamũsũngĩa, mamwĩa, O naku wĩ wa Kalilii? Mantha, wone kana vaiuma mwathani Kalilii.'),
('kam', 'JHN', 7, 53, '(Na menũka kĩla mũndũ nyũmbanĩ kwake:'),
('kam', 'JHN', 8, 1, 'ĩndi Yesũ athi kĩĩmanĩ kya Mĩthata.'),
('kam', 'JHN', 8, 2, 'Na kĩoko tene avota ĩngĩ ĩkalũnĩ, na andũ onthe mathi vala ũĩ; nake ekala nthĩ, na amamanyĩsya.'),
('kam', 'JHN', 8, 3, 'Na aandĩki na Avalisi mamũetee mũndũ mũka wakwatiwe ũlaalaini; na mamũũngamya katĩ woo,'),
('kam', 'JHN', 8, 4, 'mamwĩa, Mũmanyĩsya, mũndũ mũka ũũ akitw’a akĩka ũlaalai.'),
('kam', 'JHN', 8, 5, 'Na mĩaonĩ Mose atwĩaĩe kũaa ta ũyũ na mavia: wĩasya ata ĩndĩ, we, ũndũ wake?'),
('kam', 'JHN', 8, 6, 'Na waasya ũu, makĩmũtata, mone ũndũ wa ũmũvinganĩsya naw’o. Ĩndĩ Yesũ akunama, na aandĩka nthĩ na kyaa kyake.'),
('kam', 'JHN', 8, 7, 'Na mathing’ĩĩsya kũmũkũlya, aũngalala, na amea, Ũla ũte na nai katĩ wenyu nĩambe kũmwĩkya ĩvia.'),
('kam', 'JHN', 8, 8, 'Na akunama ĩngĩ, na aandĩka nthĩ na kyaa kyake.'),
('kam', 'JHN', 8, 9, 'Namo, meew’a ũu, maumaala ũmwe na ũmwe, kwambĩlĩlya ala akũũ, kũvika, ala ma mũminũkĩlyo: na Yesũ atiwa e weka, na ũla mũndũ vala eĩĩ katĩ.'),
('kam', 'JHN', 8, 10, 'Na Yesũ aũngalala, na amwĩa, Mũndũ mũka, maĩva ala? Vai ũmwe ũnaũsilĩla?'),
('kam', 'JHN', 8, 11, 'Na amwĩa, Vai ũmwe, Mwĩaĩi. Na Yesũ amwĩa, O nakwa ndiũkũsilĩla: enda; na kuma yu ndũkaaĩke naĩ ĩngĩ.)'),
('kam', 'JHN', 8, 12, 'Na ĩndĩ Yesũ aneena namo ĩngĩ, akyasya, Nyie, ninyie kyeni kya nthĩ: ũla ũmbikĩlaa ndakakinya kĩvindunĩ, ĩndĩ akeethĩwa na kyeni kya thayũ.'),
('kam', 'JHN', 8, 13, 'Na ĩndĩ Avalisi mamwĩa, Nũkwĩkũsĩĩa mwene; ũkũsĩ waku ti wa w’o.'),
('kam', 'JHN', 8, 14, 'Yesũ amaswũngĩa na amea, O na ethĩwa nĩngwĩkũsĩĩa mwene, ũkũsĩ wakwa nĩ wa w’o; nũndũ nĩnĩsĩ kũla naumie, na kũla nĩthi: ĩndĩ inyw’ĩ mũtyĩsĩ kũla naumie, kana kũla nĩthi.'),
('kam', 'JHN', 8, 15, 'Inyw’ĩ mũsila kĩmwĩi; nyie ndisilĩlaa mũndũ.'),
('kam', 'JHN', 8, 16, 'Na ethĩwa nĩngũsila, kũsila kwakwa nĩ kwa w’o; nũndũ ndi nyioka, ĩndĩ nyie na Asa ũla wandũmie.'),
('kam', 'JHN', 8, 17, 'Na mĩaonĩ yenyu nĩkũandĩkĩtwe kana ũmũsĩ wa andũ elĩ nĩ wa w’o.'),
('kam', 'JHN', 8, 18, 'Nyie nĩngwĩkũsĩĩa mwene, na Asa ũla wandũmie, nake nũnũngũsĩĩa.'),
('kam', 'JHN', 8, 19, 'Na kwondũ wa ũu mamũkũlya, Au aĩva? Yesũ amasũngĩa, Mũimbĩsĩa, o na Asa mũimwĩsĩ: kethĩwa, nĩmũmbĩsĩ, nake Asa mwĩthĩw mũmwĩsĩ.'),
('kam', 'JHN', 8, 20, 'Ndeto ii aneenie e vala valekelaw’a mbesa, akĩmanyĩsya ĩkalũnĩ: na vai mũndũ waamũkwata; nũndũ saa wake ndwaĩ ũnamba ũvika.'),
('kam', 'JHN', 8, 21, 'Na ĩndĩ amatavya ĩngĩ Nyie nĩngũthi, nenyu mũkamantha, na mũkakw’a naĩnĩ yenyu: kũla nĩthi, mũtitonya kũka.'),
('kam', 'JHN', 8, 22, 'Na ĩndĩ Ayuti masya, Akeeyũaa mwene, nũndũ easya, Kũla nĩthi, mũtitonya kũka?'),
('kam', 'JHN', 8, 23, 'Na amea, Inyw’ĩ mwĩ ma ĩtheo; nyie nĩ wa ĩũlũ: inyw’ĩ mwĩ ma nthĩ ĩno; nyie ndi wa thaĩ ĩno.'),
('kam', 'JHN', 8, 24, 'Nũndũ wa ũu namwĩa, kana mũkakw’a naĩnĩ syenyu: nũndũ mwalea kwĩtĩkĩla kana ninyie we mũkakw’a naĩni syenyu.'),
('kam', 'JHN', 8, 25, 'Na ĩndĩ mamũkulya, We nue ũũ? Yesũ amea, No ũla namũtavasya kuma mwambĩlĩlyonĩ.'),
('kam', 'JHN', 8, 26, 'Nĩ na maũndũ maingĩ ma ũneena na ma ũsila ũndũ wenyu: ĩndĩ ũla wandũmie nĩ wa w’o; na maũndu ala neewie kwake, nĩmo nĩmĩtavasya nthĩ.'),
('kam', 'JHN', 8, 27, 'Natyaamanya kana emawetea Asa.'),
('kam', 'JHN', 8, 28, 'Na ĩndĩ Yesũ asya, Yĩla mwĩmũkĩlya ũla Mwana wa mũndũ, nĩw’o mũkamanya kana ninyie we, na ndyĩkaa ũndũ nũndũ wakwa, ĩndĩ no ũndũ Asa wamanyĩisye, nĩw’o nĩneenaa.'),
('kam', 'JHN', 8, 29, 'Na ũla wandũmie e wamwe nakwa; ndaandia nĩ nyioka; nũndũ mavinda onthe nĩkaa maũndũ ala mamwendeeasya.'),
('kam', 'JHN', 8, 30, 'Akĩneena ndeto isu, andũ angĩ mamwĩtĩkĩla.'),
('kam', 'JHN', 8, 31, 'Nĩvo ĩndĩ Yesũ wameie Ayuti ala Ethĩwa inyw’ĩ mũkekalaa w’o;'),
('kam', 'JHN', 8, 32, 'na mũkamanya ũla w’o, na ũla w’o ũkamũthasya.'),
('kam', 'JHN', 8, 33, 'Namo mamũsũngĩa, Twĩ ũsyao wa Avalaamu, tũiaamba kwĩthĩwa ngombo sya mũndũ o na wĩva: wĩasya ata ĩndĩ, aĩ, Mũkathaw’a?'),
('kam', 'JHN', 8, 34, 'Yesũ amasũngĩa, Nĩ w’o, nĩ w’o, nĩngũmwĩa, Kĩla mũndũ wĩkaa naĩ nĩ ngombo ya naĩ.'),
('kam', 'JHN', 8, 35, 'Na ngombo ndĩkalaa nyũmbanĩ mavinda onthe: mwana ekalaa mavind onthe.'),
('kam', 'JHN', 8, 36, 'Ethĩwa ũla Mwana akamũthasya, mũkethĩwa mwĩ athasye w’o.'),
('kam', 'JHN', 8, 37, 'Nĩnĩsĩ kana mwĩ ũsyao wa Avalaamu; ĩndĩ mwĩmantha ũmbũaa, nũndũ ndeto yakwa ndĩ na ũthei nthĩnĩ wenyu.'),
('kam', 'JHN', 8, 38, 'Nĩneenaa maũndũ ala noonie kwa Asa: o nenyu nĩmwĩkaa maũndũ ala mweewie kwa ĩthe wenyu.'),
('kam', 'JHN', 8, 39, 'Mamũsũngĩa na mamwĩa, Asa waitũ nĩ Avalaamũ. Yesũ amea, Kethĩwa mwĩ syana sya Avalaamu, mwĩthĩwa mũkĩka, mawĩa ma Avalaamu.'),
('kam', 'JHN', 8, 40, 'Ĩndĩ yu nĩmũũmantha kũmbũaa, mũndũ ũla ũmũtavĩtye w’o, ũla neewie kwa Ngai: Avalaamu ndaaĩka ũu.'),
('kam', 'JHN', 8, 41, 'Nĩmwĩkaa mawĩa ma ĩthe wenyu. Na mamwĩa, Ithyĩ tũtyaasyaĩwa ũlaalaini; twĩ na Asa ũmwe, nake nĩ Ngai.'),
('kam', 'JHN', 8, 42, 'Yesũ amea, Kethĩwa Ngai nĩ Ĩthe wenyu, mwithĩwa mũkĩmbenda: nũndũ naumie kwa Ngai na nooka; na ndyaaũka kwondũ wakwa, ĩndĩ nĩwe wandũmie.'),
('kam', 'JHN', 8, 43, 'Nĩ ũndũ wa kĩ mũteũmanya ũndũ ngũneena? Nũndũ mũtitonya kwĩw’a ndeto yakwa.'),
('kam', 'JHN', 8, 44, 'Ĩnyw’ĩ, mwĩ ma ĩthe wenyu ndevili, na wendi wa ĩthe wenyu nĩw’o mwendaa kwĩka. Aĩ mũaani kuma mwambĩlĩlyonĩ, na ndaaĩkala nthĩnĩ wa w’o, nũndũ nthinĩ wake vati w’o. Yĩla ũnũũneena ũvũngũ, eneena ũndũ wĩ naw’o: nũndũ nĩ mũneeni wa ũvũngũ, na nĩ ĩthe wa ũvũngũ.'),
('kam', 'JHN', 8, 45, 'Ĩndĩ nũndũ nĩneenaa w’o, mũtiũmbitikila.'),
('kam', 'JHN', 8, 46, 'Nũũ wenyu ũla ũkũsĩĩa ki kana nyie nĩ mwĩki wa naĩ? Ethĩwa nĩneenaa w’o, nĩkĩ mũtiũmbĩtĩkila?'),
('kam', 'JHN', 8, 47, 'Ũla wa Ngai nĩwĩw’aa ndeto sya Ngai: na kwondũ wa ũu mũtyĩw’aa, nũndũ mũi ma Ngai.'),
('kam', 'JHN', 8, 48, 'Ayuti mamũsũngĩa, mamwĩa, Tũtinaneena o w’o kana wĩ Mũsamalia, na wĩ na ndaimonĩ?'),
('kam', 'JHN', 8, 49, 'Yesũ amasũngĩa, Ndi na ndaimoni; ĩndĩ nĩmũtaĩa Asa wakwa, na inyw’ĩ mũiũndaĩa.'),
('kam', 'JHN', 8, 50, 'Nakwa ndĩĩmantha ndaĩa yakwa mwene: kwĩ ũmwe ũla ũkumantha na nowe ũtusaa.'),
('kam', 'JHN', 8, 51, 'Nĩ w’o, nĩw’o, nĩngũmwĩa. Ethĩwa mũndũ nũkwataa ndeto yakwa, ndakona kĩkw’ũ o na ĩndĩĩ.'),
('kam', 'JHN', 8, 52, 'Ayuti mamwĩa, Yu nĩtwamanya kana wĩ na ndaimoni. Avalaamu nĩwakwie, na athani; naku wĩasya, Ethĩwa mũndũ nũkwataa ndeto yakwa, ndakasama kĩkw’ũ o na ĩndĩĩ.'),
('kam', 'JHN', 8, 53, 'We, wĩ mũnene kwĩ asa waitũ Avalaamu, nake nĩwakwie? Na athani nĩmakwie: wĩĩtw’a ũũ?'),
('kam', 'JHN', 8, 54, 'Yesũ asũngĩa, Ethĩwa nĩĩtaĩa mwene, ndaĩa yakwa ti kĩndũ: nĩ Asa wakwa ũla ũnũũndaĩa; ũla inyw’ĩ mũkwasya, nĩ Ngai wenyu;'),
('kam', 'JHN', 8, 55, 'na inyw’ĩ mũiaamũmanya: ĩndĩ nĩnĩmwĩsĩ; na ethĩwa ngasya, Ndĩmwĩsĩ, ngeethĩwa mũneeni wa ũvũngũ tenyu: ĩndĩ nĩnĩmwĩsĩ na nĩngwataa ndeeya yake.'),
('kam', 'JHN', 8, 56, 'Ĩthe wenyu, Avalaamu, nĩwatanie nũndũ wa kwona mũthenya wakwa; na nĩwawonie, na atana.'),
('kam', 'JHN', 8, 57, 'Ĩndĩ Ayuti mamwĩa, Ndũnamba ũvikya myaka mĩongo ĩtano, na nĩwamwonie Avalaamũ?'),
('kam', 'JHN', 8, 58, 'Yesũ amatavya, Nĩ w’o, nĩ w’o, nĩngũmwĩa, Nĩ kw’o naĩ, Avalaamuatanamba ũsyawa.'),
('kam', 'JHN', 8, 59, 'Nĩvo ĩndĩ moosie mavia mamũkime: ĩndĩ Yesũ eevitha, na auma ĩkalũnĩ.'),
('kam', 'JHN', 9, 1, 'Na avĩtĩte, oona mũndũ e kĩlilinda kuma asyawa.'),
('kam', 'JHN', 9, 2, 'Na amanyĩw’a make mamũkũlya, makyasya, Lavai, ũla wekie naĩ nũũ, nĩ mũndũ ũũ, kana nĩ asyai make, kana asyawe kĩlilinda?'),
('kam', 'JHN', 9, 3, 'Yesũ amasũngĩa, Ũũ ndaaĩka naĩ, kana asyai make: ĩndĩ nĩ kana mawĩa ma Ngai monanw’e nthĩnĩ wake.'),
('kam', 'JHN', 9, 4, 'Mũvaka tũtethye mawĩa ma ũla wandũmie, kwĩ mũthenya: ũtukũ nĩwũkĩte, yĩla mũndũ ũtatonya kũtethya wĩa.'),
('kam', 'JHN', 9, 5, 'Ĩvinda yĩla nĩ kũũ nthĩ, nyie nĩ kyeni kya nthĩ.'),
('kam', 'JHN', 9, 6, 'Na aneena ũu, atw’ĩla mata nthĩ, na aulua kataka na mata, na amũvaka kala kataka metho,'),
('kam', 'JHN', 9, 7, 'na amwĩa, Thi, ũkathambe ndianĩ ya Siloami (ũalyũlo wayo nĩ, Kũtũmwa). Na ĩndĩ athi, athamba, na ooka akyona.'),
('kam', 'JHN', 9, 8, 'Na kwondũ wa ũu atũi, na ala mamwonaa tene, yĩla waĩ mũvoyi wa syĩndũ, masya, Ũũ ti ũla wekalaa nthĩ akĩvoya syĩndũ?'),
('kam', 'JHN', 9, 9, 'Angĩ masya, Nĩwe: na angĩ masya, Aiee, ĩndĩ avw’anene nake. Nake asya, Ninyie.'),
('kam', 'JHN', 9, 10, 'Na ĩndĩ mamũkũlya, Ũsalukilw’e ata metho maku?'),
('kam', 'JHN', 9, 11, 'Amasũngĩa, Mũndũ ũla wĩtawa Yesũ aulua kataka, na avaka metho makwa, na ambĩa, Enda ũkathambe Siloami: nakwa nathi nathamba, na nanengwa kwona.'),
('kam', 'JHN', 9, 12, 'Na mamũkũlya, Aĩva mũndũ ũsu? Asya, Ndyĩsĩ.'),
('kam', 'JHN', 9, 13, 'Na mamũtwaa kwa Avalisi ũsu waĩ kĩlilinda tene.'),
('kam', 'JHN', 9, 14, 'Na mũthenya ũsu waĩ wa savato yĩla Yesũ wauluile kataka, na amũsalukya metho.'),
('kam', 'JHN', 9, 15, 'Na kwondũ wa ũu Avalisi mamũkũlya ĩngĩ ũndũ wanengwa kwona. Na amea, Ambĩkĩie kataka metho, na nathamba, na nĩngwona.'),
('kam', 'JHN', 9, 16, 'Na ĩndĩ amwe ma Avalisi masya, Mũndũ ũũ ndaauma kwa Ngaĩ, nũndũ ndalilikanaa savato. Ĩndĩ angĩ masya, Mũndũ mwathe atonya ata kwĩka syama ta isu? Na kwaya ũtilĩkangano katĩ wamo.'),
('kam', 'JHN', 9, 17, 'Na ĩndĩ mamwĩa ĩngĩ ũla waĩ kĩlilinda, Wĩasya ata we ũndũ wake, nũndũ nũnaũsalukilye metho? Nake asya, Nĩ mwathani.'),
('kam', 'JHN', 9, 18, 'Ĩndĩ Ayuti maiaaĩtĩkĩla ũvoo wake, kana aĩ kĩlilinda, na anegwa kwona, mũvaka makũlya asyai ma ũla ũnanengiwe kwona,'),
('kam', 'JHN', 9, 19, 'na mamakũlya, makyasya, Ũũ nĩwe mwana wenyu, ũla mwaasya asyaiwe e kĩlinda? Eona ata ĩndĩ yu?'),
('kam', 'JHN', 9, 20, 'Asyai make masũngĩa, masya Nĩtwĩsĩ kana ũũ nĩ mwana waitũ, na asyaiwe e kĩlilinda:'),
('kam', 'JHN', 9, 21, 'ĩndĩ kĩla kĩtumaa ona yu, tũtikĩsĩ; na tũiĩsĩ ũla ũnamũsalukilye metho: mũkũlyei we; nĩ mũndũ mũima, akeneenea.'),
('kam', 'JHN', 9, 22, 'Asyai make maisye ũu, nũndũ nĩmakĩaa Ayuti: nũndũ Ayuti maĩ mananeena makew’ana, kana ethĩwa mũndũ akasya nĩwe Klisto, ũsu akalũngw’a ĩsinakokenĩ.'),
('kam', 'JHN', 9, 23, 'Kwondũ wa ũu asyai make masya, Nĩ mũima: mũkũlyei we.'),
('kam', 'JHN', 9, 24, 'Na ĩndĩ mamwĩta ũla mũndũ wai kĩlilinda, ĩngĩ ya kelĩ, na mamwĩa, Mũnenge Ngai ndaĩa: nĩtwĩsĩ kana mũndũ ũsu nĩ mwathe.'),
('kam', 'JHN', 9, 25, 'Ĩndĩ nake asũngĩa, Ethĩwa nĩ mwathe, ndyĩsĩ: nĩsĩ ũndũ o ũmwe, kana nyie naĩ kĩlilinda, ĩndĩ yu nĩngwona.'),
('kam', 'JHN', 9, 26, 'Na ĩndĩ mamũkũlya, Anakwĩkie ata? Anakũsalukilye metho ata?'),
('kam', 'JHN', 9, 27, 'Amasũngĩa, Namũtavya oyu, na mũinew’a; nũndũ wa kĩ mũkwenda kwĩw’a ĩngĩ? O nenyu nĩmũkwenda kũtw’ĩka amanyĩw’a make?'),
('kam', 'JHN', 9, 28, 'Na ĩndĩ mamũuma, makyasya, We, wĩ mũmanyĩw’a wake; ĩndĩ ithyĩ twĩ amanyĩw’a ma Mose.'),
('kam', 'JHN', 9, 29, 'Nĩtwĩsĩ kana Ngai nĩwaneenie na Mose: ĩndĩ tũtyisi vala mũndũ ũũ wumite.'),
('kam', 'JHN', 9, 30, 'Ũla mũndũ amasũngĩa, amea, Ai! Ũndũ ũũ nĩ ũseng’yo, atĩ mũtyĩsĩ kũla wumĩte, na nĩwe ũnzalukilye metho makwa.'),
('kam', 'JHN', 9, 31, 'Nĩtwĩsĩ kana Ngai ndamew’aa andũ athe: ethĩwa mũndũ o na wĩva ni mũthaithi wa Ngai, na aiĩkaa kwenda kwake, ũsu nũmwĩw’aa.'),
('kam', 'JHN', 9, 32, 'Kuma mwambĩlĩlyonĩ kũiaaĩw’ĩka kana ve mũndũ waasalukya ũngĩ metho, asyaĩtwe e kĩlilinda.'),
('kam', 'JHN', 9, 33, 'Kethĩwa ũsu ndaumĩte kwa Ngai, ndanaĩ atonya kwĩka ũndũ.'),
('kam', 'JHN', 9, 34, 'Na mamũsũngĩa, mamwĩa, We wasyaĩwe naĩnĩ ki, na nũũtũmanyĩsya ithyĩ? Na mamwĩkya nza.'),
('kam', 'JHN', 9, 35, 'Na Yesũ eew’a kana nĩmamwĩkisye nza; na amwona, asya, Nũmwĩtĩkĩla Mwana wa Ngai?'),
('kam', 'JHN', 9, 36, 'Amũsũngĩa, asya, Nake nũũ, Mwĩaĩi, nĩ kana nĩmwĩtĩkĩle?'),
('kam', 'JHN', 9, 37, 'Yesũ amwĩa, Nĩwamwona, na nĩwe ũũ ũla ũnũũneena naku.'),
('kam', 'JHN', 9, 38, 'Na asya, Mwĩaĩi, nĩngwĩtĩkĩla. Na amũthaitha.'),
('kam', 'JHN', 9, 39, 'Na Yesũ asya, Ninookie kũũ nthĩ kwondũ wa ũsilĩlo, nĩ kana ala matonaa mone; na ala monaa matw’ĩke ililinda.'),
('kam', 'JHN', 9, 40, 'Na amwe ma Avalisi ala maĩ nake meew’a ndeto isu, na mamũkũlya, O naitũ twĩ ililanda?'),
('kam', 'JHN', 9, 41, 'Yesũ amea, Kethĩwa mwĩ ililinda, mũthĩwĩi na naĩ: Indĩ yu mwĩasya, Nĩtũkwona: naĩ yenyu mwĩ nayo.'),
('kam', 'JHN', 10, 1, 'Nĩ w’o, nĩ w’o, nĩngũmwĩa, Ũla ũtavotelaa mũomonĩ wa vala malondu mekalaa, ĩndĩ aikĩlĩla vangi, ũsu nĩ kĩng’ei na mũvutani.'),
('kam', 'JHN', 10, 2, 'Ĩndĩ ũla ũvotelaa mũomonĩ nĩwe mũĩthi wa malondu.'),
('kam', 'JHN', 10, 3, 'Mũsũvĩi wa mũomonĩ nũmũvĩngũĩaa ũsu; na malondunĩmew’aa wasya wake: kĩla ilondu na syĩtwa yayo, na nũmatongoeasya, nza.'),
('kam', 'JHN', 10, 4, 'Na amaumaalya onthe ala make, nũmatongoeasya na malondu makĩmũvikĩla: nũndũ nĩmesĩ wasya wake.'),
('kam', 'JHN', 10, 5, 'Na maivikĩlaa mũeni, nĩ maimũkĩa: nĩkwĩthĩwa matyĩsĩ wasya wa aeni.'),
('kam', 'JHN', 10, 6, 'Yesũ amaelekanĩlya na ngelekan’yo ĩno: ĩndĩ maiaamanya maũndũ ala wamatavya.'),
('kam', 'JHN', 10, 7, 'Na ĩndĩ Yesũ amea ĩngĩ, Nĩ w’o, nĩ w’o, nĩngũmwĩa, Nyie, ninyie mũomo wa malondu.'),
('kam', 'JHN', 10, 8, 'Onhe ala mambie kũka mbee wakwa nĩ ing’ei na nĩ avutani: ĩndĩ malondu maiaamew’a.'),
('kam', 'JHN', 10, 9, 'Nyie, ninyie mũomo; ũla ũnũũvotela vala nĩĩ, ũsu akatangĩĩwa, na akavota nthĩnĩ na akaumaala, na akoona kya ũya.'),
('kam', 'JHN', 10, 10, 'Kĩng’ei kĩtyũkaa, ate o kana kyũye, na kũaa, na kwananga: nyie nĩnookie kana methĩwe na thayũ, na ĩngĩ methĩwe naw’o mwingĩ.'),
('kam', 'JHN', 10, 11, 'Nyie, ninyie mũithi ũla mũseo: mũĩthi mũseo nũnũũwia thayũ wake nthĩ ũndũ wa malondu.'),
('kam', 'JHN', 10, 12, 'Mũndũ wa ũtuvwa, na tiwe mũĩthĩ, na malondut i make, oona nzũi yũkĩte, nũtiaa malondu, akakĩa, na nzũi ĩkĩmakwata, na ĩkĩmanyaĩĩkya:'),
('kam', 'JHN', 10, 13, 'akĩaa nũndũ nĩ mũndũ wa ũtuvwa, na ndeũsũanĩa malondu.'),
('kam', 'JHN', 10, 14, 'Nyie, ninyie mũĩthi ũla mũseo; na ala makwa mwene nĩnĩmesĩ, na nĩmambĩsĩ ala makwa mwene,'),
('kam', 'JHN', 10, 15, 'o ũndũ Asa ũmbĩsĩ, nakwa nĩnĩmwĩsĩ Asa; na nĩngwia thayũ wakwa nthĩ ũndũ wa malondu.'),
('kam', 'JHN', 10, 16, 'Nakwa nĩ na malondu angĩ mate ma ĩĩthya yĩĩ: asu namo nditĩa ũmaete, na makew’a wasya wakwa; na makatw’ĩka ma ĩĩthya yĩmwe, na mũĩthi ũmwe.'),
('kam', 'JHN', 10, 17, 'Kwondũ wa ũu Asa nũmbendete, nũndũ nĩngwia thayũ wakwa nthĩ, nĩ kana nĩwose ĩngĩ.'),
('kam', 'JHN', 10, 18, 'Vai mũndũ ũnũũmbena thayũ, ĩndĩ no nyie ngũwia nthĩ. Nĩ na ũkũmũ wa kũwia nthĩ, na nĩ na ũkũmũ wa kũwosa ĩngĩ. Mwĩao ũũ noosie kwa Asa wakwa.'),
('kam', 'JHN', 10, 19, 'Na kwookĩla ĩngĩ ũtilĩkangano katĩ wa Ayuti nũndũ wa ndeto isu.'),
('kam', 'JHN', 10, 20, 'Na aingĩ moo masya, E na ndaimoni, na nũnũkũũũka; mwĩmwĩw’ĩa kĩ?'),
('kam', 'JHN', 10, 21, 'Angĩ masya, Ndeto isu ti sya mũndũ wĩ na ndaimoni. Ndaimoni nĩtonya kũsalukya ililinda metho?'),
('kam', 'JHN', 10, 22, 'Na kwaĩ mboka ya kũlilikana ũthesyo wa ĩkalu, kũya Yelusaleme: na yaĩ ĩvinda ya mbevo;'),
('kam', 'JHN', 10, 23, 'na Yesũ angangaa ĩkalũnĩ valasyanĩ wa Solomoni.'),
('kam', 'JHN', 10, 24, 'Na ĩndĩ Ayuti mamũthyũlũlũka, na mamwĩa, Wĩtũsaanĩsya ĩvinda yĩana ata? Ethĩwa nue Klĩsto tũtavye nesa.'),
('kam', 'JHN', 10, 25, 'Yesũ amasũngĩa, Nĩnamũtavisye, na mũtikwĩtĩkĩla: mawĩa ala nĩkaa syĩtwanĩ ya Asa, nimo mangũsĩĩaa.'),
('kam', 'JHN', 10, 26, 'Ĩndĩ mũtikwĩtĩkĩla, nũndũ mũi ma malondu makwa.'),
('kam', 'JHN', 10, 27, 'Malondu makwa nĩmew’aa wasya wakwa, nakwa nĩnĩmesĩ, nao nĩmeũmbikĩla:'),
('kam', 'JHN', 10, 28, 'nakwa nĩngũmanenga thayũ ũthathela; na maĩkaa o na ĩndĩĩ, na kũi mũndũ ũkambena kw’okonĩ kwakwa.'),
('kam', 'JHN', 10, 29, 'Asa wakwa, ũla wanengie, nĩ mũnene mbee wa onthe; na kũ mũndũ ũtonya kũmavenana maume kw’okonĩ kwa Asa.'),
('kam', 'JHN', 10, 30, 'Nyie na Asa twĩ ũmwe.'),
('kam', 'JHN', 10, 31, 'Na Ayuti moosa mavia ĩngĩ mamũkime.'),
('kam', 'JHN', 10, 32, 'Yesũ amasũngĩa, Nimwonetye mawĩa maseo maingĩ kũma kwa Asa; nũndũ wa wĩva wa asu ũla mũũngimĩa na mavia?'),
('kam', 'JHN', 10, 33, 'Ayuti mamũsũngĩa, Tũiũkũkima na mavia nũndũ wa wĩa mũseo, ĩndĩ nũndu ũkuuma Ngai; na nũndũ we, wĩ mũndũ, wĩĩtw’ĩkĩthya Ngai.'),
('kam', 'JHN', 10, 34, 'Yesũ amasũngĩa, Kũiandĩkĩtwe mĩanoĩ yenyi, Nyie naisye, Mwĩ nagĩ?'),
('kam', 'JHN', 10, 35, 'Ethĩwa nĩwametie ngai, ala maetewe ndeto ya Ngai (na maandĩko maitonya kũtũlwa),'),
('kam', 'JHN', 10, 36, 'mwĩneenea ũla wavathaniw’e na watũmiwe kũũ nthĩ nĩ Ĩthe, Nũkũumana; nũndũ nĩnaisye, Nĩ Mwana wa Ngai?'),
('kam', 'JHN', 10, 37, 'Ethĩwa ndyĩkaa mawĩa ma Asa wakwa, mũikambĩtĩkĩle.'),
('kam', 'JHN', 10, 38, 'Ĩndĩ ethĩwa nĩngũmeka, o na ethĩwa mũtiũmbĩtĩkĩla, metĩkĩlei mawĩa: nĩ kana mũmanya na mũmanyae vyũ kana Asa e nthĩni wakwa, nakwa nĩ nthĩnĩ wa Asa.'),
('kam', 'JHN', 10, 39, 'Na meethĩwa makĩmantha ĩngĩ kũmũkwata: na auma mokonĩ moo.'),
('kam', 'JHN', 10, 40, 'Na athi ĩngĩ mũingo wa ũsĩ wa Yolotani vala Yoana wavatisĩaa ĩvinda ya mbee; na ekala vo.'),
('kam', 'JHN', 10, 41, 'Na aingĩ mathi vala ũĩ, maĩasya, Yoana ndaaĩka kyama: ĩndĩ maũndũ onthe ala maneeniwe nĩ Yoana ũndu wa mũndu ũũ maĩ ma w’o.'),
('kam', 'JHN', 10, 42, 'Na aingĩ mamwĩtĩkĩlĩla kũu.'),
('kam', 'JHN', 11, 1, 'Kwaĩ mũndũ ũmwe mũwau, wetawa Lasalo, wa mũsyĩ wa Vethania, vala Meli na mwĩĩtu‐a‐inyia Matha matwĩe.'),
('kam', 'JHN', 11, 2, 'Nĩ Meli ũsu ũla wamũvakie Mwĩaĩi mauta me mũuke mũseo, na aimũnyasya maũũ make na nzw’ĩĩ syake, na nĩ mwana‐a‐inyia wake Lasalo ũla waĩ mũwau.'),
('kam', 'JHN', 11, 3, 'Nũndũ wa ũu eĩtũ‐a‐inyia mamũtũmana, makyasya, Mwĩaĩi, sisya, ũla wendete nĩ mũwau.'),
('kam', 'JHN', 11, 4, 'Na Yesũ eew’a ũu, asya, Ũwau ũsu ti wa kĩkw’ũ, ĩndĩ nĩ kana Ngai ataĩwe na nĩ kana Mwana wa Ngai ataĩwe nũndũ waw’o.'),
('kam', 'JHN', 11, 5, 'Na Yesũ nĩwamwendete Matha, na mwĩĩtu‐a‐inyia, na Lasalo.'),
('kam', 'JHN', 11, 6, 'Na eew’a kana nĩ mũwau, amba kwĩkala vo vala waĩ mĩthenya ĩngĩ ĩlĩ.'),
('kam', 'JHN', 11, 7, 'Nĩvo ĩndĩ ĩtina wa ũu wameie amanyĩw’a, Tũthii ĩngĩ Yutia.'),
('kam', 'JHN', 11, 8, 'Amanyĩw’a manwĩa, Lavai, oyu mĩtũkĩ Ayuti nĩmanamanthaa kũũkima na mavia; na wĩthi kw’o ĩngĩ?'),
('kam', 'JHN', 11, 9, 'Yesũ asũngĩa, Masaa ma mũthenya ti ĩkũmi na elĩ? Ethĩwa mũndũ ethi na mũthenya, ndatulw’a, nũndũ niwene kyeni kya nthĩ ĩno.'),
('kam', 'JHN', 11, 10, 'Ĩndĩ ethĩwa mũndũ ethi na ũtukũ, nũnũũtulw’a, nũndũ kyeni kĩi nthĩnĩ wake.'),
('kam', 'JHN', 11, 11, 'Aneena maũndũ asu: na ĩtina amea, Lasalo ũla mũnyanyae waitũ nũkomete; ĩndĩ nĩngũthi ngamũamũkye.'),
('kam', 'JHN', 11, 12, 'Na ĩndĩ amanyĩw’a make mamwĩa, Mwĩaĩi, ethĩwa nũkomete, akavoa.'),
('kam', 'JHN', 11, 13, 'Ĩndĩ Yesũ aneenaa ũndũ wa kikw’ũ kyake: ĩndĩ nĩmaisye eneena ũndũ wa kũkoma too.'),
('kam', 'JHN', 11, 14, 'Nĩvo ĩndĩ Yesũ wamatavya vyũ, Lasalo nĩ mũkw’ũ.'),
('kam', 'JHN', 11, 15, 'Na nĩngũtana kwondũ wenyu nũndũ ndinaĩ vo, nĩ kana mwĩtĩkĩle; ĩndĩ tũthii vala ũĩ.'),
('kam', 'JHN', 11, 16, 'Na ĩndĩ Thomas, ũla wetawa Ĩvatha, wameie amanyĩw’a ala angĩ, Tũthii naitũ, tũkw’e vamwe nake.'),
('kam', 'JHN', 11, 17, 'Na Yesũ avika, ethĩa nũminĩte matukũ ana e mbũanĩ.'),
('kam', 'JHN', 11, 18, 'Na Vethania vaĩ vakuvĩ na Yelusaleme, ta maĩli elĩ;'),
('kam', 'JHN', 11, 19, 'na aingĩ ma Ayuti nĩmookie kwa Matha na Meli, kũmakiakisya nũndũ wa mwana‐a‐inyia woo.'),
('kam', 'JHN', 11, 20, 'Na ĩndĩ Matha, yĩla wewie kana Yesũ nĩwũkĩte, athi ũmũthaũa: ĩndĩ Meli ailyĩ nyũmba.'),
('kam', 'JHN', 11, 21, 'Na ĩndĩ Matha amwĩa Yesũ, Mwĩaĩi, kethĩwa ũnaĩ kũũ, mwana‐a‐ia ndakw’a.'),
('kam', 'JHN', 11, 22, 'Na nĩnĩsĩ o na yu kana ũndũ o na wĩva ũla wĩmwĩtya Ngai, Ngai akakũnenga.'),
('kam', 'JHN', 11, 23, 'Yesũ amwĩa, Mwana‐a‐inyia waku akathayũũka.'),
('kam', 'JHN', 11, 24, 'Matha amwĩa, Nĩnĩsĩ akathayũũka ũthayũũkyonĩ wa mũthenya wa mũminũkĩlyo.'),
('kam', 'JHN', 11, 25, 'Yesũ amwĩa, Ninyie ũthayũũkyo, na ninyie thayũ: ũla ũmbĩtĩkĩlaa, o na ethĩwa nũnũũkw’a, akeethĩwa na thayũ;'),
('kam', 'JHN', 11, 26, 'na o ũla wĩ na thayũ na ũmbĩtĩkĩlaa ndakakw’a o na ĩndĩĩ. Nũkwĩtĩkĩla ũu?'),
('kam', 'JHN', 11, 27, 'Nake amwĩa, Ĩĩ, Mwĩaĩi: nĩnĩtĩkĩlĩte kana nue Klĩsto, Mwana wa Ngai, ũla wĩũka kũũ nthĩ.'),
('kam', 'JHN', 11, 28, 'Na asya ũu, athi, amwĩta Meli mwĩĩtũ‐a‐inyia nzama, akyasya, Mũmanyĩsya e vaa, na nũnũũkwĩta.'),
('kam', 'JHN', 11, 29, 'Nake eew’a ũu, ookĩla na mĩtũkĩ, na athi vala ũĩ.'),
('kam', 'JHN', 11, 30, '(Ĩndĩ Yesũ ndaĩ anamba ũvota mũsyi, ĩndĩ aĩ o vala Matha wakomanĩe nake.)'),
('kam', 'JHN', 11, 31, 'Nĩvo Ayuti ala maĩ nake nyũmbanĩ makĩmũkiakisya, moona Meli, ũndu wokĩla na mĩtũkĩ na aũmaala, mamũatĩĩie, makĩsũanĩa ũendete mbũanĩ akaĩĩe vo.'),
('kam', 'JHN', 11, 32, 'Na Meli, ooka vala ve Yesũ, na amwona, eevalũkya maũũnĩ make, akĩmwĩa, Mwĩaĩi, kethĩwa ũnaĩ kũũ, mwana‐a‐ia ndakw’a.'),
('kam', 'JHN', 11, 33, 'Na Yesũ oona akĩĩa, na Ayũti ala mookanisye nake makĩĩa, eew’a woo vevanĩ, na aũũya,'),
('kam', 'JHN', 11, 34, 'na asya, Mũnamwiie va? Mamwĩa, Mwĩaĩi, ũka ũkone.'),
('kam', 'JHN', 11, 35, 'Yesũ aĩa.'),
('kam', 'JHN', 11, 36, 'Na ĩndĩ Ayuti masya, Kwa sisyai ũndũ ũnamwendete!'),
('kam', 'JHN', 11, 37, 'Ĩndĩ amwe moo masya, Ũũ wasalukilye kĩlilinda metho, ndanaĩ atonya kũtuma mũndũ ũũ ũtakw’a?'),
('kam', 'JHN', 11, 38, 'Na ĩndĩ Yesũ eew’a woo ĩngĩ nthĩnĩ wake avika mbũanĩ. Nayo yaĩ ngunga, na yakunĩkĩlw’e na ĩvia.'),
('kam', 'JHN', 11, 39, 'Na Yesũ asya, Vetai ĩvia. Matha, mwĩĩtu‐a‐inyia wa ũla mũkw’ũ, amwia, Mwĩaĩi, yuyu nũnũũnyunga; nũndũ ũmũnthĩ nĩ wa kana, akw’a.'),
('kam', 'JHN', 11, 40, 'Yesũ amwia, Ndinakwĩa, kana, ethĩwa nũkwĩtĩkĩla, nũkwona ũnene wa Ngai?'),
('kam', 'JHN', 11, 41, 'Na ĩndĩ maveta yĩla ĩvia. Na Yesũ aũngalalya metho, na asya, Asa, nĩngũũtũngĩa mũvea nũndũ nĩwambĩw’a.'),
('kam', 'JHN', 11, 42, 'Nakwa nĩnĩsĩ kana mavinda onthe nũmbĩw’aa: ĩndĩ nũndũ wa ĩkomano yĩĩ yĩũngeme yĩnthyũlũlũkĩte naneena ũu, matonye kwĩtĩkĩla kana nue wandũmie.'),
('kam', 'JHN', 11, 43, 'Na aneena maũndũ asu, aneena na wasya mũnene, Lasalo, umaala.'),
('kam', 'JHN', 11, 44, 'Ũla eĩ mũkw’ũ aumaala, alingĩlĩtwe ngũa ya mathiko maũũ na moko; na ũthyũ wake wovetwe na kĩtambaa. Yesũ amea, Mũthasyei, na mũekei athi.'),
('kam', 'JHN', 11, 45, 'Na ĩndĩ aingĩ ma Ayuti, ala mookie kwa Meli na moona ũndũ ũla wĩkie, mamwĩtĩkĩla.'),
('kam', 'JHN', 11, 46, 'Ĩndĩ amwe moo mathi kwa Avalisi mamatavya maũndũ ala Yesũ wĩkie.'),
('kam', 'JHN', 11, 47, 'Na ĩndĩ athembi ala anene na Avalisi moomban’ya nzama, na masya, Twĩĩka ata? Nũndũ mũndũ ũũ ekaa syama mbingĩ.'),
('kam', 'JHN', 11, 48, 'Ethĩwa twĩmũeka ũu, andũ onthe makamwĩtĩkĩla: na Alomi makooka mose kũũ kwitũ na mbaĩ yaitũ.'),
('kam', 'JHN', 11, 49, 'Ĩndĩ ũmwe wamo, ũla wetawa Kaiava, ũla waĩ mũthembi mũnene mwaka ũsu, amatavya, Mũi ũndũ mwĩsĩ,'),
('kam', 'JHN', 11, 50, 'na mũtiũsũanĩa nĩkwaĩle inyw’ĩ, mũndũ ũmwe akw’e nũndũ wa andũ, nĩ kana mbaĩ yonthe ndĩkae.'),
('kam', 'JHN', 11, 51, 'Na ndaaneena ũu kwondũ wake: ĩndĩ nũndũ nĩwe waĩ mũthembi mũnene mwaka ũsu, athana kana Yesũ akamĩkw’ĩĩa mbaĩ;'),
('kam', 'JHN', 11, 52, 'na ti ũndũ wa mbaĩ yoka ĩndĩ nĩ kana atonye kũmban’ya syana sya Ngai ila itwĩe inyaĩĩkĩtw’e syĩthĩwe ũmwe.'),
('kam', 'JHN', 11, 53, 'Na ĩndĩ kuma mũthenya ũsu masaman’ya nĩ kana matonye kũmũaa.'),
('kam', 'JHN', 11, 54, 'Na kwondũ wa ũu Yesũ ndaambĩla kwanganga eyumĩlĩtye katĩ wa Ayuti, ĩndĩ auma kw’o na athi nthĩ ĩla ĩthengeee weũnĩ, ndũanĩ yĩtawa Evalaimũ; na ekala vo vamwe na amanyĩw’a make.'),
('kam', 'JHN', 11, 55, 'Na mboka ya vasaka yaĩ vakuvĩ ũvĩka: na aingĩ maumie nthĩ ĩsu mambatie Yelusaleme vasaka ũtanamba ũvika, nĩ kana methesye.'),
('kam', 'JHN', 11, 56, 'Na mamantha Yesũ, na maneenan’ya ene kwa ene, maũngamĩte ĩkalũnĩ, Mwĩona ata? Mwĩasya ndeũka mbokanĩ?'),
('kam', 'JHN', 11, 57, 'Na ĩndĩ athembi anene na Avalisi maumisye mwĩao, kana, ethĩwa mũndũ nĩwĩsĩ vala ũĩ, aete ũvoo, nĩ kana mamũkwate.'),
('kam', 'JHN', 12, 1, 'Na vatiele mĩthenya thanthatũ vasaka ũvike, Yesũ athi Vethania, vala Lasalo watwĩe, ũla wathayũũkiw’e nĩ Yesũ kuma kwa akw’ũ.'),
('kam', 'JHN', 12, 2, 'Na mamũseũvĩsya lĩu kw’o: na Matha nĩwe wanenganae lĩu; ĩndĩ Lasalo aĩ ũmwe wa ala mailyĩ nthĩ makĩya nake.'),
('kam', 'JHN', 12, 3, 'Na ĩndĩ Meli oosa latili ũmwe wa mauta matheu, me vata mũnene mũno, na amũvaka Yesũ maũũ, na amanyasya maũũ make na nzw’ĩĩ syake: na nyũmba yausũa mũuke wa ala mauta.'),
('kam', 'JHN', 12, 4, 'Ĩndĩ mũmanyĩw’a ũmwe wake, wetawa Yutasi Isikalioti, ũla wĩmũvũnyanĩa, asya,'),
('kam', 'JHN', 12, 5, 'Nĩkĩ mauta mateĩ matewa silingi maana atatũ, ikanengwa ngya?'),
('kam', 'JHN', 12, 6, 'Ndaasya ũũ, nũndũ wa kũsyĩw’ĩa ngya tei; ĩndĩ nũndũ aĩ kĩng’ei, na aĩ mũkui wa ngusu, na akyũya kĩla kyeekĩawa vo.'),
('kam', 'JHN', 12, 7, 'Na ĩndĩ Yesũ asya, Mũekei: ambĩka ũu ũndũ wa mũthenya ũla nĩthikwa.'),
('kam', 'JHN', 12, 8, 'Nũndũ ngya mwĩ nasyo mavinda onthe; ĩndĩ nyie mũi nakwa mavinda onthe.'),
('kam', 'JHN', 12, 9, 'Na ĩndĩ nguthu ya Ayuti yamanya kana e kw’o, yooka, na ti ũndũ wa Yesũ weka, ĩndĩ nĩ kana ĩmwone Lasalo nake, ũla wathayũũkiw’e nĩ Yesũ kuma akw’ũnĩ.'),
('kam', 'JHN', 12, 10, 'Ĩndĩ athembi anene masaman’ya mamũae Lasalo nake;'),
('kam', 'JHN', 12, 11, 'nũndũ andũ aingĩ maumie kwa Ayuti kwondũ wake, mamwĩtĩkĩla Yesũ.'),
('kam', 'JHN', 12, 12, 'Na ũnĩ ũsu nguthu nene ĩla yaĩ ĩnavika mbokanĩ, yeew’a kana Yesũ nũnũkũka Yelusaleme,'),
('kam', 'JHN', 12, 13, 'yoosa matũ ma makĩndũ, na yathi ũmũthaũa, na yookĩlya mawasya mũno, ĩkyasya, Hosana: Nĩ mũathime ũla wũkĩte syĩtwanĩ ya Mwĩaĩi, nĩwe Musumbĩ wa Isilaeli.'),
('kam', 'JHN', 12, 14, 'Na Yesũ oona ndena ya ĩng’oi, na amĩtũla; o ũndũ kũandĩkĩtwe,'),
('kam', 'JHN', 12, 15, 'Ndũkakĩe, mwĩĩtu wa Saioni: sisya, Mũsũmbĩ waku mwũkĩte, atũlĩte ndena ya ĩng’oi.'),
('kam', 'JHN', 12, 16, 'Maũndũ asu amanyĩw’a make maiaamanya mbee: ĩndĩ yĩla Yesũ wesie kũtaĩwa, nĩvo malilikanile kana maũndũ asu nĩmaandĩkĩtwe ũndũ wake, na mamwĩkie o maũndũ asu.'),
('kam', 'JHN', 12, 17, 'Na indĩ nguthu ĩla yaĩ nake yĩla wamwĩtie Lasalo aume mbũanĩ na amũthayũũkya kwa akw’ũ, nĩyakũsĩĩaa.'),
('kam', 'JHN', 12, 18, 'Na kwondũ wa ũu nguthu yaendie kũmũthaũa, nũndũ nĩyeewie kana nũneekie kyama kyu.'),
('kam', 'JHN', 12, 19, 'Na ĩndĩ Avalisi masya ene kwa ene, Sisyai mũti ũndũ mũtonya; onai, nthĩ nĩendete ĩmũatĩĩe.'),
('kam', 'JHN', 12, 20, 'Na kwaĩ Akiliki amwe katĩ wa ala mambatie kũthaitha mbokanĩ:'),
('kam', 'JHN', 12, 21, 'namo mathi vala ve Vilivu, ũla ũtwĩe Vethisaita, nthĩ ya Kalilii, na mamũkũlya, makyasya, Vwana, nĩtũkwenda kũmwona Yesũ.'),
('kam', 'JHN', 12, 22, 'Na Vilivu athi amũtavya Andalea: na Andalea athi. E na Vilivu, na mamũtavya Yesũ.'),
('kam', 'JHN', 12, 23, 'Na Yesũ amasũngĩa, akyasya, Saa nĩ mũviku yu Mwana wa mũndũ kũtaĩwa.'),
('kam', 'JHN', 12, 24, 'Nĩ w’o, nĩ w’o, nĩngũmwĩa, Keka mbeke ya nganũ ĩnĩũvalũka mũthanganĩ na ĩikw’a, ĩkalaa ĩyoka; ĩndĩ yakw’a, ĩsyaaa ũsyao mwingĩ.'),
('kam', 'JHN', 12, 25, 'Ũla wendaa thayũ wake nũnũkũwasya; na ũla ũmenaa thayũ wake e kũũ nthĩ akoosũvia kũvika thayũ ũtathela.'),
('kam', 'JHN', 12, 26, 'Ethiwa mũndũ o na wiva nũnũũnthũkũma, nambikĩle; na vala nĩĩ, nĩvo mũthũkũmi wakwa nake ũkethĩwa: ethĩwa mũndũ o na wĩva akanthũkũma, akataĩwa nĩ Asa.'),
('kam', 'JHN', 12, 27, 'Na yu ngoo yakwa nĩnĩkũũũya; na nĩasya ata? Asa, ndangĩĩa kuma saanĩ ũũ. Ĩndĩ kwondũ wa ũu nĩnookie kũvĩkĩa saa ũũ.'),
('kam', 'JHN', 12, 28, 'Asa, taĩa syĩtwa yaku. Na ĩndĩ kwauma wasya ĩtunĩ, ũkyasya, Nĩnayĩtaĩa, na ngayĩtaĩa ĩngĩ.'),
('kam', 'JHN', 12, 29, 'Na ĩndĩ nguthu ĩla yaũngeme vo, yeew’a, yasya kana nĩkwatunduma: angĩ masya, Nĩ mũlaĩka waneena nake.'),
('kam', 'JHN', 12, 30, 'Yesũ asũngĩa na asya. Wasya ũsu ndũnoka kwondũ wakwa, ĩndĩ nũndũ wenyu.'),
('kam', 'JHN', 12, 31, 'Oyu ũsililo wa nthĩ ĩno wĩ kw’o: oyu mũnene wa nthĩ ĩno akekw’a nza.'),
('kam', 'JHN', 12, 32, 'Nakwa, nookĩlw’a ĩũlũ wa nthĩ, ngakusya andũ onthe kwakwa.'),
('kam', 'JHN', 12, 33, 'Aasya ũu, akyonan’ya kĩkw’ũ kĩla wĩkw’a.'),
('kam', 'JHN', 12, 34, 'Ĩkomano yamũsũngĩa, Ĩthyĩ nĩtwĩw’ĩte mĩaonĩ kana Klĩsto ekalaa tene na tene: naku wĩasya ata, Ũla Mwana wa mũndũ mũvaka okĩlw’e? Mwana ũsu wa mũndũ nũũ?'),
('kam', 'JHN', 12, 35, 'Na ĩndĩ Yesũ amea, Kũtiele ĩvinda ĩnini kyeni kĩ katĩ wenyu. Endai ĩvinda yĩla mwĩ na kyeni, nĩ kana kĩvindu kĩikamũkitye: na ũla ũendelaa kĩvindunĩ ndesĩ kũla ũnũũthi.'),
('kam', 'JHN', 12, 36, 'Yĩla mwĩ na kyeni, ĩtĩkĩlai kyeni nĩ kana mwĩthĩwe ana ma kyeni. Yesũ aneena maũndũ asu, na athi amevitha.'),
('kam', 'JHN', 12, 37, 'O na kau nĩwekie syama mbingĩ mbee wamo, ĩndĩ matyaamwĩtĩkĩla:'),
('kam', 'JHN', 12, 38, 'nĩ kana ndeto yĩanĩw’e, ĩla yaneeniwe nĩ mwathani Isaia, akyasya, Mwĩaĩi, nũũ ũla wetĩkĩlile ũvoo ũla twaetie? Na kw’oko kwa Mwĩaĩi kwavuanĩw’e ũũ?'),
('kam', 'JHN', 12, 39, 'Na nũndu wa ũu maiaatonya kwĩtĩkĩla, nũndũ Isaia nĩwaneenie ĩngĩ, akyasya,'),
('kam', 'JHN', 12, 40, 'Nĩwamatw’ĩkĩthisye ililinda, na amomya ngoo syoo; Maikese kwona na metho moo, na kũmanya na ngoo syoo, Makaelyũla, Nakwa ngamavosya.'),
('kam', 'JHN', 12, 41, 'Isaia aneenie maũndũ asu, nũndũ nĩwonie ũtheu mũtisu wake: na aneena ũndũ wake.'),
('kam', 'JHN', 12, 42, 'Ĩndĩ o na aingĩ ma anene nĩmamwĩtĩkĩlile; ĩndĩ kwondũ wa Avalisi maiaamumbũla, maikalũngw’e ĩsinakokenĩ;'),
('kam', 'JHN', 12, 43, 'nũndũ nĩmendaa ndaĩa ya andũ mbee wa ndaĩa ya Ngai'),
('kam', 'JHN', 12, 44, 'Yesũ ookĩlya wasya mũnene na asya, Ũla ũmbĩtĩkĩlaa, tii nyie wĩtĩkĩlĩte, ĩndĩ nĩ ũla wandũmie.'),
('kam', 'JHN', 12, 45, 'Na ũla ũnzyaasya nyie amũsyasya ũla wandũmie.'),
('kam', 'JHN', 12, 46, 'Nĩnũkĩte kũũ nthĩ ni kyeni, ni kana ũla ũmbĩtĩkĩlaa ndakekale kĩvindunĩ.'),
('kam', 'JHN', 12, 47, 'Na ethĩwa mũndũ o na wĩva nũkwĩw’a ndeto syakwa, na ndekwikwata, ndiũmũsilĩla: nũndũ ndyaaũka nĩsilĩle nthĩ, ĩndĩ nĩ kana nĩtangĩĩe nthĩ.'),
('kam', 'JHN', 12, 48, 'Ũla ũnũũndea, na ndeũkwata ndeto syakwa, e na ũla ũnũũmũsilĩla: ndeto ila naneena, nĩyo ĩkamũsilĩla mũthenya wa mũminũkĩlyo.'),
('kam', 'JHN', 12, 49, 'Nũndũ ndyaaneena ũndũ wumĩte kwakwa mwene; ĩndĩ Asa ũla wandũmie, nĩwendaĩe, ũndũ ngasya, na ũndũ nganeena.'),
('kam', 'JHN', 12, 50, 'Nakwa nĩnĩsĩ kana mwĩao wake nĩ thayũ ũtathela; na kwondũ wa ũu maũndũ ala ngũneena, o ũndũ Asa wambĩie, nĩw’o nĩneenaa.'),
('kam', 'JHN', 13, 1, 'Na mboka ya vasaka ĩtanavika, Yesũ nĩwesĩ kana saa wake nĩ mũviku aume kũũ nthĩ athi kwa Asa, na kwa kwĩthĩwa nĩwamendie ala make me kũũ nthĩ, amendie kũvika mũminũkĩlyo.'),
('kam', 'JHN', 13, 2, 'Na makĩya lĩu wa wĩoo, ndevili amina kwĩkĩa ngoonĩ ya Yutasi Isikalioti, mwana wa Simoni, kũmũvũnyanĩa,'),
('kam', 'JHN', 13, 3, 'na Yesũ nĩwesĩ kana Ĩthe nĩwamũnengie maũndũ onthe mokonĩ make, na kana nĩwaumie kwa Ngai, na ethi kwa Ngai,'),
('kam', 'JHN', 13, 4, 'ookĩla lĩunĩ, na aia ngũa syake ũtee; na oosa kĩtambaa, na eevotoa.'),
('kam', 'JHN', 13, 5, 'Na ĩndĩ eekĩa manzĩ ĩsaaninĩ ĩnene, na ambĩlĩlya kũmathambya amanyĩw’a make maũũ, na amanyasya na kĩtambaa kĩla wevotoete.'),
('kam', 'JHN', 13, 6, 'Na avika vala ve Simoni Vetelo. Na amwĩa, Mwĩaĩi, wĩnthambya maũũ makwa?'),
('kam', 'JHN', 13, 7, 'Yesũ amũsũngĩa na amwĩa, Ũndũ ngwĩka ndũũmanya yu; ĩndĩ ũkamanya ĩtina.'),
('kam', 'JHN', 13, 8, 'Vetelo amwĩa, Ndwĩnthambya maũũ makwa o na ĩndĩĩ. Na Yesũ amũsũngĩa, Ethĩwa ndiũthambya, ndwĩ na kĩanda nakwa.'),
('kam', 'JHN', 13, 9, 'Simoni Vetelo amwĩa Mwĩaĩi, ti maũũ oka, ĩndĩ nthambya o na moko na mũtwe.'),
('kam', 'JHN', 13, 10, 'Yesũ amwĩa, Ũla ũthambĩte nde na vata ate o kũthambya maũũ, ĩndĩ ni mũtheu kw’onthe: na inyw’ĩ mwĩ atheu, ĩndĩ ti inyw’onthe.'),
('kam', 'JHN', 13, 11, 'Nũndũ nĩwesĩ ũla ũnũũmũvũnyanĩa; na nũndũ wa ũu aisye, Mũi atheu inyw’onthe.'),
('kam', 'JHN', 13, 12, 'Na ĩndĩ amathambya maũũ, oosa ngũa syake, na ekala nthĩ, amea Nĩmwĩsĩ ũndũ namwĩka?'),
('kam', 'JHN', 13, 13, 'Inyw’i mwĩmbĩta, Mũmanyisya, na Mwĩaĩi: na mwĩasya nesa; nũndũ nĩw’o ninyie.'),
('kam', 'JHN', 13, 14, 'Ĩndĩ ethĩwa nyie, Mwĩaĩi na mũmanyĩsya, namũthambya maũũ menyu, inyw’ĩ nenyu, nĩmwaĩlwe nĩ kũthamban’ya maũũ.'),
('kam', 'JHN', 13, 15, 'Nũndũ nĩnamwon’ya ngelekan’yo, nĩ kana ũndũ namwĩka nenyu mwĩkanae o ta ũu.'),
('kam', 'JHN', 13, 16, 'Nĩ w’o, nĩ w’o, nĩngũmwĩa, Ngombo ti nene kwĩ vwana wayo; o na ũla ũtũmĩtwe ti mũnene kwĩ ũla ũmũtũmĩte.'),
('kam', 'JHN', 13, 17, 'Ethĩwa nĩmwĩsĩ maũndũ aa, mwĩ aathime ethĩwa nĩmũũmeka.'),
('kam', 'JHN', 13, 18, 'Ndiũmũweta inyw’onthe: nĩnĩsĩ ala nanyuvie: ĩndĩ nĩ kana maandĩko meanĩw’e, Ũla ũnũũya lĩu nakwa nũnũũmbũkĩlĩlya kĩtiinyo kyake ĩũlũ wakwa.'),
('kam', 'JHN', 13, 19, 'Kuma yu nĩmũtavya mbee wa ũtanekĩka, ni kana weekĩka, mwĩthiwe o mwĩtĩkĩle kana ninyie we.'),
('kam', 'JHN', 13, 20, 'Ni w’o, nĩ w’o, nĩngũmwĩa, Ũla ũmwosaa ũla ndũmaa embosa nyie; na ũla ũmbosaa nyie emwosa ũla wandũmie.'),
('kam', 'JHN', 13, 21, 'Na Yesũ amina ũneena ũu, aũũya vevanĩ, na akũsĩĩa, asya, Ni w’o, ni w’o, nĩngũmwĩa, kana ũmwe wenyu akambũnyanĩa.'),
('kam', 'JHN', 13, 22, 'Na ĩndĩ amanyĩw’a make masyaan’ya, me na nzika mateũmanya ũla ũnũũwetwa.'),
('kam', 'JHN', 13, 23, 'Na mesanĩ kwaĩ ũmwe wa amanyĩw’a make, ũla wendetwe nĩ Yesũ, aĩĩe kithũini kya Yesũ.'),
('kam', 'JHN', 13, 24, 'Na kwondũ wa ũu Simoni Vetelo amwon’ya na kw’oko, amwĩa, Tũtavye nũũ ũla ũnũũweta.'),
('kam', 'JHN', 13, 25, 'Nake amwaĩĩe Yesũ kĩthũinĩ, o ũndũ wailyi, amũkũlya, Mwĩaĩi, nũũ?'),
('kam', 'JHN', 13, 26, 'Yesũ amũsũngĩa, Ũla ngũindĩa kyenyũ kya kĩmũtũ, na kũmũnenga, nĩ ũsu. Na ainda, amũnenga Yutasi, mwana wa Simoni Isikalioti.'),
('kam', 'JHN', 13, 27, 'Na ĩtina wa kwosa kĩla kĩlungu, avotwa nĩ Satani. Na ĩndĩ Yesũ amwĩa, Ũndũ ula ũkwĩka, ĩka mĩtũkĩ.'),
('kam', 'JHN', 13, 28, 'Na vaiaĩ mũndũ wa ala mailyĩ mesanĩ waamanya nũndũ wa kĩ waneena nake ũu.'),
('kam', 'JHN', 13, 29, 'Nĩkwĩthĩwa Yutasi akuaa mũvuko, amwe masũanĩa kana Yesũ amwia, Thooa syĩndũ ila twĩ vata nasyo sya mboka; kana anenge ngya kĩndũ.'),
('kam', 'JHN', 13, 30, 'Nake oosa kĩla kĩlũngu kya kĩmũtũ aumaala kavinda o kau: na kwaĩ ũtukũ.'),
('kam', 'JHN', 13, 31, 'Na ĩndĩ ũsu aumaala, Yesũ asya, Yu Mwana wa mũndũ nũnũũtaĩwa, na Ngai nũnũũtaĩwa nthĩnĩ wake;'),
('kam', 'JHN', 13, 32, 'na Ngai akamũtaĩa nthĩnĩ wake mwene, na akamũtaĩa mĩtũkĩ.'),
('kam', 'JHN', 13, 33, 'Syana nini, vatiele ĩvinda ĩnini nĩ vamwe nenyu. Mũkamantha: na tondũ nameie Ayuti, Kũla nĩthi, mũtitonya kũka; ta ũu yu nĩngũmwĩa inyw’ĩ.'),
('kam', 'JHN', 13, 34, 'Nĩngũmũnenga mwĩao mweũ, atĩ mwendane inyw’ĩ kwa inyw’ĩ; o ũndũ namwendie, nenyu mwĩthĩwe mũkyendana o w’o.'),
('kam', 'JHN', 13, 35, 'Na kwondũ wa ũu andũ onthe makamanya kana mwĩ amanyĩw’a makwa, ethĩwa mwĩthĩwa na wendo ĩnyw’ĩ kwa inyw’ĩ.'),
('kam', 'JHN', 13, 36, 'Simoni Vetelo amũkũlya, Mwĩaĩi, wĩthi kũ? Yesũ amũsũngĩa, Kũla ngũthi, ndũtonya ũmbikĩla yu; ĩndĩ ũkambikĩla ĩtina.'),
('kam', 'JHN', 13, 37, 'Vetelo amwĩa, Mwĩaĩi, nditonya ũkũvikĩla oyu nĩkĩ? Thayũ wakwa nĩngũwia nthĩ kwondũ waku.'),
('kam', 'JHN', 13, 38, 'Yesũ amũsũngĩa, Ũkaia thayũ waku nthĩ kwondũ wakwa? Nĩ w’o, nĩ w’o, nĩngũkwĩa, Nzamba ĩtanamba kwasya ũkangaĩa katatũ.'),
('kam', 'JHN', 14, 1, 'Ngoo syenyu itikaũũye: mũĩkĩĩei Ngai, na mũindĩkĩĩa nyie.'),
('kam', 'JHN', 14, 2, 'Nthĩnĩ wa nyũmba ya Asa kwĩ mawĩkalo maingĩ; na kethĩwa ti ũu, nĩthĩwa namũtavisye; nũndũ nĩngũthi ũmũseũvĩsya vandũ.'),
('kam', 'JHN', 14, 3, 'Nakwa nathi ũmũseũvĩsya vandũ, ngooka ĩngĩ, na ngamwosa inyw’ĩ mwĩthĩwe kwakwa; nĩ kana vala nĩĩ, nenyu mwĩthĩwe vo.'),
('kam', 'JHN', 14, 4, 'Na kũla nĩthi, nĩmwĩsĩ nzĩa.'),
('kam', 'JHN', 14, 5, 'Thoma amwĩa, Mwĩaĩi, tũtesĩkũla wĩthi; twĩsĩ nzĩa ata?'),
('kam', 'JHN', 14, 6, 'Yesũ amwĩa, Nyie ninyie nzĩa, na ninyie w’o, na ninyie thayũ: vai mũndũ wũkaa kwa Asa, atesĩle kwakwa.'),
('kam', 'JHN', 14, 7, 'Kethĩwa nĩmwamanyie nyie, mwĩthĩwa mwamũmanyie Asa nake: na kuma yu nĩmũmwĩsĩ, na nĩmũwonete.'),
('kam', 'JHN', 14, 8, 'Vilivu amwĩa, Mwĩaĩi, twon’ye Asa, na nĩw’o twĩĩanĩwa.'),
('kam', 'JHN', 14, 9, 'Yesũ amwĩa, Nai vamwe nenyu ĩvinda yĩu yonthe, na ndũmbĩsĩ, Vilivu? Ũla wambonie nĩwamwonie Asa; wĩasya ata ĩndĩ, Twon’ye Asa?'),
('kam', 'JHN', 14, 10, 'Ndwĩtĩkĩlĩte kana nyie nĩ nthĩnĩ wa Asa, na Asa e nthĩnĩ wakwa? Ndeto ila ngũmũtavya ndiũneena kuma kwakwa: ĩndĩ Asa ũla ũtwie nthĩnĩ wakwa, nĩwe ũtethasya mawĩa make.'),
('kam', 'JHN', 14, 11, 'Mbĩtĩkĩlai kana nyie nĩ nthĩnĩ wa Asa, na Asa e nthĩnĩ wakwa: kana ethĩwa ti ũu, mbĩtĩkĩlai kwondũ wa ala mawĩa e mo.'),
('kam', 'JHN', 14, 12, 'Nĩ w’o, nĩ w’o, nĩngũmwĩa, Ũla ũmbĩtĩkĩlaa, mawĩa ala ngwĩka nyie, nake akameka; na akeeka mawĩa manene kũvĩta aa; nũndũ nĩngũthi kwa Asa.'),
('kam', 'JHN', 14, 13, 'Na ũndũ o na wĩva w’onthe ũla mwĩvoya syĩtwanĩ yakwa, ngawĩka, nĩ kana Asa ataĩwe nthĩnĩ wa Mwana.'),
('kam', 'JHN', 14, 14, 'Ethĩwa mũkavoya ũndũ o na wĩva syĩtwanĩ yakwa, ngawĩka.'),
('kam', 'JHN', 14, 15, 'Ethĩwa nĩmũmbendete, mũkakwataa mĩao yakwa.'),
('kam', 'JHN', 14, 16, 'Nakwa ngamũvoya Asa, nake akamũnenga Mũtetheesya ũngĩ, ethĩwe nenyu mavinda onthe,'),
('kam', 'JHN', 14, 17, 'nake nĩwe Veva wa w’o: ũla nthĩ ĩtatonya kũmwosa; nũndũ ndĩmwonaa, o na ndĩmwĩsĩ: ĩndĩ inyw’ĩ nĩmũmwĩsĩ; nũndũ ekalaa nenyu, na akeethĩwa e nthĩnĩ wenyu.'),
('kam', 'JHN', 14, 18, 'Ndikamũtia ta syana ndiwa: ngooka vala mũĩ.'),
('kam', 'JHN', 14, 19, 'Kũtiele ĩvinda ĩnini, na nthĩ ndĩkambona ĩngĩ; ĩndĩ inyw’ĩ nimũũmbona: nũndũ nyie nĩ thayũ, ĩnyw’ĩ nenyu mũkeethĩwa mwĩ thayũ.'),
('kam', 'JHN', 14, 20, 'Mũthenya ũsu mũkamanya kana nyie nĩ nthĩnĩ wa Asa, na inyw’ĩ mwĩ nthĩnĩ wakwa, nakwa nĩ nthĩnĩ wenyu.'),
('kam', 'JHN', 14, 21, 'Ũla wĩ na mĩao yakwa, na ũmĩkwataa, ũsu nĩwe ũmbendete: na ũla ũmbendete akendwa nĩ Asa, nakwa ngamwenda na ngeeyonan’ya kwake.'),
('kam', 'JHN', 14, 22, 'Yutasi (eka Isikalioti) amwĩa, mwĩaĩi, kũilyĩ ata ũkwĩyonan’ya kwitũ, ũtekwĩyonan’ya kwa nthĩ?'),
('kam', 'JHN', 14, 23, 'Yesũ asũngĩa na amwĩa, Ethĩwa mũndũ nũmbendaa, akakwataa ndeto yakwa: na Asa wakwa akamwenda, naitũ tũkooka vala ũĩ, tũtũae kwake.'),
('kam', 'JHN', 14, 24, 'Ũla ũtambendaa ndakwataa ndeto syakwa; na ndeto ĩla mũkwĩw’a ti yakwa, ĩndĩ nĩ ya Asa ũla wandũmie.'),
('kam', 'JHN', 14, 25, 'Maũndũ aa namũtavya, ĩvinda yĩĩ nĩilyĩ nenyu.'),
('kam', 'JHN', 14, 26, 'Ĩndĩ ũla Mũtetheesya, nake nĩ Veva Mũtheu, ũla Asa wĩmũtũma syĩtwanĩ yakwa, akamũmanyĩsya maũndũ onthe, na akamũlilikan’ya maũndũ onthe ala namũtavisye.'),
('kam', 'JHN', 14, 27, 'Nĩmũtiĩa mũuo; mũuo wakwa nĩmũnenga inyw’ĩ: ndiũmũnenga ũndũ nthĩ ĩnenganae. Ngoo syenyu itikaũũye, o na itikethĩwe na w’ĩa.'),
('kam', 'JHN', 14, 28, 'Nimweewie ũndũ namwĩie, Nĩngũthi, na ngooka vala mũĩ. Kethĩwa nĩmwambendie, mwĩthĩwa mwatana, nũndũ nĩngũthi kwa Asa: nũndũ Asa nĩ mũnene kwĩ nyie.'),
('kam', 'JHN', 14, 29, 'Na yu namũtavya ũtanamba kwĩkĩka, nĩ kana wekĩka, mwĩĩtĩkĩla.'),
('kam', 'JHN', 14, 30, 'Na kuma yu ndikaneena nenyu mũno, nũndũ mũnene wa nthĩ nũnũkũka: na nde na ũndũ nthĩnĩ wakwa;'),
('kam', 'JHN', 14, 31, 'ĩndĩ nĩ kana nthĩ ĩmanye kana nĩnĩmwendete Asa, na ũndũ Asa wendaĩe, nĩw’o nĩkaa. Ũkĩlai, tũthi.'),
('kam', 'JHN', 15, 1, 'Nyie, ninyie mũsavivũ ũla wa w’o, na Asa nĩwe mũĩmi.'),
('kam', 'JHN', 15, 2, 'Kĩla kaũvonge ke nthĩnĩ wakwa katasyaaa, nũkavetaa: na kĩla kaũvonge kasyaaa, nũkatheasya, nĩ kana kongeleke ũsyaa.'),
('kam', 'JHN', 15, 3, 'O na yu inyw’ĩ mwĩ atheũ nũndũ wa ndeto ĩla nĩmũtavĩtye.'),
('kam', 'JHN', 15, 4, 'Ĩkalai nthĩnĩ wakwa, nakwa nthĩnĩ wenyu. Ũndũ kaũvonge katatonya kũsyaa ke koka, ate o kakĩkala mũsavivũnĩ; ta ũu o nenyu mũtitonya, mũtekwĩkala nthĩnĩ wakwa.'),
('kam', 'JHN', 15, 5, 'Nyie, ninyie mũsavivũ, nenyu mwĩ tũũvonge: ũla wĩkalaa nthĩnĩ wakwa, nakwa nĩ nthĩnĩ wake, ũsu asyaaa ũsyao mwingĩ: nũndũ nde vo nyie, mũtĩtonya kwĩka ũndũ nongi.'),
('kam', 'JHN', 15, 6, 'Mũndũ atekwĩkala nthĩnĩ wakwa, ekaw’a ũtee tondũ kaũvonge kekaw’a, na kakoma; na andũ nĩmatũmbanasya, na maitwĩkya mwakinĩ, na tũivya.'),
('kam', 'JHN', 15, 7, 'Mũkĩkala nthĩnĩ wakwa, na ndeto syakwa ikĩkala nthĩnĩ wenyu, voyai ũla mũkwenda w’onthe, na mũkeekwa.'),
('kam', 'JHN', 15, 8, 'Asa wakwa nũtaĩawa ũndũnĩ ũũ wa inyw’ĩ kũsyaa ũsyao mwingĩ; na kwĩthĩwa amanyĩw’a makwa.'),
('kam', 'JHN', 15, 9, 'O ũndũ Asa ũmbendete, nakwa nĩmwendete inyw’ĩ o w’o: ĩkaalai wendonĩ wakwa.'),
('kam', 'JHN', 15, 10, 'Ethĩwa nĩmũkwataa mĩao yakwa, mũkekalaa wendonĩ wakwa; o ũndũ nyie nakwataa mĩao ya Asa wakwa, na nĩkalaa wendonĩ wake.'),
('kam', 'JHN', 15, 11, 'Nĩnamũtavya maũndũ aa, nĩ kana ũtanu wakwa wĩthĩwe nthĩnĩ wenyu, na ũtanu wenyu wĩthĩwe wĩ musũu.'),
('kam', 'JHN', 15, 12, 'Ũũ nĩw’o mwĩao wakwa, nĩ kana mwendane inyw’ĩ kwa inyw’ĩ, o ũndũ namwendie.'),
('kam', 'JHN', 15, 13, 'Vai mũndũ wĩ wendo mwingĩ ũvĩtũkĩte ũũ, wa mũndũ kũwia thayũ wake nthĩ nũndũ wa anyanyae.'),
('kam', 'JHN', 15, 14, 'Inyw’ĩ mwĩ anyanyawa, ethĩwa nĩmwĩkaa maũndũ ala nĩmwĩaĩaa.'),
('kam', 'JHN', 15, 15, 'Kuma yu ndiũmwĩta ngombo ĩngĩ: nũndũ ngombo ndĩmanya ũndũ vwana wayo wĩkaa: ĩndĩ inyw’ĩ namwĩta anyanyawa; nũndũ maũndũ onthe ala neewĩie kwa Asa nĩmo nĩmũmanyĩthĩtye.'),
('kam', 'JHN', 15, 16, 'Ti inyw’ĩ mwanyuvie, ĩndĩ ninyie namũnyuvie, na namwia, nĩ kana mũendae mũisyaa, na ũsyao wenyu wĩkale: nĩ kana o ũla mwĩvoyaa Asa syĩtwanĩ yakwa, amũnengae.'),
('kam', 'JHN', 15, 17, 'Maũndũ aa nĩngũmwĩaĩa, nĩ kana mwendane inyw’ĩ kwa inyw’ĩ.'),
('kam', 'JHN', 15, 18, 'Ethĩwa nthĩ nĩnĩũmũmena, nĩmwĩsĩ kana nĩyamenie nyie ĩtanamba kũmũmena inyw’ĩ.'),
('kam', 'JHN', 15, 19, 'Kethĩwa mwĩ ma nthĩ, nthĩ ĩthĩwa ĩkyenda ala mayo: ĩndĩ nũndũ mũti ma nthĩ, ĩndĩ namũnyuvie kuma kwa ala ma nthĩ, kwondũ wa ũu nthĩ nĩnĩũmũmena.'),
('kam', 'JHN', 15, 20, 'Lilikanai ndeto ĩla namũtavisye, ngombo ti nene kwĩ vwana wayo. Ethĩwa nĩmanthĩnisye, o nenyu makamũthĩn’ya; ethĩwa nĩmakwatie ndeto yakwa, yenyu nayo makamĩkwata.'),
('kam', 'JHN', 15, 21, 'Ĩndĩ maũndũ aa onthe nĩmakamwĩka nũndũ wa syĩtwa yakwa, nũndũ maimwĩsĩ ũla wandũmie.'),
('kam', 'JHN', 15, 22, 'Kethĩwa ndyaaũka na nganeena namo, maiĩthĩwa na naĩ: ĩndĩ yu maitonya kwĩmila kwondũ wa naĩ yoo.'),
('kam', 'JHN', 15, 23, 'Ũla ũmenaa nyie amenaa Asa wakwa nake.'),
('kam', 'JHN', 15, 24, 'Kethĩwa ndyĩkĩte katĩ woo mawĩa ala mataaĩkwa nĩ mũndũ ũngĩ, maĩĩthĩwa na naĩ: ĩndĩ nĩmambonete na nĩmamenete vamwe na Asa wakwa.'),
('kam', 'JHN', 15, 25, 'Ĩndĩ nĩ kana ĩla ndeto yĩanĩw’e ĩla ĩandĩkĩtwe ĩla mĩaonĩ yoo, Nĩmamenie vate kĩtumi.'),
('kam', 'JHN', 15, 26, 'Ĩndĩ yĩla Mũtetheesya wĩũka, ũla nĩmũtũma kũla mũĩ kũma kwa Asa, nake nĩ ũla Veva wa w’o, ũla wĩuma kwa Asa, we akangũsĩĩa:'),
('kam', 'JHN', 15, 27, 'o nenyu nĩmũũkũsĩĩa, nũndũ nĩmwĩkalanĩtye nakwa kuma mwambĩlĩyonĩ.'),
('kam', 'JHN', 16, 1, 'Maũndũ asu namũtavya, nĩ kana mũikese kũlulutĩkw’a.'),
('kam', 'JHN', 16, 2, 'Nĩmakamũlũngya masinakokenĩ: ĩĩ, na ĩngĩ saa nĩwũkĩte, ũla ũnũũmũaa akatalĩlya kana emũthũkũma Ngai.'),
('kam', 'JHN', 16, 3, 'Na makeeka maũndũ asu, nũndũ maimwĩsĩ Asa, kana nyie.'),
('kam', 'JHN', 16, 4, 'Ĩndĩ maũndũ aa namũtavya, nĩ kana saa wamo wavika, mũkamalilikana, ũndũ namũtavisye. Na maũndũ asu ndyaamũtavya mwambĩlĩlyonĩ, nũndũ naĩ vamwe nenyu.'),
('kam', 'JHN', 16, 5, 'Ĩndĩ yu nĩngũthi kwa ũla wandũmie; na vai ũmwe wenyu ũngũlya, Wĩthi kũ'),
('kam', 'JHN', 16, 6, 'Ĩndĩ kwondũ wa kũmũtavya maũndũ aa, ngoo syenyu syausũwa nĩ kĩmako.'),
('kam', 'JHN', 16, 7, 'Ĩndĩ nĩmũtavya w’o: Nĩkũmwaĩle nyie nĩthi; nũndũ ethĩwa ndithi, ũla Mũtetheesya ndakoka vala mũĩ; ĩndĩ ethĩwa nĩngũthi, ngamũtũma vala mũĩ.'),
('kam', 'JHN', 16, 8, 'Nake, yĩla wĩũka, akamĩĩkĩĩthya nthĩ ũndũ wa naĩ, na ũlũngalu, na ũsilĩlo:'),
('kam', 'JHN', 16, 9, 'ũndũ wa naĩ, nũndũ maiũmbĩtĩkĩla;'),
('kam', 'JHN', 16, 10, 'ũndũ wa ũlũngalu, nũndũ nĩngũthi kwa Asa, na mũimbona ingĩ;'),
('kam', 'JHN', 16, 11, 'ũndũ wa ũsilĩlo, nũndũ mũnene wa nthĩ ĩno nĩ mũsilĩle.'),
('kam', 'JHN', 16, 12, 'Nĩndialĩtye maũndũ maingĩ ma ũmũtavya, ĩndĩ mũtitonya kũmomĩĩsya yu.'),
('kam', 'JHN', 16, 13, 'Ĩndĩ yĩla wĩũka, ũla Veva wa w’o, akamũtongoeasya amwonelelasye w’o w’onthe: nũndũ ndakaneena kuma kwake mwene; ĩndĩ maũndũ onthe ala ũkew’aa nĩmo ũkaneena: na akamũtavya maũndũ ala makoka.'),
('kam', 'JHN', 16, 14, 'Akandaĩa nyie: nũndũ akoosa maũndũ makwa, na akamũvuanĩsya inyw’ĩ.'),
('kam', 'JHN', 16, 15, 'Maũndũ onthe o na meva ala Asa wĩ namo nĩ makwa: kwondũ wa ũu namwĩa kana nĩwosaa maũndũ makwa, na akamũvuanĩsya.'),
('kam', 'JHN', 16, 16, 'Kũtiele ĩvinda ĩnini, na mũtimbona ĩngĩ; na ĩvinda yĩngĩ ĩnini, na mũkambona, nũndũ nĩngũthi kwa Asa.'),
('kam', 'JHN', 16, 17, 'Na ĩndĩ amanyĩw’a amwe maneenan’ya. Ũndũ ũũ watwĩa nata, Kwĩ ĩvinda ĩnini, na mũtĩmbona; na ĩvinda yĩngĩ ĩnini, na mũkambona: na, Nũndũ nĩngũthi kwa Asa?'),
('kam', 'JHN', 16, 18, 'Na indĩ masya, Nata ũu ũnũkwasya, Ĩvinda ĩnini? Tũtyĩsĩ ũndũ ũnũkwasya.'),
('kam', 'JHN', 16, 19, 'Na Yesũ amanya kana menda ũmũkũlya, na amea, Mwĩkũlan’ya ũndũ namwĩa, Kwĩ ĩvinda ĩnini, na mũtimbona, na ĩvinda yĩngĩ ĩnini, na mũkambona?'),
('kam', 'JHN', 16, 20, 'Nĩ w’o, nĩ w’o, nĩngũmwĩa, Inyw’ĩ mũkaĩa na kũmeta, ĩndĩ nthĩ ĩkatana: inyw’ĩ mũkeethĩwa na kĩmako, ĩndĩ kĩmako kyenyu kĩkaalyũlwa ũtanu.'),
('kam', 'JHN', 16, 21, 'Kĩveti kĩkyaũnya kĩthĩawa na woo, nũndũ saa wakyo nĩ mũviku: ĩndĩ kyasyaa kana, kĩililikanaa woo ĩngĩ, ĩndĩ no kũtana nũndũ wa mũndũ asyawa kũũ nthĩ.'),
('kam', 'JHN', 16, 22, 'Nenyu yu mwĩ na kĩmako: ĩndĩ ngamwona ingĩ, na ngoo syenyu ikatana, na ũtanu wenyu vai mũndũ wĩmũvena.'),
('kam', 'JHN', 16, 23, 'Na mũthenya ũsu mũtikangũlya ũndũ. Nĩ w’o, nĩ w’o, nĩngũmwĩa, O ũla mũkavoya Asa syĩtwanĩ yakwa, akamũnenga.'),
('kam', 'JHN', 16, 24, 'Kũvika yu mũiaavoya ũndũ syĩtwanĩ yakwa: voyai, na mũkanengwa, kana ũtanu wenyu wusũe.'),
('kam', 'JHN', 16, 25, 'Maũndũ asu naneena nenyu na nthimo: saa nĩwũkĩte, yĩla ndakaneena nenyu na nthimo, ĩndĩ ngamũtavya ũvoo wa Asa vyũ.'),
('kam', 'JHN', 16, 26, 'Mũthenya ũsu mũkavoya syĩtwanĩ yakwa: na ndiũmũtavya kana ngamũvoya Asa nũndũ wenyu;'),
('kam', 'JHN', 16, 27, 'nũndũ Asa we mwene nũmwendete, nĩkwĩthĩwa nĩmwambendie, na kwĩtĩkĩla kana naumie kwa Asa.'),
('kam', 'JHN', 16, 28, 'Naumie kwa Asa, nooka kũũ nthĩ: na ĩngĩ, nĩnguma kũũ nthĩ, nĩthi kwa Asa.'),
('kam', 'JHN', 16, 29, 'Amanyĩw’a make mamwĩa, Sisya, yu nũũtũtavya ũtheinĩ, o na ndũũneena na nthimo.'),
('kam', 'JHN', 16, 30, 'Yu nĩtwĩsĩ kana nĩwĩsĩ maũndũ onthe, o na ndwĩ vata wa ũkũlw’a nĩ mũndũ: na kwondũ wa ũu nĩtweetĩkĩla kana waumie kwa Ngaĩ.'),
('kam', 'JHN', 16, 31, 'Yesũ amakũlya, Yu nĩmũkwĩtĩkĩla?'),
('kam', 'JHN', 16, 32, 'Nĩmwenei, saa nĩwũkĩte, ĩĩ na nĩ mũviku, yĩla mwĩnyaĩĩkw’a, kĩla mũndũ kwake, mũndie nyioka: na ĩngi ndi nyioka, nũndũ Asa e vamwe nakwa.'),
('kam', 'JHN', 16, 33, 'Maũndũ aa namũtavya, nĩ kana nthĩnĩ wakwa mwĩthĩwe na mũuo. Kũũ nthĩ mwĩ na thĩna: ĩndĩ ĩthĩwai na ũnyiau; nyie, nĩngĩlĩtye nthĩ vinya.'),
('kam', 'JHN', 17, 1, 'Maũndũ asu Yesũ aneena; na ang’elelya metho make ĩtunĩ, na asya, Asa, saa nĩ mũviku; taĩa Mwana waku, nĩ kana ũ Mwana akũtaĩe;'),
('kam', 'JHN', 17, 2, 'o ũndũ wamũnengie ũkũmũ wa kwĩaĩa andũ onthe, nĩ kana onthe ala wamũnengĩe, amanenge thayũ ũtathela.'),
('kam', 'JHN', 17, 3, 'Na thayũ ũtathela nĩw’o ũũ, nĩ kana makũmanye we Ngai ũla wa w’o weka, na ũla wamũtũmie, nake nĩ Yesũ Klĩsto.'),
('kam', 'JHN', 17, 4, 'Ninĩkũtaĩĩte kũũ nthĩ, nũndũ nĩnĩminĩte kwĩka wĩa ũla wanengie nĩke.'),
('kam', 'JHN', 17, 5, 'Na yu, Asa, ndaĩĩthya vamwe naku, na ũtaĩo ũla naĩ naw’o vamwe naku nthĩ ĩtanamba ũtw’ĩkĩthw’a.'),
('kam', 'JHN', 17, 6, 'Nĩnamaumĩlĩlye syĩtwa yaku andũ ala wanengie kuma kwa ala ma nthĩ: maĩ maku, naku wanenga mo; na nĩmakwatiend to yaku.'),
('kam', 'JHN', 17, 7, 'Na yu nĩmesĩ kana maũndũ onthe ala wanengie maumaa kwaku:'),
('kam', 'JHN', 17, 8, 'nũndũ ndeto ila wanengie nĩnĩmanengete; na nĩmasyosie, na nĩmamanyie w’o kana naumie kwakũ, na meetĩkĩla, aĩ, nue wandũmie.'),
('kam', 'JHN', 17, 9, 'Nĩngũmavoyea: ndiũmĩvoyea nthĩ, ĩndĩ nĩ ala wanengie; nũndũ nĩ maku:'),
('kam', 'JHN', 17, 10, 'na syĩndũ syonthe ila syakwa nĩ syaku, na ila syaku nĩ syakwa: nakwa nĩndaĩawa nthĩnĩ wasyo.'),
('kam', 'JHN', 17, 11, 'Na ndi kũũ nthĩ ĩngĩ, ĩndĩ aa me kũũ nthĩ, na nĩngũka kwaku. Asa Mũtheu, masũvĩe syĩtwanĩ yaku yĩla wanengie, nĩ kana methĩwe me ũmwe, o taitũ.'),
('kam', 'JHN', 17, 12, 'Ĩvinda yĩla naĩ vamwe nao, nĩnamasũvĩaa syĩtwanĩ yaku yĩla wanengie: na nĩnamasyaĩĩasya, na vai ũmwe waaa ate o ũla mwana wa wanangĩko; nĩ kana maandĩko meanĩw’e.'),
('kam', 'JHN', 17, 13, 'Na yu nĩngũka kwaku; na maũndũ aa nĩneena kũu nthĩ, nĩ kana methĩwe na ũtanu wakwa wusũe, nthĩnĩ wamo.'),
('kam', 'JHN', 17, 14, 'Nĩnĩmanengete ndeto yaku; na nthĩ nĩyamamenie, nũndũ mo ti ma nthĩ, o ũndũ nyie ndi wa nthĩ.'),
('kam', 'JHN', 17, 15, 'Ndiũvoya nĩ kana ũmaumye kũũ nthĩ, ĩndĩ nĩ kana ũmasũvĩe kwa ũsu mũthũku.'),
('kam', 'JHN', 17, 16, 'Namo ti ma nthĩ, o ũndũ nyie ndi wa nthĩ.'),
('kam', 'JHN', 17, 17, 'Mavahe methĩwe atheu nthĩnĩ wa ũla w’o: ndeto yaku nĩyo w’o.'),
('kam', 'JHN', 17, 18, 'Tondũ wandũmie kũũ nthĩ, o ta ũu nakwa nĩnamatũmie kũũ nthĩ.'),
('kam', 'JHN', 17, 19, 'Na kwondũ wamo nĩngwĩvatha, nĩ kana namo mavathanw’e methĩwe atheu nthĩnĩ wa ũla w’o.'),
('kam', 'JHN', 17, 20, 'O na ti asu oka ngũvoyea, ĩndĩ nĩmavoyea ala makambĩtĩkĩla nũndũ wa ndeto yoo;'),
('kam', 'JHN', 17, 21, 'nĩ kana onthe methĩwe me ũmwe; o ũndũ we, Asa, wĩ nthĩnĩ wakwa, nakwa nĩ nthĩnĩ waku, kana namo methĩwe me nthĩnĩ waitũ: nĩ kana nthĩ yĩtĩkĩle kana nĩwandũmie.'),
('kam', 'JHN', 17, 22, 'Na ũtaĩo ũla wanengie nĩnĩmanengete w’o; nĩ kana methĩwe me ũmwe, o ũndũ ithyĩ twĩ ũmwe;'),
('kam', 'JHN', 17, 23, 'nyie nthĩnĩ woo, naku nthĩnĩ wakwa, kana methĩwe eanĩu nthĩnĩ wa ũmwe; nĩ kana nthĩ ĩmanye, aĩ, nĩwandũmie, na nĩwamendie o ũndũ wambendie.'),
('kam', 'JHN', 17, 24, 'Asa, nĩngwenda asu ala wanengie methĩwe vamwe nakwa vala nĩĩ, kana monage ũtheu mũtisu wakwa, ũla wanengie: nũndũ nĩwambendie mbee wa nthĩ ĩtanambĩlĩlw’a.'),
('kam', 'JHN', 17, 25, 'Ĩĩ, Asa mũĩũngalu, nthĩ ndĩaakũmanya, ĩndĩ nĩnakũmanyie; na aa nĩmamanyie kana natũmiwe nue:'),
('kam', 'JHN', 17, 26, 'na nĩnĩmamanyithĩtye syĩtwa yaku, na ngatũma yimanyĩka; nĩ kana wendo ũla ũmbendete naw’o wĩthĩwe nthĩnĩ woo, nakwa nĩthĩwe nĩ nthĩnĩ woo.'),
('kam', 'JHN', 18, 1, 'Na yĩla Yesũ waminie kũneena ndeto ii, aumaala e na amanyiw’a make mainga kalũsĩ kala ketawa Kitiloni, vala vaĩ mũũnda, na avota vo, e na amanyiw’a make.'),
('kam', 'JHN', 18, 2, 'Nake Yutasi, ũla ũnũũmũvũnyanĩa, nĩwesĩ vandũ vau: nũndũ Yesũ niwaendaa vo kaingĩ na amanyĩw’a make.'),
('kam', 'JHN', 18, 3, 'Na ĩndĩ Yutasi amina ũnengwa nguthu ya asikalĩ, na makanga kuma kwa athembi anene na Avalisi, mooka vo makuĩte mataa na mũĩ na mĩio ya kaũ.'),
('kam', 'JHN', 18, 4, 'Ĩndĩ Yesũ, esĩ maũndũ onthe ala memũkwata, aumĩla, na amakũlya, Mwĩmantha ũũ?'),
('kam', 'JHN', 18, 5, 'Mamũsũngĩa Yesũ wa Nasaleti. Yesũ amea, Ninyie. Nake Yutasi, ũla ũnũũmũvũnyanĩa, aũngeme namo.'),
('kam', 'JHN', 18, 6, 'Na ĩndĩ yĩla wameie, Ninyie, masyoka na kyamũtete, na mavalũka nthĩ.'),
('kam', 'JHN', 18, 7, 'Na ĩndĩ amakũlya ĩngĩ, Mwĩmantha ũũ? Na masya, Yesũ wa Nasaleti.'),
('kam', 'JHN', 18, 8, 'Yesũ amasũngĩa, Nĩnamũtavya ninyie; ethĩwa ĩndĩ ninyie mũũmantha, maekei aa mathi:'),
('kam', 'JHN', 18, 9, 'nĩ kana ĩla ndeto waneenie yĩanĩw’e, ya atĩĩ, Ala ũnengete ndyaasya o na ũmwe.'),
('kam', 'JHN', 18, 10, 'Na Simoni Vetelo ai na ũvyũ, na akũa, na amĩtema ngombo ya mũthembi mũnene, na amĩtila kũtũ kwa ngalĩ ya kw’oko kwa aũme. Na ĩla ngombo yetawa Malikusi.'),
('kam', 'JHN', 18, 11, 'Na ĩndĩ Yesũ amwĩa Vetelo, Tũngĩa ũvyũ ndoonĩ yaw’o: kĩkombe kĩla Asa ũnengete, ngalea kũnyw’a?'),
('kam', 'JHN', 18, 12, 'Nĩvo ĩndĩ ĩla nguthu na mũnene woo, na makanga ma Ayuti, mamũkwatie Yesũ na mamwova,'),
('kam', 'JHN', 18, 13, 'na mbee mamũtwaa kwa Anasi; nũndũ aĩ mũthoni wa Kaiava, ũla waĩ mũthembi mũnene mwake ũsu.'),
('kam', 'JHN', 18, 14, 'Na Kaiava nĩwe wamataie Ayuti, asya nĩkwaĩle mũndũ ũmwe akw’e kwondũ wa andũ.'),
('kam', 'JHN', 18, 15, 'Na Simoni Vetelo amũatĩĩe Yesũ, e na mũmanyĩw’a ũngĩ. Na mũmanyĩw’a ũsu nĩwesĩkĩwe nĩ mũthembi mũnene, na avota vamwe na Yesũ nza kwa mũthembi mũnene;'),
('kam', 'JHN', 18, 16, 'ĩndĩ Vetelo aũngama mũomonĩ nza. Na ĩndĩ mũmanyĩw’a ũla ũngĩ, ũla wesikĩwe nĩ mũthembĩ mũnene, aumaala na aneena na mũsũvĩi wa mũomonĩ, na amũtwaa Vetelo nthĩnĩ.'),
('kam', 'JHN', 18, 17, 'Na ĩndĩ mwĩĩtu ũla mũsũvĩi wa mũomonĩ amũkũlya Vetelo, O naku wĩ ũmwe wa amanyĩw’a ma mũndũ ũũ? Asya, Ndi ũmwe.'),
('kam', 'JHN', 18, 18, 'Na ngombo na makanga maũngamĩte, mavuvĩte mwaki wa makaa; nũndũ kwaĩ mbevo; na motaa mwaki: na Vetelo nake aĩ vamwe nao, aũngeme akyota mwaki.'),
('kam', 'JHN', 18, 19, 'Na ĩndĩ ũla mũthembi mũnene amũkũlya Yesũ ũndũ wa amanyĩw’a make, na ũndũ wa ũmanyĩsyo wake.'),
('kam', 'JHN', 18, 20, 'Yesũ amũsũngĩa, Nyie, nĩneenete ũtheinĩ na nthĩ; na namanyĩasya masinakokenĩ, na ĩkalũnĩ, kũla Ayuti onthe mombanĩaa; na ndyaaneena ndeto ya mbitha.'),
('kam', 'JHN', 18, 21, 'Wĩngũlĩlya kĩ? Makũlye ala meewie, ũndũ naneenie namo: sisya, aa nimesĩ maũndũ ala naisye.'),
('kam', 'JHN', 18, 22, 'Na aneena ũu, ũmwe wa makanga aũngamĩte ũtee amũmandũla Yesũ, akyasya, Wĩmũsũngĩa mũthembi mũnene ũu?'),
('kam', 'JHN', 18, 23, 'Yesũ amũsũngĩa, Ethĩwa nĩnaneena naĩ, kũsĩĩa naĩ ĩsu: ĩndĩ ethĩwa nĩnaneena nesa, wĩngũnĩa kĩ?'),
('kam', 'JHN', 18, 24, 'Na ĩndĩ Anasi amũtwaa e mwove kwa ũla mũthembi mũnene, Kaiava.'),
('kam', 'JHN', 18, 25, 'Na Samoni Vetelo aũngeme aiota mwaki. Na ĩndĩ mamwĩa, Naku wĩ ũmwe wa amanyĩw’a make? Akaĩa, asya, Ndi ũmwe.'),
('kam', 'JHN', 18, 26, 'Na imwe ya ngombo sya mũthembi mũnene, ya mbaĩ ya ĩla yatililwe kũtũ nĩ Vetelo, yasya. Ndinakwona wĩ nake mũũndanĩ?'),
('kam', 'JHN', 18, 27, 'Na ĩndĩ Vetelo akaĩa ĩngĩ: na kavinda o kaũ nzamba yasya.'),
('kam', 'JHN', 18, 28, 'Na ĩndĩ mamumaalya Yesũ kwa Kaiava mamũtwaa kĩsilĩlonĩ: na kwaĩ masangya; ĩndĩ mo ene maiaavota kĩsilĩloni, maikavukw’e nĩ kana maye vasaka.'),
('kam', 'JHN', 18, 29, 'Na Vilato aumaala nza kũla mai, na amakũlya, Mũmũvinganĩĩsye mũndũ ũũ kyaũ?'),
('kam', 'JHN', 18, 30, 'Mamũsũngĩa, mamwĩa, Kethĩwa mũndũ ũũ ti mwĩk wa naĩ, tũiĩthĩwa twamũete kwaku.'),
('kam', 'JHN', 18, 31, 'Vilato amatavya, Mwosei inyw’ĩ, mũkamũsilĩle kwĩanana na mĩao yenyu. Na Ayuti mamwĩa, Ndwosana na ĩla mĩao thyĩ kũaa mũndũ:'),
('kam', 'JHN', 18, 32, 'nĩ kana ndeto ya Yesũ yĩanĩw’e. Ĩla waneenie, aionan’ya kĩkw’ũ kĩla wĩkw’a.'),
('kam', 'JHN', 18, 33, 'Na ĩndĩ Vilato avota ĩngĩ kĩsilĩlonĩ, na amwĩta Yesũ na amũkũlya. We nue Mũsumbi wa Ayuti?'),
('kam', 'JHN', 18, 34, 'Yesũ asũngĩa, akyasya. Wĩneena ũu ũndũ waku kana nũtavitw’e nĩ andũ angĩ ũndũ wakwa?'),
('kam', 'JHN', 18, 35, 'Vilato amũkũlya, Nyie nĩ Mũyuti? Mbaĩ yaku na athembi anene nĩmo makũete kwakwa: wĩkĩte ata?'),
('kam', 'JHN', 18, 36, 'Yesũ asũngĩa, Ũsumbi wakwa tĩ wa nthĩ ĩno, kethĩwa ũsumbĩ wakwa nĩ wa nthi ĩno, makanga makwa methĩwa makyũkita, nĩ kana ndikanenganwe kwa Ayuti: ĩndĩ yu ũsumbĩ wakwa ti wa kũũ.'),
('kam', 'JHN', 18, 37, 'Na ĩndĩ Vilato amwĩa, Ĩndĩ, we, ko wĩ mũsumbĩ? Yesũ amũsũngĩa, We nũũneena kana nĩ mũsumbĩ. Nyie nasyaiwe kwondũ wa ũu, na ĩngĩ nĩ kwondũ wa ũu nokie kũũ nthĩ, ni kana ndw’ĩke ngũsĩ ya ũla w’o. Kĩla mũndũ wĩ ngalĩ ya ũla w’o nĩwĩw’aa wasya wakwa.'),
('kam', 'JHN', 18, 38, 'Vilato amũkũlya W’o nĩ kyaũ? Na aneena ũu, aumaala ĩngĩ nza vala ve Ayuti, na amea, Nyie ndikwona ĩvityo yake.'),
('kam', 'JHN', 18, 39, 'Ĩndĩ mwi na ũndũ wĩkawa, ĩvinda ya vasaka nĩmũthaĩasya mũndũ: mwĩenda nĩmũthaisye Mũsumbĩ wa Ayuti?'),
('kam', 'JHN', 18, 40, 'Na ĩndĩ maneena ĩngĩ na wasya mũnene, makyasya, Ndũkathasye mũndũ ũũ, thasya Valava. Na Valava ai mũvũtani.'),
('kam', 'JHN', 19, 1, 'Na ĩndĩ Vilato amwosa Yesũ, na amũvũa.'),
('kam', 'JHN', 19, 2, 'Na asikalĩ mavĩlangan’ya ngovia ya miw’a, na mamwĩkĩa mũtwe, na mamũvw’ika ngũa ĩilyĩ ta ndune;'),
('kam', 'JHN', 19, 3, 'na mathi vala ũĩ, maimwĩa, Nũvoo, Mũsumbĩ wa Ayuti! Na mamũmandũla.'),
('kam', 'JHN', 19, 4, 'Na Vilato aumaala ĩngi, na amea, Sisyai, nĩnamumaalĩlya ũũ, nĩ kana mũmanye ndikwona ĩvĩtyo o na yĩva yake.'),
('kam', 'JHN', 19, 5, 'Na ĩndĩ Yesũ aumaala, ekĩĩtwe ngovia ya mĩw’a na ngũa ĩla ĩilyĩ ta ndune. Na Vilato amea, Sisyai, mũndũ nĩwe ũũ!'),
('kam', 'JHN', 19, 6, 'Na ĩndĩ athembi anene na makanga mamwona, mookĩlya mawasya, makyasya, Mwambe! Mwambe! Vilato amea, Mwosei inyw’ĩ ene, mũkamwambe: nũndũ nyie ndikwona ĩvĩtyo o na yĩva yake.'),
('kam', 'JHN', 19, 7, 'Na Ayuti mamũsũngĩa, mamwĩa, Ithyĩ twĩ na mwĩao, na ũndũ wa mwĩao ũsu nĩwaĩle kũkw’a, nũndũ etw’ĩte Mwana wa Ngai.'),
('kam', 'JHN', 19, 8, 'Na ĩndĩ Vĩlato eew’a ndeto isũ, eew’a w’ĩa mũnene kwĩ ũla waĩ naw’o;'),
('kam', 'JHN', 19, 9, 'na avota ĩngĩ kĩsilĩlonĩ, na amũkũlya Yesũ, Wumĩte va, we? Indĩ Yesũ ndaamũsũngĩa.'),
('kam', 'JHN', 19, 10, 'Na ĩndĩ Vilato amwĩa. Ndũneena nakwa? We ndwĩsĩ kana nĩ na ũkũmũ wa ũkũthasya, na nĩ na ũkũmũ wa ũkwamba?'),
('kam', 'JHN', 19, 11, 'Yesũ amũsũngĩa, O na ndwĩthĩwa na ũkũmũ ĩũlũ wakwa, keka ũnengetwe kuma iũlũ: na kwondũ wa ũũ ũla wĩkĩte naĩ ĩla nene nĩ ũla ũnenganĩte mokonĩ maku.'),
('kam', 'JHN', 19, 12, 'Kuma vau Vilato amantha nzĩa ya kũmũthasya: ĩndĩ Ayutĩ mookĩlya mawasya, makyasya, Ethĩwa nũũmũthasya mũndũ ũũ, ndwĩ, mũnyanyae wa Kaisali: o mũndũ ũla wĩtusaa mũsumbĩ elea Kaisali.'),
('kam', 'JHN', 19, 13, 'Na Vilato eew’a ndeto isu, amumaalya Yesũ, na ekala kĩvĩlanĩ kya sila, syĩtwa ya vo nĩ Maviamalan’ye, ĩndĩ Kĩevelania vetawa Kavatha.'),
('kam', 'JHN', 19, 14, 'Na kwaĩ Ũseũvyo wa vasaka: na kwaĩ ta saa wa thanthatũ. Na amea Ayuti, Sisya, Mũsumbĩ wenyu!'),
('kam', 'JHN', 19, 15, 'Na kwa ũu mookĩlya mawasya, makyasya, Mũvete! Mũvete! Mwambe! Vilato amakũlya, Nĩmwambe Mũsumbĩ wenyu? Na athembi anene masũngĩa, Tũi na mĩsumbĩ ate o Kaisali.'),
('kam', 'JHN', 19, 16, 'Na ĩndĩ amũnengane mokonĩ moo ambwe.'),
('kam', 'JHN', 19, 17, 'Na ĩndĩ mamũtwaa Yesũ: na aumaala, ekuĩe ngelan’yo yake, kũvika vala vetwa Vandũ va kĩng’ala, na Kĩevelania vetawa Kolokotha:'),
('kam', 'JHN', 19, 18, 'na mamwamba vau, na vamwe nake andũ angĩ elĩ, ngalĩ ĩmwe ũmwe, na ngalĩ ĩngĩ ũmwe, na Yesũ vu katĩ.'),
('kam', 'JHN', 19, 19, 'Na ĩngĩ Vilato aandĩka ũandĩko, awĩkĩa ngelan’yonĩ. Naw’o waandĩkĩtwe, YESŨ MŨNASALETI, MŨSUMBĨ WA AYUTI.'),
('kam', 'JHN', 19, 20, 'Na ũandiko ũsu wasomwa nĩ Ayuti aĩngĩ, nũndũ vala Yesũ wambiwe vaĩ vakuvĩ na ndũa: na nĩwaandĩkĩtwe Kĩevelania, na Kĩlatini, na Kikiliki.'),
('kam', 'JHN', 19, 21, 'Na kwondũ wa ũũ athembi anene ma Ayuti mamwĩa Vilato, Ndũkaandĩke, Mũsumbĩ wa Ayuti, ĩndĩ, andĩka kana aisye, Ninyie Mũsumbĩ wa Ayuti.'),
('kam', 'JHN', 19, 22, 'Vilato amasũngĩa, Ũla naandĩka nĩnamina kũandĩka.'),
('kam', 'JHN', 19, 23, 'Na ĩndĩ asikalĩ mamina ũmwamba Yesũ, moosa ngũa syake na maaan’ya ianda inya, kĩla mũsikalĩ kĩanda kyake; o na ngũa yake ya ĩũlũ: ngũa ĩsu ndyaĩ nduman’ye, yaĩ o ĩmwe kuma mũthya kũvika yonthe.'),
('kam', 'JHN', 19, 24, 'Na kwondũ wa ũu maisye, Tũikatembũe, ĩndĩ tũlimane, tũmanye ũla ĩnĩkũtw’ĩka yake: nĩ kana maandĩko meanĩw’e, ala maĩtye, Nĩmaaanisye ngũa syakwa katĩ woo, Na kwondũ wa kĩtonyeo kyakwa nĩmakĩlimanĩle.'),
('kam', 'JHN', 19, 25, 'Ũu nĩw’o asikalĩ meekie. Na vu ngelan’yonĩ ya Yesũ vaũngeme inyia wake, na mwĩĩtũ‐a‐inyia wa nyinyia, Meli kĩveti kya Kilova, na Meli Makatelene.'),
('kam', 'JHN', 19, 26, 'Na ĩndĩ Yesũ amwona nyinyia, na mũmanyĩw’a ũla wendetwe nĩwe maũngeme vakuvĩ, amwĩa inyia wake, Kĩveti, sisya, ũũ nĩwe mwana waku!'),
('kam', 'JHN', 19, 27, 'Na amwĩa ũla mũmanyĩw’a, Sisya, ũũ nĩwe inyia waku! Na kuma saa ũsu ũla mũmanyĩw’a amwosa amwĩkalya kwake.'),
('kam', 'JHN', 19, 28, 'Na ĩtina wa ũu Yesũ amanya kana maũndũ onthe nĩmathelile, nĩ kana maandĩko meanĩw’e, asya, Nĩ na waũni.'),
('kam', 'JHN', 19, 29, 'Na vaiĩtwe nzele vo yausũĩtwe siki: na manyw’ĩthya sivanzi siki yakola, mamĩkĩa ĩsevenĩ ya mũtĩ wa ĩsovo na matwaa kanyw’anĩ wake.'),
('kam', 'JHN', 19, 30, 'Na Yesũ avivita ũla siki, asya, Nĩwathela: na enamya mũtwe, na aumya veva wake.'),
('kam', 'JHN', 19, 31, 'Na ĩndĩ Ayuti, nũndũ kwaĩ Ũseũvyo, kana simba itikekale ngelan’yonĩ mũthenya wa savato (nũndũ savato ũsu waĩ mũthenya mũnene), mamũvoya Vilato maũũ moo matũlwe, nĩ kana simba ivetwe.'),
('kam', 'JHN', 19, 32, 'Na ĩndĩ asikalĩ mooka, matũla ũla wa mbee maũũ, na ũla ũngi wambiwe nake:'),
('kam', 'JHN', 19, 33, 'ĩndĩ mavika vala ve Yesũ, na meethĩa nũkwie, maiaamũtũla maũũ:'),
('kam', 'JHN', 19, 34, 'ate o mũsikalĩ ũmwe wamũtonyie mbaunĩ na ĩtumo, na oyu vauma nthakame na manzĩ.'),
('kam', 'JHN', 19, 35, 'Na ũla wonie nĩwe ngũsĩ, na ũkũsĩ wake nĩ wa w’o: nake nĩwĩsĩ kana eneena w’o, nĩ kana nenyu mwĩtĩkĩle.'),
('kam', 'JHN', 19, 36, 'Maũndũ aa meekiwe, kana maandĩko meanĩw’e ala maĩtye, Vai ĩvĩndĩ yake yĩkatũlwa.'),
('kam', 'JHN', 19, 37, 'Na maandĩko angĩ maĩtye, Makamũsisya ũla matonyie.'),
('kam', 'JHN', 19, 38, 'Na ĩtina wa maũndũ asu Yosevu, mũndũ wa ndũa ya Alimathia, nake aĩ mũmanyĩw’a wa Yesũ, ĩndĩ kwa kĩmbithĩ nũndũ wa ũkĩa Ayuti, amũvoya Vilato anengwe ũthei wa kwosa mwĩĩ wa Yesũ: na Vilato eetĩkĩla. Nake athi oosa mwĩĩ wake.'),
('kam', 'JHN', 19, 39, 'Na Nikotemo nake ũla waendie mbee kwa Yesũ na ũtukũ, athi akuĩte mũvulan’yo wa manemane na uuti, ũvikya latili ĩana.'),
('kam', 'JHN', 19, 40, 'Namo moosa mwĩĩ wa Yesũ, na moolingĩla ngũa sya katane vamwe na ũla mũvulan’yo wa mĩtĩ ĩla ĩnyungaa nesa, o ũndũ Ayuti mekaa makĩnzĩa nthĩ.'),
('kam', 'JHN', 19, 41, 'Na vakuvĩ na vala wambiwe vaĩ mũũnda; na mũũndanĩ vaĩ mbũa nzaũ, ĩla ĩtaamba kwiwa mũndũ.'),
('kam', 'JHN', 19, 42, 'Vandũ vau nũndũ wa Ũseũvyo wa Ayuti (nũndũ mbũa yaĩ vakuvĩ) nĩvo mamwiie Yesũ.'),
('kam', 'JHN', 20, 1, 'Na mũthenya wa mbee wa kyumwa Meli Makatelene athi mbũanĩ tene, kwĩ kĩvindũ, na oona ĩvia yĩ ĩvete mbũanĩ.'),
('kam', 'JHN', 20, 2, 'Na kwondũ wa ũu athi asembete vala ve Simoni Vetelo, na mũmanyĩw’a ũngĩ ũla wendetwe nĩ Yesũ, na amea, Nĩmaumisye Mwĩaĩi mbũanĩ mamũtwaa, na tũtyĩsĩ vala mamwĩĩte.'),
('kam', 'JHN', 20, 3, 'Na ĩndĩ Vetelo aumaala, e na mũmanyĩw’a ũla ũngĩ, na mathi maelete mbũanĩ.'),
('kam', 'JHN', 20, 4, 'Na masemba me elĩ: ĩndĩ mũmanyĩw’a ũla ũngĩ akĩlya Vetelo maũũ, na amba ũvika mbũanĩ:'),
('kam', 'JHN', 20, 5, 'na akunĩkĩla, na oona ngũa sya katane ila walingĩlwe syĩ nthĩ; ĩndĩ ndaavota nthĩnĩ.'),
('kam', 'JHN', 20, 6, 'Na ĩndĩ Simoni Vetelo nake ooka, amũvikĩlĩte, na avota mbũanĩ nthĩnĩ; nake oona ila ngũa sya katane syĩ nthĩ,'),
('kam', 'JHN', 20, 7, 'na kĩtambaa, kĩla kĩnaĩ mũtwe wake, kĩte na ila ngũa sya katane, ĩndĩ kĩkũnzĩtwe kĩ vandũ vakyo.'),
('kam', 'JHN', 20, 8, 'Na ĩndĩ mũmanyĩw’a ũla wambie ũvika mbũanĩ avota, nake oona, na eetĩkĩla.'),
('kam', 'JHN', 20, 9, 'Nũndũ maiaĩ manamba ũmanya maandĩko, kana ndatĩa kũthayũũka kuma akw’ũnĩ.'),
('kam', 'JHN', 20, 10, 'Na ĩndĩ amanyĩw’a asu menũka.'),
('kam', 'JHN', 20, 11, 'Ĩndĩ Meli aũngeme mbũanĩ nza akĩĩa: na akĩĩa, akunĩkĩla mbũanĩ nthĩnĩ;'),
('kam', 'JHN', 20, 12, 'na oona alaĩka elĩ mekĩe ngũa nzaũ mailyĩ, ũmwe ngalĩ ya mũtwe, na ũmwe ngalĩ ya maũũ, vala mwĩĩ wa Yesũ ũnaiĩtwe.'),
('kam', 'JHN', 20, 13, 'Na mamũkũlya, Mũndũ mũka, wĩĩw’a nĩ kyaũ? Amea, Nũndũ nĩmatwaie Mwĩaĩi wakwa, na ndyĩsĩ vala mamwiie.'),
('kam', 'JHN', 20, 14, 'Na ĩndĩ aneena ũu, eethyũũa, na oona Yesũ aũngeme, na ndeesĩ kana nĩ Yesũ.'),
('kam', 'JHN', 20, 15, 'Yesũ amũkũlya, Mũndũ mũka, wĩĩw’a nĩ kyau? Wĩmantha ũũ? Nake, atalĩlya kana nĩ mũsũvĩi wa mũũnda, na amwĩa, Vwana, ethĩwa nue ũmumisye vaa, ndavya vala ũmwiie, na nĩngũmwosa.'),
('kam', 'JHN', 20, 16, 'Yesũ amwĩa, Meli. Nake eethyũũa, na aneena Kĩevelania, Lavoni: ũalyũlo nĩ, Mũmanyĩsya.'),
('kam', 'JHN', 20, 17, 'Yesũ amwĩa, Manya ũngiita; nũndũ ndinamba kwambata kwa Asa: ĩndĩ thi kwa ana‐a‐asa makwa, noimatavya, Nyie nĩngwambata kwa Asa wakwa, na nĩwe Ĩthe wenyu, na kwa Ngai wakwa, na nĩwe Ngai wenyu.'),
('kam', 'JHN', 20, 18, 'Na Meli Makatelene athĩ amatavya amanyĩw’a ũndũ wamwona Mwĩaĩi; na ũndũ wamũtavya maũndũ asu.'),
('kam', 'JHN', 20, 19, 'Na mũthenya o ũsu wa mbee wa kyumwa, kwatuka, na mĩomo ĩvingĩtwe vala amanyĩw’a maĩ, nũndũ wa kũkĩa Ayuti, Yesũ ooka aũngama katĩ woo, na amea, Ĩthĩwai na mũuo.'),
('kam', 'JHN', 20, 20, 'Na asya ũu, amon’ya itaa syake na mbaunĩ kwake. Na kwondũ wa ũu amanyĩw’a matana, mamwona Mwĩaĩi.'),
('kam', 'JHN', 20, 21, 'Na ĩndĩ Yesũ amea ĩngĩ, Ĩthĩwai na mũuo: o ũndũ Asa wandũmie, nĩw’o ngũmũtũma.'),
('kam', 'JHN', 20, 22, 'Na asya ũu, amavevea, na amea, Osai Veva Mũtheu:'),
('kam', 'JHN', 20, 23, 'O ala mũũekea naĩ syoo, namo nĩmekũekewa; na ala mũtekũekea naĩ syoo, matikũekewa.'),
('kam', 'JHN', 20, 24, 'Ĩndĩ Thoma, ũmwe wa ala ĩkũmi na elĩ, wetawa Ĩvatha, ndaĩ vamwe na ala angĩ yĩla Yesũ wokie.'),
('kam', 'JHN', 20, 25, 'Ĩndĩ amanyĩw’a ala angĩ mamwĩa, Nĩtwamwona Mwĩaĩi. Ĩndĩ we amea, Ndanona matonya ma mĩsumaa itaanĩ syake, na ngekĩa kyaa kyakwa matonyanĩ ma mĩsumaa, na ngekĩa kw’oko kwakwa mbaunĩ kwake, ndiketĩkĩla nongi.'),
('kam', 'JHN', 20, 26, 'Na matukũ nyanya mathela amanyĩw’a make maĩ nyũmbanĩ nthĩnĩ ĩngĩ, na Thoma aĩ vamwe nao. Na Yesũ ooka, mĩomo ĩ mĩvinge, na aũngama katĩ wamo, na asya, Ĩthĩwai na mũuo.'),
('kam', 'JHN', 20, 27, 'Na ĩndĩ amwĩa Thoma, Ete kyaa kyaku vaa, noiona itaa syakwa; na ete kw’oko kwaku, wĩkĩe mbaunĩ kwakwa: na ndũkethĩwe ũtetĩkĩlĩte, ĩndĩ wĩthĩwe wĩtĩkĩlĩte.'),
('kam', 'JHN', 20, 28, 'Thoma amũsũngĩa amwĩa, Mwĩaĩi wakwa na Ngai wakwa!'),
('kam', 'JHN', 20, 29, 'Yesũ amwĩa, Wetĩkĩla nũndũ wambona: nĩ aathime ala matonete na nĩmetĩkĩlĩte.'),
('kam', 'JHN', 20, 30, 'Na kwĩ syama ingĩ mbingĩ ila Yesũ wekie amanyĩw’a make me vo, ĩtaandĩkĩtwe ĩvukunĩ yũ:'),
('kam', 'JHN', 20, 31, 'ĩndĩ ii niandĩkĩtwe, nĩ kana mwĩtĩkĩle atĩ Yesũ nĩwe Klĩsto, Mwana wa Ngai; na ũndũ wa kwĩtĩkĩla kwenyu mwĩthĩwe na thayũ syĩtwanĩ yake.'),
('kam', 'JHN', 21, 1, 'Ĩtina wa maũndũ aa Yesũ eeyonan’ya ĩngĩ kwa amanyĩw’a make ũtee wa ũkanga wa Tivelia; na kwĩyonan’ya kwake kwailyĩ ũũ.'),
('kam', 'JHN', 21, 2, 'Simoni Vetelo, na Thoma ũla wetawa Ĩvatha, na Nathanaeli wa ndũa yĩtawa Kena ya Kalilii, na ala ana ma Sevetii, na angĩ elĩ ma amanyĩw’a make maĩ vamwe.'),
('kam', 'JHN', 21, 3, 'Simoni Vetelo amea, Nĩngũthi kũtea makũyũ. Namo mamwĩa, O naitũ nĩtũũthi naku. Na maumaala mathi malika ngalawanĩ; na ũtukũ ũsu maiaakwatya kĩndũ.'),
('kam', 'JHN', 21, 4, 'Na kũikya. Yesũ aũngama ũtee wa ũkanga: ĩndĩ amanyĩw’a maieesĩ kana nĩ Yesũ.'),
('kam', 'JHN', 21, 5, 'Na ĩndĩ Yesũ amea, Syana, mwĩ na kya ũya? Mamũsũngĩa, Aiee.'),
('kam', 'JHN', 21, 6, 'Na amea, Ĩkyai kĩtei ngalĩ ya kw’oko aũme kwa ngalawa, na nĩmũkwona. Na ĩndĩ mekya, na yu maemwa nĩ ũkusya nũndũ wa makũyũ kwingĩva.'),
('kam', 'JHN', 21, 7, 'Na ĩndĩ mũmanyĩw’a ũla wendetwe nĩ Yesũ amwĩa Vetelo, Nĩ Mwĩaĩi. Na Simoni Vetelo eew’a kana nĩ Mwĩaĩi, oosa ngũa yake eevotoa (nũndũ aĩ mũthei), na eeyĩkya ũkanganĩ.'),
('kam', 'JHN', 21, 8, 'Ĩndĩ amanyĩw’a ala angĩ mookie na kakalawa kala kanini (nũndũ maiaĩ kũasa na ũtee, no vandũ va mĩkono maana elĩ), makĩkusya kĩtei kyusũĩte makũyũ.'),
('kam', 'JHN', 21, 9, 'Na maumĩla nthĩ, moona mwaki wa makaa vo, na ĩkũyũ yiĩtwe ĩũlũ, na kĩmũtũ.'),
('kam', 'JHN', 21, 10, 'Yesũ amea, Etei makũyũ amwe ma ala mwakwatya oyu.'),
('kam', 'JHN', 21, 11, 'Na ĩndĩ Simoni Vetelo alika ngalawanĩ, na akusya kĩtei ũtee, nakyo kyausũĩte makũyũ manene, ĩana yĩnwe na mĩongo ĩtano na atatũ: o na makũyũ maingĩvĩte ũu, kĩtei kĩtyaatembũka.'),
('kam', 'JHN', 21, 12, 'Yesũ amea, Ũkai mwĩtw’a ĩta. Na vai ũmwe wa amanyĩw’a waatata kũmũkũlya, We, nue ũũ? Nũndũ nĩmeesĩ kana nĩ Mwĩaĩi.'),
('kam', 'JHN', 21, 13, 'Yesũ athi, na oosa kĩmũtũ, na amanenga, na makũyũ ta ũu.'),
('kam', 'JHN', 21, 14, 'Na ĩvinda yĩu nĩ ya katatũ Yesũ akĩyonan’ya kwa amanyĩw’a make, ĩtina wa athayũũka kuma kwa akw’ũ.'),
('kam', 'JHN', 21, 15, 'Na ĩndĩ meetw’a ĩta, Yesũ amũkũlya Simoni Vetelo, Simoni, mwana wa Yona, nũmbendete mbee wa aa? Amũsũngĩa, Ĩĩ, Mwĩaĩi; we nĩwĩsĩ kana nĩngwendete. Amwĩa, Ĩthya tũlondu twakwa.'),
('kam', 'JHN', 21, 16, 'Na amũkũlya ĩngĩ ya kelĩ, Simoni, mwana wa Yona, nũmbendete? Amwĩa, Ĩĩ, Mwĩaĩi; we nĩwĩsĩ kana nĩngwendete. Amwĩa, Ĩthya malondu makwa.'),
('kam', 'JHN', 21, 17, 'Na amũkũlya ĩngĩ ya katatũ, Simoni, mwana wa Yona, nũmbendete? Na Vetelo amaka nũndũ wamũkũlya katatũ, Nũmbendete? Na amwĩa, Mwĩaĩi, nĩwĩsĩ maũndũ onthe; nĩwĩsĩ kana nĩngwendete. Yesũ amwĩa, Ĩthya malondu makwa.'),
('kam', 'JHN', 21, 18, 'Nĩ w’o, nĩ w’o, nĩngũkwĩa, Yĩla waĩ mwanake, weevotoaa, ũkathi kũla ũkwenda: ĩndĩ yĩla wĩtumĩa, ũkatambũũkya moko maku, na ũngĩ akakũvotoa, na kũkũtwaa kũla ũtekwenda.'),
('kam', 'JHN', 21, 19, 'Na aneenie ũu, akyonan’ya kĩkw’ũ kĩla ũkamũtaĩa Ngai nakyo. Na amina ũneena ũu, amwĩa, Mbikĩla.'),
('kam', 'JHN', 21, 20, 'Na Vetelo, eethyũũa, amwona ũla mũmanyĩw’a wendetwe nĩ Yesũ aimaatĩĩa; nake nĩwe ũla wamwaĩĩe Yesũ kĩthũinĩ makĩya lĩu wa wĩoo, aimũkũlya, Mwĩaĩi, nũũ ũsu wĩkũvũnyanĩa?'),
('kam', 'JHN', 21, 21, 'Na ĩndĩ Vetelo amwona ũsu amũkũlya Yesũ, Mwĩaĩi, mũndũ ũũ nake, akeka ata?'),
('kam', 'JHN', 21, 22, 'Yesũ amwĩa, Ethĩwa nĩngwenda ekale mũvaka yĩ ngoka, wĩ ũndũ wa kĩ? We mbikĩla.'),
('kam', 'JHN', 21, 23, 'Na ĩndĩ ndeto ĩno yanyaĩĩka katĩ wa ana‐a‐ithe, kana mũmanyĩw’a ũsu ndakakw’a: o na tiw’o Yesũ waisye kana ndakakw’a; ĩndĩ, Ethĩwa ngenda ekale mũvaka yĩ ngoka, wĩ ũndũ wa kĩ?'),
('kam', 'JHN', 21, 24, 'Ũũ nĩwe mũmanyĩw’a ũla ũkũsĩĩaa maũndũ aa, na nĩwe ũandĩkĩte maũndũ aa: na ũkũsĩ wake nĩtwĩsĩ ni wa w’o.'),
('kam', 'JHN', 21, 25, 'Na kwĩ maũndũ angĩ maingĩ ala Yesũ wekie, nao makaandĩkwa, ũmwe na ũmwe, nĩasya nthĩ nima ndĩanĩa mavuku ala maandĩkwa.'),
('kam', 'ACT', 1, 1, 'Theovilo, naandĩkie ũvoo wa mbee wa maũndũ onthe ala Yesũ wambĩlĩlye kwĩka na kũmanyĩsya,'),
('kam', 'ACT', 1, 2, 'kũvika mũthenya ũla wosiwe ĩũlũ, amina kũmatiĩa atũmwa ala wanyuvie mĩao e nthĩnĩ wa Veva Mũtheu:'),
('kam', 'ACT', 1, 3, 'na nĩweyonanisye mwene kwamo na mawonan’yo maingĩ ma w’o, e thayũ, ĩtina wa kũnyamaa kwake, akĩmaumĩlĩla ĩvinda ya mĩthenya mĩongo ĩna, na aineena maũndũ ma ũsumbĩ wa Ngai:'),
('kam', 'ACT', 1, 4, 'na ombanĩte nao, ameaĩa maikaume Yelusaleme, ĩndĩ meteele watho wa Asa, ũla mweewie nakwa:'),
('kam', 'ACT', 1, 5, 'nũndũ nĩ w’o Yoana nĩwavatisie na kĩw’ũ; ĩndĩ inyw’ĩ mũkavatiswa na Veva Mũtheu ĩtina wa mĩthenya mĩvũthũ.'),
('kam', 'ACT', 1, 6, 'Na indĩ, yĩla moombanĩte vamwe, mamũkũlya, maiasya, Mwĩaĩĩ, ũkatũngĩa Isilaeli ũsumbĩ ĩvinda yĩĩ twĩ nayo?'),
('kam', 'ACT', 1, 7, 'Nake amea, Ti ũndũ wenyu kũmanya syathĩ na mavinda, ala Asa wiĩte ũkũmũnĩ wake mwene.'),
('kam', 'ACT', 1, 8, 'Ĩndĩ mũkoosa vinya, yĩla Veva Mũtheu wĩũka ĩũlũ wenyu: na mũkeethĩwa mwĩ ngũsĩ syakwa Yelusaleme, na Yutia yonthe, na Samalia, na kũvika itulu sya nthĩ.'),
('kam', 'ACT', 1, 9, 'Na amina kũneena maũndũ asu, ambatw’a ĩũlũ masyaĩtye; na ĩthweo yamwosa auma methonĩ moo.'),
('kam', 'ACT', 1, 10, 'Na maketee mũno ĩtunĩ eyĩendee, sisya, aũme elĩ maũngama nao mekĩĩte ngũa nzaũ;'),
('kam', 'ACT', 1, 11, 'nao masya, Inyw’ĩ andũ ma Kalilii, nĩkĩ mũkũũngama mũkĩsisya ĩtunĩ? Yesũ ũsu, ũla woswa ĩũlũ ĩtunĩ kuma vala mũĩ, akooka o ta ũu, o ũndũ mwamwona aithi ĩtunĩ.'),
('kam', 'ACT', 1, 12, 'Na indĩ maalũka Yelusaleme mauma kĩĩma kĩtawa Oliveti, kĩla kĩ vakuvĩ na Yelusaleme, mũendo wa mũthenya wa savato.'),
('kam', 'ACT', 1, 13, 'Na malika nthĩnĩ, mambata mavota nyũmbanĩ ya ĩũlũ, vala mekalaa; Vetelo na Yoana na Yakovo na Andalea, Vilivu na Thoma, Valitholomayo na Mathayo, Yakovo wa Alivaio, na Simoni Nzelote, na Yutasi wa Yakovo.'),
('kam', 'ACT', 1, 14, 'Asu onthe mekalaa na ngoo ĩmwe makĩvoya na kĩthing’ĩĩsyo, vamwe na ala aka, na Meli, inyia wa Yesũ, na ana‐a‐inyia make.'),
('kam', 'ACT', 1, 15, 'Na mĩthenya ĩsu Vetelo aũngamie kati wa ana‐a‐ĩthe, na asya, (na maĩ aingĩ mombanĩte vamwe, ũtalo woo waĩ ta ĩana na mĩongo ĩlĩ),'),
('kam', 'ACT', 1, 16, 'Ana‐a‐asa, nĩkwaĩle ũla ũandĩko wĩanĩw’e, ũla Veva Mũtheu wambie ũneena na kanyw’a wa Ndaviti ũndũ wa Yutasi, ũla waĩ mũtongoi wa ala mamũkwatie Yesũ.'),
('kam', 'ACT', 1, 17, 'Nĩkwĩthiwa atalĩlanaw’a naitũ, na nĩwosie kĩanda kyake ũthũkũminĩ ũũ.'),
('kam', 'ACT', 1, 18, '(Na ĩndĩ mũndũ ũsu athooie mũũnda na ĩtuvi ya ũthũku wake; na avalũka na ĩvu, aatũkanĩla katĩ, na maa make onthe metĩka.'),
('kam', 'ACT', 1, 19, 'Na ũndũ ũsu wamanyĩkie nĩ onthe ala matwĩe Yelusaleme; na ũu watumie mũũnda ũsu wĩtwa kĩthyomonĩ kyoo Akelitama, na ũalyũlo wayo nĩ, Mũũnda wa nthakame.)'),
('kam', 'ACT', 1, 20, 'Nũndũ nĩkũandĩkĩtwe ĩvukunĩ ya Savuli, Ũtũo wake nĩwĩthĩwe mũthei, Na mũndũ o na wĩva ndakaaũtũe: na, Ũsyaĩĩsyo wake nĩwoswe nĩ ũngĩ.'),
('kam', 'ACT', 1, 21, 'Kwondũ wa ũu, nĩkwaĩle mũndũ ũmwe wa asu ala maatĩanĩe naitũ mĩthenya yonthe ĩla Mwĩaĩi Yesũ wavotaa na kuma katĩ waitũ,'),
('kam', 'ACT', 1, 22, 'kuma ũvatiso wa Yoana, kũvika mũthenya ũla wosiwe ĩũlũ kuma vala tũĩ, ethĩwe ngũsĩ ya kũthayũũka kwake, vamwe naitũ.'),
('kam', 'ACT', 1, 23, 'Na maia andũ elĩ, Yosevu wetawa Valisava, ũla waĩ na syĩtwa yĩngĩ Yusito, na Mathia.'),
('kam', 'ACT', 1, 24, 'Na mavoya, maiasya, We, Mwĩaĩi, ũla wĩsĩ ngoo sya andũ onthe, twon’ye ũla ũnyuvĩte wa aa elĩ,'),
('kam', 'ACT', 1, 25, 'ose ũthũkũmi na ũtũme ũũ, ũla waumiwe nĩ Yutasi nĩ kana aende vandũ vake mwene.'),
('kam', 'ACT', 1, 26, 'Nao malimana na wamũvalũkĩla Mathia; nake atalanĩlwa vamwe na ala atũmwa ĩkũmi na ũmwe.'),
('kam', 'ACT', 2, 1, 'Na mũthenya wa Vendekosito wavika, meethĩwa mombanĩte onthe vandũ vamwe.'),
('kam', 'ACT', 2, 2, 'Na oyu, o ĩmwe, kwauma kĩuumo ĩtunĩ ta kĩseve kĩnene kĩiuutana, nakyo kyausũa nyũmba yonthe vala mekalĩte.'),
('kam', 'ACT', 2, 3, 'Na maumĩlĩlwa nĩ nĩmĩ sya mwaki syĩaanĩtye; na kwĩkalĩla kĩla mũndũ.'),
('kam', 'ACT', 2, 4, 'Na onthe mausũwa nĩ Veva Mũtheu, na mambĩlĩlya ũneena na ithyomo ingĩ, o ũndũ Veva wamanengie ũneeni.'),
('kam', 'ACT', 2, 5, 'Na Yelusaleme kwekalĩte Ayuti, akĩi ma Ngai, ala maumĩte mbaĩnĩ syonthe sya andũ ĩtheo wa ĩtu.'),
('kam', 'ACT', 2, 6, 'Na wasya ũsu weew’ĩka, ĩkomano yakomana, na yasaanĩw’a, nĩkwĩthĩwa kĩla mũndũ nĩwamewie maineena na kĩthyomo kyake mwene.'),
('kam', 'ACT', 2, 7, 'Na onthe maseng’a na masũanĩwa, maiasya, Sisyai, andũ aa onthe meũneena ti Akalilii?'),
('kam', 'ACT', 2, 8, 'Na twĩĩw’a ata ithyĩ, kĩla mũndũ na kĩthyomo kyake mwene, kĩla wasyaiwe nakyo?'),
('kam', 'ACT', 2, 9, 'Avathiani na Ametia na Aelamu, na andũ ala matwĩe Mesovotamia na Yutia na Kavatosia na Vondo na Asia,'),
('kam', 'ACT', 2, 10, 'na Velikia na Vambilia, na Misili na ngalĩ sya Livia vakuvĩ na Kulene, na ekali ma ũeninĩ maumĩte Lomi, Ayuti na avikĩli moo,'),
('kam', 'ACT', 2, 11, 'na Akilete na Alavu, nĩtũkũmew’a aa maineena na ithyomo sitũ maũndũ manene ma Ngai.'),
('kam', 'ACT', 2, 12, 'Na onthe maseng’a, na masũanĩwa, maiasya ene kwa ene, Ũndũ ũũ wĩonan’ya ata?'),
('kam', 'ACT', 2, 13, 'Ĩndĩ angĩ masya, maivũthya, Aa nĩmatoonetw’e nĩ mbinyu mbĩthĩ.'),
('kam', 'ACT', 2, 14, 'Ĩndĩ Vetelo, aũngeme na ala ĩkũmi na ũmwe, atũlya wasya wake, na aneena namo, aiasya, Inyw’ĩ aũme ma Yutia, na inyw’onthe ala mũtwĩe Yelusaleme, ũndũ ũũ nũmanyĩke kwenyu, na ĩthukĩĩsyei ndeto syakwa.'),
('kam', 'ACT', 2, 15, 'Nĩkwĩthĩwa andũ aa ti atoon’ye, ũndũ mũũtalĩlya; nũndũ no saa itatũ sya mũthenya;'),
('kam', 'ACT', 2, 16, 'ĩndĩ ũndũ ũũ nĩ ũla waneeniwe nĩ mwathani Yoeli:'),
('kam', 'ACT', 2, 17, 'Na kũkeethĩwa mĩthenyanĩ ya mũminũkĩlyo, easya ũu Ngai, Ngamĩtulũĩla mĩĩ yonthe Veva wakwa: Na ana menyu na eĩtu menyu makathana, Na anake menyu makoona mawoni, Na atumĩa menyu makaota ndoto:'),
('kam', 'ACT', 2, 18, 'Ĩĩ, ĩũlũ wa ngombo syakwa aũme na aka mĩthenyanĩ ĩsu Ngatulũla Veva wakwa; nasyo ikathana.'),
('kam', 'ACT', 2, 19, 'Na ngoonan’ya moseng’yo ĩũlũ ĩtunĩ, Na syama ĩtheo nthĩ; Nthakame, na mwaki, na ũtoi wa syũki:'),
('kam', 'ACT', 2, 20, 'Syũa yĩkaalyũkw’a yĩthĩwe kĩvindu, Na mwei wĩthĩwe nthakame, Mbee wa mũthenya wa Mwĩaĩĩ ũtanoka, Mũthenya ũla mũnene na mwonan’ye:'),
('kam', 'ACT', 2, 21, 'Na kũkeethĩwa, o ũla ũkekaĩla. Syĩtwa ya Mwĩaĩi nũkatangĩĩwa.'),
('kam', 'ACT', 2, 22, 'Inyw’ĩaũme ma Isilaeli, ĩthukĩĩsyei ndeto ii: Yesũ wa Nasaleti, ũla wonaniw’e nĩ Ngai kwenyu na mavinya na momakyo na syama ila Ngai wekie nake katĩ wenyu, o ũndũ inyw’ĩ ene mwĩsĩ;'),
('kam', 'ACT', 2, 23, 'we, anenganiwe o tondũ Ngai watwie na wamanyĩte kuma tene, inyw’i mwamwambie na kũmũaa na moko ma ala ang’endu:'),
('kam', 'ACT', 2, 24, 'ũla Ngai wamũthayũũkisye, athaĩtye mawoo ma kĩkw’ũ: nĩkwĩthĩwa kũiaatonyeka alũmw’e nĩkyo.'),
('kam', 'ACT', 2, 25, 'Nũndũ Ndaviti aneenie ũvoo wake, aiasya, Nĩnoonie Mwĩaĩi mbee wa ũthyũ wakwa mavinda onthe; Nĩkwĩthĩwa we e ngalĩ ya kw’oko kwakwa kwa aũme, nĩ kana ndikathingithangw’e:'),
('kam', 'ACT', 2, 26, 'Kwondũ wa ũu ngoo yakwa yaĩ na ũtanu, na ũĩmĩ wakwa watana; O na ĩngĩ mwĩĩ wakwa ũkatũaa wĩkwatyonĩ:'),
('kam', 'ACT', 2, 27, 'Nũndũ we ndũkatia veva wakwa vala maveva ma akw’ũ mekalaa, O na ndũkanengane Mũtheu waku one wanangĩko.'),
('kam', 'ACT', 2, 28, 'We, nĩwamanyĩthye nzĩa sya thayũ; We, ũkambusũasya ũtanu na ũthyũ waku.'),
('kam', 'ACT', 2, 29, 'Ana‐a‐asa, nĩtonya kũneena nenyu vyũ, ũvoo wa mũtũmĩa Ndaviti, kana nĩwakwie na akĩnzĩwa nthĩ, na vala wenzĩĩwe ve o kwitũ kũvika mũthenya ũũ wa ũmũnthĩ.'),
('kam', 'ACT', 2, 30, 'Nũndũ aĩ mwathani na amanya kana Ngai nĩwevĩtie kwake na wĩvĩto, atĩ kuma ũsyaonĩ wa kĩnyunyu kyake, akamwĩkalya ũmwe kĩvĩlanĩ kyake kya ũsumbĩ;'),
('kam', 'ACT', 2, 31, 'we, onete ũndũ ũsu mbee, aneena ũvoo wa kũthayũũka kwa Klĩsto, kana ndaatiwa vala maveva ma akw’ũ mekalaa, o na mwĩĩ wake ndwaaona wanangĩko.'),
('kam', 'ACT', 2, 32, 'Yesũ ũsu Ngai nĩwamũthayũũkisye, naitũ ithyonthe twĩ ngũsĩ sya ũũ.'),
('kam', 'ACT', 2, 33, 'Ĩndĩ nĩkwĩthĩwa nĩwaneneviw’e kw’okonĩ kwa aũme kwa Ngai, na oosete kwa Ĩthe ũla watho wa Veva Mũtheu, nĩwonoisye ũndũ ũũ, ũla mũkwona na kwĩw’a.'),
('kam', 'ACT', 2, 34, 'Nũndũ Ndaviti ndaaambata ĩtunĩ: ĩndĩ we mwene easya, Mwĩaĩi amwĩie Mwĩaĩi wakwa, Ĩkala nthĩ ngalĩ ya kw’oko kwakwa kwa aũme,'),
('kam', 'ACT', 2, 35, 'Mũvaka natw’a amaitha maku kavĩla ka nyaĩĩ syaku.'),
('kam', 'ACT', 2, 36, 'Kwondũ wa ũu nyũmba yonthe ya Isilaeli ĩmanye vyũ, kana Yesũ ũsu ũla inyw’ĩ mwamwambie, Ngai nũmũtw’ĩte ethĩwe Mwĩaĩi, na ĩngĩ ethĩwe Klĩsto.'),
('kam', 'ACT', 2, 37, 'Na meew’a ndeto isu syamatonya ngoonĩ syoo, na mamwĩa Vetelo na atũmwa ala angĩ, Ana‐a‐asa, twĩĩka ata?'),
('kam', 'ACT', 2, 38, 'Na Vetelo amea, Alyũlai ngoo, na mũivatiswa kĩla mũndũ syĩtwanĩ ya Yesũ Klĩsto, mwone ũekeo wa naĩ syenyu; na mũkoosa mũthĩnzĩo wa Veva Mũtheu.'),
('kam', 'ACT', 2, 39, 'Nũndũ watho ũsu nĩ kwondũ wenyu, na kwondũ wa syana syenyu, na kwondũ wa onthe ala me kũasa mũno, o ala maketwa nĩ Mwĩaĩi Ngai waitũ, moke kwake.'),
('kam', 'ACT', 2, 40, 'Na akũsĩĩa na ndeto ingĩ nyingĩ, na amataa, aiasya, Ĩtangĩĩei na ũsyao ũũ mũthyoeku.'),
('kam', 'ACT', 2, 41, 'Na ĩndĩ ala moosie ndeto yake mavatiswa: na mũthenya ũsu mongeleka andũ ta ngili itatũ.'),
('kam', 'ACT', 2, 42, 'Na mekalaa malũlũmĩle momanyĩsyonĩ ma atũmwa, na mũambanĩ, na kũtila kĩmũtũ, na mboya.'),
('kam', 'ACT', 2, 43, 'Na w’ĩa wamũlika kĩla mũndũ: na momakyo maingĩ na syama nyingĩ syeekwa nĩ atũmwa.'),
('kam', 'ACT', 2, 44, 'Na onthe ala meetĩkĩlile maĩ vandũ vamwe, na meethĩwa na mũamba wa syĩndũ syoo syonthe;'),
('kam', 'ACT', 2, 45, 'na mathoosya syĩndũ syoo ila maĩ nasyo, na maaana onthe, kĩla mũndũ o ũndũ waĩ na vata wĩana.'),
('kam', 'ACT', 2, 46, 'Na kĩla mũthenya mekalaa ĩkalũnĩ na ngoo ĩmwe, na makĩtila kĩmũtũ nyũmbanĩ kwoo, nĩmaĩsaa lĩu woo na mũyo na ngoo ĩmwe,'),
('kam', 'ACT', 2, 47, 'makĩmũkumya Ngai, na makyaĩla kwa andũ onthe. Mwĩaĩi, nake, amongelelaa mũthenya na mũthenya ala matangĩĩawa.'),
('kam', 'ACT', 3, 1, 'Na ĩndĩ Vetelo na Yoana mambatie ĩkalũnĩ ĩvinda ya kũvoya, saa kenda.'),
('kam', 'ACT', 3, 2, 'Na kwaĩ mũndũ ũmwe wasyaiwe e kyonze, nake akuawa, akaiwa kĩla mũthenya mũomonĩ wa ĩkalũ ũla wĩtawa Mwanakavye, avoye ũtethyo kwa ala mavotaa ĩkalũnĩ;'),
('kam', 'ACT', 3, 3, 'nake oona Vetelo na Yoana makĩlika ĩkalũnĩ, amavoya anengwe ũtethyo.'),
('kam', 'ACT', 3, 4, 'Na Vetelo, aimũketeea, vamwe na Yoana, asya, Tũsisye.'),
('kam', 'ACT', 3, 5, 'Na amasisya, akyasya nũnũũnengwa kĩndũ nĩmo.'),
('kam', 'ACT', 3, 6, 'Ĩndĩ Vetelo amwĩa, Ndi na vetha kana thaavu; ĩndĩ kĩla nĩ nakyo, nĩkyo ngũũnenga. Syĩtwanĩ ya Yesũ Klĩsto wa Nasaleti, ĩkinyie.'),
('kam', 'ACT', 3, 7, 'Na amũkwata kw’oko kwa aũme kwake amũkĩlya: na kavinda kau nyaĩĩ syake na maleenyũ ma ngũlimũ syake meekĩwa vinya.'),
('kam', 'ACT', 3, 8, 'Na ookĩla na aũngama, na ambĩlĩlya ũkinya; na avota ĩkalũnĩ vamwe nao, aikinya, na aithaanyũkanga, na amũkumya Ngai.'),
('kam', 'ACT', 3, 9, 'Na andũ onthe mamwona aikinya na aimũkumya Ngai:'),
('kam', 'ACT', 3, 10, 'na mamũmanya, kana niwe ũnekalaa aivoya ũtethyo Mũomonĩ Mwanakavye wa ĩkalũ; mausũwa nĩ kũsaanĩw’a na kũseng’a kwondũ wa ũndũ ũsu wamũkĩtĩkĩa.'),
('kam', 'ACT', 3, 11, 'Na amakwete Vetelo na Yoana, andũ onthe mamombania masembete valasyanĩ ũla wĩtawa wa Solomoni, maiseng’a mũno.'),
('kam', 'ACT', 3, 12, 'Na Vetelo oona ũndũ ũsu, amatavya ala andũ, Ĩnyw’ĩ aũme ma Isilaeli, nĩki mũũseng’a nũndũ wa mũndũ ũũ? Kana nĩkĩ mũtũketeea na metho menyu, ta ithyĩ kwa vinya witũ kana ũseo witũ twatuma ũũ ekinyia?'),
('kam', 'ACT', 3, 13, 'Ngai wa Avalaamu, na wa Isaka, na wa Yakovo, Ngai wa aasa maitũ, nũmũtaĩĩte Mũthũkũmi wake Yesũ; ũla inyw’i mwamũnenganie, na kũmũleela mbee wa Vilato, yĩla we watw’ĩte athaw’e.'),
('kam', 'ACT', 3, 14, 'Ĩndĩ inyw’i mwamũleile Ũla Mũtheu na Mũlũngalu, na mweetya mũnengwe mũaani,'),
('kam', 'ACT', 3, 15, 'na mwamũaa ũsu Mũnene wa thayũ; nake Ngai nĩwamũthayũũkisye kũmumya kwa akw’ũ; naitũ twĩ ngũsĩ sya ũndũ ũsu.'),
('kam', 'ACT', 3, 16, 'Na kwondũ wa mũĩkĩĩo syĩtwanĩ yake, syĩtwa yake nĩyamũnenga mũndũ ũũ vinya, ũũ mũmwene na mũmwĩsĩ: ĩĩ, mũĩkĩĩo ũsu ũla wĩ kwondũ wake, nĩwamũnenga ũũ wĩanĩu ũũ mũima mũwene inyw’onthe.'),
('kam', 'ACT', 3, 17, 'Na yu, ana‐a‐asa, nĩona kana nĩmweekie ũu kwa kũlea kũmanya, na asumbĩki menyu no ta ũu.'),
('kam', 'ACT', 3, 18, 'Ĩndĩ maũndũ ala Ngai wonanisye mbee na makanyw’a ma athani onthe, kana Klĩsto wake akathĩnw’a, nĩweanĩisye ũu.'),
('kam', 'ACT', 3, 19, 'Alyũlai ngoo, ĩndĩ, mwĩthyũũe, naĩ syenyu syanangwe, nĩ kana kũtonye kũka mavinda ma ũvuũkyo kuma ũthyũnĩ wa Mwĩaĩi;'),
('kam', 'ACT', 3, 20, 'na ĩngĩ kana atonye kũmũtũma Klĩsto ũla waiĩtwe kwondũ wenyu, nake nĩwe Yesũ:'),
('kam', 'ACT', 3, 21, 'ũla ĩtu yĩnaaĩlwe nĩ ũmwosa kũvika mavinda ma ũtũnga syĩndũ syonthe syĩthĩwe nzaũ, ala Ngai waneenie na makanyw’a ma athani make atheu, ala mai kw’o kuma tene.'),
('kam', 'ACT', 3, 22, 'Nĩ w’o Mose nĩwaneenie aiasya, Mwĩaĩi Ngai akamũkĩlĩlya mwathani kuma kwa ana‐a‐ĩthe menyu, ũilyĩ takwa; mwĩw’ei maũndũnĩ onthe ala ũkaneena nenyu.'),
('kam', 'ACT', 3, 23, 'Na kũkeethĩwa, kana kĩla mũndũ ũtakamwĩthukĩĩsya mwathani ũsu, akaanangwa vyũ na kumw’a katĩ wa andũ.'),
('kam', 'ACT', 3, 24, 'Ĩĩ, na athani onthe kuma Samueli na ala mamũatĩĩe ĩtina, o ũndũ maneenie meana, nao nĩmatavanisye ũvoo wa mĩthenya ĩno.'),
('kam', 'ACT', 3, 25, 'Inyw’i mwĩ ana ma athani, na ma ũtianĩo ũla Ngai watianĩe na aaĩthe menyu, aimwĩa Avalaamu atĩĩ, Ũsyaonĩ waku mĩvĩa yonthe ya andũ ĩkaathimwa.'),
('kam', 'ACT', 3, 26, 'Ngai, amina kũthayũũkya Mũthũkũmi wake, ambie kũmũtũma amũathime inyw’ĩ, aimũthyũũa kĩla ũmwe wenyu mũtie mothũku menyu.'),
('kam', 'ACT', 4, 1, 'Na makĩneena na andũ, athembi anene na mũnene wa ĩkalũ na Asatukai mamaumĩlĩla,'),
('kam', 'ACT', 4, 2, 'makĩw’a woo mũno nũndũ wamo kũmamanyĩsya andũ, na kũtavan’ya ũthayũũkyo wa akw’ũ nthĩnĩ wa Yesũ.'),
('kam', 'ACT', 4, 3, 'Na mamakwata na mamekĩa kolokolonĩ kũvika ũnĩ: nĩkwĩthĩwa kwaĩ kũnavika wĩoo.'),
('kam', 'ACT', 4, 4, 'Ĩndĩ aingĩ ma ala meewie ndeto meetĩkĩlile; na ũtalo wa aũme weethĩwa ta ngili itano.'),
('kam', 'ACT', 4, 5, 'Na ũnĩ ũsu, anene moo na atumĩa na aandĩki meethĩwa mombanĩte vamwe Yelusaleme;'),
('kam', 'ACT', 4, 6, 'na Anasi mũthembi mũnene aĩ vo, na Kaiava na Yoana, na Alesanda, na angĩ o ala maĩ ma mbaĩ ya mũthembi mũnene.'),
('kam', 'ACT', 4, 7, 'Na mamaia katĩ woo, mamakũlya, Undũ ũsu mũneekie kwa vinya wiva, kana kwa syĩtwa yĩva?'),
('kam', 'ACT', 4, 8, 'Nĩvo ĩndĩ Vetelo, ausũĩtwe nĩ Veva Mũtheu, wamasũngĩie, aiasya, Inyw’ĩ asumbĩki ma andũ, na atumĩa,'),
('kam', 'ACT', 4, 9, 'ethĩwa nĩtũũkũlw’a ũmũnthĩ ũndũ wa wĩko mũseo ũla ũneekiwe mũndũ kyonze, ũndũ ũnavoiw’e;'),
('kam', 'ACT', 4, 10, 'nĩkũmanyĩke kwa inyw’onthe, na kwa andũ onthe ma Isilaeli, kana nĩ kwondũ wa syĩtwa ya Yesũ Klĩsto wa Nasaleti, ũla inyw’ĩ mwamwambie, na Ngai nĩwamũthayũũkisye kũmumya kwa akw’ũ, no kwondũ wa ũsu mũndũ ũũ nũũngeme mbee wenyu e mũima.'),
('kam', 'ACT', 4, 11, 'Ũsu nĩwe yĩla ĩvia yavũthiwe nĩ inyw’ĩ aki, nayo yatw’ĩka yĩla ĩnene ya kĩkotonĩ.'),
('kam', 'ACT', 4, 12, 'O na kũti ũtangĩĩo kwa ũngĩ o na wĩva w’onthe: nũndũ kũti syĩtwa yĩngĩ ĩtheo wa ĩtu, yĩnengetwe andũ, yĩtwaĩle ithyĩ kũtangĩĩwa nayo.'),
('kam', 'ACT', 4, 13, 'Na moona ũnyiau wa Vetelo na Yoana, na mamanya kana nĩ andũ matamanyĩĩtw’e, na mate na ũmanyi, maseng’a; na mamamanya kana maneethĩawa vamwe na Yesũ.'),
('kam', 'ACT', 4, 14, 'Na makyona ũla mũndũ ũnavoiw’e aũngeme vamwe nao, maiaatonya kũsũngĩa ũndũ ũsu.'),
('kam', 'ACT', 4, 15, 'Ĩndĩ mamatavya maumaale nza kuma nzamanĩ, makũlan’ya ene kwa ene,'),
('kam', 'ACT', 4, 16, 'maiasya, Twĩmeka ata andũ aa? Nĩkwĩthĩwa nĩwenekee kwa onthe ala matwĩe Yelusaleme kana kyama kĩnene nĩkĩneekiwe kwondũ wamo; na ithyĩ tũtitonya kũkaĩa.'),
('kam', 'ACT', 4, 17, 'Ĩndĩ nĩ kana ũndũ ũũ ndũkanyaĩĩke mbee wa vau andũnĩ, tũmatĩsye, kana maikaneene ĩngĩ na mũndũ syĩtwanĩ yĩu.'),
('kam', 'ACT', 4, 18, 'Na mameta, na mameaĩa maikaaneene ĩngĩ nongĩ kana kũmanyĩsya syĩtwanĩ ya Yesũ.'),
('kam', 'ACT', 4, 19, 'Ĩndĩ Vetelo na Yoana mamasũngĩa, mamea, Ethĩwa nĩ wa w’o mbee wa Ngai kũmwĩthukĩĩsya inyw’ĩ kwĩ kũmwĩthukĩĩsya Ngai, silai inyw’ĩ:'),
('kam', 'ACT', 4, 20, 'nũndũ ithyĩ tũitonya ate o kũneena maũndũ ala twoonie na kwĩw’a.'),
('kam', 'ACT', 4, 21, 'Namo, mamatĩsya ĩngĩ, mamalekya, matene ũndũ matonya kũmasilĩla, nũndũ wa andũ; nĩkwĩthĩwa andũ onthe mamũtaĩaa Ngai kwondũ wa ũndũ ũsu ũneekiwe,'),
('kam', 'ACT', 4, 22, 'Nũndũ mũndũ ũsu ũla ũneekiwe kyama kyu kya ũvow’a, avikĩtye myaka mbee wa mĩongo ĩna.'),
('kam', 'ACT', 4, 23, 'Na mathaw’a, mathi vala ve ala angĩ moo, na mamatavya maũndũ onthe ala mataviw’e nĩ athembi anene na atumĩa.'),
('kam', 'ACT', 4, 24, 'Namo, meew’a ũu, mamũkĩlĩlya Ngai mawasya moo na ngoo ĩmwe, maiasya, Ame Mwĩaĩi, nue woombie ĩtu na nthĩ na ũkanga, na syĩndũ syonthe ila syĩ nthĩnĩ wasyo:'),
('kam', 'ACT', 4, 25, 'we, ũla waneenie kwondũ wa Veva Mũtheu, na kanyw’a wa asa waitũ Ndaviti, mũthũkũmi waku, ũkyasya, Andũ‐ma‐mbaĩ‐ingĩ malonzanĩlye kĩ, Na andũ kũsũanĩa maũndũ ma mana?'),
('kam', 'ACT', 4, 26, 'Asumbĩ ma nthĩ nĩmetaũĩtye, Na asumbĩki nĩmoombanie vamwe, Ĩũlũ wa Mwĩaĩi, na ĩũlũ wa Mwĩtĩkĩw’a mauta wake:'),
('kam', 'ACT', 4, 27, 'nũndũ nĩ w’o ndũanĩ ĩno, Elote na Vondio Vilato vamwe na Andũ‐ma‐mbaĩ‐ingĩ na andũ ma Isilaeli nĩmoombanie vamwe, ĩũlũ wa Mũthũkũmi waku mũtheu Yesũ, ũla wamwĩtĩkĩsye mauta,'),
('kam', 'ACT', 4, 28, 'meke o ala kw’oko kwaku na ũtw’ĩo waku watwie mbee kana methĩwe.'),
('kam', 'ACT', 4, 29, 'Na yu, Mwĩaĩi, sisya motĩsyo moo: noinenga ngombo syaku ineene ndeto yaku na ũnyiau w’onthe,'),
('kam', 'ACT', 4, 30, 'naku wĩthĩwe ũitambũũkya kw’oko kwaku kũvosya; nĩ kana syama na momakyo mekwe kwondũ wa syĩtwa ya Mũthũkũmi waku mũtheu Yesũ.'),
('kam', 'ACT', 4, 31, 'Na mavoya, vala moombanĩte vathingithangw’a; nao mausũwa onthe nĩ Veva Mũtheu, na maneena ndeto ya Ngai na ũnyiau.'),
('kam', 'ACT', 4, 32, 'Na nguthu ya ala meetĩkĩlĩte maĩ na ngoo ĩmwe na veva ũmwe: na vai ũmwe waasya kĩndũ o na kĩmwe kya ila waĩ nasyo nĩ kyake mwene; ĩndĩ maĩ na mũamba wa syĩndũ syonthe.'),
('kam', 'ACT', 4, 33, 'Na atũmwa maumya ũkũsĩ woo wa kũthayũũka kwa Mwĩaĩi Yesũ na vinya mũnene: na mumo mũnene waĩ ĩũlũ wa onthe.'),
('kam', 'ACT', 4, 34, 'Nũndũ vaiaaĩthĩwa ũmwe wamo waanyivĩwa nĩ kĩndũ: nĩkwĩthĩwa ala maĩ na nthĩ kana nyũmba syoo nĩmathooisye, na maete thooa wa syĩndũ ila ithooetw’e,'),
('kam', 'ACT', 4, 35, 'mawia maũũnĩ ma atũmwa: na maana kĩla mũndũ, o ũndũ vata wake weanaa.'),
('kam', 'ACT', 4, 36, 'Na Yosevu, ũla wanengiwe syĩtwa ya kelĩ nĩ ala atũmwa, ya Valanava (nayo ũalyũlo wayo nĩ, Mwana wa ũtao), aĩ Mũlivai, ĩndĩ kũsyaĩwa kwake nĩ Kuvolo,'),
('kam', 'ACT', 4, 37, 'aĩ na mũũnda, na oothoosya, na aete thooa waw’o aia maũũnĩ ma atũmwa.'),
('kam', 'ACT', 5, 1, 'Ĩndĩ mũndũ ũmwe wetawa Anania, vamwe na Savaila mũka wake, athooisye kĩlungu kyake kya nthĩ,'),
('kam', 'ACT', 5, 2, 'na avitha kĩlungu kĩmwe kya thooa wayo, na mũka wake nĩwesĩ, na aete kĩlungu kĩmwe na akia maũũnĩ ma atũmwa.'),
('kam', 'ACT', 5, 3, 'Ĩndĩ Vetelo amũkũlya, Anania, nĩkĩ wausũwa ngoo yaku nĩ Satani ũmũtavye Veva Mũtheu ũvũngũ, na kũsiĩĩa ũvithĩte kĩlungu kya thooa wa nthĩ?'),
('kam', 'ACT', 5, 4, 'Yĩla waĩ nayo ndĩaĩ yaku mwene? Na yathoow’a, ndĩaĩ ũtonyinĩ waku mwene? Kũilyĩ ata ĩndĩ kwĩkĩa ũndũ ũũ ngoonĩ yaku? Ti andũ watavya ũvũngũ, ĩndĩ wamũtavya Ngai.'),
('kam', 'ACT', 5, 5, 'Na Anania eew’a ndeto isu avalũka nthĩ na aumwa nĩ veva: na w’ĩa mũnene wooka ĩũlũ wa onthe ala meewĩe.'),
('kam', 'ACT', 5, 6, 'Na anake mookĩla mamũlingĩla ngũa, mamumaalya nza na mamwĩnzĩa nthĩ.'),
('kam', 'ACT', 5, 7, 'Na ĩtina ĩvinda ya masaa atatũ, mũka wake ooka atesĩ ũndũ kweekwa, na alika.'),
('kam', 'ACT', 5, 8, 'Na Vetelo amwia, Ndavya, mũnathooisye nthĩ thooa o ũsu? Nake amũsũngĩa, Ĩĩ, thooa o ũsu.'),
('kam', 'ACT', 5, 9, 'Ĩndĩ Vetelo amwĩa, Kũilyĩ ata inyw’ĩ kwĩw’ana kũmũtata ũla Veva wa Mwĩaĩi? Sisya, nyaĩĩ sya ala mamwinzia mũemeu nthĩ syĩ mũomoni, nao nĩmeũkũkua we.'),
('kam', 'ACT', 5, 10, 'Nake avalũka oyu maũũnĩ ma Vetelo, na aumwa nĩ veva: na ala anake mavota meethĩa e mũkw’ũ, na mamumaalya nza na mamwĩnzĩa nthĩ ũtee wa mũũme wake.'),
('kam', 'ACT', 5, 11, 'Na w’ĩa mũnene wooka ĩũlũ wa ĩkanisa yonthe, na ĩũlũ wa onthe ala meewie maũndũ asu.'),
('kam', 'ACT', 5, 12, 'Na syama nyingĩ na momakyo meekiwe andũnĩ na moko ma atũmwa: na onthe maĩ na ngoo imwe valasyanĩ wa Solomoni.'),
('kam', 'ACT', 5, 13, 'Ĩndĩ ma ala angĩ vai mũndũ waatata kwĩkwatan’ya nao: ĩndĩ andũ mamataĩaa mũno;'),
('kam', 'ACT', 5, 14, 'na etĩkĩli aingĩ mongeleka ngalĩ ya Mwĩaĩi, nguthu nene sya andũ, aũme na aka:'),
('kam', 'ACT', 5, 15, 'o na kweethĩwa maimaumaalya awau moo kũmatwaa nzĩanĩ nene, na kũmaia mokomonĩ na mĩkekanĩ, nĩ kana Vetelo aivĩta, nongo kyuu kyake kĩtonye kũkiita ũmwe wamo.'),
('kam', 'ACT', 5, 16, 'Na ĩngĩ kwoombana nguthu nene ya andũ ma ndũa ila ithyũlũlũkĩte Yelusaleme, makĩete andũ awau, na ala mathĩnaw’a nĩ maveva mavuku: nao mavow’a onthe.'),
('kam', 'ACT', 5, 17, 'Ĩ ndĩ mũthembi mũnene ookĩla, na onthe ala maĩ nake (namo nĩ kĩthemba kya Asatukai), nao mausũwa nĩ kĩwĩu,'),
('kam', 'ACT', 5, 18, 'na mamakwata atũmwa, mamekĩa kolokolonĩ.'),
('kam', 'ACT', 5, 19, 'Ĩndĩ mũlaĩka wa Mwĩaĩi avingũa mĩomo ya kolokolo na ũtukũ, na amaumaalya nza, amea,'),
('kam', 'ACT', 5, 20, 'Endai, mũkaũngame ĩkalũnĩ, na mũitavya andũ ndeto syonthe sya Thayũ ũũ.'),
('kam', 'ACT', 5, 21, 'Na meew’a ũu mavota ĩkalũnĩ kwĩ masangya, na kũmanyĩsya. Ĩndĩ mũthembi mũnene ooka, na ala maĩ nake, na moomban’ya andũ ma nzama, na atumĩa onthe ma Isilaeli, na matũma andũ mathi kolokolonĩ mamaete.'),
('kam', 'ACT', 5, 22, 'Ĩndĩ makanga ala maendie matyaamethĩa kolokolonĩ; na maalũka, matavan’ya ũvoo,'),
('kam', 'ACT', 5, 23, 'maiasya, Nyũmba ya kolokolo tweethĩa ĩvingĩtwe, nayo ndĩ na ũndũ, na asũvĩi maũngeme mĩomonĩ: ĩndĩ twavingũa, tũinamwĩthĩa mũndũ nthĩnĩ.'),
('kam', 'ACT', 5, 24, 'Na mũnene wa ĩkalũ na athembi anene meew’a ndeto isu, masũanĩwa mũno nĩsyo, na vala ũvoo ũsu wĩvika.'),
('kam', 'ACT', 5, 25, 'Na kwooka mũndũ ũmwe amatavya, Sisyai, andũ ala mũneekĩie kolokolonĩ me ĩkalũnĩ maũngeme maimanyĩsya andũ.'),
('kam', 'ACT', 5, 26, 'Na ĩndĩ ũla mũnene athi vamwe na makanga na mamaete, ĩndĩ ti kwa vinya; nũndũ nĩmakĩaa andũ maikamakime na mavia.'),
('kam', 'ACT', 5, 27, 'Na mamaete, mamaũngamya mbee wa nzama. Na mũthembi mũnene amakũlya,'),
('kam', 'ACT', 5, 28, 'aiasya, Tũtineemũvata mũno na vinya kũmanyisya syĩtwanĩ yĩu? Na sisyai, nĩmũsũĩtye Yelusaleme momanyĩsyo menyu, mũkyenda kũete nthakame ya mũndũ ũsu ĩũlũ waitũ.'),
('kam', 'ACT', 5, 29, 'Ĩndĩ Vetelo na atũmwa ala angĩ masũngĩa, maiasya, Mũvaka tũmwĩw’e Ngai mbee wa kũmew’a andũ.'),
('kam', 'ACT', 5, 30, 'Ngai wa asaa maitũ nĩwamũthayũũkisye Yesũ, ũla inyw’ĩ mwamũaie, mũimwamba mũtĩnĩ.'),
('kam', 'ACT', 5, 31, 'Ĩndĩ we Ngai nũmũnenevetye kw’okonĩ kwake kwa aũme, ethĩwe Mũnene na Mũtangĩĩi, amanenge Isilaeli ũalyũlo wa ngoo, na ũekeo wa naĩ.'),
('kam', 'ACT', 5, 32, 'Na ithyĩ twĩ ngũsĩ sya maũndũ asu; na Veva Mũtheu nake no ta ũu, ũla Ngai ũnengete ala mamwĩw’aa.'),
('kam', 'ACT', 5, 33, 'Namo meew’a ũu matemwa ngoonĩ, na menda kũmoaa.'),
('kam', 'ACT', 5, 34, 'Ĩndĩ mũndũ ũmwe Mũvalisi, wetawa Kamalieli, mũmanyĩsya mũnene wa mĩao, ũla wataĩawa nĩ andũ onthe, aũngama nzamanĩ, na atw’a mamaumaalye andũ asu nza kavinda kanini.'),
('kam', 'ACT', 5, 35, 'Nake amea, Inyw’ĩ aũme ma Isilaeli, ĩsũvĩei ene ũndũ wa andũ aa, ũndũ mũkilĩlye kwĩka.'),
('kam', 'ACT', 5, 36, 'Nikwĩthĩwa mbee wa mĩthenya ĩno Theutasi nũnookĩlile, aimatavya andũ nĩwe ĩkũ; na andũ aingĩ mamũatĩĩa, ũtalo woo wavikĩte ta maana ana: nake nĩwoaiwe; na onthe ala mamwĩw’aa manyaĩĩkw’a, meethĩwa ti kĩndũ.'),
('kam', 'ACT', 5, 37, 'Ĩtina wa mũndũ ũsu, anookĩla Yutasi, mũndũ wa Kalilii, mĩthenya ĩsu ya kũandĩkwa, nake akusya andũ amwe mamũatĩĩa: nake aaa; na onthe, o ala mamwĩw’aa, manyaĩĩkw’a.'),
('kam', 'ACT', 5, 38, 'Yu nĩmwĩa inyw’ĩ, Isiĩĩei na andũ aa, nũmaeke: nũndũ ethĩwa nzama ĩno kana wĩa ũũ nĩ wa andũ, ũkaanangwa:'),
('kam', 'ACT', 5, 39, 'ĩndĩ ethĩwa nĩ wa Ngai, mũtikatonya kũmananga; mũikese kwoneka mũkyũkita na Ngai.'),
('kam', 'ACT', 5, 40, 'Na meew’a ndeto syake; na mameta atũmwa mbee woo, mamakũna na mameaĩa maikaneene syĩtwanĩ ya Yesũ, na mamaeka mathi.'),
('kam', 'ACT', 5, 41, 'Namo ĩndĩno mauma mbee wa nzama, maitana nũndũ nĩmatalĩlwe kwĩthĩwa nĩmaĩlwe nĩ kwanangĩwa ndaĩa nũndũ wa Syĩtwa yĩu.'),
('kam', 'ACT', 5, 42, 'Na mĩthenya yonthe, ĩkalũnĩ na nyũmbanĩ kwoo, maiaaeka kũmanyĩsya na kũtavan’ya ũvoo mũseo wa Yesũ kana nĩwe Klĩsto.'),
('kam', 'ACT', 6, 1, 'Na mĩthenya ĩsu, yĩla ũtalo wa amanyĩw’a waĩ ũkingĩva, kwookĩla mũnyungunyĩsyo wa Ayuti ma Ũkiliki ĩũlũ wa Aevelania, nũndũ wa aka moo ndiwa kũlea kũnengwa nesa ũtethyo ũla wanenganawe kĩla mũthenya.'),
('kam', 'ACT', 6, 2, 'Na ala ĩkũmi na elĩ mameta nguthu ya amanyĩw’a moke kwamo, na mamea, Kũtiaĩle ithyĩ kũtia ndeto ya Ngai, na kũthũkũma maũndũnĩ ma mesa.'),
('kam', 'ACT', 6, 3, 'Kwondũ wa ũu, ana‐a‐asa, nyuvai katĩ wenyu aũme mũonza me na nguma nzeo, mausũĩtwe nĩ Veva na ũĩ, ala tũtonya kũmaia kwondũ wa wĩa ũũ.'),
('kam', 'ACT', 6, 4, 'Ĩndĩ ithyĩ tũkekalaa tũlũlũmĩle mboyanĩ na ũthũkũminĩ wa ĩla ndeto.'),
('kam', 'ACT', 6, 5, 'Na ndeto ĩsu yendeesya ĩla nguthu yonthe: na mamũnyuva Sitivini, mũndũ wusũĩte mũĩkĩĩo na Veva Mũtheu, na Vilivu, na Volokolo, na Nikanoli, na Timona, na Valimena, na Nikola mũvikĩli wa Kĩyuti wa Andiokia:'),
('kam', 'ACT', 6, 6, 'na asu mamaia mbee wa atũmwa: na mavoya, mamailĩĩla moko.'),
('kam', 'ACT', 6, 7, 'Na ndeto ya Ngai yeana; na ũtalo wa amanyĩw’a waingĩvw’a mũno Yelusaleme; na nguthu nene ya athembi yalika ũla mũĩkĩĩonĩ.'),
('kam', 'ACT', 6, 8, 'Na Sitivini, ausũĩte mumo na vinya, eeka momakyo manene na mawonan’yo andũnĩ.'),
('kam', 'ACT', 6, 9, 'Ĩndĩ kwookĩla amwe ala maĩ ma ĩsinakoke yĩla yĩtawa ya Alivelitino, na ya Akulene, na ya Aalesandalia, na ya ala ma Silisia na Asia, maikananĩa na Sitivini.'),
('kam', 'ACT', 6, 10, 'Na matyaatonya kũsiĩĩa ũĩ wake na Veva ũla waneenie naw’o.'),
('kam', 'ACT', 6, 11, 'Na ĩndĩ mew’ana na maisye, Nĩtwĩw’ĩte ũsu aineenea Mose na Ngai ndeto sya ũumano.'),
('kam', 'ACT', 6, 12, 'Na mamaingĩanĩsya andũ, na atumĩa, na aandĩki, na mamũkĩlĩla, mamũkwata, na mamũete nzamanĩ,'),
('kam', 'ACT', 6, 13, 'na mamũũngamĩsya ngũsĩ sya ũvũngũ, ila syaisye, Mũndũ ũũ ndaekaa ũneenea vandũ vaa vatheu na ĩla mĩao ndeto:'),
('kam', 'ACT', 6, 14, 'nũndũ nĩtwĩw’ĩte aiasya kana Yesũ ũsu wa Nasaleti akaananga vandũ vaa, na kũalyũla syĩthĩo ila twanengiwe nĩ Mose.'),
('kam', 'ACT', 6, 15, 'Na onthe ala mekalĩte nzamanĩ, maimũketeea na metho moo, moona ũthyũ wake ũilyĩ ta ũthyũ wa mũlaĩka.'),
('kam', 'ACT', 7, 1, 'Na mũthembi mũnene amũkũlya Sitivini, Nĩw’o mailyĩ maũndũ asu?'),
('kam', 'ACT', 7, 2, 'Na asũngĩa, Ana‐a‐asa na aasa, ĩthukĩĩsyei: Ngai ũla ũtaĩawa amumĩlĩle asa waitũ Avalaamu, yĩla watwĩe nthĩ ya Mesovotamĩa, atanamba ũtũa nthĩ ya Aalani,'),
('kam', 'ACT', 7, 3, 'na amwĩa, Uma nthĩ ĩno yaku, ũtie andũ maku, ũthi nthĩ ĩla ngakwon’ya.'),
('kam', 'ACT', 7, 4, 'Na ĩndĩ auma nthĩ ya Akalitei, na atũa nthĩ ya Aalani: na yĩla ĩthe wake wakwie, Ngai amũthamya amũete nthĩ ĩno, ĩla mũtwĩe yu:'),
('kam', 'ACT', 7, 5, 'na ndaamũnenga ũtiĩwa wayo, aiee, o na veana kwia ũnyaĩĩ wake: na amwatha kana akamũnenga nthĩ ĩno yĩthĩwe ng’ũndũ yake, na ya ũsyao wake ĩtina wake, yĩla ũtaĩ mwana.'),
('kam', 'ACT', 7, 6, 'Na Ngai aneena ũu, kana ũsyao, wake ũkekala ũeni nthĩ ngeni, na kana makatuwa ngombo syoo, na kwĩkwa naĩ, ĩvinda ya myaka maana ana.'),
('kam', 'ACT', 7, 7, 'Na mbaĩ ĩla makethĩwa ngombo syayo ngamĩsilĩla, aisye ũu Ngai: na ĩtina wa ũu makauma nthĩ ĩsu, na kũnthũkũmĩa vaa.'),
('kam', 'ACT', 7, 8, 'Na amũnenga ũtianĩo wa nzaĩko: na ĩndĩ Avalaamu amũsyaa Isaka, na amwaĩka mũthenya wa nyanya; na Isaka amũsyaa Yakovo, na Yakovo amasyaa ala atumĩa maitũ ĩkũmi na elĩ.'),
('kam', 'ACT', 7, 9, 'Na atumĩa asu mamwĩw’ĩe Yosevu kĩwĩu, na mamũthoosya athi Misili: na Ngai aĩ nake,'),
('kam', 'ACT', 7, 10, 'na amumya mathĩnanĩ make onthe, na amũnenga waĩlu na ũĩ mbee wa Valao, mũsumbĩ wa Misili; na amũtw’a ngavana ĩũlũ wa Misili na ĩũlũ wa nyũmba yake yonthe.'),
('kam', 'ACT', 7, 11, 'Na kwooka yũa ĩũlũ wa nthĩ yonthe ya Misili na ya Kanaani, na ũnyamao mũnene: na aasa maitũ maiaaona syĩndũ sya ũmavũn’ya.'),
('kam', 'ACT', 7, 12, 'Ĩndĩ Yakovo eew’a kana lĩu wĩ Misili, amatũma aasa maitũ, ya mbee.'),
('kam', 'ACT', 7, 13, 'Na ya kelĩ Yosevu eeyumbũla kwa ana‐a‐ĩthe make; na mbaĩ ya Yosevu yamanyĩka kwa Valao.'),
('kam', 'ACT', 7, 14, 'Na Yosevu atũmana Yakovo ĩthe wake, amwĩta oke kwake na andũ make onthe, andũ mĩongo muonza na atano.'),
('kam', 'ACT', 7, 15, 'Na Yakovo atheea alika Misili; na akw’a, we na aasa maitũ;'),
('kam', 'ACT', 7, 16, 'nao makuwa matwawa Sekemu, na maiwa mbũanĩ ĩla Avalaamu wathooie na thooa wa vetha kwa ana ma Amolu nthĩ ya Sekemu.'),
('kam', 'ACT', 7, 17, 'Ĩndĩ ĩvinda ya watho ũla Ngai wamũnengie Avalaamu yathengeea, andũ asu meana na maingĩva nthĩ ya Misili,'),
('kam', 'ACT', 7, 18, 'mũvaka kwookĩla mũsumbĩ ũngĩ ĩũlũ wa Misili, ũtaamwĩsĩ Yosevu.'),
('kam', 'ACT', 7, 19, 'Ũsu amĩkĩe mbaitũ ũseleke, na kũmeka naĩ aasa maitũ, kana mekye tũũkenge twoo ĩtheka tũikethĩwe thayũ.'),
('kam', 'ACT', 7, 20, 'Na ivĩnda yĩu Mose asyawa, nako kaĩ kanake mũno; na kaeewa nyũmbanĩ ya ĩthe myei ĩtatũ:'),
('kam', 'ACT', 7, 21, 'na kekw’a ĩtheka, mwĩĩtu wa Valao akosa, akaea akatw’a mwana wake.'),
('kam', 'ACT', 7, 22, 'Na Mose amanyĩiw’e ũĩ w’onthe wa Amisili; nake aĩ mwai ndetonĩ syake na mekonĩ make.'),
('kam', 'ACT', 7, 23, 'Ĩndĩ avikya myaka yake mĩongo ĩna, kwamũlika ngoonĩ yake kũenda kũmasisya ana‐a‐ĩthe make, ana ma Isilaeli.'),
('kam', 'ACT', 7, 24, 'Na akyona ũmwe wamo akĩnyamaw’a, amũtetheesya, na amũĩvanĩĩsya ũsu wanyamaaw’a, na amũaa ũla Mũmisili:'),
('kam', 'ACT', 7, 25, 'nake atalĩlya kana ana‐a‐ĩthe nimamanyite kana Ngai nũmanengete wovosyo na kw’oko kwake; ĩndĩ matyaamanya.'),
('kam', 'ACT', 7, 26, 'Na ũnĩ ũsu amaumĩlĩla maiũkita, nake enda ũmew’anĩthya ĩngĩ, aimea, Mavwana, mwĩ ma ĩthe ũmwe; nikĩ mũkwĩkana nai?'),
('kam', 'ACT', 7, 27, 'Ĩndĩ ũla ũmwĩkĩte ũngĩ naĩ amũluuta, aisya, Ũtw’ĩtwe mũnene na mũsili ĩũlũ waitũ nũũ?'),
('kam', 'ACT', 7, 28, 'Wĩenda ũmbũaa, ũndũ ũnamũaie Mũmisili ĩoo?'),
('kam', 'ACT', 7, 29, 'Na Mose akĩa nũndũ wa ndeto isu, na atw’ĩka mwĩkali wa ũeninĩ nthĩ ya Mitiani, na asyaĩa ana elĩ kw’o.'),
('kam', 'ACT', 7, 30, 'Na avikya myaka mĩongo ĩna e kw’o, aumĩlĩlwa nĩ mũlaĩka ũmũĩnĩ wa mwaki wĩ kakuthunĩ, weũnĩ wa kĩĩma kya Sinai.'),
('kam', 'ACT', 7, 31, 'Na Mose awona, aseng’w’a nĩ woni ũsu: na akĩthengeea asisye, kwooka wasya wa Mwĩaĩi, ũiasya,'),
('kam', 'ACT', 7, 32, 'Nyie nĩ Ngai wa aaĩthe maku, Ngai wa Avalaamu, na wa Isaka, na wa Yakovo. Na Mose atetema, na akĩa kũsisya.'),
('kam', 'ACT', 7, 33, 'Na Mwĩaĩi amwĩa, Umya iatũ maũũnĩ maku: nũndũ vandũ vau ũũngeme nĩ nthĩ ntheu.'),
('kam', 'ACT', 7, 34, 'Nyie nĩnonete nesa monyamao ma andũ makwa me Misili, na nĩnĩw’ĩte kũluma kwo, nakwa natheea kũmatangĩĩa: na yu ũka, nĩngũũtũma Misili.'),
('kam', 'ACT', 7, 35, 'Mose ũsu ũla maleile, maiasya, Ũtw’ĩtwe mũnene na mũsili nũũ? Nĩwe watũmiwe nĩ Ngai ethĩwe mũnene, na ĩngĩ ethĩwe mwovosya kwondũ wa kw’oko kwa mũlaĩka ũla wamumĩlĩle kakuthunĩ.'),
('kam', 'ACT', 7, 36, 'Mũndũ ũsu amatongoesye, akĩka momakyo na syama nthĩ ya Misili, na Ukanganĩ Mũtune, na weũni, ĩvinda ya myaka mĩongo ĩna.'),
('kam', 'ACT', 7, 37, 'Mose ũsu nĩwe ũla wamatavisye ana ma Isilaeli, Ngai akamũkĩlĩlya mwathani kuma kwa ana‐a‐ĩthe menyu, ũilyĩ takwa.'),
('kam', 'ACT', 7, 38, 'Ũsu nĩwe ũla waĩ ũmbanonĩ weũnĩ, vamwe na mũlaĩka ũla waneenie nake kĩĩmanĩ kya Sinai, na vamwe na aasa maitũ: ũla wosie ndeto syĩ thayũ atũnenge ithyĩ:'),
('kam', 'ACT', 7, 39, 'na aasa maitũ maiaaĩtĩkĩla kũmwĩw’a, ĩndĩ mamũluuta kũasa, na ngoonĩ syoo maalũka Misili,'),
('kam', 'ACT', 7, 40, 'Aluni, Tũseũvĩsye ngai ila syĩtũtongoeasya: nũndũ Mose ũsu, ũla watumisye nthĩ ya Misili, tũtyĩsĩ ũndũ ũmũkwatĩte.'),
('kam', 'ACT', 7, 41, 'Na mĩthenya ĩsu maseũvya mũvw’anano wa kasaũ ka ng’ombe, na mootwaĩa mũvw’anano ũsu nthembo, na kũtanĩa mawĩa ma moko moo.'),
('kam', 'ACT', 7, 42, 'Ĩndĩ Ngai eethyũũa, na aekana nao mathũkũme nguthu ya ĩtunĩ; o ũndũ kũandĩkĩtwe ĩvukunĩ ya athani, atĩĩ, Mwaandetee nyie indo mbũae na nthembo sya kũtonywa Ĩvinda ya myaka mĩongo ĩna weũnĩ, inyw’ĩ nyũmba ya Isilaeli?'),
('kam', 'ACT', 7, 43, 'Na inyw’ĩ mwakuĩte kakalũ ka Moleki, Na ndata ya ĩla ngai yetawa Levani, Mĩvw’anano ĩla mwaseũvisye mũmĩthaithe: Nakwa ngatuma mũenda mwĩ atave kũasa kũvĩta Mbaviloni.'),
('kam', 'ACT', 7, 44, 'Aasa maitũ maĩ na ũla wĩkalo wa ũkũsĩ weũnĩ, o ũndũ Mose weaĩwe nĩ ũla waneenie nake, kana ayĩseũvye kwĩanana na ngelekan’yo ĩla wonie.'),
('kam', 'ACT', 7, 45, 'Naw’o aasa maitũ nĩmookuanasya, na kũete me na Yosua, yĩla malikile kũmĩmeesya nthĩ sya i mbai ila Ngai walũngilye mbee wa mothyũ ma aasa maitũ kũvika mĩthenya ya Ndaviti;'),
('kam', 'ACT', 7, 46, 'ũla wonie waĩlo vala ve Ngai, nake nĩwendie kũmwonea Ngaĩ wa Yakovo wĩkalo.'),
('kam', 'ACT', 7, 47, 'Ĩndĩ Solomoni amwakĩa nyũmba.'),
('kam', 'ACT', 7, 48, 'Ĩndĩ Ũla Wĩ lũlũ wa Onthe ndekalaa nthĩnĩ wa nyũmba syakĩtwe na moko; o ũndũ mwathani waitye,'),
('kam', 'ACT', 7, 49, 'Ĩtu nĩ kĩvĩla kyakwa kya ũsumbĩ, Na nthĩ nĩ kavila kakwa ka nyaĩĩ syakwa; Mwĩaĩĩ easya, Mũkambakĩa nyũmba ĩilyĩ ata? Kana nĩ vandũ vailyĩ ata vala ngathũmũa?'),
('kam', 'ACT', 7, 50, 'Ti kw’oko kwakwa kwoombie syĩndũ ii syonthe?'),
('kam', 'ACT', 7, 51, 'Inyw’ĩ mwĩ na ngingo nyũmũ, na ngoo syenyu na matũ menyu mate maike, mĩthenya yonthe nĩmũmũsiĩĩaa Veva Mũtheu: o ũndũ aaĩthe menyu meekie, nĩw’o inyw’ĩ mwĩkaa.'),
('kam', 'ACT', 7, 52, 'Nĩ mwathani wĩva ũla aaĩthe menyu mataamũthĩn’ya? Na ĩngĩ nĩmamoaie ala mambie ũmwon’ya kũka kwa Ũla Mũlũngalu; na ũsu inyw’ĩ yu nĩmũtw’ĩkĩte amũvũnyanĩi na amũai;'),
('kam', 'ACT', 7, 53, 'inyw’ĩ ala mwoosie ĩla mĩao ũndũ kwatwiwe nĩ alaĩka, na mũtyaamĩkwata.'),
('kam', 'ACT', 7, 54, 'Na meew’a maũndũ asu, matemwa ngoonĩ syoo, na mamũvevetanĩsye maeo moo.'),
('kam', 'ACT', 7, 55, 'Ĩndĩ ausũĩtwe nĩ Veva Mũtheu, ang’elela aketee ĩtuni, na oona ũtheu mũtisu wa Ngai, na Yesũ aũngeme ngalĩ ya kw’oko kwa aũme kwa Ngai,'),
('kam', 'ACT', 7, 56, 'na asya, Sisya, nĩngwona ĩtu yĩvingũkĩte, na ũla Mwana wa mũndũ aũngeme ngalĩ ya kw’oko kwa aũme kwa Ngai.'),
('kam', 'ACT', 7, 57, 'Ĩndĩ makaya na wasya mũnene, na malinda matũ moo, mamũthaanyũkĩa na ngoo ĩmwe;'),
('kam', 'ACT', 7, 58, 'mamũkusũlan’ya mamũtwaa ũtee wa ndũa, na mamũkimanga na mavia: na ila ngũsĩ syaia ngũa syoo maũũnĩ ma mwanake wĩtawa Saulo.'),
('kam', 'ACT', 7, 59, 'Na mamũkimanga Sitivini, aimwĩkaĩla Mwĩaĩi, ayasya, Mwĩaĩi Yesũ, osa veva wakwa.'),
('kam', 'ACT', 7, 60, 'Nake atulya ndu, na aneena na wasya mũnene, Mwĩaĩi, ndũkamatalĩle naĩ ĩno. Na amina ũneena ũu, akoma.'),
('kam', 'ACT', 8, 1, 'Na Saulo oona nĩ ũseo kũawa kwake. Na mũthenya ũsu kwambĩlĩlya ũnyamao mũnene ĩũlũ wa ĩkanisa yĩla yaĩ Yelusaleme; na manyaĩĩkw’a onthe ivalonĩ sya Yutia na Samalia, ate o ala atũmwa.'),
('kam', 'ACT', 8, 2, 'Na andũ ala mamũkĩaa Ngai mamwĩnzĩa Sitivini nthĩ, na mamũĩĩa mũno.'),
('kam', 'ACT', 8, 3, 'Ĩndĩ Saulo aananga ĩkanisa mũno, aivota kĩla nyũmba, aimakusũlan’ya aũme na aka aimekĩa kolokolonĩ.'),
('kam', 'ACT', 8, 4, 'Kwondũ wa ũu asu ala manyaĩĩkĩtw’e maendaa maitavan’ya ũla ũvoo mũseo.'),
('kam', 'ACT', 8, 5, 'Na Vilivu atheea alika ndũanĩ ya Samalia, na amũtavan’ya Klisto kw’o.'),
('kam', 'ACT', 8, 6, 'Na makomano meethukĩĩsye na ngoo ĩmwe maũndũ ala maneeniwe nĩ Vilivu, yĩla meewie, na moonie mawonan’yo ala wekie.'),
('kam', 'ACT', 8, 7, 'Nĩkwĩthĩwa maveva mavuku nĩmamaumie aingi ala maĩ namo, maikaya na wasya mũnene: na aingi maaĩte mamutha, na ala mathuaa, mavow’a.'),
('kam', 'ACT', 8, 8, 'Na kweethĩwa ũtanu mũnene ndũanĩ ĩsu.'),
('kam', 'ACT', 8, 9, 'Ĩndĩ kwaĩ mũndũ ũmwe, syĩtwa yake wetawa Simoni, ũla tene wekaa ũoi ndũanĩ ĩsu, aimaseng’ya andũ ma Samalia, akĩyĩta mwene mũndũ mũnene:'),
('kam', 'ACT', 8, 10, 'na onthe mamwĩthukĩĩasya kuma ũla mũnini kũvika ũla mũnene mbee, maiasya, Mũndũ ũũ nĩwe ũla ũtonyi wa Ngai ũla wĩtawa Mũnene.'),
('kam', 'ACT', 8, 11, 'Na mamwĩthukĩĩasya, nũndũ amaseng’etye na mooi make ĩvinda ĩasa.'),
('kam', 'ACT', 8, 12, 'Ĩndĩ meetĩkĩla Vilivu aitavan’ya ũla ũvoo mũseo wa ũsumbĩ wa Ngai na syĩtwa ya Yesũ Klĩsto, mavatiswa, aũme na aka.'),
('kam', 'ACT', 8, 13, 'Na Simoni nake mwene nĩwetĩkĩlile: na avatiswa ekalaa vamwe na Vilivu; na akyona syama na mavinya manene ala meekiwe aseng’a.'),
('kam', 'ACT', 8, 14, 'Na atũmwa ala maĩ Yelusaleme meew’a kana Samalia nĩmosete ndeto ya Ngai, mamatũma Vetelo na Yoana kw’o:'),
('kam', 'ACT', 8, 15, 'nao, matheea kw’o, mamavoyea, nĩ kana mose Veva Mũtheu:'),
('kam', 'ACT', 8, 16, 'nĩkwĩthĩwa ndaĩ anamba ũmatheeea o na ũmwe woo: ate o nĩmavatisĩtwe syĩtwanĩ ya Mwĩaĩi Yesũ.'),
('kam', 'ACT', 8, 17, 'Na ĩndĩ mamailĩĩla moko moo, na moosa Veva Mũtheu.'),
('kam', 'ACT', 8, 18, 'Na Simoni oona kana Veva Mũtheu anenganwe ũndũ wa kwilĩĩlwa moko ma atũmwa, amaetee mbesa,'),
('kam', 'ACT', 8, 19, 'aiasya, Nengai nakwa vinya ũũ, nĩ kana o ũla nĩilĩĩla moko makwa ose Veva Mũtheu.'),
('kam', 'ACT', 8, 20, 'Ĩndĩ Vetelo amwĩa, Mbesa syaku nĩsyae vamwe naku, nũndũ wĩasya ũkoosa mũthĩnzĩo wa Ngai ũndũ wa mbesa.'),
('kam', 'ACT', 8, 21, 'Ndwĩ na kĩlungu kana kĩanda ũndũnĩ ũũ: nĩkwĩthĩwa ngoo yaku ndĩaĩlĩte mbee wa Ngai.'),
('kam', 'ACT', 8, 22, 'Alyũla ngoo ĩndĩno ũndũ wa ũthũku ũũ waku, noimũvoya Mwĩaĩi, no kwĩthĩwa akakũekea ũlilikano ũsu wa ngoo yaku.'),
('kam', 'ACT', 8, 23, 'Nũndũ nĩngwona wĩ ũũ ta nyongo na wĩ wovonĩ wa ũthũkũ.'),
('kam', 'ACT', 8, 24, 'Na Simoni asũngĩa, asya, Mboyeai inyw’ĩ kwa Mwĩaĩi, nĩ kana maũndũ asu mwasya maikangwate, o na ũmwe.'),
('kam', 'ACT', 8, 25, 'Namo ĩndĩ, maumĩlya ũkũsĩ na kũneena ndeto ya Mwĩaii, maalũka Yelusaleme, na matavan’ya ũvoo mũseo mĩsyĩ mingĩ ya Asamalia.'),
('kam', 'ACT', 8, 26, 'Ĩndĩ mũlaĩka wa Mwĩaĩi aneena na Vilivu, aiasya, Ũkĩla, ũthi ngalĩ ya itheo kũvika nzĩa ĩla yumĩte Yelusaleme kũvika Ngasa: na kw’o nĩ weũ.'),
('kam', 'ACT', 8, 27, 'Nake ookĩla, athi: na sisya, mũndũ wa Ethiovia, mũndũ mũvakũe ũla waĩ na ũkũmũ mũnene ĩtheo wa Kandake, mũsumbĩ mũndũ mũka, wa Aethiovia, nake nĩwe ũla waiĩtwe ĩũlũ wa syĩndũ syake syonthe, ũla wokĩte Yelusaleme ũndũ wa kũthaitha;'),
('kam', 'ACT', 8, 28, 'na aalũkĩte ailyĩ ngalĩnĩ yake, aisoma ĩvuku ya mwathani Isaia.'),
('kam', 'ACT', 8, 29, 'Na Veva amwĩa Vilivu, Thengeea vakuvĩ, ũendan’ye na ngalĩ ĩsu.'),
('kam', 'ACT', 8, 30, 'Na Vilivu asemba vala ũĩ, na eew’a aisoma ĩvuku ya mwathani Isaia, na amũkũlya, Nũũmanya ũu ũũsoma?'),
('kam', 'ACT', 8, 31, 'Nake amũsũngĩa, Nĩmanya ata ndeũtongoew’a nĩ mũndũ? Na amwĩsũva Vilivu ambate ekale nake.'),
('kam', 'ACT', 8, 32, 'Na kĩlungu kya maandĩko kĩla wasomaa nĩ kĩĩ, Atongoew’e kũthi kũthĩnzwa ta ĩlondu; Na ta katena ka ĩlondu kavindĩtye mbee wa ũla ũkatilaa maw’ĩa, Nake no ta ũu, ndaathamũkan’ya kanyw’a wake:'),
('kam', 'ACT', 8, 33, 'Wĩnyivyonĩ wake kũsilĩlwa katĩ kwavetwa: Nũũ ũla ũkonan’ya ũsyao wake? Nĩkwĩthĩwa thayũ wake nũvetetwe nthĩ.'),
('kam', 'ACT', 8, 34, 'Na ũla mũndũ mũvakũe amũsũngĩa Vilivu, amwĩa, Nĩngũũvoya, mwathani ũsu eneena ndeto ii nũndũ waũ? Nĩ ũvoo wake mwene, kana nĩ mũndũ ũngi?'),
('kam', 'ACT', 8, 35, 'Na Vilivu aathamya kanyw’a wake, na amũtavya ũvoo mũseo wa Yesũ, akyambĩlĩlya na maandĩko asu.'),
('kam', 'ACT', 8, 36, 'Na maendete nzĩani, mavika vandũ ve manzĩ; na mũndũ ũsu mũvakũe asya, Sisya, manzĩ ti aa; nĩ ũndũ wĩva ũnziĩĩa ndikavatiswe?'),
('kam', 'ACT', 8, 37, '(Vilivu asũngĩa, amwĩa, Ethĩwa nĩwĩtĩkĩlĩte na ngoo yaku yonthe, nũtonya. Nake amũsũngĩa, amwĩa, Nĩngwĩtĩkĩla kana Yesũ Klĩsto nĩ Mwana wa Ngai.)'),
('kam', 'ACT', 8, 38, 'Na eeaa ngalĩ iũngame: na matheea me elĩ manzĩnĩ, Vilivu na ũla mũvakũe; na Vilivu amũvatisa.'),
('kam', 'ACT', 8, 39, 'Na mauma manzĩnĩ, Veva wa Mwĩaĩi amũvulya Vilivu; na ũla mũndũ mũvakũe ndaamwona ĩngĩ, nĩkwĩthĩwa aendie na nzĩa yake akĩtana.'),
('kam', 'ACT', 8, 40, 'Ĩndĩ Vilivu ooneka Asoto: na avĩtĩle ku nĩwatavanasya ũla ũvoo mũseo ndũanĩ syonthe, mũvaka avika Kaisalea.'),
('kam', 'ACT', 9, 1, 'Ĩndĩ Saulo nake, kũveva kwake kwaĩ kũmakan’ya na kũmoaa amanyĩw’a ma Mwĩaĩi, aenda kwa mũthembi mũnene,'),
('kam', 'ACT', 9, 2, 'na amwĩtya mavalũa ma ũthi nao Ndamasiku masinakokenĩ, nĩ kana oona andũ ma ĩla Nzĩa, o na ethĩwa nĩ aũme kana aka, amaete me ove Yelusaleme.'),
('kam', 'ACT', 9, 3, 'Nake aendete na nzĩa, kweethĩwa aithengeea vakuvĩ na Ndamasiku: na oyu, o ĩmwe, kyeni kyauma ĩtunĩ kyakena ngalĩ syake syonthe:'),
('kam', 'ACT', 9, 4, 'nake avalũka nthĩ, na eew’a wasya ũineena nake, Saulo, Saulo, nĩkĩ ũũnthĩn’ya?'),
('kam', 'ACT', 9, 5, 'Nake akũlya, Nue ũũ, Mwĩaĩi? Nake amũsũngĩa, Ninyie Yesũ ũla ũũthĩn’ya: (nĩ vinya kwaku kũtheela mũsenge.'),
('kam', 'ACT', 9, 6, 'Nake aitelema na kũseng’a, asya, Mwĩaĩi, wĩenda nĩke ata?) Amwĩa, Ũkĩla, ũvote ndũanĩ, na ũkatavw’a ũndũ waĩle kwĩka.'),
('kam', 'ACT', 9, 7, 'Na andũ ala maendanĩtye nake maũngama makilĩtye ki, makĩw’a wasya, ĩngĩ maiaaona mũndũ.'),
('kam', 'ACT', 9, 8, 'Na Saulo ookĩla nthĩ; na asalukya metho make, ndaaona kĩndũ; na mamũtongoesya mamũkwete kw’oko, na mamũtwaa Ndamasiku.'),
('kam', 'ACT', 9, 9, 'Nake ekala mĩthenya ĩtatũ atekwona, na ateũya kana kũnyw’a.'),
('kam', 'ACT', 9, 10, 'Na kwaĩ mũmanyĩw’a ũmwe Ndamasiku, wetawa Anania; na Mwĩaĩi aneena nake woninĩ, amwĩta, Anania. Nake eetĩka, Sisya, ninyioo Mwĩaĩi.'),
('kam', 'ACT', 9, 11, 'Na Mwĩaĩi amwĩa, Ũkila, ũthi nzĩanĩ ĩla yĩtawa Ndũngalu, noikũlya nyũmbanĩ ya Yutasi mũndũ ũmwe wĩtawa Saulo, mũndũ wa Taliso: nũndũ sisya, nũnũũvoya;'),
('kam', 'ACT', 9, 12, 'na nĩwonete mũndũ wĩtawa Anania aivota, na akilĩĩla moko ĩũlũ wake, nĩ kana atonye kũnengwa kwona.'),
('kam', 'ACT', 9, 13, 'Ĩndĩ Anania amũsũngĩa, Mwĩaĩi, nĩnĩw’ĩte na andũ aingĩ ũvoo wa mũndũ ũsu, ũndũ wĩkĩte atheu maku kũya Yelusaleme mothũku maingĩ:'),
('kam', 'ACT', 9, 14, 'na vaa e na ũkũmũ wumĩte kwa athembi anene amove onthe ala mawetaa syĩtwa yaku.'),
('kam', 'ACT', 9, 15, 'Ĩndĩ Mwĩaiĩ amwia, Enda: nĩkwĩthĩwa we nĩ mũio mũnyuve kwakwa, wa ũkua syĩtwa yakwa kwa Andũ‐ma‐mbaĩ‐ingĩ, na asumbĩ, na andũ ma mbaĩ ya Isilaeli:'),
('kam', 'ACT', 9, 16, 'nũndũ nyie, ngamwon’ya maũndũ ũndũ meana, ala matatĩa ũmũkwata kwondũ wa syĩtwa yakwa.'),
('kam', 'ACT', 9, 17, 'Na Anania athi, na alika nyũmba; na aimwilĩĩla moko make asya, Mwana‐a‐asa Saulo, ũla Mwĩaĩi nĩwandũma, nake nĩwe Yesũ, ũnakumĩlĩle nzĩanĩ ĩla ũnookĩte nayo, nĩ kana ũtonye kũnengwa kwona na kusũwa nĩ Veva Mũtheu.'),
('kam', 'ACT', 9, 18, 'Na oyuyu kwavalũka syĩndũ kuma methonĩ make ta makwaũ, nake anengwa kwona; na ookĩla na avatiswa;'),
('kam', 'ACT', 9, 19, 'na ĩndĩ aya lĩu na eethĩwa na vinya. Nake ekala vamwe na amanyĩw’a ala maĩ Ndamasiku mĩthenya ĩmwe.'),
('kam', 'ACT', 9, 20, 'Na oyu masinakokenĩ amũtavan’ya Yesũ kana nĩwe Mwana wa Ngai.'),
('kam', 'ACT', 9, 21, 'Na onthe ala mamwĩwie maseng’a, na masya, Ũũ tiwe ũla ũnamanangaa ala manayĩkaĩlaa syĩtwa yĩĩ Yelusaleme? Nake anookĩte vaa kwondũ wa ũu, nĩ kana amatwae me ove kwa athembi anene.'),
('kam', 'ACT', 9, 22, 'Ĩndĩ Saulo ongeleka kũya vinya, na aimakĩlya ũĩ Ayuti ala matwĩe Ndamasiku, akyonan’ya kana ũsu nĩwe Klĩsto.'),
('kam', 'ACT', 9, 23, 'Na mĩthenya mingĩ yavĩta, Ayuti masaman’ya vamwe, mamũae:'),
('kam', 'ACT', 9, 24, 'ĩndĩ nzama yoo yamanyĩka nĩ Saulo. Nao mamwoveesya mbingĩlonĩ mũthenya na ũtukũ, kana matonye kũmũaa:'),
('kam', 'ACT', 9, 25, 'ĩndĩ amanyĩw’a mamwosa na ũtukũ na mamũtheelelya ũvainĩ e kĩkavũnĩ.'),
('kam', 'ACT', 9, 26, 'Na avika Yelusaleme, atata kwĩyosan’ya na amanyĩw’a: na onthe nĩmamũkĩaa, matekwĩtĩkĩla kana we nĩ mũmanyĩw’a.'),
('kam', 'ACT', 9, 27, 'Ĩndĩ Valanava amwosa, na amũete kwa atũmwa, na amatavya ũndũ wamwonie Mwĩaĩi nzĩanĩ, na ũndũ waneenie nake, na ũndũ watavanisye na ũkũmbaũ syĩtwanĩ ya Yesũ ku Ndamasiku.'),
('kam', 'ACT', 9, 28, 'Na aĩ vamwe nao akĩlika na akyumaala Yelusaleme,'),
('kam', 'ACT', 9, 29, 'akĩtavan’ya na ũkũmbaũ syĩtwanĩ ya Mwĩaĩi: na aneena na aikananĩa na Ayuti ma Ũkiliki; ĩndĩ mamantha ũmũaa.'),
('kam', 'ACT', 9, 30, 'Na ana‐a‐ĩthe mamanya mamũtheesya Kaisalea, na mamwĩa athi Taliso.'),
('kam', 'ACT', 9, 31, 'Na ĩndĩ ĩkanisa ya nthĩ yonthe ya Yutia na Kalilii na Samalia yaĩ na mũuo, na kwakĩka, na kũendeea kũmũkĩa Mwĩaĩi, na ũkiakisyonĩ wa Veva Mũtheu, na yaingĩva.'),
('kam', 'ACT', 9, 32, 'Na kweethĩwa, Vetelo aianganga ku kw’onthe, atheea kwa atheu ala matwĩe Lita.'),
('kam', 'ACT', 9, 33, 'Na ku oona mũndũ, syĩtwa yake Ainea, ũla wamamĩte ũkomonĩ wake myaka nyanya; nĩkwĩthĩwa aĩ mwau mamutha.'),
('kam', 'ACT', 9, 34, 'Na Vetelo amwĩa, Ainea, Yesũ Klĩsto nũnũũkũvosya: ũkĩla walan’ye ũkomo waku. Na oyu ookĩla'),
('kam', 'ACT', 9, 35, 'Na onthe ala matwĩe Lita na Saloni mamwona, na mamwĩthyũũĩa Mwĩaĩi.'),
('kam', 'ACT', 9, 36, 'Na Yova kwaĩ mũmanyĩw’a ũmwe wetawa Tavitha, ũalyũlo wayo nĩ, Ndolokasi: mũndũ mũka ũsu ausũĩte meko maseo ala wekaa vamwe na kumya motethyo.'),
('kam', 'ACT', 9, 37, 'Na mĩthenya ĩsu akwatwa nĩ ũwau, na akw’a: na mamũthambya, mamwia nyũmbanĩ ya ĩũlũ.'),
('kam', 'ACT', 9, 38, 'Na nĩkwĩthĩwa ndũa ya Lita yaĩ vakuvĩ na Yova, ala amanyĩw’a meew’a kana Vetelo e kw’o, mamatũma andũ elĩ kwake, maimwĩsũva, makyasya, Ndũkekale, ũka kwĩtũ.'),
('kam', 'ACT', 9, 39, 'Na Vetelo ookĩla na aendan’ya nao. Na avika, mambata nake nyũmbanĩ ĩla ya ĩũlũ: na aka ndiwa onthe maũngama nake makĩĩa, na maimwon’ya itonyeo na ngũa syonthe ila Ndolokasi watumĩte, yĩla waĩ vamwe nao.'),
('kam', 'ACT', 9, 40, 'Ĩndĩ Vetelo amaumaalya onthe, na atulya ndu, avoya; na eethyũũa elekela kimba, asya, Tavitha, ũkĩla. Nake asalukya metho; na amwona Vetelo, ookĩla ekala nthĩ.'),
('kam', 'ACT', 9, 41, 'Nake amũnenga kw’oko kwake, amũkĩlya; na ĩndĩ ameta atheu na aka ndiwa, amanenga we, e thayũ.'),
('kam', 'ACT', 9, 42, 'Na ũndũ ũsu wamanyĩka ndũa yonthe ya Yova: na aingĩ mamwĩtĩkĩla Mwĩaĩi.'),
('kam', 'ACT', 9, 43, 'Na Vetelo ekala vo Yova mĩthenya mingĩ kwa mũndũ wetawa Simoni, mũseũvya wa ithuma.'),
('kam', 'ACT', 10, 1, 'Na kwaĩ mũndũ ũmwe Kaisalea, wetawa Kolinelio, mũnene wa nguthu ya asikalĩ ĩana yetawa nguthu ya Italia,'),
('kam', 'ACT', 10, 2, 'mũthaithi mũnene, wakĩaa Ngai vamwe na nyũmba yake yonthe, nake nĩwanengae andũ motethyo maingĩ, na amũvoyaa Ngai mĩthenya yonthe.'),
('kam', 'ACT', 10, 3, 'Ũsu nĩwonie woninĩ ki, mũthenya ta saa kenda, mũlaĩka wa Ngai akyũka vala ũĩ, na aneena, Kolinelio.'),
('kam', 'ACT', 10, 4, 'Nake, akĩmũketeea, e na w’ĩa, asya, Nĩ kyaũ, Mwĩaĩi? Nake amwĩa, Mboya syaku na motethyo maku nĩmavikĩte ĩũlũ, matw’ĩkĩte ũlilikan’yo kwa Ngai.'),
('kam', 'ACT', 10, 5, 'Na yu tũma andũ mathi Yova, malatye mũndũ wĩtawa Simoni, ũla wĩ na syĩtwa ya kelĩ, Vetelo:'),
('kam', 'ACT', 10, 6, 'nake nĩ mũeni kwa mũndũ wĩtawa Simoni, mũseũvya wa ithuma, nyũmba yake ĩ ũtee wa ũkanga.'),
('kam', 'ACT', 10, 7, 'Na ũla mũlaĩka ũnũũneenaa nake athi, Kolinelio ameta athũkũmi elĩ ma nyũmba, na mũsikalĩ ũmwe ũkĩaa Ngai wa ala mamũthũkũmaa mĩthenya yonthe;'),
('kam', 'ACT', 10, 8, 'na amatavya maũndũ onthe, amatũma mathi Yova.'),
('kam', 'ACT', 10, 9, 'Na ũnĩ ũsu, maendete, makĩthengeea ndũa, Vetelo ambata nyũmbanĩ ĩũlũ avoye, syũa yĩkĩũngama:'),
('kam', 'ACT', 10, 10, 'na eew’a nzaa, na enda ũya: ĩndĩ maiseũvya lĩu, akwatwa nĩ too ũilyĩ ta kĩkw’ũ;'),
('kam', 'ACT', 10, 11, 'na oona ĩtu yĩkĩvingũka, na kĩndũ kĩitheea ta ngũa nene, ĩkĩtheew’a nthĩ na mĩthya ĩna yayo:'),
('kam', 'ACT', 10, 12, 'nayo nthĩnĩ wayo vaĩ nyamũ syĩ maũũ ana sya mĩthemba yonthe, na tũsamũ twa nthĩ tũla tũtambũkaa, na syĩndũ ila iũlũkaa yayayanĩ.'),
('kam', 'ACT', 10, 13, 'Na kwooka wasya vala ũĩ, ũkyasya, Ũkĩla, Vetelo; wũae, ũye.'),
('kam', 'ACT', 10, 14, 'Ĩndĩ Vetelo asya, Aiee, Mwĩaĩi; ndyaamba ũya kĩndũ o na kĩva kĩvuku kana kĩte kĩtheu.'),
('kam', 'ACT', 10, 15, 'Na wasya wooka vala ũĩ ĩngĩ ya kelĩ ũkyasya, Ila itheetw’e nĩ Ngai ndũkaitw’e mbuku.'),
('kam', 'ACT', 10, 16, 'Na ũndũ ũsu weekwa katatũ: na oyu kĩla kĩndũ kyambatw’a ĩtunĩ.'),
('kam', 'ACT', 10, 17, 'Na Vetelo aisũanĩwa mũno nthĩnĩ wake ũndũ ũilyĩ woni ũsu ũla wonie, sisya, andũ ala manatũmiwe nĩ Kolinelio, makũlilye nyũmba ya Simoni, maũngama mbingĩlonĩ,'),
('kam', 'ACT', 10, 18, 'na meetana makũlya ethĩwa Simoni, ũla wĩ na syĩtwa ya kelĩ, Vetelo, ekalĩte vo.'),
('kam', 'ACT', 10, 19, 'Na Vetelo aisũanĩa ũndũ wa woni, Veva amwĩa, Sisya, ve andũ atatũ meũkũmantha.'),
('kam', 'ACT', 10, 20, 'Ĩndĩ ũkĩla, ũtheee ũendan’ye nao ũte na nzika: nũndũ ninyie nĩmatũmĩte.'),
('kam', 'ACT', 10, 21, 'Na Vetelo atheea vala ve ala andũ, na amea, Sisya, ninyie ũla mũũmantha: mwooka nũndũ wa kĩ?'),
('kam', 'ACT', 10, 22, 'Nao mamwĩa, Kolinelio mũnene wa asikalĩ ĩana, mũndũ mũlũngalu na ũkĩaa Ngaĩ, ũla wĩ na nguma nzeo kwa mbaĩ yonthe ya Ayuti, oniw’e nĩ mũlaĩka mũtheu akũtũmane ũthi nyũmba kwake nĩ kana ethukĩĩsye ndeto syaku.'),
('kam', 'ACT', 10, 23, 'Na ĩndĩ amea malike nyũmba na amon’ya mokomo. Na ũnĩ ũsu ookĩla na aendan’ya nao, na ana‐a‐ĩthe amwe ma ndũa ya Yova mathi nake.'),
('kam', 'ACT', 10, 24, 'Na ũnĩ ũsu malika Kaisalea. Na Kolinelio nĩwameteele, ombanĩtye andũ ma mũvĩa wake na anyanyae anene.'),
('kam', 'ACT', 10, 25, 'Na Vetelo ailika, Kolinelio amũthaũa, na avalũka maũũnĩ make, amũthaitha.'),
('kam', 'ACT', 10, 26, 'Ĩndĩ Vetelo amũkĩlya, akyasya, Ũngama; nyie nakwa nĩ mũndũ.'),
('kam', 'ACT', 10, 27, 'Na akĩneena nake, avota, na eethĩa andũ aingĩ mombene:'),
('kam', 'ACT', 10, 28, 'na amea, Inyw’ĩ ene nĩmwisĩ kana nĩ ũndũ ũvatanĩtwe nĩ mĩao mũndũ Mũyuti kwĩvulan’ya, kana kũlika kwa mũndũ wa mbaĩ ĩngĩ; ĩndĩ Ngai nũmbonetye ndikete mũndũ o na wĩva mũvuku kana ũte mũtheu:'),
('kam', 'ACT', 10, 29, 'kwondũ wa ũu nĩnooka vate ngananĩo, natũmanwa. Kwondũ wa ũu nĩmũkũlya indĩ ũndũ ũla mũnandũmanĩe.'),
('kam', 'ACT', 10, 30, 'Na Kolinelio amũsũngĩa, Yu nĩ mĩthenya ĩna ĩnathela, kũvika saa ũũ, naĩ nyũmbanĩ yakwa ngĩvoya Ngai saa kenda; na sisya, mũndũ aũngama mbee wakwa evw’ikĩte ngũa ndisu,'),
('kam', 'ACT', 10, 31, 'nake asya, Kolinelio, kũvoya kwaku nĩkwĩw’ĩkĩte, na motethyo maku nĩmalilikenwe kwa Ngai.'),
('kam', 'ACT', 10, 32, 'Tũmana ĩndĩ Yova ũmwĩte Simoni, ũla wĩ na syĩtwa ya kelĩ, Vetelo, oke kwaku; athokete nyũmbanĩ ya Simoni, mũseũvya wa ithuma, nayo ĩ ũtee wa ũkanga.'),
('kam', 'ACT', 10, 33, 'Na ĩndĩ o kavinda kau nĩnakũtũmana; naku weka nesa wooka. Na ĩndĩ yu twĩ vaa ithyonthe mbee wa Ngai, nĩ kana twĩw’e maũndũ onthe ala weeaĩwe nĩ Mwĩaĩi.'),
('kam', 'ACT', 10, 34, 'Na Vetelo aathamya kanyw’a wake, asya, Nĩ w’o, nĩngũmanya kana Ngai ti mwendeesya wa andũ;'),
('kam', 'ACT', 10, 35, 'ĩndĩ mbaĩnĩ syonthe ũla ũmũkĩaa we, na kwĩka ũlũngalu, nĩwĩtĩkĩlawa nĩwe.'),
('kam', 'ACT', 10, 36, 'Ndeto ila watwaĩe ana ma Isilaeli, aitavan’ya ũla ũvoo mũseo wa mũuo kwondũ wa Yesũ Klĩsto (we nĩ Mwĩaĩi wa onthe)—'),
('kam', 'ACT', 10, 37, 'ndeto isu inyw’i nenyu nĩmwĩsĩ, ĩla yatavaniw’e nthĩ yonthe ya Yutia, ĩkyambĩlĩlw’a Kalilii, ĩtina wa ũvatisi ũla watavaniw’e nĩ Yoana;'),
('kam', 'ACT', 10, 38, 'ũvoo wa Yesũ wa Nasaleti, o ũndũ Ngai wamwĩtĩkĩsye Veva Mũtheu, o na vinya: ũla waendaa aiĩka nesa, na aimavosya onthe ala manyamaaw’a nĩ ndevili; nĩkwĩthĩwa Ngai aĩ vamwe nake.'),
('kam', 'ACT', 10, 39, 'Na ithyĩ twĩ ngũsĩ sya maũndũ asu onthe ala wekie nthĩ ya Ayuti, na Yelusaleme nayo; nake nĩmamũaie makĩmwamba mũtĩnĩ.'),
('kam', 'ACT', 10, 40, 'Mũndũ ũsu Ngai nĩwamũthayũũkisye mũthenya wa katatũ na amumĩlya onanw’e,'),
('kam', 'ACT', 10, 41, 'ti kwa andũ onthe, indĩ kwa ngũsĩ ila Ngai wambie ũnyuva, nasyo nĩ ithyĩ, ala twaĩe na kũnyw’a vamwe nake ĩtina wa kũthayũũka kwake kuma kwa akw’ũ.'),
('kam', 'ACT', 10, 42, 'Nake atwĩaĩe tũtavan’ye kwa andũ, na kũneena ũkũsĩ kana ũsu nĩwe wiĩtwe nĩ Ngai ethĩwe Mũsili wa ala me thayũ na wa ala akw’ũ.'),
('kam', 'ACT', 10, 43, 'Athani onthe nĩmeũmũkũsĩĩa kana kwondũ wa syitwa yake kĩla mũndũ ũmwĩtĩkĩlaa akoosa ũekeo wa naĩ.'),
('kam', 'ACT', 10, 44, 'Na Vetelo aineena ndeto isu, Veva Mũtheu amatheeea onthe ala methukĩĩsye ĩla ndeto.'),
('kam', 'ACT', 10, 45, 'Na ala ma nzaĩko metĩkĩlĩte, ala mookanĩtye na Vetelo, maseng’a nũndũ mũthĩnzĩo wa Veva Mũtheu watulũĩlwe Andũ‐ma‐mbaĩ‐ĩngĩ nao.'),
('kam', 'ACT', 10, 46, 'Nũndũ nĩmeewie maineena na ithyomo, na kũmũtaĩa Ngai. Na ĩndĩ Vetelo asũngĩa,'),
('kam', 'ACT', 10, 47, 'Ve mũndũ ũtonya kũmavata aa manzĩ, maikavatiswe, ala mosete Veva Mũtheu o taitũ?'),
('kam', 'ACT', 10, 48, 'Na atw’a mavatiswe syĩtwanĩ ya Yesũ Klĩsto. Na ĩndĩ mamwĩsũva ekale nao mĩthenya ĩmwe.'),
('kam', 'ACT', 11, 1, 'Na atũmwa na ana‐a‐ĩthe ala maĩ Yutia meew’a kana Andũ‐ma‐mbaĩ‐ĩngĩ nao nĩmosete ndeto ya Ngai.'),
('kam', 'ACT', 11, 2, 'Na Vetelo ambata Yelusaleme, ala maĩ ma nzaĩko makananĩa nake,'),
('kam', 'ACT', 11, 3, 'makĩmwĩa, We, nĩwalikile kwa andũ mataĩkawa, na waya nao.'),
('kam', 'ACT', 11, 4, 'Ĩndĩ Vetelo ambĩlĩlya kũmon’ya nesa ũndũ ũsu, aatĩanĩsye, aiasya,'),
('kam', 'ACT', 11, 5, 'Naĩ ndũanĩ ya Yova ngĩvoya: na nĩ toonĩ ũilyĩ ta kĩkw’ũ noona woni, kĩndũ kĩitheea, ta ngũa nene ĩkĩtheew’a kuma ĩtunĩ, ĩkwetwe mĩthya ĩna; nakyo kyooka vala nĩĩ:'),
('kam', 'ACT', 11, 6, 'na ngĩketeea mũno, na kũsũanĩa, noona nthĩnĩ wakyo nyamũ sya nthĩ ila syĩ maũũ ana, na nyamũ ila mbai, na tũsamũ tũla tũtambũkaa, na syĩndũ ila iũlũkaa.'),
('kam', 'ACT', 11, 7, 'Na neew’a naw’o wasya ũkĩmbĩa, Ũkĩla, Vetelo; wũae, ũye.'),
('kam', 'ACT', 11, 8, 'Ĩndĩ nyie nasya, Aiee, Mwĩaĩi; nĩkwĩthĩwa kĩndũ kĩvuku kana kĩte kĩtheu kĩtyaamba kũlika kanyw’anĩ wakwa nongi.'),
('kam', 'ACT', 11, 9, 'Ĩndĩ wasya wanzũngĩa ya kelĩ kuma ĩtunĩ, Ila itheetw’e nĩ Ngai ndũkaitw’e mbuku.'),
('kam', 'ACT', 11, 10, 'Na ũndũ ũsu weekwa katatũ: na kyonthe kyakusw’a kyambatw’a ĩtunĩ.'),
('kam', 'ACT', 11, 11, 'Na sisya, oyu kwaũngama andũ atatũ mbee wa nyũmba ĩla twaĩ, matũmĩtwe kũla nĩĩ kuma Kaĩsalea.'),
('kam', 'ACT', 11, 12, 'Na Veva ambĩa nĩthi nao, nde na kĩvathũkan’yo. Na ana‐a‐asa aa thanthatũ maendan’ya nakwa; na twavota nyũmbanĩ ya ũla mũndũ:'),
('kam', 'ACT', 11, 13, 'nake atũtavya ũndũ ũnoonie mũlaĩka aũngeme nthĩnĩ wa nyũmba yake, aiasya, Tũma andũ mathi Yova, mamũlatye Simoni, ũla wĩ na syitwa yĩngĩ ya kelĩ, Vetelo;'),
('kam', 'ACT', 11, 14, 'ũla wĩkũtavya ndeto ila syĩkũtangĩĩa, we na nyũmba yaku yonthe.'),
('kam', 'ACT', 11, 15, 'Na kweethĩwa ngyambĩlĩlya ũneena nao, Veva Mũtheu amatheeea, o ũndũ watũtheeie ithyĩ mwambĩlĩlyonĩ.'),
('kam', 'ACT', 11, 16, 'Na indĩ nalilikana ndeto ya Mwĩaĩi, ũndũ waisye, Nĩ w’o, Yoana nĩwavatisie na kĩw’ũ; ĩndĩ inyw’ĩ mũkavatiswa nĩ Veva Mũtheu.'),
('kam', 'ACT', 11, 17, 'Ethĩwa ĩndĩ Ngai nũmanengete mũthĩnzĩo o ũla watũnengie ithyĩ, twamwĩtĩkĩla Mwĩaĩi Yesũ Klĩsto, nyie nai ũũ, kana nĩtonye kũmũsiĩĩa Ngai?'),
('kam', 'ACT', 11, 18, 'Namo meew’a maũndũ asu, mavindya ki, na mamũtaĩa Ngai, maiasya, O na Andũ‐ma‐mbaĩ‐ingĩ Ngai nũmanengete ũalyũlo wa ngoo ũetae thayũ.'),
('kam', 'ACT', 11, 19, 'Na ĩndĩ ala manyaĩĩkĩtw’e nũndũ wa ũnyamao ũla wookĩlile kwondũ wa Sitivini, mathi mavika Voenike, na Kuvolo, na Andiokia, mateũneena ĩla ndeto kwa mũndũ ate o kwa Ayuti oka.'),
('kam', 'ACT', 11, 20, 'Ĩndĩ kwaĩ amwe moo, aũme ma Kuvolo na Kulene, ala, yĩla mavikie Andiokia, mamatavisye Akiliki nao, maitavan’ya Mwĩaĩi Yesũ.'),
('kam', 'ACT', 11, 21, 'Na kw’oko kwa Mwĩaĩi kwaĩ vamwe nao: na andũ aingĩ meetĩkĩla na mamwĩthyũũĩa Mwĩaĩi.'),
('kam', 'ACT', 11, 22, 'Na ũvoo woo wavika matũnĩ ma ĩkanisa yĩla yaĩ Yelusaleme: nao mamũtũma Valanava avike Andiokia:'),
('kam', 'ACT', 11, 23, 'nake yĩla wavikie, na kwona mũmo wa Ngai, atana; na amataa onthe, nĩ kana malũman’ye na Mwĩaĩi na kwenda kwa ngoo:'),
('kam', 'ACT', 11, 24, 'nĩkwĩthĩwa we aĩ mũndũ mũseo, na kusũwa nĩ Veva Mũtheu na mũĩkĩĩo. Na andũ aingĩ mongeleka ngalĩ ya Mwĩaĩi.'),
('kam', 'ACT', 11, 25, 'Na ĩndĩ athi Taliso kũmũmantha Saulo;'),
('kam', 'ACT', 11, 26, 'na amwona, amũete Andiokia. Na meethiwa makyũmbana na ĩkanisa ĩvinda ya mwaka mũima, na mamanyĩsya andũ aingĩ; na ala amanyĩw’a mambĩlĩlya kwĩtwa Aklĩsto ndũanĩ ĩsu ya Andiokia.'),
('kam', 'ACT', 11, 27, 'Na mĩthenya isu kwatheeie athani kuma Yelusaleme maithi Andiokia.'),
('kam', 'ACT', 11, 28, 'Na ũmwe woo wetawa Akavo aũngama, na oonan’ya kwa Veva kana kũkooka yũa ĩnene ĩũlũ wa nthĩ yonthe: nayo yooka mĩthenya ya Kilautiosi Kaisali.'),
('kam', 'ACT', 11, 29, 'Na ala amanyĩw’a, kĩla mũndũ kwĩanana na ũtonyi wake, masũanĩa, matw’a kũmatwaĩa ũtethyo ana‐a‐ĩthe moo ala matwie Yutia:'),
('kam', 'ACT', 11, 30, 'nao meeka ũu, mamatwaĩa atumĩa na moko ma Valanava na Saulo.'),
('kam', 'ACT', 12, 1, 'Na ta ĩvinda yĩu mũsumbĩ Elote atambũũkya moko make amathĩn’ye andũ amwe ma ĩkanisa.'),
('kam', 'ACT', 12, 2, 'Na amũaa Yakovo mwana‐a‐inyia wa Yoana na ũvyũ.'),
('kam', 'ACT', 12, 3, 'Na oona kana Ayuti mendeew’a nĩ ũu, aendeea naw’o na amũkwata Vetelo nake. Na mĩthenya ĩsu yaĩ mĩthenya ya kĩmũtũ kĩte ĩlawa.'),
('kam', 'ACT', 12, 4, 'Na amũkwata amwĩkĩa kolokolonĩ, na amũnengane kwa asikalĩ, ana, ana, kũndũ kũna, mamũsũvĩe; akyenda ĩtina wa Vasaka kũmumya na kũmwia mbee wa andũ.'),
('kam', 'ACT', 12, 5, 'Na Vetelo ĩndĩno asũvĩwa kolokolonĩ: ĩndĩ ĩkanisa yamũvoya Ngai na ũthangaau kwondũ wake.'),
('kam', 'ACT', 12, 6, 'Na yĩla Elote wendie kũmumaalya, ũtukũ o ũsu Vetelo akomete katĩ wa asikalĩ elĩ, ovetwe na mĩnyololo ĩlĩ: na asũvĩi ma mũomonĩ maisũvĩa kolokolo.'),
('kam', 'ACT', 12, 7, 'Na sisya, mũlaĩka wa Mwĩaĩi aũngama ũtee wake, na kyeni kyakena kasũmbanĩ kala waĩ: na amũkũna Vetelo mbaunĩ, amũamũkya, akyasya, Ũkĩla mĩtũki. Na ĩla mĩnyololo yavalũka yauma mokonĩ make.'),
('kam', 'ACT', 12, 8, 'Na mũlaĩka amwĩa, Ĩvotoe noiĩkĩa iatũ syaku. Nake eeka ũu. Na amwĩa, Ĩvw’ĩke ngũa yaku noimbikĩla.'),
('kam', 'ACT', 12, 9, 'Nake aumaala nza, amũvikĩla; na ndeesĩ kana nĩ w’o ũla weekwa nĩ mũlaĩka, ĩndĩ aasya nĩwona woni.'),
('kam', 'ACT', 12, 10, 'Na mavĩtũka ũsũvĩo wa mbee na wa kelĩ, mavika mbingĩlonĩ ya kĩaa ĩla ĩendaa ndũanĩ; nayo yamevingũĩa e yo: na maumaala, na mavĩta maienda na mbee na nzĩa ĩmwe nene na oyu mũlaĩka athi amũtia.'),
('kam', 'ACT', 12, 11, 'Na Vetelo avindũka, asya, Yu nĩnamanya vyũ kana Mwĩaĩi nĩwatũma mũlaĩka wake na anumya kw’okonĩ kwa Elote na weteelonĩ w’onthe wa andũ ma Ayuti.'),
('kam', 'ACT', 12, 12, 'Na aisũanĩa ũndũ ũsu, avika nyũmbanĩ ya Meli nyinyia wa Yoana ũla waĩ na syĩtwa yĩngĩ ya Maliko; vala andũ aingĩ mombanĩte makĩvoya.'),
('kam', 'ACT', 12, 13, 'Na aivingũsya mũomonĩ wa mbingĩlo, mwĩĩtu ooka kwĩthukĩĩsya, eetawa Lota.'),
('kam', 'ACT', 12, 14, 'Na amanya wasya wa Vetelo, ndaavingũa mbingĩlo kwondũ wa kũtana, ĩndĩ asemba nthĩnĩ, na amatavya andũ kana Vetelo aũngeme mbee wa mbingĩlo.'),
('kam', 'ACT', 12, 15, 'Nao mamwĩa. Wĩ na ndũũka we. Ĩndĩ alũlũmĩlya mũno, akyasya kana nĩ w’o. Namo masya, Nĩ mũlaĩka wake.'),
('kam', 'ACT', 12, 16, 'Ĩndĩ Vetelo ekala aivingũsya: na mamũvingũĩa, mamwona, na maseng’a.'),
('kam', 'ACT', 12, 17, 'Ĩndĩ we amavindĩthya na kw’oko, na amatavya ũndũ Mwĩaĩi wamumya kolokolonĩ. Na amea, Mũtavyei Yakovo na ana‐a‐asa maũndũ asu. Na aumaala, aenda vandũ vangĩ.'),
('kam', 'ACT', 12, 18, 'Na kwakya kwaya kĩthokoan’yo kĩnene kya asikalĩ atĩ Vetelo aangie ata.'),
('kam', 'ACT', 12, 19, 'Na Elote amũmantha, na alea ũmwona, amakũlya ala asũvĩi, na indĩ atw’a moawe. Na ĩtina atheea kuma Yutia athi Kaisalea, na ekala kw’o.'),
('kam', 'ACT', 12, 20, 'Nake amathatĩa mũno andũ ma Tile na Sitoni: na maenda kwake na ngoo ĩmwe, na matuma ndũũ na Vilasito ũla waĩ mũsũviĩ wa nyũmba ĩla mũsumbĩ Elote wakomaa, mamũvoya methĩwe na mũuo, nũndũ nthĩ yoo yonaa lĩu ũndũ wa nthĩ ya mũsumbĩ.'),
('kam', 'ACT', 12, 21, 'Na mũthenya ũmwe ũla watw’ĩtwe, Elote eevw’ĩka ngũa sya kĩũsumbĩ, na ekalĩla kĩvĩla kya ũsumbĩ, na atavan’ya ndeto nzeũvye mbee wamo.'),
('kam', 'ACT', 12, 22, 'Na yĩla ĩkomano yaneena mũno, yĩkyasya, Nĩ wasya wa ngai, ti wasya wa mũndũ.'),
('kam', 'ACT', 12, 23, 'Na kavinda kau mũlaĩka wa Mwĩaĩi amũkũna, nĩkwĩthĩwa ndaamũnenga Ngai ndaĩa: nake aĩwa nĩ iinyũ, na aumwa nĩ veva.'),
('kam', 'ACT', 12, 24, 'Ĩndĩ ndeto ya Ngai yeana na yaingĩva.'),
('kam', 'ACT', 12, 25, 'Na Valanava na Saulo mamina kwĩanĩsya ũthũkũmi woo mauma Yelusaleme, me na Yoana ũla waĩ na syĩtwa yĩngĩ ya Maliko.'),
('kam', 'ACT', 13, 1, 'Na ĩkanisanĩ yĩla yaĩ Andiokia, kwaĩ athani na amanyĩsya, Valanava, na Simeoni ũla wetawa Nikeli, na Lukio wa Kulene, na Manaene ũla waeanĩwe na Elote ũla wai mũsumbĩ ĩndĩ maiaasyaanĩw’a, na Saulo.'),
('kam', 'ACT', 13, 2, 'Na makĩmũthũkũma Mwiaĩi, na kwĩkala mateũya, Veva Mũtheu asya, Mbathĩai Valanava na Saũlo kwondũ wa ũla wĩa nametĩe.'),
('kam', 'ACT', 13, 3, 'Na ĩndĩ mamina kũtĩĩa ũya na kũvoya na kũmailĩĩla moko moo, mamatũma mathi.'),
('kam', 'ACT', 13, 4, 'Nao ĩndĩ, matũmwa nĩ Veva Mũtheu, matheea mathi Seleusi; na kuma vau mathi na ngalawa Kuvolo.'),
('kam', 'ACT', 13, 5, 'Na yĩla maĩ Salamisi, matavan’ya ĩla ndeto ya Ngai masinakokenĩ ma Ayuti: na maĩ na Yoana nake aĩ mũtethya woo.'),
('kam', 'ACT', 13, 6, 'Na matvĩtĩla kĩthamanĩ kyonthe mavika Vavo, moona mũndũ mũe ũmwe, mwathani wa ũvũngĩ, Mũyuti, syĩtwa yake nĩyo Vali‐Yesũ;'),
('kam', 'ACT', 13, 7, 'nake aĩ vamwe na mũnene wetawa Selikio Vaulo, mũndũ mũmanyi. Ũsu ameta Valanava na Saulo moke kwake, akyenda kwĩw’a ndeto ya Ngai.'),
('kam', 'ACT', 13, 8, 'Ĩndi Elumo ũla mũndũ mũe (nũndũ nĩw’o ũilyĩ ũalyũlo wa syĩtwa yake) amakananĩsya, aimantha kũmwathũkya ũla mũnene kũmumya mũĩkĩĩonĩ.'),
('kam', 'ACT', 13, 9, 'Ĩndi Saulo, nake nĩwĩtawa Vaulo, ausũĩtwe nĩ Veva Mũtheu, amũketeea na metho make,'),
('kam', 'ACT', 13, 10, 'na asya, We, usũĩte ũkengani na wai w’onthe, we, mwana wa ndevili, na mũmaitha wa ũlũngalu w’onthe, ndũkaeka kwathũkya nzĩa ndũngalu sya Mwĩaĩi?'),
('kam', 'ACT', 13, 11, 'Na yu, sisya, kw’oko kwa Ngai kwĩ ĩũlũ waku, naku ũkeethĩwa kĩlilinda, ũtona syũa kwa ĩvinda. Na oyu kwamũtheea wiki na kĩvindu; na aenda aivavata aimantha mũndũ amũkwate kw’oko amũtongoesye.'),
('kam', 'ACT', 13, 12, 'Na ĩndĩ ũla mũnene, oona ũndũ kweekwa, eetĩkĩla, aiseng’w’a nĩ ũmanyĩsyo wa Mwĩaĩi.'),
('kam', 'ACT', 13, 13, 'Na ĩndĩ Vaulo na ala maĩ nake mauma Vavo mathi na ngalawa, na mavika Velika nthĩ ya Vambilia: na Yoana ataanĩĩsya namo vo asyoka Yelusaleme.'),
('kam', 'ACT', 13, 14, 'Ĩndĩ mo, mavĩta mauma Velika, mavika Andiokia nthĩ ya Visitia; nao mathi ĩsinakokenĩ mũthenya wa savato na mekala nthĩ.'),
('kam', 'ACT', 13, 15, 'Na ĩtina wa kũsoma mĩao na mavuku ma athani, anene ma ĩsinakoke matũma mũndũ kwamo, amea, Ana‐a‐asa, ethĩwa mwĩ na ndeto ya ũtao ya ũmatavya andũ aa, neenai.'),
('kam', 'ACT', 13, 16, 'Na Vaulo aũngama, na amokĩlĩlya kw’oko, asya, Aũme ma Isilaeli, na inyw’ĩ ala mũkĩaa Ngai, ithukĩĩsyei:'),
('kam', 'ACT', 13, 17, 'Ngai wa andũ asu ma Isilaeli nĩwamanyuvie aaĩthe maitũ, na amanenevya andũ asu yĩla matwĩe ũeni nthĩ ya Misili, na amatongoesya na kũmaumya nthĩ ĩsu na kw’oko kwĩ vinya.'),
('kam', 'ACT', 13, 18, 'Na ĩvinda ya myaka mĩongo ina amakua na kũmĩĩsya meko moo weũnĩ.'),
('kam', 'ACT', 13, 19, 'Na aananga mbaĩ mũonza nthĩ ya Kanaani, amanenga nthĩ syasyo syĩthĩwe ũtiĩwa woo, ĩvinda ya myaka maana ana na mĩongo ĩtano:'),
('kam', 'ACT', 13, 20, 'na ĩtina wa maũndũ asu amanenga asili kũvika mwathani Samueli.'),
('kam', 'ACT', 13, 21, 'Na ĩtina mamũvoya manengwe mũsumbĩ: na Ngai amanenga Saulo, mwana wa Kisi, mũndũ wa mbaĩ ya Mbenyamini, ĩvinda ya myaka mĩongo ĩna.'),
('kam', 'ACT', 13, 22, 'Na amũveta ũsu, amũkĩlya Ndaviti ethĩwe mũsumbĩ woo; nake nĩwamũkũsĩĩe, aiasya, Nĩnamwona Ndaviti, mwana wa Yese, mũndũ wendeeasya ngoo yakwa, ũla ũkeka kwenda kwakwa kw’onthe.'),
('kam', 'ACT', 13, 23, 'Na ũsyaonĩ wa mũndũ ũsu kwĩanana na watho wake, Ngai amaetee Isilaeli Mũtangĩĩi Yesũ;'),
('kam', 'ACT', 13, 24, 'Yoana aĩ anamba ũtavan’ya ũvatiso wa ũalyũlo wa ngoo kwa andũ onthe ma Isilaeli, mbee wa kũka kwake.'),
('kam', 'ACT', 13, 25, 'Na Yoana akĩminũkĩlya mũendo wake, nĩwaisye, Mwĩndalĩlya ninyie ũũ? Tii nyie we. Ĩndĩ sisyai, nĩkũkĩte ũmwe ĩtina wakwa ũla ndyĩaniwe nĩ ũthasya iatũ sya maũũ make.'),
('kam', 'ACT', 13, 26, 'Ana‐a‐asa, ana ma ũsyao wa Avalaamu, na ala me katĩ wenyu ala mũkĩaa Ngai, ndeto ya ũtangĩĩo ũũ nĩtũmĩtwe kwitũ.'),
('kam', 'ACT', 13, 27, 'Nĩkwĩthĩwa ala matwĩe Yelusaleme, vamwe na anene moo, nũndũ maiaamũmanya, o na mawasya ma athani ala masomawa kĩla mũthenya wa savato, mameanĩsye kwa ũmũsilĩla.'),
('kam', 'ACT', 13, 28, 'O na kau maiaaona ũndũ ũtuma mamũaa, ĩndĩ mamũvoya Vilato kana oawe.'),
('kam', 'ACT', 13, 29, 'Na mamina kwĩanĩsya maũndũ onthe ala maandĩkiwe kwondũ wake, mamwambũa mũtĩnĩ, na mamwia mbũanĩ.'),
('kam', 'ACT', 13, 30, 'Ĩndĩ Ngai amũthayũũkya amumya kwa akw’ũ:'),
('kam', 'ACT', 13, 31, 'nake nĩwonekie matukũ maingĩ nĩ ala mambatie nake Yelusaleme kuma Kalilii, namo nĩo ngũsĩ syake yu mbee wa andũ.'),
('kam', 'ACT', 13, 32, 'Na nĩtũmũetee ũvoo mũseo wa ũla watho wanengiwe aasa,'),
('kam', 'ACT', 13, 33, 'ũndũ Ngai wawĩanĩsye kwa syana sitũ, kwondũ wa kũmũthayũũkya Yesũ; o ũndũ kũandĩkĩtwe Savuli kĩlungu kya keli, Nue mwana wakwa, ũmũnthĩ nĩnaũsyaa.'),
('kam', 'ACT', 13, 34, 'Na kwa kwĩthĩwa nĩwamũthayũũkisye kũmumya kwa akw’ũ, atekũsyoka wanangĩkonĩ ĩngĩ, aneenete atĩĩ, Ngamũnenga inyw’ĩ moathimo ma Ndaviti ala matheu na ala maĩkĩĩĩka.'),
('kam', 'ACT', 13, 35, 'Nũndũ nĩwaisye naw’o, Savuli vandũ vangĩ, Ndũkanengane Mũtheu waku one wanangĩko.'),
('kam', 'ACT', 13, 36, 'Nĩkwĩthĩwa Ndaviti, athũkũmĩte ũtw’ĩo wa Ngai ũsyaonĩ wa ĩvinda yake, nĩwakomie, na aiwa na aaĩthe make, na oona wanangĩko:'),
('kam', 'ACT', 13, 37, 'ĩndĩ ũla wokĩlilw’e nĩ Ngai ndaaona wanangĩko.'),
('kam', 'ACT', 13, 38, 'Ĩndĩ ũndũ ũũ nũmanyĩke kwenyu, ana‐a‐asa maitũ, kana kwondũ wa mũndũ ũũ nĩkũũtavanw’a kwa inyw’ĩ ũekeo wa naĩ:'),
('kam', 'ACT', 13, 39, 'na kwondũ wake kĩla mũndũ ũla ũmwĩtĩkĩlaa nũtalĩlawa ũlũngalu maũndũnĩ onthe, ala kwondũ wa mĩao ya Mose mũtaatonya kũtalĩlwa ũlũngalu.'),
('kam', 'ACT', 13, 40, 'Ĩsũvĩei ĩndĩ, ũla waneeniwe mavukunĩ ma athani ndũkese ũmũvikĩa:'),
('kam', 'ACT', 13, 41, 'Sisyai, inyw’ĩ avũthya, seng’ai, na anangĩkai; Nũndũ nĩtethya wĩa mĩthenya yenyu, Wĩa ũla mũtaketĩkĩla nongi, o na ethĩwa mũndũ akamũtavya.'),
('kam', 'ACT', 13, 42, 'Na makyumaala, mamwĩsũva matavw’e ndeto isu savato ũla wũkĩte.'),
('kam', 'ACT', 13, 43, 'Na andũ ala maĩ ĩsinakokenĩ mataanĩsya, aingĩ ma Ayuti na avikĩlĩ ma Kĩyuti makĩaa Ngai mamaatĩĩa Vaulo na Valanava; nao maineena nao mamathing’ĩĩsya mekalae mumonĩ wa Ngai.'),
('kam', 'ACT', 13, 44, 'Na savato ũsu ũngĩ, meethĩwa mombanĩte ta ndũa nima methukĩĩsye ndeto ya Ngai.'),
('kam', 'ACT', 13, 45, 'Ĩndĩ Ayuti moona makomano, mausũwa nĩ kĩwĩu, na makananĩsya ndeto ila syaneeniwe nĩ Vaulo makĩumana.'),
('kam', 'ACT', 13, 46, 'Na Vaulo na Valanava maneena na ũkũmbaũ maiasya, No mũvaka ndeto ya Ngai ĩneenwe mbee kwenyu. Ĩndĩ kwa kwĩthĩwa nĩmwamĩluutile yume kwenyu, na kwĩtw’ĩĩa ene kana mũiaĩlwe nĩ thayũ wa tene na tene, sisyai, nĩtũũalyũka twelekele Andũ‐ma‐mbaĩ‐ingi.'),
('kam', 'ACT', 13, 47, 'Nũndũ niw’o tweeaĩwe nĩ Mwĩaĩi, aiasya, Nĩkwiĩte we wĩthĩwe kyeni kya Andũ‐ma‐mbaĩ‐ingĩ, Ni kana wĩthĩwe ũtangĩĩo kũvika itulunĩ syonthe sya nthĩ.'),
('kam', 'ACT', 13, 48, 'Na Andũ‐ma‐mbaĩ‐ingĩ meew’a ũu, matana, na mataia ndeto ya Ngai: na ũndũ meanaa ala manyuvĩtwe kwĩthĩwa na thayũ ũtathela nĩmeetĩkĩlile.'),
('kam', 'ACT', 13, 49, 'Na ndeto ya Mwĩaĩi yanyaiĩkw’a nthĩ isu yonthe.'),
('kam', 'ACT', 13, 50, 'Ĩndĩ Ayuti nĩmamaingĩanĩsye aka me nguma, athaithi anene, na atumĩa anene ma ndũa, na mamokĩlĩlya Vaulo na Valanava thĩna mũnene, na mamalũngya maume mĩvakanĩ yoo.'),
('kam', 'ACT', 13, 51, 'Ĩndĩ mamatuangĩa kĩtoo kya nyaĩĩ syoo, na mathi Ikonio.'),
('kam', 'ACT', 13, 52, 'Na amanyĩw’a mausũĩtwe nĩ ũtanu na Veva Mũtheu.'),
('kam', 'ACT', 14, 1, 'Na kweethĩwa malika vamwe ĩsĩnakokenĩ ya Ayuti ndũanĩ ya Ikonio, na maneenie ũndũ nguthu nene ya Ayuti na ya Akiliki yeetĩkĩla.'),
('kam', 'ACT', 14, 2, 'Ĩndĩ Ayuti ala matetĩkĩlĩte mathokoan’ya ngoo sya Andũ‐ma‐mbaĩ‐ingĩ, na mamendethya ũthũku ĩũlũ wa ana‐a‐asa.'),
('kam', 'ACT', 14, 3, 'Na kwa ũu mekala vo matukũ maingĩ makĩneena na ũkũmbaũ nthĩnĩ wa Mwĩaĩi, ũla wakũsĩĩe ĩla ndeto ya mumo wake, aimanenga syama na momakyo mekwe na moko moo.'),
('kam', 'ACT', 14, 4, 'Ĩndĩ ĩkomano ya andũ ma ndũa yavathũkana; amwe maĩ ngalĩ ya Ayuti, na amwe maĩ ngalĩ ya atũmwa.'),
('kam', 'ACT', 14, 5, 'Ĩndĩ Andũ‐ma‐mbaĩ‐ingi na Ayuti na anene moo menda kũmavithũkĩa, mameke nai na ũmakima na mavia,'),
('kam', 'ACT', 14, 6, 'mamanya, na makia mathi ndũanĩ sya nthĩ ya Laikonia, Lisitela na Ndelive, na ivaloni ila syĩ ndee:'),
('kam', 'ACT', 14, 7, 'na matavan’ya ũla ũvoo mũseo kw’o.'),
('kam', 'ACT', 14, 8, 'Na Lisitela kwaĩ mũndũ ũmwe waĩ mwau maũũ, kyonze kuma asyawa, ũtaakinya nongi.'),
('kam', 'ACT', 14, 9, 'Ũsu amwĩthukĩĩsya Vaulo aineena: na Vaulo amũketeea, na akyona kana e na mũĩkĩĩo wa kũvow’a,'),
('kam', 'ACT', 14, 10, 'amũtavya na wasya mũnene, Ũngama vyũ na maũũ maku. Nake ookĩla aithaka na eekinyie.'),
('kam', 'ACT', 14, 11, 'Na ĩkomano yoona ũndũ Vaulo weka, mookĩlya mawasya moo, maiasya na kĩthyomo kya Laikonia, Ila ngai nĩsyatũtheeea ivw’anene na andũ.'),
('kam', 'ACT', 14, 12, 'Na Valanava mamwĩta Yuvita; na Vaulo mamwĩta Mekyuli, nĩkwĩthĩwa aĩ mũneeni mũno.'),
('kam', 'ACT', 14, 13, 'Na mũthembi wa Yuvita, nayo ĩkalũ yayo yaĩ ngalĩ ya mbee ya ndũa, aete ng’ombe na mĩsonzo ya malaa mbingĩlonĩ, akyenda kũthemba vamwe na makomano.'),
('kam', 'ACT', 14, 14, 'Ĩndĩ atũmwa, Valanava na Vaulo, meew’a ũvoo ũsu, matembũanga ngũa syoo, na matũlĩla mathi ĩkomanonĩ, mokĩlĩtye mawasya,'),
('kam', 'ACT', 14, 15, 'maiasya, Aũme, nĩkĩ mũkwĩka maũndũ aa? Ithyĩ naitũ twĩ andũ tũilyĩ tenyu, na nĩtũmũetee ũvoo mũseo, nĩ kana mwĩthyũũe na kũekana na maũndũ aa ma mana, mũmwelekele Ngai ũla wĩ thayũ, ũla wombie ĩtu na nthĩ na ũkanga, na syĩndũ syonthe ila syĩ nthĩnĩ wasyo:'),
('kam', 'ACT', 14, 16, 'ũla waekie mbaĩ syonthe mavinda ala mavĩtie ithi na nzĩa syasyo ene.'),
('kam', 'ACT', 14, 17, 'Ĩndĩ vamwe na ũu ndaaĩtia vate ũkũsĩ, nĩkwĩthĩwa eekie nesa aimũnenga mbua kuma ĩtunĩ, na mavinda ma ũketha, aimusũĩsya lĩu na ũtanu ngoonĩ syenyu.'),
('kam', 'ACT', 14, 18, 'Na vamwe na ndeto ii vatiele vanini maemwe kũsiĩĩa ĩkomano kũmathembea.'),
('kam', 'ACT', 14, 19, 'Ĩndĩ kwooka Ayuti kw’o kuma Andiokia na Ikonio: na mamaingĩĩsya makomano, mamũkimanga Vaulo na mavia, na mamũkusya mamumya ndũanĩ, maitalĩlya kana nĩ mũkw’ũ.'),
('kam', 'ACT', 14, 20, 'Ĩndĩ amanyĩw’a maũngeme mamũthyũlũlũkĩte, ookĩla, na avota ndũanĩ: na ũnĩ ũsu aumaala vamwe na Valanava mathi Ndelive.'),
('kam', 'ACT', 14, 21, 'Na matavan’ya ũvoo mũseo ndũanĩ ĩsu, na matw’ikĩthya andũ aingĩ amanyĩw’a, maalũka Lisitela, na Ikonio, na Andiokia,'),
('kam', 'ACT', 14, 22, 'makĩlũlũmĩlya ngoo sya amanyĩw’a, makĩmataa mekalae ũla mũĩkĩĩonĩ, na maimon’ya kana tũitĩa kũvĩtĩla mathĩnanĩ maingĩ tũilika ũsumbĩnĩ wa Ngai.'),
('kam', 'ACT', 14, 23, 'Na mamaiĩa atumĩa kĩla ĩkanisa, na mavoya Ngai mateũya, mamanengane kwa Mwĩaĩi ũla metĩkĩlĩte.'),
('kam', 'ACT', 14, 24, 'Na mavĩtĩla Visitia, na mooka Vambilia.'),
('kam', 'ACT', 14, 25, 'Na maneena ĩla ndeto Velika, matheea Atalia;'),
('kam', 'ACT', 14, 26, 'na kuma vo mathi na ngalawa Andiokia, vala manenganĩwe mumonĩ wa Ngai kwondũ wa wĩa ũla meanĩsye.'),
('kam', 'ACT', 14, 27, 'Nao mavika, na moomban’ya ĩkanisa vamwe, mayĩtavya maũndũ onthe ala Ngai wĩkĩte namo, na ũndũ ũmavingũĩe Andũ‐ma‐mbaĩ‐ingĩ mũomo wa mũĩkĩĩo.'),
('kam', 'ACT', 14, 28, 'Nao mekala na amanyĩw’a ĩvinda ĩasa.'),
('kam', 'ACT', 15, 1, 'Na andũ amwe matheea kuma Yutia na mamanyĩsya ala ana‐a‐asa, maiasya, Mwalea kwaĩkwa kũatĩĩa kĩthĩo kya Mose, mũitonya kũtangĩĩwa.'),
('kam', 'ACT', 15, 2, 'Na Vaulo na Valanava maĩ manakananĩa na ũkũlan’ya nao mũno, ala ana‐a‐asa matw’a kana Vaulo na Valanava, na angĩ amwe mamo, mambate mathi Yelusaleme kwa atũmwa na atumĩa kwondũ wa ũkũlyo ũsu.'),
('kam', 'ACT', 15, 3, 'Namo ĩndĩ, maumaaw’a nĩ ĩkanisa, mavĩtĩla Voenike na Samalia, maitavan’ya kwĩthyũũĩa Ngai kwa Andũ‐ma‐mbaĩ‐ingĩ: na matan’ya ana‐a‐asa na ũtanu mũnene.'),
('kam', 'ACT', 15, 4, 'Na mavika Yelusaleme, mooswa nĩ ĩkanisa na atũmwa na atumĩa, na mamatavya maũndũ onthe ala Ngai wĩkĩte namo.'),
('kam', 'ACT', 15, 5, 'Ĩndĩ mookĩla amwe meetĩkĩlĩte, ma kĩthemba kya Avalisĩ, masya, Nĩmaĩlwe nĩ kwaĩkwa, na kwĩaĩwa makwate mĩao ya Mose.'),
('kam', 'ACT', 15, 6, 'Na ala atũmwa na atumĩa moombana vamwe kũsũanĩa ũndũ ũsũ.'),
('kam', 'ACT', 15, 7, 'Na maĩ manakũlan’ya mũno, Vetelo aũngama, amea, Ana‐a‐asa, nĩmwĩsĩ kana tene Ngai nĩwanyuvie kwenyu, kana Andũ‐ma‐mbaĩ‐ingĩ mew’e na kanyw’a wakwa ndeto ya ũla ũvoo mũseo, na kwĩtĩkĩla.'),
('kam', 'ACT', 15, 8, 'Na Ngai, ũla wĩsĩ ngoo, amakũsĩĩa, aimanenga Veva Mũtheu, o ũndũ watũnengie ithyĩ;'),
('kam', 'ACT', 15, 9, 'na ndaaĩkĩa kĩvathũkan’yo katĩ waitũ nao, aimathesya ngoo syoo nũndũ wa kũĩkĩĩa.'),
('kam', 'ACT', 15, 10, 'Na ĩndĩ nĩkĩ yu mũũmũtata Ngai, mũimekĩa amanyĩw’a ngingonĩ ĩsoki yĩla aasa maitũ o naitũ twaemiwe nĩ ũkua?'),
('kam', 'ACT', 15, 11, 'Ĩndĩ nĩtwĩtĩkĩle kana ithyĩ tũkatangĩĩwa nũndũ wa mumo wa Mwĩaĩi Yesũ o tamo.'),
('kam', 'ACT', 15, 12, 'Na ĩkomano yonthe yavindya ki; na yeethukĩĩsya Valanava na Vaulo maimatavya ũvoo wa syama na momakyo ala Ngai wĩkĩte kwa Andũ‐ma‐mbaĩ‐ingĩ namo.'),
('kam', 'ACT', 15, 13, 'Nao mamina ũneena, Yakovo asũngĩa, aiasya, Ana‐a‐asa, mbĩthukĩĩsyai:'),
('kam', 'ACT', 15, 14, 'Simoni nĩwatũngĩlĩla ũndũ Ngai wambie kũmokĩa Andũ‐ma‐mbaĩ‐ingĩ, nĩ kana aumye andũ katĩ wamo kwondũ wa syĩtwa yake.'),
('kam', 'ACT', 15, 15, 'Na ndeto sya athani syosanaa na ũu; ũndũ kũandĩkĩtwe,'),
('kam', 'ACT', 15, 16, 'Ĩtina wa maũndũ aa ngaalũka, Nakwa ngaaka wĩkalo wa Ndaviti, ũla mũvalũku; Na ngatũngĩĩa kũla waombokie, Na ngawũũngamya:'),
('kam', 'ACT', 15, 17, 'Nĩ kana ũtialo wa andũ ũmũmanthe Mwĩaĩi, Na Andũ‐ma‐mbaĩ‐ingĩ onthe, ala syĩtwa yakwa yĩũwetwa ĩũlũ woo,'),
('kam', 'ACT', 15, 18, 'Easya ũu Mwĩaĩi, ũla ũtumaa maũndũ aa mamanyĩka kuma tene.'),
('kam', 'ACT', 15, 19, 'Kwondũ wa ũu, nĩtw’a atĩ tũikamanyamasye Andũ‐ma‐mbaĩ‐ingĩ ala meĩthyũũa na ũmwelekela Ngai;'),
('kam', 'ACT', 15, 20, 'ĩndĩ nĩtũmaandĩkĩe, mevathane na movukyo na mĩvw’anano, na ũlaalai, na syĩndũ ila sitĩtwe, o na nthakame.'),
('kam', 'ACT', 15, 21, 'Nũndũ kuma mavinda ma tene kĩla ndũanĩ Mose e na ala matavanasya ũvoo wake, ũkĩsomeawa masinakokenĩ mĩthenya yonthe ya savato.'),
('kam', 'ACT', 15, 22, 'Na ĩndĩ atũmwa na atumĩa, vamwe na ĩkanisa yonthe, moona nĩ ũseo kũnyuva andũ amwe moo, na kũmatũma Andiokia vamwe na Vaulo na Valanava; namo nĩ aa, Yutasi wĩtawa syĩtwa yĩngĩ Valisava, na Sila, andũ me na nguma katĩ wa ana‐a‐asa:'),
('kam', 'ACT', 15, 23, 'na maandĩka na ũmatwaĩa namo, Atũmwa na atumĩa, ana‐a‐asa, valũa ũũ witũ ũmavikĩe ana‐a‐asa ma Andũ‐ma‐mbaĩ‐ingĩ ala me Andiokia na Silia na Silisia, nũvoo:'),
('kam', 'ACT', 15, 24, 'Nĩkwĩthĩwa nĩtwĩw’ĩte kana andũ amwe ala maumie kwitũ nĩmamũthĩnitye na ndeto syoo, na kũthyũũa ngoo syenyu; nao tũiaameaĩa;'),
('kam', 'ACT', 15, 25, 'naitũ twonete nĩ ũseo, nĩkwĩthĩwa twĩw’anĩte na ngoo ĩmwe, kũnyuva andũ na kũmatũma kwenyu vamwe na endwa maitũ Valanava na Vaulo,'),
('kam', 'ACT', 15, 26, 'andũ ala malikĩtye mathayũ moo mũisyonĩ kwondũ wa syĩtwa ya Mwĩaĩi waitũ Yesũ Klĩsto.'),
('kam', 'ACT', 15, 27, 'Ĩndĩ twatũma Yutasi na Sila, nao ene makamũtavya ndeto isu na makanyw’a moo.'),
('kam', 'ACT', 15, 28, 'Nĩkwĩthĩwa Veva Mũtheu onie nĩ ũseo, naitũ no ta ũu, tũikamwaĩkye inyw’ĩ mũio ũthonokete maũndũ aa me na vata wa kwĩthĩwa:'),
('kam', 'ACT', 15, 29, 'nao nĩ aa, kana mwĩvathane na syĩndũ ila syũaĩawa mĩvw’anano, na nthakame, na syĩndũ ila sitĩtwe, na ũlaalai; mweesũvĩa maũndũ asu, kũkeethĩwa ũseo kwenyu. Ĩkalai na ũvoo.'),
('kam', 'ACT', 15, 30, 'Namo, mamina kũnengwa ũthei, matheea Andiokia; na moomban’ya ikomano yonthe vamwe, mamanenga ũla valũa.'),
('kam', 'ACT', 15, 31, 'Nao moosoma, matana nũndũ wa ũkiakisyo ũsu.'),
('kam', 'ACT', 15, 32, 'Na Yutasi na Sila, kwa kwĩthĩwa maĩ athani, mamataa ana‐a‐asa na ndeto nyingĩ, na ũmalũlũmĩlya.'),
('kam', 'ACT', 15, 33, 'Nao mekala vo ĩvinda ĩasa, meew’a mathi na mũuo, nao mauma kwa ana‐a‐asa masyoka kwa ala mamatũmie. ('),
('kam', 'ACT', 15, 34, 'Ĩndi Sila nĩwendie kwĩkalanga kw’o.)'),
('kam', 'ACT', 15, 35, 'Ĩndĩ Vaulo na Valanava mekala Andiokia, makĩmanyĩsya na kũtavan’ya ndeto ya Mwĩaĩi, me na andũ angĩ aingĩ.'),
('kam', 'ACT', 15, 36, 'Na mithenya ĩmwe yavĩta Vaulo amwĩa Valanava, Tũalũke ĩndĩ yu tũmasisye ana‐a‐asa ala me ndũanĩ syonthe kũla twatavanisye ndeto ya Mwĩaĩi, ũndũ mailyĩ.'),
('kam', 'ACT', 15, 37, 'Na Valanava endie Yoana aendan’ye nao, ũla wetawa syĩtwa yĩngĩ Maliko.'),
('kam', 'ACT', 15, 38, 'Ĩndĩ Vaulo oona ti ũseo kũthi na ũsu ũla wamatiie Vambilia, alea ũlika ũla wĩanĩ vamwe namo.'),
('kam', 'ACT', 15, 39, 'Na ĩndĩ kwookĩla ĩteta yai, na mataanĩsya ũmwe na ũla ũngĩ, na Valanava oosa Maliko aendan’ya nake, na athi na ngalawa Kuvolo:'),
('kam', 'ACT', 15, 40, 'ĩndĩ Vaulo amũnyuva Sila, nake aumaala, anenganwe mumonĩ wa Mwĩaĩi nĩ ana‐a‐asa.'),
('kam', 'ACT', 15, 41, 'Nake avĩtĩla Silia na Silisia aimalũlũmĩlya makanisa.'),
('kam', 'ACT', 16, 1, 'Na ĩndĩ avika Ndelive na Lisitela: na sisya, vaĩ mũmanyĩw’a ũmwe vo, wetawa Timotheo, mwana wa mũndũ mũka Mũyuti wetĩkĩlĩte; ĩndĩ ĩthe aĩ Mũkiliki.'),
('kam', 'ACT', 16, 2, 'Ũsu awetawa nesa nĩ ana‐a‐asa ala matwĩe Lisitela na Ikonio.'),
('kam', 'ACT', 16, 3, 'Nake Vaulo endie ũsu aendan’ye nake; na amwosa na amwaĩka nũndũ wa Ayuti ala maĩ ngalĩ isu: nĩkwĩthĩwa onthe nĩmeesĩ kana ĩthe aĩ Mũkiliki.'),
('kam', 'ACT', 16, 4, 'Nao makyanganga ndũanĩ, mamanenga ala motw’ĩo matw’ĩtwe nĩ atũmwa na atumĩa ala maĩ Yelusaleme mamasũvĩe.'),
('kam', 'ACT', 16, 5, 'Na kwondũ wa ũu makanisa malũlũmĩlw’a mũĩkĩĩonĩ, na ũtalo woo waingĩvaa mĩthenya yonthe.'),
('kam', 'ACT', 16, 6, 'Na mavĩtĩla nthĩ ya Velikia na Kalatia, nĩkwĩthĩwa nĩmavatiwe nĩ Veva Mũtheu kũneena ĩla ndeto nthĩ ya Asia;'),
('kam', 'ACT', 16, 7, 'na mavika mũvakanĩ wa Misia, matata kũthi Vithinia; na Veva wa Yesũ ndaamanenga ũthei;'),
('kam', 'ACT', 16, 8, 'na mavĩta Misia, matheea Teloa.'),
('kam', 'ACT', 16, 9, 'Na Vaulo aumĩlĩlwa nĩ woni ũtukũ: oona mũndũ wa Masetonia aũngeme, aimwĩsũva, na aimwĩa, Inga wũke Masetonia, ũtũtethye ithyĩ.'),
('kam', 'ACT', 16, 10, 'Na oona ũla woni, oyu twamantha kũthi Masetonia, twamanya kana Ngai nũtwĩtie tũmatavye ũla ũvoo mũseo.'),
('kam', 'ACT', 16, 11, 'Na ĩndĩ twauma Teloa na ngalawa, twathi tũlũngalĩte twelekele Samothelake, na ũnĩ ũsu twavika Neavoli;'),
('kam', 'ACT', 16, 12, 'na kuma vau twavika Vilivi, nayo nĩ ndũa ya Masetonia, ĩla nene ya nthĩ ĩsu, vala Alomi matwĩe: na twaĩ vo ndũanĩ ĩsu twĩkalĩte mĩthenya ĩmwe.'),
('kam', 'ACT', 16, 13, 'Na mũthenya wa savato twaumaala mbingĩlonĩ nza ũtee wa ũsĩ, vala twatalĩlasya kana ve vandũ va ũvoyea; na twekala nthĩ, twaneena na aka ala mombanĩte.'),
('kam', 'ACT', 16, 14, 'Na mũndũ mũka ũmwe wetawa Litia, mũthoosya wa langi ũla ũilyĩ ta mũtune, ũla wa mũsyĩ wa Thiatila, ũla wathaithaa Ngai, atwĩw’a: na Mwĩaĩi amũvingũa ngoo yake, nĩ kana amethukĩĩsye maũndũ ala maneeniwe nĩ Vaulo.'),
('kam', 'ACT', 16, 15, 'Na avatiswa, vamwe na ala ma nyũmba yake, atwĩsũva, akyasya, Ethĩwa nĩmũmbonete nĩ kĩthito kwa Mwĩaĩi, ũkai nyũmbanĩ kwakwa, mwĩkale vo. Na atũthing’ĩĩsya.'),
('kam', 'ACT', 16, 16, 'Na kweethĩwa, tũendete vala vandũ va ũvoyea, mwĩĩtu ũmwe ũla waĩ na veva wa kũaũsya akomana naitũ, nake amoneaa mavwana make ũtandĩthyo mũnene nũndũ wa kũaũsya kwake.'),
('kam', 'ACT', 16, 17, 'Ũsu akĩtũatĩĩa twĩ na Vaulo, atũlya wasya, akyasya, Aũme aa nĩ ngombo sya Ngai Ũla Wĩ Ĩũlũ wa Onthe, nao nĩmeũmũtavya inyw’ĩ nzĩa ya ũtangĩĩo.'),
('kam', 'ACT', 16, 18, 'Na eekie ũu mĩthenya mingĩ. Ĩndĩ Vaulo akĩw’a woo mũno, eethyũũa na ootavya ũla veva, Nĩkwĩaĩa syĩtwanĩ ya Yesũ Klĩsto, uma nthĩni wake. Naw’o wamuma saa o ũsu.'),
('kam', 'ACT', 16, 19, 'Ĩndĩ mavwana make moona kana wĩkwatyo wa ũtandĩthyo woo nĩwaaa, mamakwata Vaulo na Sila, na mamakusya mathi nao kĩng’ang’anĩ mbee wa asili,'),
('kam', 'ACT', 16, 20, 'na mamaete mbee wa asili, masya, Andũ aa, kwa kwĩthĩwa nĩ Ayuti, nĩmeũthokoan’ya mũno ndũa yaitũ,'),
('kam', 'ACT', 16, 21, 'na kwonan’ya syĩthĩo ila itosana na mĩao yaitũ kũsyosa kana kwiatĩĩa, nĩkwĩthĩwa twĩ Alomi.'),
('kam', 'ACT', 16, 22, 'Na ĩkomano yamokĩlĩla vamwe: na asili mamatembũangĩa ngũa syoo makĩsyumya, na matw’a makũnwe na ndata.'),
('kam', 'ACT', 16, 23, 'Nao mamakũna makũna maingĩ, mamekya kolokolonĩ na mamwĩaĩa mũnene wa kolokolo amasũvĩe mũno:'),
('kam', 'ACT', 16, 24, 'nake, anengwa mwĩao ta ũsu, amekya kasũmbanĩ ka kolokolo kala ke nthĩnĩ mũno, na amovea maũũ moo mĩtĩnĩ.'),
('kam', 'ACT', 16, 25, 'Ĩndĩ ta ũtukũ katĩ Vaulo na Sila meethĩwa maimũvoya Ngai na ũmwinĩa mbathi sya ũmũkatha, na ovwa ala angĩ nĩmamethukĩĩsye;'),
('kam', 'ACT', 16, 26, 'na oyu, o ĩmwe, kwaya kĩtetemo kĩnene kya nthĩ, ũndũ myambĩlĩlyo ya kolokolo yathingithangiw’e: na oyu mĩomo yonthe yavingũka; na syĩndũ ila syoovete asu onthe syathalĩka.'),
('kam', 'ACT', 16, 27, 'Na mũnene wa kolokolo aamũka kuma toonĩ, na oona mĩomo ya kolokolo ĩ mĩvingũku, akũa ũvyũ wake akilĩlye kwĩyũaa, aitalĩlya kana ovwa onthe nĩmakĩie.'),
('kam', 'ACT', 16, 28, 'Ĩndĩ Vaulo aneena na wasya mũnene aiasya, Ndũkeyĩke ũndũ ũthũku: nũndũ ithyonthe twĩ o vaa.'),
('kam', 'ACT', 16, 29, 'Na ĩndĩ eetya mataa, na athaanyũka avota nthĩnĩ, na aitetemwa nĩ w’ĩa, avalũka nthĩ mbee wa Vaulo na Sila,'),
('kam', 'ACT', 16, 30, 'na amaumaalya nza, asya, Mavwana, nĩĩka ata kana ndangĩĩwe?'),
('kam', 'ACT', 16, 31, 'Nao mamwĩa, Mwĩtĩkĩle Mwĩaĩi Yesũ, na nũũtangĩĩwa we, na nyũmba yaku.'),
('kam', 'ACT', 16, 32, 'Na mamũtavya ndeto ya Mwĩaĩi vamwe na onthe ala maĩ nyũmba kwake.'),
('kam', 'ACT', 16, 33, 'Na amosa o saa ũsu wa ũtukũ, na amathambya makũnwa moo; na avatiswa oyu, we na andũ make onthe.'),
('kam', 'ACT', 16, 34, 'Na amambatya amatwaa nyũmbanĩ kwake nthĩnĩ, na aia lĩu mbee wamo, na atana mũno, we na onthe ma nyũmba yake, nũndũ wa kwĩtĩkĩla Ngai.'),
('kam', 'ACT', 16, 35, 'Ĩndĩ kwakya, asili matũma anene ma asikalĩ, maiasya, Thasyai ala andũ mathi.'),
('kam', 'ACT', 16, 36, 'Na mũnene wa kolokolo amũtavya Vaulo ndeto syoo, aiasya, Ala asili matũmana mũthaw’e: yu ĩndĩ umaalai, na mũithi na ũvoo.'),
('kam', 'ACT', 16, 37, 'Ĩndĩ Vaulo amea, Nĩmanatũkũnĩe mbee wa andũ, na tũineesilĩlwa, na ithyĩ twĩ Alomi, na manatwĩkisye kolokolonĩ; na yu nĩmeũtwĩkya nza na kĩmbithĩ? Aiee, ti w’o; ĩndĩ nĩmoke e mo ene matumye.'),
('kam', 'ACT', 16, 38, 'Na anene ma asikalĩ mamatavya asili ndeto isu: namo meew’a kana nĩ Alomi, makĩa;'),
('kam', 'ACT', 16, 39, 'na mooka mamesũva; na mamaumaalya nza, mamavoya maume ndũanĩ yoo.'),
('kam', 'ACT', 16, 40, 'Na mauma kolokolonĩ, malika nyũmbani ya Litia: na moona ana‐a‐asa, mamakiakisya na ĩndĩ mathi.'),
('kam', 'ACT', 17, 1, 'Na mavĩtĩla Amimbivoli na Avolonia, mavika Thesalonika, vala vaĩ ĩsinakoke ya Ayuti:'),
('kam', 'ACT', 17, 2, 'na Vaulo, o ũndũ wakothaa kwĩka, avota kwamo, na vandũ va mĩthenya ĩtatũ ya savato asũanĩa nao ũvoo kuma maandĩkonĩ,'),
('kam', 'ACT', 17, 3, 'aiumĩlya na kwonan’ya kana kwaĩ na vata wa Klĩsto kũthĩna, na kũthayũũka kuma kwa akw’ũ; na ĩngĩ kana Yesũ ũsu, ũla ngũmũtavya inyw’ĩ, nĩwe Klĩsto.'),
('kam', 'ACT', 17, 4, 'Na amwe moo meetĩkĩla, na maatĩanĩa na Vaulo na Sila; na ma ala makĩaa Ngai ma Akiliki nguthu nene, na aka aingĩ me nguma.'),
('kam', 'ACT', 17, 5, 'Ĩndĩ Ayuti, mausũwa nĩ kĩwĩu, meeyosea andũ amwe athũku ma nguthu sya imaamai, na moomban’ya nguthu, meekĩa ndũa kĩthokoan’yo; na mathi nyũmbanĩ ya Yasoni maimantha kũmaumaalya na ũmanengane mokonĩ ma andũ.'),
('kam', 'ACT', 17, 6, 'Na malea ũmona, mamũkusya Yasoni o na ana‐a‐asa amwe amwe mbee wa anene ma ndũa, maiasya, Aa makulumanĩtye nthĩ nĩmokĩte vaa navo;'),
('kam', 'ACT', 17, 7, 'na Yasoni amosa: na aa onthe mekaa maũndũ mavĩtanĩte na motw’ĩo ma Kaisali, maiasya kana kwĩ mũsumbĩ ũngĩ wĩtawa Yesũ.'),
('kam', 'ACT', 17, 8, 'Na maũũyĩthya ĩkomano na anene ma ndũa, meew’a maũndũ asu.'),
('kam', 'ACT', 17, 9, 'Na Yasoni na ala angĩ maumw’a ngwatĩlĩlyo, na mamalekya mathi.'),
('kam', 'ACT', 17, 10, 'Na oyu ala ana‐a‐asa mamea Vaulo na Sila mathi Velia na ũtukũ: nao mavika kw’o malika ĩsinakokenĩ ya Ayuti.'),
('kam', 'ACT', 17, 11, 'Na andũ asu maĩ na ngoo nzeo mbee wa ala ma Thesalonika nĩkwĩthĩwa nĩmeetĩkĩlile ĩla ndeto na ũthalĩku w’onthe wa ngoo, maimantha maandĩkonĩ mĩthenya yonthe, kana maũndũ asu nĩw’o mailyĩ.'),
('kam', 'ACT', 17, 12, 'Kwondũ wa ũu aingĩ moo meetĩkĩla; vamwe na aka ma Akiliki me nguma, na aũme aingĩ.'),
('kam', 'ACT', 17, 13, 'Ĩndĩ Ayuti ma Thesalonika mesa ũmanya kana ndeto ya Ngai nĩtavanĩtw’e nĩ Vaulo kũu Velia nakw’o, mathi kw’o mamathokoan’ya na kũmaũũyĩthya makomano.'),
('kam', 'ACT', 17, 14, 'Na ĩndĩ oyu ana‐a‐asa mamwĩa Vaulo athi avike ũtee wa ũkanga: na Sila na Timotheo matiwa vo.'),
('kam', 'ACT', 17, 15, 'Ĩndĩ ala maendie na Vaulo mamũvikya Athene: na meeaĩwa nĩwe makamatavye Sila na Timotheo mamũatĩĩe na mĩtũkĩ, mathi.'),
('kam', 'ACT', 17, 16, 'Na Vaulo akĩmeteela Athene, veva wake wathilĩka nthĩnĩ wake, aiona ndũa yusũĩte mĩvw’anano.'),
('kam', 'ACT', 17, 17, 'Na kwa ũu asũanĩa na Ayuti na ala makĩaa Ngai ĩsinakokenĩ, na ala makomanaa nake kĩng’ang’anĩ, kĩla mũthenya.'),
('kam', 'ACT', 17, 18, 'Na andũ oĩ amwe ma Evikuleo na Sitoiko mamũwĩla. Na amwe masya, Mũthelya ũũ wa tũmaũndũ enda kwasya ata? Angĩ masya, Eoneka ta mũndũ mwonan’ya wa ngai ngeni: nũndũ nĩwatavanasya Yesũ na ũthayũũkyo.'),
('kam', 'ACT', 17, 19, 'Na mamũkwata, mamũtwaa Aleovako, maiasya, Momanyĩsyo aa ala ũmanyĩasya we, nĩtũtonya kũmanya ũndũ mailyĩ?'),
('kam', 'ACT', 17, 20, 'Nĩkwĩthĩwa we ũetete maũndĩ meũ matesĩkĩwe matũnĩ maitũ: ĩndĩ nĩtũkwenda kũmanya ũndũ mailyĩ maũndũ aa.'),
('kam', 'ACT', 17, 21, '(Na Aathene na aeni ala mekalaa ũeni kw’o maiaĩ na ũthei wa ũndũ ũngĩ, ate o kũneenan’ya kana kwĩthukĩĩsya ũvoo wa ũndũ weũ.)'),
('kam', 'ACT', 17, 22, 'Na vaulo aũngama Aleovako katĩ, na asya, Inyw’ĩ aũme ma Athene, maũndũnĩ onthe nĩona kana mwĩ na maũndũ ma ũthaithi mwingĩ.'),
('kam', 'ACT', 17, 23, 'Nũndũ ngĩvĩtĩla nzĩanĩ, na ngĩsisya mũno syĩndũ sya ũthaithi wenyu, nonie kĩthembeo nakyo kĩkĩĩtwe ũandĩko ũũ, KWA NGAI ŨLA ŨTESĨKĨWE. Ũla inyw’ĩ ĩndĩ mũthaithaa kwa ũlea ũmanya, nĩwe ngũmwon’ya inyw’ĩ.'),
('kam', 'ACT', 17, 24, 'Ngai ũla wombie nthĩ na syĩndũ syonthe ila syĩ vo, we, Mwĩaĩi wa itũ na nthĩ, ndekalaa nyũmbanĩ syakĩtwe na moko;'),
('kam', 'ACT', 17, 25, 'o na ndathũkũmawa nĩ moko ma andũ, ta wĩ na vata wa kĩndũ, nĩkwithĩwa nĩwe ũnengae onthe thayũ, na mĩthũmũ, na syĩndũ syonthe;'),
('kam', 'ACT', 17, 26, 'na oombie mbaĩ syonthe sya andũ kuma mũndũnĩ ũmwe, matũae ĩũlũ wa nthĩ yonthe, atw’ĩte mavinda moo ala wambie ũtw’a, na mĩvaka ya mawĩkalo moo;'),
('kam', 'ACT', 17, 27, 'nĩ kana mamũmanthe Ngai, o na ethĩwa nĩmatonya ũmũmantha maimũvavata mamwone, o na kau nde kũasa na kĩla ũmwe waitũ:'),
('kam', 'ACT', 17, 28, 'nũndũ twĩ thayũ, na nĩtũũthi, na twĩ na mwĩkalĩle witũ nthĩnĩ wake; o tondũ atili amwe menyu ma mbathi maisye, Nũndũ ithyi naitũ twĩ ũsyao wake.'),
('kam', 'ACT', 17, 29, 'Ĩndĩ kwa kwĩthĩwa twĩ ũsyao wa Ngai, tũiaĩlwe nĩ ũtalĩlya kana Ũ‐Ngai ũvw’anene na thaavu, kana vetha, kana ĩvia, ila syasũvĩtwe na ũtũĩka na ũĩ wa mũndũ.'),
('kam', 'ACT', 17, 30, 'Ĩndĩ mavinda ma ũlea ũmanya, Ngai etw’a ta ũteona; ĩndĩ yu emeaĩa andũ onthe kũndũ kw’onthe maalyũle ngoo:'),
('kam', 'ACT', 17, 31, 'nĩkwĩthĩwa nĩwiĩte mũthenya ũla ũkasilĩla nthĩ yonthe na ũlũngalu, kwa mũndũ ũla wanyuvie; nake amanengete andũ onthe kũmanya, kwondũ wa kũmũthayũũkya kũmumya kwa akw’ũ.'),
('kam', 'ACT', 17, 32, 'Namo meew’a ũvoo wa ũthayũũkyo wa akw’ũ, amwe moovũĩa ngũĩ; ĩndĩ angĩ masya, Tũkakwĩthukĩĩsya ĩngĩ ũvoonĩ ũũ.'),
('kam', 'ACT', 17, 33, 'Na kũilyĩ ũu Vaulo auma vo amatia.'),
('kam', 'ACT', 17, 34, 'Ĩndĩ amwe malũman’ya nake, na meetĩkĩla: na amwe ma asu nĩ Ndionisio ũla Mũaleovako, na mũndũ mũka wetawa Ndamali, na angĩ vamwe nao.'),
('kam', 'ACT', 18, 1, 'Ĩtina wa maũndũ asu Vaulo auma Athene, na avika Kolintho.'),
('kam', 'ACT', 18, 2, 'Na amwona Mũyuti ũmwe wetawa Akwila, mũndũ wasyaĩwe Vondo, ũla ũnaumie Italia mĩtũkĩ, vamwe na mũka wake Vilisila, nũndũ Kilautiosi atw’ĩte Ayuti onthe maume Lomi: nake avika kwoo;'),
('kam', 'ACT', 18, 3, 'na nũndũ aĩ wa wĩa ũmwe nao, ekala namo, maitethya wĩa; nũndũ maĩ atumi ma maeema.'),
('kam', 'ACT', 18, 4, 'Na Vaulo asũanĩa ĩsinakokenĩ mĩthenya yonthe ya savato, aimantha kũmetĩkĩlĩthya Ayuti na Akiliki.'),
('kam', 'ACT', 18, 5, 'Ĩndĩ yĩla Sila na Timotheo matheeie kuma Masetonia, Vaulo athangaaw’a mũno nĩ ĩla ndeto, aineena ũkũsĩ kwa Ayuti kana Yesũ nĩwe Klĩsto.'),
('kam', 'ACT', 18, 6, 'Ĩndĩ makananĩsya, na kũmũumanga Ngai, avuunza ngũa syake, na amea, Nthakame yenyu yĩthĩwe ĩũlũ wa mĩtwe yenyu ene; nyie nĩ mũtheu: kuma yu nĩthi kwa Andũ‐ma‐mbaĩ‐ingĩ.'),
('kam', 'ACT', 18, 7, 'Na auma vau, aenda nyũmbanĩ ya mũndũ ũmwe wetawa Tito Yusito, ũmwe ũla wathaithaa Ngai, na nyũmba yake yakwatene na ĩsinakoke.'),
('kam', 'ACT', 18, 8, 'Na Kilisivo, mũnene wa ĩsinakoke, nĩwamwĩtĩkĩlile Mwĩaĩi vamwe na nyũmba yake yonthe; na aingi ma Akolintho meew’a meetĩkĩla, na mavatiswa.'),
('kam', 'ACT', 18, 9, 'Na Mwĩaĩi amũtavya Vaulo ũtukũ woninĩ, Ndũkakĩe, ĩndĩ neena, ndũkavindye:'),
('kam', 'ACT', 18, 10, 'nũndũ nĩ vamwe naku, na vai mũndũ ũkoka vala ũĩ akwĩke nai: nĩkwĩthĩwa nyie nĩ na andũ aingĩ ndũanĩ ĩno.'),
('kam', 'ACT', 18, 11, 'Nake ekala kw’o mwaka na myei thanthatũ, akĩmanyĩsya ndeto ya Ngai kwoo.'),
('kam', 'ACT', 18, 12, 'Ĩndĩ ĩvinda yĩla Kalio waĩ mũnene wa Akaia, Ayuti mamũkĩlĩla Vaulo na ngoo ĩmwe, na mamũete kĩvĩlanĩ kya sila,'),
('kam', 'ACT', 18, 13, 'makyasya, Mũndũ ũũ emetĩkĩlĩthya andũ kũmũthaitha Ngai ũndũ ũvĩtanĩte na ĩla mĩao.'),
('kam', 'ACT', 18, 14, 'Ĩndĩ Vaulo akilĩlye kwathamya kanyw’a wake, Kalio amea ala Ayuti, Kethĩwa ve ũndũ ũthũku, kana ũng’endu mwĩai inyw’ĩ Ayuti, nĩkwaĩle kwakwa kũmũmĩĩsya:'),
('kam', 'ACT', 18, 15, 'ĩndĩ ethĩwa nĩ mokũlyo ma ndeto na masyĩtwa na mĩao ĩ yenyu, sisyai inyw’ĩ ene ũndũ ũsu: nyie ndikwenda nĩthĩwe mũsili wa maũndũ asu.'),
('kam', 'ACT', 18, 16, 'Na amalũngya maume kĩvĩlanĩ kya sila.'),
('kam', 'ACT', 18, 17, 'Na onthe mamũkwata Sosithene, ũla mũnene wa ĩsinakoke, na mamũkũnĩa mbee wa kĩvĩla kya sila. Na Kalio ndaamona maũndũ asu ta ũndũ.'),
('kam', 'ACT', 18, 18, 'Na Vaulo, ekalile mĩthenya mingĩ ĩtina wa ũndũ ũsu, ataanĩsya na ana‐a‐asa na athi na ngalawa Silia, na Vilisila na Akwila mathi vamwe nake: eenzewe mũtwe wake ku Kengelea; nĩkwĩthĩwa aĩ na wĩvĩto.'),
('kam', 'ACT', 18, 19, 'Na mavika Eveso, amatia kw’o: ĩndĩ we mwene alika ĩsinakokenĩ, na asũanĩa na Ayuti.'),
('kam', 'ACT', 18, 20, 'Na mamwĩa ekale ĩvinda ĩasanga, nake ndaaĩtĩkĩla;'),
('kam', 'ACT', 18, 21, 'ĩndĩ eeaanĩa nao, amea, Ngamũalũkĩla ĩngĩ, Ngai enda, na athi na ngalawa kuma Eveso.'),
('kam', 'ACT', 18, 22, 'Nake aumĩa Kaisalea ambata amakethya andũ ma ĩkanisa, na ĩndĩ atheea Andiokia.'),
('kam', 'ACT', 18, 23, 'Na ekala kw’o mĩthenya ĩmwe, athi, na avĩtĩla nthĩ ya Kalatia na Velikia, aatĩanĩsye, aimalũlũmilya amanyĩw’a onthe.'),
('kam', 'ACT', 18, 24, 'Na Mũyutĩ ũmwe wetawa Avolo, wasyaiwe Ũalesandalia, mũndũ wa ũmanyi, ooka Eveso; nake amanyaa mũno maandiko.'),
('kam', 'ACT', 18, 25, 'Mũndũ ũsu nĩwamanyĩĩtw’e nzĩa ya Mwĩaĩi; na nĩkwĩthĩwa aĩ mũthangaau vevanĩ wake, nĩwaneenie na kũmanyĩsya nesa maũndũ ma Yesũ, ĩndĩ eesĩ ũvatisi wa Yoana w’oka:'),
('kam', 'ACT', 18, 26, 'nake ambĩlĩlya ũneena na ũkũmbaũ ĩsinakokenĩ. Ĩndĩ Vilisila na Akwila mamwĩw’a, mamũtwaa kwoo, na mamũvuanĩsya nzĩa ya Ngai nesa mbee wa vala wesĩ.'),
('kam', 'ACT', 18, 27, 'Nake enda kũinga kũthi Akaia, ala ana‐a‐asa mamũkũmbaĩthya, na mamaandĩkĩa ala amanyiw’a kana mamwose: na avika amatethya mũno ala meetĩkĩlĩte nũndũ wa mumo:'),
('kam', 'ACT', 18, 28, 'nũndũ amakĩlĩlye Ayuti ũĩ, mbee wa andũ, aionan’ya na maandĩko kana Yesũ nĩ Klĩsto.'),
('kam', 'ACT', 19, 1, 'Na kweethĩwa, ĩvinda yĩla Avolo waĩ Kolintho, Vaulo avĩtĩla nthi ya ngalĩ ya iũlũ avika Eveso, na ku oona amanyĩw’a amwe:'),
('kam', 'ACT', 19, 2, 'na amakũlya, Nĩmwoosie Veva Mũtheu mweetĩkĩla? Na mamũsũngĩa, Aiee, o na tũiaaĩw’a kana kwĩ Veva Mũtheu.'),
('kam', 'ACT', 19, 3, 'Na ĩndĩ amakũlya, Mwavatisiwe ũvatisinĩ mwaũ ĩndĩ? Na mamũsũngĩa, Twavatisiwe ũvatisinĩ wa Yoana.'),
('kam', 'ACT', 19, 4, 'Na Vaulo amea, Yoana nĩwavatisaa na ũvatiso wa ũalyũlo wa ngoo, aimatavya andũ nĩmamwĩtĩkĩle ũla wĩũka ĩtina wake, nake nĩ Yesũ.'),
('kam', 'ACT', 19, 5, 'Nao meew’a ũu, mavatiswa syitwani ya Mwĩaĩi Yesũ.'),
('kam', 'ACT', 19, 6, 'Na Vaulo amailĩĩla moko make, Veva Mũtheu amatheeea; na maneena na ithyomo, na mathana.'),
('kam', 'ACT', 19, 7, 'Na onthe maĩ andũ aũme ta ĩkũmi na elĩ.'),
('kam', 'ACT', 19, 8, 'Nake alika ĩsinakokenĩ, na aneena na ũkũmbaũ ĩvinda ya myei ĩtatũ, aisũanĩa na andũ na kũmetĩkĩlĩthya maũndũ ma ũsumbĩ wa Ngai.'),
('kam', 'ACT', 19, 9, 'Ĩndĩ amwe meeyũmanĩlya, malea kwĩw’a, maimĩneenea ĩla Nzĩa naĩ mbee wa ĩkomano, aumaala amatia, na amavatha amanyĩw’a, na amamanyĩasya maineenan’ya mĩthenya yonthe kĩsomonĩ kya Tilano.'),
('kam', 'ACT', 19, 10, 'Na maũndũ asu maendeea ĩvinda ya myaka ĩlĩ; ũndũ onthe ala matwĩe nthĩ ya Asia meewie ndeto ya Mwĩaĩi, Ayuti na Akiliki nao.'),
('kam', 'ACT', 19, 11, 'Na Ngai eeka mavinya mataaĩkwa nĩ mũndũ na moko ma Vaulo:'),
('kam', 'ACT', 19, 12, 'ũndũ o na awau maetewe ngũa na itambaa syumĩte mwĩĩnĩ wake, nao mavoa mowau moo, na maveva mathũku mamauma.'),
('kam', 'ACT', 19, 13, 'Ĩndĩ Ayuti amwe, angangi, alũngya ma maveva, meenenga ene kũneena syĩtwa ya Mwĩaĩi Yesũ ĩũlũ wa ala maĩ na maveva mathũkũ, maiasya, Nĩmũavĩthya na Yesũ ũla ũtavanaw’a nĩ Vaulo.'),
('kam', 'ACT', 19, 14, 'Na kw’o kwaĩ aũme mũonza, ana ma Mũyuti wetawa Sikiva, mũthembi mũnene, ala mekaa ũu.'),
('kam', 'ACT', 19, 15, 'Na ũla veva mũthũku wamasũngĩa, wamea, Yesũ nĩnĩmwĩsĩ, na Vaulo nĩngũmũmanya; ĩndĩ inyw’ĩ mwĩ aaũ?'),
('kam', 'ACT', 19, 16, 'Na mũndũ ũla waĩ na ũla veva mũthũku amathaanyũkĩa, amakũa elĩ, na kũmakĩlya vinya, na makĩa mauma nyũmba ĩsu me athei na okite.'),
('kam', 'ACT', 19, 17, 'Na ũndũ ũsu wamanyĩka kwa Ayuti onthe na Akiliki ala matwĩe Eveso; na w’ĩa mũnene wamavalũkĩla onthe, na syĩtwa ya Mwĩaĩi Yesũ yataĩwa mũno.'),
('kam', 'ACT', 19, 18, 'Na aingĩ nao ma ala meetĩkĩlile mooka, makyumbũla, na makyonan’ya meko moo.'),
('kam', 'ACT', 19, 19, 'Na andũ aingĩ ala meekaa maũndũ ma ũwe maete mavuku moo na moomban’ya vamwe, na mamavĩvĩsya mbee wa andũ onthe; na matala thooa wamo na meethĩa nĩ ilungu sya vetha ngili mĩongo ĩtano.'),
('kam', 'ACT', 19, 20, 'Ũu nĩw’o ndeto ya Ngai yeanie na ũkilya vinya.'),
('kam', 'ACT', 19, 21, 'Na ĩtina wa maũndũ asu mathela, Vaulo atw’a vevanĩ wake, kũvĩtĩla Masetonia na Akaia, na akĩthi Yelusaleme, aiasya, Ĩtina wa kwĩthĩwa kw’o, mũvaka none Lomi nakw’o.'),
('kam', 'ACT', 19, 22, 'Na atũma elĩ ma ala mamũthũkũmaa mathi Masetonia, nao nĩ Timotheo na Elasito, nake mwene ekalanga Asia ĩvinda.'),
('kam', 'ACT', 19, 23, 'Na ta ĩvinda yĩu kwookĩla kĩthokoan’yo kĩte kĩnini ũndũ wa ĩla Nzia.'),
('kam', 'ACT', 19, 24, 'Nũndũ mũndũ ũmwe wetawa Ndemetelio, mũtwii wa vetha, ũla waseũvasya tũkalũ twa Ndiana, amaeteae andũ ndũĩka ũtandĩthyo ũte mũnini;'),
('kam', 'ACT', 19, 25, 'nake amomban’ya, vamwe na ala angĩ maĩ na wĩa ta ũsu, na amea, Mavwana, inyw’ĩ nĩmwĩsĩ kana ithyĩ nĩtwonaa ũthwii nũndũ wa wĩa ũũ.'),
('kam', 'ACT', 19, 26, 'Na nĩmũkwona na ĩngĩ nĩmũkwĩw’a, kana ti vaa Eveso voka, ĩndĩ no ta kw’onthe Asia, Vaulo ũsu ametĩkĩlĩthĩtye andũ aingĩ na kũmaalyũla, akyasya kana ti syo ngai, ila iseũvĩtw’e na moko:'),
('kam', 'ACT', 19, 27, 'na ti kwa kwĩthĩwa wĩa ũũ witũ wĩ na mũisyo na kũwetwa naĩ wĩ w’oka; ĩndĩ yĩla ĩkalũ ya ngai nga nene Ndiana yĩtalĩtwe ti kĩndũ, o na kũmyumya ndaĩanĩ yayo, ĩla ĩthaithawa nĩ Asia yonthe na nthĩ yonthe.'),
('kam', 'ACT', 19, 28, 'Namo meew’a ũu mausũwa nĩ ũthatu, na maua mbu, maiasya, Ndiana ĩla ya Aeveso nĩyo nene.'),
('kam', 'ACT', 19, 29, 'Na ndũa yausũwa nĩ kĩthokoo: na mathi na ngoo ĩmwe masembete, malika nyũmbanĩ ya ĩthaũ, mamakwete Kaio na Alisitaliko, andũ ma Masetonia, ala maendaa vamwe na Vaulo.'),
('kam', 'ACT', 19, 30, 'Na Vaulo akyenda kũlika yĩla ĩkomanonĩ, ala amanyĩw’a mamũvata ndakalike vo.'),
('kam', 'ACT', 19, 31, 'Na anene amwe ma Asia, ala maĩ anyanyae make, matũma andũ kwake na mamwĩsũva ndakatate kwĩlikya nyũmbanĩ ĩsu ya ĩthaũ.'),
('kam', 'ACT', 19, 32, 'Amwe ĩndĩ maneena ũndũ ũmwe, na angĩ ũndũ ũngĩ: nũndũ ũmbano waĩ na kĩthokoo; na ala aingĩ maiaamanya ũndũ ũla ũkũmbanĩawa.'),
('kam', 'ACT', 19, 33, 'Na mamumya Alesanda ĩkomanonĩ, Ayuti mamwia mbee wa andũ. Na Alesanda amakilĩthya na kw’oko, akyenda kũmasũngĩa.'),
('kam', 'ACT', 19, 34, 'Ĩndĩ mamanya kana nĩ Mũyuti, onthe maua mbu na wasya ũmwe vandũ va masaa elĩ, maiasya, Ndiana ĩla ya Aeveso nĩyo nene.'),
('kam', 'ACT', 19, 35, 'Ĩndĩ mũandĩki wa ndũa ayĩkilĩthya yĩla ĩkomano, asya, Inyw’ĩ aũme ma Eveso, nĩ mũndũ wĩva ũla ũtesĩ kana ndũa ya Eveso nĩyo isũvĩaa ĩkalũ ya Ndiana nene, na mũvw’anano ũla watheeie kuma ĩtunĩ?'),
('kam', 'ACT', 19, 36, 'Ĩndĩ nũndũ maũndũ aa maitonya ũkaĩwa, nĩmwaĩle kũkilya, na kũlea kwĩka ũndũ na mĩtũkĩ.'),
('kam', 'ACT', 19, 37, 'Nũndũ mwaete andũ aa vaa, nao ti ing’ei sya mĩio ya makalũ, o na ti aumi ma ngai nga yaitũ.'),
('kam', 'ACT', 19, 38, 'Ethĩwa ĩndĩ Ndemetelio, na andũ ndũĩka vamwe nake, meethĩwa na ũndũ ĩũlũ wa mũndũ o na wĩva, mĩthenya ya sila ĩ kw’o, na asili me kw’o: nĩmasitakane.'),
('kam', 'ACT', 19, 39, 'Ĩndĩ ethĩwa mwĩmantha ũndũ o na wĩva maũndũnĩ angĩ, ũkatw’ĩwa nzamanĩ ĩla yaĩle.'),
('kam', 'ACT', 19, 40, 'Nũndũ o naitũ twĩ na mũisyo wa kũsitakwa ũndũ wa kĩthokoo kya mũthenya ũũ, na nĩ kya mana: na kwondũ wa ũu, tũikatonya kũneena ũndũ wa ũmbano ũũ.'),
('kam', 'ACT', 19, 41, 'Na amina ũneena ũu ayũmbũũkya ĩkomano.'),
('kam', 'ACT', 20, 1, 'Na kĩtuu kyu kyakilya, Vaulo amatũmana ala amanyĩw’a na amataa, eeaanĩa nao, na ĩndĩ athi Masetonia.'),
('kam', 'ACT', 20, 2, 'Nake avĩtĩla ngalĩ isu, na ũmanenga ũtao mwingĩ, athĩ Ũkiliki.'),
('kam', 'ACT', 20, 3, 'Na ekalĩte kw’o myei ĩtatũ, Ayuti mamũsamĩa mamũae akilĩlye ũthi na ngalawa avike Silia, nake atw’a kũalũka avĩtĩle Masetonia.'),
('kam', 'ACT', 20, 4, 'Na andũ aa nĩmo maendanisye nake kũvika Asia, Sovatele mũndũ wa Velia, mwana wa Vilo; na ma Athesalonika, Alisitaliko na Sekundo; na Kaio mũndũ wa Ndelive, na Timotheo; na ma Asia, Tikiko na Telovimo.'),
('kam', 'ACT', 20, 5, 'Ĩndĩ andũ asu maĩ manathi mbee, nao matweteela Teloa.'),
('kam', 'ACT', 20, 6, 'Naitũ twaumie Vilivi na ngalawa, ĩtina wa mĩthenya ya kĩmũtũ kĩte ĩlawa, na mĩthenya ĩtano yathela twamavikĩa ala maĩ Teloa; na twekala kw’o mĩthenya mũonza.'),
('kam', 'ACT', 20, 7, 'Na mũthenya wa mbee wa kyumwa, twombanĩte vamwe kũtila kĩmũtũ, Vaulo aneena nao, akyenda ũthi ũnĩ ũsu: na aasavya ũtavan’yo wake kũvika ũtukũ katĩ.'),
('kam', 'ACT', 20, 8, 'Na kwaĩ mataa maingĩ nyũmbanĩ ya ĩũlũ ĩla twoombanĩte.'),
('kam', 'ACT', 20, 9, 'Na mũndũ ũmwe, mwanake wetawa Eutikusi, ailyĩ mbũthinĩ, akwatwa nĩ too mũno; na Vaulo aiendeea mũno na kũtavan’ya kwake, na nĩkwĩthĩwa ausũĩtwe nĩ too wake avalũka kuma nyũmba ya katatũ kũvika nthĩ, na ooswa e mũkw’ũ.'),
('kam', 'ACT', 20, 10, 'Na Vaulo atheea, na amũmamĩa, na amũvĩvĩtĩĩsya, asya, Mũikekĩe kĩtuu; nũndũ thayũ wake wĩ o nthĩnĩ wake.'),
('kam', 'ACT', 20, 11, 'Na ambata ĩũlũ, na atila kĩla kĩmũtũ, na aya, na aneena nao ĩvinda ĩasa, o na kũvika kũikya, na ĩndĩ athi.'),
('kam', 'ACT', 20, 12, 'Na mamũete ũla mwanake e thayũ, na makiakiw’a ũndũ ũtee ũnini.'),
('kam', 'ACT', 20, 13, 'Ĩndĩ ithyĩ, twambie ũthi mbee na ngalawa, twakũsya tũende Asoso, navo twenda ũmũlikya Vaulo: nũndũ nĩw’o watwie, akyenda e we mwene ũthi na nyaĩĩ.'),
('kam', 'ACT', 20, 14, 'Na twavika Asoso, akomana naitũ, na twamũlikya ngalawanĩ, na twathi Mitilene.'),
('kam', 'ACT', 20, 15, 'Na twakũsya kw’o, na mũthenya wa kelĩ twavika vakuvĩ na Kiosi; na mũthenya wa katatũ twavika Samo; na mũthenya wa kana twavika Mileto.'),
('kam', 'ACT', 20, 16, 'Nũndũ Vaulo atw’ĩte kũvĩta Eveso, nĩ kana ndakekale Asia; nũndũ nĩwekalaatĩte, ethĩwa ũu nũtonyeka, we ethĩwe Yelusaleme mũthenya wa Vendekosito.'),
('kam', 'ACT', 20, 17, 'Na atũma andũ kuma Mileto maende Eveso kũmeta atumĩa ma ĩkanisa moke kwake.'),
('kam', 'ACT', 20, 18, 'Nao mooka, amea, Inyw’ĩ ene nĩmwĩsĩ, kuma mũthenya ũla nambie ũkinya nthĩ ĩno ya Asia, ũndũ nekalĩte nenyu ĩvinda yĩu yonthe,'),
('kam', 'ACT', 20, 19, 'ngĩmũthũkũma Mwĩaĩi na wĩnyivyo w’onthe wa ngoo, na methoi, na monyamao ala mangwatie kwa kũsyimwa nĩ Ayuti;'),
('kam', 'ACT', 20, 20, 'ũndũ ndaatundua kũmũtavya inyw’ĩ ndeto o na yĩva ĩmwaĩle, na ngĩmũmanyĩĩsya andũnĩ, nyũmba na nyũmba,'),
('kam', 'ACT', 20, 21, 'ngĩkũsĩĩa kwa Ayuti na Akiliki nao, ualyũlo wa ngoo ũmwelekele Ngai, na mũĩkĩĩo ũmwelekele Mwĩaĩi waitũ Yesũ Klĩsto.'),
('kam', 'ACT', 20, 22, 'Na yu, sisyai, nĩngũthi Yelusaleme nĩ mwove vevanĩ, ndesĩ maũndũ ala mengwatĩa kw’o:'),
('kam', 'ACT', 20, 23, 'ate o Veva Mũtheu kũngũsĩĩa ndũanĩ syonthe, aiasya kana syĩndũ sya kwovwa nasyo na monyamao nimbeteele.'),
('kam', 'ACT', 20, 24, 'Ĩndĩ ndiũtala thayũ wakwa ta kĩndũ kwakwa, nĩ kana nĩtonye kwĩanĩsya mũendo wakwa, na ũthũkũmi ũla noosie kwa Mwĩaĩi Yesũ, kũkũsĩĩa ũla ũvoo mũseo wa mumo wa Ngai.'),
('kam', 'ACT', 20, 25, 'Na yu, sisyai, nĩnĩsĩ kana inyw’onthe, ala nangangĩte katĩ wenyu ngĩtavan’ya ũsumbĩ wa Ngai, mũikambona ĩngĩ ũthyũ wakwa.'),
('kam', 'ACT', 20, 26, 'Kwondũ wa ũu nĩmũkũsĩĩa ũmũnthĩ, kana ndikakũlw’a nyie nthakame ya mũndũ o na wĩva.'),
('kam', 'ACT', 20, 27, 'Nũndũ ndyaatundua kũmũtavya inyw’ĩ ũtw’ĩo w’onthe wa Ngai.'),
('kam', 'ACT', 20, 28, 'Ĩsũvĩei inyw’ĩ ene, na mũisũvĩa ĩĩthya yonthe yĩla Veva Mũtheu ũmũtw’ĩte inyw’ĩ mwĩthĩwe asyaĩĩsya nĩ kana mũĩthye ĩkanisa ya Mwĩaĩi yĩla ũthooete na nthakame yake mwene.'),
('kam', 'ACT', 20, 29, 'Nĩnĩsĩ kana ĩtina wa kũthi kwakwa nzũi mbai ikalika katĩ wenyu, iteũyĩw’ĩa yĩla ĩĩthya tei;'),
('kam', 'ACT', 20, 30, 'na andũ aingĩ makookĩla kuma katĩ wenyu, makĩneena ndeto sya ngũlũ, maimakusya amanyĩw’a mamaatĩĩe mo.'),
('kam', 'ACT', 20, 31, 'Kwondũ wa ũũ syaĩĩsyai, mũkĩlilikana kana ĩvinda ya myaka ĩtatũ ndyaaeka kũmũtaa kĩla mũndũ na kwĩtĩkya methoi mũthenya na ũtukũ.'),
('kam', 'ACT', 20, 32, 'Na yu nĩmũnengane kwa Ngai, na kwa ndeto ya mumo wake, ĩla ĩtonya kũmwaka, na kũmũnenga inyw’ĩ ũtiĩwa katĩ wa onthe ala mavathĩwe Ngai.'),
('kam', 'ACT', 20, 33, 'Ndyaawĩw’ĩa ĩtomo vetha wa mũndũ o na wĩva, kana thaavu, kana ngũa.'),
('kam', 'ACT', 20, 34, 'Inyw’ĩ ene nĩmwĩsĩ kana moko aa makwa matethisye wĩa kwondũ wa mavata makwa mwene na ma ala maĩ nakwa.'),
('kam', 'ACT', 20, 35, 'Maũndũnĩ onthe namũnengie ngelekan’yo, kana nĩmwaĩlwe nĩ ũtethya o ũu, kũmatethya ala onzu, na kũlilikana ndeto sya Mwĩaĩi Yesũ, ũndũ we mwene waisye, Kwĩ mũyo kũnengane kwĩ kwosa.'),
('kam', 'ACT', 20, 36, 'Na aneena ũu, atulya ndu na avoya vamwe namo onthe.'),
('kam', 'ACT', 20, 37, 'Na onthe maĩa mũno, na mamũvalũkĩla Vaulo ngingonĩ na mamũmumunya,'),
('kam', 'ACT', 20, 38, 'makĩmaka mũno nũndũ wa ndeto ĩla waneenie, kana maikamwona ũthyũ wake ĩngĩ. Na mamumaasya mamũvikya ngalawanĩ.'),
('kam', 'ACT', 21, 1, 'Na kweethĩwa twamina kũtaanĩsya nao na twakũsya na ngalawa, twathi tũlũngalĩte twavika Kosi, na ũnĩ ũsu twavika Lote, na kuma vau twathi Vatala:'),
('kam', 'ACT', 21, 2, 'na twoona ngalawa ĩnĩkũinga ĩvike Voenike twamĩlika, na twakũsya.'),
('kam', 'ACT', 21, 3, 'Na twoona kĩthama kya Kuvolo, twakĩtia ngalĩ ya kw’oko kwa aka, twathi Silia, na twaumĩa Tile; nũndũ ngalawa ĩsu yaumĩw’e mĩio yayo vo.'),
('kam', 'ACT', 21, 4, 'Na twoona ala amanyĩw’a, twekala vo mĩthenya mũonza: na asu mamũtavya Vaulo me nthĩni wa Veva Mũtheu, kana ndakakinye Yelusaleme.'),
('kam', 'ACT', 21, 5, 'Na kweethĩwa tweanĩsya mĩthenya yaitũ twookĩla twathi; namo onthe, vamwe na aka moo na syana syoo, matumaasya matũvikya ũtee wa ndũa: na twatulya ndu ũtee wa ũkanga, twavoya, na twatianĩa ũvoo;'),
('kam', 'ACT', 21, 6, 'na twavota ngalawanĩ, nao maalũka kwoo.'),
('kam', 'ACT', 21, 7, 'Na twamina mũendo ũsu wa ngalawa kuma Tile, twavika Vetolemai; na twakethya ana‐a‐asa, twekala nao mũthenya ũmwe.'),
('kam', 'ACT', 21, 8, 'Na ũnĩ ũsu twathi, na twavika Kaisalea: na twavota nyũmbanĩ ya Vilivu ũla mũtavan’ya wa ũvoo mũseo, ũla waĩ ũmwe wa ala mũonza, twekala kwake.'),
('kam', 'ACT', 21, 9, 'Na mũndũ ũsu aĩ na eĩtu ana atheu, ala mathanaa.'),
('kam', 'ACT', 21, 10, 'Na tũkĩkala vo mĩthenya ĩmwe, kwatheeie mwathani ũmwe kuma Yutia, wetawa Akavo.'),
('kam', 'ACT', 21, 11, 'Nake ooka vala tũĩ, oosa mũkwa wa Vaulo eeyova e we mwene maũũ na moko, na asya, Ũũ nĩw’o ũnũkwasya Veva Mũtheu, Ayuti ala me Yelusaleme makoova mũndũ ũla mwene wa mũkwa ũũ ta ũu, na makamũnengane mokonĩ ma Andũ‐ma‐mbaĩ‐ingĩ.'),
('kam', 'ACT', 21, 12, 'Na tweew’a maũndũ asu, ithyĩ o na andũ ma vandũ vau, twamwĩsũva ndakambate Yelusaleme.'),
('kam', 'ACT', 21, 13, 'Na nĩvo Vaulo wasũngĩie, Mwĩĩka ata, mũkĩĩa na ũndũla ngoo yakwa? Nũndũ nyie nĩnĩyũmbanĩtye, ti kwovwa kw’oka, o na kũaĩwa Yelusaleme kwondũ wa syĩtwa ya Mwĩaĩi Yesu.'),
('kam', 'ACT', 21, 14, 'Na alea kũtwĩw’a, twamũeka, tũiasya, Kwenda kwa Mwĩaĩi nĩkwĩkwe.'),
('kam', 'ACT', 21, 15, 'Na ĩtina wa mĩthenya ĩsu twoomban’ya mĩio yaitũ, na twakũsya twambata Yelusaleme.'),
('kam', 'ACT', 21, 16, 'Na amwe ma amanyĩw’a ma ndũa ya Kaisalea mathi vamwe naitũ, me na Masoni mũndũ wa Kuvolo, mũmanyĩw’a wa tene, nake nĩwe twĩĩkalaa kwake.'),
('kam', 'ACT', 21, 17, 'Na twavika Yelusaleme, ala ana‐a‐asa matwosa na mũyo.'),
('kam', 'ACT', 21, 18, 'Na mũthenya ũla waatĩĩe ũsu, Vaulo aenda naitũ kwa Yakovo; na atumĩa onthe nĩ vo maĩ.'),
('kam', 'ACT', 21, 19, 'Na amakethya, amatavya maũndũ onthe, ũmwe na ũmwe, ala Ngai wĩkĩte kwondũ wa ũthũkũmi wake katĩ wa Andũ‐ma‐mbaĩ‐ingĩ.'),
('kam', 'ACT', 21, 20, 'Namo, meew’a mamũtaĩa Ngai; na mamwĩa, Nũkwona, mwana‐a‐asa, kana nĩ vo maĩ ngili mbingĩ ma Ayuti ala metĩkĩlĩte; namo onthe me na kĩwĩu ũndũ wa ĩla mĩao:'),
('kam', 'ACT', 21, 21, 'namo nĩmatavĩtw’e ũvoo waku, kana ũmanyĩĩtye Ayuti onthe ala matwĩe katĩ wa Andũ‐ma‐mbaĩ‐ingĩ matie Mose, ũimatavya maikaĩke syana syoo, na maikaatĩĩe syĩthĩo sya Ayuti.'),
('kam', 'ACT', 21, 22, 'Ĩndĩ nĩ ata? Maitĩa kwĩw’a kana nĩwũkite.'),
('kam', 'ACT', 21, 23, 'Ĩka ĩndĩ ũndũ ũla tũũkũtavya: Twĩ na aũme ana ala me na wĩvĩto ĩũlũ woo;'),
('kam', 'ACT', 21, 24, 'osana na asu, nokĩthesya mwene vamwe nao, nokyumya syĩndũ nũndũ wamo, nĩ kana matonye kwenza mĩtwe yoo: na ĩndĩ onthe makamanya kana ti ma w’o maũndũ ala matavĩtw’e ũndũ waku; ĩndĩ kana we mwene ũendaa nesa, na ũsũvĩaa ĩla mĩao.'),
('kam', 'ACT', 21, 25, 'Ĩndĩ ũndũ wa Andũ‐ma‐mbaĩ‐ingĩ ala metĩkĩlĩte, nĩtwaandĩkie na twamatavya, kana mevathane na syĩndũ ila syũaĩwe mĩvw’anano, na maikanyw’e nthakame, o na kĩndũ kitĩtwe, na kwĩvathana na ũlaalai.'),
('kam', 'ACT', 21, 26, 'Na ĩndĩ Vaulo oosana na ala andũ, na mũthenya ũla waatĩĩe ũsu eethesya mwene vamwe namo, avota ĩkalũnĩ, aitavan’ya kana mĩthenya ya ũthesyo nĩ mĩanĩu, mũvaka nthembo yathembwa kwondũ wa kĩla ũmwe wamo.'),
('kam', 'ACT', 21, 27, 'Na ĩla mĩthenya mũonza ĩkilĩlye ũthela, Ayuti ala maumie Asia, moona Vaulo ĩkalũnĩ, maingĩanĩsya ĩkomano yonthe na mamũkwata,'),
('kam', 'ACT', 21, 28, 'makyũkĩlya mawasya, makyasya, Aũme ma Isilaeli, tũtethyei: Mũndũ nĩwe ũũ ũla ũmanyĩasya andũ onthe kũndũ kw’onthe, aineenea andũ naĩ, na ĩla mĩao, o na vandũ vaa; na mbee wa ũu nĩwaetie Akiliki nao ĩkalũnĩ, nake nũvukĩtye vandũ vaa vatheu.'),
('kam', 'ACT', 21, 29, 'Nũndũ maĩ manamwona ndũanĩ e na Telovimo, mũndũ wa Eveso, namo nĩmatalĩlasya kana Vaulo nũmũetete ĩkalũnĩ.'),
('kam', 'ACT', 21, 30, 'Na ndũa yonthe yaya kĩtuu, na andũ moombana masembete; na mamũkwata Vaulo, mamũkusũlan’ya na kũmumaalya ũtee wa ĩkalũ: na oyu mĩomo yavingwa.'),
('kam', 'ACT', 21, 31, 'Na makĩmantha kũmũaa, ũvoo wamũvikĩa ũla mũnene wa nguthu ya asikalĩ ngili, kana Yelusaleme kw’onthe nĩkũlikile kĩtuu.'),
('kam', 'ACT', 21, 32, 'Na oyu oosa asikaiĩ na anene ma asikalĩ ĩana ĩana, na amatheeea asembete: nao, moona ũla mũnene na asikalĩ, maeka kũmũlumangya Vaulo.'),
('kam', 'ACT', 21, 33, 'Na ĩndĩ ũla mũnene athengeea, na amũkwata Vaulo, na eeaa nĩovwe na mĩnyololo ĩlĩ; na akũlya ũndũ wĩtawa na ũndũ wĩkĩte.'),
('kam', 'ACT', 21, 34, 'Na amwe manĩĩsya ũndũ ũmwe, na angĩ katĩ wa nguthu manĩĩsya ũndũ ũngi: na alea ũmanya nesa nũndũ wa kĩtuu, eeaa aetwe ngomenĩ.'),
('kam', 'ACT', 21, 35, 'Na avika mbasyanĩ, akuwa nĩ asikalĩ nũndũ wa ũng’endu wa ĩla nguthu ya andũ;'),
('kam', 'ACT', 21, 36, 'nũndũ ĩkomano ya andũ yamũvikĩlĩte, yĩkyasya na wasya mũnene, Mũvete ũsu.'),
('kam', 'ACT', 21, 37, 'Na Vaulo akilĩlye ũlikwa ngomenĩ nthĩnĩ, amwĩa ũla mũnene wa asikalĩ, Nĩ na ũthei nyie kũkũtavya ũndũ? Nake amũkũlya, Nĩwĩsĩ Kĩkiliki?'),
('kam', 'ACT', 21, 38, 'Tuue ũla Mũmisili, ũla mbee wa mĩthenya ĩno wamang’endethisye andũ ngili inya ala metawa Oaani na wamatongoesya weũnĩ?'),
('kam', 'ACT', 21, 39, 'Ĩndĩ Vaulo amũsũngĩa, Nyie nĩ Mũyuti, mũndũ wa Taliso, ndũa ya Silisia, mũndũ wa ndũa ĩte mbũthũ: na nĩngũkwĩsũva ũnenge ũthei nĩneene na andũ aa.'),
('kam', 'ACT', 21, 40, 'Na amũnenga ũthei, Vaulo, aũngeme mbasyanĩ, amavindĩthya andũ na kw’oko; na mavindya ki, aneena namo na Kĩevelania, aiasya,'),
('kam', 'ACT', 22, 1, 'Ana‐a‐asa makwa na aasa, ĩthukĩĩsyei ũsũngĩo wakwa ũla ngũsũngĩa mbee wenyu oyu.'),
('kam', 'ACT', 22, 2, 'Na meew’a kana eneena nao na Kĩevelania, mavindĩĩsya mũno: nake asya,'),
('kam', 'ACT', 22, 3, 'Nyie nĩ Mũyuti, nasyaĩwe Taliso, ndũa ya Silisia, ĩndĩ neanĩe ndũanĩ ĩno, na ũmanyĩĩw’a maũũnĩ ma Kamalieli, kwĩanana na wĩanĩu wa ĩla mĩao ya aasa maitũ, na neethĩwa na ũthangaau kwa Ngai, o ũndũ inyw’ĩ mũilyĩ ũmũnthĩ:'),
('kam', 'ACT', 22, 4, 'nakwa nathĩnasya ala ma Nzĩa ĩno o na ũmoaa, na ngĩmova na kũmekya kolokolonĩ aũme na aka.'),
('kam', 'ACT', 22, 5, 'O ũndũ mũthembi mũnene e na ũkũsĩ wakwa, na atumĩa onthe: ala noosie mavalũa kwoo nĩmaetee ala ana‐a‐asa, na nathi kyalo Ndamasiku, ngamaete ala maĩ kw’o me ove Yelusaleme, masilĩlwe.'),
('kam', 'ACT', 22, 6, 'Na kweethĩwa yĩla naendete kyalo, ngĩthengeea Ndamasiku, ta mũthenya katĩ, oyu, o ĩmwe, kyeni kĩnene kyaumie ĩtunĩ kyatisa ngalĩ syakwa syonthe.'),
('kam', 'ACT', 22, 7, 'Nakwa navalũka nthĩ, na neew’a wasya ũineena nakwa, ũiasya, Saulo, Saulo, nĩkĩ ũũnthĩn’ya?'),
('kam', 'ACT', 22, 8, 'Nakwa nasũngĩa, Nue ũũ, Mwĩaĩi? Nake ambĩa, Ninyie Yesũ wa Nasaleti, ũla ũũthĩn’ya.'),
('kam', 'ACT', 22, 9, 'Na ala maĩ nakwa nĩmoonie kyeni kyu, ĩndĩ maiaaĩw’a wasya wa ũla ũnũũneena nakwa.'),
('kam', 'ACT', 22, 10, 'Nakwa nasya, Nĩĩka ata, Mwĩaĩi? Na Mwĩaĩi ambĩa, Ũkĩla, ũthi Ndamasiku nthĩnĩ; na kw’o ũkatavĩw’a ũvoo wa maũndũ onthe ala meaĩtwe wĩke.'),
('kam', 'ACT', 22, 11, 'Na ĩndĩ neethĩwa ndekwona nthĩ nũndũ wa ũtheu mũtisu wa kĩla kyeni, natongoew’a nĩ ala maĩ nakwa mangwete kw’oko, nalika Ndamasiku.'),
('kam', 'ACT', 22, 12, 'Na mũndũ ũmwe wĩtawa Anania, mũthaithi mũnene wa Ngai kwĩanana na ĩla mĩao, ũla ũwetawa nesa nĩ Ayuti onthe ala matwĩe kw’o,'),
('kam', 'ACT', 22, 13, 'ooka vala nĩĩ, na aũngama ũtee wakwa ambĩa, Mwana‐a‐asa Saulo, nengwa kwona. Nakwa mamũũngalalĩlya metho makwa saa o ũsu.'),
('kam', 'ACT', 22, 14, 'Nake asya, Ngai wa aasa maitũ nũkũnyuvĩte we ũmanye kwenda kwake, na kũmwona Ũla Mũlũngalu, na kwĩw’a wasya ũla wumaa kanyw’anĩ wake.'),
('kam', 'ACT', 22, 15, 'Nũndũ ũkeethĩwa ngũsĩ kwondũ wake kwa andũ onthe ya maũndũ ala ũnoonie na kwĩw’a.'),
('kam', 'ACT', 22, 16, 'Na yu weteele kyaũ? Ũkĩla, ũvatiswe, ũthambw’e naĩ syaku, ũkĩkaĩla syĩtwa yake.'),
('kam', 'ACT', 22, 17, 'Na kweethĩwa, naalũka Yelusaleme, ngĩvoya ĩkalũnĩ, nakwatwa nĩ too ũilyĩ ta kĩkw’ũ,'),
('kam', 'ACT', 22, 18, 'na namwona aimbĩa, Ĩkalaate nokyuma Yelusaleme mĩtũkĩ; nĩkwĩthĩwa maikosa ũkũsĩ waku kwondũ wakwa.'),
('kam', 'ACT', 22, 19, 'Nakwa nasũngĩa, Mwĩaĩi, o ene nĩmesĩ kana nyie nĩnamovie kolokolonĩ na ngĩmakũnĩa masinakokenĩ ala makwĩtĩkĩlĩte:'),
('kam', 'ACT', 22, 20, 'na yĩla nthakame ya ngũsĩ yaku Sitivini yetĩkaw’a, nyie naũngeme ũtee woo, na neetĩkĩla oawe, nĩsũvĩĩte ngũa sya ala mamũaie.'),
('kam', 'ACT', 22, 21, 'Nake ambĩa, Thi: nũndũ ngaũtũma ũthi kũasa kwa Andũ‐ma‐mbaĩ‐ingĩ.'),
('kam', 'ACT', 22, 22, 'Na mamwĩthukĩĩsya kũvika ndeto ĩsu: na mookĩlya mawasya moo, na masya, Mũvetei mũndũ ta ũsu kũũ nthĩ: nũndũ ndaĩle kwĩkala thayũ.'),
('kam', 'ACT', 22, 23, 'Na makĩlonzan’ya, na kwĩkya ngũa syoo, na kwĩkya mũthanga na ĩũlũ,'),
('kam', 'ACT', 22, 24, 'ũla mũnene wa asikalĩ eeaa nalikw’e nthĩnĩ wa ĩla ngome, aiasya kana akũlw’e kwa ũkũnwa, nĩ kana atonye ũmanya ũndũ ũũtuma malonzan’ya ũu ĩũlũ wake.'),
('kam', 'ACT', 22, 25, 'Na mamwovete na mĩkwa, Vaulo amũkũlya mũnene wa asikalĩ ĩana ũla ũũngeme ũtee wake, Nĩkwosana na mĩao kwenyu kũmũkũna mũndũ Mũlomi, o na ti mũsilĩle?'),
('kam', 'ACT', 22, 26, 'Na ũla mũnene eew’a ũu, aenda kwa ũla mũnene wa asikalĩ ngili, amũkũlya, aiasya, Ũkilĩlye kwĩka ata? Nũndũ mũndũ ũsu nĩ Mũlomi.'),
('kam', 'ACT', 22, 27, 'Na ũla mũnene wa asikalĩ ngili ooka, amwĩa, Ndavya, we wĩ Mũlomi? Na amwĩa Ĩĩ.'),
('kam', 'ACT', 22, 28, 'Na ĩndĩ mũnene ũsu asya Nyie nĩnengetwe kwĩtwa Mũlomi ngĩthooa na mbesa nyingĩ. Na Vaulo amwĩa, Ĩndĩ nyie nĩ Mũlomi kwa kũsyawa.'),
('kam', 'ACT', 22, 29, 'Ĩndĩ ala makilĩlye kũmũkũlya mamũtia, mathi: na mũnene ũsu akĩa amanya kana nĩ Mũlomi, na nũndũ nũmwovie.'),
('kam', 'ACT', 22, 30, 'Ĩndĩ ũnĩ ũsu, aienda kũmanya vyũ ũndũ ũnavinganĩw’e nĩ Ayuti, amũthasya, na ameaĩa athembi anene na nzama yonthe mombane vamwe, na amũtheesya Vaulo amwia mbee woo.'),
('kam', 'ACT', 23, 1, 'Na Vaulo, aimĩketeea ĩla nzama, asya, Ana‐a‐asa, nĩnekalĩtye thayũ wakwa mbee wa Ngai na wasya wa ngoo mũtheu kũvika ũmũnthĩ.'),
('kam', 'ACT', 23, 2, 'Na mũthembi mũnene Anania ameaĩa ala maũngeme na Vaulo mamũkũne kanyw’a.'),
('kam', 'ACT', 23, 3, 'Na ĩndĩ Vaulo amwĩa, Ngai nũkilĩlye ũkũkũna we, ũvai ũvakĩtwe ĩa: naku wĩkalĩte kũnzilĩla nyie kwĩanana na ĩla mĩao, naku wĩtw’a kana nĩkũnwe ũndũ ũvĩtanĩte na ĩla mĩao?'),
('kam', 'ACT', 23, 4, 'Na ala maũngyĩ ũtee masya, Wĩmũuma mũthembi mũnene wa Ngai?'),
('kam', 'ACT', 23, 5, 'Na Vaũlo asya, Ndyĩĩsĩ, ana‐a‐asa, kana we nĩ mũthembi mũnene: nũndũ nĩkũaandĩkĩtwe, Ndũkanenee mũnene wa andũ maku naĩ.'),
('kam', 'ACT', 23, 6, 'Ĩndĩ Vaulo oona kana kĩlungu kĩmwe kya nzama nĩ Asatukai, na kĩla kĩngĩ nĩ Avalisi, aneena mũno katĩ wa nzama, aiasya, Ana‐a‐asa, nyie nĩ Mũvalisi, na nĩ mwana wa Mũvalisi: kwondũ wa wĩkwatyo wa ũthayũũkyo wa akw’ũ nyie nĩngũsilĩlwa.'),
('kam', 'ACT', 23, 7, 'Na asya ũu, kwookĩla ngananĩo katĩ wa Avalisi na Asatukai; na nzama yatilĩkana.'),
('kam', 'ACT', 23, 8, 'Nũndũ Asatukai maasya kũi ũthayũũkyo, o na mũlaĩka, o na veva; ĩndĩ Avalisi nĩmalĩkĩlaa asu elĩ.'),
('kam', 'ACT', 23, 9, 'Na kwookĩla kĩlonzo kĩnene: na aandĩki amwe ma kĩlungu kya Avalisi maũngama na mateta mũno, maiasya, Tũtikwona ũthũku wa mũndũ ũũ: na ethĩwa veva waneena nake, kana mũlaĩka, kwĩ kĩ?'),
('kam', 'ACT', 23, 10, 'Na kwookĩla ngananĩo nene, ũla mũnene wa asikalĩ ngili aikĩa Vaulo ndakese ũkavũlangw’a nĩo, ameaĩa asikalĩ matheee mamumya Vaulo katĩ woo na vinya, na kũmũete ngomenĩ.'),
('kam', 'ACT', 23, 11, 'Na ũtukũ o ũsu Mwĩaĩi aũngama ũtee wake, na asya, Ĩthĩwa, na ũnyiau: nũndũ o tondũ waneenie ũkũsĩ ũndũ wakwa Yelusaleme, o ta ũu mũvaka ũneene ũkũsĩ Lomi.'),
('kam', 'ACT', 23, 12, 'Na kwakya, Ayuti moombana vamwe, na malũman’ya na kũya muma, maiasya kana maiya o na kũnyw’a matamũaĩte Vaulo.'),
('kam', 'ACT', 23, 13, 'Na ala meevĩtie ũu maĩ andũ mathonokete mĩongo ĩna.'),
('kam', 'ACT', 23, 14, 'Namo mooka kwa athembi anene na atumĩa, na mamatavya, Nĩtwĩvĩtie twaya muma mbai, tũikasame kĩndũ o na kĩva, tũtamũaĩte Vaulo.'),
('kam', 'ACT', 23, 15, 'Na ĩndĩ inyw’ĩ vamwe na nzama yonthe mũkamũtavye ũla mũnene wa asikalĩ ngili amũtheesye Vaulo oke mbee wenyu, mũkeke ta mũkwenda kũmanya nesa mbee ũndũ wake: naitũ nĩtwĩyũmbanĩtye kũmũaa atanamba ũthengeea.'),
('kam', 'ACT', 23, 16, 'Ĩndĩ mwĩvae wa Vaulo eew’a ũndũ memwoveesya, athi ngomenĩ na amũtavya Vaulo.'),
('kam', 'ACT', 23, 17, 'Na Vaulo amwĩta mũnene ũmwe wa asikalĩ ĩana, amwĩa, Mũtwae mwanake ũũ kwa ũla mũnene wa asikalĩ ngili; nũndũ e na ũndũ wa ũmũtavya.'),
('kam', 'ACT', 23, 18, 'Nake amwosa, na amũete kwa mũnene ũsu, na asya, Vaulo ũla mwove ambĩta kwake, enda nĩkũetee mwanake ũũ, nake e na ũndũ wa ũkũtavya.'),
('kam', 'ACT', 23, 19, 'Na mũnene ũsu amũkwata kw’oko, athi nake ũtee me nzama na amũkũlya, Nĩ ũndũ mwaũ ũla ũũndavya?'),
('kam', 'ACT', 23, 20, 'Nake amwĩa, Ayuti nĩmew’anĩte kũũvoya we ũmũtheesye Vaulo ũmwie mbee wa nzama ũnĩ, ta ũkwenda kũmanya ũvoo wake nesa mbee.'),
('kam', 'ACT', 23, 21, 'Naku ĩndĩ ndũketĩkĩle ũndũ ũsu woo: nũndũ andũ mathonoka mĩongo ĩna nĩmamwoveesye, nao nĩmaĩe muma, maikaye kana kũnyw’a matamũaĩte Vaulo: na yu nĩmeyũmbanĩtye, meteele watho waku.'),
('kam', 'ACT', 23, 22, 'Na ĩndĩ mũnene ũsu amũeka ũla mwanake athi, aimwĩaĩa atĩĩ, Ndũkatavye mũndũ o na wĩva kana nũmbonetye maũndũ aa.'),
('kam', 'ACT', 23, 23, 'Na ameta anene elĩ ma asikalĩ ĩana moke kwake, na amea, Ũmban’yai asikalĩ maana elĩ ma ũthi Kaisalea, na andũ mĩongo mũonza ala matũlĩte mbalasi, na ala me na matumo nao, maana elĩ, mathi saa itatũ sya ũtukũ:'),
('kam', 'ACT', 23, 24, 'na mbalasi nasyo mũseũvye, nĩ kana mũtonye kũmũtũlya Vaulo, na ũmũtwaa kwa Velike ũla ngavana, mũmũsũvĩĩte.'),
('kam', 'ACT', 23, 25, 'Nake aandĩka valũa ũilyĩ ũũ:'),
('kam', 'ACT', 23, 26, 'Kilautiosi Lisiasi, valũa ũũ wakwa ũmũvikĩe Velĩke, ngavana mũtaĩwa, nũvoo.'),
('kam', 'ACT', 23, 27, 'Mũndũ ũũ nĩwakwatiwe nĩ Ayuti, na makilĩlye kũmũaa, nakwa namatheeea nĩ na asikalĩ na namũtangĩĩa, namanya kana nĩ Mũlomi.'),
('kam', 'ACT', 23, 28, 'Na ngĩmantha kĩla mamũvinganĩĩsye, namũtheesya namũtwaa mbee wa nzama yoo:'),
('kam', 'ACT', 23, 29, 'nakwa noonie kana evinganĩĩw’a nũndũ wa mokũlyo ma mĩao yoo, ĩndĩ kũiaĩ ũndũ ĩũlũ wake ũtuma oawa kana kwovwa.'),
('kam', 'ACT', 23, 30, 'Nakwa nonetwe kana mũndũ ũũ akooveew’a, namũete kwaku oyu, ngĩmeaĩa ala mamũvinganĩsye nao, moke maneene mbee waku ũla me naw’o ĩũlũ wake. Ĩkala na ũvoo.'),
('kam', 'ACT', 23, 31, 'Na ĩndĩ, ala asikalĩ mamwosa Vaulo, o ũndũ meaĩwe, na mamũvikya Andivatili na ũtukũ.'),
('kam', 'ACT', 23, 32, 'Ĩndĩ ũnĩ ũsu masyoka ngomenĩ, mamatia ala matũlĩte mbalasi mathi nake:'),
('kam', 'ACT', 23, 33, 'nao mavika Kaisalea, mamũnenga ngavana ũla valũa, na mamwia Vaulo mbee wake.'),
('kam', 'ACT', 23, 34, 'Nake asoma, amakũlya nĩ mũndũ wa nthĩ yĩva; na amanya kana nĩ mũndũ wa Silisia,'),
('kam', 'ACT', 23, 35, 'asya, Ngakwĩthukĩĩsya vyũ yĩla meũka nao ala makũvinganĩsye: na eeaa asũvĩĩwe nyũmbanĩ ya sila ya Elote.'),
('kam', 'ACT', 24, 1, 'Na ĩtina wa mĩthenya ĩtano ũla mũthembi mũnene Anania atheea na amwe ma atumĩa, na mũneeni ũmwe wetawa Telitulo; nao mamũtavya ngavana ũvoo wa Vaulo.'),
('kam', 'ACT', 24, 2, 'Na Vaulo eetwa, Telitulo ambĩlĩlya ũmũvinganĩsya aiasya, Nĩkwĩthĩwa ithyĩ twonaa mũuo mũnene nũndũ waku, we, Velike mũtaĩwa, na kwa ũsũvĩo waku maũndũ mathũku nĩmaseũvaw’a nthĩnĩ wa mbaĩ ĩno,'),
('kam', 'ACT', 24, 3, 'nĩtũwosaa na nzĩa syonthe, na kũndũ kw’onthe, na mũvea w’onthe.'),
('kam', 'ACT', 24, 4, 'Ĩndĩ ndikakwĩkalye vaa mũno, nĩngũkwĩsũva ũtwĩw’ĩe ndeto mbũthũ nũndũ wa ĩnee yaku.'),
('kam', 'ACT', 24, 5, 'Nũndũ nĩtwonete mũndũ ũũ, e mũndũ wĩ kolokolo, mwene kwambĩlĩlya mong’endu katĩ wa Ayuti onthe kũũ kw’onthe nthĩ, nake nĩ mũtongoi wa kĩthemba kya Anasali:'),
('kam', 'ACT', 24, 6, 'ũla watatie naw’o mbee wa ũu kũvukya ĩkalũ: na twamũkwata: (tũkyenda kũmũsilĩla kwĩanana na mĩao yaitũ.'),
('kam', 'ACT', 24, 7, 'Ĩndĩ ũla mũnene wa asikalĩ ngili wĩtawa Lisiasi ooka, na amumya mokonĩ maitũ na vinva mũnene,'),
('kam', 'ACT', 24, 8, 'aimeaĩa avinganĩsya make moke mbee waku.) Nũtonya, kwa ũmũkũlya mwene, kũmanya maũndũ onthe ala tũũmũvinganĩĩsya.'),
('kam', 'ACT', 24, 9, 'Na Ayuti nao maatĩĩa ũvingan’yo ũsu, makyasya, kana maũndũ asu nĩ ma w’o.'),
('kam', 'ACT', 24, 10, 'Na ngavana amũkĩlĩlya kw’oko, nĩ kana aneene, Vaulo asũngĩa, Nĩkwĩthĩwa nĩnĩsĩ kana we wĩ mũsili wa mbaĩ ĩno myaka mingĩ, nyie nĩngumya ũsũngĩo wakwa na mũyo;'),
('kam', 'ACT', 24, 11, 'nĩkwithĩwa nũtonya kũmanya vyũ, kana kuma yĩla naendie Yelusaleme kũthaitha, ndĩvĩtũka mĩthenya ĩkũmi na ĩli:'),
('kam', 'ACT', 24, 12, 'na maiaambona ngĩkananĩa na mũndũ ĩkalũnĩ kana ngĩthokoan’ya nguthu, o na masinakokenĩ, o na ndũanĩ.'),
('kam', 'ACT', 24, 13, 'O na maitonya kwonan’ya vyũ kana maũndũ asu ala meũmbinganĩĩsya kwaku nĩ ma w’o.'),
('kam', 'ACT', 24, 14, 'Ĩndĩ nĩngũlĩkĩla ũndũ ũũ ũmwe mbee waku, kana kũatĩĩa ĩla Nzĩa ĩla mamĩtaa kĩthemba kya ũvũngũ, nĩw’o nĩmũthũkũmaa Ngai wa aasa maitũ, ngĩtĩkĩla maũndũ onthe ala mosana na ĩla mĩao, na onthe ala maandĩkĩtwe mavukunĩ ma athani:'),
('kam', 'ACT', 24, 15, 'nĩ na wĩkwatyo kwa Ngai, ũla aa namo ene meteele, kana kũkeethĩwa ũthayũũkyo wa ala alũngalu, na ala mate alũngalu nao.'),
('kam', 'ACT', 24, 16, 'Na kwa ũu nĩngwĩmanyĩsya mwene nĩthĩwe na wasya wa ngoo ũte na ũthũkyo kwa Ngai na kwa andũ mĩthenya yonthe.'),
('kam', 'ACT', 24, 17, 'Na ĩtina wa myaka ĩmwe nĩnookie kũetee mbaĩ yakwa ũtethyo na nthembo:'),
('kam', 'ACT', 24, 18, 'na ngĩka ũu mambonie nĩ mũthesye ĩkalũnĩ, nde na nguthu, kana kĩthokoan’yo: ĩndĩ kwaĩ Ayuti amwe maumie Asia—'),
('kam', 'ACT', 24, 19, 'nao nĩmaĩlwe nĩ kwĩthĩwa vaa mbee waku, na kũmbinganĩsya, ethĩwa me na ũndũ ĩũlũ wakwa.'),
('kam', 'ACT', 24, 20, 'Kana andũ aa ene nĩmaneene ũndũ ũtaĩle wakwa ũla moonie yĩla naũngamie mbee wa nzama,'),
('kam', 'ACT', 24, 21, 'ate o kwondũ wa wasya ũmwe, ũla naneenie nĩũngeme katĩ wamo, ngyasya, Kwondũ wa kũthayũũkw’a kwa akw’ũ nĩngũsilĩlwa ũmũnthĩ mbee wenyu.'),
('kam', 'ACT', 24, 22, 'Ĩndĩ Velike, nĩkwĩthĩwa nĩwesĩ nesa ũndũ wa ĩla Nzĩa, amatĩsya, aiasya, O yĩla Lisiasi ũla mũnene wa asikalĩ ngili wĩtheea, ngatw’a ũndũ wenyu.'),
('kam', 'ACT', 24, 23, 'Nake eeaia ũla mũnene wa asikalĩ ĩana kana Vaulo asũvĩwe, ĩndĩ nĩethĩwe na ũthei; na anyanyae make maikavatwe kũmũtethya.'),
('kam', 'ACT', 24, 24, 'Ĩndĩ ĩtina wa mĩthenya ĩmwe, Velike ooka na mũka wake Ndilusila, nake aĩ Mũyutĩ, na amũtũmana Vaulo, na amwĩthukĩĩsya ũvoonĩ wa mũĩkĩĩo ũla wĩ nthĩnĩ wa Klĩsto Yesũ.'),
('kam', 'ACT', 24, 25, 'Na akĩneena ũndũ wa ũlũngalu, na wĩting’o, na ũsilĩlo ũla ũkoka, Velike akwatwa nĩ w’ĩa, na amũsũngĩa, Enda yu; na yĩla nĩona ũthei, ngakwĩta ũke kwakwa.'),
('kam', 'ACT', 24, 26, 'Nake vamwe na ũu, aĩ na wĩkwatyo wa ũnengwa mbesa nĩ Vaulo: na kwondũ wa ũu amwĩtangaa kaingĩ, na ũneena nake.'),
('kam', 'ACT', 24, 27, 'Ĩndĩ myaka ĩlĩ yathela. Velike alivũlwa nĩ Volikio Vesito; na akyenda kwendeesya Ayuti, amũeka Vaulo e o mwove.'),
('kam', 'ACT', 25, 1, 'Na ĩndĩno Vesito alika nthĩ yake, na mĩthenya ĩtatũ yathela ambata Yelusaleme kuma Kaisalea.'),
('kam', 'ACT', 25, 2, 'Na athemb anene na andũ ala anene ma Ayuti mamũtavya ũvoo wa Vaulo; na mamwĩsũva,'),
('kam', 'ACT', 25, 3, 'ameke nesa ũndũ wa Vaulo, kana amũtũmane aetwe Yelusaleme; nĩ kana matonye kũmwoveesya nzĩanĩ mamũae okĩte.'),
('kam', 'ACT', 25, 4, 'Ĩndĩ Vesito amasũngĩa, kana Vaulo esũvĩĩwa Kaisalea, na ĩngĩ kana we mwene nũkilĩlye kũthi kw’o mĩtũkĩ.'),
('kam', 'ACT', 25, 5, 'Na ĩngĩ asya, Kwondũ wa ũu, ala me na ũtonyi katĩ wenyu, nĩmatheee vamwe nakwa, na ethĩwa ve ũndũ ũtaĩle mũndũnĩ ũsu, nĩmamũvinganĩsye.'),
('kam', 'ACT', 25, 6, 'Na ekala kw’o mĩthenya ĩtathonokete nyanya kana ĩkũmi, atheea Kaisalea; na ũnĩ ũsu ekala kĩvĩlanĩ kya sila, na eeaa Vaulo aetwe.'),
('kam', 'ACT', 25, 7, 'Nake ooka, Ayuti ala manatheeie kuma Yelusaleme maũngama mamũthyũlũlũkĩte, makĩete movingan’yo maingĩ na maito ĩũlũ wake, nao matyaatonya kwonan’ya kana nĩ ma w’o;'),
('kam', 'ACT', 25, 8, 'ĩndĩ Vaulo aumya ũsũngĩo wake, aiasya, Ndyaavĩtya nongo ĩũlũ wa ĩla mĩao ya Ayuti, o na ĩũlũ wa ĩkalũ, o na ĩũlũ wa Kaisali.'),
('kam', 'ACT', 25, 9, 'Ĩndĩ Vesito, akyenda kwendeesya Ayuti, amũsũngĩa Vaulo aimwĩa, Nũkwenda kwambata Yelusaleme, ũkasilĩĩlwe kw’o mbee wakwa ũndũ wa maũndũ asu?'),
('kam', 'ACT', 25, 10, 'Ĩndĩ Vaulo asya, Nĩũngeme mbee wa kĩvĩla kya sila kya Kaisali, vala naĩlwe nĩ kũsilĩĩlwa: Ayuti ndimekĩte ũndũ ũthũku, o ũndũ we wĩsĩ mũno.'),
('kam', 'ACT', 25, 11, 'Ethĩwa ĩndĩ nĩ mwĩki wa naĩ, na ethĩwa nĩnĩkĩte ũndũ waĩle kĩkw’ũ, ndiũlea kũkw’a; ĩndĩ ethĩwa maũndũ asu ti ma w’o ala aa meũmbinganĩĩsya, vai mũndũ ũtonya kũnumya na kũnengane kwa mo. Nĩmwĩkaĩla Kaisali.'),
('kam', 'ACT', 25, 12, 'Na ĩndĩ Vesito amina kũneena na nzama, amũsũngĩa, Nĩwamwĩkaĩla Kaisali: ũkathi kwa Kaisali.'),
('kam', 'ACT', 25, 13, 'Na mĩthenya ĩmwe yavĩta, mũsumbĩ Akiliva na Velinike mavika Kaisalea, mamũkethya Vesito.'),
('kam', 'ACT', 25, 14, 'Na makĩkala kw’o mĩthenya mingĩ, Vesito amũtavya ũla mũsũmbĩ ũvoo wa Vaulo, aiasya, Kwĩ mũndũ ũmwe vaa watiiwe e mwove nĩ Velike;'),
('kam', 'ACT', 25, 15, 'nakwa, yĩla naĩ Yelusaleme, athembi anene na atumĩa ma Ayuti nĩmandavisye ũvoo wake, makĩngũlya nĩmũtw’ĩĩe.'),
('kam', 'ACT', 25, 16, 'Nakwa namasũngĩa, kana ti kĩthĩo kya Alomi kũnengane mũndũ o na wĩva, mũvinganĩw’a atanamba kwonana na ala mamũvinganĩsye, ũthyũ kwa ũthyũ, one ũthei wa kwĩneenea ũndũ ũla ũvinganĩĩw’e.'),
('kam', 'ACT', 25, 17, 'Na ĩndĩ moombana vaa, ndyaaĩkala, ĩndĩ ũnĩ ũsu nekalile kĩvĩlanĩ kya sila, na neeaa kana mũndũ ũsu aetwe.'),
('kam', 'ACT', 25, 18, 'Na ala mamũvinganĩsye maũngama, matyaaete ũndũ ũthũku nongo iũlũ wake tondũ natalĩlasya meũete;'),
('kam', 'ACT', 25, 19, 'ĩndĩ maĩ na mokũlyo amwe ĩũlũ wake ũndũ wa ũthaithi woo ene, na ũndũ wa mũndũ ũmwe Yesũ, ũla waĩ anakw’a, ũla Vaulo walũlũmĩlaa mũno kwasya e thayũ.'),
('kam', 'ACT', 25, 20, 'Nakwa, nasũanĩwa ũndũ ngũkũlya maũndũ asu, namũkũlya kana nũnũkwenda kũthi Yelusaleme, akasilĩlwe kw’o ũndũ wa maũndũ asu.'),
('kam', 'ACT', 25, 21, 'Ĩndĩ Vaulo enda asũvĩwe akasilĩlwe nĩ Kaisali, neeaa asũvĩwe mũvaka yĩla nĩmũtwaa kwa Kaisali.'),
('kam', 'ACT', 25, 22, 'Akiliva amwĩa Vesito, Nyie o nakwa nĩnendaa kwĩthukĩĩsya ũ mũndũ. Amwĩa, Ũkamwĩthukĩĩsya ũnĩ.'),
('kam', 'ACT', 25, 23, 'Na ĩndĩ ũnĩ ũsu, Akiliva ooka, na Velinike, na ũsũng’wa mũnene, na mavota vandũ va kwĩthukĩĩsya vamwe na anene ma asikali ngili, na andũ anene ma ndũa, Vesito eeaa Vaulo naetwe.'),
('kam', 'ACT', 25, 24, 'Na Vesito asya, Mũsumbĩ Akiliva, na andũ aa onthe ala mwĩ vaa vamwe naitũ, nĩmũkwona mũndũ ũũ, ũla ĩkomano yonthe ya Ayuti, Yelusaleme o na kũũ, nĩmamboyete kwondũ wake, maineena mũno, maiasya, kana ndaĩle kwĩthĩwa thayũ.'),
('kam', 'ACT', 25, 25, 'Ĩndĩ nyie noonie kana ndaaĩka ũndũ o na wĩva ũtuma oawa: na kwa kwĩthĩwa we mwene nĩwamwĩkaĩlile Kaisali natw’a kũmũtwaa kw’o.'),
('kam', 'ACT', 25, 26, 'Nakwa ndi na ũndũ wa w’o wa ũmũandĩkĩa mwĩaĩi wakwa kwondũ wake. Kwondũ wa ũu namũete vaa mbee wenyu, na mũno mbee waku, mũsumbĩ Akiliva, nĩ kana akũlangw’a, ĩtina none nongo ũndũ wa kũandĩka.'),
('kam', 'ACT', 25, 27, 'Nũndũ nĩngwona nĩ ũndũ ũtaĩle kũtwaa mwovwa, na kũlea kwonan’ya movingan’yo ala ũvinganĩw’e namo.'),
('kam', 'ACT', 26, 1, 'Na Akiliva amwĩa Vaulo, Wĩ na ũthei wa kwĩneenea mwene. Na ĩndĩ Vaulo atambũũkya kw’oko kwake, na eeneenea mwene:'),
('kam', 'ACT', 26, 2, 'Nĩngwĩtala mwene kwĩthĩwa na ũtanu, mũsumbĩ Akiliva, nĩkwĩthĩwa nĩnanengwa kwĩneenea mbee waku ũmũnthĩ ũndũ wa maũndũ onthe ala nĩvinganĩĩw’e nĩ Ayuti:'),
('kam', 'ACT', 26, 3, 'na mbee nũndũ we wĩ mũmanyi mũĩ wa syĩthĩo syonthe na mokũlyo onthe ma Ayuti: kwondu wa ũu nĩngũkwĩsũva ũmbĩthukĩĩsye na wũmĩĩsyo.'),
('kam', 'ACT', 26, 4, 'Ayuti onthe nĩmesĩ, mwĩkalĩle wa thayũ wakwa kuma nĩ kavĩsĩ, kuma mwambĩlĩlyonĩ katĩ wa mbaĩ yakwa, na ku Yelusaleme;'),
('kam', 'ACT', 26, 5, 'nĩmambĩsĩ mũno kuma tene ethĩwa nĩmekwenda kũneena ũkũsĩ, kana nyie naĩ Mũvalisi kũatĩĩa na kwĩanĩsya kĩthemba kya ũthaithi witũ ũla mũmũ mbee.'),
('kam', 'ACT', 26, 6, 'Na yu nĩngũũngama vaa nĩsilĩlwe kwondũ wa wĩkwatyo wa watho ũla Ngai wamathie aasa maitũ;'),
('kam', 'ACT', 26, 7, 'na kwaw’o mbaĩ sitũ ĩkũmi na ilĩ nĩsyĩkwatasya kwĩthĩwa ikavikĩa, ikĩmũthũkũma Ngai na ũthangaau ũtukũ na mũthenya. Na ũndũ wa wĩkwatyo ũũ, mũsumbĩ, nĩngũvinganĩw’a nĩ Ayuti!'),
('kam', 'ACT', 26, 8, 'Nĩkĩ mũkwona nĩ ũndũ ũtetĩkĩlĩka, kana Ngai athayũũkasya akw’ũ?'),
('kam', 'ACT', 26, 9, 'Nĩ w’o nyie mwene nĩnoonie kana nĩnaĩlwe nĩ kwĩka maũndũ maingĩ mavĩtanĩte na syĩtwa ya Yesũ wa Nasaleti.'),
('kam', 'ACT', 26, 10, 'Nakwa nĩneekie ũu Yelusaleme: na namavingie aingĩ ma ala atheu makolokolonĩ, nosete ũkũmũ kwa athembi anene, na maiũawa wasya wakwa waĩ vo ĩũlũ woo.'),
('kam', 'ACT', 26, 11, 'Na ngĩmathĩn’ya kaingĩ masinakokenĩ onthe, natatie kũmaumĩthya Ngai; na kwa kwĩthĩwa namathatĩe mũno, namathĩn’ya o na kũvika ndũa sya ũeninĩ.'),
('kam', 'ACT', 26, 12, 'Na ngĩka maũndũ asu, yĩla naendete Ndamasiku nĩ na ũkũmũ na ũtũme wa athembi anene,'),
('kam', 'ACT', 26, 13, 'mũthenya katĩ, mũsumbĩ, nonie nzĩanĩ kyeni kuma ĩtunĩ, kĩthonokete ũtisu wa syũa kĩikena ngalĩ syonthe syakwa na sya ala maendete vamwe nakwa.'),
('kam', 'ACT', 26, 14, 'Na twavalũka nthĩ ithyonthe, newie wasya ũineena nakwa kĩthyomonĩ kya Kĩevelania, ũiasya, Saulo, Saulo, nĩkĩ ũũnthĩn’ya? Nĩ vinya kwaku kũtheela mũsenge.'),
('kam', 'ACT', 26, 15, 'Nakwa nasya, Nue ũũ, Mwĩaĩi? Na Mwĩaĩi anzũngia, Ninyie Yesũ ũla ũũthĩn’ya.'),
('kam', 'ACT', 26, 16, 'Ĩndĩ ũkĩla, ũũngame na maũũ maku: nũndũ nakumĩlĩla kwondũ wa ũndũ ũũ, kũkwia we wĩthĩwe mũthũkũmi na ngũsĩ ya maũndũ asu ala wambona nyie nĩ nthĩnĩ wamo, na ya maũndũ ala nthĩnĩ wamo ngakumĩlĩla:'),
('kam', 'ACT', 26, 17, 'ngiũtangĩĩa kwa andũ ma mbaĩ yaku, na kwa Andũ‐ma‐mbaĩ‐ingĩ, ala ngũũtũma kwamo,'),
('kam', 'ACT', 26, 18, 'kũmasalukya metho moo, nĩ kana methyũũe na kũkĩtia kĩvindu makyelekele kyeni, na kũeka ũkũmũ wa Satani na ũmwelekela Ngai, nĩ kana mose ũekeo wa naĩ, na ũtiĩwa vamwe na onthe ala mavathanĩtw’e kwondũ wa mũĩkĩĩo ũla wĩ kwakwa.'),
('kam', 'ACT', 26, 19, 'Nĩvo ĩndĩ, mũsumbĩ Akiliva, ndyaatw’ika mũlei wa ũla woni waumie ĩtunĩ:'),
('kam', 'ACT', 26, 20, 'ĩndĩ mbee natavanisye kwa ala ma Ndamasiku, na Yelusaleme, na ku kw’onthe nthĩ ya Yutia, na kwa Andũ‐ma‐mbaĩ‐ingĩ nao, kana mealyũle na ũmwelekela Ngai, mekae meko mosanĩte na kũalyũla ngoo kwoo.'),
('kam', 'ACT', 26, 21, 'Kwondũ wa ũu Ayuti mangwatĩa ĩkalũnĩ na menda ũmbũaa.'),
('kam', 'ACT', 26, 22, 'Ĩndĩ nĩkwĩthĩwa nosete ũtethyo ũla wumaa kwa Ngai, nĩũngeme kũvika ũmũnthĩ ngĩnenga ũkũsĩ anene na anini nao, o na ndiũneena ũndũ, ate o ũla athani na Mose maisye ũkoka:'),
('kam', 'ACT', 26, 23, 'wa atĩ ũndũ Klĩsto nde ndĩi ya ũlea kũthĩnw’a, na ũndũ we ũkamba kũthayũũkw’a kwa akw’ũ na kũtavan’ya kyeni kwa andũ ma mbaĩ yaitũ na kwa Andũ‐ma‐mbaĩ‐ingĩ.'),
('kam', 'ACT', 26, 24, 'Na akĩneena ũu, Vesito amwĩa na wasya mũnene, Vaulo, wĩ na ndũũka; kũsoma waku kwingĩ nĩkũũkũalyũkĩla ndũũka.'),
('kam', 'ACT', 26, 25, 'Ĩndĩ Vaulo asũngĩa, Nyie ndi na ndũũka, we Vesito mũtaĩwa, ĩndĩ nĩneena ndeto sya w’o na sya kĩlĩko.'),
('kam', 'ACT', 26, 26, 'Nũndũ mũsumbĩ nĩwĩsĩ ũvoo wa maũndũ asu, nakwa nĩneena nake vyũ: nũndũ nĩnĩsĩ mũno kana kũi ũmwe wa maũndũ asu ũvithĩtwe kwake; nũndũ ũndũ ũũ ndwĩkĩtwe ũtee kĩmbithĩnĩ.'),
('kam', 'ACT', 26, 27, 'Mũsumbĩ Akiliva, nĩwĩtĩkĩlaa athani? Nĩnĩsĩ kana nũmetĩkĩlaa.'),
('kam', 'ACT', 26, 28, 'Na Akiliva amũtavya Vaulo, Vatiele vanini ũngalyũle ndw’ĩke Mũklĩsto.'),
('kam', 'ACT', 26, 29, 'Na Vaulo asya, Nĩngũvoya Ngai, ethĩwa nĩ vanini kana ethĩwa nĩ vanene, tuue weka, ĩndĩ o na onthe ala meũmbĩw’a ũmũnthĩ, methĩwe mailyĩ takwa, ate o mĩnyololo ĩno.'),
('kam', 'ACT', 26, 30, 'Na mũsumbĩ ookĩla, na ngavana, na Velinike, na ala mekalĩte vamwe nao;'),
('kam', 'ACT', 26, 31, 'na maumaala ũtee, maneenan’ya, maiasya, Mũndũ ũsu nde na ũndũ waĩle kĩkw’ũ kana kwovwa.'),
('kam', 'ACT', 26, 32, 'Na Akiliva amwĩa Vesito, Kethĩwa ndaamwĩkaĩla Kaisali, ethĩwa athaw’a.'),
('kam', 'ACT', 27, 1, 'Na kwatw’ĩtwe kana tũende na ngalawa Italia, mamũnengane Vaulo na ovwa angĩ amwe kwa mũnene wa asikalĩ ĩana wetawa Yuliusi, wa nguthu ya Aukusito.'),
('kam', 'ACT', 27, 2, 'Na twavota ngalawanĩ ya ku Atilamitio, ĩla yakilĩlye ũkũsya ĩthi kũndũ kwingĩ ũtee wa nthi ya Asia, na twathi na ũkanga, na Alisitaliko, mũndũ wa Masetonia wa ndũa ya Thesalonika, eethĩwa vamwe naitũ.'),
('kam', 'ACT', 27, 3, 'Na mũthenya wa kelĩ twavika Sitoni: na Yuliusi amwĩka Vaulo nesa, na amũnenga ũthei athi kwa anyanyae nĩ kana evuũkye.'),
('kam', 'ACT', 27, 4, 'Na twathi ĩngĩ na ũkanga kuma kw’o, twaenda na ũtee ũla ũkilĩtye wa kĩthama kya Kuvolo, nũndũ iseve syaumie na mbee.'),
('kam', 'ACT', 27, 5, 'Na twakĩla ũkanga ũla wĩ ngalĩ ya Silisia na Vambilia, twavika Mila, ndũa ya Lisia.'),
('kam', 'ACT', 27, 6, 'Na ku ũla mũnene wa asikalĩ ĩana oona nga awa ya Ũalesandalia ĩendete Italia; na atũlikya vo.'),
('kam', 'ACT', 27, 7, 'Na twathi kavola kavola mĩthenya mingĩ, twathi na vinya twesa ũthengeea Kinito, na kĩseve kyatũsiĩĩa, twathi ũtee ũla ũkilĩtye wa Kilete, twelekele Salimone;'),
('kam', 'ACT', 27, 8, 'na twathi na vinya ũtee wakyo twavika vandũ vetawa Ũthũmũo Mũseo; na vakuvĩ na vo vaĩ ndũa yĩtawa Lasea.'),
('kam', 'ACT', 27, 9, 'Na ĩvinda ĩasa yavĩta, na kũthi na ngalawa ĩvinda yĩu kwaĩ na mũisyo, nĩkwĩthĩwa o na ĩvinda ya kũtĩĩa kũya yaĩ yĩnavĩta, Vaulo amataa,'),
('kam', 'ACT', 27, 10, 'aimea, Mavwana, nĩngwona kana mũendo ũũ ũkeethĩwa wa ũnyamao na wasyo mwingĩ, na ti mũisyo wa mĩio na ngalawa syoka, ĩndĩ wa mathayũ maitũ namo.'),
('kam', 'ACT', 27, 11, 'Ĩndĩ ũla mũnene wa asikalĩ ĩana nĩwamethũkĩĩsye mũtwai na mwene wa ngalawa, mbee wa maũndũ ala maneeniwe nĩ Vaulo.'),
('kam', 'ACT', 27, 12, 'Na nĩkwĩthĩwa kĩthũmũo kĩtiaĩ kĩnene kya kwĩkala myei ya mbevo, ala aingĩ moo masya mathi na ũkanga kuma kw’o, nongo mavike Vinisi, mekale kw’o myei ya mbevo; nakyo nĩ kĩthũmũo kya Kilete, ngalĩ ya ĩũlũ kwelekela wumĩlonĩ wa syũa, na ngalĩ ya ĩtheo kwelekela wumĩlonĩ wa syũa.'),
('kam', 'ACT', 27, 13, 'Na kĩseve kya ngalĩ ya ĩtheo kyauutana kavola, matalĩlya ta moona ũndũ mekwenda, mambatya nanga na makũsya maikyamana na Kilete, vakuvĩ na ũtee wa ũkanga.'),
('kam', 'ACT', 27, 14, 'Ĩndĩ ĩtina wa ĩvinda yĩte ĩasa, kyamatheeea kĩseve kyai mũno, kĩla kĩtawa Eulakulo;'),
('kam', 'ACT', 27, 15, 'na ngalawa yakwatwa nĩ kĩseve, na yaemwa nĩ ũkyelekela, twamĩeka, na twatwawa nĩkyo.'),
('kam', 'ACT', 27, 16, 'Na tũitwawa twavika ũtee ũla ũkilĩtye wa kĩthama kĩnini kĩtawa Kauta, nĩtwoonie vinya kũlũmya kakalawa:'),
('kam', 'ACT', 27, 17, 'na makatũlya ĩũlũ, malũlũmĩlya ngalawa, kwa ũvĩtĩlya makanda ungu wayo; na maikĩa maikalũme kĩthangathĩni kĩtawa Siliti, matheesya ngũa sya ngalawa sya ũkwata kĩseve, na ũu matwawa nĩ kĩseve o kũla kĩkwenda.'),
('kam', 'ACT', 27, 18, 'Naitũ tũkĩnyamaw’a mũno nĩ kĩuutani mũthenya wa kelĩ mambĩlĩlya kwĩkya mĩio ĩla makuĩte ũkanganĩ;'),
('kam', 'ACT', 27, 19, 'na mũthenya wa katatũ mekya syĩndũ sya ngalawa na moko moo ene.'),
('kam', 'ACT', 27, 20, 'Na syũa na ndata ityaatũkenea mĩthenya mingĩ, na ũndũ kĩuutani kyaĩ kĩnene ĩũlũ waitũ, kwavetwa wĩkwatyo w’onthe wa ũvĩta.'),
('kam', 'ACT', 27, 21, 'Na mekalĩte ĩvinda ĩasa mateũya lĩu, nĩvo ĩndĩ Vaulo waũngamie katĩ woo, na asya, Mavwana, nĩmwaaĩlwe nĩ ũmbĩw’a, na kũlea kuma Kilete, mũikoneke nĩ ũnyamao ũũ na wasyo.'),
('kam', 'ACT', 27, 22, 'Na yu nĩmũtaa mwĩthĩwe mwĩ kwa ũmwe anyiau; nũndũ kũikethĩwa kwaa thayũ kwa ũmwe katĩ wenyu, ate o ngalawa yoka.'),
('kam', 'ACT', 27, 23, 'Nũndũ ũtukũ ũũ wa ũmũnthĩ mũlaĩka wa Ngai ũla nĩ wake, na ũla nĩthũkũmaa, nũũngamie ũtee wakwa,'),
('kam', 'ACT', 27, 24, 'aiasya, Ndũkakĩe, Vaulo; ndũtĩa kũũngama mbee wa Kaisali: na sisya, Ngai nũkũnengete onthe ala maendete vamwe naku.'),
('kam', 'ACT', 27, 25, 'Kwondũ wa ũu, mavwana, ĩthĩwai na ũnyiau: nũndũ nĩngũmwĩtĩkĩla Ngai, kana kũkeethĩwa o ũndũ nĩiwe.'),
('kam', 'ACT', 27, 26, 'Ĩndĩ tũitĩa kwĩkw’a kĩthamanĩ kĩmwe.'),
('kam', 'ACT', 27, 27, 'Ĩndĩ ũtukũ wa ĩkũmi na kana wavika, tũkĩtwawa kũũ na kũũ ũkanganĩ wa Atilia, ta ũtukũ katĩ atwai ma ngalawa matalĩlya kana nĩmeũthengeea nthĩ ĩmwe:'),
('kam', 'ACT', 27, 28, 'na mathima ũliku wa manzĩ, meethĩa nĩ mĩkono mĩongo nyanya; na ĩtina vandũ vanini, mathima ĩngĩ, meethĩa nĩ mĩkono mĩongo thanthatũ.'),
('kam', 'ACT', 27, 29, 'Na tũikĩa tũikekw’e ngoongonĩ sya mavia, mekya nanga inya sya ĩtina wa ngalawa, na mambĩlĩlya kũvoya kũkye.'),
('kam', 'ACT', 27, 30, 'Na atwai ma ngalawa makyenda kũkĩa kuma ngalawanĩ, matheetye kakalawa ũkanganĩ, ta mekwĩkya nanga sya mbee sya ngalawa,'),
('kam', 'ACT', 27, 31, 'Vaulo amwĩa ũla mũnene wa asikalĩ ĩana na asikalĩ, Ethĩwa aa matikwĩkala ngalawanĩ, inyw’ĩ nenyu mũitonya kũvĩta.'),
('kam', 'ACT', 27, 32, 'Na ĩndĩ asikalĩ matila makanda ma kakalawa, na makaeka kavalũka.'),
('kam', 'ACT', 27, 33, 'Na kũikya, Vaulo amesũva onthe kana maye lĩu, aiasya, Ũmũnthĩ nĩ wa ĩkũmi na kana mweteele na kũlea ũya, o na mũiaaya kĩndũ o na kĩva.'),
('kam', 'ACT', 27, 34, 'Na kwa ũu nĩngũmwĩsũva mũye: nũndũ ũu nĩ kwondũ wa ũtangĩĩo wa mĩĩ yenyu: nũndũ vai ũsw’ĩĩ ũmwe wa mũtwe wa ũmwe wenyu o na wĩva wĩaa.'),
('kam', 'ACT', 27, 35, 'Na aneena ũu, oosa kĩmũtũ, amũtũngĩĩa Ngai mũvea onthe mene; na akĩtila, na ambĩlĩlya ũya.'),
('kam', 'ACT', 27, 36, 'Na ĩndĩ onthe matana, namo moosa kya ũya kyoo ene.'),
('kam', 'ACT', 27, 37, 'Naitũ ithyonthe ala twaĩ ngalawanĩ ũtalo witũ wavikĩte andũ maana elĩ na mĩongo mũonza na thanthatũ.'),
('kam', 'ACT', 27, 38, 'Nao maya mavũna, manyivya mĩio ya ngalawa, makĩkya nganũ ũkanganĩ.'),
('kam', 'ACT', 27, 39, 'Na kwakya, maiaamanya, nthĩ ĩsu: ĩndĩ moona kyoko kĩmwe kĩ na kĩvũngĩĩo, na masũanĩa ethĩwa nĩmatonya kũmĩete ngalwa nesa ĩũlũ wakyo.'),
('kam', 'ACT', 27, 40, 'Na matila ila nanga, maitia ũkanganĩ, na ĩvinda o yĩu mathasya makanda ala movete sukani; na mambatya ngũa ya mbee ĩkwate kĩseve, mathi maelete kivũngĩĩonĩ.'),
('kam', 'ACT', 27, 41, 'Ĩndĩ mavika vala vakomanĩe maũkanga elĩ, maaĩĩsya ngalawa mũthanganĩ; na mũthya wa ngalawa walũma wekala ũteũthingithanga, ĩndĩ mũthya wa ĩtina wamunda ũtũlangw’a nĩ vinya wa itulumo.'),
('kam', 'ACT', 27, 42, 'Na kũsũanĩa kwa asikalĩ kwaĩ kũaa ovwa onthe, maikathambĩe, makĩe.'),
('kam', 'ACT', 27, 43, 'Ĩndĩ ũla mũnene wa asikalĩ ĩana, akyenda kũmũtangĩĩa Vaulo, amasiĩĩa maikeke ũndũ mendaa; na ameaĩa kana ala matonya kũthambĩa meyĩkye ũkanganĩ, mambe ũvika mũthanganĩ;'),
('kam', 'ACT', 27, 44, 'na ala angĩ, amwe mbwaũnĩ, na angĩ syĩndũnĩ ingĩ sya ngalawa. Na kwa ũu, onthe mavonoka mavika mũthanganĩ.'),
('kam', 'ACT', 28, 1, 'Na twavonoka, nĩvo ĩndĩ twamanyie kana nĩ kĩthama kĩla kĩtawa Melita.'),
('kam', 'ACT', 28, 2, 'Na ene ma kw’o matwon’ya ũseo mũnene: nĩkwĩthĩwa nĩmavuvie mwakĩ, na matwosa ithyonthe, nũndũ wa mbua ĩla yauie, na mbevo ĩla yai kw’o.'),
('kam', 'ACT', 28, 3, 'Ĩndĩ Vaulo aunĩte mũio wa ngũ na ekya mwakinĩ, nzoka mbai yauma ila ngũnĩ nũndũ wa muutĩa, yamũũma kw’oko.'),
('kam', 'ACT', 28, 4, 'Na andũ ma kw’o moona ĩla nzoka ĩniinĩte kw’okonĩ kwake, masya ene kwa ene Nĩ w’o mũndũ ũsu nĩ mũaani, nake, o na kau avĩta ũkanganĩ, Ũla ũsilaa katĩ ndanetĩkĩla ekale thayũ.'),
('kam', 'ACT', 28, 5, 'Ĩndĩ we amĩvuunzĩa ĩla nzoka mwakinĩ, na ndaaona ũthũkyo.'),
('kam', 'ACT', 28, 6, 'Ĩndĩ mo meeteela aimbe kana kũvalũka nthĩ mĩtũkĩ, o ĩmwe, e mũkw’ũ: ĩndĩ meeteela ĩvinda ĩasa, na malea kwona ũndũ ũthũku ũimũkwata, maalyũla ililikano syoo masya kana we nĩ ngai.'),
('kam', 'ACT', 28, 7, 'Na vakuvĩ na vandũ vau vaĩ mĩũnda ya mũndũ mũnene wa kĩthama wetawa Vuvilio; ũla watwosie, na atũthokya na ngoo ya ũnyanya, mĩthenya ĩtatũ.'),
('kam', 'ACT', 28, 8, 'Na kweethĩwa, ĩthe wa Vuvilio aĩ mũwau mũno ndetema na kwĩtũũa nthakame: na Vaulo alika kwake, na avoya, na amwilĩĩla moko make amũvosya.'),
('kam', 'ACT', 28, 9, 'Na kweekwa ũu, angĩ nao ma kĩthama kyu ala maĩ na mowau mooka, na mavow’a:'),
('kam', 'ACT', 28, 10, 'namo matũtaĩa na ndaĩa nyingĩ; na tũikũsya, matwĩkĩĩa ngalawanĩ syĩndũ ila twaĩ vata nasyo.'),
('kam', 'ACT', 28, 11, 'Na ĩtina wa myei ĩtatũ twakũsya twĩ ngalawanĩ ya Ũalesandalia ĩla yekalĩte kĩthamanĩ kyu myei ya mbevo, nayo syĩtwa yayo nĩ Ndiosikuli.'),
('kam', 'ACT', 28, 12, 'Na twavika Silakuse, twekala kw’o mĩthenya ĩtatũ.'),
('kam', 'ACT', 28, 13, 'Na kuma vau twathyũlũlũka twavika Lekio: na ĩtina wa mũthenya ũmwe kiseve kyookĩla kuma ngalĩ ya ĩtheo, na mũthenya wa kelĩ twavika Vutiolo:'),
('kam', 'ACT', 28, 14, 'na vau twoona ana‐a‐asa, nao matwĩsũva twĩkale nao mĩthenya mũonza: na twavika Lomi ta ũu.'),
('kam', 'ACT', 28, 15, 'Na ana‐a‐asa ma vo, meew’a kana nĩtũkĩte kw’o, mooka ũtũthaũa kũvika kĩng’ang’a kya Aivu, na Mĩkawa Ĩtatũ; nake Vaulo amona, amũtũngĩa Ngai mũvea, na ngoo yalũlũmĩla.'),
('kam', 'ACT', 28, 16, 'Na twalika Lomi, ũla mũnene wa asikalĩ ĩana amanengane ovwa mokonĩ ma mũnene wa nguthu ya asũvĩi; ĩndĩ Vaulo nĩwanengiwe ũthei wa kwĩkala vandũ vake mwene vamwe na mũsikalĩ ũla wamũsũvĩaa.'),
('kam', 'ACT', 28, 17, 'Na kweethĩwa, ĩtina wa mĩthenya ĩtatũ ameta ala maĩ anene ma Ayuti mombane: na moombana, amea, Nyie, ana‐a‐asa, o na kau ndyaaĩka ũndũ ĩũlũ wa andũ maitũ, kana ũndũ ũtosana na syĩthĩo sya aasa maitũ, ĩndĩ nanenganiwe mokonĩ ma Alomi nĩ mwove kuma Yelusaleme:'),
('kam', 'ACT', 28, 18, 'nao, mamina ũngũlya, menda ũnthasya nĩkwĩthĩwa kũiaaoneka ũndũ kwakwa ũtuma nũawa.'),
('kam', 'ACT', 28, 19, 'Ĩndĩ yĩla Ayuti makananĩsye makĩlea, nething’ĩĩsye kũmwĩkaĩla Kaisali; ti atĩ naĩ na ũndũ wa ũmĩvinganĩsya mbaĩ yakwa naw’o.'),
('kam', 'ACT', 28, 20, 'Kwondũ wa ũu ĩndĩ, nĩnamwĩtie nĩmwone na kũneena nenyu: nũndũ nyie novetwe na mũnyololo ũũ kwondũ wa wĩkwatyo wa Isilaeli.'),
('kam', 'ACT', 28, 21, 'Nao mamwĩa, Tũiaaosa mavalũa ma ũvoo waku kuma Yutia, o na kũiaaũka o na ũmwe wa ana‐a‐asa vaa, aetete ũvoo waku kana kũneena ndeto nthũku ĩũlũ waku.'),
('kam', 'ACT', 28, 22, 'Ĩndĩ nĩtũkwenda kwĩw’a kuma kwaku ũndũ ũkwasya: nũndũ kĩthemba kyu nĩkĩsĩkĩwe kwitũ kana nĩkĩwetawa naĩ kũndũ kw’onthe.'),
('kam', 'ACT', 28, 23, 'Na matianĩa kyathĩ nake, mathi nyũmba ĩla wekalĩte andũ aingĩ mũno; amavuanĩsya na kumya ũkũsĩ wa maũndũ ma ũsumbĩ wa Ngai, na aimathing’ĩĩsya ũvoo wa Yesũ, kuma mĩaonĩ ya Mose na mavukunĩ ma athani, kuma kĩoko kũvika wĩoo.'),
('kam', 'ACT', 28, 24, 'Na amwe nĩmeetĩkĩlile maũndũ ala maneeniwe, na angĩ maiaaĩtĩkĩla.'),
('kam', 'ACT', 28, 25, 'Na meethĩwa matekwĩw’ana ene kwa ene, maithi Vaulo amatavya ndeto ĩno ĩmwe, Veva Mũtheu nĩwaneenie nesa na aaĩthe menyu, na kanyw’a wa mwathani Isaia,'),
('kam', 'ACT', 28, 26, 'akyasya, Enda kwa andũ aa, ũkasye, Kwĩw’a mũkeew’a, o na mũikamanya nongi; Na kũsisya mũkasisya, o na mũikona nongi:'),
('kam', 'ACT', 28, 27, 'Nũndũ ngoo sya andũ aa nĩ nenevu, Na matũ moo nĩmew’aa na vinya, Na metho moo nĩmalalĩtye; Maikese kwona na metho moo, Na kwĩw’a na matũ moo, Na kũmanya na ngoo syoo, Na kwĩalyũla, Na ngamavosya.'),
('kam', 'ACT', 28, 28, 'Na ĩndĩ nĩkũmanyĩke kwenyu, kana ũtangĩĩo ũũ wa Ngai nũtwaĩtwe kwa Andũ‐ma‐mbaĩ‐ingĩ: namo makawĩw’a.'),
('kam', 'ACT', 28, 29, 'Na aneena ndeto isu, Ayuti maumaala, me na ngananĩo nyingĩ ene kwa ene.'),
('kam', 'ACT', 28, 30, 'Nake ekala myaka ĩlĩ mĩima nyũmbanĩ yake mwene ĩla wathooete wikalo, na amosa onthe ala mavotaa kwake,'),
('kam', 'ACT', 28, 31, 'aitavan’ya ũvoo wa ũsumbi wa Ngai, na kũmanyĩsya maũndũ ma Mwĩaĩi Yesũ Klĩsto na ũnyiau w’onthe, ateũvatwa nĩ mũndũ.'),
('kam', 'ROM', 1, 1, 'Vaulo, ngombo ya Yesũ Klĩsto, wetiwe ethĩwe mũtũmwa, ũvathanĩtw’e kwondũ wa ũvoo mũseo wa Ngai,'),
('kam', 'ROM', 1, 2, 'ũla Ngai wambie kwatha tene na athani make nthĩnĩ wa maandĩko matheu,'),
('kam', 'ROM', 1, 3, 'ũvoo wa Mwana wake, ũla wasyaiwe wa ũsyao wa Ndaviti kwondũ wa mwĩĩ,'),
('kam', 'ROM', 1, 4, 'ũla watavaniw’e kwĩthĩwa nĩ Mwana wa Ngai na vinya, kwondũ wa veva wa ũtheu, nĩ kũthayũũkw’a kuma kwa akw’ũ; Yesũ Klĩsto Mwĩaĩi waitũ,'),
('kam', 'ROM', 1, 5, 'ũla kwondũ wake twosete mumo na ũtũmwa, nĩ kana andũ ma mbaĩ syonthe matw’ĩke ewi wĩtĩkĩlonĩ, kwondũ wa syĩtwa yake;'),
('kam', 'ROM', 1, 6, 'o nenyu katĩ wasyo, nĩmwĩtĩtwe mwĩthĩwe ma Yesũ Klĩsto:'),
('kam', 'ROM', 1, 7, 'valũa ũũ wakwa ũmavikĩe onthe ala me Lomi, endwa ma Ngai, ala meetiwe methĩwe atheu: Mumo nĩwĩthĩwe kwenyu na mũuo kuma kwa Ngai Asa waitũ na kwa Mwĩaĩi Yesũ Klĩsto.'),
('kam', 'ROM', 1, 8, 'Mbee, nĩmũtũngĩa Ngai mũvea nthĩnĩ wa Yesũ Klĩsto ũndũ wenyu inyw’onthe nũndũ mũĩkĩĩo wenyu nũtavanaw’a nthĩ yonthe.'),
('kam', 'ROM', 1, 9, 'Nũndũ Ngai nĩwe ngũsĩ yakwa, ũla nĩthaithaa vevanĩ wakwa ũvoonĩ mũseo wa Mwana wake, ũndũ nĩmũwetaa vate kũeka, mavinda onthe mboyanĩ syakwa'),
('kam', 'ROM', 1, 10, 'nĩngũvoya nũke kwenyu mĩthenya ĩno Ngai enda, aaĩlya kyalo kyakwa.'),
('kam', 'ROM', 1, 11, 'Nũndũ nĩ na mea ma kũmwona, kana nĩmũolele mũthĩnzĩo ũmwe wa veva, nĩ kana mũlũlũmĩlw’e;'),
('kam', 'ROM', 1, 12, 'naw’o, nĩ kana nyie vamwe nenyu tũkiakian’ye, kĩla ũmwe wa ithyĩ ũndũ wa mũĩkĩĩo wa ũla ũngĩ, wenyu na wakwa.'),
('kam', 'ROM', 1, 13, 'Ndikwenda mũlee ũmanya, ana‐a‐asa makwa, kana mavinda maingĩ nendaa kũka kwenyu (nakwa nĩnziĩĩĩtwe kũvika o na yu), nĩ kana nĩtonye kwĩthĩwa na ũsyao kwenyu nenyu, o ũndũ nĩ naw’o kwa Andũ‐ma‐mbaĩ‐ila‐ingĩ.'),
('kam', 'ROM', 1, 14, 'Nĩ na thiĩ na Akiliki na ala mate Akiliki, kwa ala me na ũmanyi na kwa ala atumanu.'),
('kam', 'ROM', 1, 15, 'Kwondũ wa ũu nĩnĩyũmbanĩtye kũtavan’ya ũvoo mũseo kwa inyw’i ala mwĩ Lomi, o ũndũ ndonya.'),
('kam', 'ROM', 1, 16, 'Nũndũ ndiwĩw’ĩaa nthoni ũla ũvoo mũseo: nũndũ nĩ vinya wa Ngai ũla ũtangĩĩaa o ũla wĩtĩkĩlaa; mbee nĩ Mũyuti, na ĩtina Mũkiliki.'),
('kam', 'ROM', 1, 17, 'Nũndũ ũlũngalu wa Ngai nĩwumĩlĩtw’e vo, kuma kũĩkĩĩa kũendeea na kũĩkĩĩa: tondũ kũandĩkĩtwe, Ĩndĩ ũla mũlũngalu akekala thayũ kwondũ wa kũĩkĩĩa.'),
('kam', 'ROM', 1, 18, 'Nũndũ ũthatu wa Ngai nĩwumĩlĩtw’e kuma ĩtunĩ ĩũlũ wa kĩla ũndũ ũte wa kũmũkĩa Ngai, na kĩla ũndũ ũte ũlũngalu wa andũ, ala masiĩĩaa ũla w’o ũndũnĩ ũte ũlũngalu;'),
('kam', 'ROM', 1, 19, 'nĩkwĩthĩwa maũndũ ma Ngai ala mamanyĩkaa nĩ monan’ye nthĩnĩ woo; nũndũ Ngai nĩwamonisye.'),
('kam', 'ROM', 1, 20, 'Nũndũ syĩndũ syake ila itonekaa kuma nthĩ yoombwa nikwoneka nesa, ikĩmanyĩka ũndũ wa ila syoombiwe, nasyo nĩ vinya wake wa tene na tene na Ũ Ngai wake; nĩ kana methĩwe mate na wĩmilo:'),
('kam', 'ROM', 1, 21, 'nĩkwĩthĩwa, yĩla mamwĩsi Ngai, matyaamũtaĩa ta nĩwe Ngai, o na matyaamũtũngĩa mũvea; ĩndĩ matw’ika ma mana mosũanĩonĩ moo, na ngoo syoo ndumanu syeekĩwa kĩvindu.'),
('kam', 'ROM', 1, 22, 'Kwĩyĩta amanyi, nĩmatw’ĩkĩte ndia,'),
('kam', 'ROM', 1, 23, 'na makũan’ya ũtheu mũtisu wa Ngai ũla ũtanangĩkaa na mũvw’anano wa mũndũ ũla wanangĩkaa, na wa syĩndũ ila iũlũkaa, na wa nyamũ ila syĩ na maũũ ana, na tũsamũ tũla tũtambũkaa.'),
('kam', 'ROM', 1, 24, 'Kwondũ wa ũu Ngai amalekya mĩmeonĩ mĩthũku ya ngoo syoo kũatĩĩa ũvuku, nĩ kana mĩĩ yoo mamyanangĩe ndaĩa ene kwa ene:'),
('kam', 'ROM', 1, 25, 'nũndũ nĩmakũanĩtye ũla w’o wa Ngai na ũvũngũ, na kũthaitha na kũthũkũma kyũmbe vandũ va Mũmbi, ũla ũkathawa tene na tene. Ameni.'),
('kam', 'ROM', 1, 26, 'Kwondũ wa ũu Ngai amalekya mĩmeonĩ mĩthũku ĩla yĩ nthoni: nĩkwĩthĩwa o na aka moo makũanisye mũtuo wa mũsyawa na mũtuo ũngĩ ũtosana na ũsu:'),
('kam', 'ROM', 1, 27, 'na aũme moo no ta ũu, maitia ũndũ ũla kwĩkawa kwa aka, makana mĩmeonĩ yoo ene kwa ene, aũme kwa aũme maĩĩka maũndũ mataĩle, na makyona nthĩnĩ woo ĩtuvi ya kũvĩtya kwoo yĩla yĩmaĩle.'),
('kam', 'ROM', 1, 28, 'Na o tondũ maleile kwĩthĩwa na Ngai ũmanyinĩ woo, Ngai amalekya methĩwe na kĩlĩko kĩtaĩle nongi, meke maũndũ asu mataĩle;'),
('kam', 'ROM', 1, 29, 'makyusũwa nĩ ũla ũte ũlũngalu w’onthe, na ũthũku, na ĩtomo, na wai; makyusũwa nĩ kĩwĩu, na ũaani, na ĩteta, na ũkenganĩ, na ũng’endu; aneeni ma kĩwe;'),
('kam', 'ROM', 1, 30, 'ailĩanĩli, ameni ma Ngai, avũthya, etaĩi, ekathĩĩi, ambĩlĩlya ma maũndũ mathe, matamew’aa ala mamasyaie,'),
('kam', 'ROM', 1, 31, 'mate na ũmanyi, anangi ma ũtianĩo, mate na wendo waĩle, mate na tei:'),
('kam', 'ROM', 1, 32, 'nao, o na mesĩ ũtw’ĩo wa Ngai, kana ala mekaa maũndũ ta asu nĩmaĩlwe nĩ kĩkw’ũ, nĩmekaa maũndũ asu, na ti ũu w’oka, ĩndĩ nĩmew’anaa na ala mamekaa.'),
('kam', 'ROM', 2, 1, 'Kwondũ wa ũu naku ndwĩ na wĩmilo, we mũndũ, ũla ũsilĩlaa ũngĩ: nũndũ maũndũnĩ ala ũsilĩlaa ũngĩ, wĩsilĩlaa mwene kana wĩ mũvĩtan’ya; nĩkwĩthĩwa we ũla ũsilĩlaa wĩkaa maũndũ o asu.'),
('kam', 'ROM', 2, 2, 'Naitũ nĩtwĩsĩ kana ũsilĩlo wa Ngai nĩ kwĩanana na w’o ĩũlũ wa ala mekaa maũndũ ta asu.'),
('kam', 'ROM', 2, 3, 'Naku mũndũ, ũla ũsilĩlaa ala mavikĩlaa maũndũ ta asu, naku mwene nũmekaa, wĩtalĩlya kana we ũkavonoka ũsilĩlo wa Ngai?'),
('kam', 'ROM', 2, 4, 'Kana we wĩvũthya wingĩ wa ũseo wake na wĩtũngi na wũmĩĩsyo, ũteũmanya kana ũseo wa Ngai ũkũtongoeasya ũalyũloni wa ngoo?'),
('kam', 'ROM', 2, 5, 'Ĩndĩ kũatĩĩa wũmũ waku na ngoo yaku ĩte na wĩlilo wĩyiĩaa ũthatu wa mũthenya wa ũthatu na wa wonan’yo wa ũsilĩlo mũlũngalu wa Ngai:'),
('kam', 'ROM', 2, 6, 'ũla ũkamũnenga kĩla mũndũ kwĩanana na meko make:'),
('kam', 'ROM', 2, 7, 'kwa asu ala mekwĩyũmĩĩsya kwĩkaa nesa mamanthaa ndaĩa na nguma na maũndũ matanangĩkaa, akamanenga thayũ ũtathela:'),
('kam', 'ROM', 2, 8, 'ĩndĩ kwa ala maetae ngananĩo, na matew’aa ũla w’o, ĩndĩ nĩmew’aa ũndũ ũte ũlũngalu, kũkeethĩwa ũthilĩku na ũthatu,'),
('kam', 'ROM', 2, 9, 'thĩna na ũnyamao, ĩũlũ wa kĩla mũndũ ũla wĩkaa nai, wa Mũyuti mbee, na wa Mũkiliki nake;'),
('kam', 'ROM', 2, 10, 'ĩndĩ ndaĩa na nguma na mũuo kwa kĩla mũndũ ũla wĩkaa nesa, Mũyuti mbee, na Mũkiliki nake:'),
('kam', 'ROM', 2, 11, 'nũndũ Ngai ti mwendeesya wa andũ.'),
('kam', 'ROM', 2, 12, 'Nũndũ onthe ala meekie nai ĩla mĩao ĩte vo makaaa vate ĩla mĩao; na asu onthe ala meekie nai me na ĩla mĩao makasilĩlwa na ĩla mĩao;'),
('kam', 'ROM', 2, 13, 'nũndũ ti ewi ma ĩla mĩao alũngalu mbee wa Ngai, ĩndĩ nĩ eki ma mĩao makatalĩlwa ũlũngalu;'),
('kam', 'ROM', 2, 14, '(nũndũ yĩla Andũ‐ma‐mbaĩ‐ingĩ mate na ĩla mĩao mekaa maũndũ ala me nthĩnĩ wa mĩao kwa mũtuo woo, andũ asu, mate na mĩao, no mo mĩao ene;'),
('kam', 'ROM', 2, 15, 'nũndũ maũndũnĩ asu meonan’ya wĩa wa ĩla mĩao ũandĩkĩtwe ngoonĩ syoo, wasya wa ngoo woo ũkĩkũsĩĩa, na malilikano moo ene kwa ene maimon’ya mavĩtyo kana kũmaekea;)'),
('kam', 'ROM', 2, 16, 'mũthenya ũla Ngai ũkasilĩla syĩmbithĩ sya andũ, kwa nzĩa ya Yesũ Klĩsto, kwĩanana na ũvoo mũseo wakwa.'),
('kam', 'ROM', 2, 17, 'Ĩndĩ ethĩwa we nĩwĩtawa Mũyuti na kwĩlingya ĩla mĩao, na kwĩkathĩĩa nthĩnĩ wa Ngai,'),
('kam', 'ROM', 2, 18, 'na kũmanya kwenda kwake, na kũmakũnĩa kĩthalũ maũndũ ala maseo mbee, ũmanyĩĩtw’e ĩla mĩaonĩ.'),
('kam', 'ROM', 2, 19, 'Na kũmanya nesa vyũ kana we mwene wĩ mũtongoi wa ililinda, na kyeni kya ala me kĩvindunĩ,'),
('kam', 'ROM', 2, 20, 'mũtai wa ala atumanu, na mũmanyĩsya wa tũũkenge, na wĩ na mũvw’ano wa ũmanyi na wa ũla w’o mĩaonĩ:'),
('kam', 'ROM', 2, 21, 'kwondũ wa ũu we ũla ũmanyĩasya ũngĩ, ndwĩmanyĩasya mwene? We ũla ũtavanasya kana mũndũ ndakoye, nĩwũyaa?'),
('kam', 'ROM', 2, 22, 'We ũla waasya mũndũ ndakalaalae, nũlaalaaa? We ũla ũmenaa mĩvw’anano, nĩwũyaa makalũnĩ mayo?'),
('kam', 'ROM', 2, 23, 'We ũla wĩkathĩĩaa nthĩnĩ wa ĩla mĩao, kwondũ wa kũvĩtya ĩla mĩao ndũkwanangĩa Ngai ndaĩa?'),
('kam', 'ROM', 2, 24, 'Nũndũ syĩtwa ya Ngai yĩumawa Andũnĩ‐mambaĩ‐ingĩ nũndũ wenyu, o tondũ kũandĩkĩtwe.'),
('kam', 'ROM', 2, 25, 'Nũndũ nĩ w’o nzaĩko yĩ vata, ethĩwa wĩ mwĩki wa ĩla mĩao: ĩndĩ ethĩwa wĩ mũvĩtan’ya wa ĩla mĩao, nzaĩko yaku ĩtw’ĩkĩte ti nzaĩko.'),
('kam', 'ROM', 2, 26, 'Ĩndĩ ethĩwa ũla ũtaĩkawa akwataa motw’io ma ĩla mĩao, kũtaĩkwa kwake kũikatalwa kwĩthĩwa nĩ nzaĩko?'),
('kam', 'ROM', 2, 27, 'Na ethĩwa ũla wa mũtuo wa kũlea kwaĩkwa, nũkwĩanĩsya ĩla mĩao, ndakaũsilĩla we, ũla wĩ na maandĩko na nzaĩko, na wĩ mũvĩtan’ya wa ĩla mĩao?'),
('kam', 'ROM', 2, 28, 'Nũndũ we ti Mũyuti ũla wĩ Mũyuti kwa ũvano wa ũtheinĩ: o na nzaĩko ti ĩla yĩ ũtheinĩ mwĩĩnĩ:'),
('kam', 'ROM', 2, 29, 'ĩndĩ we nĩ Mũyuti, ũla wĩ Mũyuti nthĩnĩ; na nzaĩko nĩ ĩla ya ngoo, vevanĩ na ti nthĩnĩ wa maandĩko; na ndaĩa yake ndyumaa andũnĩ, ĩndĩ yumaa kwa Ngai.'),
('kam', 'ROM', 3, 1, 'Mũyuti ĩndĩ akĩlanĩtye kyau? Kana kũuna kwa nzaĩko nĩ kwaũ?'),
('kam', 'ROM', 3, 2, 'Yĩ vata mũno na nzĩa syonthe: mbee nĩ kũĩkĩĩĩka na ndeto ila syaneeniwe nĩ Ngai.'),
('kam', 'ROM', 3, 3, 'Nata ĩndĩ o na ethĩwa amwe matyaĩ na mũĩkĩĩo? Kũlea kwĩtĩkĩla kwoo kũkatw’ĩkĩthya kĩthito kya Ngai ta kĩte na ũtonyi?'),
('kam', 'ROM', 3, 4, 'Aiee, kũikethĩwe ũu: nĩkũmanyĩke Ngai nĩ wa w’o, ĩndĩ kĩla mũndũ nĩ mũkengani; o tondũ kũandĩkĩtwe, Kana we ũtonye kwĩthĩwa mũlũngalu ndetonĩ syaku, Na ũtonye ũkĩlya yĩla wĩlika silanĩ.'),
('kam', 'ROM', 3, 5, 'Ĩndĩ ethĩwa ũte ũlũngalu witũ nĩwonanasya ũlũngalu wa Ngai, twĩasya ata? Ngai nĩ ũla ũte mũlũngalu ũla ũsilĩlaa na ũthatu? (Nĩngũneena ũndũ andũ maneenaa.)'),
('kam', 'ROM', 3, 6, 'Aiee, kũikethĩwe ũu: nũndũ ethĩwa nĩ ũu Ngai akatonya ata kũmĩsilĩla nthĩ?'),
('kam', 'ROM', 3, 7, 'Ĩndĩ ethĩwa ũla w’o wa Ngai nĩwingĩvaa kũvikĩa kũtaĩwa kwake kwondũ wa ũvũngũ wakwa, nĩkĩ ngũsilĩlwa ta nĩ mwathe?'),
('kam', 'ROM', 3, 8, 'Na nĩkĩ tũikwasya, Twike naĩ nĩ kana ũseo wũke? (O tondũ tũsukawa, na tondũ amwe malũlũmĩlasya kwasya kana tũneenaa ũu,) ũsilĩlo woo kwĩthĩwa nĩ avĩtan’ya nĩ wa katĩ.')
